    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

    function monthKey(d) { return `${d.getFullYear()}-${d.getMonth()}`; }
    function fillMonths(entries, keyFn, valFn) {
      const map = {};
