// CHAT-003: attach requireConversationMember to every conversation- and
// message-scoped route in chat.js. Injected immediately after `protect`, so
// membership is proven before any handler query runs.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
process.chdir(root);

const FILE = 'src/routes/chat.js';
let src = fs.readFileSync(FILE, 'utf8');

// [method, path]
const SCOPED = [
  ['put', '/conversations/:conversationId/request'],
  ['get', '/messages/:conversationId'],
  ['get', '/messages/:conversationId/search'],
  ['put', '/messages/read/:conversationId'],
  ['put', '/messages/delivered/:conversationId'],
  ['put', '/messages/mark-unread/:conversationId'],
  ['put', '/settings/:conversationId'],
  ['delete', '/chat/:conversationId/clear'],
  ['delete', '/chat/:conversationId'],
  ['put', '/chat/:conversationId/draft'],
  ['put', '/chat/:conversationId/pin-message'],
  ['post', '/messages/:messageId/reactions'],
  ['get', '/messages/:messageId/reactions'],
  ['put', '/messages/:messageId'],
  ['delete', '/messages/:messageId'],
  ['put', '/messages/:messageId/star'],
  ['get', '/messages/:messageId/info'],
  ['get', '/messages/:conversationId/media'],
  ['post', '/messages/bulk-delete'],
  ['post', '/messages/forward'],
  ['get', '/starred'],
];

let applied = 0, already = 0;
const misses = [];

for (const [method, rpath] of SCOPED) {
  const esc = rpath.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`(router\\.${method}\\(\\s*'${esc}'\\s*,\\s*protect)(?![\\w])`);
  if (!re.test(src)) { misses.push(`${method.toUpperCase()} ${rpath}`); continue; }
  // Skip if this registration already carries the guard.
  const reg = src.match(new RegExp(`router\\.${method}\\(\\s*'${esc}'[\\s\\S]{0,300}?=>\\s*\\{`));
  if (reg && /requireConversationMember/.test(reg[0])) { already++; continue; }
  src = src.replace(re, '$1, requireConversationMember()');
  applied++;
}

if (!/middleware\/chatMembership\.js/.test(src)) {
  src = src.replace(
    /^import express from 'express';$/m,
    "import express from 'express';\nimport { requireConversationMember } from '../middleware/chatMembership.js';"
  );
}

fs.writeFileSync(FILE, src, 'utf8');
console.log(`chat: guards added ${applied}, already present ${already}, unmatched ${misses.length}`);
for (const m of misses) console.log('   unmatched: ' + m);

// REC-006 / PHARMA-003: escape + length-cap every user-supplied string that
// reaches `new RegExp`. Rewrites `new RegExp(<ident>, 'i')` to
// `new RegExp(escapeRegex(capSearch(<ident>)), 'i')`.
//
// Deliberately keeps the `new RegExp(...)` shape (rather than switching to a
// helper that can return null) so a whitespace-only `?q=%20%20` still behaves
// exactly as it did before instead of becoming `filter.x = null`.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
process.chdir(root);

const dir = 'src/routes/';
const files = fs.readdirSync(dir).filter((f) => f.endsWith('.js'));

// Identifier that is plainly safe (internal constants), never user input.
const SAFE = new Set(['MEDICINE_NAME', 'PATIENT_NAME']);

let totalRewrites = 0;
const report = [];

for (const f of files) {
  const p = dir + f;
  let src = fs.readFileSync(p, 'utf8');
  const before = src;

  let rewrites = 0;
  src = src.replace(
    /new RegExp\(\s*([A-Za-z_$][\w$]*(?:\??\.[A-Za-z_$][\w$]*)*)\s*,\s*(['"])(i|gi|ig|g|is)\2\s*\)/g,
    (m, ident, _q, _flags) => {
      if (SAFE.has(ident)) return m;
      rewrites++;
      return `new RegExp(escapeRegex(capSearch(${ident})), '${_flags}')`;
    }
  );

  // chat.js declares its own local escapeRegex — drop it in favour of the util.
  if (rewrites > 0 || /const escapeRegex =/.test(src)) {
    if (f === 'chat.js') {
      src = src.replace(
        /^const escapeRegex = .*$/m,
        "import { escapeRegex, capSearch } from '../utils/escapeRegex.js';"
      );
      if (!/import \{ escapeRegex/.test(src)) {
        src = src.replace(
          /^import express from 'express';$/m,
          "import express from 'express';\nimport { escapeRegex, capSearch } from '../utils/escapeRegex.js';"
        );
      }
    } else if (!/from '\.\.\/utils\/escapeRegex\.js'/.test(src)) {
      // Insert the import after the last top-level import so ordering is sane.
      const lines = src.split('\n');
      let last = -1;
      for (let i = 0; i < lines.length; i++) {
        if (/^import .*;$/.test(lines[i])) last = i;
      }
      const need = /escapeRegex\(/.test(src) ? 'escapeRegex' : '';
      const need2 = /capSearch\(/.test(src) ? 'capSearch' : '';
      const names = [need, need2].filter(Boolean);
      if (names.length) {
        lines.splice(last + 1, 0, `import { ${names.join(', ')} } from '../utils/escapeRegex.js';`);
        src = lines.join('\n');
      }
    }
  }

  if (src !== before) {
    fs.writeFileSync(p, src, 'utf8');
    totalRewrites += rewrites;
    if (rewrites) report.push(`${f}: ${rewrites}`);
  }
}

console.log('rewrote ' + totalRewrites + ' regex construction(s)');
for (const r of report) console.log('  ' + r);

