import { execSync } from 'child_process';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// Repo-root compose file (script runs from anywhere).
const COMPOSE_FILE = path.join(__dirname, '..', '..', '..', 'infra', 'docker-compose.yml');

const MONGO_URL = 'mongodb://127.0.0.1:27018/findmedi?directConnection=true';
const REDIS_URL = 'redis://localhost:6380';
process.env.MONGO_URI = MONGO_URL;
process.env.REDIS_URL = REDIS_URL;

const results = [];
function check(name, ok, detail = '') {
  results.push({ name, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ` — ${detail}` : ''}`);
}

function sh(cmd) {
  return execSync(cmd, { encoding: 'utf8', timeout: 120000 });
}

// ── Baseline ──
try {
  const { default: mongoose } = await import('mongoose');
  await mongoose.connect(MONGO_URL);
  const isPrimary = await mongoose.connection.db.admin().serverInfo()
    .then(() => true).catch(() => false);
  check('baseline: mongo reachable', isPrimary);
  await mongoose.disconnect();
} catch (e) {
  check('baseline: mongo reachable', false, e.message);
}

// ── CHAOS: SIGKILL both data services ──
console.log('CHAOS: killing findmedi-mongo1 + findmedi-redis (SIGKILL)...');
try {
  sh('docker kill findmedi-mongo1 findmedi-redis');
  check('chaos: kill delivered', true);
} catch (e) {
  check('chaos: kill delivered', false, e.message);
  process.exit(1);
}

// ── Recovery: restart policies do NOT self-heal SIGKILL on this daemon
// (verified: containers stay Exited). The supported recovery path is an
// explicit `up -d` (runbook), which this test exercises end-to-end.
try {
  console.log('RECOVERY: docker compose up -d mongo1 redis ...');
  sh(`docker compose -f "${COMPOSE_FILE}" up -d mongo1 redis`);
  check('recovery: compose up accepted', true);
} catch (e) {
  check('recovery: compose up accepted', false, e.message);
  process.exit(1);
}

let mongoOk = false;
let redisOk = false;
for (let i = 0; i < 20; i++) {
  await new Promise((r) => setTimeout(r, 15000));
  try {
    const { default: mongoose } = await import('mongoose');
    await mongoose.connect(MONGO_URL, { serverSelectionTimeoutMS: 5000 });
    const hello = await mongoose.connection.db.admin().command({ hello: 1 });
    if (hello.isWritablePrimary || hello.setName) mongoOk = true;
    await mongoose.disconnect();
  } catch {}
  try {
    const { createClient } = await import('redis');
    const c = createClient({ url: REDIS_URL });
    await c.connect();
    redisOk = (await c.ping()) === 'PONG';
    await c.disconnect();
  } catch {}
  if (mongoOk && redisOk) break;
}
check('recovery: mongo PRIMARY writable', mongoOk);
check('recovery: redis PONG', redisOk);

// ── Post-recovery proofs ──
try {
  const { default: mongoose } = await import('mongoose');
  await mongoose.connect(MONGO_URL);
  const session = await mongoose.startSession();
  let txnOk = false;
  try {
    await session.withTransaction(async () => {
      await mongoose.connection.db.collection('__chaos_probe__').insertOne({ at: new Date() }, { session });
    });
    txnOk = true;
  } finally {
    await session.endSession();
  }
  await mongoose.connection.db.collection('__chaos_probe__').deleteMany({});
  await mongoose.disconnect();
  check('post-recovery: multi-doc transaction', txnOk);
} catch (e) {
  check('post-recovery: multi-doc transaction', false, e.message);
}

try {
  const { createClient } = await import('redis');
  const c = createClient({ url: REDIS_URL });
  await c.connect();
  await c.set('chaos:h3:probe', JSON.stringify({ cell: '883d9b910bfffff' }), { EX: 60 });
  const back = await c.get('chaos:h3:probe');
  await c.del('chaos:h3:probe');
  await c.disconnect();
  check('post-recovery: redis write/read round-trip', back !== null);
} catch (e) {
  check('post-recovery: redis write/read round-trip', false, e.message);
}

const failed = results.filter((r) => !r.ok);
console.log(`\nCHAOS RESULT: ${results.length - failed.length}/${results.length} checks passed`);
process.exit(failed.length ? 1 : 0);

#!/usr/bin/env node
/**
 * AUTHZ-B-06: route-level authorization coverage inventory.
 *
 * The sweep behind this audit counted 799 route definitions and found 316 that
 * carried `protect` but NO authorization marker on the definition line. Some of
 * those are legitimately self-scoped (`GET /me`, `GET /my-appointments`); others
 * are accidental holes. Nobody could tell which was which, so "is authorization
 * covered?" was unanswerable — and the CI job that does exist
 * (checkAuthzCallerReachability) only catches routes that are OVER-blocked, not
 * ones that are under-blocked.
 *
 * This script classifies every route and compares the result against a committed
 * baseline, so:
 *   - a NEW unclassified route fails CI (it must be tagged before it ships), and
 *   - the tagged/unclassified counts are visible in the PR, which is what turns
 *     "unmeasured" into "measured".
 *
 * Tag grammar (a `// authz:` comment on the line above the route):
 *   // authz: public        no authentication at all (documented + justified)
 *   // authz: self         authenticated, scoped to req.user by the handler
 *   // authz: role         authorize()/restrictTo()/adminOnly on the definition
 *   // authz: object       authorizeObject() on the definition
 *   // authz: facility     sameFacilityStrict()/applyTenantScope in the handler
 *   // authz: inherited    guarded by a router.use(...) above it
 *
 * Usage:
 *   node scripts/check-authz-coverage.mjs            # report + fail on NEW gaps
 *   node scripts/check-authz-coverage.mjs --report   # print the full inventory
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildInventory, countByTag, buildOwnershipMatrix, OWNERSHIP_MECHANISMS } from './lib/authzClassify.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, '..');
const ROUTES_DIR = path.join(ROOT, 'src', 'routes');
const BASELINE_FILE = path.join(ROOT, '.authz-coverage-baseline.json');

/**
 * AUTHZ-M-02: the grammar itself lives in lib/authzClassify.mjs so a test can
 * re-derive the manifest and prove the committed file is current. Keeping it
 * inline here would mean the freshness test had to re-implement the classifier,
 * and a second grammar is exactly what this finding is about.
 */
const rows = buildInventory(ROUTES_DIR);
const counts = countByTag(rows);

console.log('AUTHZ coverage inventory (AUTHZ-B-06)');
console.log('-------------------------------------');
for (const [tag, n] of Object.entries(counts).sort((a, b) => b[1] - a[1])) {
  console.log(`  ${tag.padEnd(14)} ${n}`);
}
console.log(`  ${'TOTAL'.padEnd(14)} ${rows.length}`);
const unclassified = rows.filter((r) => r.tag === 'unclassified');
console.log(`\nunclassified (protect but no authorization marker): ${unclassified.length}`);

if (process.argv.includes('--report')) {
  const byFile = new Map();
  for (const r of rows) {
    if (!byFile.has(r.file)) byFile.set(r.file, []);
    byFile.get(r.file).push(r);
  }
  for (const [file, list] of [...byFile.entries()].sort()) {
    const gaps = list.filter((r) => r.tag === 'unclassified');
    console.log(`\n${file} — ${list.length} routes, ${gaps.length} unclassified`);
    for (const r of gaps) console.log(`   L${r.line} ${r.method} ${r.target}`);
  }
}

// ── AUTHZ-M-02: the machine-readable manifest ───────────────────────────────
//
// Everything above this line was console-only. The classification was computed,
// printed, thrown away, and recomputed by hand the next time anybody asked
// "what may call this route?" - which is the exact loop that let AUTHZ-M-01
// drift: eight ownership mechanisms coexisted because nobody had a list that
// showed them side by side.
//
// This file is the artefact the finding asked for. It is emitted on EVERY run
// (not behind a flag) because a manifest that only exists when someone remembers
// to ask for it is documentation, and documentation rots.
//
// Deliberately has NO timestamp: a generated-at line makes every run dirty the
// git diff even when nothing changed, and the diff is the point - a reviewer
// should see a one-line change when one route changes classification.
const MANIFEST_FILE = path.join(ROOT, 'authz-manifest.json');

// AUTHZ-M-07: the matrix half of the manifest - not just WHETHER a route is
// guarded, but BY WHAT. Without this the central layer (authorizeObject) and the
// ten mechanisms that bypass it are indistinguishable in the numbers, which is
// how AUTHZ-M-01 went unaddressed for as long as it did.
const { byMechanism, centralLayer, alternatives, unnamedHandlerGuard, unrecognised } = buildOwnershipMatrix(ROUTES_DIR);
const alternativeRows = Object.entries(alternatives)
  .map(([mechanism, n]) => ({ mechanism, routes: n }))
  .sort((a, b) => b.routes - a.routes);
const objectScopedTotal = centralLayer.length + alternativeRows.reduce((a, b) => a + b.routes, 0);

const manifest = {
  schemaVersion: 1,
  note: 'Generated by scripts/check-authz-coverage.mjs. Do not hand-edit.',
  tags: {
    public: 'no authentication required',
    self: 'the authenticated subject may act on their own data',
    role: 'gated on the role of the caller only',
    object: 'gated on ownership/tenancy of the addressed object',
    facility: 'gated on sharing a facility with the target',
    inherited: 'guard comes from router-level middleware, not the route line',
    unclassified: 'protected but no authorization decision recorded - a GAP',
  },
  total: rows.length,
  counts: Object.fromEntries(Object.entries(counts).sort(([a], [b]) => a.localeCompare(b))),

  // AUTHZ-M-07. `byMechanism` answers "which guard, for every route";
  // `centralLayer` is the single number AUTHZ-M-01 is about - how much of the
  // object-scoped surface actually goes through the central layer rather than a
  // mechanism that grew up alongside it.
  byMechanism,
  centralLayer: {
    mechanism: OWNERSHIP_MECHANISMS[0],
    routes: centralLayer.length,
    objectScopedTotal,
    share: objectScopedTotal ? +(centralLayer.length / objectScopedTotal).toFixed(3) : null,
    alternatives: alternativeRows,
    // Object-scoped, but the guard lives in the handler body behind a pattern
    // the parser matches without naming a mechanism. These are the routes the
    // central-layer migration cannot even identify yet.
    unnamedHandlerGuard,
    note: 'AUTHZ-M-01 is OPEN. The alternatives are not necessarily wrong - several predate authorizeObject and carry domain rules it does not model - but the split was previously invisible, and a route can be guarded twice by two mechanisms whose rules were never reconciled.',
  },
  unrecognised,
  // Sorted so the file is byte-stable across runs regardless of scan order.
  // Locale-independent ASCII order (same comparator as scripts/lib/authzClassify.mjs;
  // localeCompare would disagree with the byte-order assertion in authzManifest.spec.js).
  routes: rows
    .slice()
    .sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : a.line - b.line))
    .map((r) => ({ file: r.file, line: r.line, method: r.method, target: r.target, tag: r.tag })),
};

fs.writeFileSync(MANIFEST_FILE, `${JSON.stringify(manifest, null, 2)}\n`);
console.log(`\nmanifest written: authz-manifest.json (${rows.length} routes)`);

// ── Baseline gate ───────────────────────────────────────────────────────────
// The count may only go DOWN. Migrations tag routes over time; a new gap means a
// route shipped without anyone deciding who may call it.
const totalGaps = unclassified.length;
let baseline = null;
try {
  baseline = JSON.parse(fs.readFileSync(BASELINE_FILE, 'utf8'));
} catch { /* first run */ }

if (!baseline) {
  fs.writeFileSync(
    BASELINE_FILE,
    `${JSON.stringify({ total: rows.length, unclassified: totalGaps }, null, 2)}\n`
  );
  console.log(`\nbaseline written: ${totalGaps} unclassified of ${rows.length} routes`);
  process.exit(0);
}

if (totalGaps > baseline.unclassified) {
  console.error(
    `\nAUTHZ-B-06 gate FAILED: unclassified routes ${baseline.unclassified} -> ${totalGaps}.`
  );
  for (const r of unclassified.slice(0, 25)) {
    console.error(`  ${r.file}:${r.line}  ${r.method} ${r.target}`);
  }
  console.error('\nEither tag the route with `// authz: public|self|role|object|facility`,');
  console.error('or wire authorizeObject()/authorize() onto it.');
  process.exit(1);
}

console.log(
  `\nAUTHZ-B-06 gate OK — ${totalGaps} unclassified (baseline ${baseline.unclassified}), none added.`
);
process.exit(0);

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const COMPOSE_FILE = path.join(ROOT, 'infra', 'docker-compose.prod.yml');
const IMAGE_TEMPLATE = '${BACKUP_IMAGE:?set BACKUP_IMAGE to an immutable repository@sha256 digest}';

export function isImmutableImageDigest(image) {
  return /^(?:[A-Za-z0-9.-]+(?::[0-9]+)?\/)?[A-Za-z0-9._/-]+@sha256:[a-f0-9]{64}$/.test(String(image || ''));
}

function serviceBlock(compose, serviceName) {
  const match = compose.match(new RegExp(`^  ${serviceName}:\\r?\\n([\\s\\S]*?)(?=^  [A-Za-z0-9_-]+:|^volumes:|\\Z)`, 'm'));
  return match?.[1] || null;
}

export function assertBackupImagePolicy(compose, backupImage = undefined) {
  const images = ['backup', 'backup-drill'].map((service) => {
    const block = serviceBlock(compose, service);
    if (!block) throw new Error(`production compose is missing ${service} service`);
    const image = block.match(/^[ ]{4}image:\s*(.+)\s*$/m)?.[1];
    if (image !== IMAGE_TEMPLATE) {
      throw new Error(`${service}.image must require the shared BACKUP_IMAGE digest variable`);
    }
    return image;
  });
  if (images[0] !== images[1]) throw new Error('backup and backup-drill must use the same image reference');
  if (backupImage !== undefined && !isImmutableImageDigest(backupImage)) {
    throw new Error('BACKUP_IMAGE must be an immutable repository@sha256:<64 lowercase hex> reference');
  }
  return true;
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  try {
    const compose = fs.readFileSync(COMPOSE_FILE, 'utf8');
    assertBackupImagePolicy(compose, process.env.BACKUP_IMAGE);
    console.log(process.env.BACKUP_IMAGE
      ? 'Backup image policy OK: backup and restore drill share an immutable digest.'
      : 'Backup image template policy OK; set BACKUP_IMAGE to a repository@sha256 digest when rendering production compose.');
  } catch (error) {
    console.error(`Backup image policy failed: ${error.message}`);
    process.exitCode = 1;
  }
}

/**
 * DOC-B-03 — env-var drift guard.
 *
 * The runbooks document env vars; `envValidator.js` enforces them; `.env.example`
 * lists them. Nothing connected the three, so they drifted silently: a var could
 * be required in code, undocumented in the example, and named differently in a
 * runbook — and the failure only appeared as a confusing startup crash.
 *
 * This checks the mechanical direction, which is the one that actually breaks
 * deployments:
 *
 *   1. Every var REQUIRED by envValidator.js must appear in `.env.example`.
 *      A missing example entry means the first person to deploy discovers it by
 *      hitting the error.
 *   2. Every var used in docker-compose / k8s must be in the example too.
 *   3. Every var in `.env.example` should be recognised by the validator —
 *      otherwise the example is teaching a variable the app ignores.
 *
 * It deliberately does NOT try to parse prose in Markdown. A doc scanner that
 * cries wolf on a code sample in a runbook gets disabled within a week, and a
 * disabled check is worse than no check. Run from the repo root:
 *
 *   node backend/scripts/check-env-docs.mjs
 */
import { readFileSync, existsSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

const read = (p) => (existsSync(p) ? readFileSync(p, 'utf8') : null);

/**
 * Locate the env example without hard-coding one location.
 *
 * The repo has `backend/.env.example`, `frontend/.env.example` and
 * `backend/mindsupport/.env.example`. The backend one is the one that must cover
 * every server-side var, so it is preferred; if it is ever moved, the check
 * reports which paths it looked at rather than silently finding nothing and
 * passing.
 */
const EXAMPLE_CANDIDATES = [
  'backend/.env.example',
  '.env.example',
  'frontend/.env.example',
];

function findExample() {
  for (const rel of EXAMPLE_CANDIDATES) {
    const abs = join(REPO, rel);
    if (existsSync(abs)) return abs;
  }
  return null;
}

/** Names inside `{ name: 'X', ... }` entries of REQUIRED_VARS. */
function requiredFromValidator(src) {
  const out = new Set();
  if (!src) return out;
  const block = src.slice(src.indexOf('REQUIRED_VARS'));
  for (const m of block.matchAll(/name:\s*'([A-Z0-9_]+)'/g)) out.add(m[1]);
  return out;
}

/** Names inside `{ name: 'X' }` entries of OPTIONAL_VARS, plus known-optional lists. */
function optionalFromValidator(src) {
  const out = new Set();
  if (!src) return out;
  for (const m of src.matchAll(/OPTIONAL_VARS[\s\S]{0,4000}/g)) {
    for (const n of m[0].matchAll(/'([A-Z][A-Z0-9_]+)'/g)) out.add(n[1]);
  }
  return out;
}

/** `KEY=value` pairs in a dotenv-style file. */
function keysFromDotenv(src) {
  const out = new Set();
  if (!src) return out;
  for (const line of src.split(/\r?\n/)) {
    const m = line.match(/^\s*(?:export\s+)?([A-Z][A-Z0-9_]*)\s*=/);
    if (m) out.add(m[1]);
  }
  return out;
}

/** `${VAR}` / `$VAR` references in compose and k8s manifests. */
function varsFromManifests() {
  const out = new Set();
  const files = [
    'infra/docker-compose.yml',
    'infra/docker-compose.prod.yml',
    'infra/k8s/core.yaml',
  ];
  for (const rel of files) {
    const src = read(join(REPO, rel));
    if (!src) continue;
    for (const m of src.matchAll(/\$\{([A-Z][A-Z0-9_]*)/g)) out.add(m[1]);
  }
  return out;
}

const validator = read(join(REPO, 'backend/src/config/envValidator.js'));
const examplePath = findExample();
if (!examplePath) {
  console.error(
    'No .env.example found. Looked in:\n  ' +
    EXAMPLE_CANDIDATES.map((p) => join(REPO, p)).join('\n  ')
  );
  process.exit(1);
}
const example = keysFromDotenv(read(examplePath));

const required = requiredFromValidator(validator);
const optional = optionalFromValidator(validator);
const manifestVars = varsFromManifests();

const problems = [];

// 1 & 2. Anything required or used by a manifest must be documented.
for (const key of [...required].sort()) {
  if (!example.has(key)) {
    problems.push(
      `REQUIRED but missing from .env.example: ${key}` +
      `\n    Add it to .env.example, or the first deployment discovers it as a startup crash.`
    );
  }
}
for (const key of [...manifestVars].sort()) {
  if (!example.has(key)) {
    problems.push(`Used in infra manifests but missing from .env.example: ${key}`);
  }
}

// 3. Documented but not known to the app.
const known = new Set([...required, ...optional]);
const undocumentedInCode = [];
for (const key of [...example].sort()) {
  if (known.size > 0 && !known.has(key)) undocumentedInCode.push(key);
}

const separator = '='.repeat(72);
console.log(separator);
console.log('DOC-B-03 · env documentation drift');
console.log(separator);
console.log(`required by validator : ${required.size}`);
console.log(`documented in example  : ${example.size}`);
console.log(`used in infra manifests: ${manifestVars.size}`);

if (problems.length) {
  console.error(`\n${problems.length} PROBLEM(S):\n`);
  for (const p of problems) console.error(`  - ${p}\n`);
  console.error(separator);
  process.exit(1);
}

if (undocumentedInCode.length) {
  // Reported, not fatal: a var can legitimately be consumed by the frontend, a
  // build script or a CI step, none of which the validator knows about. Failing
  // here would mean either a false positive or a stub entry in the validator.
  console.log(
    `\nNote: ${undocumentedInCode.length} var(s) in .env.example are not referenced by\n` +
    `envValidator.js (they may belong to the frontend, CI or an infra script):\n  ` +
    undocumentedInCode.join(', ')
  );
}

console.log(`\nOK — every required and manifest-referenced var is documented.`);
console.log(separator);

#!/usr/bin/env node
/**
 * DP-M-01 — event schema registry compatibility gate.
 *
 * The registry (src/events/schemaRegistry.js) enforces contracts at runtime;
 * this script enforces the things runtime cannot see:
 *
 *   1. COMPLETENESS  every `case '<literal>'` in the Kafka consumer, every
 *      KAFKA_TOPICS topic, and every producer-side `eventType: '<literal>'`
 *      must have a registry entry. A new consumer branch or producer event
 *      that skips the registry fails CI until it is registered.
 *   2. BACKWARD COMPAT  every entry ships a valid fixture that must parse
 *      against the current schema — fixtures are the append-only history of
 *      what consumers have already accepted, so loosening/re-typing a field in
 *      an incompatible way fails here. Every entry also ships a negative
 *      fixture (`*.invalid.json`) that must NOT parse, proving the schema
 *      still rejects garbage rather than having been loosened into a rubber
 *      stamp.
 *   3. STATIC COMPLETENESS LIMIT  dynamic eventTypes (template literals like
 *      `${type}.assigned`) cannot be enumerated statically; they are printed
 *      as info and constrained at runtime (registered + invalid → throw).
 *
 * Run:  node scripts/check-event-schema-compat.mjs     (CI: tenant-guard job)
 */
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { join, dirname, relative, sep } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { KAFKA_TOPICS } from '../src/config/kafka.js';
import { EVENT_SCHEMA_ENTRIES, lookupEntry } from '../src/events/schemaRegistry.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const BACKEND = join(HERE, '..');
const SRC = join(BACKEND, 'src');
const FIXTURES = join(SRC, 'events', 'fixtures');
const REGISTRY_FILE = join(SRC, 'events', 'schemaRegistry.js');

function jsFilesUnder(dir) {
  const out = [];
  const stack = [dir];
  while (stack.length) {
    const d = stack.pop();
    for (const name of readdirSync(d, { withFileTypes: true })) {
      const p = join(d, name.name);
      if (name.isDirectory()) stack.push(p);
      else if (name.isFile() && name.name.endsWith('.js')) out.push(p);
    }
  }
  return out;
}

/** All `case '<literal>'` values in the consumer's event switch. */
export function collectConsumerCases() {
  const src = readFileSync(join(SRC, 'services', 'kafkaConsumerService.js'), 'utf8');
  return [...src.matchAll(/case\s+'([^']+)'/g)].map((m) => m[1]);
}

/**
 * Static producer-side eventTypes: `eventType: '<literal>'` object fields plus
 * the positional emit* wrappers (`emitPharmacyInventoryEvent(id, 'type', …)`).
 * The registry's own definition file is skipped — it is the definition site,
 * not a producer. Dynamic (backtick) names are returned separately as info.
 */
export function collectProducerEventTypes() {
  const literals = new Set();
  const dynamic = [];
  for (const file of jsFilesUnder(SRC)) {
    if (file === REGISTRY_FILE) continue;
    const rel = relative(SRC, file).split(sep).join('/');
    const src = readFileSync(file, 'utf8');
    for (const m of src.matchAll(/eventType:\s*'([^']+)'/g)) literals.add(m[1]);
    for (const m of src.matchAll(
      /emit(?:HospitalAdmission|PharmacyInventory)Event\(\s*[^,]+,\s*'([^']+)'/g
    )) {
      literals.add(m[1]);
    }
    for (const m of src.matchAll(/eventType:\s*`([^`]+)`/g)) dynamic.push(`${rel}: ${m[1]}`);
  }
  return { literals: [...literals].sort(), dynamic };
}

export function runChecks() {
  const problems = [];
  const registeredTypes = new Set(
    EVENT_SCHEMA_ENTRIES.filter((e) => e.eventType).map((e) => e.eventType)
  );

  // 1a. Every consumer switch case must be registered.
  const consumerCases = collectConsumerCases();
  for (const c of consumerCases) {
    if (!registeredTypes.has(c)) {
      problems.push(
        `consumer case '${c}' has no registry entry — an event arriving for it passes unvalidated`
      );
    }
  }

  // 1b. Every topic in the manifest must have at least one entry.
  for (const topic of Object.values(KAFKA_TOPICS)) {
    if (!EVENT_SCHEMA_ENTRIES.some((e) => e.topic === topic)) {
      problems.push(`topic ${topic} has no registry entry — payloads on it are never validated`);
    }
  }

  // 1c. Every static producer literal must be registered.
  const { literals, dynamic } = collectProducerEventTypes();
  for (const t of literals) {
    if (!registeredTypes.has(t)) {
      problems.push(
        `producer emits eventType '${t}' but no registry entry exists — consumers of it see a silent default`
      );
    }
  }

  // 2. Fixture contract: valid must pass, invalid must fail, both must exist.
  for (const entry of EVENT_SCHEMA_ENTRIES) {
    const validPath = join(FIXTURES, entry.fixture);
    const invPath = join(FIXTURES, entry.fixture.replace(/\.json$/, '.invalid.json'));
    if (!existsSync(validPath)) {
      problems.push(`entry ${entry.key} is missing its fixture ${entry.fixture}`);
      continue;
    }
    let valid;
    try {
      valid = JSON.parse(readFileSync(validPath, 'utf8'));
    } catch (e) {
      problems.push(`fixture ${entry.fixture} is not valid JSON: ${e.message}`);
      continue;
    }
    const res = entry.schema.safeParse(valid);
    if (!res.success) {
      const detail = res.error.issues
        .map((i) => `${i.path.length ? i.path.join('.') : '(root)'}: ${i.message}`)
        .join('; ');
      problems.push(
        `fixture ${entry.fixture} no longer validates (BACKWARD-COMPAT BREAK): ${detail}`
      );
    }
    if (!existsSync(invPath)) {
      problems.push(
        `entry ${entry.key} is missing its negative fixture ${entry.fixture.replace(/\.json$/, '.invalid.json')}`
      );
      continue;
    }
    let inv;
    try {
      inv = JSON.parse(readFileSync(invPath, 'utf8'));
    } catch (e) {
      problems.push(`negative fixture ${invPath} is not valid JSON: ${e.message}`);
      continue;
    }
    if (entry.schema.safeParse(inv).success) {
      problems.push(
        `negative fixture ${entry.fixture.replace(/\.json$/, '.invalid.json')} PASSES the schema — the entry no longer rejects malformed payloads`
      );
    }
  }

  // Sanity: lookup fallback must not shadow an exact entry anywhere.
  for (const entry of EVENT_SCHEMA_ENTRIES) {
    if (entry.eventType && lookupEntry(entry.topic, entry.eventType)?.key !== entry.key) {
      problems.push(`entry ${entry.key} is shadowed by another registry entry`);
    }
  }

  return { problems, consumerCases, literals, dynamic, entryCount: EVENT_SCHEMA_ENTRIES.length };
}

const separator = '='.repeat(72);

if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url) {
  const { problems, consumerCases, literals, dynamic, entryCount } = runChecks();
  console.log(separator);
  console.log('DP-M-01 · event schema registry compatibility');
  console.log(separator);
  console.log(`registry entries        : ${entryCount}`);
  console.log(`consumer cases covered  : ${consumerCases.length}`);
  console.log(`producer literals       : ${literals.length}`);
  if (dynamic.length) {
    console.log(`dynamic eventTypes (info, runtime-enforced): ${dynamic.length}`);
    for (const d of dynamic) console.log(`    ${d}`);
  }

  if (problems.length) {
    console.error(`\n${problems.length} PROBLEM(S):\n`);
    for (const p of problems) console.error(`  - ${p}\n`);
    console.error(separator);
    process.exit(1);
  }

  console.log(
    '\nOK — every consumer case, topic and producer literal is registered; ' +
      'all fixtures validate; all negative fixtures reject.'
  );
  console.log(separator);
}

#!/usr/bin/env node
/**
 * AUTHZ-B-07 regression guard.
 *
 * The hand-rolled guard `if (req.user.hospitalId && role !== 'superadmin') …`
 * silently becomes "no tenant filter" for any account without a hospitalId,
 * which is how a self-registered hospital_admin (or a rider / assistant / lab
 * staff account) ended up reading platform-wide data on ~20 route files.
 *
 * Migrations to the fail-closed `applyTenantScope()` helper are in progress, so
 * this script compares the per-file occurrence count against a committed
 * BASELINE: the count may go DOWN (a file was migrated) but must never go UP,
 * and a file that is not in the baseline must not contain the pattern at all.
 *
 * Usage:  node scripts/check-tenant-guard-regression.mjs [--write-baseline]
 * Exit 0 = no regression, 1 = new fail-open guard introduced.
 */
import { readFileSync, readdirSync, statSync, writeFileSync, existsSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const srcDir = join(here, '..', 'src');
const baselinePath = join(here, '..', '.tenant-guard-baseline.json');
const PATTERN = /if \(req\.user\.hospitalId &&/;

function walk(dir, out = []) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else if (entry.endsWith('.js')) out.push(full);
  }
  return out;
}

const counts = {};
for (const file of walk(srcDir)) {
  const source = readFileSync(file, 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
  const hits = source.split('\n').filter((l) => PATTERN.test(l) && !l.trim().startsWith('//'));
  if (hits.length) counts[relative(join(here, '..'), file).replace(/\\/g, '/')] = hits.length;
}

if (process.argv.includes('--write-baseline')) {
  writeFileSync(baselinePath, `${JSON.stringify(counts, null, 2)}\n`);
  console.log(`baseline written: ${Object.keys(counts).length} files, ${Object.values(counts).reduce((a, b) => a + b, 0)} occurrences`);
  process.exit(0);
}

if (!existsSync(baselinePath)) {
  console.error('No baseline. Run: node scripts/check-tenant-guard-regression.mjs --write-baseline');
  process.exit(1);
}

const baseline = JSON.parse(readFileSync(baselinePath, 'utf8'));
const regressions = [];
for (const [file, count] of Object.entries(counts)) {
  const allowed = baseline[file];
  if (allowed === undefined) regressions.push(`${file}: ${count} new occurrence(s) (file not in baseline)`);
  else if (count > allowed) regressions.push(`${file}: ${count} occurrences (baseline ${allowed})`);
}
for (const file of Object.keys(baseline)) {
  if (counts[file] === undefined) console.log(`  migrated: ${file} (baseline ${baseline[file]} -> 0)`);
}

if (regressions.length) {
  console.error('AUTHZ-B-07 REGRESSION — new fail-open tenant guard(s):\n  ' + regressions.join('\n  '));
  console.error('\nUse applyTenantScope()/callerOwnsTenant() from src/utils/tenantScope.js instead.');
  process.exit(1);
}
console.log(`AUTHZ-B-07 guard OK — ${Object.values(counts).reduce((a, b) => a + b, 0)} legacy occurrence(s) remain, none added.`);

#!/usr/bin/env node
/**
 * Authorization caller-reachability gate.
 *
 * WHY THIS FILE EXISTS AT ALL
 * --------------------------
 * `.github/workflows/ci.yml` has had a job running
 * `node scripts/checkAuthzCallerReachability.mjs`, and that script did not
 * exist. Like the missing `checkPermissionMatrix.mjs`, the job fails with
 * MODULE_NOT_FOUND on every run and reads as a code regression rather than a
 * typo, so it gets re-run instead of fixed. Both were found by listing the
 * scripts ci.yml invokes and checking each one resolves - a two-minute check
 * that should have been the first thing done when either job was added.
 *
 * WHAT IT CHECKS
 * --------------
 * `check-authz-coverage.mjs` catches routes that are UNDER-blocked (protected,
 * but no authorization decision recorded). `checkPermissionMatrix.mjs` catches a
 * permission no role holds. This one catches the opposite failure: a route whose
 * guard stack NOBODY can satisfy.
 *
 * The shape it hunts is a contradiction between two gates:
 *
 *     router.post('/x', protect, platformAdminOnly, hospitalAdminOnly, ...)
 *
 * `platformAdminOnly` admits `superadmin`; `hospitalAdminOnly` admits
 * `hospital_admin` only. The intersection is empty, so the endpoint is a 403 for
 * every account that exists - it looks live, it is documented, and nobody can
 * ever reach it. Nobody notices, because a 403 is exactly what an authorization
 * check is supposed to return.
 *
 * This can only be proven for ROLE gates: their admitted sets are literal and
 * known. It deliberately does NOT reason about object/tenancy guards
 * (`authorizeObject`, `requireTenantOwnership`, ...), where reachability depends
 * on the data in the row and a static intersection would produce confident
 * nonsense.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { CANONICAL_ROLES } from '../src/config/permissions.js';
import { stripComments, scanRoutes } from './lib/routeScan.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROUTES_DIR = path.resolve(__dirname, '..', 'src', 'routes');

/**
 * Fixed role gates, transcribed from src/middleware/auth.js.
 *
 * Transcribed, not imported: the middleware are functions over `req`, so "what
 * roles does this admit" is not callable without a fake request and response.
 * These are short and stable, and the duplication risk is handled below by
 * asserting the middleware source still contains each literal - if somebody
 * widens `adminOnly`, this script FAILS rather than quietly disagreeing with the
 * runtime.
 */
const ROLE_GATES = {
  adminOnly: ['hospital_admin', 'superadmin'],
  superadminOnly: ['superadmin'],
  platformAdminOnly: ['superadmin'],
  hospitalAdminOnly: ['hospital_admin'],
  clinicalStaffOnly: ['superadmin', 'hospital_admin', 'doctor', 'nurse'],
};

/** Gates whose admitted set is an inline array literal at the call site. */
const LIST_GATES = ['requireRole', 'roleOnly', 'restrictTo'];

const intersect = (a, b) => a.filter((r) => b.includes(r));

console.log('authorization caller reachability');
console.log('---------------------------------');

// ── 0. the transcription above must still match the runtime ────────────────
const authSrc = fs.readFileSync(path.resolve(__dirname, '..', 'src', 'middleware', 'auth.js'), 'utf8');
const stale = [];
for (const [gate, roles] of Object.entries(ROLE_GATES)) {
  const re = new RegExp(`export const ${gate}\\b[\\s\\S]{0,400}?\\n\\}`, 'm');
  const body = (re.exec(authSrc) || [''])[0];
  for (const role of roles) {
    if (body && !body.includes(`'${role}'`)) {
      stale.push(`${gate} admits ${role} here but not in middleware/auth.js`);
    }
  }
}
if (stale.length) {
  for (const s of stale) console.error(`  STALE: ${s}`);
  console.error('\n  Update ROLE_GATES in this script to match middleware/auth.js.');
  process.exit(1);
}
console.log(`  ${Object.keys(ROLE_GATES).length} fixed role gates verified against middleware/auth.js`);

// ── 1. no route may have an unsatisfiable role-gate stack ──────────────────
const dead = [];
const unknownRoles = new Set();

for (const r of scanRoutes(ROUTES_DIR)) {
  const line = r.routeLine;
  const id = `${r.file}:${r.line}`;

  let admitted = null;         // null = no role gate seen yet
  const gates = [];

  for (const [gate, roles] of Object.entries(ROLE_GATES)) {
    if (!line.includes(gate)) continue;
    gates.push(gate);
    admitted = admitted === null ? [...roles] : intersect(admitted, roles);
  }

  for (const gate of LIST_GATES) {
    const at = line.indexOf(`${gate}(`);
    if (at === -1) continue;
    const arrMatch = /^\s*\[([^\]]*)\]/.exec(line.slice(at + gate.length + 1));
    // Built from a variable, so not statically resolvable - skip rather than
    // guess, which is what turns a gate into noise that gets deleted.
    if (!arrMatch) continue;
    const roles = [...arrMatch[1].matchAll(/'([^']+)'|"([^"]+)"/g)]
      .map((m) => m[1] || m[2])
      .filter(Boolean);
    gates.push(`${gate}(${roles.join(',') || '<empty>'})`);
    if (roles.length === 0) {
      admitted = [];            // an empty allowlist admits nobody, by definition
      continue;
    }
    for (const role of roles) {
      if (!CANONICAL_ROLES.includes(role)) unknownRoles.add(`${gate}: ${role}`);
    }
    admitted = admitted === null ? roles : intersect(admitted, roles);
  }

  if (admitted !== null && admitted.length === 0) {
    dead.push({ id, gates, target: r.rawTarget });
  }
}

if (dead.length) {
  console.error(`\n  ${dead.length} route(s) whose role guards NO role can satisfy:`);
  for (const d of dead) {
    console.error(`    ${d.id}  ${d.gates.join(' + ')}   ${d.target}`);
  }
  console.error('\n  These endpoints are a permanent 403 for every account that exists.');
  console.error('  A 403 is what an authz check returns when it WORKS, so this failure');
  console.error('  mode is invisible in production logs and in the UI.');
  process.exit(1);
}
console.log('  no route has an unsatisfiable role-gate stack');

if (unknownRoles.size) {
  // Informational: a role no account can hold is a dead branch in a guard,
  // which usually means a typo rather than an intentionally reserved role.
  console.log(`\n  ${unknownRoles.size} role(s) in a requireRole()/restrictTo() list that are not canonical:`);
  for (const u of [...unknownRoles].sort()) console.log(`    ${u}`);
}

console.log('\ncaller reachability gate OK');

#!/usr/bin/env node
/**
 * Permission-matrix sanity gate.
 *
 * WHY THIS FILE EXISTS AT ALL
 * --------------------------
 * `.github/workflows/ci.yml` has had a `permission-matrix-sanity` job that runs
 * `node scripts/checkPermissionMatrix.mjs` — and that script did not exist. The
 * job would have failed with `MODULE_NOT_FOUND` on every run, which is worse
 * than having no gate: it looks like a red build caused by the code under test
 * rather than by a typo in a filename, so the reflex is to re-run or to blame
 * permissions, and the real drift underneath never gets looked at.
 *
 * WHAT IT CHECKS
 * --------------
 * Two ways a role/permission matrix silently rots, both of which present to a
 * user as "this feature is broken" rather than "this is a misconfiguration":
 *
 *   1. A role is missing from the matrix entirely. Every `authorize()` check
 *      denies such an account, so a whole profession's access disappears.
 *      `assertRoleMatrixComplete` already detects this; nothing called it.
 *
 *   2. A route requires a permission that NO role holds. That route is a
 *      permanent 403 for every non-superadmin — the endpoint exists, is
 *      documented, and can never succeed. This is the one worth failing on.
 *
 * The converse (a permission in the matrix no route uses) is reported but does
 * NOT fail: reserved permissions ahead of a route are normal, and a gate that
 * punishes planning would be deleted.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  ROLE_PERMISSIONS,
  CANONICAL_ROLES,
  assertRoleMatrixComplete,
  roleHasPermission,
} from '../src/config/permissions.js';
// Comments are stripped with the SAME helper the route scanner uses, and that
// matters for correctness rather than tidiness: a fix often writes
// `// used to be authorize('records:write')` in its explanation. Scanning raw
// text would then count a permission as "used by a route" that no route
// actually gates on — which does not merely add noise, it SUPPRESSES the
// unreachable-permission report and hides the real drift underneath.
// routeScan's own docblock says it plainly: "A comment is not a control, but it
// very often NAMES one."
import { stripComments } from './lib/routeScan.mjs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROUTES_DIR = path.resolve(__dirname, '..', 'src', 'routes');

const fail = [];
const note = (m) => console.log(`  ${m}`);
const bad = (m) => { fail.push(m); console.error(`  ${m}`); };

// ── 1. every canonical role has a matrix entry ──────────────────────────────
console.log('permission matrix sanity');
console.log('------------------------');
try {
  assertRoleMatrixComplete(ROLE_PERMISSIONS);
  note(`all ${CANONICAL_ROLES.length} canonical roles have a matrix entry`);
} catch (err) {
  bad(err.message);
}

// ── 2. every permission a route requires is actually held by someone ───────
//
// `authorize('a', 'b')` means "a OR b", so a permission is REACHABLE if any
// non-superadmin role holds it. Superadmin carries '*' and would mask the whole
// check, so it is excluded deliberately: the question is whether the feature
// works for anybody who is not the platform owner.
const WORKING_ROLES = CANONICAL_ROLES.filter((r) => r !== 'superadmin');

const used = new Map();   // permission -> [{file, line}]
const opaque = [];        // authorize(...variable) — not statically checkable

for (const file of fs.readdirSync(ROUTES_DIR).filter((f) => f.endsWith('.js'))) {
  const lines = stripComments(fs.readFileSync(path.join(ROUTES_DIR, file), 'utf8')).split('\n');
  lines.forEach((line, i) => {
    const at = line.indexOf('authorize(');
    if (at === -1) return;
    // The call is `authorize(` + argument list; take everything up to the
    // matching `)` or the end of the line, whichever comes first.
    const args = line.slice(at + 'authorize('.length);
    const end = args.indexOf(')');
    const argText = end === -1 ? args : args.slice(0, end);

    const literals = [...argText.matchAll(/'([^']+)'|"([^"]+)"/g)]
      .map((m) => m[1] || m[2])
      .filter(Boolean);
    if (literals.length === 0) {
      opaque.push(`${file}:${i + 1}  authorize(${argText.trim().slice(0, 60)})`);
      return;
    }
    for (const perm of literals) {
      if (!used.has(perm)) used.set(perm, []);
      used.get(perm).push(`${file}:${i + 1}`);
    }
  });
}

const unreachable = [];
for (const [perm, sites] of used) {
  const holders = WORKING_ROLES.filter((role) => roleHasPermission(role, perm));
  if (holders.length === 0) unreachable.push({ perm, sites });
}

console.log(`\n  permissions referenced by routes : ${used.size}`);
console.log(`  canonical non-superadmin roles   : ${WORKING_ROLES.length}`);

if (unreachable.length) {
  console.error(`\n  ${unreachable.length} permission(s) required by a route that NO non-superadmin role holds:`);
  for (const u of unreachable) {
    console.error(`    ${u.perm}`);
    console.error(`      used at ${u.sites.slice(0, 4).join(', ')}${u.sites.length > 4 ? ` (+${u.sites.length - 4} more)` : ''}`);
  }
  console.error('\n  These routes are a permanent 403 for every role. Either grant the');
  console.error('  permission to the role that is supposed to use it, or delete the route.');
  fail.push(`${unreachable.length} unreachable permission(s)`);
} else {
  note('\n  every permission a route requires is held by at least one non-superadmin role');
}

if (opaque.length) {
  // NOT a failure. `authorize(...SOME_CONST)` cannot be resolved by reading the
  // call site, and pretending otherwise would either miss real drift or force
  // someone to inline constants to satisfy a linter.
  console.log(`\n  ${opaque.length} authorize() call(s) take a non-literal argument - not statically checked:`);
  for (const o of opaque) console.log(`    ${o}`);
}

// ── 3. permissions in the matrix that no route asks for ────────────────────
// Informational only: reserved-ahead-of-a-route permissions are legitimate.
const declared = new Set(
  Object.values(ROLE_PERMISSIONS).flat().filter((p) => p !== '*')
);
const unused = [...declared].filter((p) => !used.has(p)).sort();
if (unused.length) {
  console.log(`\n  ${unused.length} declared permission(s) not referenced by any route (informational):`);
  console.log(`    ${unused.join(', ')}`);
}

console.log('');
if (fail.length) {
  console.error(`permission matrix gate FAILED (${fail.join('; ')})`);
  process.exit(1);
}
console.log('permission matrix gate OK');

