import mongoose from 'mongoose';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.join(__dirname, '..', '.env') });

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/findmedi';

async function migrateIndex() {
  await mongoose.connect(MONGO_URI);
  console.log('Connected to MongoDB.');

  const db = mongoose.connection.db;
  const collection = db.collection('appointments');

  const indexes = await collection.indexes();
  console.log('\nCurrent indexes on appointments collection:');
  indexes.forEach(idx => console.log(`  ${idx.name}: ${JSON.stringify(idx.key)}`));

  const oldIndexName = 'patientId_1_date_1_time_1';
  const oldIndex = indexes.find(idx => idx.name === oldIndexName);

  if (oldIndex) {
    console.log(`\nDropping old index "${oldIndexName}"...`);
    await collection.dropIndex(oldIndexName);
    console.log('Old index dropped successfully.');
  } else {
    console.log(`\nOld index "${oldIndexName}" not found — already removed.`);
  }

  const expectedIndex = indexes.find(idx => idx.name === 'patientId_1_doctorId_1_date_1_time_1');
  if (expectedIndex) {
    console.log('New index patientId_1_doctorId_1_date_1_time_1 already exists. Skipping creation.');
  } else {
    console.log('\nCreating new compound index doctorId_1_patientId_1_date_1_time_1...');
    await collection.createIndex(
      { doctorId: 1, patientId: 1, date: 1, time: 1 },
      { unique: true, partialFilterExpression: { status: { $in: ['Pending', 'Confirmed', 'In Queue', 'Serving'] }, doctorId: { $type: 'objectId' } } }
    );
    console.log('New index created successfully.');
  }

  const finalIndexes = await collection.indexes();
  console.log('\nFinal indexes on appointments collection:');
  finalIndexes.forEach(idx => console.log(`  ${idx.name}: ${JSON.stringify(idx.key)}`));

  await mongoose.disconnect();
  console.log('\nMigration complete.');
}

migrateIndex().catch(err => {
  console.error('Migration failed:', err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * R0 taxonomy migration (rolesmd/subcatogary.md PART D step 1).
 *
 * Backfills the new Category lineage fields, drops the legacy unique index that
 * made "Paediatrics under Dentistry" impossible, seeds the canonical specialty
 * rows, and maps Doctor.specialization free text onto Doctor.specialtyCode.
 *
 * Usage:
 *   node scripts/migrate-category-taxonomy.mjs           # dry run (default)
 *   node scripts/migrate-category-taxonomy.mjs --apply   # write
 *
 * Idempotent: re-running reports nothing to change.
 */
import mongoose from 'mongoose';

const APPLY = process.argv.includes('--apply');
const MONGO_URI = process.env.MONGO_URI;
if (!MONGO_URI) {
  console.error('MONGO_URI is not set — refusing to run.');
  process.exit(1);
}

const escapeRegex = (value) => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const slug = (type, name) => {
  const prefix = String(type ?? '').toUpperCase().replace(/[^A-Z]/g, '') || 'ITEM';
  const body = String(name ?? '').toUpperCase().replace(/[^A-Z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 48);
  return `${prefix}.${body || 'ITEM'}`;
};

await mongoose.connect(MONGO_URI);
mongoose.set('autoIndex', false);

const { default: Category } = await import('../src/models/Category.js');
const { default: Doctor } = await import('../src/models/Doctor.js');
const { SPECIALTIES, resolveSpecialtyCode } = await import('../src/lib/taxonomy.js');

console.log(`Category taxonomy migration (${APPLY ? 'APPLY' : 'DRY RUN'})\n`);

const report = (label, count, detail = '') =>
  console.log(`  ${label.padEnd(34)} ${String(count).padStart(5)}${detail ? `  ${detail}` : ''}`);

// ── 1. codes ────────────────────────────────────────────────────────────────
const rows = await Category.find({}).select('_id code type name parent path level').lean();
const used = new Map();
for (const row of rows) {
  if (!row.code) continue;
  const taken = used.get(row.type) || new Set();
  taken.add(row.code);
  used.set(row.type, taken);
}
const codePlan = [];
for (const row of rows) {
  if (row.code) continue;
  const taken = used.get(row.type) || new Set();
  const base = slug(row.type, row.name);
  let candidate = base;
  let suffix = 2;
  while (taken.has(candidate)) candidate = `${base}_${suffix++}`;
  taken.add(candidate);
  used.set(row.type, taken);
  codePlan.push({ id: row._id, code: candidate, name: row.name, type: row.type });
}
report('categories missing code', codePlan.length);
for (const plan of codePlan.slice(0, 20)) console.log(`      ${plan.type.padEnd(12)} ${plan.name} -> ${plan.code}`);
if (codePlan.length > 20) console.log(`      ... and ${codePlan.length - 20} more`);

if (APPLY) {
  for (const plan of codePlan) {
    await Category.updateOne({ _id: plan.id }, { $set: { code: plan.code } }, { overwriteImmutable: true });
  }
}
const codeById = new Map(codePlan.map((p) => [String(p.id), p.code]));
for (const row of rows) if (!row.code) row.code = codeById.get(String(row._id));

// ── 2. path / level ─────────────────────────────────────────────────────────
const byId = new Map(rows.map((r) => [String(r._id), r]));
const lineagePlan = [];
const compute = (row, seen = new Set()) => {
  if (!row || seen.has(String(row._id))) return { path: row?.code || 'ITEM', level: 0 };
  seen.add(String(row._id));
  if (row.parent) {
    const parent = byId.get(String(row.parent));
    if (parent) {
      const above = compute(parent, seen);
      return { path: `${above.path}/${row.code}`, level: above.level + 1 };
    }
  }
  return { path: row.code, level: 0 };
};
for (const row of rows) {
  const next = compute(row);
  if (row.path !== next.path || row.level !== next.level) {
    lineagePlan.push({ id: row._id, ...next });
  }
}
report('path/level corrections', lineagePlan.length);
if (APPLY) {
  for (const plan of lineagePlan) {
    await Category.updateOne({ _id: plan.id }, { $set: { path: plan.path, level: plan.level } }, { overwriteImmutable: true });
  }
}

// ── 3. duplicate names under one parent (would break the new {type,parent,name} index) ──
const dupeKey = new Map();
for (const row of rows) {
  const key = `${row.type}|${row.parent || 'root'}|${String(row.name).toLowerCase()}`;
  dupeKey.set(key, (dupeKey.get(key) || 0) + 1);
}
const dupes = [...dupeKey.entries()].filter(([, count]) => count > 1);
report('duplicate name under same parent', dupes.length, dupes.length ? '(resolve manually)' : '');

// ── 4. indexes ──────────────────────────────────────────────────────────────
const before = await Category.collection.listIndexes();
const legacy = before.filter((idx) => {
  const keys = Object.keys(idx.key);
  return !idx.name.startsWith('_') && idx.unique && keys.length === 2 && keys.includes('name') && keys.includes('type');
});
report('legacy unique {name,type} indexes', legacy.length, legacy.map((i) => i.name).join(', '));
report('current index count', before.length, before.map((i) => i.name).join(', '));

// ── 5. canonical specialties ────────────────────────────────────────────────
let seeded = 0;
let updatedSpecialty = 0;
for (const specialty of SPECIALTIES) {
  const existing = await Category.findOne({
    type: 'specialty',
    $or: [{ code: specialty.code }, { name: new RegExp(`^${escapeRegex(specialty.name)}$`, 'i') }],
  }).select('_id code name').lean();

  if (existing) {
    if (existing.code === specialty.code) continue;
    updatedSpecialty += 1;
    if (APPLY) {
      await Category.updateOne({ _id: existing._id },
        { $set: { code: specialty.code, name: specialty.name, aliases: specialty.aliases, path: specialty.code, level: 0, tier: 'T1' } },
        { overwriteImmutable: true });
    }
  } else {
    seeded += 1;
    if (APPLY) {
      await Category.create({
        type: 'specialty', code: specialty.code, name: specialty.name,
        aliases: specialty.aliases, path: specialty.code, level: 0, tier: 'T1',
      });
    }
  }
}
report('canonical specialties to create', seeded);
report('canonical specialties to re-code', updatedSpecialty);

// ── 6. Doctor.specialization -> specialtyCode ───────────────────────────────
const specializations = await Doctor.distinct('specialization');
let mapped = 0;
let unmapped = 0;
const unmappedValues = [];
for (const value of specializations.filter(Boolean)) {
  const code = resolveSpecialtyCode(value);
  if (!code) {
    unmapped += 1;
    unmappedValues.push(value);
    continue;
  }
  mapped += 1;
  if (APPLY) {
    await Doctor.updateMany(
      { specialization: value, $or: [{ specialtyCode: { $in: ['', null] } }, { specialtyCode: { $exists: false } }] },
      { $set: { specialtyCode: code } },
    );
  }
}
report('distinct specializations mapped', mapped);
report('distinct specializations unmapped', unmapped, unmappedValues.slice(0, 8).join(' | '));
if (unmappedValues.length > 8) console.log(`      ... and ${unmappedValues.length - 8} more`);

// ── apply-only: sync declared indexes, drop the legacy unique index ─────────
if (APPLY) {
  if (dupes.length) {
    console.log('\n  NOT syncing indexes: duplicate names under one parent would break {type,parent,name}.');
    console.log('  Fix the duplicates above, then re-run with --apply.');
  } else {
    const sync = await Category.syncIndexes();
    console.log(`\n  syncIndexes -> ${sync.length} index operation(s) applied.`);
  }
}

console.log(APPLY ? '\ndone.' : '\ndry run complete; pass --apply to write.');
await mongoose.disconnect();
process.exit(0);

import mongoose from 'mongoose';
import dotenv from 'dotenv';
import path from 'path';
import dns from 'dns';
import { fileURLToPath } from 'url';
import { remapSubSpecialtyCode, remapSubSpecialtyCodes } from '../src/lib/taxonomy.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.join(__dirname, '..', '.env') });
dns.setServers(['8.8.8.8', '1.1.1.1']);

// Dry-run is the default. Explicit --apply is required before any persisted
// doctor row changes; this makes a mistaken invocation read-only.
const apply = process.argv.includes('--apply');
const mongoUri = process.env.MONGO_URI || 'mongodb://localhost:27017/findmedi';

function safeTarget(uri) {
  try {
    const parsed = new URL(uri);
    return `${parsed.hostname}/${parsed.pathname.replace(/^\//, '').split('?')[0] || '(default database)'}`;
  } catch { return '(unparseable MongoDB target)'; }
}

async function migrateDoctorSubSpecialties() {
  await mongoose.connect(mongoUri);
  console.log(`Connected to ${safeTarget(mongoUri)} (${apply ? 'APPLY' : 'DRY RUN'}).`);

  const doctors = mongoose.connection.db.collection('doctors');
  const cursor = doctors.find({
    $or: [
      { subSpecialtyCodes: { $exists: true, $ne: [] } },
      { specialtyCode: { $exists: true, $type: 'string', $ne: '' } },
    ],
  }).project({ _id: 1, subSpecialtyCodes: 1, specialtyCode: 1 });

  let scanned = 0;
  let wouldChange = 0;
  let listsChanged = 0;
  let specialtiesChanged = 0;
  for await (const doc of cursor) {
    scanned += 1;
    const original = Array.isArray(doc.subSpecialtyCodes) ? doc.subSpecialtyCodes : [];
    const cleaned = remapSubSpecialtyCodes(original);
    const set = {};
    if (JSON.stringify(original) !== JSON.stringify(cleaned)) {
      set.subSpecialtyCodes = cleaned;
      listsChanged += 1;
    }

    const canonicalSpecialty = remapSubSpecialtyCode(doc.specialtyCode || '');
    if (canonicalSpecialty && canonicalSpecialty !== doc.specialtyCode) {
      set.specialtyCode = canonicalSpecialty;
      specialtiesChanged += 1;
    }

    if (!Object.keys(set).length) continue;
    wouldChange += 1;
    if (apply) await doctors.updateOne({ _id: doc._id }, { $set: set });
  }

  console.log(JSON.stringify({ mode: apply ? 'apply' : 'dry-run', scanned, doctorsChanged: wouldChange, listsChanged, specialtiesChanged }, null, 2));
  if (!apply && wouldChange) console.log('No rows were changed. Re-run with --apply only after reviewing the target and counts.');
  await mongoose.disconnect();
}

migrateDoctorSubSpecialties().catch(async (err) => {
  console.error('migrate-doctor-subspecialties failed:', err.message);
  try { await mongoose.disconnect(); } catch { /* already closed */ }
  process.exitCode = 1;
});

/**
 * P2-9: one-shot migration — encrypt legacy PLAINTEXT govt IDs + bank details
 * at rest (AES-256-GCM, see src/utils/phiFields.js).
 *
 *   node scripts/migrate-encrypt-phi.mjs --dry-run   # default: report only
 *   node scripts/migrate-encrypt-phi.mjs --apply      # encrypt in place
 *   node scripts/migrate-encrypt-phi.mjs --rollback   # decrypt back to plaintext
 *
 * Safety:
 * - Requires FIELD_ENCRYPTION_KEY(S) in env (dev fallback is per-boot random
 *   and MUST NOT be used for real data — the script refuses without a key
 *   unless --allow-dev-key is passed explicitly for local testing).
 * - Idempotent: already-encrypted values are skipped; blind-index hashes are
 *   (re)computed for every row that has an ID.
 * - --rollback only touches values it can decrypt; anything else is reported
 *   and left alone.
 * - Run a backup + --dry-run first. Verify with:
 *     db.assistantprofiles.countDocuments({ govtIdNumber: { $not: /^v1:/ } })
 */
import mongoose from 'mongoose';
import { isEncrypted, decryptField } from '../src/utils/fieldEncryption.js';
import {
  encryptPhi,
  decryptPhi,
  phiBlindIndex,
  normalizeGovtId,
  phiAad,
} from '../src/utils/phiFields.js';

const args = new Set(process.argv.slice(2));
const APPLY = args.has('--apply');
const ROLLBACK = args.has('--rollback');
const ALLOW_DEV = args.has('--allow-dev-key');

if (!process.env.FIELD_ENCRYPTION_KEY && !process.env.FIELD_ENCRYPTION_KEYS && !ALLOW_DEV) {
  console.error('Refusing: set FIELD_ENCRYPTION_KEY(S) first (or --allow-dev-key for local throwaway data).');
  process.exit(2);
}
if (!process.env.MONGO_URI) {
  console.error('Refusing: MONGO_URI is not set.');
  process.exit(2);
}

const TARGETS = [
  { name: 'AssistantProfile', idField: 'govtIdNumber', bank: true },
  { name: 'RiderProfile', idField: 'govtIdNumber', bank: true },
  { name: 'LawyerProfile', idField: 'govtIdNumber', bank: true },
  { name: 'DeliveryPartner', idField: null, bank: 'dp' }, // accountNo/holderName shape
];

const stats = { scanned: 0, encrypted: 0, hashed: 0, decrypted: 0, skipped: 0, errors: [] };

const maybeEncrypt = (model, field, v) => {
  if (!v) return { value: v, changed: false };
  if (isEncrypted(String(v))) return { value: v, changed: false };
  return { value: encryptPhi(model, field, v), changed: true };
};

async function run() {
  await mongoose.connect(process.env.MONGO_URI);
  for (const t of TARGETS) {
    const { default: Model } = await import(`../src/models/${t.name}.js`);
    const docs = await Model.find({}).lean(false);
    for (const doc of docs) {
      stats.scanned += 1;
      try {
        let dirty = false;
        if (ROLLBACK) {
          // Decrypt anything we can; leave the rest and report.
          for (const path of [t.idField, 'bankDetails.accountNumber', 'bankDetails.ifsc', 'bankDetails.upiId', 'bankDetails.accountNo'].filter(Boolean)) {
            const raw = path === t.idField ? doc[t.idField] : doc.bankDetails?.[path.split('.')[1]];
            if (typeof raw === 'string' && isEncrypted(raw)) {
              try {
                const plain = decryptField(raw, phiAad(t.name, path));
                if (path === t.idField) doc[t.idField] = plain;
                else doc.bankDetails[path.split('.')[1]] = plain;
                dirty = true;
                stats.decrypted += 1;
              } catch (e) {
                stats.errors.push(`${t.name}:${doc._id}:${path}: cannot decrypt (${e.message})`);
              }
            }
          }
        } else {
          if (t.idField && doc[t.idField]) {
            const norm = normalizeGovtId(doc[t.idField]);
            // Re-normalize legacy rows (register uppercases; old rows may not be).
            const r = maybeEncrypt(t.name, t.idField, isEncrypted(String(doc[t.idField])) ? doc[t.idField] : norm);
            if (r.changed || doc[t.idField] !== r.value) { doc[t.idField] = r.value; dirty = true; stats.encrypted += r.changed ? 1 : 0; }
            const h = norm ? phiBlindIndex(norm) : '';
            if (doc.govtIdNumberHash !== h) { doc.govtIdNumberHash = h; dirty = true; stats.hashed += 1; }
          }
          const bd = doc.bankDetails || {};
          const fields = t.bank === 'dp'
            ? [['accountNo', 'bankDetails.accountNo'], ['ifsc', 'bankDetails.ifsc'], ['upiId', 'bankDetails.upiId']]
            : [['accountNumber', 'bankDetails.accountNumber'], ['ifsc', 'bankDetails.ifsc'], ['upiId', 'bankDetails.upiId']];
          for (const [key, path] of fields) {
            if (bd[key]) {
              const r = maybeEncrypt(t.name, path, bd[key]);
              if (r.changed) { bd[key] = r.value; dirty = true; stats.encrypted += 1; }
            }
          }
          if (dirty && t.bank) doc.bankDetails = bd;
        }
        if (dirty) {
          if (APPLY || ROLLBACK) await doc.save();
          else stats.skipped += 1;
        }
      } catch (e) {
        stats.errors.push(`${t.name}:${doc._id}: ${e.message}`);
      }
    }
  }
  await mongoose.disconnect();
  console.log(JSON.stringify({ mode: ROLLBACK ? 'rollback' : APPLY ? 'apply' : 'dry-run', ...stats, errorCount: stats.errors.length }, null, 2));
  if (stats.errors.length) console.log('ERRORS:', stats.errors.slice(0, 20));
}

run().catch((e) => { console.error('Migration failed:', e.message); process.exit(1); });

