/**
 * PG dual-write reconciliation (read-only, zero writes).
 *
 * Compares MongoDB (primary today) vs PostgreSQL (dual-write mirror) for the
 * six money models: Payment, Billing, Insurance, TransactionLedger, Payout,
 * CommissionConfig. Compares document counts + money totals in paise (avoids
 * float/Decimal representation noise).
 *
 * Exit codes: 0 = zero drift (safe to cut reads over), 1 = drift found,
 *             2 = skipped (PG not reachable / client not generated).
 *
 * Run:  node scripts/reconcile-pg.mjs
 * Env:  MONGO_URI + DATABASE_URL (see backend/.env.example)
 */
import mongoose from 'mongoose';
import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
dotenv.config({ path: path.join(__dirname, '..', '.env') });

const MONGO_URI = process.env.MONGO_URI || 'mongodb://localhost:27017/findmedi';
const DATABASE_URL = process.env.DATABASE_URL || '';

// Paise-normalize any money value (Number, Decimal, string, null) -> integer.
const toPaise = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n * 100) : 0;
};

async function mongoStats(db) {
  const sum = async (coll, field) => {
    const [r] = await db.collection(coll).aggregate([
      { $group: { _id: null, total: { $sum: `$${field}` } } },
    ]).toArray();
    return toPaise(r?.total);
  };
  const count = (coll) => db.collection(coll).estimatedDocumentCount();
  return {
    payment: { count: await count('payments'), amountPaise: await sum('payments', 'amount') },
    billing: { count: await count('billings'), amountPaise: await sum('billings', 'amount') },
    insurance: { count: await count('insurances'), claimPaise: await sum('insurances', 'claimAmount') },
    ledger: {
      count: await count('transactionledgers'),
      amountPaise: await sum('transactionledgers', 'amount'),
      netPaise: await sum('transactionledgers', 'netAmount'),
    },
    payout: { count: await count('payouts'), netPaise: await sum('payouts', 'netPayout') },
    commissionConfig: { count: await count('commissionconfigs') },
  };
}

async function pgStats(prisma) {
  const [pCount, pSum] = await Promise.all([
    prisma.payment.count(),
    prisma.payment.aggregate({ _sum: { amount: true } }),
  ]);
  const [bCount, bSum] = await Promise.all([
    prisma.billing.count(),
    prisma.billing.aggregate({ _sum: { amount: true } }),
  ]);
  const [iCount, iSum] = await Promise.all([
    prisma.insurance.count(),
    prisma.insurance.aggregate({ _sum: { claimAmount: true } }),
  ]);
  const [lCount, lSum] = await Promise.all([
    prisma.transactionLedger.count(),
    prisma.transactionLedger.aggregate({ _sum: { amount: true, netAmount: true } }),
  ]);
  const [poCount, poSum] = await Promise.all([
    prisma.payout.count(),
    prisma.payout.aggregate({ _sum: { netPayout: true } }),
  ]);
  const ccCount = await prisma.commissionConfig.count();
  return {
    payment: { count: pCount, amountPaise: toPaise(pSum._sum.amount) },
    billing: { count: bCount, amountPaise: toPaise(bSum._sum.amount) },
    insurance: { count: iCount, claimPaise: toPaise(iSum._sum.claimAmount) },
    ledger: { count: lCount, amountPaise: toPaise(lSum._sum.amount), netPaise: toPaise(lSum._sum.netAmount) },
    payout: { count: poCount, netPaise: toPaise(poSum._sum.netPayout) },
    commissionConfig: { count: ccCount },
  };
}

async function main() {
  if (!DATABASE_URL) {
    console.log('SKIP: DATABASE_URL unset — PG mirror not configured, nothing to reconcile.');
    process.exit(2);
  }
  let PrismaClient;
  try {
    ({ PrismaClient } = await import('@prisma/client'));
  } catch {
    console.log('SKIP: @prisma/client not installed/generated — run `npm install` + `npx prisma generate` first.');
    process.exit(2);
  }

  await mongoose.connect(MONGO_URI, { serverSelectionTimeoutMS: 15000, family: 4 });
  const prisma = new PrismaClient();
  try {
    await prisma.$queryRaw`SELECT 1`;
  } catch (err) {
    console.log(`SKIP: PG unreachable (${err.message})`);
    await mongoose.disconnect();
    process.exit(2);
  }

  const [m, p] = await Promise.all([mongoStats(mongoose.connection.db), pgStats(prisma)]);
  const diffs = [];
  for (const key of Object.keys(m)) {
    for (const field of Object.keys(m[key])) {
      if (m[key][field] !== p[key][field]) {
        diffs.push(`${key}.${field}: mongo=${m[key][field]} pg=${p[key][field]}`);
      }
    }
  }

  console.log(JSON.stringify({ mongo: m, postgres: p }, null, 2));
  if (diffs.length) {
    console.error(`\nDRIFT (${diffs.length}):`);
    diffs.forEach((d) => console.error(`  - ${d}`));
    console.error('Do NOT cut reads over. Investigate dual-write gaps first.');
    process.exitCode = 1;
  } else {
    console.log('\nOK: zero drift — reads can be cut over to PG.');
  }

  await Promise.all([mongoose.disconnect(), prisma.$disconnect()]);
}

main().catch((err) => { console.error('Failed:', err); process.exit(1); });

#!/usr/bin/env node
/**
 * FindMedi Category Tree Seeder & Validator (Idempotent).
 *
 * Source: rolesmd/FindMedi-Categories-Pruned.md & rolesmd/FindMedi-Category-Seed-Plan.md
 *
 * Usage:
 *   node backend/scripts/seed/seed-category-tree.mjs --dry-run   # Validation & plan print (exits 0 on success)
 *   node backend/scripts/seed/seed-category-tree.mjs --apply     # Write to MongoDB (requires MONGO_URI)
 */

import dotenv from 'dotenv';
import path from 'path';
import { fileURLToPath } from 'url';
import mongoose from 'mongoose';
import { CATEGORY_TREE } from '../../src/data/categoryTree.mjs';
import { CATEGORY_TYPES, CATEGORY_TIERS, CATEGORY_CODE_RE } from '../../src/lib/taxonomy.js';

import { configureMongoDns, connectMongooseWithRetry } from '../../src/config/mongoDns.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
dotenv.config({ path: path.join(__dirname, '..', '..', '.env') });
configureMongoDns();

const isApply = process.argv.includes('--apply');
const isDryRun = process.argv.includes('--dry-run') || !isApply;

// Forbidden items from the pruned catalogue's "Jo hata diya gaya" section.
// Matched on word boundaries so specialty codes like SPEC.NUCMED / SPEC.OCCMED
// do not false-positive on the "cme" token.
const FORBIDDEN_TOKENS = [
  'veterinary', 'pet care', 'tattoo', 'piercing', 'salon', 'pest control',
  'ro purifier', 'purifier service', 'air ambulance', 'medical tourism',
  'cremation', 'funeral', 'crowdfunding', 'medical emi', 'medical loans',
  'insurance comparison', 'insurance advisor', 'cme', 'claims fraud',
  'cord blood bank', 'reiki', 'energy healing',
];

const FORBIDDEN_RES = FORBIDDEN_TOKENS.map(
  (token) => new RegExp(`\\b${token.trim().split(/\s+/).join('\\s+')}\\b`, 'i')
);

console.log(`\n======================================================`);
console.log(` FindMedi Category Tree Seeder (${isApply ? 'APPLY' : 'DRY RUN'})`);
console.log(`======================================================\n`);

// ─── 1. In-memory Static Validation ──────────────────────────────────────────
const errors = [];
const codeMap = new Map();

// Check for duplicates, regex validity, types, tiers, and forbidden leakage
for (const [index, item] of CATEGORY_TREE.entries()) {
  const rowId = `Row #${index + 1} (${item.code || 'NO_CODE'})`;

  if (!item.code) {
    errors.push(`${rowId}: code is required`);
    continue;
  }

  if (!CATEGORY_CODE_RE.test(item.code)) {
    errors.push(`${rowId}: code "${item.code}" fails CATEGORY_CODE_RE pattern`);
  }

  if (codeMap.has(item.code)) {
    errors.push(`${rowId}: duplicate code "${item.code}" found`);
  }
  codeMap.set(item.code, item);

  if (!item.name || typeof item.name !== 'string' || item.name.trim().length < 2) {
    errors.push(`${rowId}: name is required (min 2 chars)`);
  }

  if (!CATEGORY_TYPES.includes(item.type)) {
    errors.push(`${rowId}: type "${item.type}" is not in CATEGORY_TYPES`);
  }

  if (item.tier && !CATEGORY_TIERS.includes(item.tier)) {
    errors.push(`${rowId}: tier "${item.tier}" is not in CATEGORY_TIERS`);
  }

  // Check forbidden tokens in name, aliases, code (word-boundary match)
  const searchable = `${item.code} ${item.name} ${(item.aliases || []).join(' ')}`;
  for (const forbiddenRe of FORBIDDEN_RES) {
    if (forbiddenRe.test(searchable)) {
      errors.push(`${rowId}: contains dropped/forbidden term "${forbiddenRe.source}"`);
    }
  }
}

// Check parent references
for (const item of CATEGORY_TREE) {
  if (item.parent !== null && item.parent !== undefined) {
    if (!codeMap.has(item.parent)) {
      errors.push(`Code "${item.code}": parent code "${item.parent}" does not exist in the tree`);
    }
  }
}

// Compute path and level for each item
function computeLineage(item, visited = new Set()) {
  if (visited.has(item.code)) {
    errors.push(`Cycle detected at "${item.code}"`);
    return { path: item.code, level: 0 };
  }
  visited.add(item.code);

  if (!item.parent) {
    return { path: item.code, level: 0 };
  }

  const parentItem = codeMap.get(item.parent);
  if (!parentItem) {
    return { path: item.code, level: 0 };
  }

  const parentLineage = computeLineage(parentItem, new Set(visited));
  return {
    path: `${parentLineage.path}/${item.code}`,
    level: parentLineage.level + 1,
  };
}

const computedItems = [];
for (const item of CATEGORY_TREE) {
  const { path, level } = computeLineage(item);
  computedItems.push({ ...item, path, level });
}

// ─── 2. Validation Report ────────────────────────────────────────────────────
console.log(`Total categories in catalogue:  ${CATEGORY_TREE.length}`);
console.log(`Root / group categories:        ${computedItems.filter((i) => i.level === 0).length}`);
console.log(`Leaf / sub categories:          ${computedItems.filter((i) => i.level > 0).length}`);
console.log(`Sensitive (T1 / discreet):      ${computedItems.filter((i) => i.isSensitive).length}`);
console.log(`Ad-claims restricted:           ${computedItems.filter((i) => i.adClaimsRestricted).length}`);
console.log(`Roadmap ("soon" status):        ${computedItems.filter((i) => i.soon).length}`);

if (errors.length > 0) {
  console.error(`\n❌ Validation FAILED with ${errors.length} error(s):`);
  for (const err of errors) console.error(`  - ${err}`);
  process.exit(1);
}

console.log(`\n✔ Static validation PASSED: 0 errors, all codes valid, all parents resolved, 0 dropped category leakage.`);

if (isDryRun && !isApply) {
  console.log(`\nDry run completed successfully. Pass --apply to write to database.`);
  process.exit(0);
}

// ─── 3. Database Upsert (--apply mode) ──────────────────────────────────────
const MONGO_URI = process.env.MONGO_URI;
if (!MONGO_URI) {
  console.error('\n❌ MONGO_URI is not set. Cannot run in --apply mode without MONGO_URI.');
  process.exit(1);
}

console.log(`\nConnecting to MongoDB: ${MONGO_URI.replace(/:[^:]*@/, ':****@')}...`);
await connectMongooseWithRetry(mongoose, MONGO_URI);
mongoose.set('autoIndex', false);

const { default: Category } = await import('../../src/models/Category.js');

let createdCount = 0;
let updatedCount = 0;

for (const item of computedItems) {
  const doc = {
    name: item.name,
    nameHi: item.nameHi || '',
    type: item.type,
    aliases: item.aliases || [],
    path: item.path,
    level: item.level,
    tier: item.tier || 'T1',
    regulatedBy: item.regulatedBy || [],
    adClaimsRestricted: Boolean(item.adClaimsRestricted),
    isSensitive: Boolean(item.isSensitive),
    soon: Boolean(item.soon),
    kind: item.kind || '',
    isActive: true,
  };

  const existing = await Category.findOne({ code: item.code });
  if (existing) {
    await Category.updateOne({ _id: existing._id }, { $set: doc }, { overwriteImmutable: true });
    updatedCount += 1;
  } else {
    await Category.create({ code: item.code, ...doc });
    createdCount += 1;
  }
}

// ─── 4. Deactivate / Prune Untracked Categories ─────────────────────────────
const validCodeSet = new Set(computedItems.map((i) => i.code));
const untrackedResult = await Category.updateMany(
  { code: { $nin: Array.from(validCodeSet) }, isActive: true },
  { $set: { isActive: false } }
);

if (process.argv.includes('--delete-untracked')) {
  const deleteResult = await Category.deleteMany({ code: { $nin: Array.from(validCodeSet) } });
  console.log(`  - Deleted Untracked: ${deleteResult.deletedCount}`);
} else if (untrackedResult.modifiedCount > 0) {
  console.log(`  - Deactivated Untracked: ${untrackedResult.modifiedCount}`);
}

console.log(`\n✔ Database Sync Complete:`);
console.log(`  - Active Canonical: ${computedItems.length}`);
console.log(`  - Newly Created:    ${createdCount}`);
console.log(`  - Updated:          ${updatedCount}`);
console.log(`  - Untracked Dropped:${untrackedResult.modifiedCount}`);

await mongoose.disconnect();
console.log('\nFinished successfully.');
process.exit(0);

