// 5. FAST AUTO-EXPIRING OTP & RATE LIMITING
// ─────────────────────────────────────────────────────────────────────────────

export async function setRedisOTP(email, otpHash, ttlSeconds = 600) {
  if (!isRedisReady()) return false;
  try {
    await redisClient.set(`otp:${email.toLowerCase()}`, otpHash, { EX: ttlSeconds });
    return true;
  } catch (err) {
