// Connect & start
const PORT = process.env.PORT || 5001;
const mongooseOptions = {
  maxPoolSize: 10,
  serverSelectionTimeoutMS: 30000,
  socketTimeoutMS: 45000,
  family: 4,
  bufferCommands: false
};

logger.info('🔄 Attempting MongoDB connection...');
logger.info('   URI: ' + redactMongoUri(MONGO_URI));

if (process.env.NODE_ENV !== 'test') {
  const server = http.createServer(app);
  // §15.4: Slowloris guard — a client dribbling headers/body no longer pins a
  // socket for Node's 5-min default. Nginx client_*_timeout stays the outer layer.
  server.headersTimeout = 15000;
  server.requestTimeout = 30000;
  server.keepAliveTimeout = 5000;
  let instantDispatchRetryTimer;
  // INF-M-02: nodejs_*/process_* gauges start only on a real boot, so tests
  // that import this file never spawn the collection interval.
  startProcessMetrics();
  initSocket(server).then((mainIo) => {
    // Phase 6 (merge): MindSupport realtime rooms on the shared server.
    try { attachMindRealtime(mainIo); } catch (err) { logger.error(`MindSupport realtime attach failed: ${err.message}`); }
  }).catch((err) => logger.error(`Socket.IO init failed: ${err.message}`));
  mongoose.connect(MONGO_URI, mongooseOptions)
    .then(async () => {
      // Coupon caps depend on these unique keys. Create their indexes explicitly
      // before the HTTP listener opens rather than relying on autoIndex.
      try {
        const { default: CouponRedemption } = await import('./models/PlatformCouponRedemption.js');
        const { default: CouponUserUsage } = await import('./models/PlatformCouponUserUsage.js');
        await Promise.all([CouponRedemption.createIndexes(), CouponUserUsage.createIndexes()]);
        logger.info('Coupon redemption indexes ready');
      } catch (indexError) {
        logger.error(`Coupon redemption indexes failed; refusing to start payment API: ${indexError.message}`);
        throw indexError;
      }
      logger.info('✅ MongoDB connected successfully');

      // Initialize feature flags and PostHog
      initFeatureFlags();
      initPostHog();

      try {
        const { recoverStuckRequests } = await import('./services/emergencyDispatchService.js');
        await recoverStuckRequests();
      } catch (e) {
        logger.warn('recoverStuckRequests failed: ' + e.message);
      }
      // File 03 — H3 hex-cache reconciler (DB ↔ Redis drift fix, every 5 min)
      try {
        const { startHexCacheReconcile } = await import('./jobs/hexCacheReconcile.job.js');
        startHexCacheReconcile(Number(process.env.HEX_RECONCILE_INTERVAL_MS || 5 * 60 * 1000));
      } catch (e) {
        logger.warn('hexCacheReconcile scheduler failed: ' + e.message);
      }
      // Spec 14 — in-process demand-surge calculator (every 60s; Flink can replace it).
      try {
        const { startSurgeCalc } = await import('./jobs/surgeCalc.job.js');
        startSurgeCalc(Number(process.env.SURGE_CALC_INTERVAL_MS || 60 * 1000));
      } catch (e) {
        logger.warn('surgeCalc scheduler failed: ' + e.message);
      }
      // Spec 15 — OpenSearch indices (no-op unless OPENSEARCH_NODE is set).
      try {
        const { ensureIndices } = await import('./services/opensearchIndexer.js');
        ensureIndices().catch(() => {});
      } catch (e) {
        logger.warn('opensearch ensureIndices failed: ' + e.message);
      }
      // File 23: retry failed break-glass patient alerts and keep the PHI access
      // review queue actionable after transient notification-store failures.
      setInterval(async () => {
        try {
          const { retryBreakGlassPatientNotifications } = await import('./routes/breakGlass.js');
          await retryBreakGlassPatientNotifications();
        } catch (e) {
          logger.error('break-glass notification retry failed: ' + e.message);
        }
      }, 60 * 1000).unref?.();
      // Doc 02 §4.3: stale GPS → auto offline (unless on duty), every 60s
      setInterval(async () => {
        try {
          const { default: Ambulance } = await import('./models/Ambulance.js');
          const { default: RiderProfile } = await import('./models/RiderProfile.js');
          const riderFreshCutoff = new Date(Date.now() - Number(process.env.RIDER_LOCATION_FRESH_SECONDS || 60) * 1000);
          const staleRiders = await RiderProfile.find({ isOnline: true, riderStatus: 'active', 'currentLocation.updatedAt': { $lt: riderFreshCutoff } }).select('userId').limit(500).lean();
          if (staleRiders.length) {
            const riderIds = staleRiders.map((rider) => rider.userId);
            await RiderProfile.updateMany({ userId: { $in: riderIds }, isOnline: true, activeDispatchRequestId: null }, { $set: { isOnline: false } });
            const { removeProviderFromCache } = await import('./lib/h3Cache.js');
            await Promise.allSettled(riderIds.map((providerId) => removeProviderFromCache({ providerId, providerType: 'rider' })));
          }
          await Ambulance.updateMany(
            { isOnline: true, isOnDuty: { $ne: true }, lastPingAt: { $lt: new Date(Date.now() - 3 * 60 * 1000) } },
            { isOnline: false }
          );
        } catch {}
      }, 60 * 1000);
      // Graceful EADDRINUSE handling: without this the whole process died with an
      // unhandled 'error' event stack trace whenever a stale backend still held the port.
      server.on('error', (err) => {
        if (err?.code === 'EADDRINUSE') {
          logger.error(`Port ${PORT} is already in use - another FindMedi backend is probably still running.`);
          logger.error('   Fix: run "npm run free-ports" from the project root (or close the other terminal).');
          logger.error('   Tip: this watcher retries automatically on the next file change.');
          process.exit(1);
        }
        logger.error('Server error: ' + err.message);
        process.exit(1);
      });

      server.listen(PORT, () => {
        const serverUrl = `http://localhost:${PORT}`;
        logger.info(`🚀 Server running on ${serverUrl}`);
        logger.info(`📡 Health check: ${serverUrl}/api/health`);
      });
    })
    .catch(err => {
      logger.error('❌ MongoDB connection error: ' + err.message);
      logger.error('   Error code: ' + err.code);
      logger.error('   Error name: ' + err.name);
      logger.error('   Full URI used (redacted): ' + redactMongoUri(MONGO_URI));
      if (process.env.NODE_ENV !== 'production') {
        logger.error('   Stack trace: ' + err.stack);
      }
      process.exit(1);
    });

  mongoose.connection.on('connected', async () => {
    logger.info('✅ Mongoose connected to MongoDB');
    try {
      // Index sync is isolated from everything below it. A single bad index
      // spec (a `$ne` in a partial filter, a stale definition) used to reject
      // here and, because this all sat in ONE try, silently skipped demo
      // seeding, the outbox poller and every cron job while the API still came
      // up and served 404s on the data those jobs maintain. A failed index is
      // degraded, not fatal — log it and keep booting.
      try {
        const Appointment = (await import('./models/Appointment.js')).default;
        const Payment = (await import('./models/Payment.js')).default;
        const Doctor = (await import('./models/Doctor.js')).default;
        const Patient = (await import('./models/Patient.js')).default;
        await Appointment.syncIndexes();
        await Payment.syncIndexes();
        await Doctor.syncIndexes();
        await Patient.syncIndexes();
        logger.info('✅ Database indexes synced');
      } catch (indexError) {
        logger.error('⚠️ Index sync failed (continuing boot without it): ' + indexError.message);
      }

      // Same reasoning: demo seed failure must not take the pollers/jobs down
      // with it — the API is already listening either way.
      try {
        const { ensureDemoUsers } = await import('./services/demoSeedService.js');
        await ensureDemoUsers();
      } catch (seedError) {
        logger.error('⚠️ Demo seed failed (continuing boot): ' + seedError.message);
      }

      // Start Transactional Outbox Background Poller
      const { startOutboxPoller } = await import('./services/outboxPollerService.js');
      startOutboxPoller();
      const { startInstantDispatchRetryRecovery } = await import('./services/instantDispatchService.js');
      instantDispatchRetryTimer = startInstantDispatchRetryRecovery();

      // Start Event Consumer Subscriber Daemon (processes outbox / kafka pipeline)
      const { startKafkaConsumer } = await import('./services/kafkaConsumerService.js');
      startKafkaConsumer();

      // Spec 18 — internal gRPC MatchingEngineService (fail-soft; REST stays primary)
      try {
        const { startGrpcServer } = await import('./lib/grpcServer.js');
        await startGrpcServer();
      } catch (e) {
        logger.warn('gRPC server failed to start (non-fatal): ' + e.message);
      }

      // Phase 3 — BullMQ workers (notifications; no-op without REDIS_URL)
      try {
        const { startWorkers } = await import('./workers/index.js');
        await startWorkers();
      } catch (e) {
        logger.warn('job workers failed to start (non-fatal): ' + e.message);
      }

      // Release unconfirmed pharmacy stock holds after their finite checkout
      // window; the database CAS makes this safe across multiple API replicas.
      try {
        const { startPharmacyReservationExpiry } = await import('./services/pharmacyInventoryService.js');
        startPharmacyReservationExpiry({ intervalMs: Number(process.env.PHARMACY_RESERVATION_SWEEP_MS) || 60_000 });
      } catch (e) {
        logger.error('pharmacy reservation expiry worker failed to start: ' + e.message);
      }

      // MISS-PAY-003: wallet ledger reconciliation (daily, cron)
      try {
        const { startWalletReconcile } = await import('./jobs/walletReconcile.job.js');
        startWalletReconcile();
      } catch (e) {
        logger.warn('wallet reconcile job failed to start (non-fatal): ' + e.message);
      }

      // NOTIF-M-03: appointment reminders (T-24h/T-2h), every 5 min. The state
      // lives on the Appointment doc, so a missed tick is caught up by the next.
      try {
        const { startAppointmentReminders } = await import('./jobs/appointmentReminder.job.js');
        startAppointmentReminders(process.env.APPT_REMINDER_CRON || '*/5 * * * *');
      } catch (e) {
        logger.warn('appointment reminder job failed to start (non-fatal): ' + e.message);
      }

      // 5.md §11: review prompts (T+2h/T+1day after completion), every
      // 15 min. Same durability contract (per-milestone state on the doc,
      // atomic claim, skip-if-reviewed) so completed visits actually ask.
      try {
        const { startReviewPrompts } = await import('./jobs/reviewPrompt.job.js');
        startReviewPrompts(process.env.REVIEW_PROMPT_CRON || '*/15 * * * *');
      } catch (e) {
        logger.warn('review prompt job failed to start (non-fatal): ' + e.message);
      }

      // PAY-M-03: payout-vs-settlement reconciliation (daily, 03:00 — offset
      // from the 02:00 wallet job). Mismatch = audit + superadmin alert.
      try {
        const { startPayoutReconcile } = await import('./jobs/payoutReconcile.job.js');
        startPayoutReconcile(process.env.PAYOUT_RECON_CRON || '0 3 * * *');
      } catch (e) {
        logger.warn('payout reconcile job failed to start (non-fatal): ' + e.message);
      }

      // 2.md 5 / 8.md 2 / 8.md 14: document expiry (60/30/7-day reminders,
      // grace-suspension of the listing, ops alert on expiry). Daily, 06:00 —
      // offset from the 02:00 wallet and 03:00 payout jobs.
      try {
        const { startDocumentExpiry } = await import('./jobs/documentExpiry.job.js');
        startDocumentExpiry(process.env.DOC_EXPIRY_CRON || '0 6 * * *');
      } catch (e) {
        logger.warn('document expiry job failed to start (non-fatal): ' + e.message);
      }

      // T7: vendor KYC expiry sweep (Expired → PO block + audit; 30-day
      // advance alert to procurement). Daily 06:30, after documentExpiry.
      try {
        const { startVendorKycExpiry } = await import('./jobs/vendorKycExpiry.job.js');
        startVendorKycExpiry(process.env.VENDOR_KYC_EXPIRY_CRON || '30 6 * * *');
      } catch (e) {
        logger.warn('vendor KYC expiry job failed to start (non-fatal): ' + e.message);
      }

      // Join drafts: idle 30 days → expired (applicant notified); expired 30
      // more days → payload + uploaded documents purged, row kept for audit
      // (platform-expansion-plan.md:189). Daily 07:00, after the sweeps above.
      try {
        const { startJoinDraftExpiry } = await import('./jobs/joinDraftExpiry.job.js');
        startJoinDraftExpiry(process.env.JOIN_DRAFT_EXPIRY_CRON || '0 7 * * *');
      } catch (e) {
        logger.warn('join draft expiry job failed to start (non-fatal): ' + e.message);
      }

      // 5.md 15: location data minimal retention - null precise pickup/drop
      // coordinates for completed/cancelled rides older than the retention
      // window (default 7 days). Daily 04:00 UTC.
      try {
        const { startRideLocationPurge } = await import('./jobs/locationPurge.job.js');
        startRideLocationPurge(process.env.RIDE_LOCATION_PURGE_CRON || '0 4 * * *');
      } catch (e) {
        logger.warn('ride location purge job failed to start (non-fatal): ' + e.message);
      }
    } catch (e) {
      logger.error('⚠️ Failed to sync indexes, seed demo users, or start outbox poller: ' + e.message);
    }
  });

  mongoose.connection.on('error', (err) => {
    logger.error('❌ Mongoose connection error: ' + err);
  });

  mongoose.connection.on('disconnected', () => {
    logger.warn('⚠️ Mongoose disconnected');
  });

  // Graceful shutdown
  process.on('SIGINT', async () => {
    try {
      const { stopInstantDispatchRetryRecovery } = await import('./services/instantDispatchService.js');
      stopInstantDispatchRetryRecovery(instantDispatchRetryTimer);
    } catch {}
    try {
      const { stopOutboxPoller } = await import('./services/outboxPollerService.js');
      stopOutboxPoller();
    } catch {}
    try {
      const { stopWorkers } = await import('./workers/index.js');
      await stopWorkers();
      const { closeQueues } = await import('./lib/queues.js');
      await closeQueues();
    } catch {}
    await mongoose.connection.close();
    logger.info('📦 MongoDB connection closed');
    process.exit(0);
  });
}

export default app;

/**
 * Join draft expiry + purge (docs/platform-expansion-plan.md:189 —
 * "drafts expire 30 days"; 2.md join flow, data minimisation).
 *
 *   every day:  drafts idle for 30 days  ->  status 'expired' (once), applicant
 *                                           notified in-app (once), audit row
 *   every day:  expired for 30 more days ->  payload + uploaded documents are
 *                                           purged (row survives for audit)
 *
 * Design, mirroring `documentExpiry.job.js` on purpose:
 *
 *  1. DURABLE — the clock lives on the ProviderApplication row (`updatedAt`
 *     for the draft's last touch, `purgedAt` as the purge claim), not in
 *     process memory, so a missed tick is recovered by the next run.
 *  2. EXPIRE ONCE / PURGE ONCE — both transitions are atomic conditional
 *     updates (`status: 'draft'` / `purgedAt: null`), so two replicas or two
 *     overlapping runs cannot produce a second notification or a second audit
 *     row, and a draft the applicant touched between the scan and the claim
 *     (updatedAt past the cutoff) is never expired out from under them.
 *  3. PURGE IS ORDERED FOR CRASH-SAFETY — scrub the payload, unlink the local
 *     files, delete the document rows, and only then stamp `purgedAt`. A crash
 *     anywhere in between re-runs the idempotent steps next tick; an unlink
 *     that fails for a reason other than ENOENT leaves `purgedAt` unset so the
 *     row retries tomorrow instead of silently keeping orphaned bytes.
 *
 * Only `status: 'draft'` expires — submitted/review lanes are the reviewer's
 * to decide, and `expired` already refuses edit/submit in routes/join.js
 * (EDITABLE_STATUSES / SUBMITTABLE_STATUSES), so the applicant's next move is
 * a fresh application (POST /join), which has always been allowed.
 */
import { schedule } from 'node-cron';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import ProviderApplication from '../models/ProviderApplication.js';
import ProviderDocument from '../models/ProviderDocument.js';
import logger from '../config/logger.js';
import { auditLog } from '../middleware/audit.js';
import { createNotification } from '../services/notificationService.js';
import { APPLICATION_DOCUMENTS_DIR } from '../services/applicationDocumentStore.js';

export const DAY_MS = 24 * 60 * 60 * 1000;
export const MIN_MS = 60 * 1000;

/** The spec number: "drafts expire 30 days" of inactivity. */
export const DEFAULT_DRAFT_TTL_DAYS = 30;
/** Extra days after expiry before the payload + documents are purged. */
export const DEFAULT_PURGE_DAYS = 30;
/** Bound on rows touched per stage per run; the next tick picks up the rest. */
export const BATCH_LIMIT = 500;

/** Configurable draft TTL (days of inactivity before `expired`). */
export function configuredDraftTtlDays(env = process.env) {
  const raw = Number.parseInt(String(env.JOIN_DRAFT_TTL_DAYS ?? ''), 10);
  return Number.isFinite(raw) && raw >= 0 ? raw : DEFAULT_DRAFT_TTL_DAYS;
}

/** Configurable purge window (days after expiry before payload/documents go). */
export function configuredPurgeDays(env = process.env) {
  const raw = Number.parseInt(String(env.JOIN_DRAFT_PURGE_DAYS ?? ''), 10);
  return Number.isFinite(raw) && raw >= 0 ? raw : DEFAULT_PURGE_DAYS;
}

/**
 * One scan. Exported with an injectable clock so tests never depend on wall
 * time.
 * @returns {Promise<{expired:number,notified:number,purged:number,
 *                    expiredIds:string[],purgedIds:string[],
 *                    documentsDeleted:number,filesDeleted:number,purgeFailed:number}>}
 */
export async function runJoinDraftExpiryOnce(now = new Date()) {
  const ttlDays = configuredDraftTtlDays();
  const purgeDays = configuredPurgeDays();
  const report = {
    expired: 0, notified: 0, purged: 0,
    expiredIds: [], purgedIds: [],
    documentsDeleted: 0, filesDeleted: 0, purgeFailed: 0,
  };

  // ── Stage 1: expire idle drafts ───────────────────────────────────────────
  const draftCutoff = new Date(now.getTime() - ttlDays * DAY_MS);
  const idle = await ProviderApplication.find({ status: 'draft', updatedAt: { $lt: draftCutoff } })
    .select('_id applicationId applicantUserId typeKey updatedAt')
    .limit(BATCH_LIMIT)
    .lean();

  for (const app of idle) {
    // Re-assert the whole predicate atomically: a draft autosaved between the
    // scan and this claim (updatedAt now past the cutoff) must survive.
    const res = await ProviderApplication.updateOne(
      { _id: app._id, status: 'draft', updatedAt: { $lt: draftCutoff } },
      { $set: { status: 'expired', updatedAt: now } },
    );
    if (!res || res.modifiedCount !== 1) continue;

    report.expired += 1;
    report.expiredIds.push(String(app._id));

    if (app.applicantUserId) {
      try {
        const { notification, reason } = await createNotification({
          userId: String(app.applicantUserId),
          type: 'system',
          priority: 'normal',
          title: 'Application draft expired',
          message: `Your FindMedi application draft expired after ${ttlDays} days of inactivity. Start a new application to continue - drafts keep no data past expiry.`,
          dedupKey: `join-draft-expired:${app._id}`,
          details: { applicationId: app.applicationId || String(app._id), typeKey: app.typeKey, ttlDays },
          actor: 'joinDraftExpiryJob',
        });
        if (notification || reason === 'duplicate') report.notified += 1;
      } catch (err) {
        logger.warn(`joinDraftExpiry notify failed app=${app._id}: ${err.message}`);
      }
    }
  }

  if (report.expired > 0) {
    await auditLog('join_draft.expired', 'system', {
      at: now,
      ttlDays,
      count: report.expired,
      applicationIds: report.expiredIds.slice(0, 50),
    });
  }

  // ── Stage 2: purge expired applications (payload + uploaded documents) ────
  const purgeCutoff = new Date(now.getTime() - purgeDays * DAY_MS);
  const ripe = await ProviderApplication.find({
    status: 'expired',
    purgedAt: null,
    updatedAt: { $lt: purgeCutoff },
  })
    .select('_id applicationId applicantUserId updatedAt')
    .limit(BATCH_LIMIT)
    .lean();

  for (const app of ripe) {
    // 1. Read the document rows first: their file keys are the only way to
    //    find the bytes, so they must outlive the scrub below.
    const docs = await ProviderDocument.find({ applicationId: app._id })
      .select('fileRef.storage fileRef.key')
      .lean();

    // 2. Scrub the wizard payload. Idempotent; a crash after this simply
    //    re-runs steps 2-5 on the next tick (purgedAt is still null). The
    //    blind indexes go too (data minimisation) — they are HMACs of the
    //    encrypted tax fields that just left.
    await ProviderApplication.updateOne(
      { _id: app._id, status: 'expired', purgedAt: null },
      {
        $set: {
          'draft.stepData': {},
          'phiIndexes.pan': null,
          'phiIndexes.gstin': null,
          'phiIndexes.registration_number': null,
        },
      },
    );

    // 3. Unlink local bytes. Anything but ENOENT aborts this row so it stays a
    //    candidate for tomorrow - the rows still hold the keys needed to retry.
    let failed = 0;
    for (const doc of docs) {
      const ref = doc.fileRef || {};
      if (ref.storage !== 'local' || !ref.key) continue;
      try {
        // basename(): a key is a stored filename, never a path.
        await fs.unlink(path.join(APPLICATION_DOCUMENTS_DIR, path.basename(String(ref.key))));
        report.filesDeleted += 1;
      } catch (err) {
        if (err.code !== 'ENOENT') {
          failed += 1;
          logger.warn(`joinDraftExpiry unlink failed app=${app._id} key=${ref.key}: ${err.message}`);
        }
      }
    }
    if (failed > 0) {
      report.purgeFailed += 1;
      continue;
    }

    // 4. Drop the document rows, then 5. claim the purge. Both are conditional
    //    on purgedAt still being null, so a losing replica counts nothing.
    await ProviderDocument.deleteMany({ applicationId: app._id });
    const claimed = await ProviderApplication.updateOne(
      { _id: app._id, status: 'expired', purgedAt: null },
      { $set: { purgedAt: now } },
    );
    if (!claimed || claimed.modifiedCount !== 1) continue;

    report.purged += 1;
    report.purgedIds.push(String(app._id));
    report.documentsDeleted += docs.length;
  }

  if (report.purged > 0) {
    await auditLog('join_draft.purged', 'system', {
      at: now,
      purgeDays,
      count: report.purged,
      applicationIds: report.purgedIds.slice(0, 50),
      documentsDeleted: report.documentsDeleted,
      filesDeleted: report.filesDeleted,
    });
  }

  if (report.expired > 0 || report.purged > 0 || report.purgeFailed > 0) {
    logger.info('joinDraftExpiry run', {
      expired: report.expired,
      notified: report.notified,
      purged: report.purged,
      documentsDeleted: report.documentsDeleted,
      filesDeleted: report.filesDeleted,
      purgeFailed: report.purgeFailed,
    });
  }
  return report;
}

/**
 * Cron entry point. Daily by default (07:00 — after documentExpiry at 06:00
 * and the vendor KYC sweep at 06:30); the cutoff windows make the cadence a
 * recovery mechanism rather than a correctness dependency.
 */
export function startJoinDraftExpiry(cronExpression = process.env.JOIN_DRAFT_EXPIRY_CRON || '0 7 * * *') {
  logger.info(`Scheduling join draft expiry sweep: ${cronExpression}`);
  let timer;
  try {
    timer = schedule(cronExpression, () => {
      runJoinDraftExpiryOnce().catch((err) => logger.warn(`joinDraftExpiry run failed: ${err.message}`));
    });
  } catch {
    timer = setInterval(() => {
      runJoinDraftExpiryOnce().catch(() => {});
    }, 24 * 60 * MIN_MS);
  }
  return timer;
}

/**
 * Data-lake offload (Spec 16): keeps the MongoDB working set lean by
 * archiving completed rides older than LAKE_OFFLOAD_DAYS to the lake
 * manifest (MinIO/S3 when LAKE_S3_ENDPOINT is set, else local JSONL
 * manifest under ./data-lake-out/). Continuous, fail-soft, idempotent
 * (per-trip manifest marker). DeltaStreamer (data-platform/hudi/) owns the
 * parquet/MoR path; this job owns the Mongo→lake handoff record.
 */
import fs from 'node:fs';
import path from 'node:path';
import logger from '../config/logger.js';

const OFFLOAD_DAYS = Number(process.env.LAKE_OFFLOAD_DAYS || 90);
const MANIFEST_DIR = process.env.LAKE_MANIFEST_DIR || path.resolve(process.cwd(), 'data-lake-out');

export function offloadCutoff() {
  return new Date(Date.now() - OFFLOAD_DAYS * 86400 * 1000);
}

export async function runLakeOffloadOnce() {
  try {
    const mongoose = (await import('mongoose')).default;
    if (mongoose.connection.readyState !== 1) return { archived: 0, skipped: 'db_unavailable' };
    const { default: RideBooking } = await import('../models/RideBooking.js');
    const cutoff = offloadCutoff();
    const batch = await RideBooking.find({
      status: { $in: ['completed', 'cancelled_by_user', 'cancelled_by_rider'] },
      updatedAt: { $lt: cutoff },
      $or: [{ lakeArchivedAt: null }, { lakeArchivedAt: { $exists: false } }],
    })
      .sort({ updatedAt: 1 })
      .limit(500)
      .lean();
    if (!batch.length) return { archived: 0 };
    fs.mkdirSync(MANIFEST_DIR, { recursive: true });
    const day = new Date().toISOString().slice(0, 10);
    const manifest = path.join(MANIFEST_DIR, `date_partition=${day}.jsonl`);
    const lines = batch.map((r) =>
      JSON.stringify({
        trip_id: String(r._id),
        provider_id: String(r.driverId || r.providerId || ''),
        vertical: 'RIDER',
        h3_res8: r?.pickup?.h3_res8 || r?.h3Cell || '',
        fare: r?.fare?.total ?? 0,
        start_time: r?.createdAt ? new Date(r.createdAt).getTime() : null,
        end_time: r?.updatedAt ? new Date(r.updatedAt).getTime() : null,
        date_partition: day,
      })
    );
    fs.appendFileSync(manifest, lines.join('\n') + '\n');
    // TODO(lake): when LAKE_S3_ENDPOINT is set, PUT manifest to
    // s3://findmedi-data-lake/hudi_ride_telemetry_historical/ via MinIO client.
    await RideBooking.updateMany(
      { _id: { $in: batch.map((r) => r._id) } },
      { $set: { lakeArchivedAt: new Date() } }
    );
    return { archived: batch.length, manifest };
  } catch (err) {
    logger.error(`lakeOffload error: ${err.message}`);
    return { archived: 0, error: err.message };
  }
}

export function startLakeOffload(intervalMs = 6 * 3600 * 1000) {
  const timer = setInterval(() => {
    runLakeOffloadOnce().catch(() => {});
  }, intervalMs);
  if (typeof timer.unref === 'function') timer.unref();
  return timer;
}

/**
 * DP-M-04: erasure propagation for lake copies.
 *
 * The offload manifest above is the lake's Mongo handoff record - trip rows
 * keyed by trip_id, written per date partition. A `user.deleted` tombstone
 * (deletionService -> outbox -> consumer) must remove the rows that belong to
 * the erased subject: their rides as a RIDER (userId) and as a DRIVER
 * (driverId/providerId - an erased provider leaves GPS-era traces behind too).
 *
 * Manifest lines carry no user id, so the join happens through Mongo: the
 * subject's trip ids first, then a line-level rewrite of every partition that
 * mentions one. Malformed lines are KEPT (a line we cannot parse is not a
 * line we can claim to have purged - dropping it silently would turn a data
 * tool into a data loss). Rewrite is tmp+rename so a crash mid-purge cannot
 * truncate a partition.
 *
 * Post-ingestion rows (already compacted into Hudi by DeltaStreamer) are owned
 * by data-platform/hudi/ - this backend only ever owned the manifest handoff.
 */
export async function purgeUserFromLakeManifests(userId) {
  try {
    const mongoose = (await import('mongoose')).default;
    if (mongoose.connection.readyState !== 1) return { purged: 0, skipped: 'db_unavailable' };
    const { default: RideBooking } = await import('../models/RideBooking.js');
    const id = String(userId);
    const trips = await RideBooking.find({
      $or: [{ userId: id }, { driverId: id }, { providerId: id }],
    })
      .select('_id')
      .lean();
    const tripIds = new Set(trips.map((r) => String(r._id)));
    if (!tripIds.size) return { purged: 0, trips: 0 };
    if (!fs.existsSync(MANIFEST_DIR)) return { purged: 0, trips: tripIds.size };

    let purged = 0;
    let partitions = 0;
    for (const name of fs.readdirSync(MANIFEST_DIR)) {
      if (!name.endsWith('.jsonl')) continue;
      const file = path.join(MANIFEST_DIR, name);
      const lines = fs.readFileSync(file, 'utf8').split('\n');
      const kept = lines.filter((line) => {
        if (!line.trim()) return true;
        try {
          return !tripIds.has(String(JSON.parse(line).trip_id));
        } catch {
          return true;
        }
      });
      if (kept.length === lines.length) continue;
      purged += lines.length - kept.length;
      partitions += 1;
      const tmp = `${file}.purging`;
      fs.writeFileSync(tmp, kept.join('\n'));
      fs.renameSync(tmp, file);
    }
    return { purged, partitions, trips: tripIds.size };
  } catch (err) {
    logger.error(`lake purge error for user ${userId}: ${err.message}`);
    return { purged: 0, error: err.message };
  }
}

/**
 * File 17 §17.4: AI gateway. PHI redaction first, provider call second,
 * invocation log always. Default provider is an honest local stub — no
 * silent fake-AI: stub responses are labeled `provider: 'stub'` in the log.
 * Kill switch: SystemSetting `ai.enabled=false` blocks everything.
 */
import AiInvocation from '../models/AiInvocation.js';
import logger from '../config/logger.js';

const EMAIL_RX = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;
const PHONE_RX = /(\+?91[\s-]?)?[6-9]\d{4}[\s-]?\d{5}/g;
const NAME_HINT_RX = /(patient|name)\s*[:=]\s*([A-Za-z][A-Za-z .]{2,40})/gi;

export function redactPhi(text) {
  if (!text) return { text: '', redacted: false };
  let out = String(text);
  let redacted = false;
  for (const rx of [EMAIL_RX, PHONE_RX]) {
    if (rx.test(out)) { redacted = true; out = out.replace(rx, '[REDACTED]'); rx.lastIndex = 0; }
  }
  if (NAME_HINT_RX.test(out)) { redacted = true; out = out.replace(NAME_HINT_RX, '$1: [REDACTED]'); }
  return { text: out, redacted };
}

