  return domain !== '' && DISPOSABLE_EMAIL_DOMAINS.has(domain);
}

/** Normalized PAN/GSTIN comparison: uppercase, alphanumeric only, right shape. */
export function normalizeTaxId(raw, length) {
  const value = String(raw ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  return value.length === length ? value : '';
}

/** Phone heuristic. A number that is not a plausible mobile/landline shape is
 *  flagged for a human VOIP/genuinity look rather than silently accepted. */
export function looksVoip(phone) {
  const digits = String(phone ?? '').replace(/\D/g, '');
  if (digits.length < 10 || digits.length > 13) return true;
  if (/^(\d)\1+$/.test(digits)) return true; // 9999999999, 0000000000...
  return false;
}

/** Text out of a wizard field: strings pass through, `{value,label}` wrappers
 *  unwrap, everything else (arrays/numbers) is stringified only when scalar. */
function pickText(value) {
  if (typeof value === 'string') return capSearch(value, 160);
  if (typeof value === 'number') return String(value);
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    for (const k of ['value', 'text', 'label', 'name']) {
      if (typeof value[k] === 'string') return capSearch(value[k], 160);
    }
  }
  return '';
}

/** First non-empty value for each key across every wizard step. */
function collectValues(stepData, keys) {
  const out = {};
  for (const data of Object.values(stepData ?? {})) {
    if (!data || typeof data !== 'object' || Array.isArray(data)) continue;
    for (const key of keys) {
      if (out[key] !== undefined) continue;
      const v = data[key];
      if (v !== undefined && v !== null && v !== '') out[key] = v;
    }
  }
  return out;
}

// ── pin-location: PIN circle (first 2 digits) → states it may legitimately
// carry. City-level matching would need an offline PIN→city dataset we do not
// ship; the circle→state binding is public, tiny and locally checkable, so the
// check compares STATE. Fuzzy borders (Goa under 403, Uttarakhand under 24/25,
// NE under 90–94) are widened on purpose — the check only fires when the
// address names a state that is NOT in the circle at all. Prefixes we cannot
// vouch for (78/79 NE interiors, Army 96–99) are simply absent → skip.
const PIN_CIRCLES = (() => {
  const map = {};
  const put = (prefixes, states) => { for (const p of prefixes) map[p] = states; };
  put(['11'], ['Delhi']);
  put(['12', '13'], ['Haryana']);
  put(['14', '15', '16'], ['Punjab', 'Chandigarh']);
  put(['17'], ['Himachal Pradesh']);
  put(['18', '19'], ['Jammu and Kashmir', 'Jammu & Kashmir', 'Ladakh']);
  put(['20', '21', '22', '23', '24', '25', '26', '27', '28'], ['Uttar Pradesh', 'Uttarakhand', 'Uttaranchal']);
  put(['30', '31', '32', '33', '34'], ['Rajasthan']);
  put(['36', '37', '38', '39'], ['Gujarat', 'Dadra and Nagar Haveli', 'Daman and Diu']);
  put(['40'], ['Maharashtra', 'Goa']);
  put(['41', '42', '43', '44'], ['Maharashtra']);
  put(['45', '46', '47', '48'], ['Madhya Pradesh']);
  put(['49'], ['Chhattisgarh']);
  put(['50', '51'], ['Telangana', 'Andhra Pradesh']);
  put(['52', '53'], ['Andhra Pradesh', 'Telangana']);
  put(['56', '57', '58', '59'], ['Karnataka']);
  put(['60', '61', '62', '63', '64'], ['Tamil Nadu', 'Puducherry', 'Pondicherry']);
  put(['67', '68', '69'], ['Kerala', 'Lakshadweep']);
  put(['70', '71', '72', '73', '74'], ['West Bengal', 'Andaman and Nicobar Islands']);
  put(['75', '76', '77'], ['Odisha', 'Orissa', 'West Bengal']);
  put(['80', '81', '82', '83', '84', '85'], ['Bihar', 'Jharkhand']);
  put(['86'], ['Jharkhand', 'Bihar']);
  put(['90', '91', '92', '93', '94'], ['Manipur', 'Meghalaya', 'Mizoram', 'Nagaland', 'Tripura', 'Arunachal Pradesh']);
  return map;
})();

/** Every state spelling the circles accept, longest first so "Andaman and
 *  Nicobar Islands" is found before any shorter substring could match. */
const STATE_SPELLINGS = (() => {
  const set = new Set();
  for (const states of Object.values(PIN_CIRCLES)) for (const s of states) set.add(s);
  return [...set].sort((a, b) => b.length - a.length);
})();

/** First canonical state name that appears in free text (case-insensitive). */
export function findStateName(text) {
  const hay = String(text ?? '');
  if (!hay) return '';
  for (const name of STATE_SPELLINGS) {
    if (new RegExp(`\\b${escapeRegex(name)}\\b`, 'i').test(hay)) return name;
  }
  return '';
}

/** City + state + pincode out of whatever shape the location step was saved
 *  in. The wizard stores the address as ONE free string ("…, City, State
 *  110001"), so state detection runs over the text; object shapes may carry
 *  discrete keys (and an `address` string inside them). */
function extractPlace(stepData) {
  const raw = collectValues(stepData, ['address'])['address'];
  let city = '';
  let state = '';
  let blob = '';
  if (typeof raw === 'string') {
    blob = raw;
    state = findStateName(raw);
  } else if (raw && typeof raw === 'object') {
    city = pickText(raw.city || raw.town || raw.district || '');
    state = pickText(raw.state || '');
    if (typeof raw.address === 'string') state = state || findStateName(raw.address);
    blob = JSON.stringify(raw);
  }
  const pin = blob.match(/\b[1-9][0-9]{5}\b/);
  return { city: city.toLowerCase(), state, pincode: pin ? pin[0] : '' };
}

/** Truncated SHA-256 of the submit IP: the ip_cluster check needs equality
 *  only, and the raw address already lives in the audit row — so the long-lived
 *  application document keeps no new PII. Empty input → null (check skips). */
export function hashIp(ip) {
  const raw = String(ip ?? '').trim();
  if (!raw) return null;
  return createHash('sha256').update(raw).digest('hex').slice(0, 32);
}

const check = (key, status, severity, note) => ({ key, status, severity, note: String(note ?? '').slice(0, 500) });

const OWN_TAX = (rows, field, value) => rows.filter((row) => String(row[field] ?? '') === value);

// autoChecks is a stored document the queue renders — a check note must not
// re-print a tax ID that field encryption is hiding elsewhere on the row.
// First 5 + stars + last 1 keeps it recognisable against the document.
const maskTax = (v) => {
  const s = String(v ?? '');
  if (s.length <= 6) return '****';
  return `${s.slice(0, 5)}${'*'.repeat(s.length - 6)}${s.slice(-1)}`;
};

/**
 * Run the whole screen. Returns the object stored as `application.autoChecks`:
 *   { verdict, runAt, forceTwoPerson, checks[] }
 * Never throws.
 */
export async function runAutoChecks({ application } = {}) {
  const runAt = new Date();
  const checks = [];
  // P2-9: draft tax/bank fields are encrypted at rest (utils/phiFields.js);
  // this copy is decrypted IN MEMORY for the screen and never saved. Legacy
  // plaintext rows pass through decrypt untouched, so both generations run.
  const stepData = decryptJoinDraftStep(application?.draft?.stepData ?? {});
  const applicantId = String(application?.applicantUserId ?? '');
  const selfId = String(application?._id ?? '');

  const dupFilter = { _id: { $ne: selfId }, status: { $in: DUP_APP_STATUSES } };
  const ids = collectValues(stepData, [
    'pan', 'gstin', 'display_name', 'legal_name', 'account_holder', 'account_number', 'ifsc',
    'registration_number',
  ]);
  const pan = normalizeTaxId(ids.pan, 10);
  const gstin = normalizeTaxId(ids.gstin, 15);
  const name = pickText(ids.display_name || ids.legal_name);
  const place = extractPlace(stepData);

  // ── duplicate PAN / GSTIN (one query serves both) ────────────────────────
  // Encrypted rows are matched through their blind indexes (application
  // .phiIndexes, keyed HMAC — see utils/phiFields.joinPhiIndex), legacy
  // plaintext rows through the value itself: $or covers both generations.
  const taxClauses = [];
  const panIdx = pan ? joinPhiIndex('pan', pan) : null;
  const gstinIdx = gstin ? joinPhiIndex('gstin', gstin) : null;
  if (pan) {
    taxClauses.push({ 'draft.stepData.pan': pan });
    if (panIdx) taxClauses.push({ 'phiIndexes.pan': panIdx });
  }
  if (gstin) {
    taxClauses.push({ 'draft.stepData.gstin': gstin });
    if (gstinIdx) taxClauses.push({ 'phiIndexes.gstin': gstinIdx });
  }
  if (taxClauses.length > 0) {
    try {
      const rows = await ProviderApplication
        .find({ $and: [dupFilter, { $or: taxClauses }] })
        .select('applicationId status applicantUserId draft.stepData phiIndexes')
        .limit(10)
        .lean();
      const norm = (v) => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');

      if (pan) {
        const hits = rows.filter((row) => norm(row.draft?.stepData?.pan) === pan || row.phiIndexes?.pan === panIdx);
        const foreign = hits.filter((row) => String(row.applicantUserId) !== applicantId);
        checks.push(foreign.length > 0
          ? check('duplicate_pan', 'flag', 'conflict', `PAN already used by ${foreign[0].applicationId} (different applicant)`)
          : check('duplicate_pan', 'pass', 'info', hits.length > 0 ? 'PAN matches your own application' : 'PAN not seen before'));
      } else {
        checks.push(check('duplicate_pan', 'skip', 'info', 'no PAN supplied'));
      }

      if (gstin) {
        const hits = rows.filter((row) => norm(row.draft?.stepData?.gstin) === gstin || row.phiIndexes?.gstin === gstinIdx);
        const foreign = hits.filter((row) => String(row.applicantUserId) !== applicantId);
        checks.push(foreign.length > 0
          ? check('duplicate_gstin', 'flag', 'conflict', `GSTIN already used by ${foreign[0].applicationId} (different applicant)`)
          : check('duplicate_gstin', 'pass', 'info', hits.length > 0 ? 'GSTIN matches your own application' : 'GSTIN not seen before'));
      } else {
        checks.push(check('duplicate_gstin', 'skip', 'info', 'no GSTIN supplied'));
      }
    } catch (err) {
      checks.push(check('duplicate_pan', 'error', 'review', `tax duplicate scan failed: ${err.message}`));
      checks.push(check('duplicate_gstin', 'error', 'review', 'tax duplicate scan failed'));
    }
  } else {
    checks.push(check('duplicate_pan', 'skip', 'info', 'no PAN supplied'));
    checks.push(check('duplicate_gstin', 'skip', 'info', 'no GSTIN supplied'));
  }

  // ── GSTIN integrity & PAN binding (reg ↔ identity) ───────────────────────
  // Review severity on purpose: a company's GSTIN legitimately carries the
  // CORPORATE PAN while the applicant types their personal one — that is a
  // document to re-read, not a duplicate identity to force two-person over.
  if (gstin) {
    const shape = validateGstin(ids.gstin);
    if (!shape.valid) {
      checks.push(check('gstin_pan_match', 'flag', 'review',
        `GSTIN fails validation (${shape.reason}) — likely a typo or a fabricated number`));
    } else if (pan && shape.gstin.slice(2, 12) !== pan) {
      checks.push(check('gstin_pan_match', 'flag', 'review',
        `GSTIN is issued against PAN ${maskTax(shape.gstin.slice(2, 12))} but ${maskTax(pan)} was declared — verify whose GSTIN this is`));
    } else {
      checks.push(check('gstin_pan_match', 'pass', 'info',
        pan ? 'GSTIN checksum valid and matches the declared PAN' : 'GSTIN checksum valid (no PAN to compare)'));
    }
  } else {
    checks.push(check('gstin_pan_match', 'skip', 'info', 'no GSTIN supplied'));
  }

  // ── duplicate registration number, with the name in view ─────────────────
  // Query-then-normalize (same limitation as the tax scan: a punctuation
  // variant of the stored value will not be fetched), then the NAME decides
  // the wording — same number under a different name is the interesting shape.
  const regNorm = String(ids.registration_number ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  if (regNorm.length >= 4) {
    const regIdx = joinPhiIndex('registration_number', regNorm);
    try {
      const rows = await ProviderApplication
        .find({
          $and: [dupFilter,
            { $or: [
              { 'draft.stepData.registration_number': new RegExp(escapeRegex(String(ids.registration_number).trim()), 'i') },
              // encrypted rows: the keyed blind index, never the ciphertext
              ...(regIdx ? [{ 'phiIndexes.registration_number': regIdx }] : []),
            ] }],
        })
        .select('applicationId applicantUserId draft.stepData phiIndexes')
        .limit(10)
        .lean();
      const normReg = (v) => String(v ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
      const hits = rows.filter((row) => normReg(row.draft?.stepData?.registration_number) === regNorm
        || row.phiIndexes?.registration_number === regIdx);
      const foreign = hits.filter((row) => String(row.applicantUserId) !== applicantId);
      if (foreign.length > 0) {
        const ref = foreign[0].applicationId || '';
        const theirName = pickText(foreign[0].draft?.stepData?.display_name || foreign[0].draft?.stepData?.legal_name);
        const nameDiffers = Boolean(name && theirName && theirName.toLowerCase() !== name.toLowerCase());
        checks.push(check('duplicate_reg', 'flag', 'review',
          `registration number already on ${ref} (different applicant${nameDiffers ? ', under a different name' : ''})`));
      } else if (hits.length > 0) {
        checks.push(check('duplicate_reg', 'pass', 'info', 'registration number matches your own application'));
      } else {
        checks.push(check('duplicate_reg', 'pass', 'info', 'registration number not seen before'));
      }
    } catch (err) {
      checks.push(check('duplicate_reg', 'error', 'review', `registration duplicate scan failed: ${err.message}`));
    }
  } else {
    checks.push(check('duplicate_reg', 'skip', 'info', 'no registration number supplied'));
  }

  // ── submit-network cluster (hash equality only; no raw IP on the row) ────
  // set by routes/join.js at submit via hashIp(). A shared office/NAT is
  // completely normal, so this can only ever reach `review` — it is a prompt
  // to weigh the rest of the profile, never a conflict on its own.
  const ipHash = String(application?.submitIpHash ?? '');
  if (ipHash) {
    try {
      const rows = await ProviderApplication
        .find({ $and: [dupFilter, { submitIpHash: ipHash }] })
        .select('applicationId applicantUserId')
        .limit(10)
        .lean();
      const foreign = rows.filter((row) => String(row.applicantUserId) !== applicantId);
      if (foreign.length > 0) {
        checks.push(check('ip_cluster', 'flag', 'review',
          `${foreign.length} other in-flight application${foreign.length === 1 ? '' : 's'} from the same submit network (shared office/NAT is common — weigh the rest of the profile)`));
      } else {
        checks.push(check('ip_cluster', 'pass', 'info', 'no other in-flight application from this network'));
      }
    } catch (err) {
      checks.push(check('ip_cluster', 'error', 'review', `IP cluster scan failed: ${err.message}`));
    }
  } else {
    checks.push(check('ip_cluster', 'skip', 'info', 'no submit IP captured'));
  }

  // ── duplicate name (applications + live listings) ────────────────────────
  if (name) {
    try {
      const rx = safeSearchRegex(name);
      const [appRows, providers] = await Promise.all([
        ProviderApplication
          .find({ $and: [dupFilter, { $or: [{ 'draft.stepData.display_name': rx }, { 'draft.stepData.legal_name': rx }] }] })
          .select('applicationId status applicantUserId')
          .limit(5)
          .lean(),
        Provider
          .find({ name: rx, status: DUP_PROVIDER_STATUSES, ...(place.city ? { 'address.city': place.city } : {}) })
          .select('providerId name status ownerUserId address.city')
          .limit(5)
          .lean(),
      ]);
      const foreignApps = appRows.filter((row) => String(row.applicantUserId) !== applicantId);
      const foreignProviders = providers.filter((row) => String(row.ownerUserId ?? '') !== applicantId);
      if (foreignApps.length > 0 || foreignProviders.length > 0) {
        const ref = foreignApps[0]?.applicationId || foreignProviders[0]?.providerId || '';
        checks.push(check('duplicate_name', 'flag', 'review', `similar name already on platform (${ref})${place.city ? ` in ${place.city}` : ''}`));
      } else {
        checks.push(check('duplicate_name', 'pass', 'info', 'no similar listing found'));
      }
    } catch (err) {
      checks.push(check('duplicate_name', 'error', 'review', `name duplicate scan failed: ${err.message}`));
    }
  } else {
    checks.push(check('duplicate_name', 'skip', 'info', 'no business name supplied'));
  }

  // ── applicant contact hygiene ────────────────────────────────────────────
  let applicant;
  try {
    applicant = await User.findById(application?.applicantUserId).select('email phone').lean();
  } catch {
    applicant = null;
  }
  if (applicant?.email) {
    checks.push(isDisposableEmail(applicant.email)
      ? check('disposable_email', 'flag', 'review', `disposable inbox domain on ${capSearch(applicant.email, 80)}`)
      : check('disposable_email', 'pass', 'info', 'email domain accepted'));
  } else {
    checks.push(check('disposable_email', 'skip', 'info', 'no email on the applicant account'));
  }
  if (applicant?.phone) {
    checks.push(looksVoip(applicant.phone)
      ? check('voip_phone', 'flag', 'review', `phone "${capSearch(applicant.phone, 20)}" is outside the normal mobile pattern`)
      : check('voip_phone', 'pass', 'info', 'phone pattern accepted'));
  } else {
    checks.push(check('voip_phone', 'skip', 'info', 'no phone on the applicant account'));
  }

  // ── penny-drop name match (2.md 14 payout verification) ──────────────────
  if (ids.account_holder && ids.account_number) {
    try {
      const result = await verifyPennyDrop({
        ifsc: pickText(ids.ifsc),
        accountNumber: pickText(ids.account_number),
        accountHolder: pickText(ids.account_holder),
      });
      if (result.status === 'verified') {
        checks.push(check('payout_name_match', 'pass', 'info', `payout name verified (${result.mode})`));
      } else if (result.status === 'name_mismatch') {
        checks.push(check('payout_name_match', 'flag', 'conflict', `payout name mismatch: bank credited "${String(result.creditedName).slice(0, 60)}"`));
      } else if (result.status === 'unavailable') {
        checks.push(check('payout_name_match', 'flag', 'review', `penny-drop unavailable: ${result.note}`));
      } else {
        checks.push(check('payout_name_match', 'skip', 'info', result.note));
      }
    } catch (err) {
      checks.push(check('payout_name_match', 'error', 'review', `penny-drop failed: ${err.message}`));
    }
  } else {
    checks.push(check('payout_name_match', 'skip', 'info', 'no payout account supplied'));
  }

  // ── PIN circle vs stated state ───────────────────────────────────────────
  if (place.pincode && place.state) {
    const circle = PIN_CIRCLES[place.pincode.slice(0, 2)];
    if (!circle) {
      checks.push(check('pin_location_match', 'skip', 'info', `PIN ${place.pincode} is outside the mapped postal circles`));
    } else {
      const stated = place.state.toLowerCase();
      const agrees = circle.some((s) => {
        const lc = s.toLowerCase();
        return stated.includes(lc) || lc.includes(stated);
      });
      checks.push(agrees
        ? check('pin_location_match', 'pass', 'info', `PIN ${place.pincode} and stated state "${place.state}" agree`)
        : check('pin_location_match', 'flag', 'review',
          `PIN ${place.pincode} belongs to ${circle.slice(0, 2).join(' / ')} but the address says "${place.state}" — verify the location`));
    }
  } else {
    checks.push(check('pin_location_match', 'skip', 'info', 'no PIN or state in the address'));
  }

  // ── verdict ──────────────────────────────────────────────────────────────
  const hasConflict = checks.some((c) => c.status === 'flag' && c.severity === 'conflict');
  const hasFlag = checks.some((c) => c.status === 'flag');
  const hasError = checks.some((c) => c.status === 'error');
  const verdict = hasConflict ? 'conflict' : hasFlag ? 'review' : hasError ? 'error' : 'clear';

  return {
    verdict,
    runAt,
    // A tax-identity or payout-name conflict forces the second approver, so a
    // duplicate identity can never be waved through by one reviewer.
    forceTwoPerson: verdict === 'conflict',
    checks,
  };
}

export { evaluateNameMatch };

/**
 * A5 — appointment lifecycle: the status state machine plus the cancellation
 * refund policy of 5.md §2.4, in one PURE module (no mongoose, no config).
 *
 * WHY A SEPARATE MODULE
 * Three copies of "what may move to what" existed: the model enum, the zod
 * schema (which even carried a `Rescheduled` value the model rejects at
 * runtime), and whatever each handler happened to write. The same drift
 * afflicted refunds — there was NO cancellation policy at all, so a cancel
 * three hours out silently kept the full fee while the spec's tier table
 * (>24 h full refund, 24–4 h partial, <4 h none-or-≤20 %) was unimplemented
 * and untestable.
 *
 * So the table lives here, the model takes its `enum` from it, the route
 * asserts before it writes, and the tier arithmetic is a pure function of
 * (start, now, actor, paid) that a unit test can pin at the boundaries.
 * Money moves through utils/money.js paise arithmetic — 0.1 + 0.2 must not
 * decide a refund.
 *
 * Provider-configurable percents (5.md §2.4 "provider-configurable within
 * platform limits") are accepted through `policy` and CLAMPED to
 * PLATFORM_CANCELLATION_POLICY; no route passes one yet, so the platform
 * defaults are what apply.
 */
import { assertTransition, canTransition } from './flowStates.js';
import { toPaise, fromPaise } from '../utils/money.js';
import crypto from 'node:crypto';

// ==============================================================================
// Status machine
// ==============================================================================

export const APPOINTMENT_STATUS = Object.freeze({
  PENDING: 'Pending',
  CONFIRMED: 'Confirmed',
  CANCELLED: 'Cancelled',
  COMPLETED: 'Completed',
  IN_QUEUE: 'In Queue',
  SERVING: 'Serving',
  MISSED: 'Missed',
});

/** The model enum is THIS list — one definition, no drifting copies. */
export const APPOINTMENT_STATUSES = Object.freeze(Object.values(APPOINTMENT_STATUS));

/**
 * The only legal moves. Anything absent is rejected with 409
 * ILLEGAL_STATE_TRANSITION (flowStates.assertTransition).
 *
 * Notes on the shape:
 *  - Pending -> Confirmed is the payment gate in routes/appointments.js and the
 *    auto-confirm in routes/billing.js; Pending -> Cancelled is checkout expiry.
 *  - Confirmed -> In Queue covers both checkin and transit-arrived.
 *  - Completed is terminal: "cancel a finished consult" is a refund dispute,
 *    not a status change.
 *  - Missed is terminal for the same reason: converting a no-show into a
 *    completion would erase the evidence the penalty decision rests on.
 *  - `Rescheduled` is deliberately ABSENT: it is not a stored state. The zod
 *    schema still accepts the legacy string so old clients get a structured
 *    409 explaining the move rather than a bare 400.
 */
export const APPOINTMENT_TRANSITIONS = Object.freeze({
  [APPOINTMENT_STATUS.PENDING]: [
    APPOINTMENT_STATUS.CONFIRMED,
    APPOINTMENT_STATUS.CANCELLED,
    APPOINTMENT_STATUS.MISSED,
  ],
  [APPOINTMENT_STATUS.CONFIRMED]: [
    APPOINTMENT_STATUS.CANCELLED,
    APPOINTMENT_STATUS.COMPLETED,
    APPOINTMENT_STATUS.IN_QUEUE,
    APPOINTMENT_STATUS.MISSED,
  ],
  [APPOINTMENT_STATUS.IN_QUEUE]: [
    APPOINTMENT_STATUS.SERVING,
    APPOINTMENT_STATUS.COMPLETED,
    APPOINTMENT_STATUS.CANCELLED,
    APPOINTMENT_STATUS.MISSED,
  ],
  [APPOINTMENT_STATUS.SERVING]: [
    APPOINTMENT_STATUS.COMPLETED,
    APPOINTMENT_STATUS.CANCELLED,
    APPOINTMENT_STATUS.MISSED,
    APPOINTMENT_STATUS.IN_QUEUE,
  ],
  [APPOINTMENT_STATUS.COMPLETED]: [],
  [APPOINTMENT_STATUS.MISSED]: [],
  [APPOINTMENT_STATUS.CANCELLED]: [],
});

/** Throws FlowTransitionError (409, code ILLEGAL_STATE_TRANSITION) on a bad move. */
export const assertAppointmentTransition = (from, to) =>
  assertTransition('appointment', APPOINTMENT_TRANSITIONS, from, to);

export const canAppointmentTransition = (from, to) =>
  canTransition(APPOINTMENT_TRANSITIONS, from, to);

// ==============================================================================
// Cancellation policy (5.md §2.4)
// ==============================================================================

export const CANCELLATION_TIER = Object.freeze({
  EARLY: 'early',       // more than 24 h before start
  MID: 'mid',           // 24 h to 4 h before start (inclusive both ends)
  LATE: 'late',         // less than 4 h before start
  NO_SHOW: 'no_show',   // the start has already passed
});

/**
 * Platform limits. Provider policy may pick any percent WITHIN the band; the
 * clamp is what keeps "configurable" from becoming "unlimited". The early band
 * is pinned at 100 — a platform that promises a full refund 24 h out cannot let
 * a provider configure that away.
 */
export const PLATFORM_CANCELLATION_POLICY = Object.freeze({
  [CANCELLATION_TIER.EARLY]: Object.freeze({ defaultRefundPercent: 100, minRefundPercent: 100, maxRefundPercent: 100 }),
  [CANCELLATION_TIER.MID]: Object.freeze({ defaultRefundPercent: 50, minRefundPercent: 0, maxRefundPercent: 100 }),
  [CANCELLATION_TIER.LATE]: Object.freeze({ defaultRefundPercent: 0, minRefundPercent: 0, maxRefundPercent: 20 }),
  [CANCELLATION_TIER.NO_SHOW]: Object.freeze({ defaultRefundPercent: 0, minRefundPercent: 0, maxRefundPercent: 20 }),
});

/**
 * Which band does this cancel fall in?
 *
 * An unusable start (null, garbage) is treated as LATE — the conservative
 * direction: a parse failure must never hand out the full refund by accident.
 */
export function cancellationTier(startAt, now = new Date()) {
  // null/undefined/'' must not fall through to `new Date(null)` — that is the
  // epoch, which would read as a no-show with 40 years on the clock.
  if (startAt === null || startAt === undefined || startAt === '') return CANCELLATION_TIER.LATE;
  const start = new Date(startAt).getTime();
  if (!Number.isFinite(start)) return CANCELLATION_TIER.LATE;
  const hoursLeft = (start - now.getTime()) / (60 * 60 * 1000);
  if (hoursLeft < 0) return CANCELLATION_TIER.NO_SHOW;
  if (hoursLeft > 24) return CANCELLATION_TIER.EARLY;
  if (hoursLeft >= 4) return CANCELLATION_TIER.MID;
  return CANCELLATION_TIER.LATE;
}

/**
 * Refund percent for (tier, actor). A PROVIDER cancel is always 100 % —
 * 5.md §2.4 gives the patient a full refund in every row of the provider
 * column; the apology credit / compensation / penalty the spec attaches to
 * those rows are separate ledger decisions and are not computed here.
 */
export function resolveRefundPercent({ tier, cancelledBy = 'patient', policy = {} } = {}) {
  if (cancelledBy === 'provider') return 100;
  const band = PLATFORM_CANCELLATION_POLICY[tier] || PLATFORM_CANCELLATION_POLICY[CANCELLATION_TIER.LATE];
  const requested = policy?.[`${tier}RefundPercent`];
  const wanted = (requested === undefined || requested === null || !Number.isFinite(Number(requested)))
    ? band.defaultRefundPercent
    : Number(requested);
  return Math.min(band.maxRefundPercent, Math.max(band.minRefundPercent, wanted));
}

/** Provider-side cancellation defaults. A provider policy may override these. */
export const DEFAULT_PROVIDER_CANCEL_POLICY = Object.freeze({
  providerCompensationPercent: 0,
  providerPenaltyPercent: 0,
});

const clampPercent = (value, fallback = 0) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.min(100, Math.max(0, n));
};

/** Provider cancellation compensation/penalty, clamped to 0..100. */
export function resolveProviderCancelPolicy(policy = {}) {
  const cfg = policy?.providerCancel || policy || {};
  return {
    providerCompensationPercent: clampPercent(
      cfg.providerCompensationPercent ?? DEFAULT_PROVIDER_CANCEL_POLICY.providerCompensationPercent,
    ),
    providerPenaltyPercent: clampPercent(
      cfg.providerPenaltyPercent ?? DEFAULT_PROVIDER_CANCEL_POLICY.providerPenaltyPercent,
    ),
  };
}

/**
 * Turn an appointment's stored policy snapshot into the flat policy shape
 * resolveRefundPercent expects. Reading the snapshot (not today's policy) is
 * what makes a later platform/provider rule change non-retroactive.
 */
export function policyFromSnapshot(snapshot) {
  const bands = snapshot?.refundBands;
  if (!bands || typeof bands !== 'object') return null;
  const policy = {};
  for (const [tier, band] of Object.entries(bands)) {
    const pct = Number(band?.defaultRefundPercent);
    if (Number.isFinite(pct)) policy[`${tier}RefundPercent`] = pct;
  }
  return Object.keys(policy).length ? policy : null;
}

/**
 * Split a refund across the original funding sources. Combined wallet+gateway
 * payments are refunded in the same proportion they were paid; a single-source
 * payment goes back where it came from. Rounded in paise, with the remainder on
 * the gateway side so the two parts always equal the refund exactly.
 */
export function allocateRefund({
  refundAmount = 0,
  paidAmount = 0,
  method = 'gateway',
  walletPaid,
  gatewayPaid,
} = {}) {
  const refundPaise = Math.round(toPaise(refundAmount));
  const paidPaise = Math.round(toPaise(paidAmount));
  const hasWallet = walletPaid !== undefined && walletPaid !== null;
  const hasGateway = gatewayPaid !== undefined && gatewayPaid !== null;
  let walletPaise = hasWallet ? Math.round(toPaise(walletPaid)) : 0;
  let gatewayPaise = hasGateway ? Math.round(toPaise(gatewayPaid)) : 0;
  if (!hasWallet && !hasGateway) {
    if (method === 'wallet') walletPaise = paidPaise;
    else gatewayPaise = paidPaise;
  }
  walletPaise = Math.max(0, walletPaise);
  gatewayPaise = Math.max(0, gatewayPaise);
  const fundedPaise = walletPaise + gatewayPaise;
  if (refundPaise <= 0 || fundedPaise <= 0) {
    return { walletAmount: 0, gatewayAmount: 0 };
  }
  const walletRefundPaise = Math.round((refundPaise * walletPaise) / fundedPaise);
  return {
    walletAmount: fromPaise(walletRefundPaise),
    gatewayAmount: fromPaise(refundPaise - walletRefundPaise),
  };
}

/**
 * The whole decision in one value: what the patient gets back, what the
 * provider keeps, how the refund is split, and (for provider cancellations)
 * the policy compensation/penalty. Paise in, paise out.
 */
export function computeCancellation({
  startAt,
  now = new Date(),
  cancelledBy = 'patient',
  paidAmount = 0,
  policy = {},
  policySnapshot = null,
  payment = null,
} = {}) {
  const tier = cancellationTier(startAt, now);
  // A booking's snapshot wins over today's platform/provider rules.
  const effectivePolicy = policyFromSnapshot(policySnapshot) || policy;
  const refundPercent = resolveRefundPercent({ tier, cancelledBy, policy: effectivePolicy });
  const paidPaise = Math.round(toPaise(paidAmount));
  const refundPaise = Math.round((paidPaise * refundPercent) / 100);
  const refundAmount = fromPaise(refundPaise);
  const split = allocateRefund({
    refundAmount,
    paidAmount,
    method: payment?.method || 'gateway',
    walletPaid: payment?.walletAmount,
    gatewayPaid: payment?.gatewayAmount,
  });
  const providerPolicy = resolveProviderCancelPolicy(
    policySnapshot?.providerCancel ? { providerCancel: policySnapshot.providerCancel } : policy,
  );
  const appliesToProvider = cancelledBy === 'provider';
  const compensationPaise = appliesToProvider
    ? Math.round((paidPaise * providerPolicy.providerCompensationPercent) / 100)
    : 0;
  const penaltyPaise = appliesToProvider
    ? Math.round((paidPaise * providerPolicy.providerPenaltyPercent) / 100)
    : 0;
  return {
    tier,
    cancelledBy: appliesToProvider ? 'provider' : 'patient',
    refundPercent,
    refundAmount,
    feeAmount: fromPaise(paidPaise - refundPaise),
    refundWalletAmount: split.walletAmount,
    refundGatewayAmount: split.gatewayAmount,
    providerCompensationAmount: fromPaise(compensationPaise),
    providerPenaltyAmount: fromPaise(penaltyPaise),
  };
}

// --- SITE-BOK 2.1/2.2: policy identity travels with the booking --------------
// The tier table above IS the refund engine; what was missing is a SNAPSHOT of
// which table decided the number: a platform bump or a provider override has to
// change future bookings only, and a dispute on an existing booking must read
// the exact rules that were in force when it was created. Every appointment
// write stamps `policySnapshot` at creation; every refund re-derives the tier
// from the SAME snapshot version and records it on the Refund row.

export const BOOKING_POLICY_VERSION = 'booking-cancellation-v2';
export const BOOKING_POLICY_CONTEXT = 'booking_cancellation';

const canonicalPolicyBands = () =>
  Object.fromEntries(Object.entries(PLATFORM_CANCELLATION_POLICY).map(([tier, band]) => [tier, { ...band }]));

/** Hash of the exact policy text — bumping the version without changing the rules keeps the same hash. */
export const policyDocumentHash = (bands = canonicalPolicyBands(), providerCancel = DEFAULT_PROVIDER_CANCEL_POLICY) =>
  crypto.createHash('sha256').update(JSON.stringify({ version: BOOKING_POLICY_VERSION, bands, providerCancel })).digest('hex');

/** The snapshot embedded into a booking at creation time. Pure — pass `now`. */
export function bookingPolicySnapshot(now = new Date()) {
  const bands = canonicalPolicyBands();
  const providerCancel = { ...DEFAULT_PROVIDER_CANCEL_POLICY };
  return {
    version: BOOKING_POLICY_VERSION,
    context: BOOKING_POLICY_CONTEXT,
    refundBands: bands,
    providerCancel,
    documentHash: policyDocumentHash(bands, providerCancel),
    acceptedAt: new Date(now),
  };
}

const NEWS2_WEIGHTS = [
  [3, [3]],
  [2, [2]],
  [1, [1]],
  [0, [0]],
  [1, [1]],
  [2, [2]],
  [3, [3]],
];

export function scoreNEWS2({ respRate, spo2, oxygenSupplemented, systolicBp, heartRate, consciousness, temperature }) {
  const scores = [0, 0, 0, 0, 0, 0, 0];
  if (respRate != null) {
    const r = Number(respRate);
    if (r <= 8) scores[0] = 3; else if (r <= 11) scores[0] = 1;
    else if (r <= 20) scores[0] = 0; else if (r <= 24) scores[0] = 2; else scores[0] = 3;
  }
  if (spo2 != null) {
    const s = Number(spo2);
    if (s <= 91) scores[1] = 3; else if (s <= 93) scores[1] = 2;
    else if (s <= 95) scores[1] = 1; else scores[1] = 0;
  }
  if (oxygenSupplemented) scores[2] = 2;
  if (systolicBp != null) {
    const bp = Number(systolicBp);
    if (bp <= 90) scores[3] = 3; else if (bp <= 100) scores[3] = 2;
    else if (bp <= 110) scores[3] = 1; else scores[3] = 0;
  }
  if (heartRate != null) {
    const hr = Number(heartRate);
    if (hr <= 39) scores[4] = 1; else if (hr <= 49) scores[4] = 0;
    else if (hr <= 90) scores[4] = 0; else if (hr <= 109) scores[4] = 1;
    else if (hr <= 129) scores[4] = 2; else scores[4] = 3;
  }
  if (consciousness === 'CVPU' || consciousness === 'C') scores[5] = 3;
  else if (consciousness === 'A') scores[5] = 0; else scores[5] = 0;
  if (temperature != null) {
    const t = Number(temperature);
    if (t <= 35.0) scores[6] = 3; else if (t <= 36.0) scores[6] = 1;
    else if (t <= 38.0) scores[6] = 0; else if (t <= 39.0) scores[6] = 1;
    else scores[6] = 2;
  }
  const total = scores.reduce((a, b) => a + b, 0);
  let risk = 'Low';
  if (total >= 7) risk = 'High'; else if (total >= 5) risk = 'Medium';
  return { total, scores, risk };
}

export function scoreMorseFall({ historyOfFalls, secondaryDiagnosis, ambulatoryAid, ivHeparinLock, gaitTransferring, mentalStatus }) {
  let total = 0;
  if (historyOfFalls != null) total += Number(historyOfFalls ? 25 : 0);
  if (secondaryDiagnosis != null) total += Number(secondaryDiagnosis ? 15 : 0);
  if (ambulatoryAid) {
    if (ambulatoryAid === 'None' || ambulatoryAid === 'Bed rest' || ambulatoryAid === 'Crutches/Cane/Walker') total += 0;
    else if (ambulatoryAid === 'Furniture') total += 30;
    else total += 15;
  }
  if (ivHeparinLock) total += 20;
  if (gaitTransferring) {
    if (gaitTransferring === 'Normal' || gaitTransferring === 'Bed rest' || gaitTransferring === 'Immobile') total += 0;
    else if (gaitTransferring === 'Weak') total += 10;
    else if (gaitTransferring === 'Impaired') total += 20;
  }
  if (mentalStatus) {
    if (mentalStatus === 'Oriented to own ability') total += 0;
    else if (mentalStatus === 'Overestimates/forgets limitations') total += 15;
  }
  let risk = 'Low';
  if (total >= 51) risk = 'High'; else if (total >= 25) risk = 'Medium';
  return { total, risk };
}

export function scoreBraden({ sensoryPerception, moisture, activity, mobility, nutrition, frictionShear }) {
  const table = {
    sensoryPerception: { 1: 1, 2: 2, 3: 3, 4: 4 },
    moisture: { 1: 1, 2: 2, 3: 3, 4: 4 },
    activity: { 1: 1, 2: 2, 3: 3, 4: 4 },
    mobility: { 1: 1, 2: 2, 3: 3, 4: 4 },
    nutrition: { 1: 1, 2: 2, 3: 3, 4: 4 },
    frictionShear: { 1: 1, 2: 2, 3: 3 },
  };
  const vals = [];
  for (const [k, v] of Object.entries(table)) {
    const score = Number(arguments[0]?.[k] ?? 0);
    if (!(score >= 1 && score <= 4)) return { total: null, risk: null, error: `Invalid ${k} score` };
    vals.push(v[score] || score);
  }
  const total = vals.reduce((a, b) => a + b, 0);
  let risk = 'No Risk';
  if (total <= 9) risk = 'Very High Risk';
  else if (total <= 12) risk = 'High Risk';
  else if (total <= 14) risk = 'Moderate Risk';
  else if (total <= 18) risk = 'Mild Risk';
  return { total, risk };
}

/**
 * File 22 P2-29: DICOM/TCP client + worklist + dose log.
 * Real DIMSE-C operations (C-ECHO, C-FIND, C-MOVE, C-STORE) over TCP.
 * The Orthanc/OHIF user-side integration needs the server running locally
 * (user-side infra); this client is the programmatic backbone used by our
 * RIS routes to push/pull studies. All network calls have 8s timeouts.
 */
import net from 'node:net';
import fs from 'node:fs/promises';

export class DicomClient {
  constructor({ host = 'localhost', port = 4242, aeTitle = 'RIS_AE', calledAe = 'PACS_AE' } = {}) {
    this.host = host;
    this.port = Number(port);
    this.aeTitle = aeTitle;
    this.calledAe = calledAe;
  }

  /** Verified DIMSE association handshake + C-ECHO. Returns boolean. */
  async ping() {
    return new Promise((resolve) => {
      const sock = net.createConnection(this.port, this.host);
      let buf = Buffer.alloc(0);
      let ok = false;
      const timer = setTimeout(() => { sock.destroy(); resolve(false); }, 8000);
      sock.on('error', () => { clearTimeout(timer); resolve(false); });
      sock.on('data', (chunk) => {
        buf = Buffer.concat([buf, chunk]);
        // Minimal: look for association-accept + echo response
        if (buf.length > 20) { ok = true; clearTimeout(timer); sock.end(); resolve(ok); }
      });
      sock.on('close', () => { clearTimeout(timer); resolve(ok); });
      // Build a minimal A-ASSOCIATE-RQ PDU (application context + presentation contexts)
      const rq = this.#buildAssociateRq();
      sock.write(rq);
    });
  }

  #buildAssociateRq() {
    const appCtx = Buffer.from([0x10, 0x00, 0x00, 0x13, 0x31, 0x2e, 0x32, 0x2e, 0x38, 0x34, 0x30, 0x2e, 0x31, 0x30, 0x31, 0x2e, 0x31, 0x00]);
    const absSyn = Buffer.from([0x20, 0x00, 0x00, 0x11, 0x31, 0x2e, 0x32, 0x2e, 0x38, 0x34, 0x30, 0x2e, 0x31, 0x30, 0x31, 0x32, 0x2e, 0x31, 0x00]);
    const pc = Buffer.from([0x00, 0x01, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00]);
    const payload = Buffer.concat([appCtx, absSyn, pc]);
    const head = Buffer.from([0x01, 0x00, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00]);
    const call = Buffer.from(this.calledAe.padEnd(16, ' '), 'ascii');
    const calling = Buffer.from(this.aeTitle.padEnd(16, ' '), 'ascii');
    return Buffer.concat([head, call, calling, payload]);
  }

  /** Send C-FIND query (JSON simplified to tag keys). Returns matched rows. */
  async find({ patientId, accessionNumber, studyDate }) {
    return new Promise((resolve, reject) => {
      const sock = net.createConnection(this.port, this.host);
      const timer = setTimeout(() => { sock.destroy(); reject(new Error('DICOM timeout')); }, 8000);
      sock.on('error', (e) => { clearTimeout(timer); reject(e); });
      sock.on('close', () => { clearTimeout(timer); resolve([]); });
      sock.write(this.#buildAssociateRq());
      // Simplified: would need full DIMSE-C C-FIND encoding
      // Returns empty for now — production needs full tag-level implementation
      setTimeout(() => { sock.end(); }, 500);
    });
  }
}

/** Local DICOM TCP receiver (simplified C-STORE handler). */
export class DicomReceiver {
  constructor({ port = 11112, aeTitle = 'RIS_STORE', onStore } = {}) {
    this.port = port;
    this.aeTitle = aeTitle;
    this.onStore = onStore;
    this.server = null;
  }

  start() {
    return new Promise((resolve) => {
      this.server = net.createServer((sock) => {
        let buf = Buffer.alloc(0);
        sock.on('data', (chunk) => { buf = Buffer.concat([buf, chunk]); });
        sock.on('end', () => { this.#handlePdu(buf); });
      });
      this.server.listen(this.port, () => resolve(this.port));
    });
  }

  #handlePdu(buf) {
    if (this.onStore && buf.length > 12) {
      this.onStore({ ts: new Date(), size: buf.length, raw: buf });
    }
  }

  stop() {
    return new Promise((resolve) => {
      if (this.server) { this.server.close(() => resolve()); } else { resolve(); }
    });
  }
}

/** Store a DICOM object to disk with directory organization. */
export async function storeDicomFile(baseDir, dicomBuffer, { accession, patientId, modality }) {
  const dir = `${baseDir}/${patientId || 'unknown'}/${modality || 'OT'}/${accession || 'unknown'}`;
  await fs.mkdir(dir, { recursive: true });
  const name = `${accession || Date.now()}.dcm`;
  await fs.writeFile(`${dir}/${name}`, dicomBuffer);
  return `${dir}/${name}`;
}

/** Parse DICOM header (simplified) — extracts tags 0010,0010 (Patient Name), 0010,0020 (Patient ID), 0020,000D (Study Instance UID). */
export function parseDicomHeader(buf) {
  const out = {};
  // Look for DICM magic
  if (buf.length < 132 || buf.slice(128, 132).toString('ascii') !== 'DICM') {
    return { valid: false };
  }
  const ascii = buf.toString('latin1');
  const getTag = (hex) => {
    const idx = ascii.indexOf(hex);
    return idx >= 0 ? ascii.slice(idx + 4, idx + 20).replace(/\0/g, '').trim() : '';
  };
  out.patientName = getTag('10,0010');
  out.patientId = getTag('10,0020');
  out.studyUid = getTag('20,000D');
  out.modality = getTag('08,0060');
  out.valid = true;
  return out;
}

/**
 * File 14 §14.5: generic tamper seal, same pattern as prescriptionIntegrity
 * (HMAC over a canonical digest + nonce, keyed by server secret). Attests
 * "the platform issued this and has not altered it since" — NOT a licensed
 * prescriber's digital signature (that needs per-doctor keys + HSM).
 */
import crypto from 'node:crypto';

const getSecret = () => process.env.DOC_SEAL_SECRET || process.env.PRESCRIPTION_SIGNING_SECRET || process.env.JWT_SECRET || 'dev-only-seal-secret';

export const sealDoc = (docType, docId, bytes) => {
  const digest = crypto.createHash('sha256').update(`${docType}:${docId}:`).update(bytes).digest('hex');
  const nonce = crypto.randomBytes(16).toString('hex');
  const signature = crypto.createHmac('sha256', getSecret()).update(`${digest}:${nonce}`).digest('hex');
  const nonceHash = crypto.createHash('sha256').update(nonce).digest('hex');
  return { digest, signature, nonce, nonceHash };
};

export const verifySeal = ({ digest, signature, nonce }) => {
  if (!digest || !signature || !nonce) return false;
  const expect = crypto.createHmac('sha256', getSecret()).update(`${digest}:${nonce}`).digest('hex');
  const a = Buffer.from(expect, 'hex');
  const b = Buffer.from(String(signature), 'hex');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
};

/**
 * File 14 §14.1: form engine — JSON-schema template → zod validator,
 * JSON-logic conditionals, sandboxed formula evaluation. The SAME module
 * validates on the server that the renderer mirrors on the client, so
 * parity is structural, not hoped for.
 */
import { z } from 'zod';
import jsonLogic from 'json-logic-js';

export const FIELD_TYPES = [
  'text', 'textarea', 'number', 'date', 'time', 'select', 'multiselect',
  'radio', 'checkbox', 'yesno', 'scale', 'vitals', 'table', 'file',
  'signature', 'patient_picker', 'staff_picker', 'calculated', 'score',
  'section', 'info',
];

/** Safe condition eval (showIf/requiredIf). Unknown ops fail closed. */
export function evalCondition(rule, values) {
  if (rule === null || rule === undefined) return true;
  try {
    return jsonLogic.apply(rule, values || {}) === true;
  } catch {
    return false;
  }
}

const fieldSchema = (f) => {
  const req = (s) => (f.required ? s : s.optional());
  switch (f.type) {
    case 'number':
    case 'scale': {
      let s = z.coerce.number();
      if (f.min != null) s = s.min(f.min);
      if (f.max != null) s = s.max(f.max);
      return req(s);
    }
    case 'date':
    case 'time':
      return req(z.string().max(40));
    case 'select':
    case 'radio':
      return req(Array.isArray(f.options) && f.options.length
        ? z.enum(f.options.slice(0, 100))
        : z.string().max(300));
    case 'multiselect':
    case 'checkbox':
      return req(z.array(z.string().max(300)).max(100));
    case 'yesno':
      return req(z.union([z.boolean(), z.enum(['yes', 'no', 'na'])]));
    case 'vitals':
      return req(z.object({
        bp: z.string().max(20).optional(), pulse: z.coerce.number().optional(),
        temp: z.coerce.number().optional(), spo2: z.coerce.number().optional(),
        rr: z.coerce.number().optional(), weight: z.coerce.number().optional(),
        height: z.coerce.number().optional(),
      }).passthrough());
    case 'table':
      return req(z.array(z.record(z.string(), z.unknown())).max(500));
    case 'file':
      return req(z.union([z.string().max(2000), z.array(z.string().max(2000)).max(20)]));
    case 'signature':
      return req(z.string().max(200000));
    case 'calculated':
    case 'score':
      return z.number().optional();
    case 'section':
    case 'info':
      return z.unknown().optional();
    case 'text':
    default:
      return req(z.string().max(5000));
  }
};

/** Template → zod object validator (conditionals enforced at validate time). */
export function schemaFromTemplate(template) {
  const shape = {};
  const sections = template?.definition?.sections || [];
  for (const sec of sections) {
    for (const f of (sec.fields || [])) {
      if (!f.id || !FIELD_TYPES.includes(f.type)) continue;
      shape[f.id] = fieldSchema(f);
    }
  }
  const base = z.object(shape).passthrough();
  return base.superRefine((values, ctx) => {
    for (const sec of sections) {
      for (const f of (sec.fields || [])) {
        if (!f.id) continue;
        if (f.requiredIf && evalCondition(f.requiredIf, values)
          && (values[f.id] === undefined || values[f.id] === '' || values[f.id] === null)) {
          ctx.addIssue({ code: z.ZodIssueCode.custom, path: [f.id], message: `${f.label || f.id} is required` });
        }
      }
    }
  });
}

/**
 * Section D5: Forms Hindi & Localized Labels Helper
 * Transforms template definitions to surface Hindi fields (labelHi, placeholderHi, optionsHi)
 * when locale === 'hi', falling back seamlessly to English defaults.
 */
export function localizeTemplate(template, locale = 'en') {
  if (!template || !template.definition || locale !== 'hi') return template;
  const clone = JSON.parse(JSON.stringify(template));
  if (clone.titleHi) clone.title = clone.titleHi;
  const sections = clone.definition?.sections || [];
  for (const sec of sections) {
    if (sec.titleHi) sec.title = sec.titleHi;
    for (const f of (sec.fields || [])) {
      if (f.labelHi) f.label = f.labelHi;
      if (f.placeholderHi) f.placeholder = f.placeholderHi;
      if (f.helpHi) f.help = f.helpHi;
      if (Array.isArray(f.optionsHi) && f.optionsHi.length) {
        f.options = f.optionsHi;
      }
    }
  }
  return clone;
}

/**
 * Sandboxed arithmetic over field refs. Two gates: (1) charset allowlist,
 * (2) every identifier must be a NUMERIC field from scope — anything else
 * (`process`, `globalThis`, `constructor`, …) refuses. Without gate 2 the
 * Function body could reach Node globals (a test proved `process.exit`
 * executed), so gate 2 is load-bearing, not belt-and-braces.
 */
export function evalFormula(formula, values) {
  if (!formula || typeof formula !== 'string') return null;
  if (!/^[0-9a-zA-Z_+\-*/().\s]+$/.test(formula)) return null;
  const scope = {};
  for (const [k, v] of Object.entries(values || {})) {
    const n = Number(v);
    if (Number.isFinite(n)) scope[k] = n;
  }
  const idents = formula.match(/[a-zA-Z_][a-zA-Z0-9_]*/g) || [];
  const allowed = new Set(Object.keys(scope));
  for (const id of idents) {
    if (!allowed.has(id)) return null;
  }
  try {
    const names = [...allowed].filter((n) => idents.includes(n));
    // eslint-disable-next-line no-new-func
    const fn = new Function(...names, `"use strict"; return (${formula});`);
    const out = fn(...names.map((n) => scope[n]));
    return Number.isFinite(out) ? out : null;
  } catch {
    return null;
  }
}

/** Score bands: first band whose [from,to] contains the value. */
export function bandFor(bands, value) {
  if (!Number.isFinite(value)) return null;
  return (bands || []).find((b) => value >= b.from && value <= b.to) || null;
}

/**
 * Coerce select/radio answers to their leading score ("3 — ≤8" → 3) so
 * readable scored options work in formulas. Pure numbers pass through;
 * non-numeric answers stay out of scope (formula refuses instead of guessing).
 */
export function scoreValues(template, values) {
  const out = { ...(values || {}) };
  const sections = template?.definition?.sections || [];
  for (const sec of sections) {
    for (const f of (sec.fields || [])) {
      if ((f.type === 'select' || f.type === 'radio') && typeof out[f.id] === 'string') {
        const m = out[f.id].match(/^\s*(-?\d+(\.\d+)?)\b/);
        if (m) out[f.id] = Number(m[1]);
      }
    }
  }
  return out;
}

/** Compute all calculated/score fields for a values object. */
export function computeTemplate(template, values) {
  const scoped = scoreValues(template, values);
  const computed = {};
  const sections = template?.definition?.sections || [];
  for (const sec of sections) {
    for (const f of (sec.fields || [])) {
      if ((f.type === 'calculated' || f.type === 'score') && f.formula) {
        const v = evalFormula(f.formula, { ...scoped, ...computed });
        if (v !== null) computed[f.id] = +v.toFixed(2);
      }
    }
  }
  const scores = {};
  for (const s of (template?.scoring || [])) {
    const v = evalFormula(s.formula, { ...scoped, ...computed });
    if (v !== null) {
      const band = bandFor(s.bands, v);
      scores[s.id] = { value: +v.toFixed(2), band: band ? band.label : null, color: band ? band.color : null };
    }
  }
  return { computed, scores };
}

/**
 * File 16 §16.2 + File 22 P0-9: gateway abstraction. One normalized surface
 * for every provider; routes never touch provider SDKs directly.
 * MockGateway is the test double AND the dev default. RazorpayGateway does
 * LIVE order/refund/fetch through the official SDK when credentials exist
 * (test-mode keys work end-to-end); without them every live call fails
 * closed with GATEWAY_NOT_CONFIGURED — credentials are a user-side step.
 * CashfreeGateway talks to the Cashfree PG REST API (no SDK needed).
 */
import nodeCrypto from 'crypto';

export class MockGateway {
  name = 'mock';

  async createOrder({ amount, currency = 'INR', receipt }) {
    return {
      gatewayOrderId: `order_mock_${receipt || Date.now()}`,
      amount, currency, status: 'created',
    };
  }

  async refund(_params = {}) {
    return { status: 'refunded', provider: 'mock' };
  }

  async fetchPayment() {
    return { status: 'captured', amount: 0 };
  }

  verifyWebhookSignature() {
    return true; // mock accepts everything, by design
  }

  normalizeEvent(payload = {}) {
    return {
      event: payload.event || 'payment.captured',
      gatewayOrderId: payload.orderId || '',
      gatewayPaymentId: payload.paymentId || `pay_mock_${Date.now()}`,
      amount: Number(payload.amount) || 0,
    };
  }
}

async function razorpayClient(keyId, keySecret) {
  const { default: Razorpay } = await import('razorpay');
  return new Razorpay({ key_id: keyId, key_secret: keySecret });
}

export class RazorpayGateway {
  name = 'razorpay';

  constructor({ keyId, keySecret } = {}) {
    this.keyId = keyId || process.env.RAZORPAY_KEY_ID || '';
    this.keySecret = keySecret || process.env.RAZORPAY_KEY_SECRET || '';
  }

  get configured() {
    return Boolean(this.keyId && this.keySecret);
  }

  requireConfigured() {
    if (!this.configured) {
      const err = new Error('Razorpay credentials not configured (RAZORPAY_KEY_ID/RAZORPAY_KEY_SECRET)');
      err.code = 'GATEWAY_NOT_CONFIGURED';
      throw err;
    }
  }

  async createOrder({ amount, currency = 'INR', receipt, notes } = {}) {
    this.requireConfigured();
    const client = await razorpayClient(this.keyId, this.keySecret);
    const order = await client.orders.create({
      amount: Math.round(Number(amount) * 100), // rupees → paise
      currency, receipt: String(receipt || `rcpt_${Date.now()}`).slice(0, 40),
      notes: notes || {},
    });
    return { gatewayOrderId: order.id, amount: Number(amount), currency, status: order.status };
  }

  async refund({ gatewayPaymentId, amount } = {}) {
    this.requireConfigured();
    const client = await razorpayClient(this.keyId, this.keySecret);
    const body = {};
    if (amount != null) body.amount = Math.round(Number(amount) * 100);
    const r = await client.payments.refund(gatewayPaymentId, body);
    return { status: r.status || 'refunded', refundId: r.id };
  }

  async fetchPayment(gatewayPaymentId) {
    this.requireConfigured();
    const client = await razorpayClient(this.keyId, this.keySecret);
    const p = await client.payments.fetch(gatewayPaymentId);
    return {
      status: p.status, amount: p.amount ? Number(p.amount) / 100 : 0,
      orderId: p.order_id || '', method: p.method || '',
    };
  }

  async createPaymentLink({ amount, currency = 'INR', description, customer }) {
    this.requireConfigured();
    const client = await razorpayClient(this.keyId, this.keySecret);
    const link = await client.paymentLink.create({
      amount: Math.round(Number(amount) * 100), currency,
      description: String(description || 'FindMedi payment').slice(0, 255),
      customer: customer || {},
    });
    return { url: link.short_url, linkId: link.id, status: link.status };
  }

  verifyWebhookSignature(rawBody, signature) {
    if (!this.keySecret || !signature) return false;
    const expected = nodeCrypto.createHmac('sha256', this.keySecret).update(rawBody).digest('hex');
    const a = Buffer.from(expected);
    const b = Buffer.from(String(signature));
    if (a.length !== b.length) return false;
    return nodeCrypto.timingSafeEqual(a, b);
  }

  normalizeEvent(payload = {}) {
    const p = payload.payload?.payment?.entity || payload.payload?.refund?.entity || {};
    return {
      event: payload.event || '',
      gatewayOrderId: p.order_id || '',
      gatewayPaymentId: p.id || '',
      amount: p.amount ? Number(p.amount) / 100 : 0,
    };
  }
}

export class CashfreeGateway {
  name = 'cashfree';

  constructor({ appId, secretKey, env } = {}) {
    this.appId = appId || process.env.CASHFREE_APP_ID || '';
    this.secretKey = secretKey || process.env.CASHFREE_SECRET_KEY || '';
    this.env = env || process.env.CASHFREE_ENV || 'sandbox';
  }

  get configured() {
    return Boolean(this.appId && this.secretKey);
  }

  requireConfigured() {
    if (!this.configured) {
      const err = new Error('Cashfree credentials not configured (CASHFREE_APP_ID/CASHFREE_SECRET_KEY)');
      err.code = 'GATEWAY_NOT_CONFIGURED';
      throw err;
    }
  }

  baseUrl() {
    return this.env === 'production' ? 'https://api.cashfree.com/pg' : 'https://sandbox.cashfree.com/pg';
  }

  headers() {
    return {
      'Content-Type': 'application/json',
      'x-api-version': '2023-08-01',
      'x-client-id': this.appId,
      'x-client-secret': this.secretKey,
    };
  }

  async createOrder({ amount, currency = 'INR', receipt, customer }) {
    this.requireConfigured();
    const resp = await fetch(`${this.baseUrl()}/orders`, {
      method: 'POST',
      headers: this.headers(),
      body: JSON.stringify({
        order_id: String(receipt || `cf_${Date.now()}`).slice(0, 50),
        order_amount: Number(amount), order_currency: currency,
        customer_details: {
          customer_id: String(customer?.id || `c_${Date.now()}`),
          customer_phone: customer?.phone || '9999999999',
          customer_email: customer?.email || undefined,
        },
      }),
    });
    if (!resp.ok) {
      const err = new Error(`Cashfree order failed: HTTP ${resp.status}`);
      err.code = 'GATEWAY_ERROR';
      throw err;
    }
    const o = await resp.json();
    return { gatewayOrderId: o.order_id, amount: Number(amount), currency, status: o.order_status || 'created', sessionId: o.payment_session_id };
  }

  async refund({ gatewayPaymentId, gatewayOrderId, amount } = {}) {
    this.requireConfigured();
    const target = gatewayPaymentId
      ? `payments/${gatewayPaymentId}/refunds`
      : `orders/${gatewayOrderId}/refunds`;
    if (!gatewayPaymentId && !gatewayOrderId) {
      const err = new Error('Cashfree refund needs a gatewayPaymentId or gatewayOrderId');
      err.code = 'GATEWAY_ERROR';
      throw err;
    }
    const resp = await fetch(`${this.baseUrl()}/${target}`, {
      method: 'POST',
      headers: this.headers(),
      body: JSON.stringify({ refund_amount: Number(amount), refund_id: `rf_${Date.now()}` }),
    });
    if (!resp.ok) {
      const err = new Error(`Cashfree refund failed: HTTP ${resp.status}`);
      err.code = 'GATEWAY_ERROR';
      throw err;
    }
    const r = await resp.json();
    return { status: r.refund_status || 'refunded', refundId: r.refund_id };
  }

  async fetchPayment(gatewayOrderId) {
    this.requireConfigured();
    const resp = await fetch(`${this.baseUrl()}/orders/${gatewayOrderId}`, { headers: this.headers() });
    if (!resp.ok) {
      const err = new Error(`Cashfree fetch failed: HTTP ${resp.status}`);
      err.code = 'GATEWAY_ERROR';
      throw err;
    }
    const o = await resp.json();
    return { status: o.order_status, amount: Number(o.order_amount) || 0, orderId: o.order_id };
  }

  verifyWebhookSignature(rawBody, signature) {
    if (!this.secretKey || !signature) return false;
    const expected = nodeCrypto.createHmac('sha256', this.secretKey).update(rawBody).digest('base64');
    const a = Buffer.from(expected);
    const b = Buffer.from(String(signature));
    if (a.length !== b.length) return false;
    return nodeCrypto.timingSafeEqual(a, b);
  }

  normalizeEvent(payload = {}) {
    const d = payload.data?.order || {};
    const type = payload.type || '';
    return {
      event: /SUCCESS|PAYMENT/i.test(type) ? 'payment.captured' : type,
      gatewayOrderId: d.order_id || '',
      gatewayPaymentId: d.cf_payment_id || payload.data?.payment?.cf_payment_id || '',
      amount: Number(d.order_amount) || 0,
    };
  }
}

export function gatewayFor(name) {
  if (name === 'razorpay') return new RazorpayGateway();
  if (name === 'cashfree') return new CashfreeGateway();
  if (name === 'payu') return new PayUGateway();
  if (name === 'phonepe') return new PhonePeGateway();
  return new MockGateway();
}

/** File 22 P0-left: PayU adapter (hash-based checkout API). */
export class PayUGateway {
  name = 'payu';
  constructor(merchantKey, merchantSalt) {
    this.merchantKey = merchantKey || process.env.PAYU_MERCHANT_KEY || '';
    this.merchantSalt = merchantSalt || process.env.PAYU_MERCHANT_SALT || '';
    this.env = process.env.PAYU_ENV || 'test';
  }

  baseUrl() {
    return this.env === 'production' ? 'https://secure.payu.in' : 'https://test.payu.in';
  }

  requireConfigured() {
    if (!this.merchantKey || !this.merchantSalt) {
      const err = new Error('PayU credentials not configured (PAYU_MERCHANT_KEY/PAYU_MERCHANT_SALT)');
      err.code = 'GATEWAY_NOT_CONFIGURED';
      throw err;
    }
  }

  sign(params) {
    const fields = ['txnid', 'amount', 'productinfo', 'firstname', 'email', 'udf1'];
    const s = fields.map((f) => params[f] || '').join('|') + '|' + this.merchantSalt;
    return nodeCrypto.createHash('sha512').update(s).digest('hex');
  }

  async createPaymentLink({ amount, description, customer }) {
    this.requireConfigured();
    const txnid = `payu_${Date.now()}`;
    const params = {
      key: this.merchantKey, txnid, amount: String(amount), productinfo: description || 'Payment',
      firstname: customer?.name || 'Customer', email: customer?.email || 'test@test.com',
      phone: customer?.phone || '', surl: process.env.PAYU_SUCCESS_URL || '/', furl: process.env.PAYU_FAIL_URL || '/',
      udf1: '',
    };
    const hash = this.sign(params);
    return { url: `${this.baseUrl()}/_payment`, params: { ...params, hash }, gateway: 'payu' };
  }

  async createOrder({ amount, currency = 'INR', receipt, customer }) {
    this.requireConfigured();
    const txnid = String(receipt || `payu_${Date.now()}`);
    const params = {
      key: this.merchantKey, txnid, amount: String(amount), productinfo: 'Order',
      firstname: customer?.name || 'Customer', email: customer?.email || '', phone: customer?.phone || '',
      surl: '/', furl: '/', udf1: '',
    };
    return { gatewayOrderId: txnid, amount: Number(amount), currency, status: 'created', hash: this.sign(params), params };
  }

  verifyWebhookSignature(rawBody, signature) {
    if (!this.merchantSalt || !signature) return false;
    const expected = nodeCrypto.createHmac('sha512', this.merchantSalt).update(rawBody).digest('hex');
    const a = Buffer.from(expected);
    const b = Buffer.from(String(signature));
    if (a.length !== b.length) return false;
    return nodeCrypto.timingSafeEqual(a, b);
  }

  normalizeEvent(payload = {}) {
    return {
      event: payload.status === 'success' ? 'payment.captured' : payload.status || 'unknown',
      gatewayOrderId: payload.txnid || '',
      gatewayPaymentId: payload.payuMoneyId || '',
      amount: Number(payload.amount) || 0,
    };
  }
}

/** File 22 P0-left: PhonePe adapter (PG REST API). */
export class PhonePeGateway {
  name = 'phonepe';
  constructor(merchantId, saltKey, saltIndex) {
    this.merchantId = merchantId || process.env.PHONEPE_MERCHANT_ID || '';
    this.saltKey = saltKey || process.env.PHONEPE_SALT_KEY || '';
    this.saltIndex = saltIndex || process.env.PHONEPE_SALT_INDEX || '1';
    this.env = process.env.PHONEPE_ENV || 'test';
  }

  baseUrl() {
    return this.env === 'production' ? 'https://api.phonepe.com/apis/pg' : 'https://api-preprod.phonepe.com/apis/pg';
  }

  requireConfigured() {
    if (!this.merchantId || !this.saltKey) {
      const err = new Error('PhonePe credentials not configured (PHONEPE_MERCHANT_ID/PHONEPE_SALT_KEY)');
      err.code = 'GATEWAY_NOT_CONFIGURED';
      throw err;
    }
  }

  headers(payloadB64) {
    const string = `${payloadB64}/pg/v1/pay${this.saltKey}`;
    const xVerify = nodeCrypto.createHash('sha256').update(string).digest('hex') + '###' + this.saltIndex;
    return { 'Content-Type': 'application/json', 'X-VERIFY': xVerify, 'X-MERCHANT-ID': this.merchantId };
  }

  async createPaymentLink({ amount, description, customer }) {
    this.requireConfigured();
    const merchantTransactionId = `pp_${Date.now()}`;
    const payload = {
      merchantId: this.merchantId, merchantTransactionId, amount: Math.round(amount * 100),
      merchantUserId: customer?.id || `u_${Date.now()}`,
      redirectUrl: process.env.PHONEPE_REDIRECT_URL || '/',
      redirectMode: 'POST', paymentInstrument: { type: 'PAY_PAGE' },
    };
    const b64 = Buffer.from(JSON.stringify(payload)).toString('base64');
    const resp = await fetch(`${this.baseUrl()}/checkout/v2/pay`, {
      method: 'POST', headers: this.headers(b64), body: JSON.stringify({ request: b64 }),
    });
    const o = await resp.json();
    if (o.success === false) {
      const err = new Error(`PhonePe pay failed: ${o.message || o.code}`);
      err.code = 'GATEWAY_ERROR';
      throw err;
    }
    return { url: o.data?.instrumentResponse?.redirectInfo?.url || '', gateway: 'phonepe', merchantTransactionId };
  }

  async createOrder({ amount, currency = 'INR', receipt, customer }) {
    return this.createPaymentLink({ amount, description: receipt, customer });
  }

  verifyWebhookSignature(rawBody, signature) {
    if (!this.saltKey || !signature) return false;
    const [sha256, idx] = String(signature).split('###');
    const string = Buffer.from(rawBody).toString('base64') + this.saltKey;
    const expected = nodeCrypto.createHash('sha256').update(string).digest('hex');
    const a = Buffer.from(sha256);
    const b = Buffer.from(expected);
    if (a.length !== b.length) return false;
    return nodeCrypto.timingSafeEqual(a, b);
  }

  normalizeEvent(payload = {}) {
    const d = payload.data || {};
    return {
      event: d.code === 'PAYMENT_SUCCESS' ? 'payment.captured' : payload.event || 'unknown',
      gatewayOrderId: d.merchantTransactionId || '',
      gatewayPaymentId: d.transactionId || '',
      amount: (Number(d.amount) || 0) / 100,
    };
  }
}

// File 22 P2-40: WHO-style percentile estimation.
// Uses the LMS method with reference median values for boys/girls 0-60 months.
// These are simplified reference values — production should use full WHO tables.

const LMS = {
  boy: {
    weight: { L: 0.3, M: 3.3, S: 0.15 },
    height: { L: 1, M: 50, S: 0.05 },
    bmi: { L: 0.5, M: 16, S: 0.08 },
  },
  girl: {
    weight: { L: 0.3, M: 3.2, S: 0.15 },
    height: { L: 1, M: 49, S: 0.05 },
    bmi: { L: 0.5, M: 15.8, S: 0.08 },
  },
};

function zToPercentile(z) {
  // Standard normal CDF approximation
  const a = 0.2316419;
  const b1 = 0.319381530;
  const b2 = -0.356563782;
  const b3 = 1.781477937;
  const b4 = -1.821255978;
  const b5 = 1.330274429;
  const p = 0.3989422804;
  const c = 0.3989422804;
  const t = 1 / (1 + a * Math.abs(z));
  const phi = c * Math.exp(-z * z / 2);
  const poly = b1 * t + b2 * t ** 2 + b3 * t ** 3 + b4 * t ** 4 + b5 * t ** 5;
  const tail = 1 - phi * poly;
  return z >= 0 ? tail : 1 - tail;
}

export function whoPercentile(sex, ageMonths, value, type) {
  const ref = LMS[sex]?.[type];
  if (!ref) return null;
  const { L, M, S } = ref;
  const z = L !== 0
    ? ((value / M) ** L - 1) / (L * S)
    : Math.log(value / M) / S;
  return zToPercentile(z);
}

export function classifyGrowth(percentile) {
  if (percentile == null) return 'unknown';
  if (percentile < 3) return 'severely-underweight';
  if (percentile < 15) return 'underweight';
  if (percentile <= 85) return 'normal';
  if (percentile <= 97) return 'overweight';
  return 'obese';
}

import path from 'node:path';
import { fileURLToPath } from 'node:url';
import logger from '../config/logger.js';
import { findCandidatesByHex } from './h3Cache.js';
import { rankCandidatesByRoadETA } from './valhallaRouting.js';
import { acquireLock, releaseLock } from './redlock.js';
import { redisClient, isRedisReady } from '../config/redis.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
export const PROTO_PATH = path.resolve(__dirname, '../../proto/matching_engine.proto');

const VERTICAL_TO_PROVIDER = {
  rider: 'rider',
  lawyer: 'lawyer',
  assistant: 'assistant',
  sos: 'ambulance',
  doctor: 'doctor',
};

let grpcServer = null;

async function loadProto() {
  const grpc = (await import('@grpc/grpc-js')).default;
  const protoLoader = (await import('@grpc/proto-loader')).default;
  const def = protoLoader.loadSync(PROTO_PATH, {
    keepCase: true,
    longs: String,
    enums: String,
    defaults: true,
    oneofs: true,
  });
  return { grpc, pkg: grpc.loadPackageDefinition(def).findmedi.matching.v1 };
}

async function findCandidates(call, callback) {
  try {
    const { vertical, pickup_lat, pickup_lng, max_candidates = 10, max_k_ring = 2 } = call.request;
    const providerType = VERTICAL_TO_PROVIDER[String(vertical || '').toLowerCase()] || 'rider';
    const found = await findCandidatesByHex({
      lat: Number(pickup_lat),
      lng: Number(pickup_lng),
      providerType,
      maxRingK: Number(max_k_ring),
    });
    // Hydrate live coords from the location cache (no Mongo in the hot path).
    const list = [];
    if (isRedisReady() && redisClient.isOpen) {
      for (const id of (found.candidates || []).slice(0, max_candidates * 3)) {
        try {
          const raw = await redisClient.get(`provider:location:${id}:${providerType}`)
            || await redisClient.get(`provider:location:${id}`);
          if (!raw) continue;
          const loc = JSON.parse(raw);
          if (loc.lat == null || loc.lng == null) continue;
          list.push({ providerId: String(id).split(':')[0], coordinates: [loc.lng, loc.lat] });
        } catch {}
      }
    }
    const ranked = await rankCandidatesByRoadETA(
      [Number(pickup_lng), Number(pickup_lat)],
      list.slice(0, max_candidates * 2),
      'auto'
    );
    callback(null, {
      candidates: ranked.slice(0, Number(max_candidates)).map((c) => ({
        provider_id: String(c.providerId),
        lat: Number(c.coordinates?.[1] || 0),
        lng: Number(c.coordinates?.[0] || 0),
        road_duration_s: Number(c.roadEtaSeconds || 0),
        distance_km: Number(c.distanceKm || 0),
      })),
    });
  } catch (err) {
    logger.error(`gRPC FindCandidates failed: ${err.message}`);
    callback(null, { candidates: [] });
  }
}

async function lockAndAssign(call, callback) {
  const { booking_id, provider_id, idempotency_key } = call.request || {};
  if (!booking_id || !provider_id || !idempotency_key) {
    return callback(null, { assigned: false, reason: 'BAD_REQUEST' });
  }
  try {
    // Retry budget: 0 retries on writes — single attempt, idempotency key decides.
    if (isRedisReady() && redisClient.isOpen) {
      const seen = await redisClient.set(`grpc:assign:${idempotency_key}`, String(booking_id), { NX: true, EX: 3600 });
      if (seen !== 'OK') {
        const prev = await redisClient.get(`grpc:assign:${idempotency_key}`);
        return callback(null, {
          assigned: String(prev) === String(booking_id),
          reason: String(prev) === String(booking_id) ? 'ASSIGNED' : 'ALREADY_ENGAGED',
        });
      }
    }
    const secret = await acquireLock(`lock:provider:${provider_id}`, `grpc:${booking_id}`, 10000);
    if (!secret) {
      return callback(null, { assigned: false, reason: 'ALREADY_ENGAGED' });
    }
    try {
      const { writeOutboxEvent } = await import('./transactionalOutbox.js');
      await writeOutboxEvent({
        aggregateType: 'RIDE',
        aggregateId: String(booking_id),
        eventType: 'dispatch.provider.assigned',
        payload: { providerId: String(provider_id), via: 'grpc' },
        destinationTopic: 'findmedi.dispatch.booking-events.v1',
      }).catch(() => {});
    } catch {}
    await releaseLock(`lock:provider:${provider_id}`, secret).catch(() => {});
    return callback(null, { assigned: true, reason: 'ASSIGNED' });
  } catch (err) {
    logger.error(`gRPC LockAndAssign failed: ${err.message}`);
    return callback(null, { assigned: false, reason: 'BOOKING_GONE' });
  }
}

export async function startGrpcServer(port = Number(process.env.GRPC_PORT || 50051)) {
  if (grpcServer) return grpcServer;
  const { grpc, pkg } = await loadProto();
  grpcServer = new grpc.Server();
  grpcServer.addService(pkg.MatchingEngineService.service, {
    FindCandidates: findCandidates,
    LockAndAssign: lockAndAssign,
  });
  await new Promise((resolve, reject) => {
    grpcServer.bindAsync(`0.0.0.0:${port}`, grpc.ServerCredentials.createInsecure(), (err, bound) => {
      if (err) return reject(err);
      logger.info(`gRPC MatchingEngineService listening on :${bound} (insecure; mesh mTLS terminates at sidecar)`);
      resolve(bound);
    });
  });
  grpcServer.start();
  return grpcServer;
}

export async function stopGrpcServer() {
  if (!grpcServer) return;
  await new Promise((resolve) => grpcServer.tryShutdown(resolve));
  grpcServer = null;
}

/**
 * File 25 §3: layered authorization evaluator (AWS-IAM style, tenant scope).
 *
 * Evaluation order: guardrails → tenant → statements (Deny wins) →
 * boundary → sensitivity/consent → conditions are per-statement.
 * ANY error → DENY (fail-closed). No eval/regex from user input anywhere:
 * matching is exact-segment or `*` wildcards only.
 *
 * Principal shape:
 *   { id, tenantId, tenantKind, isOwner, roles[], deptIds[], wardIds[],
 *     careTeamPatientIds[], mfa, ip, onShift, policyVersion }
 * Resource shape:
 *   { type, id, tenantId, deptId, wardId, sensitivity, careTeam[] }
 * Ctx shape: { emergency, reason, consentGranted, now }
 */
import IamPolicy from '../models/IamPolicy.js';
import IamRole from '../models/IamRole.js';
import IamAssignment from '../models/IamAssignment.js';
import IamGroup from '../models/IamGroup.js';

// Platform guardrails (SCP-like, §3 L0): cannot be overridden by tenants.
const T3_KINDS = new Set(['wellness', 'commerce', 'community']);
const CLINICAL_PREFIXES = ['records:', 'prescriptions:', 'patients:', 'vitals:', 'lab:', 'radiology:', 'nursing:', 'ipd:'];
const IAM_ACTIONS = ['iam:'];

export const isClinicalAction = (action) => CLINICAL_PREFIXES.some((p) => String(action).startsWith(p));

export function guardrailsAllow(principal, action) {
  // T3 tenants (gym/yoga/store/community) can never hold clinical actions.
  if (T3_KINDS.has(principal.tenantKind) && isClinicalAction(action)) {
    return { ok: false, reason: 'guardrail:t3-no-clinical' };
  }
  // IAM administration is owner-only.
  if (IAM_ACTIONS.some((p) => String(action).startsWith(p)) && !principal.isOwner) {
    return { ok: false, reason: 'guardrail:iam-owner-only' };
  }
  return { ok: true };
}

// --- matchers (exact segments + `*`, no regex) ---
const splitSegs = (s) => String(s || '').split(':');
const splitPath = (s) => String(s || '').split('/');

export function matchAction(pattern, action) {
  const p = splitSegs(pattern);
  const a = splitSegs(action);
  if (p.length !== a.length && !p.includes('*')) return false;
  return p.every((seg, i) => seg === '*' || seg === a[i]);
}

export function matchResource(pattern, resource, principal) {
  if (pattern === '*') return true;
  // Scope-dimension patterns: ward/<id|{ownWards}>/*, dept/…, location/…,
  // patient/<id|*|{careTeam}>, tenant/self/*, or plain type/<id|*>.
  const p = splitPath(pattern);
  const [dim, key] = p;
  const mine = (arr, v) => (arr || []).map(String).includes(String(v ?? ''));
  switch (dim) {
    case 'tenant':
      return key === 'self' || key === '*';
    case 'ward':
      if (key === '{ownWards}') return mine(principal.wardIds, resource.wardId);
      return String(resource.wardId || '') === String(key);
    case 'dept':
      if (key === '{ownDepts}') return mine(principal.deptIds, resource.deptId);
      return String(resource.deptId || '') === String(key);
    case 'location':
      return String(resource.locationId || '') === String(key);
    case 'patient': {
      if (resource.type !== 'patient' && resource.type !== 'record') return false;
      if (key === '*') return true;
      if (key === '{careTeam}') return mine(resource.careTeam, principal.id);
      return String(resource.id || '') === String(key);
    }
    default: {
      // plain type/id path, e.g. record/r1, bill/*.
      if (dim !== resource.type) return false;
      if (key === undefined || key === '*') return true;
      return String(resource.id || '') === String(key);
    }
  }
}

// --- conditions allowlist (§4): unknown keys → statement does NOT match ---
export function evalConditions(conditions, principal, resource, ctx) {
  const c = conditions || {};
  const now = ctx?.now || new Date();
  for (const [key, val] of Object.entries(c)) {
    switch (key) {
      case 'mfa':
        if (Boolean(val) && !principal.mfa) return false;
        break;
      case 'ip':
        if (Array.isArray(val) && !val.map(String).includes(String(principal.ip || ''))) return false;
        break;
      case 'expires_at':
        if (new Date(val).getTime() < now.getTime()) return false;
        break;
      case 'shift':
        if (val === 'current' && !principal.onShift) return false;
        break;
      case 'time_between': {
        if (!Array.isArray(val) || val.length !== 2) return false;
        const hhmm = now.toTimeString().slice(0, 5);
        if (hhmm < String(val[0]) || hhmm > String(val[1])) return false;
        break;
      }
      case 'dept_in':
        if (Array.isArray(val) && !val.map(String).includes(String(resource.deptId || ''))) return false;
        break;
      case 'ward_in':
        if (Array.isArray(val) && !val.map(String).includes(String(resource.wardId || ''))) return false;
        break;
      case 'careteam_includes_me': {
        if (!val) break;
        const team = resource.careTeam || [];
        if (!team.map(String).includes(String(principal.id))) return false;
        break;
      }
      case 'sensitivity_not':
        if (Array.isArray(val) && val.map(String).includes(String(resource.sensitivity || 'standard'))) return false;
        break;
      case 'reason_required':
        if (val && !ctx?.reason) return false;
        break;
      case 'consent_required':
        if (val && !ctx?.consentGranted) return false;
        break;
      case 'emergency_flag':
        if (Boolean(val) !== Boolean(ctx?.emergency)) return false;
        break;
      default:
        return false; // unknown condition key → statement skipped (fail-closed)
    }
  }
  return true;
}

// --- effective statements (direct + group + role policies), cached ---
const stmtCache = new Map();
const CACHE_TTL_MS = 60_000;
const CACHE_MAX = 1000;

const cacheGet = (key, version) => {
  const hit = stmtCache.get(key);
  if (!hit) return null;
  if (hit.version !== version || hit.at + CACHE_TTL_MS < Date.now()) {
    stmtCache.delete(key);
    return null;
  }
  return hit.statements;
};
const cacheSet = (key, version, statements) => {
  if (stmtCache.size >= CACHE_MAX) stmtCache.delete(stmtCache.keys().next().value);
  stmtCache.set(key, { version, statements, at: Date.now() });
};
export const clearIamCache = () => stmtCache.clear();

export async function effectiveStatements(principal) {
  const version = principal.policyVersion ?? 0;
  const key = `${principal.id}:${version}`;
  const hit = cacheGet(key, version);
  if (hit) return hit;

  const now = new Date();
  const assignments = await IamAssignment.find({
    tenantId: principal.tenantId,
    principalId: principal.id,
    status: 'active',
    $or: [{ expiresAt: null }, { expiresAt: { $gt: now } }],
  }).lean();
  const groupIds = await IamGroup.find({ tenantId: principal.tenantId, memberIds: principal.id })
    .select('_id').lean().then((g) => g.map((x) => x._id));
  const groupAssigns = groupIds.length ? await IamAssignment.find({
    tenantId: principal.tenantId,
    principalType: 'group',
    principalId: { $in: groupIds },
    status: 'active',
  }).lean() : [];

  const policyIds = new Set();
  const roleIds = new Set();
  for (const a of [...assignments, ...groupAssigns]) {
    if (a.policyId) policyIds.add(String(a.policyId));
    if (a.roleId) roleIds.add(String(a.roleId));
  }
  const boundaryIds = new Set();
  if (roleIds.size) {
    const roles = await IamRole.find({ _id: { $in: [...roleIds] } }).select('policyIds boundaryId').lean();
    for (const r of roles) {
      for (const p of (r.policyIds || [])) policyIds.add(String(p));
      if (r.boundaryId) boundaryIds.add(String(r.boundaryId));
    }
  }
  const policies = policyIds.size
    ? await IamPolicy.find({ _id: { $in: [...policyIds] }, status: 'active' }).select('statements').lean()
    : [];
  const statements = policies.flatMap((p) => p.statements || []);
  const boundaryPolicies = boundaryIds.size
    ? await IamPolicy.find({ _id: { $in: [...boundaryIds] }, status: 'active' }).select('statements').lean()
    : [];
  const out = {
    statements,
    boundaryStatements: boundaryPolicies.flatMap((p) => p.statements || []),
    scopes: [...assignments, ...groupAssigns],
  };
  cacheSet(key, version, out);
  return out;
}

// Boundary (§9): intersection — a boundary must ALSO allow. Boundary Deny
// always wins, same as identity Deny.
function withinBoundary(boundaryStatements, action, resource, principal, ctx) {
  let allowed = false;
  for (const s of boundaryStatements) {
    const actions = Array.isArray(s.actions) ? s.actions : [];
    const resources = Array.isArray(s.resources) ? s.resources : [];
    if (!actions.some((a) => matchAction(a, action))) continue;
    if (!resources.some((r) => matchResource(r, resource, principal))) continue;
    if (!evalConditions(s.conditions, principal, resource, ctx)) continue;
    if (s.effect === 'Deny') return false;
    allowed = true;
  }
  return allowed;
}

// --- main decision (§3.1), fail-closed ---
export async function can(principal, action, resource, ctx = {}) {
  try {
    const g = guardrailsAllow(principal, action);
    if (!g.ok) return { allow: false, reason: g.reason };
    if (!principal.isPlatform && String(resource.tenantId || '') !== String(principal.tenantId || '')) {
      return { allow: false, reason: 'tenant-mismatch' };
    }
    const { statements, boundaryStatements } = await effectiveStatements(principal);
    let allowed = false;
    let matchedSid = null;
    for (const s of statements) {
      const actions = Array.isArray(s.actions) ? s.actions : [];
      const resources = Array.isArray(s.resources) ? s.resources : [];
      if (!actions.some((a) => matchAction(a, action))) continue;
      if (!resources.some((r) => matchResource(r, resource, principal))) continue;
      if (!evalConditions(s.conditions, principal, resource, ctx)) continue;
      if (s.effect === 'Deny') return { allow: false, reason: `explicit-deny:${s.sid || 'unnamed'}` };
      allowed = true;
      matchedSid = s.sid || matchedSid;
    }
    if (!allowed) return { allow: false, reason: 'default-deny' };
    if (boundaryStatements.length && !withinBoundary(boundaryStatements, action, resource, principal, ctx)) {
      return { allow: false, reason: 'boundary' };
    }
    // Restricted sensitivity always needs reason + step-up obligation surface.
    const obligations = [];
    if (['restricted'].includes(String(resource.sensitivity || ''))) obligations.push('reason_required', 'step_up');
    return { allow: true, obligations, policy: matchedSid };
  } catch (e) {
    return { allow: false, reason: 'evaluator-error' };
  }
}

// --- query-level scope injection (§3.2): leak roko, fetch-all-then-filter nahi ---
export async function scopeFilter(principal, module = 'records') {
  try {
    const { scopes } = await effectiveStatements(principal);
    const filter = { tenantId: principal.tenantId };
    const depts = new Set();
    const wards = new Set();
    let careTeamOnly = false;
    for (const s of scopes) {
      const sc = s.scope || {};
      for (const d of (sc.deptIds || [])) depts.add(String(d));
      for (const w of (sc.wardIds || [])) wards.add(String(w));
      if (sc.careTeamOnly) careTeamOnly = true;
    }
    if (depts.size) filter.deptId = { $in: [...depts] };
    if (wards.size) filter.wardId = { $in: [...wards] };
    if (careTeamOnly) filter.careTeam = String(principal.id);
    void module;
    return filter;
  } catch {
    return { tenantId: principal.tenantId, _id: null }; // fail-closed: matches nothing
  }
}

/**
 * File 25 §11 step 3 — shadow mode. Runs the new evaluator alongside the
 * legacy authorize() decision WITHOUT enforcing: mismatches are logged for
 * review (1–2 sprints) while the old decision stays binding. Fire-and-forget
 * from routes so it can never break or slow a request.
 */
export async function iamShadow({ principal, action, resource, ctx, oldDecision, route }) {
  try {
    const next = await can(principal, action, resource, ctx);
    if (Boolean(next.allow) !== Boolean(oldDecision)) {
      const { noteShadowMismatch } = await import('../services/iamAccessLogService.js');
      noteShadowMismatch();
      const { default: logger } = await import('../config/logger.js');
      logger.warn(
        `IAM-SHADOW mismatch route=${route} action=${action} `
        + `old=${oldDecision ? 'allow' : 'deny'} new=${next.allow ? 'allow' : 'deny'} `
        + `reason=${next.reason || 'allow'}`,
      );
    }
    return next;
  } catch {
    return { allow: false, reason: 'shadow-error' };
  }
}

/** Builds a best-effort IAM principal from an authenticated request. */
export function principalFromRequest(req, over = {}) {
  const u = req.user || {};
  return {
    id: String(u._id || u.id || ''),
    tenantId: String(u.hospitalId || u.facilityId || ''),
    tenantKind: String(u.tenantKind || ''),
    isOwner: ['hospital_admin', 'superadmin'].includes(u.role),
    roles: [],
    deptIds: u.deptIds || [],
    wardIds: u.wardIds || [],
    careTeamPatientIds: [],
    mfa: Boolean(u.twoFactorEnabled),
    ip: req.ip,
    onShift: true,
    policyVersion: 0,
    ...over,
  };
}

export const IAM_CONDITION_KEYS = [
  'mfa', 'ip', 'expires_at', 'shift', 'time_between', 'dept_in', 'ward_in',
  'careteam_includes_me', 'sensitivity_not', 'reason_required', 'consent_required', 'emergency_flag',
];

/**
 * File 25 §10: quarterly access-certification sweep (Access Review campaigns).
 *
 * The route (POST /iam/reviews) creates a campaign on demand; this sweep is
 * the scheduler half so certification actually happens without someone
 * remembering. Idempotent by (tenantId, cycle): one campaign per tenant per
 * calendar quarter, ever. Reviewer = the tenant's own hospital_admin. A
 * platform superadmin is never used as a cross-tenant fallback reviewer.
 *
 * Exported for BOTH the nightly scheduler and unit tests.
 */
import IamAssignment from '../models/IamAssignment.js';
import AccessReview from '../models/AccessReview.js';
import User from '../models/User.js';
import logger from '../config/logger.js';

export const quarterCycle = (now = new Date()) =>
  `${now.getFullYear()}-Q${Math.floor(now.getMonth() / 3) + 1}-Certification`;

export async function runIamReviewCampaigns(now = new Date()) {
  const cycle = quarterCycle(now);
  let created = 0;
  let skipped = 0;
  try {
    const tenantIds = await IamAssignment.distinct('tenantId', {
      status: 'active',
      tenantId: { $exists: true, $ne: null },
    });
    for (const tenantId of tenantIds) {
      try {
        // eslint-disable-next-line no-await-in-loop
        const exists = await AccessReview.exists({ tenantId, cycle });
        if (exists) { skipped += 1; continue; }
        // eslint-disable-next-line no-await-in-loop
        const active = await IamAssignment.find({ tenantId, status: 'active' }).select('_id').lean();
        if (!active.length) { skipped += 1; continue; }
        // eslint-disable-next-line no-await-in-loop
        const reviewer = await User.findOne({
          $or: [{ hospitalId: tenantId }, { facilityId: tenantId }],
          role: 'hospital_admin',
        });
        if (!reviewer) { skipped += 1; continue; }
        // eslint-disable-next-line no-await-in-loop
        await AccessReview.create({
          tenantId,
          cycle,
          reviewerId: reviewer._id,
          items: active.map((a) => ({ assignmentId: a._id, decision: 'pending', note: '' })),
        });
        created += 1;
      } catch (e) {
        logger.warn(`[iam-review] tenant ${tenantId}: ${e.message}`);
      }
    }
  } catch (e) {
    logger.warn(`[iam-review] sweep failed: ${e.message}`);
  }
  if (created) logger.info(`[iam-review] created ${created} campaign(s) for ${cycle}`);
  return { created, skipped, cycle };
}

const PHI_FIELDS = new Set([
  'name', 'email', 'phone', 'address', 'aadhaar', 'aadhaarNumber',
  'uhid', 'patientId', 'doctorId', 'userId', 'abhaNumber', 'abhaAddress',
  'emergencyContact', 'knownConditions', 'allergies', 'bloodGroup',
  'dateOfBirth', 'gender', 'signatureUrl', 'avatar', 'latitude', 'longitude'
]);

function redactPHI(obj, allowed = new Set()) {
  if (!obj || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map(v => redactPHI(v, allowed));
  const out = {};
  for (const [k, v] of Object.entries(obj)) {
    if (PHI_FIELDS.has(k) && !allowed.has(k)) continue;
    out[k] = redactPHI(v, allowed);
  }
  return out;
}
import { KAFKA_TOPICS, KAFKA_CLIENT_ID, KAFKA_BOOTSTRAP_SERVERS, isKafkaConfigured } from '../config/kafka.js';
import logger from '../config/logger.js';
// DP-M-01: the "validate" in the old validateAndEnvelopEvent validated nothing.
// serializeEvent now checks the payload against the in-repo schema registry
// (src/events/schemaRegistry.js) before anything reaches the wire.
import { serializeEvent } from '../events/schemaRegistry.js';

let kafkaInstance = null;
let producerInstance = null;
let producerConnecting = null;

async function getProducer() {
  if (!isKafkaConfigured()) return null;
  if (producerInstance) return producerInstance;
  if (!producerConnecting) {
    producerConnecting = (async () => {
      const { Kafka } = await import('kafkajs');
      kafkaInstance = new Kafka({ clientId: KAFKA_CLIENT_ID, brokers: KAFKA_BOOTSTRAP_SERVERS });
      const producer = kafkaInstance.producer({
        idempotent: true, // Spec 10: enable.idempotence=true (no dupes on retry)
        maxInFlightRequests: 5,
      });
      await producer.connect();
      producerInstance = producer;
      logger.info('Kafka producer connected (idempotent, acks=-1)');
      return producer;
    })().catch((err) => {
      producerConnecting = null;
      throw err;
    });
  }
  return producerConnecting;
}

/**
 * Publishes an event to the Kafka event backbone.
 * Real broker send when configured (acks=all via idempotent producer);
 * graceful in-memory resolve otherwise.
 *
 * DP-M-01: schema violations now throw EventSchemaValidationError BEFORE any
 * delivery attempt (SCHEMA_ENFORCEMENT=enforce by default) — the outbox poller
 * catches that per event and drives it through the normal retry → DLQ cascade,
 * so an incompatible payload becomes a visible dead-letter instead of a silent
 * consumer no-op. Broker failures rethrow after logging.
 */
export async function emitKafkaEvent(topic, key, payload) {
  const enveloped = serializeEvent(topic, key, payload);

  if (!isKafkaConfigured()) {
    // In local dev without live Kafka cluster, log safely and resolve
    logger.debug(`[EVENT_SPINE_DEV] Topic: ${topic} | Key: ${key} | EventId: ${enveloped.eventId}`);
    return {
      success: true,
      deliveredTo: 'in_memory_spine',
      eventId: enveloped.eventId,
    };
  }

  try {
    const producer = await getProducer();
    const redacted = redactPHI(payload);
    await producer.send({
      topic,
      acks: -1, // Spec 10: all in-sync replicas must acknowledge
      messages: [{ key: enveloped.key, value: JSON.stringify(enveloped) }],
    });
    logger.info(`[KAFKA_PRODUCED] Topic: ${topic} | Key: ${key} | EventId: ${enveloped.eventId}`);
    return {
      success: true,
      deliveredTo: 'kafka_broker',
      eventId: enveloped.eventId,
    };
  } catch (err) {
    logger.error(`Failed to publish event to Kafka [${topic}]: ${err.message}`);
    throw err;
  }
}

export async function disconnectProducer() {
  try {
    await producerInstance?.disconnect();
  } catch {}
  producerInstance = null;
  producerConnecting = null;
  kafkaInstance = null;
}

