import mongoose from 'mongoose';
import Review from '../models/Review.js';
import Provider from '../models/Provider.js';
import User from '../models/User.js';
import ChatReport from '../models/ChatReport.js';
import ModerationItem from '../models/ModerationItem.js';
import Strike from '../models/Strike.js';
import Notification from '../models/Notification.js';
import logger from '../config/logger.js';
import {
  ACTION_VISIBILITY,
  MODERATION_POLICY_VERSION,
  escalationForStrikeCount,
  maxSeverity,
  severityForCategory,
  slaDueAtFor,
} from './moderationRules.js';

/**
 * 8.md §5 + §6 — the model-touching half of moderation.
 *
 * Routes stay thin on purpose: they decide WHO may act and WHEN (authz, the
 * two-person gate, the appeal rules); everything that WRITES to a target row,
 * the queue, or the strike table lives here so the public read path
 * (routes/reviews.js) and the ops queue (routes/moderation.js) cannot drift
 * apart — a review hidden by an auto-flag and a review hidden by a moderator
 * end up with the same `moderationStatus`.
 *
 * Audit rows are written by the ROUTES, not here: this module is also reached
 * from the review-create path, where the route's own `auditLog` already runs
 * and a duplicate trail entry would make the counts lie.
 */

const ACTIVE_STATUSES = ['open', 'in_review', 'appealed'];

const asId = (value) => (mongoose.isValidObjectId(value) ? value : null);

/**
 * 8.md §17 catalogue alignment: categories flagged `adClaimsRestricted`
 * (skin/hair, weight-loss, supplements, IVF success rates, sexual health)
 * auto-escalate any queue item touching them to at least HIGH — banned-claim
 * review cannot sit at routine priority. Fail-open to the computed severity:
 * a catalogue read failure must not block queue entry.
 */
async function adClaimsBoost(category, severity) {
  try {
    if (!category || category === 'other') return severity;
    const { default: Category } = await import('../models/Category.js');
    const cat = await Category.findOne({
      $or: [{ code: category }, { aliases: category }],
    }).select('adClaimsRestricted').lean();
    if (cat?.adClaimsRestricted) return maxSeverity(severity, 'high');
  } catch (err) {
    logger.warn(`adClaims boost lookup failed: ${err?.message}`);
  }
  return severity;
}

/**
 * Auto-flag / report entry point: one OPEN queue row per target, ever.
 *
 * A burst of reports on the same review must not turn into fifty rows that
 * each need their own decision — the second report raises the severity of the
 * row that already exists instead.
 *
 * @returns {Promise<{item: object, created: boolean}>}
 */
export async function ensureModerationItem({
  targetType,
  targetId,
  category = 'other',
  reason = '',
  severity,
  source = 'auto_filter',
  reporterId = null,
  subjectUserId = null,
  subjectProviderId = null,
  note = '',
}) {
  const id = String(targetId);
  const existing = await ModerationItem.findOne({
    targetType,
    targetId: id,
    status: { $in: ACTIVE_STATUSES },
  });

  const nextSeverity = await adClaimsBoost(category, severity || severityForCategory(category));

  if (existing) {
    const raised = maxSeverity(existing.severity, nextSeverity);
    if (raised !== existing.severity) {
      existing.severity = raised;
      existing.slaDueAt = slaDueAtFor(raised, new Date());
      if (note) existing.notes.push({ note, by: reporterId, at: new Date() });
      await existing.save();
    } else if (note) {
      existing.notes.push({ note, by: reporterId, at: new Date() });
      await existing.save();
    }
    return { item: existing, created: false };
  }

  const item = await ModerationItem.create({
    targetType,
    targetId: id,
    category,
    reason,
    severity: nextSeverity,
    status: 'open',
    source,
    reporterId,
    subjectUserId,
    subjectProviderId,
    policyVersion: MODERATION_POLICY_VERSION,
    slaDueAt: slaDueAtFor(nextSeverity, new Date()),
    notes: note ? [{ note, by: reporterId || subjectUserId, at: new Date() }] : [],
  });
  return { item, created: true };
}

/**
 * Push a canned action onto the target row itself. This is the half of "moderation
 * is immediately reflected" that the public read path depends on: a `hide` here
 * is what makes routes/reviews.js stop serving the review.
 *
 * @returns {Promise<{applied: boolean, snapshot: object|null, targetStatus: string|null}>}
 */
export async function applyModerationAction(item, action, { by = null, note = '' } = {}) {
  const visibility = ACTION_VISIBILITY[action];
  if (!visibility) return { applied: false, snapshot: null, targetStatus: null };

  if (item.targetType === 'review') {
    const reviewId = asId(item.targetId);
    if (!reviewId) return { applied: false, snapshot: null, targetStatus: null };
    const before = await Review.findById(reviewId).select('moderationStatus');
    if (!before) return { applied: false, snapshot: null, targetStatus: null };
    await Review.findByIdAndUpdate(reviewId, { moderationStatus: visibility });
    return {
      applied: true,
      snapshot: { moderationStatus: before.moderationStatus || 'visible' },
      targetStatus: visibility,
    };
  }

  if (item.targetType === 'provider_profile') {
    const providerId = asId(item.targetId);
    if (!providerId) return { applied: false, snapshot: null, targetStatus: null };
    const provider = await Provider.findById(providerId).select('status');
    if (!provider) return { applied: false, snapshot: null, targetStatus: null };
    // The directory only serves rows whose status is live/approved, so a
    // suspended row disappears from it. `restore` puts back whatever was there.
    if (visibility === 'visible') {
      const backTo = item.targetSnapshot?.status || provider.status;
      await Provider.findByIdAndUpdate(providerId, { status: backTo });
      return { applied: true, snapshot: null, targetStatus: backTo };
    }
    await Provider.findByIdAndUpdate(providerId, { status: 'suspended' });
    return { applied: true, snapshot: { status: provider.status }, targetStatus: 'suspended' };
  }

  if (item.targetType === 'chat_report') {
    const reportId = asId(item.targetId);
    if (!reportId) return { applied: false, snapshot: null, targetStatus: null };
    const next = visibility === 'visible' ? 'reviewed' : 'action_taken';
    const before = await ChatReport.findById(reportId).select('status');
    if (!before) return { applied: false, snapshot: null, targetStatus: null };
    await ChatReport.findByIdAndUpdate(reportId, { status: next });
    return { applied: true, snapshot: { status: before.status }, targetStatus: next };
  }

  // product_listing / event / article: those catalogues are modelled by other
  // workstreams (10.md §4). The queue row, the action log and the audit entry
  // still happen — enforcement lands the day the model does.
  return { applied: false, snapshot: null, targetStatus: null };
}

/** Undo a destructive action (appeal overturned): put the snapshot back. */
export async function restoreModerationTarget(item, { note = '' } = {}) {
  const restored = await applyModerationAction(item, 'restore', { note });
  return restored;
}

export async function countActiveStrikes(subjectType, subjectId) {
  return Strike.countDocuments({ subjectType, subjectId, status: 'active' });
}

/**
 * 8.md §6: turn an upheld violation into a permanent strike and climb the
 * threshold table (see STRIKE_THRESHOLDS in moderationRules.js).
 *
 * @returns {Promise<{strike: object, activeCount: number, level: string, applied: string[]}>}
 */
export async function issueStrike({ item, by, note = '' }) {
  const subject = resolveStrikeSubject(item);
  if (!subject) {
    throw new Error('Moderation item has no strike subject (author or provider unknown)');
  }

  const activeCount = await countActiveStrikes(subject.subjectType, subject.subjectId);
  const level = escalationForStrikeCount(activeCount + 1, subject.subjectType);

  const strike = await Strike.create({
    subjectType: subject.subjectType,
    subjectId: subject.subjectId,
    providerId: subject.providerId,
    userId: subject.userId,
    moderationItemId: item._id,
    targetType: item.targetType,
    category: item.category,
    severity: item.severity,
    reason: note || item.reason,
    issuedBy: by,
    status: 'active',
    level,
    policyVersion: MODERATION_POLICY_VERSION,
  });

  const applied = await applyStrikeEscalation({ subject, level });
  return { strike, activeCount: activeCount + 1, level, applied };
}

function resolveStrikeSubject(item) {
  if (item.targetType === 'provider_profile') {
    const providerId = asId(item.targetId);
    if (providerId) {
      return { subjectType: 'provider', subjectId: providerId, providerId, userId: item.subjectUserId || null };
    }
  }
  if (item.subjectProviderId) {
    const providerId = asId(item.subjectProviderId);
    if (providerId) {
      return { subjectType: 'provider', subjectId: providerId, providerId, userId: item.subjectUserId || null };
    }
  }
  const userId = asId(item.subjectUserId);
  if (userId) return { subjectType: 'user', subjectId: userId, providerId: null, userId };
  return null;
}

/**
 * Climb (never fall) to the level the strike count demands:
 *   warning           → in-app notice only
 *   listing_suspension → provider delisted directory-wide
 *   account_suspension → owner (or the user) blocked platform-wide
 */
async function applyStrikeEscalation({ subject, level }) {
  const applied = [];
  if (subject.subjectType === 'provider') {
    if (level === 'listing_suspension' || level === 'account_suspension') {
      await Provider.findByIdAndUpdate(subject.subjectId, { status: 'suspended' });
      applied.push('provider_suspended');
    }
    if (level === 'account_suspension' && subject.userId) {
      await User.findByIdAndUpdate(subject.userId, { status: 'blocked' });
      applied.push('owner_account_blocked');
    }
  } else if (level === 'account_suspension') {
    await User.findByIdAndUpdate(subject.subjectId, { status: 'blocked' });
    applied.push('user_account_blocked');
  }
  return applied;
}

/**
 * After an appeal overturns a strike, drop back to the level the REMAINING
 * active strikes justify — and only un-suspend what this strike suspended.
 */
export async function recomputeStrikeEscalation(strike) {
  const remaining = await countActiveStrikes(strike.subjectType, strike.subjectId);
  const level = escalationForStrikeCount(remaining, strike.subjectType);

  const needsListingBack = ['listing_suspension', 'account_suspension'].includes(strike.level)
    && !['listing_suspension', 'account_suspension'].includes(level);
  const needsAccountBack = strike.level === 'account_suspension' && level !== 'account_suspension';

  if (strike.subjectType === 'provider') {
    if (needsListingBack && strike.providerId) {
      await Provider.findByIdAndUpdate(strike.providerId, { status: 'approved' });
    }
    if (needsAccountBack && strike.userId) {
      await User.findByIdAndUpdate(strike.userId, { status: 'active' });
    }
  } else if (needsAccountBack) {
    await User.findByIdAndUpdate(strike.subjectId, { status: 'active' });
  }
  return { remaining, level };
}

const STRIKE_COPY = {
  warning: {
    title: 'Community guideline warning',
    message: 'One of your posts or listings was found to violate the FindMedi content policy. Another upheld violation can lead to a suspension.',
  },
  listing_suspension: {
    title: 'Listing suspended',
    message: 'Your FindMedi listing has been suspended after repeated policy violations. Contact support to appeal.',
  },
  account_suspension: {
    title: 'Account suspended',
    message: 'Your FindMedi account has been suspended after repeated policy violations. Contact support to appeal.',
  },
};

/**
 * In-app notice (8.md §3 "suspend/unsuspend … notify"). Never throws: a
 * notification failure must not roll back a moderation decision that already
 * took effect.
 */
export async function notifySubject(userId, title, message, referenceId) {
  if (!userId) return null;
  try {
    return await Notification.create({
      userId: String(userId),
      title,
      message,
      type: 'system',
      referenceId: referenceId ? String(referenceId) : null,
    });
  } catch (err) {
    logger.warn(`moderation notification failed: ${err.message}`);
    return null;
  }
}

export async function notifyStrike(subjectUserId, level, referenceId) {
  const copy = STRIKE_COPY[level] || STRIKE_COPY.warning;
  return notifySubject(subjectUserId, copy.title, copy.message, referenceId);
}

/**
 * 8.md §5 (Content & UGC moderation) + §6 (Trust & Safety) — the RULES.
 *
 * This module is deliberately PURE: no mongoose model, no request, no I/O. It
 * is the single definition of
 *
 *   - the queue vocabulary (target type / category / severity / status /
 *     canned action) that the ModerationItem schema and the request schemas in
 *     utils/validate.js both pin to,
 *   - the auto-filters of 8.md §5.2 (keyword + regex detectors for abuse, PII
 *     and medical/advert claims — no external API, so a flag can never be
 *     blocked by a vendor outage),
 *   - the SLA clock per severity (§5.2 "SLA"), and
 *   - the strike → escalation thresholds of §6, written as a table a reviewer
 *     can read instead of a pile of magic numbers.
 *
 * The model-touching half (queue writes, target enforcement, strikes) lives in
 * ./moderationActions.js so that this file stays importable from anywhere —
 * including utils/validate.js — without registering a mongoose model as a side
 * effect of request validation.
 */

/** Bump when a rule below changes: every queue row records the version it was judged under. */
export const MODERATION_POLICY_VERSION = '2026.10-8md5';

/** 8.md §5.1 queues. `chat_report` is the moderation lane for ChatReport rows. */
export const MODERATION_TARGET_TYPES = [
  'review', 'provider_profile', 'product_listing', 'event', 'article', 'chat_report',
];

export const MODERATION_CATEGORIES = [
  // Auto-detected by analyzeContent():
  'abuse', 'pii', 'medical_claim', 'misleading', 'crisis', 'spam',
  // Reported / ops-assigned only:
  'verified_booking', 'defamation', 'copyright', 'other',
];

export const MODERATION_SEVERITIES = ['low', 'medium', 'high', 'critical'];
export const MODERATION_STATUSES = ['open', 'in_review', 'actioned', 'dismissed', 'appealed'];

/** 8.md §5.2 "canned actions" — the only verbs a moderator may take. */
export const MODERATION_ACTIONS = [
  'hide', 'restore', 'shadow_hide', 'remove', 'warn_user', 'escalate', 'strike',
];

/**
 * Actions that make content (or a livelihood) disappear. These are the ones
 * that may need a second pair of eyes — see needsSecondReviewer().
 */
export const DESTRUCTIVE_ACTIONS = ['hide', 'shadow_hide', 'remove', 'strike'];

/** Content-level impact per action, applied to the target row (moderationActions.js). */
export const ACTION_VISIBILITY = {
  hide: 'hidden',
  shadow_hide: 'shadow_hidden',
  remove: 'removed',
  restore: 'visible',
  warn_user: 'visible',
  escalate: 'visible',
  strike: 'visible',
};

// ── 8.md §5.2 — second reviewer for high-severity / destructive actions ──────
//
// Two-person rule, mirroring routes/adminApplications.js: the FIRST reviewer
// parks the action (nothing happens to the content), and only a SECOND,
// different reviewer can let it take effect.
//
//   action is destructive AND (severity is high|critical)  → second reviewer
//   action is a strike (hits the provider's income)        → second reviewer,
//                                                            regardless of severity
//
// Low/medium `hide` — the everyday first-line takedown — stays single-reviewer,
// or the queue could never drain.
export const needsSecondReviewer = (severity, action) => {
  if (action === 'strike') return true;
  return DESTRUCTIVE_ACTIONS.includes(action) && (severity === 'high' || severity === 'critical');
};

// ── 8.md §5.2 — SLA (dueAt computed from severity) ──────────────────────────
export const SLA_HOURS = { low: 72, medium: 48, high: 24, critical: 8 };

export const slaHoursFor = (severity) => SLA_HOURS[severity] ?? SLA_HOURS.medium;

export const slaDueAtFor = (severity, from = new Date()) => (
  new Date(from.getTime() + slaHoursFor(severity) * 60 * 60 * 1000)
);

/** Queue rows past their clock while still being worked. */
export const isOverdue = (item, now = Date.now()) => (
  ['open', 'in_review', 'appealed'].includes(item.status)
  && item.slaDueAt instanceof Date
  && item.slaDueAt.getTime() < now
);

// ── 8.md §6 — strike thresholds (documented, configurable in one place) ──────
//
//   active strikes │ provider subject                │ user subject
//   ───────────────┼─────────────────────────────────┼────────────────────────
//   1              │ warning (in-app notice)         │ warning (in-app notice)
//   2              │ LISTING suspension (delisted    │ — (the warning stands)
//   3              │   directory-wide)               │ ACCOUNT suspension
//   4+             │ ACCOUNT suspension (owner       │   (status: blocked)
//                  │   blocked + listing suspended)  │
//
// Strikes are PERMANENT records: they never decay, are never deleted, and an
// appeal can only overturn one (status: overturned) — the row stays as the
// evidence of what was decided and why.
export const STRIKE_THRESHOLDS = {
  warn: 1,
  suspendListing: 2,
  suspendAccount: 3,
};

export const STRIKE_LEVELS = ['warning', 'listing_suspension', 'account_suspension'];

export const escalationForStrikeCount = (count, subjectType) => {
  if (count >= STRIKE_THRESHOLDS.suspendAccount) return 'account_suspension';
  if (subjectType === 'provider' && count >= STRIKE_THRESHOLDS.suspendListing) return 'listing_suspension';
  if (count >= STRIKE_THRESHOLDS.warn) return 'warning';
  return 'none';
};

// ── 8.md §5.2 — auto-filters (keyword/regex; no external calls) ─────────────
//
// Deliberately conservative: a detector only RANKS a row into the queue, it
// never removes content by itself — removal needs the canned action, which is
// (for these severities) a two-person decision.

export const ABUSE_PATTERNS = [
  { label: 'insult', re: /\b(?:idiot|moron|imbecile|stupid|loser|pathetic|worthless|useless|clown)\b/i },
  { label: 'fraud-allegation', re: /\b(?:scammer|scam|fraudster|fraudulent|cheat|liar|thief|extortion)\b/i },
  { label: 'hostility', re: /\b(?:shut\s*up|get\s*lost|screw\s*you|back\s*off|go\s*away)\b/i },
  { label: 'profanity', re: /\b(?:bastard|bloody|damned|damn)\b/i },
  { label: 'threat', re: /\b(?:kill|beat|attack|hurt)\s+(?:you|him|her|them|your)\b/i },
];

/** 8.md §6 "Crisis escalation": flagged for HUMAN review, never auto-ban. */
export const CRISIS_PATTERNS = [
  {
    label: 'self-harm',
    re: /\b(?:suicide|suicidal|kill\s*myself|end\s*my\s*life|want\s*to\s*die|self[-\s]?harm|cut\s*myself|hanging\s*myself)\b/i,
  },
];

// Order matters: a 12-digit Aadhaar must not be re-read as a 10-digit phone.
export const PII_PATTERNS = [
  { label: 'email', re: /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/ },
  { label: 'aadhaar', re: /\b\d{4}[\s-]\d{4}[\s-]\d{4}\b|\b\d{12}\b/ },
  { label: 'pan', re: /\b[A-Z]{5}\d{4}[A-Z]\b/ },
  { label: 'phone', re: /(?:\+?91[\s-]?)?\b[6-9]\d{4}[\s-]?\d{5}\b/ },
  { label: 'phone_10d', re: /\b\d{10}\b/ },
];

// 8.md §5.1: "banned claims (cures diabetes)", Drugs & Magic Remedies / ASCI.
export const MEDICAL_CLAIM_PATTERNS = [
  {
    label: 'guaranteed-cure',
    re: /\b(?:100\s*%|100\s*percent|guaranteed?|assured)\s+(?:cure|relief|recovery|results?|success)\b/i,
  },
  {
    label: 'cure-claim',
    re: /\b(?:cure[sd]?|heal[sd]?|permanent(?:ly)?\s+(?:cure|relief|treatment|solution))\b[^.!?]{0,60}\b(?:diabetes|cancer|arthritis|asthma|hiv|aids|obesity|insomnia|depression|anxiety|hypertension|thyroid|pcod|psoriasis|eczema|kidney|liver|heart\s*disease|blood\s*pressure|sugar|hair\s*fall|baldness)\b/i,
  },
  {
    label: 'miracle-claim',
    re: /\b(?:miracle\s+cure|magic\s+cure|wonder\s+drug|no\s+side[-\s]?effects?|100\s*%\s*safe)\b/i,
  },
  {
    label: 'absolute-result',
    re: /\b(?:works\s+in\s+\d+\s+days|result\s+guaranteed|permanently\s+remove)\b/i,
  },
];

/** 8.md §5.1 events/camps: misleading "free test" promotions. */
export const MISLEADING_PATTERNS = [
  { label: 'free-test-claim', re: /\bfree\s+(?:tests?|checkups?|screenings?|medicines?)\b/i },
];

const CATEGORY_SEVERITY = {
  crisis: 'critical',
  pii: 'high',
  medical_claim: 'high',
  defamation: 'high',
  abuse: 'medium',
  misleading: 'medium',
  spam: 'low',
  copyright: 'medium',
  verified_booking: 'medium',
  other: 'low',
};

export const severityForCategory = (category) => CATEGORY_SEVERITY[category] || 'medium';

const SEVERITY_RANK = { low: 0, medium: 1, high: 2, critical: 3 };

export const maxSeverity = (...severities) => severities.reduce(
  (acc, s) => ((SEVERITY_RANK[s] ?? 0) > (SEVERITY_RANK[acc] ?? 0) ? s : acc),
  'low',
);

/** Mask a match before it is stored on a queue row (reviewer sees shape, not value). */
export const maskMatch = (value) => {
  const str = String(value ?? '');
  if (str.length <= 4) return '•'.repeat(str.length);
  const keepTail = str.length - 4 > 12 ? 12 : str.length - 4;
  return `${str.slice(0, 2)}${'•'.repeat(keepTail)}${str.slice(-2)}`;
};

/**
 * Run every auto-filter over one piece of user-generated text.
 *
 * @param {string} raw
 * @param {object} [options]
 * @param {string} [options.targetType] booking-gated lanes flag `verified_booking` separately
 * @returns {{flagged: boolean, categories: string[], severity: string, findings: Array<{category: string, label: string, sample: string}>}}
 */
export function analyzeContent(raw, options = {}) {
  const text = String(raw ?? '').slice(0, 5000);
  const findings = [];
  const seen = new Set();

  const scan = (patterns, category) => {
    if (seen.has(category)) return;
    for (const { label, re } of patterns) {
      const match = text.match(re);
      if (match) {
        seen.add(category);
        findings.push({ category, label, sample: maskMatch(match[0]) });
        return;
      }
    }
  };

  scan(CRISIS_PATTERNS, 'crisis');
  scan(PII_PATTERNS, 'pii');
  scan(MEDICAL_CLAIM_PATTERNS, 'medical_claim');
  scan(MISLEADING_PATTERNS, 'misleading');
  scan(ABUSE_PATTERNS, 'abuse');

  const categories = findings.map((f) => f.category);
  return {
    flagged: categories.length > 0,
    categories,
    severity: categories.length ? maxSeverity(...categories.map(severityForCategory)) : 'low',
    findings,
    targetType: options.targetType,
  };
}

/**
 * Headless-Chromium print render pipeline (D6).
 * Renders HTML/CSS templates into print-ready PDF buffers via Playwright Chromium.
 *
 * Security & Reliability features:
 * - Network isolation: blocks all outgoing requests except data: and about: schemes.
 * - Strict timeout: 20s execution cap per render job.
 * - Buffer limit: 10MB maximum PDF output size.
 * - Browser lifecycle: reused browser instance with isolated contexts per render.
 */

import logger from '../config/logger.js';

const MAX_PDF_BYTES = 10 * 1024 * 1024; // 10MB cap
const RENDER_TIMEOUT_MS = 20000; // 20s timeout

let browserInstance = null;
let browserPromise = null;

/**
 * Checks if PDF rendering is enabled in the current environment.
 */
export function isPdfRenderAvailable() {
  return process.env.PDF_RENDER_DISABLED !== '1';
}

/**
 * Returns the active shared Playwright Chromium browser instance.
 */
export async function getBrowser() {
  if (process.env.PDF_RENDER_DISABLED === '1') {
    throw new Error('PDF_RENDER_DISABLED');
  }

  if (browserInstance && browserInstance.isConnected()) {
    return browserInstance;
  }

  if (browserPromise) {
    return browserPromise;
  }

  browserPromise = (async () => {
    try {
      const { chromium } = await import('playwright');
      const args = [
        '--disable-dev-shm-usage',
        '--disable-gpu',
        '--disable-extensions',
      ];

      if (process.env.PDF_RENDER_NO_SANDBOX === '1' || process.platform === 'linux') {
        args.push('--no-sandbox', '--disable-setuid-sandbox');
      }

      const instance = await chromium.launch({
        headless: true,
        args,
      });

      instance.on('disconnected', () => {
        logger.info('[pdfRender] Browser instance disconnected.');
        browserInstance = null;
        browserPromise = null;
      });

      browserInstance = instance;
      return browserInstance;
    } catch (err) {
      browserPromise = null;
      logger.error(`[pdfRender] Failed to launch Chromium browser: ${err.message}`);
      throw err;
    }
  })();

  return browserPromise;
}

/**
 * Cleanly closes the active Chromium browser instance (used during test teardown or worker exit).
 */
export async function closeBrowser() {
  if (browserInstance) {
    try {
      await browserInstance.close();
    } catch (err) {
      logger.warn(`[pdfRender] Error closing browser: ${err.message}`);
    } finally {
      browserInstance = null;
      browserPromise = null;
    }
  }
}

/**
 * Renders HTML + CSS string into a print-ready PDF buffer.
 *
 * @param {object} params
 * @param {string} params.html - Complete HTML string or fragment
 * @param {string} [params.css] - Supplementary stylesheet
 * @param {object} [params.pageSetup] - Page size, margins, orientation
 * @returns {Promise<Buffer>} - Rendered PDF buffer
 */
export async function renderHtmlToPdf({ html, css = '', pageSetup = {} } = {}) {
  if (!html || typeof html !== 'string') {
    throw new Error('html string is required for PDF render');
  }

  if (!isPdfRenderAvailable()) {
    throw new Error('PDF_RENDER_DISABLED');
  }

  const browser = await getBrowser();
  const context = await browser.newContext();

  try {
    const page = await context.newPage();

    // D6 Security Rule: block all outbound network requests except inline data: & about:
    await page.route('**/*', (route) => {
      const url = route.request().url();
      if (url.startsWith('data:') || url.startsWith('about:')) {
        return route.continue();
      }
      return route.abort();
    });

    // Assemble final markup
    let finalHtml = html;
    if (css && css.trim()) {
      if (finalHtml.includes('</head>')) {
        finalHtml = finalHtml.replace('</head>', `<style>${css}</style></head>`);
      } else {
        finalHtml = `<style>${css}</style>${finalHtml}`;
      }
    }

    // Set page content with strict timeout
    await page.setContent(finalHtml, {
      waitUntil: 'load',
      timeout: RENDER_TIMEOUT_MS,
    });

    const format = pageSetup.format || 'A4';
    const margin = pageSetup.margin || {
      top: '12mm',
      right: '12mm',
      bottom: '12mm',
      left: '12mm',
    };

    const pdfBuffer = await page.pdf({
      format,
      margin,
      printBackground: true,
      preferCSSPageSize: true,
      timeout: RENDER_TIMEOUT_MS,
    });

    if (!pdfBuffer || !pdfBuffer.length) {
      throw new Error('Empty PDF buffer produced by renderer');
    }

    if (pdfBuffer.length > MAX_PDF_BYTES) {
      throw new Error(`Rendered PDF exceeds 10MB limit (${pdfBuffer.length} bytes)`);
    }

    return Buffer.isBuffer(pdfBuffer) ? pdfBuffer : Buffer.from(pdfBuffer);
  } finally {
    try {
      await context.close();
    } catch {}
  }
}

/**
 * File 14 §14.2: print render pipeline (no headless browser needed).
 * Handlebars (sandboxed: only registered safe helpers) → sanitize-html →
 * HTML for browser print (`window.print` + @page CSS) or ESC/POS text for
 * thermal. Variable registry per docType; unknown variables block publish.
 */
import Handlebars from 'handlebars';
import sanitizeHtml from 'sanitize-html';
import crypto from 'node:crypto';

// Typed variable registry per document type (admin can't reference ghosts).
export const VARIABLE_REGISTRY = {
  bill: ['patient.name', 'bill.invoiceId', 'bill.amount', 'bill.paid', 'bill.balance', 'bill.date', 'hospital.name'],
  token: ['token.number', 'token.department', 'token.room', 'patient.name', 'hospital.name'],
  label: ['code', 'title', 'subtitle', 'hospital.name'],
  wristband: ['patient.name', 'patient.uhid', 'patient.ageSex', 'ward', 'bed', 'allergyFlag', 'hospital.name'],
  discharge: ['patient.name', 'admission.id', 'doctor.name', 'hospital.name'],
  prescription: ['patient.name', 'doctor.name', 'medicines', 'hospital.name'],
};

const inWordsIndian = (n) => {
  n = Math.round(Number(n) || 0);
  if (!n) return 'Zero';
  const ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
  const two = (x) => (x < 20 ? ones[x] : `${tens[Math.floor(x / 10)]}${x % 10 ? ` ${ones[x % 10]}` : ''}`);
  const three = (x) => `${x >= 100 ? `${ones[Math.floor(x / 100)]} Hundred${x % 100 ? ' ' : ''}` : ''}${x % 100 ? two(x % 100) : ''}`;
  let out = '';
  const cr = Math.floor(n / 1e7);
  const lk = Math.floor((n % 1e7) / 1e5);
  const th = Math.floor((n % 1e5) / 1e3);
  const rest = n % 1e3;
  if (cr) out += `${two(cr)} Crore `;
  if (lk) out += `${two(lk)} Lakh `;
  if (th) out += `${two(th)} Thousand `;
  if (rest) out += three(rest);
  return `${out.trim()} Rupees Only`;
};

let helpersRegistered = false;
const ensureHelpers = () => {
  if (helpersRegistered) return;
  helpersRegistered = true;
  Handlebars.registerHelper('inWords', (v) => inWordsIndian(v));
  Handlebars.registerHelper('date', (v) => (v ? new Date(v).toLocaleDateString('en-IN') : ''));
  Handlebars.registerHelper('upper', (v) => String(v || '').toUpperCase());
  Handlebars.registerHelper('t', (key, options) => {
    const lang = options?.data?.root?.lang || options?.hash?.lang || 'en';
    if (lang === 'hi' && options?.hash?.hi) return options.hash.hi;
    return options?.hash?.en || key;
  });
};

/** Lint: every {{variable}} must exist in the docType registry. */
export function lintTemplate(docType, html) {
  const allowed = VARIABLE_REGISTRY[docType] || [];
  const tokens = new Set();
  const re = /\{\{\s*([#/^>]?)([a-zA-Z0-9_.\s]+?)\s*\}\}/g;
  let m;
  while ((m = re.exec(html || '')) !== null) {
    const name = m[2].trim().split(/\s+/)[0];
    if (['each', 'if', 'else', 't'].includes(name)) continue;
    if (name === 'this' || name.startsWith('this.')) continue;
    tokens.add(name);
  }
  const unknown = [...tokens].filter((t) => !allowed.includes(t)
    && !allowed.some((a) => t.startsWith(`${a}.`)));
  // Built-in helpers are always allowed.
  const helpers = new Set(['inWords', 'date', 'upper']);
  return unknown.filter((t) => !helpers.has(t.split('.')[0]));
}

export function renderTemplate(html, css, data, { duplicate = false, lang = 'en' } = {}) {
  ensureHelpers();
  const templateData = { lang, ...(data || {}) };
  const body = Handlebars.compile(html || '')(templateData);
  const safe = sanitizeHtml(body, {
    allowedTags: sanitizeHtml.defaults.allowedTags.concat(['h1', 'h2', 'style', 'table', 'thead', 'tbody', 'tr', 'td', 'th', 'div', 'span', 'img', 'br', 'hr', 'p']),
    allowedAttributes: false,
  });
  const mark = duplicate
    ? '<div style="position:fixed;top:40%;width:100%;text-align:center;font-size:64px;color:rgba(0,0,0,.12);transform:rotate(-20deg)">DUPLICATE COPY</div>' : '';
  const fontStyle = lang === 'hi'
    ? "@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+Devanagari:wght@400;600;700&display=swap'); body { font-family: 'Noto Sans Devanagari', sans-serif; }"
    : '';
  const full = `<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><style>@page{size:A4;margin:12mm} ${fontStyle} ${css || ''}</style></head><body>${mark}${safe}</body></html>`;
  const hash = crypto.createHash('sha256').update(full).digest('hex');
  return { html: full, hash };
}

/** Minimal ESC/POS text for thermal receipts (58/80mm). */
export function toEscPos(lines) {
  const out = ['\x1B\x40', '\x1B\x61\x01'];
  for (const line of (lines || []).slice(0, 60)) out.push(`${String(line).slice(0, 42)}\n`);
  out.push('\n\n\n\x1D\x56\x00');
  return out.join('');
}

// BullMQ job queues over the existing Redis (Phase 3 roadmap).
// Fail-soft by design: without REDIS_URL everything degrades to direct
// execution — the API never depends on the queue being up.
//
// Queues:
//   findmedi-notifications — email sending (Brevo), incl. PDF attachments
//   findmedi-pdf          — reserved: heavy PDF generation (wired next)
//   findmedi-exports      — reserved: bulk CSV/Excel exports (wired next)
//
// Retry policy: 3 attempts, exponential backoff. Completed jobs are trimmed,
// failed jobs are kept (failed set = dead-letter visibility in Bull Board).

import logger from '../config/logger.js';

export const QUEUE_NAMES = {
  notifications: 'findmedi-notifications',
  pdf: 'findmedi-pdf',
  exports: 'findmedi-exports',
};

const DEFAULT_JOB_OPTS = {
  attempts: 3,
  backoff: { type: 'exponential', delay: 5000 },
  removeOnComplete: 1000,
  removeOnFail: 5000,
};

let connection = null;
let queues = {};
let disabledReason = null;

function redisUrl() {
  return process.env.REDIS_URL || 'redis://localhost:6379';
}

export function isQueuesEnabled() {
  return !!process.env.REDIS_URL;
}

async function getConnection() {
  if (connection) return connection;
  if (disabledReason) return null;
  if (!isQueuesEnabled()) {
    disabledReason = 'REDIS_URL unset';
    return null;
  }
  try {
    const { default: IORedis } = await import('ioredis');
    connection = new IORedis(redisUrl(), {
      // Required by BullMQ (blocking connections must not time out commands)
      maxRetriesPerRequest: null,
      enableReadyCheck: false,
    });
    connection.on('error', (err) => logger.warn(`[queues] redis error: ${err.message}`));
    return connection;
  } catch (err) {
    disabledReason = err.message;
    logger.warn(`[queues] disabled: ${err.message}`);
    return null;
  }
}

export async function getQueue(name) {
  if (queues[name]) return queues[name];
  const conn = await getConnection();
  if (!conn) return null;
  try {
    const { Queue } = await import('bullmq');
    queues[name] = new Queue(name, { connection: conn, defaultJobOptions: DEFAULT_JOB_OPTS });
    return queues[name];
  } catch (err) {
    logger.warn(`[queues] Queue(${name}) unavailable: ${err.message}`);
    return null;
  }
}

/** Generic enqueue. Never throws — returns { queued:false } when down. */
export async function enqueue(queueName, jobName, payload, opts = {}) {
  try {
    const q = await getQueue(queueName);
    if (!q) return { queued: false, reason: disabledReason || 'queues disabled' };
    const job = await q.add(jobName, payload, opts.jobId ? { jobId: opts.jobId } : undefined);
    return { queued: true, jobId: job.id };
  } catch (err) {
    logger.warn(`[queues] enqueue(${queueName}) failed: ${err.message}`);
    return { queued: false, reason: err.message };
  }
}

/** Enqueue an email job. Never throws — returns { queued:false } when down. */
export async function enqueueEmail(payload) {
  try {
    const q = await getQueue(QUEUE_NAMES.notifications);
    if (!q) return { queued: false, reason: disabledReason || 'queues disabled' };
    const job = await q.add('send-email', payload, { jobId: payload.jobId });
    return { queued: true, jobId: job.id };
  } catch (err) {
    logger.warn(`[queues] enqueueEmail failed, caller should send directly: ${err.message}`);
    return { queued: false, reason: err.message };
  }
}

/**
 * Preferred call-site helper: queue the email when possible, otherwise send
 * it inline. Response contract matches sendEmail ({ success }).
 */
export async function queueEmailOrSend(payload) {
  const res = await enqueueEmail(payload);
  if (res.queued) return { success: true, queued: true, jobId: res.jobId };
  const { sendEmail } = await import('../services/notificationService.js');
  return sendEmail(payload);
}

export async function enqueuePdf(payload) {
  return enqueue(QUEUE_NAMES.pdf, 'generate-pdf', payload);
}

export async function enqueueExport(payload) {
  return enqueue(QUEUE_NAMES.exports, 'run-export', payload);
}

/** Poll a job: { state, result?, failedReason? } — null when queue/job missing. */
export async function getJobState(queueName, jobId) {
  try {
    const q = await getQueue(queueName);
    if (!q || !jobId) return null;
    const job = await q.getJob(jobId);
    if (!job) return { state: 'unknown' };
    const state = await job.getState();
    const out = { state };
    if (state === 'completed') out.result = job.returnvalue || null;
    if (state === 'failed') out.failedReason = job.failedReason || 'failed';
    if (job.timestamp) out.enqueuedAt = new Date(job.timestamp).toISOString();
    if (job.processedOn) out.startedAt = new Date(job.processedOn).toISOString();
    if (job.finishedOn) out.finishedAt = new Date(job.finishedOn).toISOString();
    return out;
  } catch (err) {
    logger.warn(`[queues] getJobState failed: ${err.message}`);
    return null;
  }
}

export async function queueStatus() {
  if (!isQueuesEnabled()) return { enabled: false, reason: 'REDIS_URL unset' };
  try {
    const out = { enabled: true, queues: {} };
    for (const name of Object.values(QUEUE_NAMES)) {
      const q = await getQueue(name);
      if (!q) {
        out.queues[name] = { error: 'unavailable' };
        continue;
      }
      const [waiting, active, delayed, failed] = await Promise.all([
        q.getWaitingCount(),
        q.getActiveCount(),
        q.getDelayedCount(),
        q.getFailedCount(),
      ]);
      out.queues[name] = { waiting, active, delayed, failed };
    }
    return out;
  } catch (err) {
    return { enabled: true, error: err.message };
  }
}

export async function closeQueues() {
  for (const q of Object.values(queues)) {
    try { await q.close(); } catch {}
  }
  queues = {};
  if (connection) {
    try { await connection.quit(); } catch {}
    connection = null;
  }
}

/**
 * Spec 24 §4 — receipt authenticity without image deps: HMAC-SHA256 of the
 * transaction ref (server secret), verifiable via GET /api/transactions/verify/:id.
 */
import crypto from 'crypto';

const SECRET = process.env.JWT_SECRET || 'findmedi-receipt-fallback-secret';

export function signTxnRef(transactionRef) {
  return crypto
    .createHmac('sha256', SECRET)
    .update(String(transactionRef || ''))
    .digest('hex')
    .slice(0, 16)
    .toUpperCase();
}

export function verifyTxnHash(transactionRef, hash) {
  if (!transactionRef || !hash) return false;
  const expected = signTxnRef(transactionRef);
  const a = Buffer.from(String(hash).toUpperCase());
  const b = Buffer.from(expected);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

import crypto from 'crypto';
import User from '../models/User.js';
import Hospital from '../models/Hospital.js';
import AuditLog from '../models/AuditLog.js';
import bcrypt from 'bcryptjs';

const IDLE_LOCK_WINDOW_MS = Number(process.env.IDLE_LOCK_WINDOW_MS || 15 * 60 * 1000);
const SHIFT_BOUND_WINDOW_MS = Number(process.env.SHIFT_BOUND_WINDOW_MS || 30 * 60 * 1000);
const MAX_FAILED_PIN_ATTEMPTS = Number(process.env.MAX_FAILED_PIN_ATTEMPTS || 5);

const DEVICE_ALLOWLIST_TTL_MS = Number(process.env.DEVICE_ALLOWLIST_TTL_MS || 30 * 24 * 60 * 60 * 1000);

export function hashChain(previousHash, payload) {
  const input = `${previousHash || 'genesis'}|${JSON.stringify(payload)}|${Date.now()}`;
  return crypto.createHash('sha256').update(input).digest('hex');
}

export async function logAuditHashChain(action, userId, payload, ip, userAgent) {
  const lastLog = await AuditLog.findOne({ action: 'hash_chain' }).sort({ createdAt: -1 }).lean();
  const chainHash = hashChain(lastLog?.payload?.chainHash, payload);
  await AuditLog.create({
    action: 'hash_chain',
    actor: userId,
    payload: { ...payload, chainHash, prevHash: lastLog?.payload?.chainHash },
    ip,
    userAgent,
    severity: 'info',
  });
  return chainHash;
}

export function checkIdleLock(user) {
  if (!user.lastActivityAt) return { locked: false };
  const idleMs = Date.now() - new Date(user.lastActivityAt).getTime();
  if (idleMs > IDLE_LOCK_WINDOW_MS) {
    return { locked: true, idleMinutes: Math.floor(idleMs / 60000) };
  }
  return { locked: false };
}

export function checkShiftBound(user, shiftStart) {
  if (!shiftStart) return { allowed: true };
  const now = Date.now();
  const shiftStartMs = new Date(shiftStart).getTime();
  const windowStart = shiftStartMs - SHIFT_BOUND_WINDOW_MS;
  const windowEnd = shiftStartMs + SHIFT_BOUND_WINDOW_MS;
  if (now < windowStart || now > windowEnd) {
    return { allowed: false, reason: 'Outside shift window' };
  }
  return { allowed: true };
}

export async function checkDeviceAllowList(userId, deviceFingerprint, ip) {
  const user = await User.findById(userId).select('allowedDevices').lean();
  if (!user?.allowedDevices?.length) return { allowed: true, reason: 'No allowlist configured' };
  const now = Date.now();
  const device = user.allowedDevices.find((d) => d.fingerprint === deviceFingerprint && (now - d.createdAt < DEVICE_ALLOWLIST_TTL_MS));
  if (!device) return { allowed: false, reason: 'Device not in allowlist' };
  return { allowed: true, deviceId: device._id };
}

export async function checkIpAllowList(userId, ip) {
  const user = await User.findById(userId).select('allowedIps').lean();
  if (!user?.allowedIps?.length) return { allowed: true, reason: 'No IP allowlist configured' };
  const allowed = user.allowedIps.some((allowedIp) => {
    if (allowedIp.includes('/')) {
      const [base, bits] = allowedIp.split('/');
      const mask = ~0 << (32 - parseInt(bits, 10));
      const ipNum = ipToNumber(ip);
      const baseNum = ipToNumber(base);
      return (ipNum & mask) === (baseNum & mask);
    }
    return allowedIp === ip;
  });
  return { allowed };
}

function ipToNumber(ip) {
  return ip.split('.').reduce((acc, octet) => (acc << 8) + parseInt(octet, 10), 0) >>> 0;
}

export function requireIdleLock(req, res, next) {
  const lock = checkIdleLock(req.authUser);
  if (lock.locked) {
    return res.status(403).json({
      message: `Session idle for ${lock.idleMinutes} minutes. Please enter your PIN to continue.`,
      code: 'IDLE_LOCK',
      idleMinutes: lock.idleMinutes,
    });
  }
  next();
}

export function requireShiftBound(req, res, next) {
  const shiftStart = req.authUser?.shiftStart || req.body?.shiftStart || req.query?.shiftStart;
  const check = checkShiftBound(req.authUser, shiftStart);
  if (!check.allowed) {
    return res.status(403).json({ message: check.reason, code: 'SHIFT_VIOLATION' });
  }
  next();
}

export function requireDeviceAllowList(req, res, next) {
  const fingerprint = req.headers['x-device-fingerprint'] || req.body?.deviceFingerprint;
  const ip = req.ip;
  checkDeviceAllowList(req.user.id, fingerprint, ip).then((result) => {
    if (!result.allowed) return res.status(403).json({ message: result.reason, code: 'DEVICE_NOT_ALLOWED' });
    next();
  }).catch((err) => res.status(500).json({ message: err.message }));
}

export function requireIpAllowList(req, res, next) {
  checkIpAllowList(req.user.id, req.ip).then((result) => {
    if (!result.allowed) return res.status(403).json({ message: 'IP not in allowlist', code: 'IP_NOT_ALLOWED' });
    next();
  }).catch((err) => res.status(500).json({ message: err.message }));
}

export const downtimeMode = async (req, res, next) => {
  const hospital = await Hospital.findById(req.user?.hospitalId).select('downtimeMode').lean();
  if (hospital?.downtimeMode) {
    const safeMethods = ['GET', 'HEAD', 'OPTIONS'];
    if (!safeMethods.includes(req.method)) {
      return res.status(503).json({ message: 'System in downtime mode. Write operations suspended.', code: 'DOWNTIME_MODE' });
    }
  }
  next();
};

export const breachRegister = {
  async log(breach) {
    const entry = {
      detectedAt: new Date(),
      breachId: crypto.randomUUID(),
      severity: breach.severity || 'medium',
      description: breach.description,
      affectedUsers: breach.affectedUsers || [],
      affectedRecords: breach.affectedRecords || [],
      reportedTo: breach.reportedTo || [],
      status: 'open',
      containmentSteps: [],
      notificationSent: false,
      deadline: new Date(Date.now() + 72 * 60 * 60 * 1000),
    };
    return AuditLog.create({ action: 'breach_logged', actor: breach.reporterId, payload: entry, severity: 'critical' });
  },
  async update(breachId, update) {
    return AuditLog.findOneAndUpdate({ 'payload.breachId': breachId }, { $set: { 'payload.$': { ...update } } }, { new: true });
  },
  async get(breachId) {
    return AuditLog.findOne({ 'payload.breachId': breachId });
  },
  async list(filter = {}) {
    return AuditLog.find({ action: 'breach_logged', ...filter }).sort({ createdAt: -1 }).limit(100);
  },
};

export async function verifyPin(req, res, next) {
  const { pin } = req.body || {};
  const user = req.authUser;
  if (!user?.pinHash) {
    return res.status(403).json({ message: 'PIN not set. Contact administrator.', code: 'PIN_NOT_SET' });
  }
  if (!pin) {
    return res.status(400).json({ message: 'PIN required', code: 'PIN_REQUIRED' });
  }
  const match = await bcrypt.compare(pin, user.pinHash);
  if (!match) {
    user.failedPinAttempts = (user.failedPinAttempts || 0) + 1;
    if (user.failedPinAttempts >= MAX_FAILED_PIN_ATTEMPTS) {
      user.lockedAt = new Date();
      await user.save();
      return res.status(403).json({ message: 'Too many failed attempts. Account locked.', code: 'PIN_LOCKED' });
    }
    await user.save();
    return res.status(401).json({ message: 'Invalid PIN', code: 'PIN_INVALID' });
  }
  user.failedPinAttempts = 0;
  user.lockedAt = null;
  user.lastActivityAt = new Date();
  await user.save();
  next();
}

export async function initPin(req, res, next) {
  const { pin } = req.body || {};
  if (!pin || pin.length < 4 || pin.length > 8 || !/^\d+$/.test(pin)) {
    return res.status(400).json({ message: 'PIN must be 4-8 digits', code: 'INVALID_PIN_FORMAT' });
  }
  const pinHash = await bcrypt.hash(pin, 12);
  req.user.pinHash = pinHash;
  req.user.failedPinAttempts = 0;
  await req.user.save();
  res.json({ message: 'PIN set successfully' });
}

export function updateActivity(req, _res, next) {
  // Throttled: one write per user per minute at most, so protect() never
  // becomes a write-per-request load. The in-memory value on req.authUser is
  // refreshed too so a burst of parallel requests collapses to a single write.
  //
  // Fail-soft by design: this is activity bookkeeping, not the request's
  // purpose. A synchronous throw here (partial User mock in tests, model
  // registration issue in prod) must not take down an otherwise-authenticated
  // request — same contract as the .catch(() => {}) below it.
  try {
    if (req.authUser && typeof User.updateOne === 'function') {
      const last = new Date(req.authUser.lastActivityAt || 0).getTime();
      if (Date.now() - last > 60_000) {
        req.authUser.lastActivityAt = new Date();
        User.updateOne({ _id: req.authUser._id }, { $set: { lastActivityAt: req.authUser.lastActivityAt } })
          .exec()
          .catch(() => {});
      }
    }
  } catch {
    /* best-effort: never fail the request over activity tracking */
  }
  if (typeof next === 'function') next();
}

import crypto from 'node:crypto';
import ApiKey from '../models/ApiKey.js';
import { auditLog } from './audit.js';

/**
 * File 25 §10: service-account auth (HL7/PACS/lab machines). Key arrives in
 * `x-api-key`; only the sha256 HASH is stored (show-once at creation).
 * Checks: exists, not revoked, not expired, IP binding. Attaches
 * req.serviceAccount { keyId, tenantId, policyId }. Updates lastUsedAt
 * (fire-and-forget). Human-user routes must NOT use this alone for PHI —
 * pair with the IAM evaluator via the key's policyId.
 */
const sha256 = (raw) => crypto.createHash('sha256').update(String(raw)).digest('hex');

export const apiKeyAuth = async (req, res, next) => {
  try {
    const raw = String(req.headers?.['x-api-key'] || '');
    if (!raw) return res.status(401).json({ message: 'API key required' });
    const key = await ApiKey.findOne({ prefix: raw.slice(0, 8) }).select('+hash');
    if (!key || key.hash !== sha256(raw)) {
      return res.status(401).json({ message: 'Invalid API key' });
    }
    if (key.revokedAt) return res.status(401).json({ message: 'API key revoked' });
    if (key.expiresAt && new Date(key.expiresAt).getTime() < Date.now()) {
      return res.status(401).json({ message: 'API key expired' });
    }
    if (Array.isArray(key.ipBinding) && key.ipBinding.length > 0
      && !key.ipBinding.map(String).includes(String(req.ip || ''))) {
      await auditLog('apikey_ip_rejected', null, { keyId: key._id, ip: req.ip }).catch(() => {});
      return res.status(403).json({ message: 'API key not allowed from this IP' });
    }
    req.serviceAccount = {
      keyId: String(key._id), tenantId: key.tenantId ? String(key.tenantId) : null, policyId: key.policyId,
    };
    ApiKey.updateOne({ _id: key._id }, { $set: { lastUsedAt: new Date() } }).catch(() => {});
    next();
  } catch (err) {
    next(err);
  }
};

export default apiKeyAuth;

/**
 * AUTHZ: assistant-booking access.
 *
 * Mirrors `lawyerBookings.js` → `assertBookingAccess`, which was found comparing a
 * `clientId` field the model does not have. The same mistake is easy to repeat, so
 * the rule lives here once and both booking modules can use it.
 *
 * Access decision, in order:
 *   1. superadmin — unrestricted.
 *   2. The patient who owns the booking.
 *   3. The assigned assistant, resolved EITHER through `assistantId` OR through
 *      AssistantProfile.userId. Providers are referenced inconsistently across the
 *      codebase; requiring both would lock legitimate assistants out, so either
 *      match counts.
 *   4. A staff/admin role in the booking's hospital. Tenant-scoped, fail closed.
 *
 * Denial is 404, not 403: a 403 confirms the id exists, and an enumerable booking
 * id is exactly what an attacker is fishing for. The response then leaks patient
 * name, phone and email.
 */
import AssistantProfile from '../models/AssistantProfile.js';

const same = (a, b) => {
  if (a == null || b == null) return false;
  const norm = (v) => String(typeof v === 'object' ? (v._id ?? v.id ?? v) : v);
  return norm(a) === norm(b);
};

const STAFF_ROLES = new Set(['superadmin', 'hospital_admin', 'admin']);

/**
 * @returns {{ ok: true, reason: string } | { ok: false, code: 'not_found' | 'forbidden' }}
 */
export async function assertAssistantBookingAccess(req, booking, { action = 'read' } = {}) {
  if (!booking) return { ok: false, code: 'not_found' };

  const userId = req.user?._id;
  const role = req.user?.role;

  if (role === 'superadmin') return { ok: true, reason: 'superadmin' };

  if (same(booking.patientId, userId) || same(booking.patientId?._id, userId)) {
    return { ok: true, reason: 'own_patient' };
  }

  // The assigned assistant, by either reference shape.
  if (same(booking.assistantId, userId) || same(booking.assistantId?._id, userId)) {
    return { ok: true, reason: 'assigned_assistant' };
  }
  const profile = await AssistantProfile.findOne({ userId }).select('_id').lean();
  if (profile && (same(booking.assistantId, profile._id) || same(booking.assistantId, userId))) {
    return { ok: true, reason: 'assigned_assistant_via_profile' };
  }

  // Hospital staff: tenant must match on BOTH sides. A caller with no tenant, or a
  // booking with no tenant, is denied — "cannot determine" must not mean "allow".
  if (STAFF_ROLES.has(role)) {
    const callerTenant = req.user.hospitalId || req.user.facilityId;
    const bookingTenant = booking.hospitalId;
    if (callerTenant && bookingTenant && String(callerTenant) === String(bookingTenant)) {
      return { ok: true, reason: 'same_tenant_staff' };
    }
    return { ok: false, code: 'not_found' };
  }

  // A patient acting on someone else's booking, or an unrelated role.
  return { ok: false, code: role === 'patient' || role === 'assistant' ? 'not_found' : 'forbidden' };
}

/** Express-style responder for a denial. Always 404, to avoid an existence oracle. */
export function denyAssistantBooking(res, decision) {
  return res.status(404).json({ message: 'Booking not found' });
}

/**
 * Middleware form: `router.get('/:id', protect, requireAssistantBooking('read'), ...)`.
 * Attaches the already-authorised booking to `req.assistantBooking`.
 */
export function requireAssistantBooking(action = 'read') {
  return async (req, res, next) => {
    try {
      if (!req.user) return res.status(401).json({ message: 'Not authorized' });
      const { default: AssistantBooking } = await import('../models/AssistantBooking.js');
      const booking = await AssistantBooking.findById(req.params.id);
      if (!booking) return res.status(404).json({ message: 'Booking not found' });

      const decision = await assertAssistantBookingAccess(req, booking, { action });
      if (!decision.ok) return denyAssistantBooking(res, decision);

      req.assistantBooking = booking;
      return next();
    } catch (err) {
      return next(err);
    }
  };
}

export default requireAssistantBooking;

import AuditLog from '../models/AuditLog.js';
import logger from '../config/logger.js';
import { redisClient, isRedisReady } from '../config/redis.js';
import { indexAuditLog } from '../services/opensearchIndexer.js';

const SENSITIVE_DETAIL_KEYS = /token|secret|password|passwd|otp|cookie|authorization|api[_-]?key|session/i;

/** Recursively redact secret-shaped keys from audit details (DP-B-03). */
export function scrubAuditDetails(value, depth = 0) {
  if (depth > 6 || value === null || value === undefined) return value;
  if (Array.isArray(value)) return value.map((v) => scrubAuditDetails(v, depth + 1));
  if (typeof value === 'object') {
    const out = {};
    for (const [k, v] of Object.entries(value)) {
      out[k] = SENSITIVE_DETAIL_KEYS.test(k) ? '[redacted]' : scrubAuditDetails(v, depth + 1);
    }
    return out;
  }
  return value;
}

/**
 * Writes an audit entry to MongoDB (system of record) and fans it out to
 * OpenSearch so compliance/security teams can query across the retention
 * window with full-text search.
 *
 * The Mongo write is authoritative and MUST succeed; the OpenSearch document
 * is fire-and-forget and never blocks or fails the request. OpenSearch is
 * unconfigured in dev/test, in which case indexAuditLog() is a no-op.
 *
 * AUTH-B-05: the AuditLog model runs with `bufferCommands: false`, so a Mongo
 * outage rejects immediately instead of stalling the caller for mongoose' 10 s
 * buffering timeout. Failures are counted (`audit:write_failures`) and logged.
 */
export const auditLog = async (action, userId, details, { required = false } = {}) => {
  try {
    // DP-B-03 (partial): `details` is Mixed with no schema, so a caller can
    // persist (and mirror into OpenSearch) anything — including tokens, OTPs
    // or cookies. Scrub secret-shaped keys before the write; structure kept.
    const safeDetails = scrubAuditDetails(details);
    // File 22 P2-31: hash-chain link (prev = latest hash, '' when empty).
    const nodeCrypto = await import('node:crypto');
    let prevHash = 'GENESIS';
    try {
      const last = await AuditLog.findOne().sort({ _id: -1 }).select('hash').lean();
      if (last?.hash) prevHash = last.hash;
    } catch { /* first entry or read failure: chain restarts explicitly */ }
    const canonical = JSON.stringify({
      prevHash, userId: String(userId || ''), action,
      details: safeDetails ?? {}, ip: safeDetails?.ip || null,
    });
    const hash = nodeCrypto.createHash('sha256').update(canonical).digest('hex');
    const entry = await AuditLog.create({
      userId,
      action,
      details: safeDetails,
      ip: safeDetails?.ip || null,
      userAgent: safeDetails?.userAgent || null,
      timestamp: new Date(),
      prevHash,
      hash,
    });

    // Keep the search document flat — Mongo `details` is Mixed and can be
    // arbitrarily nested, which OpenSearch's text mapping cannot index.
    let flattened = '';
    try {
      flattened = JSON.stringify(safeDetails ?? {});
    } catch {
      flattened = '[unserializable details]';
    }

    void indexAuditLog({
      logId: String(entry._id),
      actorId: userId ? String(userId) : '',
      action,
      resourceType: safeDetails?.resourceType || '',
      resourceId: safeDetails?.resourceId ? String(safeDetails.resourceId) : '',
      ip: safeDetails?.ip || '',
      details: flattened,
      timestamp: entry.timestamp?.toISOString?.() || new Date().toISOString(),
    }).catch((mirrorErr) => {
      // AUTH-016: mirror failures are counted + logged (Pino), never silent.
      try {
        if (isRedisReady() && redisClient.isOpen) {
          redisClient.incr('audit:mirror_failures').catch(() => {});
        }
      } catch {}
      logger.error(`Audit OpenSearch mirror failed for ${action}: ${mirrorErr.message}`);
    });
  } catch (error) {
    // AUTH-B-05: a write failure is never silent — count it so the gap in the
    // compliance trail is visible on a dashboard.
    try {
      if (isRedisReady() && redisClient.isOpen) {
        redisClient.incr('audit:write_failures').catch(() => {});
      }
    } catch {}
    logger.error(`Audit log failed: ${error.message}`);
    if (required) throw error;
  }
};

// Privacy-sensitive reads fail closed if their authoritative audit row cannot
// be committed. Most legacy audit calls retain their historical best-effort
// behavior until their route-specific durability policy is migrated.
export const auditLogRequired = (action, userId, details) =>
  auditLog(action, userId, details, { required: true });

// AUTH-F-01: EVERY token verification goes through jwtKeys. A bare verify
// against a static JWT_SECRET cannot rotate keys (it rejects anything signed
// under JWT_KEYS) and accepts a refresh token as an access token.
// verifyAccessToken closes both.
import { verifyAccessToken } from '../utils/jwtKeys.js';
import { MANDATORY_TWO_FACTOR_ROLES } from '../config/permissions.js';
import { isDemoAccount } from '../utils/demoAccount.js';
import User from '../models/User.js';
import Doctor from '../models/Doctor.js';
import Patient from '../models/Patient.js';
import Record from '../models/Record.js';
import { auditLog } from './audit.js';
import { readAuthCookie } from '../lib/cookiePolicy.js';
import { tenantQuotaGuard } from '../services/tenantQuotaService.js';
import { isTenantStaff } from '../utils/tenantScope.js';
import {
  hashChain,
  logAuditHashChain,
  requireIdleLock,
  requireShiftBound,
  requireDeviceAllowList,
  requireIpAllowList,
  downtimeMode,
  breachRegister,
  verifyPin,
  initPin,
  updateActivity,
  checkIdleLock,
  checkShiftBound,
  checkDeviceAllowList,
  checkIpAllowList,
} from '../lib/security.js';

import { authorize, isPlatformBreakGlassRole } from './authorize.js';
export { authorize, isPlatformBreakGlassRole };

// Routes still carrying legacy conditional hospital filters. Until those
// predicates are migrated to applyTenantScope(), platform operators on these
// tenant data endpoints must have an explicit hospital context.
const LEGACY_TENANT_ROUTE_PREFIXES = [
  '/api/bloodbank', '/api/clinical', '/api/diet', '/api/doctor',
  '/api/emergency', '/api/encounters', '/api/feedback', '/api/health-id',
  '/api/inventory', '/api/ipd', '/api/lab', '/api/linen', '/api/maternity',
  '/api/nursing', '/api/orders', '/api/print', '/api/radiology',
  '/api/security', '/api/staff', '/api/tokens',
  '/api/housekeeping', '/api/insurance', '/api/leave-requests', '/api/ot',
  '/api/payments', '/api/pharmacy', '/api/physio', '/api/reports',
  '/api/schedule-change-requests', '/api/triage',
];

const requiresLegacyTenantContext = (req) => {
  const path = String(req.originalUrl || req.path || '').split('?')[0];
  return LEGACY_TENANT_ROUTE_PREFIXES.some((prefix) => path === prefix || path.startsWith(`${prefix}/`));
};

// AUTH-F-06: the ONLY routes a mustResetPassword session may reach. Exact
// paths (minus query/trailing slash), never prefixes - `/api/auth/
// change-password-evil` must not ride the allowlist. Everything else needs a
// real password first, which is the whole point of the flag.
const PASSWORD_RESET_EXEMPT_PATHS = [
  '/api/auth/change-password',
  '/api/auth/logout',
  '/api/auth/logout-all',
  '/api/auth/me',
];
const isPasswordResetExempt = (req) => {
  const p = (req.originalUrl || '').split('?')[0].replace(/\/+$/, '');
  return PASSWORD_RESET_EXEMPT_PATHS.includes(p);
};

// P2-11: roles that MUST run with 2FA. Comma-separated env, e.g.
// TWO_FACTOR_REQUIRED_ROLES=superadmin,hospital_admin. Until such an account
// enrols, protect() lets it reach ONLY the enrolment paths (plus the same
// logout/me/change-password basics as AUTH-F-06) so the client can always
// complete enrolment and never deadlocks itself. Exact paths, never prefixes.
//
// 8.md 13 / 7.md 8: the ops roles (kyc_reviewer, finance_admin, ...) carry
// platform-wide reach, so THEIR requirement is code-level — MANDATORY_TWO_FACTOR_ROLES
// from the permission config is unioned in, and the env adds more (superadmin,
// hospital_admin) on top. An unset env must never mean "the ops console has no
// second factor".
const TWO_FACTOR_REQUIRED_ROLES = new Set([
  ...MANDATORY_TWO_FACTOR_ROLES,
  ...String(process.env.TWO_FACTOR_REQUIRED_ROLES || '')
    .split(',')
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean),
]);
const TWO_FACTOR_ENROL_EXEMPT_PATHS = new Set([
  '/api/auth/2fa/setup',
  '/api/auth/2fa/verify',
  '/api/auth/2fa/status',
  '/api/auth/logout',
  '/api/auth/logout-all',
  '/api/auth/me',
  '/api/auth/change-password',
]);
const isTwoFactorEnrolExempt = (req) => {
  const p = (req.originalUrl || '').split('?')[0].replace(/\/+$/, '');
  return TWO_FACTOR_ENROL_EXEMPT_PATHS.has(p);
};

export const protect = async (req, res, next) => {
  let token = readAuthCookie(req.cookies, 'token');
  if (!token) {
    const auth = req.headers.authorization;
    if (!auth || !auth.startsWith('Bearer ')) {
      return res.status(401).json({ message: 'Not authorized' });
    }
    token = auth.split(' ')[1];
  }

  let decoded;
  try {
    decoded = verifyAccessToken(token);
  } catch {
    // Siraf asli token failure (invalid/expired) ko auth failure banao
    return res.status(401).json({ message: 'Token invalid or expired' });
  }

  let user;
  let doctor = null;
  try {
    user = await User.findById(decoded.id).select('-password');
    // Counsellor/psychiatrist ko bhi doctor-jaisa Doctor-profile link (appointments,
    // /me/*, ownership checks sab doctorProfileId se chalte hain).
    // AUTH-B-12: resolve the profile by the EXPLICIT user_id link first and only
    // fall back to the email match for legacy rows that have no link at all.
    // A bare `$or: [user_id, email]` let a colliding email bind one account to
    // another account's doctor profile.
    if (user?.role === 'doctor' || user?.role === 'clinic_doctor' || user?.role === 'counsellor' || user?.role === 'psychiatrist') {
      doctor = await Doctor.findOne({ user_id: user._id.toString() });
      if (!doctor && user.email) {
        doctor = await Doctor.findOne({ email: user.email });
      }
    }
  } catch {
    // DB hiccup (reconnect/restart) auth failure nahi hai — 503 bhejo taaki
    // client network-error jaisa retry kare, logout na ho.
    return res.status(503).json({ message: 'Service temporarily unavailable. Please try again.' });
  }

  if (!user) {
    return res.status(401).json({ message: 'Token invalid or expired' });
  }

  // AUTH-012 / AUTH-B-11: token version — password change/reset/logout-all revoke
  // every previously issued token. A token minted WITHOUT the claim (pre-AUTH-012
  // legacy token) is treated as version 0, so the `?? 0` here also closes the
  // "revocation silently skipped for old tokens" hole.
  const tokenVersion = user.tokenVersion || 0;
  if ((decoded.tv ?? 0) !== tokenVersion) {
    return res.status(401).json({ message: 'Session revoked. Please login again.' });
  }

  if (user.status === 'blocked') {
    return res.status(403).json({ message: 'Your account has been blocked. Contact administrator.' });
  }

  // AUTH-F-06: temp-password accounts are locked to the four-path allowlist
  // until they rotate. Enforced HERE, not (only) at login: the login-time
  // check never ran for google/2FA-issued tokens or sessions minted before an
  // admin set the flag, and because it ran before token issuance the user
  // could never reach PUT /auth/change-password - the one route that clears
  // the flag. Session-level enforcement closes both holes.
  if (user.mustResetPassword && !isDemoAccount(user.email) && !isPasswordResetExempt(req)) {
    return res.status(403).json({
      message: 'You must set a new password before continuing.',
      code: 'PASSWORD_RESET_REQUIRED',
      mustResetPassword: true,
    });
  }

  if (!user.isVerified) {
    return res.status(403).json({
      message: 'Please verify your email before continuing.',
      requiresVerification: true,
      email: user.email,
    });
  }

  // P2-11: mandatory-2FA roles stay locked to the enrolment paths until they
  // actually enrol. Gates HERE (session-level), not only at login, so tokens
  // issued before the env was flipped also become subject to the rule.
  if (
    TWO_FACTOR_REQUIRED_ROLES.has(String(user.role || '').toLowerCase())
    && !user.twoFactorEnabled
    && !isTwoFactorEnrolExempt(req)
  ) {
    return res.status(403).json({
      message: 'Two-factor authentication is required for your role. Please set it up first.',
      code: 'TWO_FACTOR_REQUIRED',
      requiresTwoFactorEnrollment: true,
    });
  }

  if (user.role === 'doctor' || user.role === 'clinic_doctor' || user.role === 'counsellor' || user.role === 'psychiatrist') {
    if (user.approvalStatus === 'rejected') {
      return res.status(403).json({
        message: 'Your doctor account was not approved. Contact administrator.',
        approvalRejected: true,
      });
    }

    if (!doctor?.approved && user.approvalStatus !== 'approved') {
      return res.status(403).json({
        message: 'Your account is pending admin approval.',
        approvalPending: true,
      });
    }
  }

req.user = {
    id: user._id.toString(),
    _id: user._id,
    role: user.role,
    name: user.name,
    email: user.email,
    hospitalId: user.hospitalId || null,
    facilityId: user.facilityId || null,
    facilityType: user.facilityType || '',
    doctorProfileId: (user.role === 'doctor' || user.role === 'clinic_doctor' || user.role === 'counsellor' || user.role === 'psychiatrist') ? (doctor?._id || null) : null,
    mustResetPassword: isDemoAccount(user.email) ? false : Boolean(user.mustResetPassword),
  };
  req.authUser = user;

  // AUTHZ-B-07: legacy route filters often add a tenant predicate only when a
  // hospitalId exists. Tenant staff without any tenant and platform operators
  // reaching a legacy tenant-data endpoint without hospital scope must stop
  // here; otherwise the omitted predicate can become a platform-wide query.
  const missingTenant = !req.user.hospitalId && !req.user.facilityId;
  const legacyScopedEndpoint = requiresLegacyTenantContext(req);
  if (
    missingTenant
    && req.user.role !== 'superadmin'
    && (isTenantStaff(req.user) || (legacyScopedEndpoint && isPlatformBreakGlassRole(req.user.role)))
  ) {
    return res.status(403).json({ message: 'No hospital/facility linked to this account', code: 'TENANT_SCOPE_REQUIRED' });
  }

  const idleLock = checkIdleLock(user);
  if (idleLock.locked) {
    return res.status(403).json({
      message: `Session idle for ${idleLock.idleMinutes} minutes. Please enter your PIN to continue.`,
      code: 'IDLE_LOCK',
      idleMinutes: idleLock.idleMinutes,
    });
  }

  // Checklist I8: session is live — advance the idle-PIN window (throttled in
  // updateActivity) so the lock below triggers on genuine inactivity only.
  updateActivity(req, res);

  const shiftCheck = checkShiftBound(user, user.shiftStart);
  if (!shiftCheck.allowed) {
    return res.status(403).json({ message: shiftCheck.reason, code: 'SHIFT_VIOLATION' });
  }

  return tenantQuotaGuard(req, res, next);
};

