import crypto from 'crypto';

const getCookieOptions = () => ({
  httpOnly: false,
  secure: process.env.NODE_ENV === 'production',
  sameSite: process.env.NODE_ENV === 'production' ? 'none' : 'lax',
  path: '/',
  // Refresh token (7d) jitna hi rakho — warna 24h baad har POST fail ho kar session girti thi
  maxAge: 7 * 24 * 60 * 60 * 1000,
});

export const csrfProtection = (req, res, next) => {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) {
    return next();
  }

  // AUTH-003: the old `/upload` exemption is removed — multipart uploads must
  // carry the double-submit token like every other state-changing request.

  const origin = req.headers['origin'];
  const referer = req.headers['referer'];
  if (origin || referer) {
    const source = (origin || referer).trim().replace(/\/$/, '');
    const allowedList = [
      ...(process.env.CLIENT_URL ? process.env.CLIENT_URL.split(',') : []),
      ...(process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN.split(',') : []),
      'https://findmedi.online',
      'https://www.findmedi.online',
      'http://localhost:5173',
      'http://localhost:3000',
    ].map(o => o.trim().replace(/\/$/, '')).filter(Boolean);

    const isAllowed = allowedList.includes(source);
    if (!isAllowed && process.env.NODE_ENV === 'production') {
      return res.status(403).json({ message: 'CSRF validation failed: invalid origin' });
    }
  }

  // The token check is MANDATORY for every state-changing request.
  //
  // This used to fall through to an unconditional `next()` at the end of the
  // function. Because the `origin || referer` branch above does not return on
  // success, any request carrying an allow-listed Origin skipped the token
  // comparison entirely — CSRF protection was only ever applied to clients
  // that sent no Origin/Referer at all.
  //
  // Requiring the double-submit token unconditionally is what actually protects
  // the API: a cross-site attacker can cause the cookie to be sent
  // (SameSite=None) but cannot read it to populate the `x-csrf-token` header,
  // so they can never assemble a request that passes this check.
  const tokenFromCookie = req.cookies?.['csrf-token'];
  const tokenFromHeader = req.headers['x-csrf-token'];
  if (!tokenFromCookie || !tokenFromHeader || tokenFromCookie !== tokenFromHeader) {
    return res.status(403).json({ message: 'CSRF validation failed: missing token' });
  }

  return next();
};

export const setCsrfToken = (req, res) => {
  const token = crypto.randomBytes(32).toString('hex');
  res.cookie('csrf-token', token, getCookieOptions());
  res.json({ csrfToken: token });
};

/**
 * Centralized error handling middleware
 * - Hides stack traces in production
 * - Handles different error types with appropriate status codes
 * - Logs errors for monitoring
 */
/* eslint-disable @typescript-eslint/no-this-alias -- false positive in class constructor and error handler */
import crypto from 'node:crypto';
import logger from '../config/logger.js';

// Custom AppError class for operational errors
export class AppError extends Error {
  constructor(message, statusCode = 500, code = 'INTERNAL_ERROR') {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// 404 handler for unknown routes
export const notFound = (req, res, next) => {
  const error = new AppError(`Route not found: ${req.originalUrl}`, 404, 'NOT_FOUND');
  next(error);
};

// Main error handler
export const errorHandler = (err, req, res, next) => {
  // AUTH-016: every error carries a request id so logs, audit rows and client
  // reports correlate. Stack traces leave the process in development only.
  const requestId = req.id || crypto.randomUUID();
  req.id = requestId;
  // Default values
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal server error';
  let code = err.code || 'INTERNAL_ERROR';

  // Handle specific error types
  if (err.name === 'ValidationError') {
    // Mongoose validation error
    statusCode = 400;
    code = 'VALIDATION_ERROR';
    message = Object.values(err.errors || {})
      .map(e => e.message)
      .join(', ');
  } else if (err.name === 'CastError') {
    // Mongoose invalid ObjectId
    statusCode = 400;
    code = 'INVALID_ID';
    message = `Invalid ${err.path}: ${err.value}`;
  } else if (err.name === 'JsonWebTokenError') {
    statusCode = 401;
    code = 'INVALID_TOKEN';
    message = 'Invalid authentication token';
  } else if (err.name === 'TokenExpiredError') {
    statusCode = 401;
    code = 'TOKEN_EXPIRED';
    message = 'Authentication token has expired';
  } else if (err.code === 11000) {
    // MongoDB duplicate key error
    statusCode = 409;
    code = 'DUPLICATE_KEY';
    const field = Object.keys(err.keyValue || {})[0] || 'field';
    message = `${field} already exists`;
  } else if (err.name === 'MulterError') {
    statusCode = 400;
    code = 'UPLOAD_ERROR';
    if (err.code === 'LIMIT_FILE_SIZE') message = 'File too large';
    else if (err.code === 'LIMIT_FILE_COUNT') message = 'Too many files';
    else message = err.message;
  } else if (!err.isOperational) {
    // Unexpected error in production
    if (process.env.NODE_ENV === 'production') {
      message = 'Something went wrong. Please try again later.';
    }
  }

  // Log error via Pino (never silent): operational 5xx included, with id.
  logger.error({ requestId, statusCode, code, message: err.message, stack: err.stack }, '[request-error]');

  // Response — stack only in development (never staging/production).
  const response = {
    message,
    code,
    requestId,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  };

  res.status(statusCode).json(response);
};

// Async error wrapper to avoid try-catch in route handlers
export const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Rate limit error handler
export const rateLimitHandler = (req, res) => {
  res.status(429).json({
    message: 'Too many requests. Please try again later.',
    code: 'RATE_LIMIT',
  });
};

import { redisClient, isRedisReady } from '../config/redis.js';
import logger from '../config/logger.js';

/**
 * Spec 20 rule 4 — Idempotency-Key replay guard for mutating dispatch endpoints.
 * Client sends `Idempotency-Key: <uuid>`; first completion stores status+body
 * in Redis (24h) and replays it on retry instead of double-executing.
 * Header absent → pass through (fail-open; existing clients keep working).
 * Redis down → pass through (fail-open).
 */
export function idempotencyGuard({ prefix = 'idem', ttlSeconds = 86400, failClosed = false } = {}) {
  return async (req, res, next) => {
    const key = req.header('Idempotency-Key') || req.header('idempotency-key');
    if (!key) {
      // PAY-003: payment routes opt into fail-closed — no key, no processing.
      if (failClosed) {
        return res.status(400).json({
          success: false,
          error: 'IDEMPOTENCY_KEY_REQUIRED',
          message: 'Idempotency-Key header is required for this endpoint',
        });
      }
      return next();
    }

    if (!isRedisReady() || !redisClient.isOpen) {
      // PAY-003: fail-closed — never execute a payment without the replay guard.
      if (failClosed) {
        return res.status(503).json({
          success: false,
          error: 'IDEMPOTENCY_UNAVAILABLE',
          message: 'Idempotency service unavailable — request not processed',
        });
      }
      return next();
    }

    // PAY-003: scope by user (or IP for anonymous callers) so one user's key can
    // never replay another user's stored response.
    const redisKey = `${prefix}:${req.user?._id || req.ip}:${key}`;
    try {
      // PAY-B-09: the reservation is acquired ATOMICALLY with SET .. NX. The old
      // `GET` then unconditional `SET` had a TOCTOU window the length of the
      // whole handler, so two concurrent retries with the same key both executed
      // the money path (double charge / double dispatch).
      const acquired = await redisClient.set(redisKey, JSON.stringify({ replayed: false, inFlight: true }), { EX: ttlSeconds, NX: true });
      if (acquired !== 'OK') {
        // Somebody else holds the reservation: replay the stored response when it
        // is ready, otherwise tell the caller the original is still in flight.
        const existing = await redisClient.get(redisKey);
        if (existing) {
          try {
            const stored = JSON.parse(existing);
            if (stored && stored.replayed) {
              return res.status(stored.status || 200).json(stored.body);
            }
          } catch {}
        }
        return res.status(409).json({
          success: false,
          error: 'IDEMPOTENT_IN_FLIGHT',
          message: 'Same request is already being processed. Retry shortly.',
        });
      }

      const originalJson = res.json.bind(res);
      res.json = (body) => {
        redisClient
          .set(redisKey, JSON.stringify({ replayed: true, status: res.statusCode, body }), { EX: ttlSeconds })
          .catch(() => {});
        return originalJson(body);
      };
      next();
    } catch (err) {
      // PAY-M-07: this catch used to call next() unconditionally, which silently
      // disabled the double-charge guard for exactly the endpoints that declared
      // themselves fail-closed. A Redis blip mid-reservation therefore turned
      // "charge once per key" into "charge every time" — and it failed OPEN, the
      // one direction a money path must never fail in.
      logger.error(`idempotency guard error on ${prefix}: ${err.message}`);
      if (failClosed) {
        // Deliberately no rollback. The reservation may or may not have been
        // taken, and guessing would either strand the key (every retry 409s) or
        // free it while the first request is still executing. Refusing is the
        // only state that cannot double-spend; the key expires on its own TTL.
        return res.status(503).json({
          success: false,
          // Same code as the Redis-down branch above, deliberately. To a client
          // these are one condition, and a client branching on the string must
          // not have to know which of the two fired.
          error: 'IDEMPOTENCY_UNAVAILABLE',
          message: 'Idempotency service unavailable — request not processed',
        });
      }
      next();
    }
  };
}

/**
 * INF-M-02: scrape-endpoint authentication.
 *
 * Prometheus does not log in — it sends a bearer token (or the
 * `x-metrics-token` header for scrape configs that prefer it). So this gate is
 * a shared-secret comparison, NOT session `protect`, and it FAILS CLOSED:
 * with no `METRICS_TOKEN` in the environment the endpoint answers 403 rather
 * than serving request rates and error counts to whoever asks. An unauthenticated
 * metrics endpoint is a free map of your traffic shape and your busiest routes.
 *
 * Comparison is length-checked first, then `timingSafeEqual` — a plain `===`
 * on a secret leaks its value through response timing.
 */
import crypto from 'node:crypto';

export function requireMetricsToken(req, res, next) {
  const expected = process.env.METRICS_TOKEN;
  if (!expected) {
    return res.status(403).json({ message: 'metrics endpoint disabled: set METRICS_TOKEN to enable it' });
  }

  const header = req.get('authorization') || '';
  const bearer = header.replace(/^Bearer\s+/i, '');
  const got = bearer || req.get('x-metrics-token') || '';

  const a = Buffer.from(String(got), 'utf8');
  const b = Buffer.from(expected, 'utf8');
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    return res.status(403).json({ message: 'invalid metrics token' });
  }
  return next();
}

import crypto from 'node:crypto';
import { redisClient, isRedisReady } from '../config/redis.js';
import logger from '../config/logger.js';
import { ADMIT_LUA } from '../lib/admitLua.js';

/**
 * GRL-Style Distributed Rate Limiter with Redis Sliding-Window Token Bucket.
 * Admission is a single atomic Lua script (prune → count → conditional add),
 * so concurrent bursts cannot over-admit (AUTH-007). SOS *paths* bypass;
 * client-controlled `req.body.isEmergency` NEVER bypasses (AUTH-006 removed).
 *
 * @param {Object} options
 * @param {number} options.windowMs - Time window in milliseconds (default 60,000ms / 1 min)
 * @param {number} options.max - Maximum allowed requests in window
 * @param {string} options.keyPrefix - Prefix for Redis key (e.g. 'rl:auth', 'rl:booking')
 * @param {boolean} options.failClosed - 429 when Redis is down (auth/OTP only)
 */
// ADM-M-06: the admission script itself moved to lib/admitLua.js so the
// per-tenant quota guard shares one copy (and one RL-01 contract) with us.
export function createGrlRateLimiter({
  windowMs = 60000,
  max = 60,
  keyPrefix = 'rl:api',
  isEmergencyExempt = true,
  failClosed = false,
}) {
  return async (req, res, next) => {
    // 1. Only exact life-safety intake paths bypass this general limiter. Other
    // emergency/SOS-adjacent routes (history, search, admin tools) stay limited.
    // Client body fields are attacker-controlled and must not switch off
    // auth/TOTP/payment throttles.
    if (isEmergencyExempt) {
      const path = (req.path || (req.originalUrl || req.url || '').split('?')[0]).replace(/\/+$/, '') || '/';
      const method = String(req.method || 'GET').toUpperCase();
      const emergencyIntake = method === 'POST' && new Set([
        '/api/emergency',
        '/api/emergency-sos',
        '/api/emergency-sos/start',
      ]).has(path);
      if (emergencyIntake) {
        return next();
      }
    }

    // 2. Identify client by User ID if authenticated, else IP address
    const identifier = req.user?._id ? `user:${req.user._id}` : `ip:${req.ip || 'unknown'}`;
    const redisKey = `${keyPrefix}:${identifier}`;

    // 3. Redis down: fail-closed for auth/OTP in production (brute-force
    // defence); fail-open in dev/test (no Redis) and elsewhere (availability).
    if (!isRedisReady() || !redisClient.isOpen) {
      if (failClosed && process.env.NODE_ENV === 'production') {
        res.setHeader('Retry-After', Math.ceil(windowMs / 1000));
        return res.status(429).json({
          success: false,
          error: 'RATE_LIMITER_UNAVAILABLE',
          message: 'Security throttle unavailable. Please retry shortly.',
        });
      }
      return next();
    }

    const now = Date.now();
    const member = `${now}_${crypto.randomBytes(4).toString('hex')}`;

    try {
      // Atomic Lua admit: returns post-add count, or pre-add count at cap.
      const admitted = Number(await redisClient.eval(ADMIT_LUA, {
        keys: [redisKey],
        arguments: [String(now), String(windowMs), String(max), member],
      }));

      // Set standard rate limit headers
      res.setHeader('X-RateLimit-Limit', max);
      res.setHeader('X-RateLimit-Remaining', Math.max(0, max - admitted));

      // AUTH-B-04 / RL-01 / DL-04: the Lua script returns the PRE-add member count
      // when it refuses to admit (i.e. exactly `max`), so `admitted > max` was
      // never true at the cap and the counter could not grow past `max` — every
      // request above the cap was admitted (no effective throttle on /auth/*,
      // OTP verify, payouts...). The comparison must be `>=` (a window therefore
      // admits `max - 1` requests, the conservative reading of `max`).
      if (admitted >= max) {
        res.setHeader('Retry-After', Math.ceil(windowMs / 1000));
        return res.status(429).json({
          success: false,
          error: 'TOO_MANY_REQUESTS',
          message: 'Rate limit exceeded. Please wait before attempting again.',
          retryAfterSeconds: Math.ceil(windowMs / 1000),
        });
      }

      next();
    } catch (err) {
      logger.warn(`GRL rate-limiter error on [${redisKey}]: ${err.message}. Passing through.`);
      next(); // Fail-open on unexpected Redis error
    }
  };
}

