/**
 * AUTHZ-M-03: step-up authentication for sensitive actions.
 *
 * 2FA at LOGIN proves who you are once, at the start of a session. It says
 * nothing about whether the *same* person is still there when they, say, an hour
 * later add a payout account, read a full export, or change a patient's
 * diagnosis. A session token is a long-lived bearer credential; a stolen one gets
 * everything it can reach, including the endpoints that move money.
 *
 * Step-up closes that window: the sensitive action demands a FRESH proof, and the
 * result is short-lived, single-use, and bound to one action scope.
 *
 * Three deliberate properties:
 *
 *  1. FAIL CLOSED when the user HAS enabled 2FA. Someone who opted into a second
 *     factor and then finds it skipped on a payout edit has been silently
 *     downgraded. A user who never enabled 2FA is allowed through — demanding a
 *     factor they do not have locks them out of their own account, which is not a
 *     security improvement.
 *
 *  2. The grant is CONSUMED on use and bound to a scope string. A step-up granted
 *     to authorise "view export" must not also authorise "add payout account" five
 *     minutes later; that would just be a second session token with extra steps.
 *
 *  3. Opaque single-use tokens, so a grant cannot be forged or replayed. The
 *     grant is keyed by user AND scope internally as well, so a stolen token is
 *     useless against a different endpoint.
 */
import crypto from 'node:crypto';
import User from '../models/User.js';
import { verifyToken, verifyBackupCode } from '../services/twoFactorService.js';

const DEFAULT_TTL_SECONDS = 300; // 5 min: long enough for one task, short enough to matter.

/** Grants live in-process. A multi-instance deployment needs Redis for these. */
const grants = new Map();

const sweep = setInterval(() => {
  const now = Date.now();
  for (const [k, v] of grants) if (v.expiresAt <= now) grants.delete(k);
}, 60_000);
sweep.unref?.();

export const recordStepUp = (userId, scope, ttlSeconds = DEFAULT_TTL_SECONDS) => {
  const grant = { userId: String(userId), scope, expiresAt: Date.now() + ttlSeconds * 1000 };
  grants.set(`${grant.userId}:${scope}`, grant);
  return grant;
};

export const consumeStepUp = (userId, scope) => {
  const key = `${String(userId)}:${scope}`;
  const grant = grants.get(key);
  if (!grant) return null;
  grants.delete(key); // single-use, even if the action then fails partway
  return grant.expiresAt > Date.now() ? grant : null;
};

/** Read-only, for a route that wants to say "verification needed" without consuming. */
export const hasStepUp = (userId, scope) => {
  const grant = grants.get(`${String(userId)}:${scope}`);
  return Boolean(grant && grant.expiresAt > Date.now());
};

export const clearStepUps = (userId) => {
  for (const k of [...grants.keys()]) {
    if (k.startsWith(`${String(userId)}:`)) grants.delete(k);
  }
};

/** Opaque single-use token, so a grant is neither guessable nor forgeable. */
const tokenIndex = new Map();

export const issueStepUpToken = (grant) => {
  const token = crypto.randomBytes(24).toString('base64url');
  tokenIndex.set(token, grant);
  setTimeout(() => tokenIndex.delete(token), Math.max(0, grant.expiresAt - Date.now())).unref?.();
  return token;
};

const consumeStepUpToken = (token) => {
  const grant = tokenIndex.get(token);
  if (!grant) return null;
  tokenIndex.delete(token);
  return grant.expiresAt > Date.now() ? grant : null;
};

/**
 * Issue a step-up grant after the user proves possession.
 * Separate from the middleware so a client can obtain one and then make the
 * sensitive call.
 */
export const issueStepUpFor = async (userId, code, scope, ttlSeconds = DEFAULT_TTL_SECONDS) => {
  const user = await User.findById(userId)
    .select('twoFactorEnabled twoFactorSecret twoFactorBackupCodes email');
  if (!user) return { ok: false, reason: 'no-user' };
  if (!user.twoFactorEnabled) return { ok: false, reason: 'not-enabled' };

  const clean = String(code || '').trim();
  let ok = false;
  if (/^\d{6}$/.test(clean)) ok = verifyToken(clean, user.twoFactorSecret);
  else if (clean) ok = verifyBackupCode(clean, user.twoFactorBackupCodes || []);

  if (!ok) return { ok: false, reason: 'bad-code' };
  const grant = recordStepUp(user._id, scope, ttlSeconds);
  return { ok: true, grant, token: issueStepUpToken(grant) };
};

/**
 * Express middleware.
 *   router.post('/payouts', protect, requireStepUp('payouts:add'), handler)
 */
export const requireStepUp = (scope, { ttlSeconds = DEFAULT_TTL_SECONDS, requireEnrolled = false } = {}) =>
  async (req, res, next) => {
    try {
      if (!req.user) return res.status(401).json({ message: 'Not authorized' });

      const presented = req.get('x-step-up-token');
      if (presented) {
        const grant = consumeStepUpToken(String(presented));
        // Both the user AND the scope must match. A token minted for an export
        // must not open a payout, and one user's token must not work for another.
        if (grant && String(grant.userId) === String(req.user._id) && grant.scope === scope) {
          req.stepUp = { scope, expiresAt: grant.expiresAt };
          return next();
        }
      }

      const user = await User.findById(req.user._id).select('twoFactorEnabled');
      if (!user) return res.status(401).json({ message: 'Not authorized' });

      if (!user.twoFactorEnabled) {
        if (requireEnrolled) {
          return res.status(403).json({
            message: 'Two-factor authentication must be enabled before this action',
            requiresTwoFactorEnrollment: true,
            error: 'TWO_FACTOR_REQUIRED',
          });
        }
        // Property 1: no second factor on the account means no step-up is
        // possible, and refusing would lock those users out of their own account.
        req.stepUp = { scope, skipped: 'two-factor-not-enabled' };
        return next();
      }

      return res.status(403).json({
        message: 'This action requires verification',
        requiresStepUp: true,
        scope,
        error: 'STEP_UP_REQUIRED',
      });
    } catch (err) {
      return next(err);
    }
  };

export default requireStepUp;

import multer from 'multer';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs';
import { v4 as uuidv4 } from 'uuid';
import { validateMagicBytes as napiValidateMagicBytes, NATIVE_AVAILABLE } from '../services/napiImageService.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Allowed file types
const ALLOWED_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/svg+xml'];
const ALLOWED_DOC_TYPES = ['application/pdf', 'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document'];
const ALLOWED_ALL_TYPES = [...ALLOWED_IMAGE_TYPES, ...ALLOWED_DOC_TYPES];

// Max file sizes
const MAX_IMAGE_SIZE = 5 * 1024 * 1024; // 5MB
const MAX_DOC_SIZE = 10 * 1024 * 1024;  // 10MB
const MAX_ALL_SIZE = 10 * 1024 * 1024;  // 10MB

// Ensure upload directories exist
const uploadDirs = {
  avatars: path.join(__dirname, '..', '..', 'public', 'uploads', 'avatars'),
  documents: path.join(__dirname, '..', '..', 'public', 'uploads', 'documents'),
  signatures: path.join(__dirname, '..', '..', 'public', 'uploads', 'signatures'),
  reports: path.join(__dirname, '..', '..', 'public', 'uploads', 'reports'),
};

Object.values(uploadDirs).forEach(dir => {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
});

// Storage configuration
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    let uploadDir = uploadDirs.documents;

    if (file.fieldname === 'avatar' || file.fieldname === 'profile') {
      uploadDir = uploadDirs.avatars;
    } else if (file.fieldname === 'signature') {
      uploadDir = uploadDirs.signatures;
    } else if (file.fieldname === 'report' || file.fieldname === 'labReport') {
      uploadDir = uploadDirs.reports;
    }

    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    // Sanitize filename: remove special chars, spaces
    const sanitizedName = file.originalname
      .replace(/[^a-zA-Z0-9._-]/g, '_')
      .replace(/\s+/g, '_');
    const uniqueSuffix = uuidv4();
    cb(null, `${uniqueSuffix}-${sanitizedName}`);
  },
});

// File filter
function fileFilter(allowedTypes) {
  return (req, file, cb) => {
    if (allowedTypes.includes(file.mimetype)) {
      cb(null, true);
    } else {
      cb(new Error(`File type ${file.mimetype} is not allowed. Allowed types: ${allowedTypes.join(', ')}`), false);
    }
  };
}

// Magic byte signatures for content-based file type verification
const MAGIC_BYTES = {
  'image/jpeg': [Buffer.from([0xff, 0xd8, 0xff])],
  'image/png': [Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])],
  'image/gif': [Buffer.from([0x47, 0x49, 0x46, 0x38])],
  'image/webp': [Buffer.from([0x52, 0x49, 0x46, 0x46])], // RIFF....WEBP checked separately
  'application/pdf': [Buffer.from([0x25, 0x50, 0x44, 0x46])],
  'application/msword': [Buffer.from([0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x00, 0x00])],
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': [
    // ZIP signature (docx is a zip)
    Buffer.from([0x50, 0x4b, 0x03, 0x04]),
  ],
};

const isZipType = (mimetype) => mimetype.includes('officedocument');

// ClamAV malware scan — env-gated:
// - CLAMAV_HOST unset → scan skipped (dev/test default).
// - Scanner/connection error → fail-open, UNLESS CLAMAV_REQUIRED=true
//   (AUTH-021: production medical uploads must refuse unscanned files).
// Set CLAMAV_HOST (+ CLAMAV_PORT, default 3310) where a clamd sidecar runs.
let _clamavScanner = null;
let _clamavFailed = false;

const clamavRequired = () => {
  const v = process.env.CLAMAV_REQUIRED;
  if (v !== undefined && v !== '') return v === 'true';
  // P0: production defaults to REQUIRED - a missing CLAMAV_HOST (or a broken
  // scanner) must refuse uploads, not skip scanning. Dev/test stay fail-open
  // unless CLAMAV_REQUIRED=true is set explicitly.
  return process.env.NODE_ENV === 'production';
};

// CHAT-M-02: exported so chatUploadService can run the same scanner on
// base64 chat uploads (it previously served only the multer middleware path).
export async function scanBufferForMalware(buffer) {
  if (!process.env.CLAMAV_HOST || _clamavFailed) {
    if (clamavRequired()) return { clean: false, skipped: false, blocked: true };
    return { clean: true, skipped: true };
  }
  try {
    if (!_clamavScanner) {
      // clamav.js@0.12 exports an *instance*: `createScanner(port, host)`.
      // (There is no `new ClamAV()` / `scanBuffer()` API — that call shape
      // threw on every scan and tripped the fail-open path below, which is
      // what previously made this scanner silently never scan.)
      const clamav = (await import('clamav.js')).default;
      _clamavScanner = clamav.createScanner(
        Number(process.env.CLAMAV_PORT) || 3310,
        process.env.CLAMAV_HOST,
      );
    }
    const { Readable } = await import('stream');
    const malware = await new Promise((resolve, reject) => {
      // scanner.scan() takes a stream (or path), not a Buffer.
      const stream = Readable.from(buffer);
      _clamavScanner.scan(stream, (err, _obj, found) => {
        if (err) reject(err);
        else resolve(Boolean(found));
      });
    });
    return { clean: !malware, malware };
  } catch (err) {
    _clamavFailed = true;
    try {
      const logger = (await import('../config/logger.js')).default;
      logger.warn(`ClamAV scan skipped (fail-open): ${err.message}`);
    } catch {}
    if (clamavRequired()) return { clean: false, skipped: false, blocked: true };
    return { clean: true, skipped: true };
  }
}

export async function validateFileContent(buffer, mimetype) {
  if (!buffer || buffer.length < 4) return false;

  // P1-5: `file-type` content sniff is FIRST and authoritative. It knows
  // ~100+ signatures (and container structures like WEBP/OOXML) that a
  // prefix table cannot express, and — critically — it judges EVERY mime,
  // while the native/table validators below only know image prefixes and
  // fail OPEN on anything else (a PNG-bytes-as-PDF spoof sailed through).
  // A positive DETECTION that disagrees with the claimed MIME is a spoof:
  // fail closed. `undefined` (unknown to the library) falls through to the
  // validators below instead of rejecting outright.
  try {
    const { fileTypeFromBuffer } = await import('file-type');
    const detected = await fileTypeFromBuffer(buffer);
    if (detected) {
      const claimed = String(mimetype || '').toLowerCase();
      const found = String(detected.mime || '').toLowerCase();
      if (found === claimed) return true;
      // Known-equivalent spellings the routes accept.
      const ALIASES = { 'image/jpg': 'image/jpeg' };
      if (ALIASES[claimed] === found) return true;
      return false;
    }
  } catch {
    // Library unavailable/unable — fall through (route MIME allowlist +
    // ClamAV remain in front, same as before).
  }

  // Use native Rust validation when the napi module is available
  if (NATIVE_AVAILABLE) {
    return napiValidateMagicBytes(buffer, mimetype).valid;
  }

  // Fallback: pure JavaScript magic byte validation

  const signatures = MAGIC_BYTES[mimetype];
  // AUTH-021: unknown MIME → reject (fail-closed). The route-level MIME filter
  // must already have passed, so reaching here with an unknown type is a
  // bypass attempt, not a legit file.
  if (!signatures) return false;

  for (const sig of signatures) {
    if (buffer.slice(0, sig.length).equals(sig)) {
      // For WebP, verify the full RIFF....WEBP pattern
      if (mimetype === 'image/webp' && buffer.length >= 12 &&
          buffer.slice(8, 12).toString('ascii') === 'WEBP') {
        return true;
      }
      if (mimetype !== 'image/webp') return true;
    }
  }
  return false;
}

export function requireValidatedFile(allowedTypes, maxFileSize) {
  return async (req, res, next) => {
    if (!req.file) {
      return res.status(400).json({ message: 'No file uploaded' });
    }
    if (!allowedTypes.includes(req.file.mimetype)) {
      return res.status(400).json({
        message: `File type ${req.file.mimetype} is not allowed. Allowed types: ${allowedTypes.join(', ')}`,
      });
    }
    if (!(await validateFileContent(req.file.buffer, req.file.mimetype))) {
      return res.status(400).json({
        message: `File content does not match its MIME type. The file may be corrupted or malicious.`,
      });
    }
    // ClamAV malware scan — env-gated (CLAMAV_HOST unset = skip) and
    // fail-open, unless CLAMAV_REQUIRED=true blocks unscanned files.
    try {
      const { clean, malware } = await scanBufferForMalware(req.file.buffer);
      if (!clean) {
        return res.status(400).json({ message: `File rejected: malware detected (${malware || 'unknown'})` });
      }
    } catch {
      // fail-open
    }
    next();
  };
}

