import mongoose from 'mongoose';
import { hashOtp, verifyOtpHash, OTP_HASH_ALGO, ACTIVE_OTP_HASH_ALGO, resolveOtpHashAlgo } from '../services/napiOtpService.js';

const otpSchema = new mongoose.Schema({
  user: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true },
  email: { type: String, required: true, lowercase: true, index: true },
  otpHash: { type: String, required: true },
  // Explicit record of which backend produced otpHash (shared OTP_HASH_ALGO contract).
  // Optional with default so pre-existing documents without the field keep working.
  hashAlgo: {
    type: String,
    enum: Object.values(OTP_HASH_ALGO),
    default: OTP_HASH_ALGO.UNKNOWN,
  },
  type: { 
    type: String, 
    // 'email_change' — SITE-SEC 1.4 email-change flow proves possession of the
    // NEW address with its own OTP type so a valid login OTP can never be
    // replayed into an account-takeover.
    enum: ['email', 'sms', 'password_reset', 'email_change'],
    default: 'email' 
  },
  phone: { type: String, default: '' },
  used: { type: Boolean, default: false, index: true },
  expiresAt: { type: Date, index: true },
  createdAt: { type: Date, default: Date.now },
  // For rate limiting: track last OTP request time per user/email
  lastRequestAt: { type: Date, index: true }
}, { timestamps: true });

// Index for efficient query of valid, unused OTPs
otpSchema.index({ email: 1, used: 1, expiresAt: 1 });

// TTL index to automatically remove expired OTPs after 1 hour
otpSchema.index({ createdAt: 1 }, { expireAfterSeconds: 3600 });

/**
 * Hash an OTP before storing.
 * Production backend is the explicit ACTIVE_OTP_HASH_ALGO contract
 * ('rust-sha256' when native is available, otherwise 'bcrypt').
 * `hashOtp()` itself already falls back to bcrypt, so behavior is unchanged.
 */
otpSchema.statics.hashOTP = async (otp) => {
  if (ACTIVE_OTP_HASH_ALGO === OTP_HASH_ALGO.RUST_SHA256) {
    try {
      return hashOtp(otp); // Rust SHA-256 hash (returns salt:hash synchronously)
    } catch (e) {
      // Fall through to bcrypt
    }
  }
  // Fallback: bcrypt (also the active backend when native is unavailable)
  const bcrypt = (await import('bcryptjs')).default;
  return await bcrypt.hash(otp, 10);
};

/**
 * Hash an OTP and report which backend produced it (explicit contract).
 * Same hashing behavior as `hashOTP()` plus the OTP_HASH_ALGO value,
 * so callers can persist `hashAlgo` alongside `otpHash`.
 *
 * @returns {Promise<{ hash: string, algo: string }>}
 */
otpSchema.statics.hashOTPWithMeta = async (otp) => {
  if (ACTIVE_OTP_HASH_ALGO === OTP_HASH_ALGO.RUST_SHA256) {
    try {
      const hash = await hashOtp(otp);
      return { hash, algo: resolveOtpHashAlgo(hash) };
    } catch (e) {
      // Fall through to bcrypt
    }
  }
  const bcrypt = (await import('bcryptjs')).default;
  const hash = await bcrypt.hash(otp, 10);
  return { hash, algo: OTP_HASH_ALGO.BCRYPT };
};

/**
 * Compare plain OTP with stored hash.
 * Delegates to verifyOtpHash (which branches on the explicit OtpHashKind);
 * the catch-all bcrypt fallback only applies when the stored hash is
 * explicitly a bcrypt hash per the OTP_HASH_ALGO contract.
 */
otpSchema.methods.compareOTP = async function(plainOtp) {
  try {
    return await verifyOtpHash(plainOtp, this.otpHash);
  } catch (e) {
    // Explicit fallback: only bcrypt hashes can be bcrypt-compared.
    if (resolveOtpHashAlgo(this.otpHash) !== OTP_HASH_ALGO.BCRYPT) return false;
    const bcrypt = (await import('bcryptjs')).default;
    return await bcrypt.compare(plainOtp, this.otpHash);
  }
};

/**
 * Which backend produced/verifies this document's hash (explicit contract).
 * Falls back to classifying otpHash so legacy documents without `hashAlgo`
 * (default 'unknown') still resolve correctly.
 */
otpSchema.methods.resolveHashAlgo = function() {
  if (this.hashAlgo && this.hashAlgo !== OTP_HASH_ALGO.UNKNOWN) return this.hashAlgo;
  return resolveOtpHashAlgo(this.otpHash);
};

// Auto-record which backend produced otpHash (backward-compatible:
// only fills hashAlgo when it is missing/default so manual values survive).
otpSchema.pre('save', function(next) {
  try {
    if (this.isModified('otpHash') || !this.hashAlgo || this.hashAlgo === OTP_HASH_ALGO.UNKNOWN) {
      const resolved = resolveOtpHashAlgo(this.otpHash);
      if (resolved !== OTP_HASH_ALGO.UNKNOWN) this.hashAlgo = resolved;
    }
  } catch {
    // Never block saving on algo bookkeeping
  }
  if (typeof next === 'function') next();
});

/**
 * Check if OTP is valid (not used and not expired)
 */
otpSchema.methods.isValid = function() {
  return !this.used && this.expiresAt > new Date();
};

export default mongoose.model('OTP', otpSchema);

/**
 * REC-M-02: an append-only version history for clinical records.
 *
 * Records used to update IN PLACE. A medico-legal requirement is that any edit to
 * clinical data leaves a trail of who changed what, and when — and an in-place
 * update destroys the previous state, so the trail was unrecoverable by
 * construction rather than by accident.
 *
 * Properties that matter, and why:
 *
 *  1. APPEND-ONLY. No update, no delete, and no route that would accept one. A
 *     version history that can itself be edited is not an audit trail.
 *  2. The snapshot is the WHOLE prior document, not a diff. A diff is only
 *     reconstructible by replaying the chain, so one lost version makes every
 *     later one unreadable. Storage is cheap; a medico-legal trail that can
 *     silently lose a link is not.
 *  3. `version` is monotonic per record and enforced by a UNIQUE compound index,
 *     so two concurrent edits cannot both claim version N.
 *  4. The CHAIN HASH makes tampering detectable: each snapshot carries the hash
 *     of the previous one, so removing or altering an entry breaks every hash
 *     after it. That is what separates "we log it" from "we can prove it".
 */
import mongoose from 'mongoose';
import crypto from 'node:crypto';

const recordVersionSchema = new mongoose.Schema({
  recordId: { type: mongoose.Schema.Types.ObjectId, ref: 'Record', required: true, index: true },
  version: { type: Number, required: true, min: 1 },
  // The complete document as it stood BEFORE this edit.
  snapshot: { type: mongoose.Schema.Types.Mixed, required: true },
  // Field-level diff, for a human reviewer. Informational only - never the
  // source of truth, per property 2.
  changed: [{ field: String, from: mongoose.Schema.Types.Mixed, to: mongoose.Schema.Types.Mixed }],

  editedBy: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  editedByRole: { type: String, default: '' },
  editedByName: { type: String, default: '' },
  editReason: { type: String, default: '' },
  ip: { type: String, default: '' },
  userAgent: { type: String, default: '' },
  createdAt: { type: Date, default: Date.now },

  // Chain hash. A tampered or removed entry breaks every hash after it.
  prevHash: { type: String, default: '' },
  hash: { type: String, required: true },
}, { versionKey: false });

// One version N per record: two concurrent edits cannot both claim the same slot.
recordVersionSchema.index({ recordId: 1, version: 1 }, { unique: true });
// History is read newest-first far more often than in full.
recordVersionSchema.index({ recordId: 1, createdAt: -1 });

/** Fields that are never clinically meaningful and would only add noise. */
const IGNORED_IN_DIFF = new Set(['updatedAt', '__v', '_id', 'createdAt']);

export const computeVersionHash = (recordId, version, snapshot, prevHash, at) =>
  crypto
    .createHash('sha256')
    .update(
      JSON.stringify({
        recordId: String(recordId),
        version,
        // Sorted keys, so the hash does not depend on property insertion order.
        snapshot: Object.fromEntries(Object.entries(snapshot || {}).sort(([a], [b]) => (a < b ? -1 : 1))),
        prevHash: prevHash || '',
        at: new Date(at).toISOString(),
      })
    )
    .digest('hex');

/**
 * Field-level diff between two versions of a record.
 *
 * Nested objects are compared as a whole rather than recursed into: a partial
 * clinical object is ambiguous to read, and a flat "this object changed" entry is
 * more honest than a deep diff that silently drops keys on a shape change.
 */
export const diffRecord = (before = {}, after = {}) => {
  const keys = new Set([...Object.keys(before || {}), ...Object.keys(after || {})]);
  const out = [];
  for (const key of keys) {
    if (IGNORED_IN_DIFF.has(key)) continue;
    const a = before?.[key];
    const b = after?.[key];
    if (JSON.stringify(a ?? null) === JSON.stringify(b ?? null)) continue;
    out.push({ field: key, from: a ?? null, to: b ?? null });
  }
  return out;
};

/**
 * Append a version.
 *
 * A duplicate-key error is rethrown rather than swallowed: it means two edits
 * raced for the same version number, and quietly taking the loser's snapshot
 * would drop a clinical change out of the trail.
 */
recordVersionSchema.statics.appendVersion = async function appendVersion({
  recordId, before, after, editedBy, editedByRole = '', editedByName = '',
  editReason = '', ip = '', userAgent = '', at = new Date(),
}) {
  const prev = await this.findOne({ recordId }).sort({ version: -1 }).select('version hash').lean();
  const version = (prev?.version || 0) + 1;
  const prevHash = prev?.hash || '';
  const hash = computeVersionHash(recordId, version, before || {}, prevHash, at);

  return this.create({
    recordId,
    version,
    snapshot: before || {},
    changed: diffRecord(before, after),
    editedBy, editedByRole, editedByName, editReason, ip, userAgent,
    createdAt: at,
    prevHash, hash,
  });
};

/**
 * Verify a chain end to end.
 *
 * Returns the first broken link rather than a boolean, because "the audit trail
 * is broken" is useless without knowing WHERE. Any ok:false is an incident.
 */
recordVersionSchema.statics.verifyChain = async function verifyChain(recordId) {
  const versions = await this.find({ recordId }).sort({ version: 1 }).lean();
  if (versions.length === 0) return { ok: true, count: 0, reason: 'no-versions' };

  let prevHash = '';
  for (let i = 0; i < versions.length; i++) {
    const v = versions[i];
    if (v.version !== i + 1) return { ok: false, brokenAt: v.version, reason: 'version-gap' };
    if (v.prevHash !== prevHash) return { ok: false, brokenAt: v.version, reason: 'prev-hash-mismatch' };
    const expected = computeVersionHash(v.recordId, v.version, v.snapshot, v.prevHash, v.createdAt);
    if (expected !== v.hash) return { ok: false, brokenAt: v.version, reason: 'hash-mismatch' };
    prevHash = v.hash;
  }
  return { ok: true, count: versions.length };
};

export default mongoose.models.RecordVersion
  || mongoose.model('RecordVersion', recordVersionSchema);

import mongoose from 'mongoose';
import { createHash } from 'node:crypto';
import { hashOtp, verifyOtpHash } from '../services/napiOtpService.js';

const refreshTokenSchema = new mongoose.Schema({
  userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User', required: true, index: true },
  // tokenKey: an indexed lookup key for the token.
  //
  // It was `token.substring(0, 16)`, which sounds like a safe prefix but is a
  // CONSTANT: a JWT is `base64url(header).base64url(payload).signature`, and the
  // header is identical for every token this service signs (`{"alg":"HS256",
  // "typ":"JWT"}` -> `eyJhbGciOiJIUzI1...`). Verified: three tokens for three
  // different users produced the identical key `eyJhbGciOiJIUzI1`.
  //
  // Consequences of that, all real:
  //  - `findOne({ tokenKey })` returned an ARBITRARY row from the whole
  //    collection, not the caller's.
  //  - `/refresh` acts on that row BEFORE verifying the presented token against
  //    its hash, and the reuse-detection branch runs
  //    `deleteMany({ userId })`. So any caller could send the 16-byte constant
  //    plus arbitrary filler - a string that is not a token at all - and force
  //    logout of whichever user the lookup happened to land on. A mass-logout
  //    DoS with no credential.
  //  - Legitimate concurrent refreshes for two different users raced on the
  //    same key.
  //
  // A SHA-256 of the whole token is deterministic, indexed, and collision-free
  // in practice. It stores no secret material (the token itself is still hashed
  // separately in `tokenHash`).
  tokenKey: { type: String, required: true, index: true },
  // tokenHash: salted hash of the full token (rust-sha256 or bcrypt)
  tokenHash: { type: String, required: true, select: false },
  expiresAt: { type: Date, required: true },
  // MISS-002: rotation family + reuse detection.
  jti: { type: String, index: true },
  familyId: { type: String, index: true },
  replacedBy: { type: String, default: null }, // jti of the successor (null = live)
  revokedAt: { type: Date, default: null },
  userAgent: { type: String, default: '' },
  ip: { type: String, default: '' },
  createdAt: { type: Date, default: Date.now },
}, { timestamps: true });

refreshTokenSchema.index({ expiresAt: 1 }, { expireAfterSeconds: 0 });

/**
 * Lookup key for a refresh token: the first 32 hex chars of its SHA-256.
 *
 * Must be a function of the WHOLE token. A prefix is not safe here — see the
 * `tokenKey` comment above for why the previous 16-char prefix was a constant.
 */
refreshTokenSchema.statics.getTokenKey = (token) =>
  createHash('sha256').update(String(token)).digest('hex').slice(0, 32);

// Static method to hash token for storage
refreshTokenSchema.statics.hashToken = async (token) => {
  const { hashOtp } = await import('../services/napiOtpService.js');
  return await hashOtp(token);
};

// Instance method to compare plain token with stored hash
refreshTokenSchema.methods.compareToken = async function(plainToken) {
  const { verifyOtpHash } = await import('../services/napiOtpService.js');
  return await verifyOtpHash(plainToken, this.tokenHash);
};

// Pre-save hook to hash token if it's a plain token
refreshTokenSchema.pre('save', async function() {
  if (this.isModified('tokenHash') && this.tokenHash && 
      !this.tokenHash.startsWith('$2a$') && 
      !this.tokenHash.startsWith('$2b$') && 
      !this.tokenHash.startsWith('$2y$') && 
      !this.tokenHash.includes(':')) {
    // Plain token detected - hash it before saving
    const { hashOtp } = await import('../services/napiOtpService.js');
    this.tokenHash = await hashOtp(this.tokenHash);
  }
});

export default mongoose.model('RefreshToken', refreshTokenSchema);

import mongoose from 'mongoose';
import bcrypt from 'bcryptjs';
import argon2 from 'argon2';
import crypto from 'node:crypto';
import { generate16DigitId } from '../utils/idGenerator.js';
import { canonicalRole } from '../config/permissions.js';
import { encryptPhi, decryptPhi } from '../utils/phiFields.js';

// P2-11: Argon2id is the default password hasher (m=19456, t=2, p=1 —
// OWASP minimums). bcrypt-cost-12 remains readable forever so every
// existing row keeps verifying, and upgrades transparently on next login.
// Escape hatch: PASSWORD_HASHER=bcrypt (new hashes stay bcrypt).
const ARGON_OPTS = { type: argon2.argon2id, memoryCost: 19456, timeCost: 2, parallelism: 1 };
export const passwordHasher = () =>
  String(process.env.PASSWORD_HASHER || 'argon2').toLowerCase() === 'bcrypt' ? 'bcrypt' : 'argon2';

export async function hashNewPassword(plain) {
  const pepper = getPasswordPepper();
  const material = pepper ? peppered(plain, pepper) : String(plain);
  if (passwordHasher() === 'bcrypt') return bcrypt.hash(material, BCRYPT_ROUNDS);
  return argon2.hash(material, ARGON_OPTS);
}

async function verifyAgainstHash(material, hash) {
  try {
    if (String(hash).startsWith('$argon2')) return await argon2.verify(hash, material);
    return await bcrypt.compare(material, hash);
  } catch {
    return false;
  }
}

// P2-11: server-side pepper. When PASSWORD_PEPPER is set (secret manager, NOT
// the DB), passwords are HMAC-SHA256'd with it BEFORE bcrypt, so a DB-only
// leak (dump/backup/SQLi) gives an attacker hashes that still need the pepper
// to crack. Unset = disabled (zero behaviour change); enabling later upgrades
// hashes transparently on next successful login (see comparePassword).
export const getPasswordPepper = () => {
  const p = String(process.env.PASSWORD_PEPPER || '');
  return p.length >= 16 ? p : '';
};

const peppered = (plain, pepper) =>
  crypto.createHmac('sha256', pepper).update(String(plain), 'utf8').digest('hex');

// Compare a plaintext candidate against a stored hash (argon2id or bcrypt),
// trying the peppered form first and falling back to the legacy unpeppered
// form (pre-pepper rows). Returns { ok, legacy } so callers can trigger a
// re-hash upgrade.
export async function passwordMatchesHash(plain, hash) {
  const pepper = getPasswordPepper();
  if (pepper) {
    if (await verifyAgainstHash(peppered(plain, pepper), hash)) return { ok: true, legacy: false };
    if (await verifyAgainstHash(String(plain), hash)) return { ok: true, legacy: true };
    return { ok: false, legacy: false };
  }
  const ok = await verifyAgainstHash(String(plain), hash);
  return { ok, legacy: false };
}

