// The env override exists for controlled migration runs only and is clamped so
// it can never weaken a production login below the old cost 10.
const BCRYPT_ROUNDS = (() => {
  const n = Number(process.env.BCRYPT_ROUNDS);
  return Number.isInteger(n) && n >= 10 && n <= 15 ? n : 12;
})();

userSchema.pre('save', async function () {
  if (this.isModified('password')) {
    this.password = await hashNewPassword(this.password);
  }
});

userSchema.pre('save', function (next) {
  if (!this.uhid) {
    this.uhid = generate16DigitId();
  }
  if (typeof next === 'function') next();
});

// AUTH-015: single source of truth is top-level twoFactorEnabled; the legacy
// settings copy is force-synced so the two flags can never diverge again.
userSchema.pre('save', function (next) {
  if (this.isModified('twoFactorEnabled') && this.settings && typeof this.settings === 'object') {
    this.settings = { ...this.settings, twoFactorEnabled: this.twoFactorEnabled };
    this.markModified('settings');
  }
  if (typeof next === 'function') next();
});

userSchema.methods.comparePassword = async function (plain) {
  const { ok, legacy } = await passwordMatchesHash(plain, this.password);
  if (ok) {
    // P2-9/P2-11: opportunistic upgrade — a bcrypt row (any cost), a hash
    // minted at an older bcrypt cost, or a pre-pepper row is silently
    // re-hashed to argon2id on the next successful login. The pre-save hook
    // does the hashing; a failure here must never fail the login itself.
    try {
      const stored = String(this.password);
      const cost = stored.startsWith('$2')
        ? Number.parseInt(stored.slice(4, 6), 10)
        : null;
      const needsRehash = legacy
        || (passwordHasher() === 'argon2' && !stored.startsWith('$argon2'))
        || (Number.isInteger(cost) && cost < BCRYPT_ROUNDS);
      if (needsRehash) {
        this.password = plain;
        await this.save();
      }
    } catch { /* keep the successful login */ }
  }
  return ok;
};

// AUTHZ-B-05: collapse the deprecated `counselor` spellings on write so the
// collection converges on ONE canonical value. Legacy rows are migrated by
// scripts/migrate-role-aliases.mjs, and `canonicalRole()` in config/permissions.js
// keeps authorization correct for anything written before this hook existed.
userSchema.pre('save', function canonicaliseRoleAlias(next) {
  if (this.role) {
    const canonical = canonicalRole(this.role);
    if (canonical !== this.role) this.role = canonical;
  }
  if (typeof next === 'function') next();
});

// Same hook for `findOneAndUpdate` / `updateOne`, which never trigger `save`.
userSchema.pre(['updateOne', 'findOneAndUpdate'], function canonicaliseRoleAliasOnUpdate(next) {
  const update = this.getUpdate() || {};
  if (update.$set && update.$set.role) {
    update.$set.role = canonicalRole(update.$set.role);
    this.setUpdate(update);
  }
  if (typeof next === 'function') next();
});

export default mongoose.model('User', userSchema);

// §5.3/§5.4: never let secrets/internal flags leave in a response — `select: false`
// is bypassed by .lean()/.select('+password'), so strip at the DTO boundary too.
const USER_FORBIDDEN_FIELDS = new Set([
  'password', 'passwordHistory', 'tokenVersion', 'twoFactorSecret', 'twoFactorTempSecret',
  'twoFactorBackupCodes', 'driveTokens', 'abhaOtpHash', '__v',
]);

export function sanitizeUserDto(input) {
  if (!input || typeof input !== 'object') return input;
  const obj = typeof input.toObject === 'function' ? input.toObject() : { ...input };
  for (const field of USER_FORBIDDEN_FIELDS) delete obj[field];
  return obj;
}

export { USER_FORBIDDEN_FIELDS };

import express from 'express';
import AssistantProfile from '../models/AssistantProfile.js';
import AssistantBooking from '../models/AssistantBooking.js';
import User from '../models/User.js';
import Notification from '../models/Notification.js';
import { protect, requireRole } from '../middleware/auth.js';
// ADM-B-01 / DLB-11: on-demand providers are a PLATFORM marketplace, not a tenant.
// Their profiles carry Aadhaar, driving-licence and bank details, and the models
// have no hospitalId to scope by - so dminOnly (which a hospital_admin holds)
// gave every hospital KYC PII, plate numbers, bank details and ride analytics for
// every other hospital. These are platform-level operations: superadmin only -
// except the three verification-queue routes below, which the ops console's
// kyc_reviewer also holds (8.md 2). Both are platform roles; neither is ever
// hospital-scoped.
import { platformAdminOnly } from '../middleware/authorize.js';
import { auditLog } from '../middleware/audit.js';
import logger from '../config/logger.js';
import { escapeRegex, capSearch } from '../utils/escapeRegex.js';

const router = express.Router();

// Platform access for all routes in this file; each route keeps its own guard,
// so the kyc_reviewer reaches the queue only, never /suspend, /all, /bookings
// or /analytics.
router.use(protect, requireRole(['superadmin', 'kyc_reviewer']));

// ─── GET /api/admin/assistants/pending ──────────────────────────────────────
// Pending verification queue
router.get('/pending', requireRole(['superadmin', 'kyc_reviewer']), async (req, res) => {
  try {
    const assistants = await AssistantProfile.find({ assistantStatus: 'pending_approval' })
      .populate('userId', 'name email phone avatar address dateOfBirth gender createdAt')
      .sort({ createdAt: -1 })
      .lean();

    res.json({ assistants });
  } catch (err) {
    logger.error(`Get pending assistants error: ${err.message}`);
    res.status(500).json({ message: 'Failed to fetch pending assistants' });
  }
});

// ─── GET /api/admin/assistants/all ──────────────────────────────────────────
// List all assistants with status filter
router.get('/all', platformAdminOnly, async (req, res) => {
  try {
    const { status, hospital, search } = req.query;
    const query = {};

    if (status && status !== 'all') {
      query.assistantStatus = status;
    }
    if (hospital) {
      query.hospitalsCovered = { $in: [new RegExp(escapeRegex(capSearch(hospital)), 'i')] };
    }

    let assistants = await AssistantProfile.find(query)
      .populate('userId', 'name email phone avatar gender createdAt')
      .sort({ createdAt: -1 })
      .lean();

    if (search) {
      const s = search.toLowerCase();
      assistants = assistants.filter(a =>
        a.userId?.name?.toLowerCase().includes(s) ||
        a.userId?.email?.toLowerCase().includes(s) ||
        a.userId?.phone?.includes(s)
      );
    }

    res.json({ assistants, total: assistants.length });
  } catch (err) {
    logger.error(`Get all assistants error: ${err.message}`);
    res.status(500).json({ message: 'Failed to fetch assistants' });
  }
});

// ─── PUT /api/admin/assistants/:id/approve ──────────────────────────────────
// Approve assistant application
router.put('/:id/approve', requireRole(['superadmin', 'kyc_reviewer']), async (req, res) => {
  try {
