// Book a hospital assistant
router.post('/book', protect, validate(bookAssistantSchema), bookingLimiter, async (req, res) => {
  try {
    const {
      assistantId,
      hospital,
      serviceCategories,
      isUrgent = false,
      targetAssistantOnly = false,
      intakeSource = 'scheduled_profile_form',
      urgencyWindow = 'asap',
      onBehalfOf = 'self',
      familyMemberId,
      otherPatient,
      taskDescription,
      phone,
      documents = [],
      scheduledDate,
      startTime,
      durationType = '4hr',
      specialInstructions,
      patientAllergies = [],
    } = req.body;

    // Check if user already has an active or in-progress booking
    const existingActive = await AssistantBooking.findOne({
      patientId: req.user._id,
      status: { $in: ['requested', 'confirmed', 'in_progress'] },
    });

    if (existingActive) {
      return res.status(400).json({
        message: 'You already have an active assistant booking.',
        activeBookingId: existingActive._id,
      });
    }

    let rate = 150;
    let targetAssistantId = assistantId || null;

    if (targetAssistantId) {
      const profile = await AssistantProfile.findOne({
        $or: [{ userId: targetAssistantId }, { _id: targetAssistantId }],
      });
      if (profile) {
        rate = profile.pricePerHour || 150;
        targetAssistantId = profile.userId;
      }
    }

    const cost = calculateBookingCost(rate, durationType);
    const taskChecklist = buildChecklistForBooking(serviceCategories);

    const { executeWithOutbox } = await import('../lib/transactionalOutbox.js');
    const booking = await executeWithOutbox(
      async (session) => {
        const [created] = await AssistantBooking.create([
          {
            patientId: req.user._id,
            assistantId: targetAssistantId,
            hospital,
            serviceCategories,
            isUrgent,
            targetAssistantOnly: Boolean(targetAssistantOnly),
            intakeSource,
            urgencyWindow,
            onBehalfOf,
            familyMemberId: familyMemberId || null,
            otherPatient: otherPatient || {},
            taskDescription: taskDescription || specialInstructions || '',
            phone: phone || req.user.phone || '',
            documents: documents || [],
            scheduledDate: scheduledDate ? new Date(scheduledDate) : new Date(),
            startTime: startTime || 'Now',
            durationType,
            specialInstructions: specialInstructions || taskDescription || '',
            patientAllergies: Array.isArray(patientAllergies)
              ? patientAllergies.map(String).slice(0, 20)
              : [],
            cost,
            status: isUrgent && !targetAssistantId ? 'searching' : 'requested',
            taskChecklist,
            statusHistory: [{ status: isUrgent && !targetAssistantId ? 'searching' : 'requested', at: new Date(), note: 'Booking created' }],
          },
        ], { session });
        return created;
      },
      [
        {
          aggregateType: 'AssistantBooking',
          aggregateId: req.user._id,
          eventType: 'AssistantBookingCreated.v1',
          destinationTopic: 'findmedi.dispatch.booking-events.v1',
          payload: {
            patientId: req.user._id,
            hospital,
            serviceCategories,
            isUrgent,
            cost,
          },
        },
      ]
    );

    // Populate patient info for broadcast & notification
    await booking.populate('patientId', 'name phone avatar');

    if (targetAssistantId) {
      // Direct booking to specific assistant
      await Notification.create({
        userId: String(targetAssistantId),
        title: '🧑‍⚕️ New Assistant Booking Request!',
        message: `${req.user.name || 'A patient'} has booked your assistance at ${hospital} for ${durationType.toUpperCase()}.`,
        type: 'assistant',
        referenceId: String(booking._id),
      }).catch(() => {});
      broadcastAssistantBooking(booking).catch(() => {});
    } else if (isUrgent) {
      startAssistantDispatch(booking._id).catch(err => {
        logger.warn(`Assistant wave dispatch warning: ${err.message}`);
      });
    } else {
      broadcastAssistantBooking(booking).catch(() => {});
    }

    res.status(201).json({
      success: true,
      message: isUrgent
        ? 'Dispatched urgent assistant request via wave alert engine...'
        : 'Booking request sent to assistant. Awaiting confirmation.',
      booking,
    });
  } catch (err) {
    logger.error(`Book assistant error: ${err.message}`);
    res.status(500).json({ message: 'Failed to create booking', error: err.message });
  }
});

