// AUTH-F-02: `typ` marks the purpose. A refresh token is a 7-day rotating
// session secret; without this claim it verified as an access token on every
// endpoint (protect now rejects it via verifyAccessToken).
// AUTH claims minimisation: the access token carries identity + purpose only.
// `name`/`email` were never read back — protect() loads the user from the DB
// on every request and nothing decodes the JWT for profile data (verified by
// repo-wide grep) — so they only widened what a leaked token discloses.
// Tokens minted before this still verify; the claims are simply ignored.
const signAccessToken = (user) => signJwt(
  { id: user._id, role: user.role, tv: user.tokenVersion || 0, jti: crypto.randomBytes(8).toString('hex'), typ: ACCESS_TOKEN_TYP },
  { expiresIn: '15m' }
);

const signRefreshToken = (user, familyId) => {
  const jti = crypto.randomBytes(12).toString('hex');
  const token = signJwt(
    { id: user._id, tv: user.tokenVersion || 0, jti, family: familyId || jti, typ: REFRESH_TOKEN_TYP },
    { expiresIn: '7d' }
  );
  return { token, jti, familyId: familyId || jti };
};

const sign = (user, req) => {
  const accessToken = signAccessToken(user);
  const { token: refreshToken, jti, familyId } = signRefreshToken(user);
  const tokenKey = RefreshToken.getTokenKey(refreshToken);
  RefreshToken.create({
    userId: user._id,
    tokenKey,
    tokenHash: refreshToken, // will be hashed by pre-save hook
    jti,
    familyId,
    userAgent: req?.get?.('user-agent') || '',
    ip: req?.ip || '',
    expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  }).catch(err => logger.error('Failed to save refresh token:', err.message));
  // P2-10: concurrent session cap — evict oldest live sessions beyond the
  // role cap (fire-and-forget; never fails the login itself).
  enforceConcurrentCap(user._id, user.role).catch(() => {});
  // Checklist I8 / P2-31: a fresh login STARTS the idle-PIN window.
  //
  // protect() runs checkIdleLock BEFORE updateActivity, so an account whose
  // lastActivityAt was stamped beyond IDLE_LOCK_WINDOW_MS (15 min default)
  // would mint a session that is rejected on its very first call — right after
  // the caller proved their password. That is a deadlock for an account with
  // no PIN: the idle overlay has no close affordance on purpose, and it tells
  // the user to set a PIN in Settings — which itself sits behind protect().
  //
  // Only the credential paths call sign(); /auth/refresh mints through
  // signRefreshToken directly, so a background auto-refresh still does NOT
  // advance the window — otherwise the lock could never be reached.
  //
  // Fire-and-forget and fail-soft, like the two calls above: User.updateOne is
  // often stubbed in tests (sometimes returning undefined), user may be a
  // frozen stub, and no login has ever failed because a bookkeeping write did.
  try {
    const stamped = new Date();
    user.lastActivityAt = stamped;
    Promise.resolve(User.updateOne({ _id: user._id }, { $set: { lastActivityAt: stamped } })).catch(
      (err) => logger.error('Failed to stamp login activity:', err?.message)
    );
  } catch {
    /* never fail the login */
  }
  return { accessToken, refreshToken };
};

// AUTH-012: password change/reset/logout-all funnels through here — every
// other session dies with the version bump + document purge.
const revokeAllSessions = async (userId) => {
