// POST /api/billing — create a new bill
// DLB-26: validated + allow-listed. The body is no longer spread into the
// document, so `hospitalId` / `facilityId` / `balance` / `_id` / `createdAt`
// can no longer be injected; the tenant is always the caller's own.
router.post('/', protect, authorize('billing:write'), paymentLimiter, validate(createBillingSchema), async (req, res, next) => {
  try {
    // File 13 §13.6: blacklisted/deceased patients are a hard stop at billing.
    if (req.body.patientId) {
      const { patientHardStop } = await import('./masters.js');
      const stop = await patientHardStop(req.user.hospitalId, req.body.patientId).catch(() => null);
      if (stop) return res.status(409).json({ message: `Billing blocked: patient is ${stop}`, code: 'PATIENT_HARD_STOP' });
    }
    // File 22 P0-1: over-policy discounts need a consumed approval.
    const { discountPct, overDiscountPolicy, approverRolesFor, safeFirst } = await import('../lib/approvalWiring.js');
    const pct = discountPct(req.body || {});
    let approvalRef = null;
    if (pct > 0) {
      const { default: DiscountPolicy } = await import('../models/DiscountPolicy.js');
      const policy = await safeFirst(DiscountPolicy.findOne({
        hospitalId: req.user.hospitalId, role: req.user.role, active: true,
      }).lean());
      if (overDiscountPolicy(pct, policy, req.user.role)) {
        const { ensureApproval, approvalError } = await import('./approvals.js');
        try {
          const approval = await ensureApproval({
            req, policyKey: 'billing-discount',
            entityRef: { model: 'Billing', id: null },
            title: `Discount ${pct.toFixed(1)}% on ₹${Number(req.body.amount) || 0}`,
            amount: Number(req.body.amount) || 0,
            roles: approverRolesFor(policy, 'billing-discount'),
          });
          approvalRef = approval._id;
        } catch (e) {
          if (approvalError(res, e)) return undefined;
          throw e;
        }
      }
    }
    const date = req.body.date || getISTDateString();
    // File 22 P1-14: series numbering (atomic counter per hospital+prefix+FY).
    let invoiceId = req.body.invoiceId;
    let seriesUsed = '';
    if (!invoiceId && req.body.invoiceSeries) {
      const { default: InvoiceSeries } = await import('../models/InvoiceSeries.js');
      const now = new Date();
      const fyStart = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
      const fy = `${String(fyStart).slice(2)}-${String(fyStart + 1).slice(2)}`;
      const prefix = String(req.body.invoiceSeries).slice(0, 12).toUpperCase();
      const counter = await InvoiceSeries.findOneAndUpdate(
        { hospitalId: req.user.hospitalId, prefix, fy },
        { $inc: { next: 1 } },
        { upsert: true, new: true },
      );
      invoiceId = `${prefix}/${fy}/${String(counter.next - 1).padStart(5, '0')}`;
      seriesUsed = prefix;
    }
    if (!invoiceId) invoiceId = generateInvoiceId();
    // File 22 P1-14: GST auto-total from line rates (only when client did not
    // send an explicit tax — never silently overwrite a stated total).
    const body = { ...req.body };
    if ((body.tax == null || body.tax === 0) && Array.isArray(body.services) && body.services.some((s) => Number(s.gstRate) > 0)) {
      body.tax = +body.services.reduce((t, s) => t + (Number(s.price) || 0) * (Number(s.quantity) || 1) * (Number(s.gstRate) || 0) / 100, 0).toFixed(2);
      body.taxableAmount = body.services.reduce((t, s) => t + (Number(s.price) || 0) * (Number(s.quantity) || 1), 0);
    }
    let cgst = 0, sgst = 0, igst = 0, placeOfSupply = '';
    if ((body.tax || 0) > 0) {
      try {
        const { default: Hospital } = await import('../models/Hospital.js');
        const hosp = req.user.hospitalId
          ? await Hospital.findById(req.user.hospitalId).lean().catch(() => null)
          : null;
        const hospState = hosp?.state || '';
        let patientState = hospState;
        if (body.patientId) {
          const { default: Patient } = await import('../models/Patient.js');
          const pat = await Patient.findById(body.patientId).lean().catch(() => null);
          const addr = pat?.address || '';
          const stateMatch = addr.match(/,\s*([A-Za-z\s]+?)(?:\s+\d{6})?\s*$/);
          if (stateMatch) patientState = stateMatch[1].trim();
        }
        const split = computeGstSplit(body.tax, hospState, patientState);
        cgst = split.cgst; sgst = split.sgst; igst = split.igst; placeOfSupply = split.placeOfSupply;
      } catch (e) {
        // If Hospital/Patient lookups fail (e.g. in tests), default to CGST+SGST
        const taxVal = Number(body.tax) || 0;
        cgst = +(taxVal / 2).toFixed(2);
        sgst = +(taxVal - cgst).toFixed(2);
      }
    }
    const packageCap = Number(body.packageCap) || 0;
    const overage = packageCap > 0 ? Math.max(0, (Number(body.amount) || 0) - packageCap) : 0;
    const bill = await Billing.create({
      ...body,
      approvalRef,
      invoiceId,
      invoiceSeries: seriesUsed,
      overage,
      cgst, sgst, igst, placeOfSupply,
      date,
      encounterId: body.encounterId || undefined,
      appointmentId: body.appointmentId || undefined,
      admissionId: body.admissionId || undefined,
      hospitalId: req.user.hospitalId || undefined,
      facilityId: req.user.facilityId || undefined,
    });
    await auditLog('create_billing', req.user._id, { billId: bill._id, invoiceId, amount: bill.amount });
    void import('../lib/pgDualWrite.js').then((m) => m.mirrorBilling(bill)).catch(() => {});
    res.status(201).json(bill);
  } catch (err) { next(err); }
});

