// Distinct provider and facility counts for every browse tile in one request.
// Cross-listed codes contribute to every parent while each provider is counted
// only once per parent.
router.get('/specialties/counts', async (req, res) => {
  try {
    const filters = [];
    if (req.query.approvedOnly !== 'false') filters.push({ approved: true });
    if (req.query.city) {
      const cityRegex = new RegExp(`^${escapeRegex(String(req.query.city))}`, 'i');
      filters.push({ $or: [{ city: cityRegex }, { location: cityRegex }] });
    }
    if (req.query.facilityId) filters.push({ $or: [{ facilityId: req.query.facilityId }, { hospitalId: req.query.facilityId }] });
    const filter = filters.length > 1 ? { $and: filters } : (filters[0] || {});

    const doctors = await Doctor.find(filter)
      .select('_id specialtyCode specialization subSpecialtyCodes facilityId hospitalId')
      .lean();
    const rootCodes = SPECIALTIES.filter((s) => /^SPEC\.[A-Z0-9]+$/.test(s.code)).map((s) => s.code);
    const counts = Object.fromEntries(rootCodes.map((code) => [code, { doctors: 0, facilities: 0 }]));
    const doctorSets = new Map(rootCodes.map((code) => [code, new Set()]));
    const facilitySets = new Map(rootCodes.map((code) => [code, new Set()]));

    for (const doctor of doctors) {
      const specialtyCodes = new Set([
        resolveSpecialtyCode(doctor.specialtyCode),
        resolveSpecialtyCode(doctor.specialization),
        ...[...(doctor.subSpecialtyCodes || [])].map(resolveSpecialtyCode),
      ].filter(Boolean));
      const matchingRoots = new Set();
      for (const code of specialtyCodes) {
        const entry = SPECIALTIES.find((item) => item.code === code);
        if (!entry) continue;
        const root = /^SPEC\.[A-Z0-9]+$/.test(code) ? code : code.split('.').slice(0, 2).join('.');
        if (doctorSets.has(root)) matchingRoots.add(root);
        for (const parent of entry.alsoUnder || []) if (doctorSets.has(parent)) matchingRoots.add(parent);
      }
      const id = String(doctor._id);
      const facilityIds = [doctor.hospitalId, doctor.facilityId].filter(Boolean).map(String);
      for (const root of matchingRoots) {
        doctorSets.get(root).add(id);
        for (const facilityId of facilityIds) facilitySets.get(root).add(facilityId);
      }
    }
    for (const code of rootCodes) {
      counts[code] = { doctors: doctorSets.get(code).size, facilities: facilitySets.get(code).size };
    }

    res.setHeader('Cache-Control', 'public, max-age=60');
    res.json({ counts });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// authz: public - one specialty with subs + condition/procedure chips
router.get('/specialties/:code', (req, res) => {
  const resolved = resolveSpecialtyCode(req.params.code || '');
  const hit = resolved ? SPECIALTIES.find((s) => s.code === resolved) : null;
  if (!hit) return res.status(404).json({ message: 'Specialty not found' });
  res.setHeader('Cache-Control', 'public, max-age=300');

  const isTop = /^SPEC\.[A-Z0-9]+$/.test(hit.code);
  let subs = [];
  if (isTop) {
    // Own-code subs + cross-listed subs (alsoUnder points at us): one record,
    // rendered under both parents upstream (§4 duplicate-records rule).
    const prefix = `${hit.code}.`;
    subs = SPECIALTIES.filter(
      (s) => s.code.startsWith(prefix) || (s.alsoUnder || []).includes(hit.code),
    );
  }

  const topCode = isTop ? hit.code : hit.code.split('.').slice(0, 2).join('.');

  res.json({
    code: hit.code,
    name: hit.name,
    nameHi: hit.meta?.nameHi || '',
    aliases: hit.aliases,
    sensitive: !!hit.sensitive || !!hit.meta?.sensitive,
    adClaimsRestricted: !!hit.adClaimsRestricted || !!hit.meta?.adClaimsRestricted,
    claimsRestricted: !!hit.claimsRestricted,
    meta: hit.meta,
    alsoUnder: hit.alsoUnder || [],
    subs: subs.map((s) => ({
      code: s.code,
      name: s.name,
      aliases: s.aliases,
      sensitive: !!s.sensitive || !!s.meta?.sensitive,
      claimsRestricted: !!s.claimsRestricted,
      alsoUnder: s.alsoUnder || [],
      meta: s.meta,
    })),
    conditions: hit.meta?.conditions || [],
    procedures: hit.meta?.procedures || [],
    symptoms: hit.meta?.symptoms || [],
    parent: isTop ? null : topCode,
    topCode,
  });
});

// authz: public - distinct doctor/hospital counts for a specialty tile in context
// Parent count = parent + all subs (own + cross-listed) UNION'd in one $in query
// so a doctor tagged with two subs is never double-counted.
router.get('/specialties/:code/counts', async (req, res) => {
  try {
    const { city, facilityId, approvedOnly = 'true' } = req.query;
    const resolved = resolveSpecialtyCode(req.params.code || '');
    const hit = resolved ? SPECIALTIES.find((s) => s.code === resolved) : null;
    if (!hit) return res.status(404).json({ message: 'Specialty not found' });

    const isTop = /^SPEC\.[A-Z0-9]+$/.test(hit.code);
    const topCode = isTop ? hit.code : hit.code.split('.').slice(0, 2).join('.');
    const codes = new Set();
    if (isTop) {
      const prefix = `${hit.code}.`;
      for (const s of SPECIALTIES) {
        if (s.code.startsWith(prefix) || (s.alsoUnder || []).includes(hit.code)) codes.add(s.code);
      }
    } else {
      codes.add(hit.code);
    }
    if (isTop) codes.add(topCode);
    const canonicalCodes = new Set(codes);
    const storedCodes = [...new Set([
      ...canonicalCodes,
      ...Object.entries(SPEC_CODE_ALIASES)
        .filter(([, canonical]) => canonicalCodes.has(canonical))
        .map(([legacy]) => legacy),
    ])];
    const codeFilter = {
      $or: [
        { specialtyCode: { $in: storedCodes } },
        { subSpecialtyCodes: { $in: storedCodes } },
      ],
    };
    const filters = [codeFilter];
    if (city) {
      const cityRegex = new RegExp(`^${escapeRegex(String(city))}`, 'i');
      filters.push({ $or: [{ city: cityRegex }, { location: cityRegex }] });
    }
    if (facilityId) filters.push({ $or: [{ facilityId }, { hospitalId: facilityId }] });
    if (approvedOnly === 'true') filters.push({ approved: true });
    const query = filters.length === 1 ? filters[0] : { $and: filters };

    const [doctors, hospitalIds, clinicIds] = await Promise.all([
      Doctor.countDocuments(query),
      Doctor.distinct('hospitalId', query),
      Doctor.distinct('facilityId', query),
    ]);
    const facilityCount = new Set([...hospitalIds, ...clinicIds].filter(Boolean).map(String)).size;
    res.setHeader('Cache-Control', 'public, max-age=60');
    res.json({
      code: topCode,
      requestedCode: hit.code,
      doctors,
      hospitals: facilityCount,
      facilities: facilityCount,
    });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

// authz: role / catalog_manager - Idempotently seed/sync full CATEGORY_TREE into MongoDB
router.post('/seed', protect, requireRole(['superadmin', 'catalog_manager']), async (req, res) => {
  try {
    const itemByCode = new Map(CATEGORY_TREE.map((item) => [item.code, item]));
    const depthByCode = new Map();
    const getDepth = (item, visiting = new Set()) => {
      if (depthByCode.has(item.code)) return depthByCode.get(item.code);
      if (!item.parent) {
        depthByCode.set(item.code, 0);
        return 0;
      }
      if (visiting.has(item.code)) throw new Error(`Category parent cycle at ${item.code}`);
      const parent = itemByCode.get(item.parent);
      if (!parent) throw new Error(`Missing category parent ${item.parent} for ${item.code}`);
      visiting.add(item.code);
      const depth = getDepth(parent, visiting) + 1;
      visiting.delete(item.code);
      depthByCode.set(item.code, depth);
      return depth;
    };
    const orderedItems = [...CATEGORY_TREE].sort((a, b) => getDepth(a) - getDepth(b));
    const seededByCode = new Map();
    let roots = 0;
    let leaves = 0;

    for (const item of orderedItems) {
      const parentInfo = item.parent ? seededByCode.get(item.parent) : null;
      if (item.parent && !parentInfo) {
        throw new Error(`Category parent was not seeded before child ${item.code}`);
      }
      const level = depthByCode.get(item.code);
      const doc = await Category.findOneAndUpdate(
        { code: item.code },
        {
          $set: {
            name: item.name,
            nameHi: item.nameHi || '',
            type: item.type,
            aliases: item.aliases || [],
            alsoUnder: item.alsoUnder || [],
            meta: item.meta || {},
            icon: item.icon || '',
            parent: parentInfo?._id || null,
            tier: item.tier || 'T1',
            regulatedBy: item.regulatedBy || [],
            kind: item.kind || '',
            isSensitive: !!item.isSensitive,
            adClaimsRestricted: !!item.adClaimsRestricted,
            path: parentInfo ? `${parentInfo.path}/${item.code}` : item.code,
            level,
            isActive: true,
          },
        },
        { upsert: true, new: true, setDefaultsOnInsert: true }
      );
      seededByCode.set(item.code, { _id: doc._id, path: doc.path });
      if (level === 0) roots++;
      else leaves++;
    }

    await invalidatePublicCache();
    res.json({
      message: 'Category catalogue tree synchronized successfully',
      totalSeeded: CATEGORY_TREE.length,
      roots,
      leaves,
    });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// 8.md 4: the whole category tree (list, create, edit, delete, merge) is the
// catalog_manager's console - it is configuration of what the marketplace can
// even sell, so it is platform-level and NEVER tenant-scoped. The public read
// above stays anonymous; everything below is superadmin or catalog_manager.
router.get('/', protect, requireRole(['superadmin', 'catalog_manager']), async (req, res) => {
  try {
    const { type, search } = req.query;
    const filter = {};
    if (type) filter.type = type;
    if (search) {
      const term = safeSearchRegex(search);
      if (term) filter.$or = [{ name: term }, { aliases: term }, { code: term }];
    }
    const categories = await Category.find(filter).sort({ type: 1, displayOrder: 1 });
    res.json({ categories });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.post('/', protect, requireRole(['superadmin', 'catalog_manager']), validate(createCategorySchema), async (req, res) => {
  try {
    const body = { ...req.body };
    if (!body.code) body.code = deriveCategoryCode(body.type, body.name);

    if (body.parent) {
      const lineage = await resolveLineage(body.parent);
      if (!lineage) return res.status(400).json({ message: 'Parent category not found' });
      body.path = `${lineage.path}/${body.code}`;
      body.level = lineage.level;
    } else {
      body.path = body.code;
      body.level = 0;
    }

    const category = await Category.create(body);
    await invalidatePublicCache();
    res.status(201).json(category);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.put('/:id', protect, requireRole(['superadmin', 'catalog_manager']), validate(updateCategorySchema), async (req, res) => {
  try {
    const { pickBody } = await import('../utils/pick.js');
    const before = await Category.findById(req.params.id).select('code name type path level').lean();
    if (!before) return res.status(404).json({ message: 'Category not found' });

    const set = pickBody(req.body, WRITABLE_FIELDS);
    const parentChanged = set.parent !== undefined;
    const oldPath = before.path;

    if (parentChanged) {
      if (String(set.parent || '') === String(req.params.id)) {
        return res.status(400).json({ message: 'A category cannot be its own parent' });
      }
      const ownCode = before.code || deriveCategoryCode(before.type, before.name);
      if (set.parent) {
        const lineage = await resolveLineage(set.parent);
        if (!lineage) return res.status(400).json({ message: 'Parent category not found' });
        set.path = `${lineage.path}/${ownCode}`;
        set.level = lineage.level;
      } else {
        set.path = ownCode;
        set.level = 0;
      }
      if (!before.code) set.code = ownCode;
    }

    const category = await Category.findByIdAndUpdate(req.params.id, set,
      { new: true, runValidators: true, overwriteImmutable: true });
    if (!category) return res.status(404).json({ message: 'Category not found' });

    if (parentChanged && oldPath && category.path && category.path !== oldPath) {
      const delta = (category.level ?? 0) - (before.level ?? 0);
      const descendants = await Category.find({ path: new RegExp(`^${escapeRegex(oldPath)}/`) })
        .select('path level').lean();
      if (descendants.length) {
        await Category.bulkWrite(descendants.map((doc) => ({
          updateOne: {
            filter: { _id: doc._id },
            update: { $set: { path: `${category.path}${doc.path.slice(oldPath.length)}`, level: doc.level + delta } },
          },
        })));
      }
    }

    await invalidatePublicCache();
    res.json(category);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.delete('/:id', protect, requireRole(['superadmin', 'catalog_manager']), async (req, res) => {
  try {
    const children = await Category.countDocuments({ parent: req.params.id });
    if (children > 0) {
      return res.status(400).json({ message: 'Cannot delete: move or merge its subcategories first' });
    }
    await Category.findByIdAndDelete(req.params.id);
    await invalidatePublicCache();
    res.json({ message: 'Deleted' });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.post('/merge', protect, requireRole(['superadmin', 'catalog_manager']), validate(mergeCategorySchema), async (req, res) => {
  try {
    const { sourceIds, targetId } = req.body;
    await Category.updateMany({ _id: { $in: sourceIds, $ne: targetId } }, { parent: targetId, isActive: false });
    await invalidatePublicCache();
    res.json({ message: 'Merged successfully' });
  } catch (err) { res.status(400).json({ message: err.message }); }
});

export default router;

import crypto from 'crypto';
import express from 'express';
import PDFDocument from 'pdfkit';
import QRCode from 'qrcode';
import { z } from 'zod';
import Record from '../models/Record.js';
import User from '../models/User.js';
import SignatureEvent from '../models/SignatureEvent.js';
import { sealDoc } from '../lib/docSeal.js';
import { protect, authorize } from '../middleware/auth.js';
import { validate, objectIdSchema } from '../utils/validate.js';
import { auditLog } from '../middleware/audit.js';
import { paginatedResults } from '../utils/pagination.js';
import { getISTDateString } from '../utils/dateUtils.js';

const router = express.Router();

const CERTIFICATE_TYPES = ['sick_leave', 'fitness', 'referral', 'immunization', 'other'];

const CERTIFICATE_TYPE_LABELS = {
  sick_leave: 'Sick Leave Certificate',
  fitness: 'Fitness Certificate',
  referral: 'Referral Letter',
  immunization: 'Immunization Certificate',
  other: 'Medical Certificate',
};

const createCertificateSchema = z.object({
  patientId: objectIdSchema,
  type: z.enum(CERTIFICATE_TYPES).optional().default('other'),
  title: z.string().trim().min(2, 'Title is required').max(200),
  diagnosis: z.string().trim().max(2000).optional().default(''),
  daysRest: z.number().int().positive().max(365).optional(),
  validFrom: z.string().trim().max(40).optional().default(''),
  validTo: z.string().trim().max(40).optional().default(''),
  notes: z.string().trim().max(4000).optional().default(''),
  encounterId: objectIdSchema.optional(),
});

router.use(protect);

router.post('/', authorize('records:write', 'prescriptions:write'), validate(createCertificateSchema), async (req, res) => {
  try {
    const { patientId, type, title, diagnosis, daysRest, validFrom, validTo, notes, encounterId } = req.body;
    const patientUser = await User.findById(patientId).select('name role');
    if (!patientUser || patientUser.role !== 'patient') {
      return res.status(404).json({ message: 'Patient not found' });
    }
    const record = await Record.create({
      patient: patientUser.name,
      patientId,
      doctor: req.user.name || '',
      doctorId: req.user.doctorProfileId || null,
      hospitalId: req.user.hospitalId || undefined,
      encounterId: encounterId || null,
      date: getISTDateString(),
      type: 'medical_certificate',
      diagnosis: diagnosis || '',
      notes: notes || '',
      data: {
        certificateType: type,
        title,
        daysRest: daysRest ?? null,
        validFrom: validFrom || '',
        validTo: validTo || '',
        verificationCode: crypto.randomBytes(4).toString('hex').toUpperCase(),
        createdBy: String(req.user._id),
      },
    });
    const verifyUrl = `/verify/doc/certificate/${record._id}`;
    record.data.verifyUrl = verifyUrl;
    await record.save();
    await auditLog('create_medical_certificate', req.user._id, {
      recordId: record._id, certificateType: type, patientId, ip: req.ip, userAgent: req.get('user-agent'),
    });
    await record.populate('doctorId', 'name specialization');
    const certJson = record.toObject ? record.toObject() : { ...record };
    certJson.verifyUrl = verifyUrl;
    res.status(201).json({ certificate: certJson, verifyUrl });
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

router.get('/', authorize('records:read', 'records:read:own'), async (req, res) => {
  try {
    const { page, limit, patientId } = req.query;
    const filter = { type: 'medical_certificate', deletedAt: { $exists: false } };
    let scoped = false;

    if (req.user.role === 'patient') {
      filter.patientId = req.user._id;
      scoped = true;
    } else if (['doctor', 'counsellor', 'psychiatrist', 'clinic_doctor'].includes(req.user.role)) {
      filter.doctorId = req.user.doctorProfileId;
      if (req.user.hospitalId) filter.hospitalId = req.user.hospitalId;
      scoped = true;
    } else if (req.user.role === 'hospital_admin' && req.user.hospitalId) {
      filter.hospitalId = req.user.hospitalId;
      scoped = true;
    }

    if (!scoped) {
      return res.json({ data: [], total: 0, page: 1, limit: parseInt(limit, 10) || 50, totalPages: 0 });
    }

    if (patientId) {
      if (req.user.role === 'patient' && String(patientId) !== String(req.user._id)) {
        return res.json({ data: [], total: 0, page: 1, limit: parseInt(limit, 10) || 50, totalPages: 0 });
      }
      filter.patientId = patientId;
    }

    const result = await paginatedResults(Record, filter, {
      page, limit,
      sort: { createdAt: -1 },
      populate: [
        { path: 'patientId', select: 'name email' },
        { path: 'doctorId', select: 'name specialization' },
      ],
    });
    res.json(result);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

const canAccessCertificateDoc = (req, record) => {
  if (!record) return false;
  if (req.user.role === 'patient') {
    return Boolean(record.patientId && String(record.patientId._id || record.patientId) === String(req.user._id));
  }
  if (['doctor', 'clinic_doctor', 'counsellor', 'psychiatrist'].includes(req.user.role)) {
    const own = (req.user.doctorProfileId || req.user._id)?.toString();
    if (record.doctorId && String(record.doctorId._id || record.doctorId) === own) return true;
  }
  if (req.user.hospitalId) {
    return Boolean(record.hospitalId && String(record.hospitalId) === String(req.user.hospitalId));
  }
  return false;
};

const formatDate = (value) => {
  if (!value) return '-';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Asia/Kolkata' });
};

const drawMedicalCertificatePDF = async (data) => {
  let qrBuffer = null;
  if (data.verifyUrl) {
    try {
      qrBuffer = await QRCode.toBuffer(data.verifyUrl, { width: 56, margin: 1, type: 'png' });
    } catch { /* QR code generation is non-blocking */ }
  }
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: 'A4', margin: 48 });
    const chunks = [];
    doc.on('data', (chunk) => chunks.push(chunk));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);
    try {
      const { left, right } = doc.page.margins;
      const width = doc.page.width - left - right;

      doc.roundedRect(left, 40, width, 66, 8).fill('#0f766e');
      doc.circle(left + 32, 73, 17).fill('#ffffff');
      doc.strokeColor('#0f766e').lineWidth(2.2)
        .moveTo(left + 20, 73).lineTo(left + 27, 73).lineTo(left + 31, 63)
        .lineTo(left + 38, 83).lineTo(left + 42, 73).lineTo(left + 49, 73).stroke();
      doc.fillColor('#ffffff').font('Helvetica-Bold').fontSize(16).text(data.hospitalName, left + 58, 54);
      doc.font('Helvetica').fontSize(8.5).text('Official Medical Certificate — FindMedi', left + 58, 78);
      doc.font('Helvetica-Bold').fontSize(13).fillColor('#ffffff').text(data.title, left, 52, { width: width - 24, align: 'right' });
      doc.font('Helvetica').fontSize(8.5).text(`Certificate No: ${data.certificateNo}`, left, 74, { width: width - 24, align: 'right' });
      doc.text(`Issued: ${data.issueDate}`, left, 88, { width: width - 24, align: 'right' });

      doc.y = 128;
      doc.fillColor('#111827').font('Helvetica-Bold').fontSize(15).text(data.title, { align: 'center' });
      doc.moveDown(0.3);
      doc.font('Helvetica').fontSize(10).fillColor('#374151')
        .text('This is to certify the medical particulars of the patient named below.', { align: 'center' });
      doc.moveDown(1.2);

      let y = doc.y;
      const sectionTitle = (title) => {
        doc.fillColor('#134e4a').font('Helvetica-Bold').fontSize(11).text(title.toUpperCase(), left, y);
        doc.strokeColor('#d1d5db').lineWidth(0.6).moveTo(left, y + 16).lineTo(left + width, y + 16).stroke();
        y += 26;
      };
      const row = (label, value) => {
        doc.fillColor('#6b7280').font('Helvetica-Bold').fontSize(9.5).text(`${label}:`, left, y, { width: 140 });
        doc.fillColor('#111827').font('Helvetica').fontSize(10).text(value || '-', left + 145, y, { width: width - 145, lineGap: 2 });
        y = Math.max(doc.y, y + 15) + 5;
        doc.y = y;
      };

      sectionTitle('Patient');
      row('Name', data.patientName);
      row('Patient ID', data.patientUhid);
      row('Certificate Type', data.certificateTypeLabel);

      sectionTitle('Certificate Details');
      row('Diagnosis', data.diagnosis);
      if (data.daysRest) row('Rest Period', `${data.daysRest} day(s)`);
      if (data.validFrom) row('Valid From', data.validFrom);
      if (data.validTo) row('Valid Until', data.validTo);
      row('Additional Notes', data.notes);

      sectionTitle('Certification');
      doc.fillColor('#111827').font('Helvetica').fontSize(10);
      doc.text(
        'I hereby certify that the above-named patient was examined / attended at this clinic and the particulars '
        + 'recorded above are true and correct to the best of my knowledge and belief.',
        left, y, { width, lineGap: 3 }
      );
      y = doc.y + 44;

      doc.strokeColor('#9ca3af').lineWidth(0.7).moveTo(left + width - 220, y).lineTo(left + width, y).stroke();
      doc.fillColor('#6b7280').font('Helvetica').fontSize(8.5)
        .text(`Dr. ${data.doctorName}${data.doctorSpecialization ? ` — ${data.doctorSpecialization}` : ''}`, left + width - 220, y + 6, { width: 220, align: 'center' });
      doc.text('Issuing Clinician / Signature', left + width - 220, y + 20, { width: 220, align: 'center' });

      const footY = doc.page.height - 72;
      doc.strokeColor('#d1d5db').lineWidth(0.5).moveTo(left, footY).lineTo(left + width, footY).stroke();
      if (qrBuffer) {
        doc.image(qrBuffer, left + width - 48, footY + 4, { width: 44, height: 44 });
      }
      doc.fillColor('#6b7280').font('Helvetica').fontSize(8);
      const textWidth = qrBuffer ? width - 56 : width * 0.75;
      doc.text(`Record ID: ${data.recordId}   |   Verification Code: ${data.verificationCode}`, left, footY + 10, { width: textWidth });
      doc.text('Computer-generated certificate. Scan QR or verify online at FindMedi to validate authenticity.', left, footY + 24, { width: textWidth });
      if (!qrBuffer) {
        doc.text('Page 1 of 1', left, footY + 10, { width, align: 'right' });
      }

      doc.end();
    } catch (err) {
      reject(err);
    }
  });
};

router.get('/:id/pdf', authorize('records:read', 'records:read:own'), async (req, res) => {
  try {
    const record = await Record.findById(req.params.id)
      .populate('patientId', 'name uhid email')
      .populate('doctorId', 'name specialization');
    if (!record || record.type !== 'medical_certificate') {
      return res.status(404).json({ message: 'Medical certificate not found' });
    }
    if (!canAccessCertificateDoc(req, record)) {
      await auditLog('access_denied_medical_certificate', req.user._id, {
        resourceType: 'Record', resourceId: record._id, ip: req.ip, userAgent: req.get('user-agent'),
      });
      return res.status(403).json({ message: 'Not authorized' });
    }

    let hospitalName = req.user.hospitalName || '';
    if (!hospitalName && record.hospitalId) {
      try {
        const { default: Hospital } = await import('../models/Hospital.js');
        hospitalName = (await Hospital.findById(record.hospitalId).select('name'))?.name || '';
      } catch { /* cosmetic — PDF still prints with fallback */ }
    }

    const certType = record.data?.certificateType || 'other';
    const verifyBase = `${req.protocol}://${req.get('host') || 'findmedi.local'}`;
    const verifyUrl = `${verifyBase}/verify/doc/certificate/${record._id}`;
    const pdfBuffer = await drawMedicalCertificatePDF({
      hospitalName: hospitalName || 'FindMedi Clinic',
      title: record.data?.title || CERTIFICATE_TYPE_LABELS[certType] || 'Medical Certificate',
      certificateNo: String(record._id).slice(-8).toUpperCase(),
      issueDate: formatDate(record.createdAt || new Date()),
      patientName: record.patientId?.name || record.patient || 'Patient',
      patientUhid: record.patientId?.uhid || String(record.patientId?._id || record.patientId || '-'),
      certificateTypeLabel: CERTIFICATE_TYPE_LABELS[certType] || 'Medical Certificate',
      diagnosis: record.diagnosis,
      daysRest: record.data?.daysRest,
      validFrom: record.data?.validFrom ? formatDate(record.data.validFrom) : '',
      validTo: record.data?.validTo ? formatDate(record.data.validTo) : '',
      notes: record.notes,
      doctorName: record.doctorId?.name || record.doctor || 'Authorised Signatory',
      doctorSpecialization: record.doctorId?.specialization,
      recordId: String(record._id),
      verificationCode: record.data?.verificationCode || '-',
      verifyUrl,
    });

    const seal = sealDoc('certificate', String(record._id), pdfBuffer);
    try {
      await SignatureEvent.create({
        hospitalId: record.hospitalId || req.user.hospitalId,
        docRef: { kind: 'certificate', id: record._id },
        level: 'L2',
        signerRole: ['doctor', 'clinic_doctor'].includes(req.user.role) ? 'doctor' : 'staff',
        signerId: req.user._id,
        signerName: req.user.name || record.doctor || 'Authorised Signatory',
        intent: 'Seal medical certificate',
        digest: seal.digest,
        signature: seal.signature,
        nonceHash: seal.nonceHash,
        ip: req.ip,
        device: req.get('user-agent') || '',
      });
    } catch {
      // Signature recording is non-blocking for PDF download
    }

    await auditLog('download_medical_certificate', req.user._id, {
      resourceType: 'Record', resourceId: record._id, digest: seal.digest, nonce: seal.nonce, ip: req.ip, userAgent: req.get('user-agent'),
    });

    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('X-Doc-Seal-Nonce', seal.nonce);
    res.setHeader('X-Doc-Seal-Signature', seal.signature);
    res.setHeader('X-Doc-Seal-Digest', seal.digest);
    res.setHeader('X-Doc-Verify-Url', `/verify/doc/certificate/${record._id}?nonce=${seal.nonce}`);
    res.setHeader('Content-Disposition', `attachment; filename="medical-certificate-${record._id}.pdf"`);
    res.send(pdfBuffer);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

export default router;

import express from 'express';
import mongoose from 'mongoose';
import { requireConversationMember, assertRoomAccess } from '../middleware/chatMembership.js';
import { protect, authorize } from '../middleware/auth.js';
import { chatUploadLimiter } from '../middleware/rateLimit.js';
import ChatConversation from '../models/ChatConversation.js';
import ChatMessage from '../models/ChatMessage.js';
import AssistantBooking from '../models/AssistantBooking.js';
import LawyerBooking from '../models/LawyerBooking.js';
import ChatPrivacy from '../models/ChatPrivacy.js';
import ChatReport from '../models/ChatReport.js';
import PushSubscription from '../models/PushSubscription.js';
import User from '../models/User.js';
import Doctor from '../models/Doctor.js';
import Appointment from '../models/Appointment.js';
import bcrypt from 'bcryptjs';
import { verifyPin } from '../services/pinLockout.js';
import { auditLog } from '../middleware/audit.js';
import { emitChatEvent, emitChatNotification } from '../services/socketService.js';
// CHAT-M-02: all upload policy (MIME allowlist, magic bytes, ClamAV scan,
// quarantine, size cap, attachment-array validation) lives in the service.
import { storeChatUpload, validateChatAttachments } from '../services/chatUploadService.js';
// CHAT-M-04: offline delivery — env-gated web push for recipients with no
// live socket presence.
import { sendChatPush, isPushConfigured, getVapidPublicKey } from '../services/pushSender.js';

const router = express.Router();

// Booking chat threads are bound to a booking only after the same server-side
// party check used for booking socket rooms. Client-provided participants are
// never accepted. The unique context index makes concurrent provisioning safe.
router.get('/bookings/:kind/:bookingId/conversation', protect, authorize('chat:read:own'), async (req, res) => {
  try {
    const { kind, bookingId } = req.params;
    if (!['assistant', 'lawyer'].includes(kind) || !mongoose.Types.ObjectId.isValid(bookingId)) {
      return res.status(404).json({ message: 'Booking chat not found' });
    }
    const contextType = `${kind}-booking`;
    const verdict = await assertRoomAccess(req.user.id, req.user.role, contextType, bookingId);
    if (!verdict.ok) return res.status(404).json({ message: 'Booking chat not found' });
    const Model = kind === 'assistant' ? AssistantBooking : LawyerBooking;
    const booking = await Model.findById(bookingId).select('patientId userId assistantId lawyerId').lean();
    const parties = [...new Set([booking?.patientId, booking?.userId, booking?.assistantId, booking?.lawyerId].filter(Boolean).map(String))];
    if (parties.length !== 2 || !parties.includes(req.user.id)) {
      return res.status(404).json({ message: 'Booking chat not found' });
    }
    const filter = { contextType, contextId: booking._id };
    let conversation = await ChatConversation.findOne(filter);
    if (!conversation) {
      try {
        conversation = await ChatConversation.create({ ...filter, participants: parties });
      } catch (err) {
        if (err?.code !== 11000) throw err;
        conversation = await ChatConversation.findOne(filter);
      }
    }
    if (!conversation || parties.some((id) => !conversation.participants.some((p) => String(p) === id))) {
      return res.status(409).json({ message: 'Booking chat participants changed; contact support' });
    }
    const storedContextParties = (conversation.contextParticipants || []).map(String);
    if (storedContextParties.length && (storedContextParties.length !== parties.length || parties.some((id) => !storedContextParties.includes(id)))) {
      return res.status(409).json({ message: 'Booking chat assignment changed; contact support' });
    }
    if (!storedContextParties.length) {
      conversation.contextParticipants = parties;
      await conversation.save();
    }
    res.json({ conversationId: String(conversation._id) });
  } catch (err) {
    res.status(500).json({ message: 'Unable to open booking chat' });
  }
});

// ─── Helpers ─────────────────────────────────────────────────────────────────
const uid = (id) => String(id);

async function getConversationForUser(conversationId, userId) {
  const conv = await ChatConversation.findById(conversationId);
  if (!conv) return null;
  if (!conv.participants.some((p) => uid(p) === uid(userId))) return null;
  return conv;
}

function otherParticipantId(conv, userId) {
  const other = conv.participants.find((p) => uid(p) !== uid(userId));
  return other ? uid(other) : null;
}

function otherParticipant(conv, userId) {
  return conv.participants.find((p) => uid(p) !== uid(userId)) || null;
}

function getUnreadCount(conv, userId) {
  return conv.unreadCounts?.find((u) => uid(u.userId) === uid(userId))?.count || 0;
}

async function getPrivacy(userId) {
  let privacy = await ChatPrivacy.findOne({ userId });
  if (!privacy) privacy = await ChatPrivacy.create({ userId });
  return privacy;
}

// ─── Doctor ↔ Patient only chat ─────────────────────────────────────────────
const DOCTOR_ROLES = ['doctor', 'clinic_doctor'];
const isDoctorRole = (role) => DOCTOR_ROLES.includes(role);
/** True jab pair ek doctor aur ek patient ho. */
const isDoctorPatientPair = (roleA, roleB) =>
  (isDoctorRole(roleA) && roleB === 'patient') || (roleA === 'patient' && isDoctorRole(roleB));

/** Any mongoose ref (ObjectId | populated doc | string) → string id */
function plainId(value) {
  if (!value) return null;
  if (typeof value === 'object' && value._id !== undefined) return String(value._id);
  return String(value);
}

/** Hidden messages: delete-for-me + "clear chat" se pehle ke messages */
function messageVisibleToUser(message, conv, userId) {
  const id = uid(userId);
  if ((message.deletedFor || []).some((d) => uid(d) === id)) return false;
  const cleared = (conv.clearedFor || []).find((c) => uid(c.userId) === id);
  if (cleared?.at && new Date(message.createdAt) <= new Date(cleared.at)) return false;
  return true;
}

function senderSnapshot(sender) {
  if (!sender) return null;
  if (typeof sender === 'object' && sender.name !== undefined) {
    return { _id: plainId(sender), name: sender.name, avatar: sender.avatar || '', role: sender.role };
  }
  return { _id: plainId(sender), name: '', avatar: '', role: '' };
}

/**
 * Client ko bhejne layak message shape. Deleted/expired content mask karta hai,
 * reactions ko group karta hai aur receipts sirf sender ko dikhata hai.
 */
function sanitizeMessage(message, userId) {
  const m = message.toObject ? message.toObject() : { ...message };
  const id = uid(userId);
  const deleted = Boolean(m.deletedForEveryone);
  const mine = plainId(m.sender) === id;

  const byEmoji = new Map();
  (m.reactions || []).forEach((r) => {
    const key = r.emoji || '❤️';
    if (!byEmoji.has(key)) byEmoji.set(key, { emoji: key, count: 0, users: [], mine: false });
    const entry = byEmoji.get(key);
    entry.count += 1;
    entry.users.push(plainId(r.userId));
    if (plainId(r.userId) === id) entry.mine = true;
  });
  const reactions = Array.from(byEmoji.values());

  const deliveredTo = (m.deliveredTo || []).map((d) => ({ userId: plainId(d.userId), at: d.at }));
  const readBy = (m.readBy || []).map((d) => ({ userId: plainId(d.userId), at: d.at }));

  let replyTo = null;
  if (m.replyTo && typeof m.replyTo === 'object') {
    replyTo = {
      _id: plainId(m.replyTo),
      content: m.replyTo.deletedForEveryone ? '' : (m.replyTo.content || ''),
      type: m.replyTo.type || 'text',
      sender: plainId(m.replyTo.sender),
      deleted: Boolean(m.replyTo.deletedForEveryone),
    };
  } else if (m.replyTo) {
    replyTo = { _id: plainId(m.replyTo), content: '', type: 'text', sender: null, deleted: false };
  }

  return {
    _id: plainId(m._id),
    conversationId: plainId(m.conversationId),
    sender: senderSnapshot(m.sender),
    type: m.type,
    content: deleted ? '' : (m.content || ''),
    attachments: deleted ? [] : (m.attachments || []),
    replyTo,
    forwarded: Boolean(m.forwarded),
    edited: Boolean(m.edited),
    deletedForEveryone: deleted,
    reactions,
    myReaction: reactions.find((r) => r.mine)?.emoji || null,
    starred: (m.starredBy || []).some((s) => plainId(s) === id),
    mine,
    deliveredCount: deliveredTo.length,
    readCount: readBy.length,
    deliveredTo: mine ? deliveredTo : [],
    readBy: mine ? readBy : [],
    createdAt: m.createdAt,
    updatedAt: m.updatedAt,
    expiresAt: m.expiresAt || null,
  };
}

import { escapeRegex, capSearch } from '../utils/escapeRegex.js';

/** Conversation ke saare participants ke privacy flags respect karte hue response banata hai */
async function decorateConversation(conv, userId) {
  const id = uid(userId);
  const other = (conv.participants || []).find((p) => uid(p._id || p) !== id) || null;
  if (other) {
    const otherPrivacy = await getPrivacy(other._id || other);
    if (otherPrivacy.online !== 'everyone') other.isOnline = false;
    if (otherPrivacy.lastSeen !== 'everyone') delete other.lastActive;
    if (otherPrivacy.profilePhoto !== 'everyone') other.avatar = '';
    if (otherPrivacy.about !== 'everyone') other.about = '';
  }
  return conv;
}

// ── Doctor ↔ Patient contact resolution (appointment-based) ────────────────
/**
 * Ek user ke "linked" counterpart users.
 * patient → jitne doctors ke saath appointment hai
 * doctor  → jitne patients ke saath appointment hai
 */
async function getLinkedContacts(user) {
  const userId = uid(user.id || user._id);
  const role = user.role;

  if (role === 'patient') {
    const appts = await Appointment.find({
      $or: [{ patientId: user._id || userId }, { patientId: { $exists: false }, patient: user.name }],
    }).select('doctorId doctor date status appointmentMode').sort({ date: -1 }).limit(500).lean();

    const byDoctor = new Map();
    appts.forEach((a) => {
      if (!a.doctorId) return;
      const key = String(a.doctorId);
      const entry = byDoctor.get(key) || { name: a.doctor, total: 0, upcoming: 0, lastAt: a.date, modes: new Set() };
      entry.total += 1;
      if (['Pending', 'Confirmed', 'In Queue', 'Serving'].includes(a.status)) entry.upcoming += 1;
      if (a.appointmentMode) entry.modes.add(a.appointmentMode);
      if (a.date && a.date > entry.lastAt) entry.lastAt = a.date;
      byDoctor.set(key, entry);
    });

    if (!byDoctor.size) return [];
    const doctors = await Doctor.find({ _id: { $in: [...byDoctor.keys()] } })
      .populate('user_id', 'name avatar role isOnline lastActive email phone')
      .lean();

    return doctors.map((d) => {
      const meta = byDoctor.get(String(d._id)) || {};
      const account = d.user_id && typeof d.user_id === 'object'
        ? d.user_id
        : { _id: d.user_id || d._id, name: d.name, avatar: d.profile_photo || '', role: 'doctor', email: d.email, phone: d.phone };
      return {
        user: account,
        doctorProfileId: String(d._id),
        doctorName: d.name,
        specialization: d.specialization,
        via: 'appointment',
        appointmentCount: meta.total || 0,
        upcomingCount: meta.upcoming || 0,
        modes: [...(meta.modes || [])],
      };
    }).filter((c) => c.user && c.user._id);
  }

  if (isDoctorRole(role)) {
    const doctorIds = [];
    if (user.doctorProfileId) doctorIds.push(user.doctorProfileId);
    const profile = await Doctor.findOne({ $or: [{ user_id: userId }, { email: user.email }] }).select('_id').lean();
    if (profile?._id) doctorIds.push(profile._id);
    if (!doctorIds.length) return [];

    const appts = await Appointment.find({ doctorId: { $in: doctorIds } })
      .select('patientId patient date status appointmentMode')
      .sort({ date: -1 }).limit(1000).lean();

    const byPatient = new Map();
    appts.forEach((a) => {
      if (!a.patientId) return;
      const key = String(a.patientId);
      const entry = byPatient.get(key) || { total: 0, upcoming: 0, lastAt: a.date, modes: new Set() };
      entry.total += 1;
      if (['Pending', 'Confirmed', 'In Queue', 'Serving'].includes(a.status)) entry.upcoming += 1;
      if (a.appointmentMode) entry.modes.add(a.appointmentMode);
      if (a.date && a.date > entry.lastAt) entry.lastAt = a.date;
      byPatient.set(key, entry);
    });

    if (!byPatient.size) return [];
    const patients = await User.find({ _id: { $in: [...byPatient.keys()] } })
      .select('name avatar role isOnline lastActive uhid phone email gender').lean();

    return patients.map((p) => {
      const meta = byPatient.get(String(p._id)) || {};
      return {
        user: p,
        uhid: p.uhid,
        via: 'appointment',
        appointmentCount: meta.total || 0,
        upcomingCount: meta.upcoming || 0,
        modes: [...(meta.modes || [])],
      };
    });
  }

  return [];
}

/** True jab in dono users ka koi appointment-linked rishta ho (kisi bhi direction me). */
async function hasAppointmentLink(userA, userB) {
  const doctorUser = isDoctorRole(userA.role) ? userA : (isDoctorRole(userB.role) ? userB : null);
  const patientUser = userA.role === 'patient' ? userA : (userB.role === 'patient' ? userB : null);
  if (!doctorUser || !patientUser) return false;

  const doctor = await Doctor.findOne({ user_id: doctorUser._id || doctorUser.id }).select('_id').lean();
  if (!doctor) return false;
  return Boolean(await Appointment.exists({
    doctorId: doctor._id,
    $or: [
      { patientId: patientUser._id || patientUser.id },
      { patientId: { $exists: false }, patient: patientUser.name },
    ],
  }));
}

// ─── Web Push subscriptions (CHAT-M-04) ─────────────────────────────────────
// Offline fallback: sockets only reach an open tab. The VAPID key pair is
// generated locally (`npx web-push generate-vapid-keys`) — no Firebase/APNs
// account needed (that stays NOTIF-M-01). Unconfigured servers advertise
// `configured: false` and the sender skips.

// authz: self
router.get('/push-config', protect, authorize('chat:read:own'), (req, res) => {
  res.json({ configured: isPushConfigured(), publicKey: getVapidPublicKey() });
});

// authz: self
router.post('/push-subscriptions', protect, authorize('chat:write:own'), async (req, res) => {
  try {
    const { endpoint, keys, userAgent } = req.body || {};
    if (typeof endpoint !== 'string' || !endpoint || endpoint.length > 2048) {
      return res.status(400).json({ message: 'endpoint required' });
    }
    let endpointUrl;
    try {
      endpointUrl = new URL(endpoint);
    } catch {
      return res.status(400).json({ message: 'endpoint must be a valid URL' });
    }
    if (endpointUrl.protocol !== 'https:' && endpointUrl.protocol !== 'http:') {
      return res.status(400).json({ message: 'endpoint must be an http(s) URL' });
    }
    const p256dh = keys?.p256dh;
    const auth = keys?.auth;
    if (typeof p256dh !== 'string' || !p256dh || p256dh.length > 512) {
      return res.status(400).json({ message: 'keys.p256dh required' });
    }
    if (typeof auth !== 'string' || !auth || auth.length > 512) {
      return res.status(400).json({ message: 'keys.auth required' });
    }
    const userId = String(req.user.id);
    const sub = await PushSubscription.findOneAndUpdate(
      { userId, endpoint },
      {
        $set: {
          keys: { p256dh, auth },
          userAgent: typeof userAgent === 'string' ? userAgent.slice(0, 300) : '',
          lastSeenAt: new Date(),
        },
      },
      { new: true, upsert: true, setDefaultsOnInsert: true },
    );
    res.status(201).json({ id: String(sub._id), endpoint });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// authz: self
router.delete('/push-subscriptions/:id', protect, authorize('chat:write:own'), async (req, res) => {
  try {
    const { id } = req.params;
    if (!/^[0-9a-f]{24}$/i.test(id)) return res.status(404).json({ message: 'Subscription not found' });
    const result = await PushSubscription.deleteOne({ _id: id, userId: String(req.user.id) });
    if (!result.deletedCount) return res.status(404).json({ message: 'Subscription not found' });
    res.status(204).end();
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// ─── File upload (base64 dataURL → /uploads/chat) ───────────────────────────
// CHAT-M-02: this handler is now a thin wrapper — MIME allow-list, magic-byte
// content checks for ALL types (previously images only), the ClamAV malware
// scan, quarantine-on-detection and the 25MB cap all live in
// chatUploadService.storeChatUpload(). CHAT-B-06 still holds: the stored
// extension is derived from the server-side MIME map, never from the client
// filename.
router.post('/upload', protect, authorize('chat:write:own'), chatUploadLimiter, async (req, res) => {
  try {
    const { dataUrl, name = 'file' } = req.body || {};
    if (!dataUrl || typeof dataUrl !== 'string' || !dataUrl.startsWith('data:')) {
      return res.status(400).json({ message: 'dataUrl required' });
    }
    const match = dataUrl.match(/^data:([^;,]+)?(;base64)?,(.*)$/);
    if (!match) return res.status(400).json({ message: 'Invalid dataUrl' });
    const mimeType = match[1] || 'application/octet-stream';
    const isBase64 = match[2] === ';base64';
    const buffer = Buffer.from(match[3], isBase64 ? 'base64' : 'utf8');
    const result = await storeChatUpload({ buffer, mimeType, name, userId: req.user.id });
    res.json(result);
  } catch (err) {
    if (err && typeof err === 'object' && Number.isInteger(err.status)) {
      return res.status(err.status).json({ message: err.message });
    }
    res.status(500).json({ message: err.message });
  }
});


// ─── Search users to start a chat ────────────────────────────────────────────
router.get('/search-users', protect, authorize('chat:read:own'), async (req, res) => {
  try {
    const { q = '', limit = 20 } = req.query;
    const safe = escapeRegex(q);
    const me = req.authUser;
    const myId = uid(me._id);

    // Patient sirf doctors dhoondh sakta hai, doctor sirf patients.
    if (me.role === 'patient') {
      const filter = { approved: true };
      if (safe) {
        filter.$or = [
          { name: { $regex: safe, $options: 'i' } },
          { specialization: { $regex: safe, $options: 'i' } },
          { department: { $regex: safe, $options: 'i' } },
          { email: { $regex: safe, $options: 'i' } },
        ];
      }
      const doctors = await Doctor.find(filter)
        .populate('user_id', 'name avatar role isOnline lastActive')
        .select('name specialization department profile_photo user_id email phone')
        .limit(Number(limit)).lean();
      return res.json(doctors.map((d) => {
        const account = d.user_id && typeof d.user_id === 'object'
          ? d.user_id
          : { _id: d.user_id || d._id, name: d.name, avatar: d.profile_photo || '', role: 'doctor' };
        return {
          _id: account._id,
          name: account.name || d.name,
          avatar: account.avatar || d.profile_photo || '',
          role: account.role || 'doctor',
          isOnline: account.isOnline,
          lastActive: account.lastActive,
          specialization: d.specialization,
          department: d.department,
        };
      }).filter((u) => u._id && uid(u._id) !== myId));
    }

    if (isDoctorRole(me.role)) {
      // CHAT-B-09: this searched the ENTIRE patient directory (name / email /
      // phone / UHID) for any doctor token, and `limit` went straight into
      // .limit() (limit=100000 dumped the collection). Search is now restricted
      // to patients this doctor actually has a care relationship with — the
      // same linkage the /contacts endpoint uses — and the limit is clamped.
      const cappedLimit = Math.min(Math.max(Number.parseInt(limit, 10) || 20, 1), 50);
      const linked = await getLinkedContacts(me);
      // getLinkedContacts() returns an array of { user, ... } entries.
      const linkedIds = (Array.isArray(linked) ? linked : [])
        .map((c) => uid(c?.user?._id || c?.user))
        .filter(Boolean);
      if (!linkedIds.length) return res.json([]);

      const filter = { _id: { $in: linkedIds } };
      if (safe) {
        // CHAT-B-09: no phone/e-mail harvesting from search — name only.
        filter.name = { $regex: safe, $options: 'i' };
      }
      const patients = await User.find(filter)
        .select('name avatar role isOnline lastActive uhid gender').limit(cappedLimit).lean();
      return res.json(patients.filter((p) => uid(p._id) !== myId));
    }

    return res.json([]);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// ─── Contacts: mere saare doctors / patients (appointments se linked) ────────
router.get('/contacts', protect, authorize('chat:read:own'), async (req, res) => {
  try {
    const { q = '' } = req.query;
    const me = req.authUser;
    if (me.role !== 'patient' && !isDoctorRole(me.role)) {
      return res.json([]);
    }

    let contacts = await getLinkedContacts(me);
    if (q) {
      const safe = escapeRegex(q).toLowerCase();
      contacts = contacts.filter((c) =>
        (c.user?.name || '').toLowerCase().includes(safe) ||
        (c.user?.email || '').toLowerCase().includes(safe) ||
        (c.user?.uhid || '').toLowerCase().includes(safe) ||
        (c.specialization || '').toLowerCase().includes(safe)
      );
    }

    // Last message / unread badge ke liye conversation jodna
    const otherIds = contacts.map((c) => c.user._id);
    const convs = otherIds.length
      ? await ChatConversation.find({ participants: { $all: [me._id], $in: otherIds } })
          .populate('lastMessage', 'content type createdAt sender deletedForEveryone')
          .lean()
      : [];
    const byUser = new Map();
    convs.forEach((c) => {
      const other = c.participants.find((p) => uid(p) !== uid(me._id));
      if (other) byUser.set(uid(other), c);
    });

    const out = contacts.map((c) => {
      const conv = byUser.get(uid(c.user._id)) || null;
      return {
        ...c,
        conversationId: conv?._id || null,
        unreadCount: conv ? getUnreadCount(conv, me._id) : 0,
        lastMessage: conv?.lastMessage
          ? { content: conv.lastMessage.deletedForEveryone ? '' : conv.lastMessage.content, type: conv.lastMessage.type, createdAt: conv.lastMessage.createdAt }
          : null,
        lastMessageAt: conv?.lastMessageAt || null,
      };
    });

    out.sort((a, b) => new Date(b.lastMessageAt || 0) - new Date(a.lastMessageAt || 0));
    res.json(out);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// ─── Get all conversations (filter: all | archived | unread) ────────────────
router.get('/conversations', protect, authorize('chat:read', 'chat:read:own'), async (req, res) => {
  try {
    const userId = req.user.id;
    const { filter = 'all' } = req.query;
    // Pending message requests alag section me jaati hain (jab tak main initiator na hoon)
    const convs = await ChatConversation.find({
      participants: userId,
      $or: [
        { requestStatus: { $ne: 'pending' } },
        { initiatedBy: userId },
        { initiatedBy: null },
      ],
    })
      .populate('participants', 'name avatar role isOnline lastActive')
      .populate({
        path: 'lastMessage',
        populate: { path: 'replyTo', select: 'content type sender' },
      })
      .populate('pinnedMessage', 'content type sender createdAt')
      .sort({ lastMessageAt: -1 })
      .lean();

    const out = [];
    for (const conv of convs) {
      const id = uid(userId);
      if (conv.deletedFor?.some((d) => uid(d) === id)) continue;
      if (filter === 'archived' && !conv.archivedBy?.some((a) => uid(a) === id)) continue;
      if (filter === 'all' && conv.archivedBy?.some((a) => uid(a) === id)) continue;
      if (filter === 'locked' && !conv.lockedBy?.some((l) => uid(l.userId) === id)) continue;
      if (filter !== 'locked' && conv.lockedBy?.some((l) => uid(l.userId) === id)) continue;
      const unread = getUnreadCount(conv, userId);
      if (filter === 'unread' && unread === 0) continue;

      // Privacy: other user ne last seen / online hide kiya ho to strip karo
      const other = (conv.participants || []).find((p) => uid(p._id) !== id) || null;
      if (other) {
        const otherPrivacy = await getPrivacy(other._id);
        if (otherPrivacy.online === 'nobody') other.isOnline = false;
        if (otherPrivacy.lastSeen === 'nobody') delete other.lastActive;
      }

      conv.unread = unread;
      conv.pinned = conv.pinnedBy?.some((p) => uid(p) === id) || false;
      conv.muted = conv.mutedBy?.some((m) => uid(m) === id) || false;
      conv.archived = conv.archivedBy?.some((a) => uid(a) === id) || false;
      conv.myDraft = conv.drafts?.find((d) => uid(d.userId) === id)?.text || '';
      conv.requestStatus = conv.requestStatus || 'accepted';
      conv.locked = conv.lockedBy?.some((l) => uid(l.userId) === id) || false;
      conv.myWallpaper = conv.wallpapers?.find((w) => uid(w.userId) === id)?.value || '';
      out.push(conv);
    }
    // Pinned chats first, then latest
    out.sort((a, b) => (b.pinned - a.pinned) || (new Date(b.lastMessageAt) - new Date(a.lastMessageAt)));
    res.json(out);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

// ─── Get or create conversation with a user ─────────────────────────────────
router.post('/conversations', protect, authorize('chat:write', 'chat:write:own'), async (req, res) => {
  try {
    const { targetUserId } = req.body;
    const me = req.authUser;
    const userId = uid(me._id);
    if (!targetUserId) return res.status(400).json({ message: 'targetUserId required' });
    if (userId === uid(targetUserId)) {
      return res.status(400).json({ message: 'Cannot chat with yourself' });
    }

    const target = await User.findById(targetUserId).select('name avatar role email uhid');
    if (!target) return res.status(404).json({ message: 'User not found' });

    // Sirf doctor ↔ patient chat allowed
    if (!isDoctorPatientPair(me.role, target.role)) {
      return res.status(403).json({ message: 'Chat is available only between a doctor and a patient' });
    }

    let conversation = await ChatConversation.findOne({
      participants: { $all: [me._id, target._id] }
    }).populate('participants', 'name avatar role isOnline lastActive');

    if (!conversation) {
      // Message request: agar appointment-linked nahi hai to recipient ki policy lagti hai
      const linked = await hasAppointmentLink(me, target);
      let requestStatus = 'accepted';
      if (!linked) {
        const targetPrivacy = await getPrivacy(target._id);
        if (targetPrivacy.requestPolicy === 'block') {
          return res.status(403).json({ message: 'This user is not accepting new messages' });
        }
        requestStatus = targetPrivacy.requestPolicy === 'accept' ? 'accepted' : 'pending';
      }

      conversation = new ChatConversation({
        participants: [me._id, target._id],
        initiatedBy: me._id,
        requestStatus,
      });
      await conversation.save();
      await conversation.populate('participants', 'name avatar role isOnline lastActive');

      if (requestStatus === 'pending') {
        emitChatNotification(String(target._id), 'chat:message_request', {
          conversationId: conversation._id,
          from: { _id: me._id, name: me.name, role: me.role },
        });
      }
    } else {
      // "Delete chat" kiya tha to wapas unhide karo
      let changed = false;
      if (conversation.deletedFor?.some((d) => uid(d) === userId)) {
        conversation.deletedFor = conversation.deletedFor.filter((d) => uid(d) !== userId);
        changed = true;
      }
      if (conversation.requestStatus === 'declined') {
        conversation.requestStatus = 'pending';
        changed = true;
      }
      if (changed) await conversation.save();
    }

    await decorateConversation(conversation, userId);
    res.json(conversation);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

