// ─── Send a message (with reply, forward, disappearing, unread counts) ──────
router.post('/messages', protect, authorize('chat:write:own'), async (req, res) => {
  try {
    const { conversationId, content = '', type = 'text', attachments = [], replyTo = null, forwarded = false, clientGeneratedId = '' } = req.body;
    const senderId = req.user.id;

    const conversation = await getConversationForUser(conversationId, senderId);
    if (!conversation) return res.status(404).json({ message: 'Conversation not found' });
    if (conversation.contextType) {
      const verdict = await assertRoomAccess(senderId, req.user.role, conversation.contextType, conversation.contextId);
      if (!verdict.ok || !(conversation.contextParticipants || []).some((partyId) => String(partyId) === String(senderId))) {
        return res.status(404).json({ message: 'Conversation not found' });
      }
    }

    // Offline queue retry: same clientGeneratedId dobara aaya to duplicate
    // message banane ke bajaye pehla wala hi wapas bheja jata hai.
    if (clientGeneratedId) {
      const existing = await ChatMessage.findOne({ conversationId, sender: senderId, clientGeneratedId })
        .populate('replyTo', 'content type sender deletedForEveryone')
        .populate('sender', 'name avatar');
      if (existing) return res.status(200).json(sanitizeMessage(existing, senderId));
    }

    // Recipient ne block kiya hai to send na ho
    const recipientId = otherParticipantId(conversation, senderId);
    if (recipientId && conversation.blockedBy.some((b) => uid(b) === recipientId)) {
      return res.status(403).json({ message: 'You cannot send messages to this user' });
    }
    if (conversation.blockedBy.some((b) => uid(b) === uid(senderId))) {
      return res.status(403).json({ message: 'Unblock this chat to send messages' });
    }
    if (conversation.requestStatus === 'declined') {
      return res.status(403).json({ message: 'This conversation was declined' });
    }
    // Patient/doctor ke liye content validation — dono me se ek hona chahiye
    const hasText = String(content).trim().length > 0;
    const hasAttachments = Array.isArray(attachments) && attachments.length > 0;
    if (!hasText && !hasAttachments) {
      return res.status(400).json({ message: 'Message cannot be empty' });
    }

    // CHAT-BUG-04: Reject base64 file payloads smuggled in message content
    if (typeof content === 'string' && /^(data:[a-zA-Z0-9+/.-]+;base64,)/i.test(content.trim())) {
      return res.status(400).json({ message: 'Base64 file payloads not allowed in message content. Use /upload endpoint instead.' });
    }

    // CHAT-M-02: the client `attachments` array is no longer trusted verbatim.
    // Every entry must point at an existing, policy-passing file under
    // /uploads/chat (rejects external URLs, traversal, lying mimes/extension
    // mismatches, oversize values and dead references).
    const attachmentError = validateChatAttachments(attachments);
    if (attachmentError) {
      return res.status(attachmentError.status).json({ message: attachmentError.message });
    }

    const message = new ChatMessage({
      conversationId,
      sender: senderId,
      content,
      type,
      attachments,
      replyTo: replyTo || null,
      forwarded: Boolean(forwarded),
      clientGeneratedId: clientGeneratedId || '',
    });

    // Disappearing messages timer
    if (conversation.disappearing?.enabled && conversation.disappearing.durationHours > 0) {
      message.expiresAt = new Date(Date.now() + conversation.disappearing.durationHours * 3600 * 1000);
    }

    await message.save();
    await message.populate('replyTo', 'content type sender deletedForEveryone');
    await message.populate('sender', 'name avatar');

    // 8.md §5/§6 + 9.md §5: crisis keywords in chat text route to the human
    // review queue (critical). Fire-and-forget AFTER persist: screening must
    // never block or fail the send, and only text content is screened.
    if (message.type === 'text' && String(message.content || '').trim()) {
      void (async () => {
        try {
          const { analyzeContent } = await import('../lib/moderationRules.js');
          const { ensureModerationItem } = await import('../lib/moderationActions.js');
          const analysis = analyzeContent(String(message.content), { targetType: 'chat' });
          if (analysis.categories.includes('crisis')) {
            await ensureModerationItem({
              targetType: 'chat_message',
              targetId: String(message._id),
              category: 'crisis',
              reason: 'crisis keyword in chat message',
              severity: 'critical',
              source: 'auto_filter',
              reporterId: null,
              subjectUserId: senderId,
              note: 'Auto-escalated for human review; no auto-ban.',
            });
            await auditLog('chat_crisis_escalated', senderId, {
              messageId: String(message._id),
              conversationId: String(conversationId),
            });
          }
        } catch (err) {
          const { default: logger } = await import('../config/logger.js').catch(() => ({ default: console }));
          logger.warn(`chat crisis screen failed: ${err?.message}`);
        }
      })();
    }

    conversation.lastMessage = message._id;
    conversation.lastMessageAt = message.createdAt;
    // Naya message bhejne par chat list me wapas dikhna chahiye
    conversation.deletedFor = conversation.deletedFor.filter((d) => uid(d) !== uid(senderId));
    // Sender ka draft clear karo
    conversation.drafts = (conversation.drafts || []).filter((d) => uid(d.userId) !== uid(senderId));
    // recipient ka unread count badhao
    if (recipientId) {
      const entry = conversation.unreadCounts.find((u) => uid(u.userId) === recipientId);
      if (entry) entry.count += 1;
      else conversation.unreadCounts.push({ userId: recipientId, count: 1 });
    }
    await conversation.save();

    const payload = sanitizeMessage(message, senderId);
    emitChatEvent(conversationId, 'chat:receive_message', payload);
    if (recipientId) {
      emitChatNotification(recipientId, 'chat:new_message_notification', payload);
      // CHAT-M-04: sockets only reach an open tab — fall back to env-gated web
      // push when the recipient has no live presence. Routing metadata only;
      // pushSender resolves the role-scoped deep link (the FE chat routes are
      // role-based). The PHI-free copy is built inside pushSender (NOTIF-B-05).
      // Never blocks or fails the send (message is already persisted above).
      void sendChatPush(recipientId, {
        conversationId: String(conversationId),
        tag: `chat:${conversationId}`,
      }).catch(() => {});
    }
    res.status(201).json(payload);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

