      role: c.role,
      phoneEnc: looksMasked(c.phone) ? '' : encryptPhi('Lead', 'contacts.phone', c.phone),
      emailEnc: looksMasked(c.email) ? '' : encryptPhi('Lead', 'contacts.email', c.email),
    }));

    const lead = await Lead.create({
