} from '../config/redis.js';

const router = express.Router();

const doctorSpecialtyCondition = (value) => {
  const base = specialtyCondition(value);
  if (!base) return null;
  const code = resolveSpecialtyCode(value);
  if (!code) return base;
  const isTop = /^SPEC\.[A-Z0-9]+$/.test(code);
  const codes = new Set([code]);
  if (isTop) {
    const prefix = `${code}.`;
    for (const specialty of SPECIALTIES) {
      if (specialty.code.startsWith(prefix) || (specialty.alsoUnder || []).includes(code)) codes.add(specialty.code);
    }
  }
  return { $or: [...(base.$or || [base]), { subSpecialtyCodes: { $in: [...codes] } }] };
};

const upload = multer({
  storage: multer.memoryStorage(),
  limits: { fileSize: 5 * 1024 * 1024 },
  fileFilter: (req, file, cb) => {
    if (file.mimetype === 'image/png' || file.mimetype === 'image/jpeg') return cb(null, true);
    cb(new Error('Only PNG and JPG images are allowed'));
  },
});

const isAdminListRequest = async (req) => {
  const auth = req.headers.authorization;
  if (!auth?.startsWith('Bearer ')) return false;

  try {
    const token = auth.split(' ')[1];
    const decoded = verifyAccessToken(token);
    const user = await User.findById(decoded.id).select('role status isVerified');
    return Boolean(user && user.role === 'hospital_admin' && user.status !== 'blocked' && user.isVerified);
  } catch {
    return false;
  }
};

