router.get('/', async (req, res) => {
  try {
    const {
      page, limit, search, available, specialization, specialty, specialtyCode,
      location, city, includeAll, hospitalId, facilityId, doctor_type,
      homeVisit, language, languages, condition, procedure, fallbackSpecialtyCode,
    } = req.query;

    // AUTH-027: role + user in the key — otherwise an admin-view response
    // cached under bare query params is served to the next role.
    const cacheKey = `doctors_list_${req.user?.role || 'anon'}:${req.user?._id || 'none'}:${JSON.stringify(req.query)}`;
    const cached = await getCache(cacheKey);
    if (cached) {
      res.setHeader('X-Cache', 'HIT');
      return res.json(cached);
    }
    const filter = {};
    const canViewAll = includeAll === 'true' && await isAdminListRequest(req);
    if (!canViewAll) filter.approved = true;

    // Non-superadmin admin/clinic_doctor ko apni hi facility ke doctors milein — query param se bypass na ho
    let effectiveHospitalId = hospitalId;
    let effectiveFacilityId = facilityId;
    if (req.user && req.user.role !== 'superadmin' && (req.user.role === 'hospital_admin' || req.user.role === 'clinic_doctor')) {
      effectiveHospitalId = req.user.hospitalId ? req.user.hospitalId.toString() : undefined;
      effectiveFacilityId = req.user.facilityId ? req.user.facilityId.toString() : undefined;
    }
    if (effectiveFacilityId) filter.facilityId = effectiveFacilityId;
    if (search) filter.$or = [
      { name: new RegExp(escapeRegex(capSearch(search)), 'i') },
      { specialization: new RegExp(escapeRegex(capSearch(search)), 'i') },
    ];
    const specTarget = specialization || specialty || specialtyCode;
    if (specTarget && specTarget !== 'All') {
      const specialtyFilter = doctorSpecialtyCondition(specTarget);
      if (specialtyFilter) filter.$and = [...(filter.$and || []), specialtyFilter];
    }
    const fallbackCode = fallbackSpecialtyCode ? resolveSpecialtyCode(String(fallbackSpecialtyCode)) : null;
    const fallbackFilter = fallbackCode ? doctorSpecialtyCondition(fallbackCode) : null;
    for (const [term, field] of [[condition, 'conditionsTreated'], [procedure, 'procedures']]) {
      const safeTerm = capSearch(term);
      if (!safeTerm) continue;
      const regex = new RegExp(escapeRegex(safeTerm), 'i');
      const directMatch = { [field]: { $elemMatch: { $or: [{ label: regex }, { code: regex }] } } };
      const alternatives = [directMatch];
      if (fallbackFilter) {
        alternatives.push({ $and: [fallbackFilter, { $or: [{ [field]: { $exists: false } }, { [field]: { $size: 0 } }] }] });
      }
      filter.$and = [...(filter.$and || []), { $or: alternatives }];
    }
    const locOrCity = city || location;
    if (locOrCity && locOrCity !== 'All') filter.location = new RegExp(escapeRegex(capSearch(locOrCity)), 'i');
    if (available !== undefined) filter.available = available === 'true';
    if (doctor_type) filter.doctor_type = doctor_type;

    // B4 Facets (home visit & language)
    if (homeVisit === 'true' || homeVisit === true || homeVisit === '1') {
      filter.$or = [
        ...(filter.$or ? [filter.$or] : []),
        { home_visit: true },
        { appointmentModes: { $in: ['home_visit', 'home'] } },
      ];
    }
    const langTarget = language || languages;
    if (langTarget) {
      filter.languages = { $in: [new RegExp(escapeRegex(String(langTarget)), 'i')] };
    }

    const paginateOpts = {
      page, limit,
      sort: { createdAt: -1 },
      populate: [
        { path: 'hospitalId', select: 'name address city phone email rating reviewsCount establishedYear totalDoctors accreditations hospitalType emergency24x7 bedAvailability ambulanceService insuranceAccepted workingHours logo' },
        { path: 'facilityId', select: 'name address city phone email type status rating reviewsCount specialties establishedYear' },
      ],
    };

    let result;
    if (effectiveHospitalId) {
      try {
        filter.hospitalId = effectiveHospitalId;
        result = await paginatedResults(Doctor, filter, paginateOpts);
      } catch (castErr) {
        const l = Math.min(100, Math.max(1, parseInt(limit) || 20));
        return res.json({ data: [], total: 0, page: 1, limit: l, totalPages: 0 });
      }
    } else {
      result = await paginatedResults(Doctor, filter, paginateOpts);
    }

    // Enrich with clinic profiles
    const clinicDoctorIds = result.data.filter(d => d.doctor_type === 'clinic').map(d => d._id);
    if (clinicDoctorIds.length) {
      const profiles = await ClinicProfile.find({ doctorId: { $in: clinicDoctorIds } }).lean();
      const profileMap = Object.fromEntries(profiles.map(p => [p.doctorId.toString(), p]));
      result.data = result.data.map(d => {
        if (d.doctor_type === 'clinic') d.clinicProfile = profileMap[d._id.toString()] || null;
        return d;
      });
    }

    await setCache(cacheKey, result, 300);
    res.json(result);
  } catch (err) { res.status(500).json({ message: err.message }); }
});

