router.post('/', protect, validate(createDoctorSchema), async (req, res) => {
  try {
    if (req.user.role !== 'superadmin' && req.user.role !== 'hospital_admin') {
      return res.status(403).json({ message: 'Admin access required' });
    }
    const hospitalId = req.user.hospitalId;
    if (!hospitalId && req.user.role !== 'superadmin') {
      return res.status(400).json({ message: 'No hospital linked to this account' });
    }

    const { name, email, phone, specialization, experience, qualification, consultation_fees, fees, hospitalId: bodyHospitalId } = req.body;
    
    if (!email) return res.status(400).json({ message: 'Doctor email is required' });
    if (!name) return res.status(400).json({ message: 'Doctor name is required' });
    // DOC-B-02: the tenant comes from the SESSION, never from the body.
    // `bodyHospitalId || hospitalId` let a hospital_admin create a doctor (User +
    // profile + a working setup-token email) inside ANOTHER hospital's tenant.
    // Only superadmin may target one explicitly; a tenant admin always lands in
    // its own hospital.
    const targetHospitalId = req.user.role === 'superadmin'
      ? (bodyHospitalId || hospitalId)
      : (req.user.hospitalId || req.user.facilityId || hospitalId) || undefined;

    // Check if user already exists
    const existingUser = await User.findOne({ email: email.toLowerCase() });
    if (existingUser) {
      return res.status(400).json({ message: 'A user with this email already exists' });
    }

    // Create User with temporary status
    const tempPassword = randomPassword(12);
    const setupToken = signJwt({ email: email.toLowerCase(), type: 'doctor_setup', jti: crypto.randomBytes(12).toString('hex') }, { expiresIn: '48h' });

    const user = await User.create({
      name,
      email: email.toLowerCase(),
      password: tempPassword,
      mustResetPassword: true,
      role: 'doctor',
      phone: phone || '',
      hospitalId: targetHospitalId,
      isVerified: false,
      status: 'active',
      approvalStatus: 'approved',
    });

    // Create Doctor profile
    const doctor = await Doctor.create({
      name,
      email: email.toLowerCase(),
      phone: phone || '',
      specialization: specialization || 'General Medicine',
      specialtyCode: resolveSpecialtyCode(specialization || 'General Medicine') || '',
      experience: experience || '1 year',
      qualifications: qualification || '',
      fees: Number(consultation_fees || fees || 500),
      consultation_fees: Number(consultation_fees || fees || 500),
      approved: true,
      user_id: user._id.toString(),
      hospitalId: targetHospitalId,
      initials: name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase(),
      available: true,
    });

    // Send invitation email with setup link
    const setupUrl = `${process.env.CLIENT_URL || 'http://localhost:5173'}/#/doctor-setup?token=${setupToken}`;
    await sendEmail({
      to: email.toLowerCase(),
      subject: 'Welcome to FindMedi — Set up your doctor account',
      html: `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px;">
          <h2 style="color: #0b8a72;">Welcome to FindMedi, ${name}!</h2>
          <p>An admin has created a doctor account for you. Please set up your password to get started.</p>
          <a href="${setupUrl}" style="display: inline-block; padding: 12px 24px; background: #0b8a72; color: white; text-decoration: none; border-radius: 6px; font-size: 16px;">
            Set Up My Account
          </a>
          <p style="margin-top: 24px; color: #666;">This link expires in 48 hours. If you did not expect this invitation, please ignore this email.</p>
        </div>
      `,
      text: `Welcome to FindMedi! An admin has created a doctor account for you. Set up your password here: ${setupUrl}`,
    });

    res.status(201).json({
      message: 'Doctor created. An invitation email has been sent.',
      doctor,
    });
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.put('/:id', protect, validate(updateDoctorSchema), async (req, res) => {
  try {
    const doctor = await Doctor.findById(req.params.id);
    if (!doctor) return res.status(404).json({ message: 'Doctor not found' });
    const isSelf = req.user.doctorProfileId?.toString() === req.params.id ||
      doctor.user_id?.toString() === req.user._id?.toString() ||
      (doctor.email && doctor.email.toLowerCase() === req.user.email?.toLowerCase());
    const isHospitalAdmin = req.user.role === 'hospital_admin' && doctor.hospitalId?.toString() === req.user.hospitalId?.toString();
    const isClinicAdmin = req.user.role === 'clinic_doctor' && ((req.user.facilityId && doctor.facilityId?.toString() === req.user.facilityId?.toString()) || isSelf);
    const isSuperAdmin = req.user.role === 'superadmin';

    if (!isSelf && !isHospitalAdmin && !isClinicAdmin && !isSuperAdmin) {
      return res.status(403).json({ message: 'Not authorized to update this doctor' });
    }
    // §8: fold legacy flat settings keys into settings.* so nothing is dropped.
    const body = { ...req.body };
    const flatKeys = ['emergencyOnCall', 'refundGuarantee', 'videoFee', 'inPersonFee', 'emergencyFee', 'followUpFee', 'followUpWindow', 'bufferTime', 'vacationFrom', 'vacationTo', 'vacationReason', 'councilName', 'councilRegNo', 'councilYear', 'payoutUpi', 'payoutAccount', 'payoutIfsc',
      'walkInAccepted', 'refundTier', 'inClinicFee', 'homeVisitFee', 'travelPerKm', 'homeVisitRadiusKm', 'shift1Start', 'shift1End', 'shift2Start', 'shift2End', 'posBankHolder', 'posBankAccount', 'posBankIfsc', 'establishmentLicense', 'establishmentLicenseExpiry'];
    const hasFlat = flatKeys.some((k) => body[k] !== undefined);
    if (hasFlat || (body.settings && typeof body.settings === 'object')) {
      const prev = doctor.settings?.toObject?.() || doctor.settings || {};
      const merged = { ...prev, ...(body.settings || {}) };
      for (const k of flatKeys) {
        if (body[k] !== undefined) {
          merged[k] = (k === 'emergencyOnCall') ? Boolean(body[k])
            : (['videoFee', 'inPersonFee', 'emergencyFee'].includes(k)) ? (Number(body[k]) || 0)
            : body[k];
          delete body[k];
        }
      }
      body.settings = merged;
    }
    // DOC-B-01: the schema rejects server-owned fields, and this is the second
    // layer — the write is an explicit allowlist, so a future schema relaxation
    // cannot silently re-open the hole. `req.body` is no longer passed through.
    const WRITABLE = [
      'name', 'specialization', 'phone', 'experience', 'qualification',
      'location', 'bio', 'available', 'emergencySupport',
      'refundOnMissedOrCancelled', 'appointmentModes', 'appointmentFees',
      'chat_fee', 'video_fee', 'offline_fee', 'home_visit_fee', 'emergency_fee',
      'languages', 'image', 'photo', 'gender', 'degree', 'registrationNumber',
      'settings', 'conditionsTreated', 'procedures', 'subSpecialtyCodes',
    ];
    const writable = Object.create(null);
    for (const key of WRITABLE) {
      if (body[key] !== undefined) writable[key] = body[key];
    }
    // The legacy flat settings keys were folded into body.settings above.
    writable.settings = body.settings;
    if (writable.specialization !== undefined) {
      writable.specialtyCode = resolveSpecialtyCode(writable.specialization) || '';
    }
    if (writable.subSpecialtyCodes !== undefined) {
      const rootCode = writable.specialtyCode || doctor.specialtyCode || resolveSpecialtyCode(doctor.specialization);
      const requested = [...new Set(writable.subSpecialtyCodes.map(remapSubSpecialtyCode).filter(Boolean))];
      const allowed = new Set(SPECIALTIES
        .filter((entry) => entry.code.startsWith(`${rootCode}.`) || (entry.alsoUnder || []).includes(rootCode))
        .map((entry) => entry.code));
      const invalid = requested.filter((code) => !allowed.has(code));
      if (invalid.length) return res.status(400).json({ message: 'Selected sub-specialty does not belong to the doctor\'s main specialty', invalidCodes: invalid });
      writable.subSpecialtyCodes = requested;
    }

    const updated = await Doctor.findByIdAndUpdate(req.params.id, writable, { new: true, runValidators: true });
    res.json(updated);
  } catch (err) { sendServerError(res, err, 'Could not update doctor profile'); }
});

// §5.4: strict — client sirf ClinicProfile ke writable fields bhej sakta hai.
// Wire format SNAKE_CASE hai (frontend DoctorProfile `clinic_name` bhejta hai);
// doctorId/clinicId server-owned hain (clinicId client-settable hota to unique
