// ─── 4. POST /api/emergency-doctor/:requestId/accept ──────────────────────
router.post('/:requestId/accept', protect, authorize('emergency:write'), async (req, res) => {
  try {
    const { requestId } = req.params;
    const userId = req.user._id || req.user.id;

    const doctor = await Doctor.findOne({ user_id: userId });
    if (!doctor) return res.status(404).json({ success: false, message: 'Doctor profile not found' });

    // Concurrency lock check
    const existingReq = await EmergencyDoctorRequest.findById(requestId);
    if (!existingReq) return res.status(404).json({ success: false, message: 'Request not found' });
    if (existingReq.status !== 'searching') {
      return res.status(409).json({ success: false, message: 'This emergency has already been claimed by another physician' });
    }

    // RIDE-B-16: eligibility before the claim.
    //  1) the doctor profile must be approved,
    //  2) the doctor must actually be on emergency duty (no duty => no claim),
    //  3) the doctor must have a real location and be within the service radius —
    //     the [0,0] fallback used to fabricate a huge ETA that the patient was
    //     shown for a doctor who was never dispatched.
    if (doctor.approved === false) {
      return res.status(403).json({ success: false, message: 'Your doctor profile is not approved for emergency duty' });
    }
    if (doctor.emergencyDoctorOnDuty === false || doctor.isOnEmergencyDuty === false) {
      return res.status(403).json({ success: false, message: 'You are not on emergency duty' });
    }
    const rawCoords = doctor.emergencyDoctorLocation?.coordinates;
    const hasRealLocation = Array.isArray(rawCoords)
      && rawCoords.length === 2
      && Number.isFinite(Number(rawCoords[0]))
      && Number.isFinite(Number(rawCoords[1]))
      && !(Number(rawCoords[0]) === 0 && Number(rawCoords[1]) === 0);
    if (!hasRealLocation) {
      return res.status(403).json({ success: false, message: 'Share your live location before accepting an emergency' });
    }
    const doctorCoords = rawCoords;
    const patientCoords = existingReq.pickupLocation.coordinates;
    const distKm = calculateDistanceKm(doctorCoords, patientCoords);
    const radiusKm = Number(doctor.emergencyRadiusKm || doctor.emergencyDoctorRadiusKm || existingReq.startingRadiusKm || 25);
    if (distKm > radiusKm) {
      return res.status(403).json({ success: false, message: `You are ${distKm} km away — outside your ${radiusKm} km emergency radius` });
    }
    const etaMinutes = Math.max(3, Math.round(distKm * 2.5));

    // RIDE-B-16: the claim is applied ATOMICALLY with `{ status: 'searching' }`
    // in the filter, so two doctors racing for the same emergency cannot both win
    // (the loser gets null and a 409).
    const doctorClaimed = await Doctor.findOneAndUpdate(
      { _id: doctor._id, activeDispatchRequestId: null },
      { $set: { activeDispatchRequestId: requestId } },
      { new: true, select: '_id' }
    );
    if (!doctorClaimed) return res.status(409).json({ success: false, message: 'You are already assigned to an active emergency' });

    let updated;
    try {
      updated = await EmergencyDoctorRequest.findOneAndUpdate(
        { _id: requestId, status: 'searching' },
        {
        $set: {
          assignedDoctorId: doctor._id,
          assignedDoctorUserId: userId,
          clinicId: doctor.facilityId || null,
          status: 'assigned',
          transitDistanceKm: distKm,
          estimatedArrivalMinutes: etaMinutes,
          doctorLiveLocation: {
            type: 'Point',
            coordinates: doctorCoords,
            updatedAt: new Date(),
          },
        },
        $push: {
          timeline: {
            stage: 'assigned',
            timestamp: new Date(),
            note: `Accepted by Dr. ${doctor.name}`,
            coordinates: doctorCoords,
          },
        },
        },
        { new: true }
      );
    } catch (error) {
      await releaseProviderClaim('emergency_doctor', userId, requestId).catch((releaseError) => {
        logger.error(`Failed to release doctor claim after accept error: ${releaseError.message}`);
      });
      throw error;
    }

    // RIDE-B-16: the loser's atomic update returns null (someone else claimed it).
    if (!updated) {
      await releaseProviderClaim('emergency_doctor', userId, requestId);
      return res.status(409).json({ success: false, message: 'This emergency has already been claimed by another physician' });
    }

    // Notify Patient via Socket
    try {
      const io = getIO();
      if (io) {
        io.to(`user_${existingReq.patientId}`).emit('emergency_doctor:doctor_assigned', {
          requestId: updated._id,
          doctor: {
            id: doctor._id,
            name: doctor.name,
            phone: doctor.phone,
            specialization: doctor.specialization,
            photo: doctor.profile_photo,
            etaMinutes,
            distanceKm: distKm,
          },
        });
      }
    } catch {}

    res.json({ success: true, request: updated });
  } catch (err) {
    res.status(500).json({ success: false, message: err.message });
  }
});

// ─── 5. PUT /api/emergency-doctor/:requestId/telemetry ────────────────────
router.put('/:requestId/telemetry', protect, authorize('emergency:read'), async (req, res) => {
  try {
    const { requestId } = req.params;
    const { coordinates, heading = 0, speed = 0 } = req.body;

    if (!coordinates || coordinates.length !== 2) {
      return res.status(400).json({ success: false, message: 'Coordinates [lng, lat] required' });
    }

    // RIDE-B-14: telemetry may only be written by the doctor assigned to THIS
    // request. `authorize('emergency:read')` is granted to patients and staff
    // alike, so any holder could spoof another patient's live doctor location.
    const telemetryScope = req.user.role === 'superadmin'
      ? { _id: requestId }
      : { _id: requestId, assignedDoctorUserId: req.user._id };

    const updated = await EmergencyDoctorRequest.findByIdAndUpdate(
      telemetryScope,
      {
        $set: {
          'doctorLiveLocation.coordinates': coordinates,
          'doctorLiveLocation.heading': heading,
          'doctorLiveLocation.speed': speed,
          'doctorLiveLocation.updatedAt': new Date(),
        },
      },
      { new: true }
    );

    if (!updated) {
      return res.status(403).json({ success: false, message: 'You are not assigned to this emergency request' });
    }
    // Stream update to patient in real-time
    try {
      const io = getIO();
      if (io && updated) {
        io.to(`user_${updated.patientId}`).emit('emergency_doctor:gps_update', {
          requestId: updated._id,
          coordinates,
          heading,
          speed,
        });
      }
    } catch {}

    res.json({ success: true, location: updated?.doctorLiveLocation });
  } catch (err) {
    res.status(500).json({ success: false, message: err.message });
  }
});

// ─── 6. PUT /api/emergency-doctor/:requestId/status ──────────────────────
router.put('/:requestId/status', protect, authorize('emergency:write'), async (req, res) => {
  try {
    const { requestId } = req.params;
    const { status, note = '', clinicalReport } = req.body;

    const allowed = ['en_route', 'arrived', 'in_triage', 'completed', 'escalated_to_ambulance'];
    if (!allowed.includes(status)) {
      return res.status(400).json({ success: false, message: `Invalid status: ${status}` });
    }

    // ED-M-01 lifecycle parity: terminal states are idempotent, non-terminal
    // transitions are CAS-guarded so a duplicate `completed` or a stale
    // client cannot move a closed request, matching assistant/lawyer 409s.
    const existingReq = await EmergencyDoctorRequest.findById(requestId).select('status').lean();
    if (!existingReq) {
      return res.status(404).json({ success: false, message: 'Emergency request not found' });
    }
    const TERMINAL_ED = ['completed', 'cancelled_by_user', 'cancelled_by_doctor', 'escalated_to_ambulance'];
    if (TERMINAL_ED.includes(existingReq.status)) {
      const idempotent = existingReq.status === status
        || (existingReq.status === 'escalated_to_ambulance' && status === 'escalated_to_ambulance');
      return res.status(idempotent ? 200 : 409).json({
        success: idempotent,
        message: idempotent ? 'Request was already closed' : `Cannot move a ${existingReq.status} request to ${status}`,
      });
    }
    const ELIGIBLE_ED = {
      en_route: ['assigned', 'in_progress'],
      arrived: ['en_route', 'assigned', 'in_progress'],
      in_triage: ['arrived', 'en_route', 'assigned', 'in_progress'],
      completed: ['assigned', 'in_progress', 'en_route', 'arrived', 'in_triage'],
      escalated_to_ambulance: ['assigned', 'in_progress', 'en_route', 'arrived', 'in_triage'],
    };
    if (!((ELIGIBLE_ED[status] || []).includes(existingReq.status))) {
      return res.status(409).json({
        success: false,
        message: `Cannot move a ${existingReq.status} request to ${status}`,
      });
    }

    const updateData = { status };
    if (clinicalReport) {
      updateData.clinicalReport = clinicalReport;
    }

    // RIDE-B-14: only the assigned doctor (or a superadmin) may drive the
    // lifecycle of an emergency request — otherwise any user holding
    // `emergency:write` could complete/escalate somebody else's SOS.
    // ED-M-01: the status predicate is part of the filter so a concurrent
    // close wins atomically (loser gets null → 409, never a double close).
    const statusScope = req.user.role === 'superadmin'
      ? { _id: requestId, status: existingReq.status }
      : { _id: requestId, assignedDoctorUserId: req.user._id, status: existingReq.status };

    const updated = await EmergencyDoctorRequest.findOneAndUpdate(
      statusScope,
      {
        $set: updateData,
        $push: {
          timeline: {
            stage: status,
            timestamp: new Date(),
            note,
          },
        },
      },
      { new: true }
    );

    if (!updated) {
      const latestStatus = await EmergencyDoctorRequest.findById(requestId).select('status').lean();
      if (latestStatus && latestStatus.status !== existingReq.status) {
        return res.status(latestStatus.status === status ? 200 : 409).json({
          success: latestStatus.status === status,
          message: latestStatus.status === status ? 'Request was already closed' : `Request is now ${latestStatus.status}`,
        });
      }
      return res.status(403).json({ success: false, message: 'You are not assigned to this emergency request' });
    }
    if (['completed', 'escalated_to_ambulance'].includes(status) && updated.assignedDoctorUserId) {
      await releaseProviderClaim('emergency_doctor', updated.assignedDoctorUserId, updated._id);
    }

    // Notify patient
    try {
      const io = getIO();
      if (io && updated) {
        io.to(`user_${updated.patientId}`).emit('emergency_doctor:status_changed', {
          requestId: updated._id,
          status,
          note,
        });
      }
    } catch {}

    res.json({ success: true, request: updated });
  } catch (err) {
    res.status(500).json({ success: false, message: err.message });
  }
});

// ─── 7. GET /api/emergency-doctor/:requestId ──────────────────────────────
router.get('/:requestId', protect, async (req, res) => {
  try {
    const { requestId } = req.params;
    const request = await EmergencyDoctorRequest.findById(requestId)
      .populate('assignedDoctorId', 'name specialization phone profile_photo hospitalId facilityId')
      .populate('patientId', 'name phone email');

    if (!request) return res.status(404).json({ success: false, message: 'Emergency request not found' });
    // RIDE-B-15: `protect` alone leaked the whole request (patient name/phone/
    // email, live location, clinical report) to any logged-in account.
    if (!canAccessEmergencyDoctorRequest(req, request)) {
      return res.status(403).json({ success: false, message: 'Not authorized to view this emergency request' });
    }
    res.json({ success: true, request });
  } catch (err) {
    res.status(500).json({ success: false, message: err.message });
  }
});

// ─── 8. POST /api/emergency-doctor/:requestId/cancel ─────────────────────
router.post('/:requestId/cancel', protect, authorize('emergency:write'), async (req, res) => {
  try {
    const { requestId } = req.params;
    const { reason = 'Cancelled by user' } = req.body;

    // RIDE-B-15: `cancelledBy` came from the body, so any caller could forge the
    // audit trail ("cancelled_by_user" vs "cancelled_by_doctor"). It is derived
    // from the session now, and ownership is enforced.
    const existing = await EmergencyDoctorRequest.findById(requestId);
    if (!existing) return res.status(404).json({ success: false, message: 'Emergency request not found' });
    if (!canAccessEmergencyDoctorRequest(req, existing)) {
      return res.status(403).json({ success: false, message: 'Not authorized to cancel this emergency request' });
    }
    const isAssignedDoctor = String(existing.assignedDoctorUserId || '') === String(req.user._id);
    const cancelledBy = isAssignedDoctor ? 'doctor' : 'patient';

    const updated = await EmergencyDoctorRequest.findByIdAndUpdate(
      requestId,
      {
        $set: {
          status: cancelledBy === 'doctor' ? 'cancelled_by_doctor' : 'cancelled_by_user',
          cancelledBy,
          cancellationReason: reason,
        },
        $push: {
          timeline: {
            stage: 'cancelled',
            timestamp: new Date(),
            note: `Cancelled (${cancelledBy}): ${reason}`,
          },
        },
      },
      { new: true }
    );

    if (existing.assignedDoctorId) await releaseProviderClaim('emergency_doctor', existing.assignedDoctorId, existing._id);
    res.json({ success: true, message: 'Emergency doctor request cancelled', request: updated });
  } catch (err) {
    res.status(500).json({ success: false, message: err.message });
  }
});

// ─── 8b. POST /api/emergency-doctor/:requestId/room ────────────────────────
// Spec 09: issue an encrypted video-triage session for an assigned consultation.
router.post('/:requestId/room', protect, async (req, res) => {
  try {
    const docReq = await EmergencyDoctorRequest.findById(req.params.requestId);
    if (!docReq) return res.status(404).json({ success: false, message: 'Request not found' });
    const me = String(req.user._id || req.user.id);
    const isParty = [String(docReq.userId), String(docReq.patientId), String(docReq.assignedDoctorUserId)].includes(me);
    if (!isParty && req.user.role !== 'superadmin') {
      return res.status(403).json({ success: false, message: 'Not a party to this consultation' });
    }
    if (!['assigned', 'in_progress'].includes(docReq.status)) {
      return res.status(400).json({ success: false, message: 'Room available only for active consultations' });
    }
    const { randomUUID } = await import('crypto');
    if (!docReq.webrtcRoom?.sessionId) {
      docReq.webrtcRoom = {
        sessionId: `EDR-${Date.now().toString(36).toUpperCase()}`,
        token: randomUUID(),
        startedAt: new Date(),
        endedAt: null,
      };
      if (docReq.status === 'assigned') docReq.status = 'in_progress';
      docReq.timeline.push({ stage: 'video_room_opened', timestamp: new Date(), note: 'Video triage session issued' });
      await docReq.save();
    }
    const io = getIO();
    io?.to(`emergency_doctor:${docReq._id}`).emit('emergency_doctor:status_changed', {
      requestId: String(docReq._id),
      status: docReq.status,
      videoSessionId: docReq.webrtcRoom.sessionId,
    });
    res.json({ success: true, room: { sessionId: docReq.webrtcRoom.sessionId, token: docReq.webrtcRoom.token } });
  } catch (err) {
    logger.error(`Video room error: ${err.message}`);
    res.status(500).json({ success: false, message: err.message });
  }
});

// ─── 9. POST /api/emergency-doctor/:requestId/escalate ─────────────────────
// Spec 09: doctor escalates to ALS ambulance mid-consultation — spins up a
// linked SOS EmergencyRequest and starts ambulance dispatch.
router.post('/:requestId/escalate', protect, authorize('emergency:write'), async (req, res) => {
  try {
    const { requestId } = req.params;
    const docReq = await EmergencyDoctorRequest.findById(requestId);
    if (!docReq) return res.status(404).json({ success: false, message: 'Request not found' });
    if (!['assigned', 'in_progress'].includes(docReq.status)) {
      return res.status(400).json({ success: false, message: 'Only active consultations can be escalated' });
    }
    const doctorId = String(req.user._id || req.user.id);
    if (docReq.assignedDoctorUserId && String(docReq.assignedDoctorUserId) !== doctorId && req.user.role !== 'superadmin') {
      return res.status(403).json({ success: false, message: 'Only the assigned doctor can escalate' });
    }

    const symptomToCategory = {
      chest_pain: 'heart_attack',
      breathing_issue: 'breathing_issue',
      injury: 'accident',
      severe_pain: 'other',
      high_fever: 'other',
      mental_health_crisis: 'other',
      other: 'other',
    };
    const { default: EmergencyRequest } = await import('../models/EmergencyRequest.js');
    const { startEmergencyDispatch } = await import('../services/emergencyDispatchService.js');
    const sos = await EmergencyRequest.create({
      userId: docReq.userId,
      reporterMode: 'other',
      patientDetails: {
        name: docReq.patientName || docReq.patientDetails?.name || 'Emergency Patient',
        age: docReq.patientAge ?? docReq.patientDetails?.age ?? null,
        gender: docReq.patientDetails?.gender || '',
        phone: docReq.patientPhone || docReq.patientDetails?.phone || '',
      },
      category: symptomToCategory[docReq.symptomCategory] || 'other',
      location: {
        type: 'Point',
        coordinates: docReq.location?.coordinates || docReq.pickupLocation?.coordinates || [79.9864, 23.1815],
        address: docReq.location?.address || docReq.pickupAddress || '',
      },
    });
    docReq.status = 'escalated_to_ambulance';
    docReq.timeline.push({ stage: 'escalated_to_ambulance', timestamp: new Date(), note: `Escalated to SOS ${sos._id} by doctor` });
    await docReq.save();
    if (docReq.assignedDoctorUserId) {
      await releaseProviderClaim('emergency_doctor', docReq.assignedDoctorUserId, docReq._id);
    }
    startEmergencyDispatch(sos._id).catch((err) => logger.error(`Escalated SOS dispatch error: ${err.message}`));

    const io = getIO();
    io?.to(`emergency_doctor:${requestId}`).emit('emergency_doctor:status_changed', {
      requestId: String(requestId),
      status: 'escalated_to_ambulance',
      sosRequestId: String(sos._id),
    });
    res.status(201).json({ success: true, message: 'Escalated to ambulance dispatch', sosRequestId: sos._id, request: docReq });
  } catch (err) {
    logger.error(`Escalate to ambulance error: ${err.message}`);
    res.status(500).json({ success: false, message: err.message });
  }
});

export default router;

import express from 'express';
import EmergencyRequest from '../models/EmergencyRequest.js';
import Hospital from '../models/Hospital.js';
import Ambulance from '../models/Ambulance.js';
import { protect, authorize } from '../middleware/auth.js';
import { bookingLimiter } from '../middleware/rateLimit.js';
import {
  handleProviderAccept,
  selectDestinationHospital,
  findEligibleAmbulances,
  findEligibleEmergencyVehicles,
} from '../services/emergencyDispatchService.js';
import RiderProfile from '../models/RiderProfile.js';
import {
  startManualModeSearch,
  bookChosenProvider,
  startAutoEscalateLoop,
  startAutoFindLoop,
} from '../services/sosVehicleService.js';
import SOSVehicleSettings from '../models/SOSVehicleSettings.js';
import { getIO } from '../services/socketService.js';
import logger from '../config/logger.js';

const router = express.Router();

// Ownership helper for a single SOS request (RIDE-B-11/12/15).
// Allowed: the patient who raised it, the provider it is assigned to, a
// superadmin. Everything else (any other logged-in account) is refused.
const isSosOwner = (req, r) => Boolean(r) && String(r.userId) === String(req.user._id || req.user.id);

const isAssignedProvider = async (req, r) => {
  if (!r?.assignedProviderId) return false;
  if (String(r.assignedProviderId) === String(req.user._id || req.user.id)) return true;
  if (r.assignedProviderType === 'ambulance') {
    const amb = await Ambulance.findById(r.assignedProviderId).select('userId').lean().catch(() => null);
    return Boolean(amb?.userId && String(amb.userId) === String(req.user._id || req.user.id));
  }
  return false;
};

const canAccessSos = async (req, r) => {
  if (!r) return false;
  if (req.user.role === 'superadmin') return true;
  if (isSosOwner(req, r)) return true;
  return isAssignedProvider(req, r);
};

/**
 * RIDE-B-01: middleware form of `canAccessSos` for every `/:id/*` route.
 *
 * The finding was that `/:id/status`, `/:id/book/:providerId`, `/:id/cancel` and
 * `/:id/progress` were `protect`-only. With any valid token an attacker could
 * poll a victim's LIVE LOCATION and emergency category, cancel a real dispatch
 * (a safety-of-life action), or push providers onto someone else's incident.
 *
 * This loads the session once, then answers **404** — not 403 — for anyone who
 * is not the requester, the assigned provider or a superadmin, so an id cannot
 * even be probed for existence.
 */
const requireSosAccess = async (req, res, next) => {
  try {
    const r = await EmergencyRequest.findById(req.params.id).select(
      'userId assignedProviderId assignedProviderType status'
    );
    if (!r) return res.status(404).json({ message: 'Request not found' });
    if (!(await canAccessSos(req, r))) {
      logger.warn(
        `RIDE-B-01: SOS access denied user=${req.user?._id} role=${req.user?.role} sos=${req.params.id} path=${req.originalUrl}`
      );
      return res.status(404).json({ message: 'Request not found' });
    }
    req.sosRequest = r;
    return next();
  } catch (err) {
    return next(err);
  }
};

// ─── POST /api/emergency-sos — legacy create (auto tiered dispatch) ───
router.post('/', protect, authorize('emergency:write'), bookingLimiter, async (req, res) => {
  try {
    const { reporterMode = 'self', patientDetails = {}, reporterOwnDetailsShared, reporterDetails, category = '', lat, lng, accuracy, address = '' } = req.body;
    if (lat === undefined || lng === undefined) return res.status(400).json({ message: 'lat/lng required' });
    if (reporterMode === 'self' && !patientDetails.gender && req.user.gender) {
      patientDetails.gender = String(req.user.gender).toLowerCase();
    }
    const doc = await EmergencyRequest.create({
      userId: req.user._id || req.user.id,
      reporterMode,
      patientDetails,
      reporterOwnDetailsShared: !!reporterOwnDetailsShared,
      reporterDetails: reporterDetails || {},
      category,
      location: { type: 'Point', coordinates: [Number(lng), Number(lat)], address, accuracy: accuracy != null ? Number(accuracy) : null },
      status: 'searching',
      requestMode: 'auto_select_ambulance',
      selectedVehicleTypes: ['ambulance'],
      autoBookEnabled: true,
      autoFindEnabled: true,
      startingRadiusKm: 5,
      currentSearchRadiusKm: 5,
      currentSearchPhase: 'ambulance',
    });
    // background dispatch, don't block response
    startAutoEscalateLoop(String(doc._id), [5, 10, 15, 20], 5).catch((e) => logger.error(`legacy create dispatch fail ${doc._id}: ${e.message}`));
    res.status(201).json({ emergency: { _id: doc._id, id: doc._id, status: doc.status, requestMode: doc.requestMode } });
  } catch (err) {
    logger.error(`SOS create error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── POST /api/emergency-sos/start — new 3-mode entry ───
// RIDE-B-13: `/start` was `protect`-only — no bookingLimiter, no permission and
// no "one active SOS" check, so a single account could script thousands of
// alerts, each fanning out notifications to every nearby provider (alert fatigue
// for real responders + dispatch/socket storms).
router.post('/start', protect, authorize('emergency:write', 'emergency:write:own'), bookingLimiter, async (req, res) => {
  try {
    const {
      requestMode = 'auto_select_ambulance',
      selectedVehicleTypes = [],
      autoBookEnabled = false,
      autoFindEnabled = false,
      startingRadiusKm = 5,
      reporterMode = 'self',
      patientDetails = {},
      reporterOwnDetailsShared,
      reporterDetails,
      category = '',
      lat, lng, accuracy, address = '',
    } = req.body;
    if (lat === undefined || lng === undefined) return res.status(400).json({ message: 'lat/lng required' });
    // Reject non-finite coordinates before they reach the geo queries.
    if (!Number.isFinite(Number(lat)) || !Number.isFinite(Number(lng))
      || Math.abs(Number(lat)) > 90 || Math.abs(Number(lng)) > 180) {
      return res.status(400).json({ message: 'Invalid lat/lng' });
    }
    // One ACTIVE SOS per user — a second concurrent alert is almost always a
    // double-tap or a script, not a second emergency.
    try {
      const active = await EmergencyRequest.findOne({
        userId: req.user._id || req.user.id,
        status: { $in: ['searching', 'assigned', 'en_route', 'picked_up'] },
      }).select('_id status');
      if (active) {
        return res.status(409).json({
          success: false,
          message: 'You already have an active emergency request',
          requestId: active._id,
          status: active.status,
        });
      }
    } catch { /* guard is best effort */ }
    if (requestMode === 'manual_select' && (!selectedVehicleTypes || !selectedVehicleTypes.length)) {
      return res.status(400).json({ message: 'Kam se kam ek vehicle type chuno' });
    }
    if (reporterMode === 'self' && !patientDetails.gender && req.user.gender) {
      patientDetails.gender = String(req.user.gender).toLowerCase();
    }
    let vehicleSettings = null;
    try { vehicleSettings = await SOSVehicleSettings.findOne().lean(); } catch {}
    const includeAmbInAuto = requestMode === 'auto_select_vehicle' && !!vehicleSettings?.includeAmbulanceInAutoVehicleMode;
    const request = await EmergencyRequest.create({
      userId: req.user._id || req.user.id,
      reporterMode,
      patientDetails,
      reporterOwnDetailsShared: !!reporterOwnDetailsShared,
      reporterDetails: reporterDetails || {},
      category,
      location: { type: 'Point', coordinates: [Number(lng), Number(lat)], address, accuracy: accuracy != null ? Number(accuracy) : null },
      status: 'searching',
      requestMode,
      selectedVehicleTypes: requestMode === 'manual_select' ? selectedVehicleTypes : requestMode === 'auto_select_ambulance' ? ['ambulance'] : (includeAmbInAuto ? ['auto', 'e_rickshaw', 'car', 'van', 'ambulance'] : ['auto', 'e_rickshaw', 'car', 'van']),
      autoBookEnabled: requestMode === 'auto_select_ambulance' ? true : !!autoBookEnabled,
      autoFindEnabled: !!autoFindEnabled,
      startingRadiusKm: Number(startingRadiusKm) || 5,
      currentSearchRadiusKm: Number(startingRadiusKm) || 5,
      currentSearchPhase: requestMode === 'auto_select_ambulance' ? 'ambulance' : 'vehicle',
    });

    const requestId = String(request._id);
    let settings = null;
    try { settings = await SOSVehicleSettings.findOne().lean(); } catch {}
    const radiusSteps = settings?.radiusSteps?.length ? settings.radiusSteps : [5, 10, 15, 20];
    const maxRetries = settings?.maxRetriesPerRadius ?? 3;
    const pauseMs = (settings?.retryPauseSeconds ?? 3) * 1000;

    // Fire-and-respond: searching UI shows immediately, waves run in background
    if (requestMode === 'auto_select_ambulance' && autoFindEnabled) {
      startAutoFindLoop(requestId, radiusSteps, maxRetries, pauseMs).catch((e) => logger.error(`autofind fail: ${e.message}`));
    } else if (requestMode === 'auto_select_vehicle' && autoFindEnabled) {
      startAutoFindLoop(requestId, radiusSteps, maxRetries, pauseMs).catch((e) => logger.error(`autofind fail: ${e.message}`));
    } else if (requestMode === 'auto_select_ambulance' || autoBookEnabled) {
      startAutoEscalateLoop(requestId, radiusSteps, request.startingRadiusKm).catch((e) => logger.error(`autobook fail: ${e.message}`));
    } else if (requestMode === 'manual_select') {
      startManualModeSearch(requestId, request.startingRadiusKm).catch((e) => logger.error(`manual search fail: ${e.message}`));
    } else {
      // auto_select_vehicle + autoBook OFF + autoFind OFF → patient khud choose karega;
      // legacy auto-assign dispatch kabhi nahi (mode violation hota)
      startManualModeSearch(requestId, request.startingRadiusKm).catch((e) => logger.error(`manual search fail: ${e.message}`));
    }

    res.status(201).json({ requestId, requestMode: request.requestMode, status: request.status, mode: requestMode, startingRadiusKm: request.startingRadiusKm });
  } catch (err) {
    logger.error(`SOS start error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── POST /api/emergency-sos/:id/book/:providerId ───
router.post('/:id/book/:providerId', protect, requireSosAccess, async (req, res) => {
  try {
    const result = await bookChosenProvider(req.params.id, req.params.providerId);
    if (result.error) return res.status(400).json({ message: result.error });
    res.json({ success: true, request: result.request });
  } catch (err) {
    logger.error(`SOS book error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── POST /api/emergency-sos/:id/search-again — same radius retry ───
router.post('/:id/search-again', protect, requireSosAccess, async (req, res) => {
  try {
    const cur = await EmergencyRequest.findById(req.params.id).select('currentSearchRadiusKm status');
    if (!cur) return res.status(404).json({ message: 'Request not found' });
    if (cur.status !== 'searching') return res.status(400).json({ message: 'Request not searching' });
    // Fire-and-forget: 30s HTTP block nahi. Result 'emergency_window_closed' socket event se aata hai.
    startManualModeSearch(req.params.id, cur.currentSearchRadiusKm || 5, { fresh: true })
      .catch((e) => logger.error(`search-again fail: ${e.message}`));
    res.json({ started: true, radiusKm: cur.currentSearchRadiusKm || 5 });
  } catch (err) {
    logger.error(`SOS search-again error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── POST /api/emergency-sos/:id/search-radius/:km ───
router.post('/:id/search-radius/:km', protect, async (req, res) => {
  try {
    const km = parseInt(req.params.km, 10);
    if (!km || km < 1 || km > 50) return res.status(400).json({ message: 'Invalid radius' });
    // RIDE-B-12: only the patient who raised the SOS (or a superadmin) may drive
    // the search radius — anyone could otherwise re-dispatch other patients'
    // emergencies and read the accepted-candidate list.
    const scope = req.user.role === 'superadmin' ? { _id: req.params.id } : { _id: req.params.id, userId: req.user._id };
    const cur = await EmergencyRequest.findOne(scope).select('status');
    if (!cur) return res.status(404).json({ message: 'Request not found' });
    if (cur.status !== 'searching') return res.status(400).json({ message: 'Request not searching' });
    startManualModeSearch(req.params.id, km).catch((e) => logger.error(`search-radius fail: ${e.message}`));
    res.json({ started: true, radiusKm: km });
  } catch (err) {
    logger.error(`SOS search-radius error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── GET /api/emergency-sos/:id/accepted-candidates ───
router.get('/:id/accepted-candidates', protect, requireSosAccess, async (req, res) => {
  try {
    // RIDE-B-15: same ownership rule — the candidate list reveals which doctors
    // /riders responded to a specific patient's SOS.
    const scope = req.user.role === 'superadmin' ? { _id: req.params.id } : { _id: req.params.id, userId: req.user._id };
    const r = await EmergencyRequest.findOne(scope).select('acceptances windowEndsAt userId');
    if (!r) return res.status(404).json({ message: 'Request not found' });
    const accepted = (r.acceptances || [])
      .filter((a) => !r.windowEndsAt || new Date(a.acceptedAt) <= new Date(r.windowEndsAt))
      .sort((a, b) => a.distanceKm - b.distanceKm);
    res.json({ accepted: accepted.map((a) => ({ providerId: a.providerId, providerType: a.providerType, distanceKm: a.distanceKm, userId: a.userId })) });
  } catch (err) {
    logger.error(`SOS accepted-candidates error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});


// ─── GET /api/emergency-sos/:id/status ───
router.get('/:id/status', protect, requireSosAccess, async (req, res) => {
  try {
    const request = await EmergencyRequest.findById(req.params.id).select(
      'status requestMode selectedVehicleTypes autoBookEnabled autoFindEnabled startingRadiusKm currentSearchRadiusKm currentSearchPhase dispatchLog notified acceptances windowEndsAt assignedProviderId assignedProviderType assignedVehicleType assignedHospitalId assignedAt selectedHospitalId userId'
    );
    if (!request) return res.status(404).json({ message: 'Request not found' });
    // RIDE-B-12: live dispatch state (who is assigned, the dispatch log, the
    // accepted candidates) is per-patient — do not serve it to any account.
    if (!(await canAccessSos(req, request))) {
      return res.status(403).json({ message: 'Not authorized to view this emergency request' });
    }
    res.json({
      status: request.status,
      requestMode: request.requestMode,
      selectedVehicleTypes: request.selectedVehicleTypes,
      autoBookEnabled: request.autoBookEnabled,
      autoFindEnabled: request.autoFindEnabled,
      startingRadiusKm: request.startingRadiusKm,
      currentSearchRadiusKm: request.currentSearchRadiusKm,
      currentSearchPhase: request.currentSearchPhase,
      dispatchLog: request.dispatchLog,
      notifiedCount: (request.notified || []).length,
      acceptancesCount: (request.acceptances || []).length,
      assigned: !!request.assignedProviderId,
      providerType: request.assignedProviderType,
      vehicleType: request.assignedVehicleType,
      hospital: request.assignedHospitalId ? String(request.assignedHospitalId) : null,
      assignedAt: request.assignedAt,
    });
  } catch (err) {
    logger.error(`SOS status error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── Legacy provider + patient endpoints (restored) ───
router.post('/:id/accept', protect, authorize('emergency:write'), async (req, res) => {
  try {
    const { providerType, providerId } = req.body;
    const out = await handleProviderAccept(req.params.id, providerId, providerType, req.user);
    if (out.status === 'accepted_pending') return res.json({ status: 'accepted_pending', windowEndsAt: out.windowEndsAt, distanceKm: out.distanceKm, success: true });
    if (out.status === 'too_late') return res.status(409).json({ status: 'too_late', message: out.message, success: false });
    if (out.status === 'not_eligible') return res.status(403).json({ status: 'not_eligible', message: out.message, success: false });
    return res.status(400).json({ ...out, success: false });
  } catch (err) {
    logger.error(`SOS accept error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

router.post('/:id/reject', protect, authorize('emergency:write'), async (req, res) => {
  try {
    // RIDE-B-12: a provider may only reject on its OWN behalf. The identity
    // comes from the session — a body `providerId` let any provider blacklist
    // its competitors out of a patient's dispatch pool.
    await EmergencyRequest.updateOne(
      { _id: req.params.id, status: 'searching' },
      { $addToSet: { rejections: String(req.user._id || req.user.id) } }
    );
    res.json({ success: true });
  } catch (err) {
    logger.error(`SOS reject error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

router.post('/:id/cancel', protect, requireSosAccess, async (req, res) => {
  try {
    const r = await EmergencyRequest.findById(req.params.id).select('userId status notified assignedProviderType assignedProviderId');
    if (!r) return res.status(404).json({ message: 'Request not found' });
    const isOwner = String(r.userId) === String(req.user._id || req.user.id);
    if (!isOwner && req.user.role !== 'superadmin') {
      return res.status(403).json({ message: 'Sirf request karne wala cancel kar sakta hai' });
    }
    if (!['searching', 'assigned', 'en_route'].includes(r.status)) {
      return res.json({ success: true, already: r.status });
    }
    // updateOne (save nahi) — purane docs pe full-validation 500 se bachne ke liye
    await EmergencyRequest.updateOne(
      { _id: r._id },
      { $set: { status: 'cancelled_by_user', cancelledAt: new Date(), updatedAt: new Date() } }
    );
    const io = getIO();
    if (io) {
      io.to(`emergency:${r._id}`).emit('emergency_cancelled', { requestId: String(r._id) });
      (r.notified || []).forEach((n) => io.to(`user:${n.userId}`).emit('emergency_closed', { requestId: String(r._id) }));
    }
    // free ambulance if assigned
    if (r.assignedProviderType === 'ambulance' && r.assignedProviderId) {
      await Ambulance.findByIdAndUpdate(r.assignedProviderId, { isOnDuty: false, currentEmergencyId: null }).catch(() => {});
    }
    res.json({ success: true });
  } catch (err) {
    logger.error(`SOS cancel error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

router.put('/:id/complete', protect, authorize('emergency:write'), async (req, res) => {
  try {
    const r = await EmergencyRequest.findById(req.params.id);
    if (!r) return res.status(404).json({ message: 'Request not found' });
    // RIDE-B-11: closing a live SOS frees the assigned ambulance, so it must be
    // the assigned provider, the patient, or a superadmin — `emergency:write` is
    // held by many roles and was the only gate.
    if (!(await canAccessSos(req, r))) {
      return res.status(403).json({ message: 'Not authorized to complete this emergency request' });
    }
    if (['completed', 'cancelled_by_user'].includes(r.status)) {
      return res.json({ success: true, already: r.status });
    }
    r.status = 'completed';
    r.completedAt = new Date();
    await r.save();
    if (r.assignedProviderType === 'ambulance' && r.assignedProviderId) {
      await Ambulance.findByIdAndUpdate(r.assignedProviderId, { isOnDuty: false, currentEmergencyId: null }).catch(() => {});
    }
    const io = getIO();
    if (io) io.to(`emergency:${r._id}`).emit('emergency_completed', { requestId: String(r._id) });
    try {
      const noteUserId = r.assignedProviderType === 'ambulance'
        ? (await Ambulance.findById(r.assignedProviderId).select('userId').lean())?.userId
        : r.assignedProviderId;
      if (noteUserId) {
        const Notification = (await import('../models/Notification.js')).default;
        await Notification.create({
          title: 'Job Completed',
          message: `Job complete ho gaya — ${r.patientDetails?.name || 'Patient'}`,
          type: 'system',
          userId: String(noteUserId),
        });
      }
    } catch {}
    res.json({ success: true });
  } catch (err) {
    logger.error(`SOS complete error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

router.get('/:id/nearby-hospitals', protect, requireSosAccess, async (req, res) => {
  try {
    const r = await EmergencyRequest.findById(req.params.id).select('location');
    if (!r) return res.status(404).json({ message: 'Request not found' });
    const [lng, lat] = r.location.coordinates;
    const hospitals = await Hospital.aggregate([
      { $geoNear: { near: { type: 'Point', coordinates: [Number(lng), Number(lat)] }, key: 'location.coordinates', distanceField: 'distanceMeters', maxDistance: 20000, spherical: true, query: { status: 'approved' } } },
      { $limit: 10 },
      { $project: { name: 1, address: 1, phone: 1, location: 1, distanceMeters: 1 } },
    ]).catch(() => []);
    res.json({ hospitals });
  } catch (err) {
    logger.error(`SOS nearby-hospitals error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

router.put('/:id/select-hospital', protect, authorize('emergency:write'), async (req, res) => {
  try {
    const out = await selectDestinationHospital(req.params.id, req.body.hospitalId);
    if (out.status !== 'success') return res.status(400).json({ message: 'Could not set hospital' });
    res.json({ success: true, hospital: out.hospital });
  } catch (err) {
    logger.error(`SOS select-hospital error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── PUT /api/emergency-sos/:id/progress — provider updates job stage ───
router.put('/:id/progress', protect, requireSosAccess, async (req, res) => {
  try {
    const { stage } = req.body;
    const valid = ['reached_pickup', 'heading_to_hospital', 'reached_hospital'];
    if (!valid.includes(stage)) return res.status(400).json({ message: 'Invalid stage' });

    const request = await EmergencyRequest.findById(req.params.id);
    if (!request) return res.status(404).json({ message: 'Request not found' });
    if (!['assigned', 'en_route'].includes(request.status)) {
      return res.status(400).json({ message: 'Job is not active' });
    }

    // Ownership: rider → assignedProviderId is userId; ambulance → check Ambulance.userId
    let allowed = false;
    if (request.assignedProviderType === 'ambulance') {
      const amb = await Ambulance.findById(request.assignedProviderId).select('userId').lean();
      allowed = !!amb && String(amb.userId) === String(req.user._id || req.user.id);
    } else {
      allowed = String(request.assignedProviderId) === String(req.user._id || req.user.id);
    }
    if (!allowed) return res.status(403).json({ message: 'Access denied' });

    request.progressStage = stage;
    request.progressLog.push({ stage, at: new Date() });
    if (stage === 'heading_to_hospital') request.status = 'en_route';
    await request.save();

    const io = getIO();
    if (io) {
      io.to(`emergency:${request._id}`).emit('emergency_progress', {
        requestId: String(request._id),
        stage,
        at: new Date(),
      });
    }
    try {
      const noteUserId = request.assignedProviderType === 'ambulance'
        ? (await Ambulance.findById(request.assignedProviderId).select('userId').lean())?.userId
        : request.assignedProviderId;
      if (noteUserId) {
        const Notification = (await import('../models/Notification.js')).default;
        await Notification.create({
          title: 'Job Progress Updated',
          message: `Stage: ${stage.replace(/_/g, ' ')}`,
          type: 'sos',
          userId: String(noteUserId),
          // NOTIF-B-05: SOS alerts are critical (never rate-capped/quiet-suppressed)
          // and de-duplicated per SOS + stage.
          priority: 'critical',
          dedupKey: `sos_stage:${request._id}:${stage}`,
        });
      }
    } catch {}
    res.json({ success: true, progressStage: request.progressStage });
  } catch (err) {
    logger.error(`SOS progress error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── GET /api/emergency-sos/debug/eligible-providers (admin diagnostic) ───
router.get('/debug/eligible-providers', protect, authorize('emergency:read'), async (req, res) => {
  try {
    // RIDE-B-02: this enumerates every nearby provider's id and live location.
    // In production it is not a diagnostic, it is a dispatch fingerprint: knowing
    // which drivers are near a coordinate tells an attacker who is on duty and where.
    // It now answers 404 in production so the route is not even discoverable.
    if (process.env.NODE_ENV === 'production') {
      logger.warn('RIDE-B-02: /debug/eligible-providers accessed in production by ' + req.user?.id);
      return res.status(404).json({ message: 'Not found' });
    }
    if (!['superadmin', 'hospital_admin'].includes(req.user.role)) {
      return res.status(403).json({ message: 'Access denied' });
    }
    const { lat, lng, radiusKm = 10 } = req.query;
    if (!lat || !lng) return res.status(400).json({ message: 'lat/lng required' });

    const [ambulances, vehicles] = await Promise.all([
      findEligibleAmbulances(Number(lng), Number(lat), Number(radiusKm), []),
      findEligibleEmergencyVehicles(Number(lng), Number(lat), Number(radiusKm), []),
    ]);
    const [totalRiders, onlineRiders, esRiders] = await Promise.all([
      RiderProfile.countDocuments({}),
      RiderProfile.countDocuments({ isOnline: true }),
      RiderProfile.countDocuments({ isOnline: true, emergencySupport: true }),
    ]);
    const [totalAmb, onlineAmb, esAmb] = await Promise.all([
      Ambulance.countDocuments({}),
      Ambulance.countDocuments({ isOnline: true }),
      Ambulance.countDocuments({ isOnline: true, emergencySupport: true }),
    ]);

    res.json({
      eligibleNow: { ambulances: ambulances.length, vehicles: vehicles.length },
      funnelRiders: { total: totalRiders, online: onlineRiders, onlineAndEmergencySupport: esRiders },
      funnelAmbulances: { total: totalAmb, online: onlineAmb, onlineAndEmergencySupport: esAmb },
    });
  } catch (err) {
    logger.error(`SOS eligible-providers error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── GET /api/emergency-sos/:id/diagnostics (owner/admin snapshot) ───
router.get('/:id/diagnostics', protect, authorize('emergency:read'), async (req, res) => {
  try {
    const r = await EmergencyRequest.findById(req.params.id).lean();
    if (!r) return res.status(404).json({ message: 'Not found' });
    if (String(r.userId) !== String(req.user._id || req.user.id) && !['superadmin', 'hospital_admin'].includes(req.user.role)) {
      return res.status(403).json({ message: 'Access denied' });
    }
    res.json({
      status: r.status,
      requestMode: r.requestMode,
      selectedVehicleTypes: r.selectedVehicleTypes,
      currentSearchRadiusKm: r.currentSearchRadiusKm,
      currentSearchPhase: r.currentSearchPhase,
      dispatchLog: r.dispatchLog || [],
      notifiedCount: (r.notified || []).length,
      acceptancesCount: (r.acceptances || []).length,
      windowEndsAt: r.windowEndsAt,
    });
  } catch (err) {
    logger.error(`SOS diagnostics error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

// ─── GET /api/emergency-sos/:id (keep last — :id catch-all) ───
router.get('/:id', protect, authorize('emergency:read'), async (req, res) => {
  try {
    const em = await EmergencyRequest.findById(req.params.id).lean();
    if (!em) return res.status(404).json({ message: 'Request not found' });

    const isAdmin = req.user.role === 'superadmin' || req.user.role === 'hospital_admin';
    const isRequester = em.userId?.toString() === req.user._id.toString();
    if (!isAdmin && !isRequester) {
      return res.status(403).json({ message: 'Not authorized to view this emergency request' });
    }

    res.json({ emergency: em });
  } catch (err) {
    logger.error(`SOS get error: ${err.message}`);
    res.status(500).json({ message: err.message });
  }
});

export default router;

import express from 'express';
import Event from '../models/Event.js';
import EventRegistration from '../models/EventRegistration.js';
import Provider from '../models/Provider.js';
import Refund from '../models/Refund.js';
import { authorizeObject } from '../middleware/authorize.js';
import { auditLog } from '../middleware/audit.js';
import { publicSearchLimiter, bookingLimiter } from '../middleware/rateLimit.js';
import { idempotencyGuard } from '../middleware/idempotency.js';
import { randomId } from '../utils/secureRandom.js';
import { verifiedPaymentFor } from '../services/paymentVerification.js';
import {
  validate, createEventSchema, updateEventSchema, eventActionSchema,
  registerEventSchema, cancelRegistrationSchema, checkInSchema,
} from '../utils/validate.js';
import { protect } from '../middleware/auth.js';
import {
  EVENT_STATUS, EVENT_TRANSITIONS, REGISTRATION_STATUS, REGISTRATION_TRANSITIONS,
  canTransition,
} from '../lib/flowStates.js';

// FLOW-E (5.md 6) - event registration: camps, workshops, drives, retreats.
//
//   Event:        draft -> open -> cancelled | ended
//   Registration: REGISTERED -> CHECKED_IN | CANCELLED | REFUNDED
//
// Three rules carry the flow:
//   1. SEATS are claimed with a compare-and-set on the counter
//      (`$expr: { $lt: ['$registeredCount', '$capacity'] }`), the same shape
//      slotCapacity.js uses. `count(documents) < capacity` as two statements is
//      how two people both get the last seat (5.md 13).
//   2. ONE registration per person, enforced by a UNIQUE index on
//      (eventId, userId), not by a pre-read that only narrows the race.
//   3. CANCELLATION refund rule: cancel before the cut-off and the money goes
//      back through the existing Refund state machine; after it (or when
//      nothing was paid) the registration is CANCELLED. The two outcomes are
//      separate STATES, so "was this refunded?" never needs a second field.

const router = express.Router();

const OBJECT_ID = /^[0-9a-f]{24}$/i;

const actorId = (req) => req.user._id ?? req.user.id;

const denyTransition = (res, from, to) => res.status(409).json({
  message: `Cannot move from ${from} to ${to}`, code: 'ILLEGAL_STATE_TRANSITION', from, to,
});

const slugify = (title) => String(title)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 60);

/**
 * Claim ONE seat.
 *
 * Deliberately a single guarded update: the filter contains the capacity
 * condition, so Mongo evaluates and applies it atomically and only one of two
 * racing registrations can match. Returns null for "full", "not open" or
 * "gone" — the caller reads once to tell them apart, which is safe because the
 * read is only for the ERROR, never for the decision to write.
 */
const claimSeat = (event) => Event.findOneAndUpdate(
  {
    _id: event._id,
    status: EVENT_STATUS.OPEN,
    $expr: { $lt: ['$registeredCount', '$capacity'] },
  },
  { $inc: { registeredCount: 1 } },
  { new: true },
);

/** Compensating action: the seat goes back if the registration could not be written. */
const releaseSeat = (eventId) => Event.updateOne(
  { _id: eventId, registeredCount: { $gt: 0 } },
  { $inc: { registeredCount: -1 } },
);

/**
 * The payment rule now lives in services/paymentVerification.js, shared with
 * the membership purchase (5.md Flow D): same owner/status/amount checks, one
 * source, so the two paid flows cannot drift.
 */

/**
 * The existing refund service, as payments.js uses it: request (idempotent on
 * idempotencyKey) then settle (CAS on the payment). Both are wrapped because
 * neither can be assumed reachable — no payment id, a production gateway that
 * refuses to move money (PAY-B-08), or a concurrent settle. The CALLER then
 * decides the resulting registration state, so a refund that did not happen
 * never reports as REFUNDED.
 */
const issueRefund = async ({ paymentId, amount, reason, requestedBy, idempotencyKey }) => {
  if (!paymentId) return { ok: false, reason: 'no-payment' };
  if (process.env.NODE_ENV === 'production') return { ok: false, reason: 'provider-unavailable' };
  try {
    const { refund, created } = await Refund.requestRefund({
      paymentId,
      amount,
      originalAmount: amount,
      reason,
      reasonCode: 'service_not_delivered',
      idempotencyKey,
      requestedBy,
    });
    if (!created) return { ok: true, refund, duplicate: true };
    try {
      const settle = await Refund.settleRefund({ paymentId, amount });
      refund.status = settle.status;
      refund.settledAt = new Date();
      await refund.save();
      return { ok: true, refund };
    } catch (settleErr) {
      refund.status = 'FAILED';
      refund.failureReason = settleErr.message;
      await refund.save();
      return { ok: false, reason: settleErr.message, refund };
    }
  } catch (err) {
    return { ok: false, reason: err.message };
  }
};

// authz: public
//
// The public catalogue of what is on. Drafts and cancelled events are not
// listed, and nothing here joins attendee data — an event's registration rows
// are a different collection on purpose.
router.get('/', publicSearchLimiter, async (req, res) => {
  try {
    const filter = { status: { $in: [EVENT_STATUS.OPEN, EVENT_STATUS.ENDED] } };
    if (req.query.type) filter.type = String(req.query.type);
    if (req.query.city) filter['venue.city'] = String(req.query.city);
    if (req.query.upcoming !== 'false') filter['schedule.start'] = { $gte: new Date() };

    const limit = Math.min(Math.max(Number.parseInt(String(req.query.limit ?? 20), 10) || 20, 1), 100);
    const page = Math.max(Number.parseInt(String(req.query.page ?? 1), 10) || 1, 1);
    const [events, total] = await Promise.all([
      Event.find(filter)
        .select('-outcomeReport -__v')
        .sort({ 'schedule.start': 1 })
        .skip((page - 1) * limit)
        .limit(limit)
        .lean(),
      Event.countDocuments(filter),
    ]);
    return res.json({ events, total, page, pages: Math.ceil(total / limit) || 1, limit });
  } catch (err) {
    return res.status(500).json({ message: err.message });
  }
});

// authz: object
//
// Creating an event names an ORGANISER, and the guard proves the caller owns
// that provider (authorizeObject on ownerUserId) — the same shape as creating
// a service on a listing. `req.scoped` is the provider, so the kind check runs
// on the loaded row rather than on a client claim.
router.post('/', protect, bookingLimiter, validate(createEventSchema), authorizeObject({
  model: Provider,
  idFrom: (req) => req.body.organizerId,
  ownerField: 'ownerUserId',
  actorRoles: [],
  write: true,
}), async (req, res) => {
  try {
    const organizer = req.scoped;
    if (!['organizer', 'facility', 'practitioner', 'vendor'].includes(organizer.kind)) {
      return res.status(409).json({ message: 'Provider kind cannot organise events', code: 'NOT_AN_ORGANIZER' });
    }
    const { organizerId, ...data } = req.body;
    const event = await Event.create({
      ...data,
      organizerId,
      status: EVENT_STATUS.DRAFT,
      registeredCount: 0,
      slug: `${slugify(data.title)}-${randomId('', 6).toLowerCase()}`,
    });
    await auditLog('event_created', actorId(req), {
      eventId: event._id, organizerId, type: event.type, ip: req.ip, userAgent: req.get('user-agent'),
    });
    return res.status(201).json(event);
  } catch (err) {
    if (err?.code === 11000) return res.status(409).json({ message: 'Event slug already exists', code: 'DUPLICATE_SLUG' });
    return res.status(400).json({ message: err.message });
  }
});

// authz: public
//
// Published events are public: id or slug. Drafts and cancelled events are
// hidden from everyone except the organiser's own workspace, and the lookup
// answers 404 either way so the endpoint is not an existence oracle.
router.get('/:id', publicSearchLimiter, async (req, res) => {
  try {
    const filter = OBJECT_ID.test(String(req.params.id))
      ? { _id: req.params.id }
      : { slug: String(req.params.id).toLowerCase() };
    filter.status = { $in: [EVENT_STATUS.OPEN, EVENT_STATUS.ENDED] };
    const event = await Event.findOne(filter).lean();
    if (!event) return res.status(404).json({ message: 'Not found' });
    return res.json(event);
  } catch (err) {
    return res.status(500).json({ message: err.message });
  }
});

// authz: object
router.patch('/:id', protect, validate(updateEventSchema), authorizeObject({
  model: Event,
  idFrom: (req) => req.params.id,
  ownerLoader: async (doc) => {
    const provider = await Provider.findById(doc.organizerId);
    return provider?.ownerUserId ?? null;
  },
  actorRoles: [],
  write: true,
}), async (req, res) => {
  try {
    const event = req.scoped;
    // An event with attendees is a contract: the schedule and the fee cannot be
    // rewritten under people who already registered.
    if (event.registeredCount > 0 && ('fee' in req.body || 'capacity' in req.body)) {
      return res.status(409).json({ message: 'Fee and capacity are locked once registrations exist', code: 'EVENT_LOCKED' });
    }
    Object.assign(event, req.body);
    await event.save();
    await auditLog('event_updated', actorId(req), { eventId: event._id, ip: req.ip });
    return res.json(event);
  } catch (err) {
    return res.status(400).json({ message: err.message });
  }
});

// authz: object
router.post('/:id/publish', protect, validate(eventActionSchema), authorizeObject({
  model: Event,
  idFrom: (req) => req.params.id,
  ownerLoader: async (doc) => {
    const provider = await Provider.findById(doc.organizerId);
    return provider?.ownerUserId ?? null;
  },
  actorRoles: [],
  write: true,
}), async (req, res) => {
  try {
    const current = req.scoped;
    if (!canTransition(EVENT_TRANSITIONS, current.status, EVENT_STATUS.OPEN)) {
      return denyTransition(res, current.status, EVENT_STATUS.OPEN);
    }
    const event = await Event.findOneAndUpdate(
      { _id: current._id, status: EVENT_STATUS.DRAFT },
      { $set: { status: EVENT_STATUS.OPEN, publishedAt: new Date() } },
      { new: true },
    );
    if (!event) return denyTransition(res, current.status, EVENT_STATUS.OPEN);
    await auditLog('event_published', actorId(req), { eventId: event._id, ip: req.ip });
    return res.json(event);
  } catch (err) {
    return res.status(400).json({ message: err.message });
  }
});

// authz: object
//
// Cancelling an event is a mass action: every live registration has to be
// settled, not just the event row. Each one runs the refund rule and its
// outcome is recorded on the registration (REFUNDED vs CANCELLED), so the
// organiser's report and the ledger agree.
router.post('/:id/cancel', protect, validate(eventActionSchema), authorizeObject({
  model: Event,
  idFrom: (req) => req.params.id,
  ownerLoader: async (doc) => {
    const provider = await Provider.findById(doc.organizerId);
    return provider?.ownerUserId ?? null;
  },
  actorRoles: [],
  write: true,
}), async (req, res) => {
  try {
    const current = req.scoped;
    if (!canTransition(EVENT_TRANSITIONS, current.status, EVENT_STATUS.CANCELLED)) {
      return denyTransition(res, current.status, EVENT_STATUS.CANCELLED);
    }
    const event = await Event.findOneAndUpdate(
      { _id: current._id, status: { $in: [EVENT_STATUS.DRAFT, EVENT_STATUS.OPEN] } },
      { $set: { status: EVENT_STATUS.CANCELLED, cancelledAt: new Date(), cancelReason: req.body.reason ?? 'Cancelled by organiser' } },
      { new: true },
    );
    if (!event) return denyTransition(res, current.status, EVENT_STATUS.CANCELLED);

    const live = await EventRegistration.find({
      eventId: event._id,
      status: REGISTRATION_STATUS.REGISTERED,
    }).lean();

    const settled = [];
    for (const reg of live) {
      const refund = await issueRefund({
        paymentId: reg.paymentId,
        amount: reg.feeAmount,
        reason: `Event cancelled: ${event.cancelReason}`.slice(0, 500),
        requestedBy: actorId(req),
        idempotencyKey: `event-cancel:${reg._id}`,
      });
      const status = refund.ok ? REGISTRATION_STATUS.REFUNDED : REGISTRATION_STATUS.CANCELLED;
      await EventRegistration.updateOne(
        { _id: reg._id, status: REGISTRATION_STATUS.REGISTERED },
        {
          $set: {
            status,
            cancelledAt: new Date(),
            cancelReason: 'Event cancelled by organiser',
            ...(refund.ok ? { refundedAt: new Date(), refundId: refund.refund?._id ?? null } : {}),
          },
        },
      );
      settled.push({ registrationId: reg._id, status, refund: refund.ok ? true : false, refundReason: refund.reason });
    }
    if (live.length) await releaseSeat(event._id);

    await auditLog('event_cancelled', actorId(req), {
      eventId: event._id, registrations: live.length, refunded: settled.filter((s) => s.status === REGISTRATION_STATUS.REFUNDED).length,
      ip: req.ip, userAgent: req.get('user-agent'),
    });
    return res.json({ event, settled });
  } catch (err) {
    return res.status(400).json({ message: err.message });
  }
});

//
// The attendee registers THEMSELVES: userId comes from the session, the fee
// comes from the event row, and the seat is claimed by the atomic CAS before
// anything is written. A paid event also requires a payment the server can
// verify (owner + status + amount) - the body only names it.
// authz: self
router.post('/:id/register', protect, bookingLimiter, idempotencyGuard({ prefix: 'event-register' }), validate(registerEventSchema), async (req, res) => {
  try {
    const event = await Event.findById(req.params.id).lean();
    if (!event) return res.status(404).json({ message: 'Not found' });
    if (!canTransition(EVENT_TRANSITIONS, event.status, event.status) || event.status !== EVENT_STATUS.OPEN) {
      return res.status(409).json({ message: 'Event is not open for registration', code: 'EVENT_NOT_OPEN' });
    }

    const feeAmount = event.fee?.amount ?? 0;
    let payment = null;
    if (feeAmount > 0) {
      if (!req.body.paymentId) {
        return res.status(402).json({ message: 'Payment is required for this event', code: 'PAYMENT_REQUIRED' });
      }
      payment = await verifiedPaymentFor(req.body.paymentId, actorId(req), feeAmount);
      if (!payment) {
        return res.status(402).json({ message: 'Payment could not be verified for this event', code: 'PAYMENT_NOT_VERIFIED' });
      }
    }

    const claimed = await claimSeat(event);
    if (!claimed) {
      const again = await Event.findById(req.params.id).lean();
      if (!again) return res.status(404).json({ message: 'Not found' });
      if (again.status !== EVENT_STATUS.OPEN) {
        return res.status(409).json({ message: 'Event is not open for registration', code: 'EVENT_NOT_OPEN' });
      }
      return res.status(409).json({ message: 'No seats left', code: 'SEATS_FULL', capacity: again.capacity });
    }

    try {
      const registration = await EventRegistration.create({
        eventId: event._id,
        userId: actorId(req),
        status: REGISTRATION_STATUS.REGISTERED,
        feeAmount,
        currency: event.fee?.currency ?? 'INR',
        paymentId: payment?._id ?? null,
        // Attribution triple for organiser impact reports (optional,
        // schema-bounded, never PII).
        attribution: {
          source: req.body.attribution?.source || '',
          medium: req.body.attribution?.medium || '',
          campaign: req.body.attribution?.campaign || '',
        },
        // Server-minted. This is the string the ticket's QR encodes; the
        // client has no say in it and cannot mint one for somebody else.
        checkInCode: randomId('', 8).toLowerCase(),
        consentGivenAt: req.body.consentGiven ? new Date() : null,
      });
      await auditLog('event_registered', actorId(req), {
        eventId: event._id, registrationId: registration._id, feeAmount, ip: req.ip,
        userAgent: req.get('user-agent'),
      });
      return res.status(201).json(registration);
    } catch (err) {
      // The seat was claimed for a registration that did not happen: give it
      // back before reporting, or the event drifts toward looking full.
      await releaseSeat(event._id);
      if (err?.code === 11000) {
        return res.status(409).json({ message: 'Already registered for this event', code: 'DUPLICATE_REGISTRATION' });
      }
      return res.status(400).json({ message: err.message });
    }
  } catch (err) {
    return res.status(500).json({ message: err.message });
  }
});

// authz: object
//
// The organiser's attendee list. Deliberately does NOT join the User document:
// 5.md 6 asks for a MASKED list, so the rows carry ids and states and nothing
// that identifies a person to whoever is reading the sheet.
router.get('/:id/registrations', protect, authorizeObject({
  model: Event,
  idFrom: (req) => req.params.id,
  ownerLoader: async (doc) => {
    const provider = await Provider.findById(doc.organizerId);
    return provider?.ownerUserId ?? null;
  },
  actorRoles: [],
  read: true,
}), async (req, res) => {
  try {
