const router = express.Router();

// ─── GET /api/facilities/nearby?type=clinic&lat=&lng=&radiusKm= ─────────────
// Spec expansion-01 (clinic discovery): approved facilities near a point with
// distance + H3 res-7 cell. Public — powers "clinics near me" discovery.
router.get('/nearby', async (req, res) => {
  try {
    const type = String(req.query.type || 'clinic');
    const lat = Number(req.query.lat);
    const lng = Number(req.query.lng);
    const radiusKm = Math.min(50, Math.max(1, Number(req.query.radiusKm) || 7));
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
      return res.status(400).json({ message: 'lat and lng required' });
    }
    const facilities = await Facility.find({
      type,
      status: 'approved',
      location: { $geoWithin: { $centerSphere: [[lng, lat], radiusKm / 6371] } },
    }).select('name address city phone rating specialties emergencySupport location').lean();

    const out = [];
    for (const f of facilities) {
      const coords = f.location?.coordinates;
      if (!coords || coords.length < 2) continue;
      const distanceKm = Math.round(calculateDistanceKm(lat, lng, coords[1], coords[0]) * 10) / 10;
      if (distanceKm > radiusKm) continue;
      out.push({
        facilityId: f._id,
        name: f.name,
        type: f.type,
        address: f.address,
        city: f.city,
        phone: f.phone,
        rating: f.rating,
        specialties: f.specialties || [],
        emergencySupport: Boolean(f.emergencySupport),
        distanceKm,
        h3Index7: latLngToCell(coords[1], coords[0], 7),
      });
    }
    out.sort((a, b) => a.distanceKm - b.distanceKm);
    res.json({ success: true, type, radiusKm, facilities: out });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.get('/', async (req, res) => {
  try {
    const {
      search, city, type, status,
      ownership, scheme, system, subType,
      accreditation, emergency24x7, homeVisit,
      wheelchair, verified, specialty, openNow,
    } = req.query;
    const filter = {};
    if (type && type !== 'All') filter.type = type;

    if (status && req.headers.authorization) {
      try {
        const token = req.headers.authorization.split(' ')[1];
        const decoded = verifyAccessToken(token);
        const user = await User.findById(decoded.id).select('role status isVerified');
        if (user && user.role === 'superadmin' && user.status !== 'blocked' && user.isVerified) {
          filter.status = status;
        } else filter.status = 'approved';
      } catch { filter.status = 'approved'; }
    } else filter.status = 'approved';

    if (search) filter.$or = [
      { name: new RegExp(escapeRegex(capSearch(search)), 'i') },
      { city: new RegExp(escapeRegex(capSearch(search)), 'i') },
      { description: new RegExp(escapeRegex(capSearch(search)), 'i') },
    ];
    if (city) filter.city = new RegExp(escapeRegex(capSearch(city)), 'i');

    // B4 Search facets (rolesmd/subcatogary.md §1 & Part B)
    if (ownership) filter.ownership = String(ownership).toLowerCase();
    if (scheme) filter.schemesAccepted = { $in: [String(scheme).toLowerCase()] };
    if (system) filter.systemOfMedicine = String(system).toLowerCase();
    if (subType) filter.subType = String(subType).toLowerCase();
    if (accreditation) {
      filter.accreditations = { $in: [new RegExp(escapeRegex(String(accreditation)), 'i')] };
    }
    if (emergency24x7 === 'true' || emergency24x7 === true || emergency24x7 === '1') {
      filter.emergency24x7 = true;
    }
    if (homeVisit === 'true' || homeVisit === true || homeVisit === '1') {
      filter.$or = [
        ...(filter.$or ? [filter.$or] : []),
        { appointmentModes: { $in: ['home_visit', 'home'] } },
        { 'amenities.homeVisit': true },
      ];
    }
    if (wheelchair === 'true' || wheelchair === true || wheelchair === '1') {
      filter['amenities.wheelchairAccess'] = true;
    }
    if (specialty) {
      const { specialtyPattern } = await import('../lib/taxonomy.js');
      const pattern = specialtyPattern(specialty);
      if (pattern) {
        filter.specialties = pattern;
      } else {
        filter.specialties = new RegExp(escapeRegex(String(specialty)), 'i');
      }
    }
    if (openNow === 'true' || openNow === true || openNow === '1') {
      // Calculate current IST day and check timing
      const now = new Date();
      const utcTime = now.getTime() + (now.getTimezoneOffset() * 60000);
      const istTime = new Date(utcTime + (3600000 * 5.5));
      const days = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
      const currentDay = days[istTime.getDay()];
      filter[`timing.${currentDay}`] = { $nin: ['Closed', 'closed', '', null] };
    }

    const { page, limit } = req.query;
    const result = await paginatedResults(Facility, filter, { page, limit, sort: { createdAt: -1 } });
    res.json(result);
  } catch (err) { res.status(500).json({ message: err.message }); }
});

