      role: roleMap[type] || 'hospital_admin', phone: adminPhone || '',
      facilityId: facility._id, facilityType: type,
      isVerified: false, status: 'active', approvalStatus: 'not_required',
    });

    try {
      await License.create({
        facilityId: facility._id,
        facilityType: type,
        licenseNumber: licenseNumber || '',
        issuedDate: new Date(),
        expiryDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000),
        status: 'active',
      });
    } catch (licenseErr) {
      logger.error('License creation failed:', licenseErr.message);
    }
    await auditLog('register_facility', null, { facilityId: facility._id, type, name });

    try {
      await sendEmail({
        to: adminEmail,
        subject: `FindMedi - ${type} registration received`,
        html: `<h2>Registration Received</h2><p>Dear ${adminName},</p><p>Your ${type} <strong>${name}</strong> has been registered on FindMedi. Our team will review and approve it within 24-48 hours.</p><p>You will receive a notification once approved.</p>`,
      });
    } catch (emailErr) {
      logger.error('Facility registration confirmation email failed:', emailErr.message);
    }

    res.status(201).json({ message: `${type} registered successfully. Awaiting approval.`, facilityId: facility._id });
  } catch (err) { res.status(400).json({ message: err.message }); }
});

