    return res.json({ resourceType: 'Bundle', type: 'searchset', total: out.length, entry: out.map((o) => ({ resource: o })) });
  } catch (err) { return res.status(500).json({ message: err.message }); }
});

// GET /fhir/Procedure?patient=:id (OT surgeries)
