// ─── POST /api/lawyer-booking/:id/complete ─────────────────────────────────
// Lawyer marks consultation as completed + final summary note
router.post('/:id/complete', protect, authorize('legal:write'), async (req, res) => {
  try {
    let booking = await assertBookingAccess(req, req.params.id, 'complete');
    if (!booking) {
      return res.status(404).json({ message: 'Booking not found' });
    }

    if (String(booking.lawyerId) !== String(req.user._id)) {
      return res.status(403).json({ message: 'Only the assigned advocate can complete consultation' });
    }

    const session = await mongoose.startSession();
    let settledAmount = 0;
    let completed;
    try {
      session.startTransaction({ readConcern: { level: 'snapshot' }, writeConcern: { w: 'majority' } });
      completed = await LawyerBooking.findOneAndUpdate(
        { _id: booking._id, lawyerId: req.user._id, status: { $in: ['confirmed', 'in_progress'] }, settledAt: null },
        {
          $set: { status: 'completed', completedAt: new Date(), finalCaseSummary: req.body.finalCaseSummary || 'Consultation session completed.', settledAt: new Date() },
          $push: { statusHistory: { status: 'completed', at: new Date(), note: 'Consultation concluded' } },
        },
        { new: true, session }
      );
      if (!completed) {
        await session.abortTransaction();
        const latest = await LawyerBooking.findById(booking._id).select('status settledAt').lean();
        return res.status(latest?.status === 'completed' ? 200 : 409).json({
          success: latest?.status === 'completed',
          message: latest?.status === 'completed' ? 'Consultation was already completed' : 'Booking is not in a completable state',
          booking: latest?.status === 'completed' ? latest : undefined,
        });
      }
      const gross = Number(completed.fee) || 0;
      if (gross > 0) {
        const settlement = await recordServiceSettlement({
          source: 'lawyer', sourceId: String(completed._id), bookingNumber: completed.bookingNumber || '',
          userId: completed.userId, providerId: completed.lawyerId,
          totalAmount: gross, session,
        });
        settledAmount = settlement.netAmount;
        completed.settlementAmount = settledAmount;
        await completed.save({ session });
      }
      const recipientId = String(completed.userId?._id || completed.userId);
      const bookingId = String(completed._id);
      const completedAt = completed.completedAt || new Date();
      await Notification.create([{
        userId: recipientId,
        title: 'Consultation completed',
        message: 'Your consultation is complete. Open FindMedi to review the case summary and payment status.',
        type: 'lawyer',
        referenceId: bookingId,
        dedupKey: `lawyer-booking-completed:${bookingId}`,
      }], { session });
      await OutboxEvent.create([{
        aggregateType: 'LawyerBooking',
        aggregateId: bookingId,
        eventType: 'LawyerBookingCompleted.v1',
        destinationTopic: 'findmedi.dispatch.booking-events.v1',
        payload: {
          bookingId,
          patientId: recipientId,
          lawyerId: String(completed.lawyerId?._id || completed.lawyerId),
          status: 'completed',
          completedAt: completedAt.toISOString(),
          settledAmount,
        },
        status: 'PENDING',
        retryCount: 0,
      }], { session });
      await session.commitTransaction();
    } catch (settlementError) {
      await session.abortTransaction();
      throw settlementError;
    } finally {
      await session.endSession();
    }
    booking = completed;
    await releaseProviderClaim('lawyer', req.user._id, booking._id);

    await notifyBookingUpdate(booking, 'booking_status_update');

    res.json({ success: true, message: settledAmount > 0 ? `Consultation marked completed — ₹${settledAmount} settled to wallet` : 'Consultation marked completed', booking, settledAmount });
  } catch (err) {
    logger.error(`Error completing lawyer consultation: ${err.message}`);
    res.status(500).json({ message: 'Failed to complete consultation' });
  }
});

// ─── POST /api/lawyer-booking/:id/cancel ───────────────────────────────────
// Cancel booking by client or lawyer
router.post('/:id/cancel', protect, authorize('legal:write'), async (req, res) => {
  try {
    const booking = await assertBookingAccess(req, req.params.id, 'cancel');
    if (!booking) {
      return res.status(404).json({ message: 'Booking not found' });
    }

    const isClient = String(booking.userId) === String(req.user._id);
    const isLawyer = String(booking.lawyerId) === String(req.user._id);

    if (!isClient && !isLawyer && req.user.role !== 'superadmin') {
      return res.status(403).json({ message: 'Not authorized to cancel this booking' });
    }

    const status = isClient ? 'cancelled_by_user' : 'cancelled_by_lawyer';
    booking.status = status;
    booking.statusHistory.push({
      status,
      at: new Date(),
      note: req.body.reason || `Cancelled by ${isClient ? 'client' : 'advocate'}`,
    });
    await booking.save();
    if (booking.lawyerId) await releaseProviderClaim('lawyer', booking.lawyerId, booking._id);

    await notifyBookingUpdate(booking, 'booking_status_update');

    // LAW-M-01: auto-refund held retainer on cancellation — return the escrowed
    // amount to the user's demo wallet so the balance is not inflated.
    const { default: DemoPayment } = await import('../models/DemoPayment.js');
    const held = await DemoPayment.findOne({ lawyerBookingId: booking._id, status: 'held_in_escrow' });
    if (held) {
      await User.updateOne({ _id: held.userId }, { $inc: { 'demoWallet.balance': held.amount } });
      held.status = 'refunded';
      held.refundedAt = new Date();
      await held.save();
    }

    const recipientId = isClient ? booking.lawyerId : booking.userId;
    if (recipientId) {
      await Notification.create({
        title: '⚠️ Consultation Cancelled',
        message: `Consultation #${booking.bookingNumber} was cancelled by the other party.`,
        type: 'lawyer',
        userId: String(recipientId),
      }).catch(() => {});
    }

    res.json({ success: true, message: 'Consultation cancelled', booking });
  } catch (err) {
    logger.error(`Error cancelling lawyer booking: ${err.message}`);
    res.status(500).json({ message: 'Failed to cancel booking' });
  }
});

// ─── POST /api/lawyer-booking/:id/reschedule ───────────────────────────────
// Reschedule or accept lawyer's proposed slot
router.post('/:id/reschedule', protect, authorize('legal:write:own'), async (req, res) => {
  try {
    const booking = await LawyerBooking.findById(req.params.id);
    if (!booking) {
      return res.status(404).json({ message: 'Booking not found' });
    }

    if (req.body.acceptProposed && booking.proposedNewTime?.date) {
      booking.scheduledDate = booking.proposedNewTime.date;
      booking.scheduledTime = booking.proposedNewTime.time;
      booking.status = 'confirmed';
      booking.statusHistory.push({
        status: 'confirmed',
        at: new Date(),
        note: 'Client accepted advocate proposed slot',
      });
      booking.proposedNewTime = undefined;
    } else {
      if (req.body.scheduledDate) booking.scheduledDate = new Date(req.body.scheduledDate);
      if (req.body.scheduledTime) booking.scheduledTime = req.body.scheduledTime;
      booking.status = 'confirmed';
      booking.statusHistory.push({
        status: 'confirmed',
        at: new Date(),
        note: `Rescheduled to ${booking.scheduledDate} ${booking.scheduledTime}`,
      });
    }
    await booking.save();

    // Spec 06: auto-release held retainer on consultation sign-off.
    try {
      const { default: DemoPayment } = await import('../models/DemoPayment.js');
      const held = await DemoPayment.findOne({ lawyerBookingId: booking._id, status: 'held_in_escrow' });
      if (held) {
        held.status = 'paid';
        held.paidAt = new Date();
        await held.save();
      }
    } catch (e) {
      logger.warn(`Retainer auto-release skipped: ${e.message}`);
    }

    await notifyBookingUpdate(booking, 'booking_status_update');

    res.json({ success: true, message: 'Consultation rescheduled', booking });
  } catch (err) {
    logger.error(`Error rescheduling lawyer booking: ${err.message}`);
    res.status(500).json({ message: 'Failed to reschedule' });
  }
});

