import express from 'express';
import Event from '../models/Event.js';
import Facility from '../models/Facility.js';
import HealthPackage from '../models/HealthPackage.js';
import Doctor from '../models/Doctor.js';
import Plan from '../models/Plan.js';
import ChronicCarePlan from '../models/ChronicCarePlan.js';
import PlatformContent from '../models/PlatformContent.js';
import PatientAddress from '../models/PatientAddress.js';
import { protect, authorize } from '../middleware/auth.js';
import { auditLog } from '../middleware/audit.js';
import { getISTDateString } from '../utils/dateUtils.js';
import { carePlanRecommendations } from '../lib/carePlanRecommendations.js';
import { seasonalAlertsForMonth } from '../lib/seasonalAlerts.js';
import { resolveProfileAccess } from '../services/profileAccess.js';
import { filterSensitiveForDiscovery } from '../lib/sensitiveCategories.js';

const router = express.Router();

const actorId = (req) => req.user._id ?? req.user.id;

// 6.md §2.11's discover feed: camps/drives near you, government facilities
// (Jan Aushadhi), packages, trending doctors, membership programs, care-plan
// suggestions, seasonal alerts, doctor-reviewed content. Everything runs
// in-house against the session's own data — 6.md §9 forbids raw PHI to third
// parties, so no external call is even made from this handler.
const NEAR_EVENT_TYPES = ['camp', 'vaccination', 'blood_drive'];

// §2.11 opt-out: personalisation (the care-plan section — the only part keyed
// to health data) can be switched off per request with ?personalised=false;
// everything else is generic discovery that carries no health signal. There
// is no stored preference yet, so the client owns the toggle and the flag is
// echoed back and audited.
const wantsPersonalisation = (value) => !['false', '0', 'no', 'off'].includes(String(value ?? '').toLowerCase());

// ─── Discover recommendations (6.md §2.11, route /patient/recommendations) ──
// authz: object
router.get('/', protect, authorize('profile:read:own'), async (req, res) => {
  try {
    const me = actorId(req);

    // §8 object-level authz: ?profileId= may point at a managed family
    // profile (the care-plan section then reads that person's plans through
    // the same familyMemberId scope the summary and timeline use).
    const access = await resolveProfileAccess(req, req.query.profileId);
    if (!access.ok) return res.status(404).json({ message: 'Profile not found' });

    res.set('Cache-Control', 'no-store');
    const personalised = wantsPersonalisation(req.query.personalised);

    const address = await PatientAddress.findOne({ patientId: me, isDefault: true }).lean();
    const city = typeof address?.city === 'string' && address.city.trim() ? address.city.trim() : null;

    const now = new Date();
    const [events, facilities, packages, doctors, programs, activePlans, reviewedContent] = await Promise.all([
      Event.find({
        type: { $in: NEAR_EVENT_TYPES },
        'schedule.start': { $gte: now },
        ...(city ? { 'venue.city': city } : {}),
      }).sort({ 'schedule.start': 1 }).limit(5).lean(),
      Facility.find({ ownership: 'government', ...(city ? { city } : {}) }).limit(5).lean(),
      HealthPackage.find({}).limit(5).lean(),
      Doctor.find({ available: true }).sort({ rating: -1, reviews_count: -1 }).limit(5).lean(),
      Plan.find({ status: 'active' }).sort({ createdAt: -1 }).limit(3).lean(),
      personalised ? ChronicCarePlan.find({ userId: me, familyMemberId: access.scope, status: 'active' }).lean() : [],
      PlatformContent.find({ status: 'published', reviewedAt: { $ne: null } }).sort({ updatedAt: -1 }).limit(3).lean(),
    ]);

    const conditions = [...new Set(activePlans.map((p) => p.condition))];
    const month = Number(getISTDateString().slice(5, 7));

    const body = {
      person: access.profile,
      personalised,
      nearYou: {
        // Without a default address there is no honest "near you" — the
        // sections stay unscoped and cityScoped tells the UI to ask for one.
        city,
        cityScoped: Boolean(city),
        events: events.map((e) => ({
          id: String(e._id), title: e.title, type: e.type,
          start: e.schedule?.start?.toISOString?.() ?? '',
          city: e.venue?.city, mode: e.venue?.mode,
        })),
        facilities: filterSensitiveForDiscovery(facilities).map((f) => ({
          id: String(f._id), name: f.name, type: f.type, city: f.city, slug: f.slug,
        })),
      },
      // §2.11 packages are marked ✅ as a feature, but HealthPackage carries
      // no age/gender targeting fields — the list ships as-is rather than
      // inventing a filter the model cannot answer.
      packages: packages.map((p) => ({
        id: String(p._id), name: p.name, price: p.packagePrice, discount: p.discount,
      })),
      trending: filterSensitiveForDiscovery(doctors).map((d) => ({
        id: String(d._id), name: d.name, specialization: d.specialization,
        rating: d.rating, reviewsCount: d.reviews_count,
      })),
      programs: programs.map((p) => ({
        id: String(p._id), name: p.name, price: p.price, duration: p.duration, type: p.type,
      })),
      // null (not []) when personalisation is off: the client can tell
      // "opted out" apart from "no care plan".
      carePlan: personalised ? carePlanRecommendations(conditions) : null,
      seasonal: seasonalAlertsForMonth(month),
      content: reviewedContent.map((c) => ({
        key: c.key, title: c.title, publishedAt: c.publishedAt, reviewedAt: c.reviewedAt,
      })),
      generatedAt: new Date().toISOString(),
    };

    // Audit on record access (§8): this read touches the care plan. The
    // condition names themselves stay OUT of the log — an audit trail is
    // still a place PHI can leak from.
    await auditLog('recommendations_viewed', me, {
      personId: access.profile.id,
      personKind: access.profile.kind,
      personalised,
      conditionsCount: conditions.length,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });
    return res.json(body);
  } catch (err) {
    return res.status(500).json({ message: err.message });
  }
});

export default router;

import express from 'express';
import Appointment from '../models/Appointment.js';
import LabBooking from '../models/LabBooking.js';
import AppointmentSeries from '../models/AppointmentSeries.js';
import Event from '../models/Event.js';
import EventRegistration from '../models/EventRegistration.js';
import VaccinationSchedule from '../models/VaccinationSchedule.js';
import Record from '../models/Record.js';
import { protect, authorize } from '../middleware/auth.js';
import { auditLog } from '../middleware/audit.js';
import { getISTDateString } from '../utils/dateUtils.js';
import { RECORD_TYPE_OPTIONS } from '../utils/validate.js';
import { REGISTRATION_STATUS } from '../lib/flowStates.js';
import { resolveProfileAccess } from '../services/profileAccess.js';

const router = express.Router();

const actorId = (req) => req.user._id ?? req.user.id;

// 6.md §2.6's upcoming kinds and §2.10's records history, behind one route.
// Physio sessions, home visits and classes are listed in §2.6 but have no
// schedule to read in this repo: Physiotherapy.sessions is a log of COMPLETED
// sessions (exercisesPerformed/progressNote, sessionsCompleted mirrors its
// length) and no home-visit/class model exists — the timeline shows what the
// data can actually answer rather than inventing future slots.
const UPCOMING_TYPES = ['appointment', 'lab_test', 'series', 'event', 'vaccination'];

const SOURCE_CAP = 50;
const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 50;

// Same normalization as Record's `set` mutator (lowercase + underscored), so
// display-style vocabulary like 'Lab Report' queries the stored 'lab_report'.
const normalizeRecordType = (raw) => raw.toLowerCase().replace(/\s+/g, '_');

const isIsoDate = (raw) => /^\d{4}-\d{2}-\d{2}$/.test(raw);

// ─── Unified timeline (6.md §2.6 upcoming + §2.10 history, route /patient/timeline) ──
// segment=upcoming merges the patient's future bookings into one list sorted
// by instant; segment=history is the records timeline with person/type/date
// filters. Every source is session-scoped with the SAME forward-compatible
// `familyMemberId` predicate the dashboard summary uses: null matches rows
// written today without the field, a profile id asks for rows attributed to
// that family member (VaccinationSchedule carries it today, the booking
// models light up when their person tag lands).
//
// DTO allowlist: each kind picks its own display fields — no raw document is
// echoed, and family/clinical fields outside the list can never ride along.
// authz: object
router.get('/', protect, authorize('records:read', 'records:read:own'), async (req, res) => {
  try {
    const me = actorId(req);

    const segment = req.query.segment == null || req.query.segment === '' ? 'upcoming' : String(req.query.segment);
    if (!['upcoming', 'history'].includes(segment)) {
      return res.status(400).json({ message: 'segment must be upcoming or history' });
    }

    // History's vocabulary IS the Record type enum (via the zod options that
    // validateVocab pins as a superset of the model enum).
    const allowedTypes = segment === 'upcoming' ? UPCOMING_TYPES : RECORD_TYPE_OPTIONS;
    let type = req.query.type == null || req.query.type === '' ? null : String(req.query.type);
    if (type && !allowedTypes.includes(type)) {
      // 400, not a silent ignore: an unknown filter that quietly returns
      // everything (upcoming) or nothing (history) reads as "no data".
      return res.status(400).json({ message: `Unknown type filter for ${segment}` });
    }
    if (type && segment === 'history') type = normalizeRecordType(type);

    const dateFrom = req.query.dateFrom == null || req.query.dateFrom === '' ? null : String(req.query.dateFrom);
    const dateTo = req.query.dateTo == null || req.query.dateTo === '' ? null : String(req.query.dateTo);
    if (segment === 'history') {
      if ((dateFrom && !isIsoDate(dateFrom)) || (dateTo && !isIsoDate(dateTo))) {
        return res.status(400).json({ message: 'dateFrom/dateTo must be YYYY-MM-DD' });
      }
      if (dateFrom && dateTo && dateTo < dateFrom) {
        return res.status(400).json({ message: 'dateTo must not precede dateFrom' });
      }
    }

    const page = Math.max(1, parseInt(String(req.query.page ?? '1'), 10) || 1);
    const limit = Math.min(MAX_LIMIT, Math.max(1, parseInt(String(req.query.limit ?? String(DEFAULT_LIMIT)), 10) || DEFAULT_LIMIT));

    // Object-level decision (self or authorised family) before any read.
    const access = await resolveProfileAccess(req, req.query.personId);
    if (!access.ok) return res.status(404).json({ message: 'Profile not found' });

    res.set('Cache-Control', 'no-store');
    const scope = access.scope;
    let items = [];
    let total = 0;

    if (segment === 'upcoming') {
      const today = getISTDateString();
      const now = new Date();
      const wanted = (kind) => !type || type === kind;
      const sources = await Promise.all([
        wanted('appointment') ? Appointment.find({
          patientId: me, familyMemberId: scope,
          date: { $gte: today }, status: { $in: ['Pending', 'Confirmed'] },
        }).sort({ date: 1, time: 1 }).limit(SOURCE_CAP).lean() : [],
        wanted('lab_test') ? LabBooking.find({
          patientId: me, familyMemberId: scope,
          bookingDate: { $gte: now }, status: { $nin: ['Cancelled', 'Completed', 'Rescheduled'] },
        }).sort({ bookingDate: 1 }).limit(SOURCE_CAP).lean() : [],
        wanted('series') ? AppointmentSeries.find({
          patientId: me, familyMemberId: scope, status: 'active',
          occurrenceDates: { $gte: today },
        }).limit(SOURCE_CAP).lean() : [],
        wanted('event') ? (async () => {
          const regs = await EventRegistration.find({
            userId: me, familyMemberId: scope, status: REGISTRATION_STATUS.REGISTERED,
          }).limit(SOURCE_CAP).lean();
          if (!regs.length) return [];
          const events = await Event.find({
            _id: { $in: regs.map((r) => r.eventId) },
            'schedule.start': { $gte: now },
          }).lean();
          return events.map((e) => ({ reg: regs.find((r) => String(r.eventId) === String(e._id)), event: e }));
        })() : [],
        wanted('vaccination') ? VaccinationSchedule.find({
          userId: me, familyMemberId: scope, status: 'scheduled',
          doses: { $elemMatch: { dueAt: { $gte: now }, givenAt: null } },
        }).limit(SOURCE_CAP).lean() : [],
      ]);

      const [appointments, labBookings, series, eventPairs, vaccinations] = sources;

      for (const a of appointments) {
        items.push({ kind: 'appointment', id: String(a._id), at: a.date, time: a.time, status: a.status, title: a.doctor, department: a.department });
      }
      for (const b of labBookings) {
        items.push({ kind: 'lab_test', id: String(b._id), at: b.bookingDate?.toISOString?.() ?? String(b.bookingDate), time: b.timeSlot ?? '', status: b.status, title: (b.tests ?? []).join(', '), visitType: b.visitType });
      }
      for (const s of series) {
        for (const d of (s.occurrenceDates ?? []).filter((d) => d >= today).slice(0, SOURCE_CAP)) {
          items.push({ kind: 'series', id: String(s._id), at: d, time: s.time, status: s.status, title: s.doctor, seriesType: s.type });
        }
      }
      for (const pair of eventPairs) {
        items.push({
          kind: 'event', id: String(pair.reg._id), eventId: String(pair.event._id),
          at: pair.event.schedule?.start?.toISOString?.() ?? '', status: pair.reg.status,
          title: pair.event.title, mode: pair.event.venue?.mode,
        });
      }
      for (const v of vaccinations) {
        for (const dose of (v.doses ?? []).filter((d) => d.dueAt && !d.givenAt && d.dueAt >= now)) {
          items.push({ kind: 'vaccination', id: `${v._id}#${dose.number}`, at: dose.dueAt.toISOString(), status: v.status, title: v.vaccineName, dose: dose.number, centre: dose.centre || undefined });
        }
      }

      items.sort((a, b) => (a.at < b.at ? -1 : a.at > b.at ? 1 : a.id < b.id ? -1 : 1));
      total = items.length;
      items = items.slice((page - 1) * limit, page * limit);
    } else {
      const dateFilter = {};
      if (dateFrom) dateFilter.$gte = dateFrom;
      if (dateTo) dateFilter.$lte = dateTo;
      const filter = { patientId: me, familyMemberId: scope };
      if (type) filter.type = type;
      if (dateFrom || dateTo) filter.date = dateFilter;

      total = await Record.countDocuments(filter);
      const rows = await Record.find(filter)
        .sort({ date: -1, _id: -1 })
        .skip((page - 1) * limit)
        .limit(limit)
        .lean();
      // Allowlist: id/date/type/doctor/diagnosis only — vitals, prescription
      // body, appointment linkage and the raw `patient` string stay out.
      items = rows.map((r) => ({
        kind: 'record', id: String(r._id), at: r.date, type: r.type,
        title: r.diagnosis || r.type, doctor: r.doctor,
      }));
    }

    await auditLog('patient_timeline_viewed', me, {
      segment, type, personId: access.profile.id, personKind: access.profile.kind, count: items.length,
      ip: req.ip, userAgent: req.get('user-agent'),
    });
    return res.json({
      segment,
      person: access.profile,
      items, total, page, limit,
      generatedAt: new Date().toISOString(),
    });
  } catch (err) {
    return res.status(500).json({ message: err.message });
  }
});

export default router;

import { escapeRegex, capSearch } from '../utils/escapeRegex.js';
import express from 'express';
import Patient from '../models/Patient.js';
import { protect } from '../middleware/auth.js';
import { validate, createPatientSchema, updatePatientSchema } from '../utils/validate.js';
import { auditLog } from '../middleware/audit.js';
import { paginatedResults } from '../utils/pagination.js';
import { requireBreakGlass } from '../middleware/requireBreakGlass.js';
import logger from '../config/logger.js';

// File 23 §3.3/§4.3: platform operators see MASKED identity by default.
// Full identity needs a BreakGlassGrant (per-subject, time-boxed, audited).
const PLATFORM_DIRECTORY_ROLES = new Set([
  'superadmin', 'platform_admin', 'support_l1', 'support_l2', 'dpo',
  'security_admin', 'clinical_safety', 'analyst', 'auditor',
]);

const maskName = (v) => {
  const parts = String(v || '').split(' ').filter(Boolean);
  if (!parts.length) return '***';
  return parts.length > 1 ? `${parts[0]} ${parts[1][0]}***` : `${parts[0][0]}***`;
};
const maskPhone = (v) => {
  const s = String(v || '');
  return s.length > 4 ? `${s.slice(0, 2)}******${s.slice(-2)}` : '******';
};
const maskEmail = (v) => {
  const s = String(v || '');
  const at = s.indexOf('@');
  return at > 0 ? `${s[0]}***${s.slice(at)}` : '***';
};
const maskTail4 = (v) => {
  const s = String(v || '');
  return s.length > 4 ? `•••${s.slice(-4)}` : '•••';
};
const maskPatient = (p) => ({
  // Allowlist fields. A spread here could expose newly-added clinical/model
  // fields to every platform operator through the masked directory.
  _id: p._id,
  status: p.status,
  createdAt: p.createdAt,
  name: maskName(p.name),
  phone: maskPhone(p.phone),
  email: maskEmail(p.email),
  address: '[masked]',
  uhid: maskTail4(p.uhid),
});

// Single-subject doc routes: platform roles pass only with a grant.
const requirePatientGrant = (req, res, next) => {
  if (PLATFORM_DIRECTORY_ROLES.has(req.user?.role)) return requireBreakGlass('patient')(req, res, next);
  return next();
};

const router = express.Router();

const OBJECT_ID = /^[0-9a-f]{24}$/i;
const requireObjectId = (req, res, next) => (OBJECT_ID.test(String(req.params.id)) ? next() : res.status(404).json({ message: 'Not found' }));

/**
 * DLB-17: object-level authorization for the patient directory.
 *
 * The old checks were two fail-open one-liners:
 *   - `if (req.user.hospitalId && role !== 'superadmin') filter.hospitalId = ...`
 *     => every account WITHOUT a hospital (rider, lawyer, assistant, technician,
 *        nurse, even a doctor with no hospital link) listed the ENTIRE patient
 *     directory of every hospital on the platform.
 *   - `if (role === 'patient' && p._id !== req.user._id)` compared the Patient
 *     document id against the USER id, so a patient could never read their own row.
 *
 * Rules now: superadmin sees all; a patient sees only their own row; hospital /
 * facility staff see only their own tenant; anyone else is refused.
 */
const PATIENT_STAFF_ROLES = [
  'hospital_admin', 'doctor', 'clinic_doctor', 'nurse', 'lab_owner', 'lab_receptionist',
  'lab_technician', 'pathologist', 'pharmacy_owner', 'pharmacist', 'receptionist',
  'accountant', 'counsellor', 'psychiatrist', 'dietitian', 'physiotherapist', 'radiologist',
  // 7.md 3: clinical + facility roles that run care episodes (tenant-scoped
  // to their own facility by the check below). Retail/marketplace roles stay
  // out — an equipment vendor has no care relationship to list patients by.
  'dentist', 'dental_clinic_admin', 'optician', 'phlebotomist',
  'home_nursing_admin', 'dialysis_admin', 'fertility_admin', 'maternity_admin',
  'rehab_admin', 'govt_facility_staff',
  // File 09 §8.2: front-desk patient search (tenant-scoped by the check below).
  'receptionist',
  // Doc 12 §3: clinic front-desk + nurse need the same directory search.
  'clinic_receptionist', 'clinic_nurse',
];

const canReadPatientList = (req) => {
  // File 23 §3.3: platform directory is masked by default (no grant can
  // cover a whole list — grants are single-subject).
  if (PLATFORM_DIRECTORY_ROLES.has(req.user.role)) return { ok: true, masked: true };
  if (req.user.role === 'patient') return { ok: true, ownOnly: true };
  if (PATIENT_STAFF_ROLES.includes(req.user.role)) {
    const scope = req.user.hospitalId || req.user.facilityId;
    if (scope) return { ok: true, scope: String(scope) };
  }
  return { ok: false };
};

const canAccessPatientDoc = (req, patient) => {
  if (!patient) return false;
  // File 23 §5.3: platform roles pass only with an approved grant, attached
  // as req.breakGlass by requirePatientGrant before this check runs.
  if (PLATFORM_DIRECTORY_ROLES.has(req.user.role)) return Boolean(req.breakGlass);
  if (req.user.role === 'patient') {
    // The Patient row carries the owning User id in `userId`.
    return Boolean(patient.userId && String(patient.userId) === String(req.user._id || req.user.id));
  }
  if (PATIENT_STAFF_ROLES.includes(req.user.role)) {
    const scope = req.user.hospitalId || req.user.facilityId;
    if (!scope || !patient.hospitalId) return false;
    return String(patient.hospitalId) === String(scope);
  }
  return false;
};

// ─── Get Patients ───────────────────────────────────────────────────────────
router.get('/', protect, async (req, res) => {  try {
    const { page, limit, search, status } = req.query;
    const access = canReadPatientList(req);
    if (!access.ok) {
      return res.status(403).json({ message: 'Not authorized to list patients' });
    }
    const filter = {};
    if (access.ownOnly) {
      filter.userId = req.user._id;
    } else if (access.scope) {
      filter.hospitalId = access.scope;
    }
    if (search) {
      filter.$or = [
        { name: new RegExp(escapeRegex(capSearch(search)), 'i') },
        { disease: new RegExp(escapeRegex(capSearch(search)), 'i') },
        { doctor: new RegExp(escapeRegex(capSearch(search)), 'i') },
        { uhid: new RegExp(escapeRegex(capSearch(search)), 'i') },
      ];
    }
    if (status) filter.status = status;
    const result = await paginatedResults(Patient, filter, { page, limit });
    if (access.masked && Array.isArray(result.data)) result.data = result.data.map(maskPatient);
    else if (access.masked && Array.isArray(result.results)) result.results = result.results.map(maskPatient);
    else {
      // File 13 §13.6: field-level mask for phone/email when the role is
      // outside the clinical allowlist (e.g. accountant, pharmacist).
      const { applyFieldMaskMany } = await import('../lib/fieldMask.js');
      if (Array.isArray(result.data)) result.data = applyFieldMaskMany('Patient', result.data, req.user.role);
      else if (Array.isArray(result.results)) result.results = applyFieldMaskMany('Patient', result.results, req.user.role);
    }
    res.json(result);
  } catch (err) { res.status(500).json({ message: err.message }); }
});

// File 22 P1-12: duplicate detection (same phone, or same name+dob/phone
// prefix) + merge tool + ABHA linkage. Declared BEFORE /:id so the literal
// paths are not swallowed as ids.
// authz: role
router.get('/duplicates', protect, async (req, res) => {
  try {
    const access = canReadPatientList(req);
    // Duplicate detection requires identity comparison. It is a tenant clinic
    // workflow and cannot be made safe by returning a platform-wide masked list.
    if (!access.ok || access.masked || access.ownOnly || !access.scope) {
      return res.status(403).json({ message: 'Tenant-scoped staff access required' });
    }
    const base = {};
    if (access.scope) base.hospitalId = access.scope;
    const rows = await Patient.find({ ...base, mergedInto: null }).select('_id name phone dateOfBirth uhid').limit(2000).lean();
    const byPhone = {};
    for (const p of rows) {
      const ph = String(p.phone || '').replace(/\D/g, '').slice(-10);
      if (ph.length < 10) continue;
      byPhone[ph] = byPhone[ph] || [];
      byPhone[ph].push(p);
    }
    const groups = Object.values(byPhone).filter((g) => g.length > 1)
      .map((g) => ({ key: 'duplicate-phone', patients: g.map((p) => ({
        _id: p._id,
        name: maskName(p.name),
        phone: maskPhone(p.phone),
        uhid: maskTail4(p.uhid),
      })) }));
    return res.json({ groups });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

// Merge duplicate INTO :id (survivor). Re-points clinical/financial refs,
// moves flags, marks the duplicate merged (never deleted — audit trail).
// authz: role (front-desk leads; survivor must be unmerged).
router.post('/:id/merge', protect, async (req, res) => {
  try {
    const access = canReadPatientList(req);
    if (!access.ok) return res.status(403).json({ message: 'Not authorized' });
    const { duplicateId } = req.body || {};
    if (!duplicateId || String(duplicateId) === String(req.params.id)) {
      return res.status(400).json({ message: 'duplicateId (≠ survivor) required' });
    }
    const [survivor, dup] = await Promise.all([
      Patient.findById(req.params.id), Patient.findById(duplicateId),
    ]);
    if (!survivor || !dup) return res.status(404).json({ message: 'Patient not found' });
    if (survivor.mergedInto || dup.mergedInto) {
      return res.status(409).json({ message: 'One side is already merged' });
    }
    if (String(survivor.hospitalId) !== String(dup.hospitalId)) {
      return res.status(409).json({ message: 'Cross-hospital merge forbidden' });
    }
    const { default: Appointment } = await import('../models/Appointment.js');
    const { default: Billing } = await import('../models/Billing.js');
    const { default: LabOrder } = await import('../models/LabOrder.js');
    const { default: PharmacyOrder } = await import('../models/PharmacyOrder.js');
    const { default: Encounter } = await import('../models/Encounter.js');
    const { default: PatientFlag } = await import('../models/PatientFlag.js');
    await Promise.all([
      Appointment.updateMany(
        { $or: [{ patientRecordId: dup._id }, { patientId: dup.userId || dup._id }] },
        { $set: { patientRecordId: survivor._id } },
      ).catch(() => null),
      Billing.updateMany({ patientId: dup.userId || dup._id }, { $set: { patientId: survivor.userId || survivor._id } }).catch(() => null),
      LabOrder.updateMany({ patientId: dup.userId || dup._id }, { $set: { patientId: survivor.userId || survivor._id } }).catch(() => null),
      PharmacyOrder.updateMany({ patientId: dup.userId || dup._id }, { $set: { patientId: survivor.userId || survivor._id } }).catch(() => null),
      Encounter.updateMany({ patientId: dup.userId || dup._id }, { $set: { patientId: survivor.userId || survivor._id } }).catch(() => null),
      PatientFlag.updateMany({ patient: dup._id }, { $set: { patient: survivor._id } }).catch(() => null),
    ]);
    dup.mergedInto = survivor._id;
    dup.mergedAt = new Date();
    dup.mergedBy = req.user._id;
    await dup.save();
    await auditLog('patient_merged', req.user._id, { survivor: survivor._id, duplicate: dup._id, ip: req.ip });
    return res.json({ id: String(survivor._id), merged: String(dup._id) });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

// ABHA address linkage (verification happens when ABDM credentials exist;
// until then the address is stored Unverified — never claimed as verified).
router.post('/:id/abha', protect, async (req, res) => {
  try {
    const p = await Patient.findById(req.params.id);
    if (!p) return res.status(404).json({ message: 'Patient not found' });
    if (!canAccessPatientDoc(req, p)) return res.status(403).json({ message: 'Access denied' });
    const { abhaAddress } = req.body || {};
    if (!abhaAddress || !/^[a-zA-Z0-9._-]{3,}@[a-zA-Z]{2,}$/.test(String(abhaAddress))) {
      return res.status(400).json({ message: 'Valid ABHA address required (user@sbx)' });
    }
    p.abhaAddress = String(abhaAddress);
    p.abhaStatus = 'Unverified';
    await p.save();
