// T6 Narcotic & Schedule H1 stock reconciliation:
// Closing(expected) = Opening + Purchases(GRN) - Dispensed(H1) - Adjustments
// Compare against physical count and compute variance
// authz: role
router.get('/narcotic-register/reconcile', protect, denyPlatformClinicalAccess, authorize('pharmacy:read', 'pharmacy:manage'), async (req, res) => {
  try {
    const tenant = (req.user.hospitalId && req.user.role !== 'superadmin')
      ? { hospitalId: req.user.hospitalId } : {};
    const fromDate = req.query.from ? new Date(req.query.from) : new Date(Date.now() - 30 * 86400000);
    const toDate = req.query.to ? new Date(req.query.to) : new Date();

    const controlledFilter = {
      $or: [
        { rxSchedule: { $in: [...REGISTER_SCHEDULES, ...Object.keys(REGISTER_SCHEDULE_ALIASES)] } },
        { 'storage.controlled': true },
      ],
    };
    if (req.query.medicineId) controlledFilter._id = req.query.medicineId;

    const medicines = await Medicine.find(controlledFilter).select('_id name rxSchedule stock batch').lean();
    const rows = [];

    for (const med of medicines) {
      const medId = med._id;
      // 1. Dispensed count in period
      const dispensedEntries = await H1RegisterEntry.find({
        ...tenant,
        medicineId: medId,
        dispensedAt: { $gte: fromDate, $lte: toDate },
      }).select('quantity').lean();
      const dispensedQty = dispensedEntries.reduce((sum, e) => sum + (e.quantity || 0), 0);

      // 2. Adjustments in period
      const adjustments = await NarcoticAdjustment.find({
        ...tenant,
        medicineId: medId,
        at: { $gte: fromDate, $lte: toDate },
      }).lean();
      const adjustedQty = adjustments.reduce((sum, a) => sum + (a.qty || 0), 0);

      // 3. Purchases / GRN in period from StockLedger (if available) or current stock baseline
      const stockLedgerMoves = await StockLedger.find({
        ...tenant,
        itemId: String(medId),
        createdAt: { $gte: fromDate, $lte: toDate },
      }).lean();
      const purchasesQty = stockLedgerMoves.reduce((sum, m) => sum + (m.qtyIn || 0), 0);

      // 4. Latest physical count
      const latestCount = await NarcoticCount.findOne({
        ...tenant,
        medicineId: medId,
        at: { $lte: toDate },
      }).sort({ at: -1 }).lean();

      const currentStock = med.stock || 0;
      // Opening = currentStock + dispensedQty + adjustedQty - purchasesQty
      const openingQty = Math.max(0, currentStock + dispensedQty + adjustedQty - purchasesQty);
      const expectedClosing = Math.max(0, openingQty + purchasesQty - dispensedQty - adjustedQty);
      const physicalQty = latestCount ? latestCount.countedQty : currentStock;
      const variance = physicalQty - expectedClosing;

      rows.push({
        medicineId: String(medId),
        medicineName: med.name,
        rxSchedule: med.rxSchedule || 'h1',
        openingQty,
        purchasesQty,
        dispensedQty,
        adjustedQty,
        expectedClosing,
        physicalQty,
        variance,
        lastCountedAt: latestCount?.at || null,
        lastCountedByName: latestCount?.countedByName || '',
        witnessByName: latestCount?.witnessByName || '',
      });
    }

    const varianceCount = rows.filter((r) => r.variance !== 0).length;
    if (varianceCount > 0) {
      // Narcotic variance is a potential-diversion signal: raise ONE alert
      // per day (deduped on open alerts with the same code), not one per
      // reconcile read. Never blocks the response.
      void (async () => {
        try {
          const { default: DashboardAlert } = await import('../models/DashboardAlert.js');
          const dayAgo = new Date(Date.now() - 24 * 3600 * 1000);
          const existing = await DashboardAlert.findOne({
            hospitalId: req.user.hospitalId,
            code: 'narcotic-variance',
            status: 'open',
            createdAt: { $gte: dayAgo },
          }).select('_id').lean();
          if (!existing) {
            const { raiseAlert } = await import('../lib/alerts.js');
            await raiseAlert({
              hospitalId: req.user.hospitalId,
              severity: 'critical',
              message: `Narcotic register variance on ${varianceCount} medicine(s) — physical count differs from expected closing. Verify immediately.`,
              entityRef: { model: 'NarcoticCount' },
              code: 'narcotic-variance',
              by: req.user._id,
            });
          }
          // Queue the human follow-up as an operational task (P1), deduped on
          // open same-day tasks so repeated reconcile sweeps never flood the
          // ward task board. Tasking must never break the reconcile read.
          try {
            const { default: WorkTask } = await import('../models/WorkTask.js');
            const openTask = await WorkTask.findOne({
              hospitalId: req.user.hospitalId,
              status: 'Open',
              tags: 'narcotic-variance',
              createdAt: { $gte: dayAgo },
            }).select('_id').lean();
            if (!openTask) {
              await WorkTask.create({
                hospitalId: req.user.hospitalId,
                title: 'Narcotic register variance — physical recount required',
                detail: `${varianceCount} controlled medicine(s) show variance between physical stock and expected closing in the H1/narcotic register. Recount with a witness, file an adjustment (wastage/breakage/expiry) or report suspected diversion for CA review.`,
                entityRef: { model: 'NarcoticCount' },
                roleQueue: 'pharmacist',
                priority: 'P1',
                tags: ['narcotic-variance'],
                createdBy: req.user._id,
              });
            }
          } catch { /* task creation must never break reconciliation */ }
        } catch { /* alerting must never break reconciliation */ }
      })();
    }
    res.json({
      from: fromDate,
      to: toDate,
      count: rows.length,
      varianceCount,
      rows,
    });
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

