import { protect, denyPlatformClinicalAccess, adminOnly } from '../middleware/auth.js';
import { validate, createPhysioReferralSchema, boundedShallow } from '../utils/validate.js';

// P1-6: pain levels are 0–10 numbers (or short text); narrative fields are
// bounded text; structured fields accept text or one level of JSON — never
// arbitrary depth/values.
const painLevelShape = z.union([z.number().min(0).max(10), z.string().trim().max(50)]);
const physioTextOrStructured = z.union([z.string().trim().max(8000), boundedShallow]);
import { generateOrderId, generateInvoiceId } from '../utils/idGenerator.js';
import { getISTDateString } from '../utils/dateUtils.js';
import { escapeRegex, capSearch } from '../utils/escapeRegex.js';

// P3: explicit shapes instead of passthrough. Keys mirror the sub-docs in
// models/Physiotherapy.js — mongoose strict would drop anything else on save,
// and the handlers only read these fields (+ server-stamped ones), so nothing
// a client legitimately sends is lost.
const physioAssessSchema = z.object({
  painScale: painLevelShape.optional(),
  rangeOfMotion: physioTextOrStructured.optional(),
  strengthTest: physioTextOrStructured.optional(),
  functionalAssessment: physioTextOrStructured.optional(),
  notes: z.string().trim().max(8000).optional(),
  treatmentPlan: physioTextOrStructured.optional(),
});
const physioSessionSchema = z.object({
  exercisesPerformed: z.union([z.string().trim().max(8000), z.array(boundedShallow).max(200)]).optional(),
  progressNote: z.string().trim().max(8000).optional(),
  painLevelBefore: painLevelShape.optional(),
  painLevelAfter: painLevelShape.optional(),
  duration: z.union([z.number().finite().nonnegative().max(1440), z.string().trim().max(50)]).optional(),
});
const physioMidReviewSchema = z.object({ notes: z.string().optional(), response: z.string().optional(), progress: z.number().optional() });
const physioBillingSchema = z.object({ amount: z.number().optional(), description: z.string().optional(), sessionType: z.string().optional() });
const physioCompleteSchema = z.object({
  homeExercise: physioTextOrStructured.optional(),
  precautions: physioTextOrStructured.optional(),
  followUpDate: z.string().trim().max(50).optional(),
});

const router = express.Router();
router.use(protect, denyPlatformClinicalAccess);

router.post('/referrals', adminOnly, validate(createPhysioReferralSchema), async (req, res) => {
  try {
    const { patientId, patientName, diagnosis, treatmentPlan } = req.body;
    if (!patientId) return res.status(400).json({ message: 'Patient required' });
    const referralId = generateOrderId('PHY');
    const r = await Physiotherapy.create({ 
      referralId, patientId, patientName, diagnosis, treatmentPlan,
      doctorId: req.user.doctorProfileId || req.user._id, doctorName: req.user.name, hospitalId: req.user.hospitalId || undefined, createdBy: req.user._id 
    });
    res.status(201).json(r);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.get('/referrals', async (req, res) => {
  try {
    const { status, search } = req.query;
    const filter = {};
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }
    if (status && status !== 'All') filter.status = status;
    if (search) filter.$or = [{ referralId: new RegExp(escapeRegex(capSearch(search)), 'i') }, { patientName: new RegExp(escapeRegex(capSearch(search)), 'i') }];
    const data = await Physiotherapy.find(filter).sort({ createdAt: -1 });
    res.json({ referrals: data });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.put('/referrals/:id/assess', adminOnly, validate(physioAssessSchema), async (req, res) => {
  try {
    const r = await Physiotherapy.findById(req.params.id);
    if (!r) return res.status(404).json({ message: 'Not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || r.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Access denied' });
    }
    r.initialAssessment = req.body;
    r.status = 'In Progress';
    r.treatmentPlan = req.body.treatmentPlan;
    await r.save();
    res.json(r);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.post('/referrals/:id/session', adminOnly, validate(physioSessionSchema), async (req, res) => {
  try {
    const r = await Physiotherapy.findById(req.params.id);
    if (!r) return res.status(404).json({ message: 'Not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || r.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Access denied' });
    }
    const s = req.body;
    s.sessionNumber = (r.sessions?.length || 0) + 1;
    s.date = new Date();
    s.therapistName = req.user.name;
    r.sessions.push(s);
    await r.save();
    res.json(r);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

// Mid-review endpoint
router.put('/referrals/:id/mid-review', adminOnly, validate(physioMidReviewSchema), async (req, res) => {
  try {
    const { notes, response, progress } = req.body;
    const r = await Physiotherapy.findById(req.params.id);
    if (!r) return res.status(404).json({ message: 'Not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || r.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Access denied' });
    }

    r.status = 'Mid Review';
    r.midReviewNotes = notes || '';
    r.midReviewResponse = response || '';
    r.progress = progress || r.progress || 50;

    await r.save();
    res.json(r);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

// Create billing for physiotherapy session
router.post('/referrals/:id/create-billing', adminOnly, validate(physioBillingSchema), async (req, res) => {
  try {
    const referral = await Physiotherapy.findById(req.params.id);
    if (!referral) return res.status(404).json({ message: 'Referral not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || referral.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Access denied' });
    }

    const { amount, description, sessionType } = req.body;

    const invoiceId = generateInvoiceId('physio');

    const billing = await Billing.create({
      invoiceId,
      patient: referral.patientName,
      patientId: referral.patientId,
      service: description || 'Physiotherapy Session',
      amount: amount || 500,
      source: 'physio',
      status: 'Pending',
      date: getISTDateString(),
      physioReferralId: referral._id,
    });

    void import('../lib/pgDualWrite.js').then((m) => m.mirrorBilling(billing)).catch(() => {});

    // Notify billing department
    await Notification.create({
      title: 'New Physiotherapy Bill',
      message: `Physiotherapy billing created for ${referral.patientName}`,
      type: 'billing',
      userId: req.user._id.toString(),
    });

    res.status(201).json(billing);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.put('/referrals/:id/complete', adminOnly, validate(physioCompleteSchema), async (req, res) => {
  try {
    const r = await Physiotherapy.findById(req.params.id);
    if (!r) return res.status(404).json({ message: 'Not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || r.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Access denied' });
    }
    r.status = 'Completed';
    r.dischargePlan = req.body;
    await r.save();
    res.json(r);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

// Get single referral
router.get('/referrals/:id', async (req, res) => {
  try {
    const referral = await Physiotherapy.findById(req.params.id).populate('patientId', 'name email phone');
    if (!referral) return res.status(404).json({ message: 'Referral not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || referral.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Access denied' });
    }
    res.json(referral);
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.get('/stats', async (req, res) => {
  const hFilter = {};
  if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); hFilter.hospitalId = req.user.hospitalId; }
  const active = await Physiotherapy.countDocuments({ ...hFilter, status: { $in: ['Referred','In Progress','Mid Review'] } });
  const completed = await Physiotherapy.countDocuments({ ...hFilter, status: 'Completed' });
  const total = await Physiotherapy.countDocuments(hFilter);
  res.json({ active, completed, total });
});

export default router;

import express from 'express';
import { z } from 'zod';
import bcrypt from 'bcryptjs';
import User from '../models/User.js';
import Hospital from '../models/Hospital.js';
import Facility from '../models/Facility.js';
import Doctor from '../models/Doctor.js';
import { validate, boundedShallow } from '../utils/validate.js';
import { createAndSendOTP } from '../services/otpService.js';
import { createGrlRateLimiter } from '../middleware/rateLimit.js';
import { randomPassword } from '../utils/secureRandom.js';

const platformRegisterSchema = z.object({
  type: z.enum(['hospital', 'clinic', 'diagnostic', 'pharmacy']),
  account: z.object({
    name: z.string().min(2),
    email: z.string().email(),
    phone: z.string().min(10),
    password: z.string().min(12, 'Password must be at least 12 characters'),
  }),
  facility: z.object({
    name: z.string().min(2),
    email: z.string().email().optional(),
    phone: z.string().optional(),
    address: z.string().optional(),
    city: z.string().optional(),
    state: z.string().optional(),
    pincode: z.string().optional(),
    license: z.string().optional(),
    website: z.string().optional(),
    description: z.string().optional(),
    specialties: z.array(z.string()).optional(),
    established: z.number().optional(),
    logo: z.string().optional(),
    image: z.string().optional(),
    accreditations: z.array(z.string()).optional(),
    weekSchedule: boundedShallow.optional(),
    insurance: z.array(z.string().trim().max(200)).max(100).optional(),
    amenities: z.union([z.string().trim().max(2000), z.array(z.string().trim().max(200)).max(100)]).optional(),
    socialLinks: z.record(z.string().max(100), z.string().trim().max(500)).optional(),
    timing: z.string().optional(),
    nablNumber: z.string().optional(),
    aerbNumber: z.string().optional(),
  }).passthrough().optional(),
  services: z.array(boundedShallow).max(200).optional(),
  doctors: z.array(z.object({
    name: z.string().optional(),
    email: z.string().optional(),
    phone: z.string().optional(),
    specialization: z.string().optional(),
    experience: z.string().optional(),
    qualifications: z.string().optional(),
    licenseNumber: z.string().optional(),
    consultationFee: z.number().optional(),
    appointmentModes: z.array(z.string()).optional(),
    appointmentFees: z.union([z.number().finite().nonnegative(), z.record(z.string().max(100), z.number().finite().nonnegative())]).optional(),
  }).passthrough()).optional(),
  specialist: boundedShallow.optional(),
  ambulances: z.array(z.object({
    registrationNumber: z.string().optional(),
    vehicleModel: z.string().optional(),
    ambulanceType: z.string().optional(),
    equipmentLevel: z.string().optional(),
    driverName: z.string().optional(),
    driverPhone: z.string().optional(),
    loginEmail: z.string().optional(),
  }).passthrough()).optional(),
});

const router = express.Router();

// ADM-B-05: facility/doctor onboarding is an unauthenticated public form, so
// it gets its own per-IP budget — otherwise a script can mass-create
// institutions (and credential emails) from one IP.
const platformRegisterLimiter = createGrlRateLimiter({
  windowMs: 60 * 1000,
  max: 5,
  keyPrefix: 'rl:platformregister',
});

router.post('/register', platformRegisterLimiter, validate(platformRegisterSchema), async (req, res) => {
  try {
    const { type, account, facility, services, doctors, specialist, ambulances } = req.body;

    const existingUser = await User.findOne({ email: account.email.toLowerCase() });
    if (existingUser) return res.status(400).json({ message: 'An account with this email already exists' });

    const roleMap = {
      hospital: 'hospital_admin',
      clinic: 'clinic_doctor',
      diagnostic: 'lab_owner',
      pharmacy: 'pharmacy_owner',
    };

    const hashedPassword = await bcrypt.hash(account.password, 10);
    const slug = facility.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') + '-' + Date.now();

    let entity;

    if (type === 'hospital') {
      entity = await Hospital.create({
        name: facility.name,
        email: (facility.email || account.email).toLowerCase(),
        phone: facility.phone || account.phone,
        address: facility.address || '',
        city: facility.city || '',
        state: facility.state || '',
        pincode: facility.pincode || '',
        licenseNumber: facility.license || '',
        website: facility.website || '',
        description: facility.description || '',
        specialties: facility.specialties || [],
        establishedYear: facility.established || undefined,
        logo: facility.logo || '',
        image: facility.image || '',
        accreditations: facility.accreditations || [],
        workingHours: facility.weekSchedule || {},
        insuranceAccepted: (facility.insurance || []).map(i => ({ provider: i })),
        amenities: facility.amenities || { parking: false, acWaitingArea: false, wheelchairAccess: false, cardPayment: false, inHousePharmacy: false, drinkingWater: false, wifi: false, homeVisit: false },
        socialLinks: facility.socialLinks || { facebook: '', instagram: '', youtube: '' },
        appointmentModes: facility.appointmentModes || [],
        appointmentFees: facility.appointmentFees || {},
        emergencySupport: Boolean(facility.emergencySupport || facility.emergency24x7),
        emergency24x7: Boolean(facility.emergencySupport || facility.emergency24x7),
        refundOnMissedOrCancelled: Boolean(facility.refundPolicy ?? facility.refundOnMissedOrCancelled),
        ambulanceService: Boolean(facility.ambulanceSupport ?? facility.ambulanceService),
        slug,
        status: 'pending',
      });

      await User.create({
        name: account.name,
        email: account.email.toLowerCase(),
        password: hashedPassword,
        role: 'hospital_admin',
        phone: account.phone,
        hospitalId: entity._id,
        isVerified: false,
        status: 'inactive',
        approvalStatus: 'pending',
      });
    } else {
      entity = await Facility.create({
        type,
        name: facility.name,
        email: (facility.email || account.email).toLowerCase(),
        phone: facility.phone || account.phone,
        address: facility.address || '',
        city: facility.city || '',
        state: facility.state || '',
        licenseNumber: facility.license || '',
        pincode: facility.pincode || '',
        description: facility.description || '',
        specialties: facility.specialties || [],
        establishedYear: facility.established || undefined,
        logo: facility.logo || '',
        image: facility.image || '',
        accreditations: facility.accreditations || [],
        amenities: facility.amenities || {},
        socialLinks: facility.socialLinks || {},
        timing: facility.weekSchedule || {},
        workingHours: facility.timing || '',
        appointmentModes: facility.appointmentModes || [],
        appointmentFees: facility.appointmentFees || {},
        emergencySupport: Boolean(facility.emergencySupport),
        refundOnMissedOrCancelled: Boolean(facility.refundPolicy ?? facility.refundOnMissedOrCancelled),
        ambulanceService: Boolean(facility.ambulanceSupport ?? facility.ambulanceService),
        slug,
        status: 'pending',
        details: {
          timing: facility.timing || '',
          established: facility.established || '',
          website: facility.website || '',
          services: services || [],
          insurance: facility.insurance || [],
          amenities: facility.amenities || {},
          socialLinks: facility.socialLinks || {},
          appointmentModes: facility.appointmentModes || ['chat', 'video', 'offline'],
          appointmentFees: facility.appointmentFees || { chat: 300, video: 500, offline: 500 },
          emergencySupport: Boolean(facility.emergencySupport),
          refundOnMissedOrCancelled: facility.refundOnMissedOrCancelled !== false,
        },
        nablNumber: facility.nablNumber || '',
        aerbNumber: facility.aerbNumber || '',
        pathologistName: specialist?.pathologistName || '',
        pathologistQualification: specialist?.pathologistQualification || '',
        radiologistName: specialist?.radiologistName || '',
        radiologistQualification: specialist?.radiologistQualification || '',
        cardiologistName: specialist?.cardiologistName || '',
        cardiologistQualification: specialist?.cardiologistQualification || '',
      });

      const clinicUser = await User.create({
        name: account.name,
        email: account.email.toLowerCase(),
        password: hashedPassword,
        role: roleMap[type] || 'clinic_doctor',
        phone: account.phone,
        facilityId: entity._id,
        facilityType: type,
        isVerified: false,
        status: 'inactive',
        approvalStatus: 'pending',
      });

      // If Clinic Doctor, also create Doctor profile for discovery & booking
      if (type === 'clinic') {
        const chatFee = facility.appointmentFees?.chat || 300;
        const videoFee = facility.appointmentFees?.video || 500;
        const offlineFee = facility.appointmentFees?.offline || 500;
        const homeVisitFee = facility.appointmentFees?.home_visit || 800;

        await Doctor.create({
          user_id: clinicUser._id,
          name: account.name,
          email: account.email.toLowerCase(),
          phone: account.phone,
          specialization: facility.specialties?.[0] || 'General Medicine',
          experience: facility.established ? `${new Date().getFullYear() - Number(facility.established)} years` : '3 years',
          consultation_fees: offlineFee,
          chat_fee: chatFee,
          video_fee: videoFee,
          offline_fee: offlineFee,
          home_visit_fee: homeVisitFee,
          appointmentModes: facility.appointmentModes || ['chat', 'video', 'offline', 'home_visit'],
          appointmentFees: { chat: chatFee, video: videoFee, offline: offlineFee, home_visit: homeVisitFee },
          emergencySupport: Boolean(facility.emergencySupport),
          refundOnMissedOrCancelled: facility.refundOnMissedOrCancelled !== false,
          emergency_consultation: Boolean(facility.emergencySupport),
          facilityId: entity._id,
          facilityType: 'clinic',
          doctor_type: 'clinic',
          approved: false,
        });
      }
    }

    const user = await User.findOne({ email: account.email.toLowerCase() });

    // Hospital ambulances at signup (Doc 02 §3.3) — created now, but dispatch
    // only routes to them once the hospital is approved (status filter).
    if (type === 'hospital' && ambulances?.length && entity?._id) {
      const { default: Ambulance } = await import('../models/Ambulance.js');
      const { createAmbulanceLogin } = await import('../services/ambulanceLoginService.js');
      for (const a of ambulances) {
        if (!a.registrationNumber?.trim()) continue;
        try {
          const amb = await Ambulance.create({
            hospitalId: entity._id,
            registrationNumber: a.registrationNumber.trim().toUpperCase(),
            vehicleModel: a.vehicleModel || '',
            ambulanceType: ['BLS', 'ALS', 'PATIENT_TRANSPORT', 'MORTUARY'].includes(a.ambulanceType) ? a.ambulanceType : 'BLS',
            equipmentLevel: a.equipmentLevel || '',
            driverName: a.driverName || '',
            driverPhone: a.driverPhone || '',
            currentDriverPhone: a.driverPhone || '',
            loginEmail: (a.loginEmail || '').toLowerCase(),
            isOnline: false, isOnDuty: false,
          });
          if (a.loginEmail?.trim()) {
            try { await createAmbulanceLogin(amb, { _id: user._id }); } catch {}
          }
        } catch {}
      }
    }

    if (doctors?.length) {
      for (const doc of doctors) {
        if (!doc.name || !doc.specialization) continue;
        const docEmail = doc.email || `${doc.name.toLowerCase().replace(/\s+/g, '.')}@${slug}.findmedi.app`;
        const tempPassword = randomPassword(12);
        const docChatFee = doc.appointmentFees?.chat || doc.chatFee || 300;
        const docVideoFee = doc.appointmentFees?.video || doc.videoFee || 500;
        const docOfflineFee = doc.appointmentFees?.offline || doc.offlineFee || doc.consultationFee || 500;
        const docHomeVisitFee = doc.appointmentFees?.home_visit || doc.homeVisitFee || 800;

        const docUser = await User.create({
          name: doc.name,
          email: docEmail.toLowerCase(),
          password: tempPassword,
          mustResetPassword: true,
          role: 'doctor',
          phone: doc.phone || account.phone,
          ...(type === 'hospital' ? { hospitalId: entity._id } : { facilityId: entity._id, facilityType: type }),
          specialization: doc.specialization || '',
          experience: doc.experience || '',
          qualification: doc.qualifications || '',
          licenseNumber: doc.licenseNumber || '',
          consultationFee: docOfflineFee,
          // ADM-B-05: this endpoint is unauthenticated, so a doctor created here
          // used to come out PRE-APPROVED (isVerified + approvalStatus:approved +
          // Doctor.approved:true) — an anonymous caller could mass-create approved
          // clinicians (records:read/write, bookable profile) and mail credentials
          // to arbitrary third-party addresses. Doctors now land in the normal
          // approval queue; the credential mail still goes out so onboarding works.
          isVerified: false,
          status: 'active',
          approvalStatus: 'pending',
        });

        await Doctor.create({
          userId: docUser._id,
          user_id: docUser._id,
          name: doc.name,
          email: docEmail.toLowerCase(),
          phone: doc.phone || account.phone,
          specialization: doc.specialization,
          qualifications: doc.qualifications || '',
          experience: parseInt(doc.experience) || 0,
          licenseNumber: doc.licenseNumber || '',
          consultation_fees: docOfflineFee,
          chat_fee: docChatFee,
          video_fee: docVideoFee,
          offline_fee: docOfflineFee,
          home_visit_fee: docHomeVisitFee,
          appointmentModes: doc.appointmentModes || facility.appointmentModes || ['chat', 'video', 'offline', 'home_visit'],
          appointmentFees: { chat: docChatFee, video: docVideoFee, offline: docOfflineFee, home_visit: docHomeVisitFee },
          emergencySupport: doc.emergencySupport !== undefined ? Boolean(doc.emergencySupport) : Boolean(facility.emergencySupport),
          refundOnMissedOrCancelled: doc.refundOnMissedOrCancelled !== undefined ? Boolean(doc.refundOnMissedOrCancelled) : facility.refundOnMissedOrCancelled !== false,
          ...(type === 'hospital' ? { hospitalId: entity._id } : { facilityId: entity._id, facilityType: type }),
          // ADM-B-05: the profile is created UNAPPROVED (see the user above) —
          // a superadmin must verify the licence before the doctor is bookable.
          approved: false,
        });

        void import('../lib/queues.js')
          .then((m) => m.queueEmailOrSend({
            to: docEmail.toLowerCase(),
            subject: 'Your FindMedi Doctor Account Credentials',
            text: `Hi ${doc.name},\n\nYou have been registered on FindMedi by ${account.name}.\n\nLogin: ${docEmail.toLowerCase()}\nTemporary Password: ${tempPassword}\n\nPlease login and change your password.\n\nRegards,\nFindMedi Team`,
          }))
          .catch(() => {});
      }
    }

    await createAndSendOTP({ userId: user._id, email: user.email, type: 'email' });

    res.status(201).json({
      message: 'Registration submitted. Please verify your email to continue.',
      requiresVerification: true,
      email: account.email,
      [type === 'hospital' ? 'hospitalId' : 'facilityId']: entity._id,
    });
  } catch (err) {
    res.status(400).json({ message: err.message });
  }
});

// authz: public
router.get('/specialty-counts', async (req, res) => {
  try {
    const counts = await Doctor.aggregate([
      { $match: { approved: true } },
      { $group: { _id: '$specialtyCode', count: { $sum: 1 } } },
    ]);
    const result = {};
    for (const item of counts) {
      if (item._id) result[item._id] = item.count;
    }
    res.setHeader('Cache-Control', 'public, max-age=300');
    res.json(result);
  } catch (err) {
    res.status(500).json({ message: err.message });
  }
});

export default router;

import express from 'express';
import PlatformCoupon from '../models/PlatformCoupon.js';
import { protect, superadminOnly } from '../middleware/auth.js';
import { auditLog } from '../middleware/audit.js';
import { escapeRegex, capSearch } from '../utils/escapeRegex.js';

const router = express.Router();

router.get('/', protect, superadminOnly, async (req, res) => {
  try {
    const { status, search } = req.query;
    const filter = {};
    if (status === 'active') filter.isActive = true;
    if (status === 'inactive') filter.isActive = false;
    if (search) filter.code = new RegExp(escapeRegex(capSearch(search)), 'i');
    const coupons = await PlatformCoupon.find(filter).sort({ createdAt: -1 });
    res.json({ coupons });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.get('/stats', protect, superadminOnly, async (req, res) => {
  try {
