import express from 'express';
import crypto from 'node:crypto';
import bwipjs from 'bwip-js';
import QRCode from 'qrcode';
import PrintTemplate from '../models/PrintTemplate.js';
import PrintLog from '../models/PrintLog.js';
import User from '../models/User.js';
import Bed from '../models/Bed.js';
import Medicine from '../models/Medicine.js';
import LabOrder from '../models/LabOrder.js';
import { protect } from '../middleware/auth.js';
import { auditLog } from '../middleware/audit.js';
import { renderTemplate, lintTemplate, toEscPos, VARIABLE_REGISTRY } from '../lib/printEngine.js';
import logger from '../config/logger.js';

// File 14 §14.2 + §14.4: print templates, browser-print rendering, thermal
// ESC/POS, labels (Code128/QR, opaque IDs only — never PHI in barcodes),
// and scan-to-verify checkpoints (5-rights hard stops).

const router = express.Router();
router.use(protect);

const actorId = (req) => req.user._id ?? req.user.id;
const OBJECT_ID = /^[0-9a-f]{24}$/i;

// ─── Templates ──────────────────────────────────────────────────────────────
router.get('/templates', async (req, res) => {
  try {
    const { docType } = req.query;
    const filter = {};
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }
    if (docType) filter.docType = docType;
    const rows = await PrintTemplate.find(filter).sort({ docType: 1, version: -1 }).limit(200).lean();
    return res.json({ templates: rows, registry: VARIABLE_REGISTRY });
  } catch (err) {
    logger.error(`Print templates error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

router.post('/templates', async (req, res) => {
  try {
    const { docType, name, html, css, pageSetup, languages } = req.body || {};
    if (!docType || !name) return res.status(400).json({ message: 'docType + name required' });
    const unknown = lintTemplate(docType, html || '');
    if (unknown.length) return res.status(400).json({ message: `Unknown variables: ${unknown.join(', ')}`, unknown });
    const latest = await PrintTemplate.findOne({ hospitalId: req.user.hospitalId, docType }).sort({ version: -1 }).lean();
    const row = await PrintTemplate.create({
      hospitalId: req.user.hospitalId, docType, name, html: html || '', css: css || '',
      pageSetup: pageSetup || {}, languages: languages || ['en'],
      version: (latest?.version || 0) + 1, createdBy: actorId(req),
    });
    return res.status(201).json({ id: String(row._id), version: row.version });
  } catch (err) {
    logger.error(`Print template error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

// ─── Render (browser print HTML + logged hash; reprints watermarked) ────────
router.post('/render', async (req, res) => {
  try {
    const { docType, data, entityRef, channel, escpos } = req.body || {};
    const template = await PrintTemplate.findOne({
      hospitalId: req.user.hospitalId, docType, status: 'Approved',
    }).sort({ version: -1 });
    if (!template) return res.status(404).json({ message: 'No approved template for this docType' });
    const prior = entityRef ? await PrintLog.countDocuments({ docType, entityRef }) : 0;
    const { html, hash } = renderTemplate(template.html, template.css, data || {}, { duplicate: prior > 0 });
    await PrintLog.create({
      hospitalId: req.user.hospitalId, docType, entityRef: entityRef || '',
      templateVersion: template.version, printedBy: actorId(req),
      copies: 1, isDuplicate: prior > 0, channel: channel || 'print', hash,
    });
    if (escpos) {
      const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      return res.json({ escpos: toEscPos([`${docType.toUpperCase()} ${entityRef || ''}`, text.slice(0, 200)]), hash, isDuplicate: prior > 0 });
    }
    return res.json({ html, hash, isDuplicate: prior > 0, version: template.version });
  } catch (err) {
    logger.error(`Print render error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

// ─── Labels (Code128 + QR, opaque IDs) ──────────────────────────────────────
router.post('/labels/render', async (req, res) => {
  try {
    const { type, code, title, subtitle } = req.body || {};
    if (!['uhid', 'accession', 'bed', 'unit', 'generic'].includes(type) || !code) {
      return res.status(400).json({ message: 'type=uhid|accession|bed|unit|generic + code required' });
    }
    const png = await bwipjs.toBuffer({
      bcid: 'code128', text: String(code).slice(0, 60),
      scale: 3, height: 12, includetext: true, textxalign: 'center',
    });
    const qr = await QRCode.toDataURL(`https://app/p/${encodeURIComponent(String(code).slice(0, 60))}`);
    const zpl = `^XA^FO20,20^A0N,40,40^FD${String(title || type).slice(0, 40)}^FS`
      + `^FO20,70^BCN,80,Y,N,N^FD${String(code).slice(0, 40)}^FS`
      + `^FO20,170^A0N,28,28^FD${String(subtitle || '').slice(0, 48)}^FS^XZ`;
    return res.json({ png: png.toString('base64'), qr, zpl });
  } catch (err) {
    logger.error(`Label error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

// ─── Scan-to-verify checkpoints (5 rights hard stops) ───────────────────────
const resolvePatient = async (code) => {
  if (!code) return null;
  if (OBJECT_ID.test(String(code))) {
    const u = await User.findById(code).select('_id').lean();
    return u ? String(u._id) : null;
  }
  const u = await User.findOne({ uhid: String(code) }).select('_id').lean();
  return u ? String(u._id) : null;
};

router.post('/scan/verify', async (req, res) => {
  try {
    const { context, scans, expected, secondUserId } = req.body || {};
    if (!['mar', 'sample', 'transfusion', 'ot_timeout', 'handover', 'bed'].includes(context)) {
      return res.status(400).json({ message: 'Invalid context' });
    }
    if (!Array.isArray(scans) || !scans.length) return res.status(400).json({ message: 'scans[] required' });
    const mismatches = [];
    const patientScans = scans.filter((s) => s.kind === 'patient');
    const resolved = [];
    for (const s of patientScans) {
      const pid = await resolvePatient(s.code);
      if (!pid) mismatches.push({ scan: s.code, reason: 'unknown-patient-code' });
      else resolved.push(pid);
    }
    if (new Set(resolved).size > 1) mismatches.push({ reason: 'patient-mismatch' });
    if (expected?.patientId && resolved.length && !resolved.includes(String(expected.patientId))) {
      mismatches.push({ reason: 'wrong-patient' });
    }
    // Existence checks for non-patient scans (drug/tube/unit/bed/procedure).
    for (const s of scans.filter((s) => s.kind !== 'patient')) {
      let ok = false;
      if (s.kind === 'drug') ok = Boolean(await Medicine.exists({ $or: [{ _id: OBJECT_ID.test(String(s.code)) ? s.code : null }, { name: String(s.code) }] }));
      else if (s.kind === 'tube') ok = Boolean(await LabOrder.exists({ $or: [{ orderId: String(s.code) }, ...(OBJECT_ID.test(String(s.code)) ? [{ _id: s.code }] : [])] }));
      else if (s.kind === 'bed') ok = Boolean(await Bed.exists({ $or: [{ bedNumber: String(s.code) }, ...(OBJECT_ID.test(String(s.code)) ? [{ _id: s.code }] : [])] }));
      else if (s.kind === 'procedure') ok = String(s.code) === String(expected?.procedure || s.code);
      else if (s.kind === 'unit') ok = true; // unit registry check lives in blood-bank flow
      if (!ok) mismatches.push({ scan: s.code, reason: `unknown-${s.kind}` });
    }
    // Transfusion needs a second person (2-person check).
    if (context === 'transfusion') {
      if (!secondUserId || String(secondUserId) === String(actorId(req))) {
        mismatches.push({ reason: 'second-checker-required' });
      }
    }
    const ok = mismatches.length === 0;
    await auditLog(ok ? 'scan_verified' : 'scan_mismatch', actorId(req), {
      context, scans: scans.length, mismatches, ip: req.ip,
    }).catch(() => {});
    return res.json({ ok, mismatches });
  } catch (err) {
    logger.error(`Scan verify error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

export default router;

import express from 'express';
import crypto from 'node:crypto';
import Provider from '../models/Provider.js';
import ProviderStaffInvite from '../models/ProviderStaffInvite.js';
import User from '../models/User.js';
import { protect } from '../middleware/auth.js';
import { generalLimiter } from '../middleware/rateLimit.js';
import { auditLog } from '../middleware/audit.js';
import { sendEmail } from '../services/notificationService.js';
import { PROVIDER_STAFF_TEMPLATES, roleRequiresTwoFactor } from '../lib/providerStaffRoles.js';
import { validate, providerStaffInviteSchema } from '../utils/validate.js';
import logger from '../config/logger.js';

// 2.md 9 — the provider owner's side of staff invitation: list the team, issue
// a single-use expiring invite for one of the role TEMPLATES, revoke one.
//
// The REDEMPTION half lives in routes/auth.js (`POST /api/auth/provider-staff-setup`)
// beside doctor-setup/ambulance-setup, because it is a public password-setting
// flow with the same rate limit and the same shape.
//
// Authz model: the caller must be the listing's `ownerUserId`. A foreign id
// answers 404, never 403 — a 403 would confirm the listing exists (AUTHZ-B-04).
// No authorize() marker is needed: this is the same "self" ownership rule
// routes/join.js uses, enforced in the loader rather than by role.

const router = express.Router();

// 2.md 14: same rate-limit-before-auth ordering as routes/join.js.
router.use(generalLimiter, protect);

const OBJECT_ID = /^[0-9a-f]{24}$/i;
const INVITE_TTL_HOURS = 48;

async function loadOwnedProvider(req, res, providerId) {
  const caller = String(req.user._id ?? req.user.id ?? '');
  if (providerId) {
    if (!OBJECT_ID.test(String(providerId))) {
      res.status(404).json({ message: 'Not found' });
      return null;
    }
    const provider = await Provider.findOne({ _id: providerId, ownerUserId: caller });
    if (!provider) {
      res.status(404).json({ message: 'Not found' });
      return null;
    }
    return provider;
  }
  const owned = await Provider.find({ ownerUserId: caller }).select('_id name status').limit(2).lean();
  if (owned.length === 0) {
    res.status(404).json({ message: 'No provider listing is linked to this account' });
    return null;
  }
  if (owned.length > 1) {
    res.status(400).json({ message: 'This account owns more than one listing — pass providerId' });
    return null;
  }
  return Provider.findOne({ ownerUserId: caller });
}

// authz: self (owner of the listing)
//
// Team + pending invites for the owner's listing (2.md 9 status view).
router.get('/', async (req, res) => {
  try {
    const provider = await loadOwnedProvider(req, res, req.query.providerId);
    if (!provider) return null;

    const staffIds = (provider.staff ?? []).map((row) => row.userId);
    const [users, invites] = await Promise.all([
      staffIds.length > 0
        ? User.find({ _id: { $in: staffIds } }).select('name email role twoFactorEnabled').lean()
        : Promise.resolve([]),
      ProviderStaffInvite.find({
        providerId: provider._id,
        usedAt: null,
        revokedAt: null,
        expiresAt: { $gt: new Date() },
      }).select('email template role expiresAt createdAt').sort({ createdAt: -1 }).lean(),
    ]);
    const byId = new Map(users.map((u) => [String(u._id), u]));

    return res.json({
      provider: { _id: provider._id, name: provider.name, status: provider.status },
      staff: (provider.staff ?? []).map((row) => {
        const user = byId.get(String(row.userId)) ?? {};
        return {
          userId: row.userId,
          name: user.name ?? '',
          email: user.email ?? '',
          role: row.role,
          addedAt: row.addedAt,
          twoFactorEnabled: Boolean(user.twoFactorEnabled),
        };
      }),
      invites: invites.map((row) => ({
        _id: row._id,
        email: row.email,
        template: row.template,
        role: row.role,
        expiresAt: row.expiresAt,
        twoFactorRequired: roleRequiresTwoFactor(row.role),
      })),
      templates: Object.entries(PROVIDER_STAFF_TEMPLATES).map(([key, value]) => ({
        key, role: value.role, label: value.label, description: value.description,
        twoFactorRequired: roleRequiresTwoFactor(value.role),
      })),
    });
  } catch (err) {
    return res.status(400).json({ message: err.message });
  }
});

// authz: self (owner of the listing)
//
// Issue an invite (2.md 9). The client sends a TEMPLATE KEY; the role comes
// from PROVIDER_STAFF_TEMPLATES — no role from the client, exactly like
// routes/join.js takes no kind/tier from the client. The 128-bit code exists
// only inside the email; the API response never carries it.
router.post('/invite', validate(providerStaffInviteSchema), async (req, res) => {
  try {
    const { template, email, name, providerId } = req.body;
    const provider = await loadOwnedProvider(req, res, providerId);
    if (!provider) return null;

    const spec = PROVIDER_STAFF_TEMPLATES[template];

    const existingUser = await User.findOne({ email }).select('_id').lean();
    if (existingUser && (provider.staff ?? []).some((row) => String(row.userId) === String(existingUser._id))) {
      return res.status(409).json({ message: 'That person is already on this listing' });
    }
    const pending = await ProviderStaffInvite.exists({
      providerId: provider._id,
      email,
      usedAt: null,
      revokedAt: null,
      expiresAt: { $gt: new Date() },
    });
    if (pending) return res.status(409).json({ message: 'An invitation is already pending for that email' });

    const code = crypto.randomBytes(16).toString('base64url');
    const invite = await ProviderStaffInvite.create({
      code,
      providerId: provider._id,
      template,
      role: spec.role,
      email,
      name: name ?? '',
      invitedBy: req.user._id ?? req.user.id,
      expiresAt: new Date(Date.now() + INVITE_TTL_HOURS * 3600 * 1000),
    });

    const setupUrl = `${process.env.CLIENT_URL || 'http://localhost:5173'}/#/provider-staff-setup?code=${encodeURIComponent(code)}`;
    try {
      await sendEmail({
        to: email,
        subject: `You've been invited to join ${provider.name} on FindMedi`,
        html: `
          <div style="font-family: Arial, sans-serif; max-width: 600px; margin: auto; padding: 20px;">
            <h2 style="color: #0b8a72;">FindMedi team invitation</h2>
            <p>${name ? `${name}, you have` : 'You have'} been invited to join <strong>${provider.name}</strong> as <strong>${spec.label}</strong>.</p>
            <a href="${setupUrl}" style="display: inline-block; padding: 12px 24px; background: #0b8a72; color: white; text-decoration: none; border-radius: 6px; font-size: 16px;">Accept Invitation</a>
            <p style="margin-top: 24px; color: #666;">This single-use link expires in ${INVITE_TTL_HOURS} hours. If you did not expect this invitation, ignore this email.</p>
          </div>`,
        text: `You have been invited to join ${provider.name} on FindMedi as ${spec.label}. Accept here (expires in ${INVITE_TTL_HOURS}h): ${setupUrl}`,
      });
    } catch (err) {
      // The code only exists in the email — if the email never left, the invite
      // is worthless, so clean it up rather than leaving a dead pending row.
      await ProviderStaffInvite.deleteOne({ _id: invite._id }).catch(() => {});
      logger.warn(`provider staff invite email failed: ${err.message}`);
      return res.status(502).json({ message: 'Could not send the invitation email, please retry' });
    }

    await auditLog('provider_staff_invited', req.user._id ?? req.user.id, {
      providerId: String(provider._id),
      inviteId: String(invite._id),
      template,
      role: spec.role,
      email,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });

    return res.status(201).json({
      invite: {
        _id: invite._id,
        email: invite.email,
        template: invite.template,
        role: invite.role,
        expiresAt: invite.expiresAt,
      },
      twoFactorRequired: roleRequiresTwoFactor(spec.role),
    });
  } catch (err) {
    return res.status(400).json({ message: err.message });
  }
});

// authz: self (owner of the listing)
//
// Revoke a still-pending invite. A redeemed one is left alone — the audit trail
// of who joined matters more than tidiness.
router.delete('/invites/:id', async (req, res) => {
  try {
    if (!OBJECT_ID.test(String(req.params.id))) {
      return res.status(404).json({ message: 'Not found' });
    }
    const provider = await loadOwnedProvider(req, res, req.query.providerId);
    if (!provider) return null;

    const invite = await ProviderStaffInvite.findOne({
      _id: req.params.id,
      providerId: provider._id,
      usedAt: null,
    });
    if (!invite) return res.status(404).json({ message: 'No pending invitation with that id' });

    invite.revokedAt = new Date();
    await invite.save();

    await auditLog('provider_staff_invite_revoked', req.user._id ?? req.user.id, {
      providerId: String(provider._id),
      inviteId: String(invite._id),
      email: invite.email,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });
    return res.json({ ok: true });
  } catch (err) {
    return res.status(400).json({ message: err.message });
  }
});

export default router;

import express from 'express';
import NabhChapter, { NABH_SEED } from '../models/NabhChapter.js';
import NabhAssessment from '../models/NabhAssessment.js';
import Capa from '../models/Capa.js';
import PcpndtFormF from '../models/PcpndtFormF.js';
import MtpRegister from '../models/MtpRegister.js';
import { protect, authorize } from '../middleware/auth.js';
import { auditLog } from '../middleware/audit.js';
import logger from '../config/logger.js';

// File 22 P2-30: NABH chapters + assessments (auto-KPIs resolved live),
// CAPA ledger, PCPNDT Form F + MTP registers.

const router = express.Router();
router.use(protect);

const actorId = (req) => req.user._id ?? req.user.id;
const tenant = (req) => ({ hospitalId: req.user.hospitalId });

// NOTE: explicit single-line heads (routeScan inventory).

router.get('/chapters', authorize('staff:view'), async (req, res) => {
  try {
    const rows = await NabhChapter.find({}).sort({ code: 1 }).lean();
    return res.json({ chapters: rows });
  } catch (err) {
    logger.error(`NABH chapters error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

router.post('/chapters/seed', authorize('staff:manage'), async (req, res) => {
  try {
    let created = 0;
    for (const s of NABH_SEED) {
      // eslint-disable-next-line no-await-in-loop
      const r = await NabhChapter.findOneAndUpdate(
        { code: s.code }, { $setOnInsert: { title: s.title, objectives: s.objectives } }, { upsert: true, new: true },
      );
      if (r) created += 1;
    }
    return res.status(201).json({ chapters: created });
  } catch (err) {
    logger.error(`NABH seed error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

// Assessment with auto-KPI resolution (insights compute, same hospital).
router.post('/assessments', authorize('staff:manage'), async (req, res) => {
  try {
    const { chapter, scores } = req.body || {};
    if (!chapter || !scores) return res.status(400).json({ message: 'chapter + scores required' });
    const chap = await NabhChapter.findOne({ code: chapter }).lean();
    if (!chap) return res.status(404).json({ message: 'Unknown chapter' });
    const autoValues = {};
    const autoKeys = [...new Set((chap.objectives || []).map((o) => o.autoKpi).filter(Boolean))];
    if (autoKeys.length) {
      // Reuse the insights KPI compute through an internal call (same data,
      // no HTTP round-trip): replicate the minimal queries here would fork
      // the formulas, so instead we store the keys and resolve at read.
      autoValues._keys = autoKeys;
    }
    const vals = Object.values(scores || {});
    const counted = vals.filter((v) => v !== 'na');
    const pts = counted.reduce((s, v) => s + (v === 'compliant' ? 1 : v === 'partial' ? 0.5 : 0), 0);
    const scorePct = counted.length ? Math.round((pts / counted.length) * 100) : null;
    const row = await NabhAssessment.create({
      ...tenant(req), chapter, scores, autoValues, scorePct, assessor: actorId(req),
    });
    await auditLog('nabh_assessed', actorId(req), { chapter, scorePct, ip: req.ip });
    return res.status(201).json({ id: String(row._id), scorePct });
  } catch (err) {
    logger.error(`NABH assess error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

router.get('/assessments', authorize('staff:view'), async (req, res) => {
  try {
    const filter = tenant(req);
    if (req.query.chapter) filter.chapter = req.query.chapter;
    const rows = await NabhAssessment.find(filter).sort({ assessedAt: -1 }).limit(100).lean();
    return res.json({ assessments: rows });
  } catch (err) {
    logger.error(`NABH list error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

// Auto-KPI keys stored at assess time; the dashboard joins live values
// from GET /api/insights/kpis/compute (single source of formulas).
router.get('/assessments/:id/auto', authorize('staff:view'), async (req, res) => {
  try {
    const row = await NabhAssessment.findOne({ _id: req.params.id, ...tenant(req) }).lean();
    if (!row) return res.status(404).json({ message: 'Not found' });
    return res.json({ keys: row.autoValues?._keys || [], join: '/api/insights/kpis/compute' });
  } catch (err) {
    logger.error(`NABH auto error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

router.get('/capa', authorize('staff:view'), async (req, res) => {
  try {
    const filter = tenant(req);
    if (req.query.status) filter.status = req.query.status;
    const rows = await Capa.find(filter).sort({ createdAt: -1 }).limit(300).lean();
    return res.json({ capa: rows });
  } catch (err) {
    logger.error(`CAPA list error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
