// Doctor: create a new schedule change request
router.post('/', protect, validate(createScheduleChangeRequestSchema), async (req, res) => {
  try {
    if (req.user.role !== 'doctor' && req.user.role !== 'counsellor' && req.user.role !== 'psychiatrist') {
      return res.status(403).json({ message: 'Only doctors can request schedule changes' });
    }
    const doctor = await Doctor.findOne({ email: req.user.email });
    if (!doctor) return res.status(404).json({ message: 'Doctor profile not found' });

    // Reject if there's already a Pending request for this doctor
    const existingPending = await ScheduleChangeRequest.findOne({ doctorId: doctor._id, status: 'Pending' });
    if (existingPending) {
      return res.status(409).json({ message: 'You already have a pending change request. Please wait for admin review.' });
    }

    const rc = req.body.requestedChanges || {};

    // Snapshot the doctor's CURRENT values for every field the doctor is requesting to change.
    // This powers the "old → new" highlight text later and stays accurate even if the doctor edits again.
    const oldValues = {};
    if (rc.slotDuration != null) oldValues.slotDuration = doctor.slotDuration;
    if (rc.workingHours) oldValues.workingHours = { start: doctor.workingHours?.start, end: doctor.workingHours?.end };
    if (rc.breakTime) oldValues.breakTime = { start: doctor.breakTime?.start, end: doctor.breakTime?.end };
    if (rc.bookingWindow) oldValues.bookingWindow = { unit: doctor.bookingWindow?.unit, value: doctor.bookingWindow?.value };
    if (rc.weekly_schedule) oldValues.weekly_schedule = doctor.weekly_schedule || {};
    if (rc.leaves != null) oldValues.leaves = doctor.leaves || [];
    if (rc.dateDisabledSlots) oldValues.dateDisabledSlots = doctor.dateDisabledSlots || {};
    if (rc.bufferPerHour != null) oldValues.bufferPerHour = doctor.bufferPerHour;

    const request = await ScheduleChangeRequest.create({
      doctorId: doctor._id,
      doctorName: req.user.name,
      doctorEmail: req.user.email,
      hospitalId: req.user.hospitalId || doctor.hospitalId,
      status: 'Pending',
      requestedChanges: rc,
      oldValues,
    });

    // Notify all hospital admins
    try {
      const User = (await import('../models/User.js')).default;
      const admins = await User.find({ role: 'hospital_admin', hospitalId: doctor.hospitalId }).select('_id');
      for (const a of admins) {
        await createNotification(a._id.toString(), 'Schedule Change Request', `${req.user.name} requested schedule changes`, 'system');
      }
    } catch (_) {}

    await createNotification(req.user._id.toString(), 'Request Submitted', 'Your schedule change request has been submitted for admin review.', 'system');

    res.status(201).json(request);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

// Doctor: cancel their own pending request (withdraws the request, removes the blur on their page)
router.put('/:id/cancel', protect, async (req, res) => {
  try {
    const request = await ScheduleChangeRequest.findById(req.params.id);
    if (!request) return res.status(404).json({ message: 'Request not found' });
    if (request.status !== 'Pending') {
      return res.status(400).json({ message: `Request already ${request.status.toLowerCase()} — cannot cancel` });
    }
    // Only the requesting doctor can cancel their own request
    if (req.user.role === 'doctor' || req.user.role === 'counsellor' || req.user.role === 'psychiatrist') {
      const doctor = await Doctor.findOne({ email: req.user.email });
      if (!doctor || doctor._id.toString() !== request.doctorId.toString()) {
        return res.status(403).json({ message: 'You can only cancel your own requests' });
      }
    }

    request.status = 'Cancelled';
    request.reviewedAt = new Date();
    await request.save();

    // Notify the doctor via WebSocket — auto-removes blur on their page
    try {
      const User = (await import('../models/User.js')).default;
      const doctorUser = await User.findOne({ email: request.doctorEmail });
      if (doctorUser) emitScheduleRequestUpdate(doctorUser._id.toString(), { requestId: request._id, status: 'Cancelled' });
    } catch (_) {}

    res.json(request);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

// Admin: pending queue
router.get('/pending', protect, async (req, res) => {
  try {
    const filter = { status: 'Pending' };
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }
    const requests = await ScheduleChangeRequest.find(filter)
      .populate('doctorId', 'name email specialization slotDuration workingHours breakTime bookingWindow weekly_schedule leaves dateDisabledSlots bufferPerHour')
      .sort({ createdAt: 1 });
    res.json({ requests });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

// Admin: approve (apply only checkbox-selected fields) or reject
router.put('/:id/decision', protect, adminOnly, validate(updateScheduleChangeStatusSchema), async (req, res) => {
  try {
    const { decision, appliedFields = [], adminNote = '', rejectionNote = '' } = req.body;
    const request = await ScheduleChangeRequest.findById(req.params.id);
    if (!request) return res.status(404).json({ message: 'Request not found' });
    if (request.status !== 'Pending') return res.status(400).json({ message: 'Request already reviewed' });

    if (decision === 'approve' && appliedFields.length > 0) {
      const doctor = await Doctor.findById(request.doctorId);
      if (!doctor) return res.status(404).json({ message: 'Doctor not found' });

      const rc = request.requestedChanges || {};
      const update = {};
      let needsSlotRegen = false;
      let wh = doctor.workingHours || { start: '09:00', end: '17:00' };
      let sd = doctor.slotDuration || 15;
      let bt = doctor.breakTime || { start: '', end: '' };

      if (appliedFields.includes('slotDuration') && rc.slotDuration != null) {
        update.slotDuration = rc.slotDuration; sd = rc.slotDuration; needsSlotRegen = true;
      }
      if (appliedFields.includes('workingHours') && rc.workingHours) {
        update.workingHours = rc.workingHours; wh = rc.workingHours; needsSlotRegen = true;
      }
      if (appliedFields.includes('breakTime') && rc.breakTime) {
        update.breakTime = rc.breakTime; bt = rc.breakTime; needsSlotRegen = true;
      }
      if (appliedFields.includes('bookingWindow') && rc.bookingWindow) update.bookingWindow = rc.bookingWindow;
      if (appliedFields.includes('weekly_schedule') && rc.weekly_schedule) update.weekly_schedule = rc.weekly_schedule;
      if (appliedFields.includes('leaves') && rc.leaves) update.leaves = rc.leaves;
      if (appliedFields.includes('dateDisabledSlots') && rc.dateDisabledSlots) update.dateDisabledSlots = rc.dateDisabledSlots;
      if (appliedFields.includes('bufferPerHour') && rc.bufferPerHour != null) update.bufferPerHour = rc.bufferPerHour;

      // Regenerate time_slots if any timing-related field was applied
      if (needsSlotRegen) {
        update.time_slots = generateTimeSlots(wh.start, wh.end, sd, bt);
      }

      if (Object.keys(update).length > 0) {
        await Doctor.findByIdAndUpdate(request.doctorId, update);
      }

      // Determine which requested fields were NOT applied -> record as rejectionNote for visibility
      const allRequested = Object.keys(rc).filter(k => rc[k] != null);
      const notApplied = allRequested.filter(f => !appliedFields.includes(f));
      const finalRejectionNote = notApplied.length > 0
        ? `These changes were not applied: ${notApplied.join(', ')}.${rejectionNote ? ' ' + rejectionNote : ''}`
        : rejectionNote;

      request.status = 'Approved';
      request.appliedFields = appliedFields;
      request.adminNote = adminNote;
      request.rejectionNote = finalRejectionNote;
      request.reviewedBy = req.user._id;
      request.reviewedAt = new Date();
      await request.save();
    } else if (decision === 'reject') {
      request.status = 'Rejected';
      request.rejectionNote = rejectionNote || 'Request rejected by admin';
      request.adminNote = adminNote;
      request.reviewedBy = req.user._id;
      request.reviewedAt = new Date();
      await request.save();
    } else if (decision === 'approve' && appliedFields.length === 0) {
      // Admin confirmed but selected nothing -> treat as soft reject
      request.status = 'Rejected';
      request.rejectionNote = rejectionNote || 'No fields were selected for approval.';
      request.adminNote = adminNote;
      request.reviewedBy = req.user._id;
      request.reviewedAt = new Date();
      await request.save();
    }

    // Notify the doctor
    try {
      const User = (await import('../models/User.js')).default;
      const user = await User.findOne({ email: request.doctorEmail });
      if (user) {
        const msg = request.status === 'Approved'
          ? `Your schedule change request was approved.${request.appliedFields.length ? ' Applied: ' + request.appliedFields.join(', ') : ''}${request.rejectionNote ? ' | ' + request.rejectionNote : ''}`
          : `Your schedule change request was rejected.${request.rejectionNote ? ' Reason: ' + request.rejectionNote : ''}`;
        await createNotification(user._id.toString(), 'Schedule Request Update', msg, 'system');
        // WebSocket: auto-remove blur + render highlights on doctor's page (no refresh needed)
        emitScheduleRequestUpdate(user._id.toString(), { requestId: request._id, status: request.status });
      }
    } catch (_) {}

    res.json(request);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

export default router;

import express from 'express';
import { protect, adminOnly } from '../middleware/auth.js';
import { publicSearchLimiter } from '../middleware/rateLimit.js';
import { searchProviders, searchDrugs, searchEhr, isOpenSearchConfigured } from '../services/opensearchIndexer.js';
import { toSearchCard } from '../utils/searchDto.js';
import { expandSearchQuery } from '../config/searchTaxonomy.js';
import { SPECIALTIES, isTopLevelSpecialty, resolveSpecialtyCode } from '../lib/taxonomy.js';
import { escapeRegex } from '../utils/escapeRegex.js';
import logger from '../config/logger.js';
import mongoose from 'mongoose';
import { assertEhrSearchAccess } from '../services/ehrSearchAccess.js';
import { sendServerError } from '../utils/safeError.js';
import { roleHasPermission } from '../config/permissions.js';

const router = express.Router();

// ─── GET /api/search?q=&type=&city=&lat=&lng= — public directory search ──────
// 10.md 4.1 (anonymous, cacheable, DTO-only). Same engine as the authenticated
// route below; what makes it public-safe is toSearchCard — an allowlist, since
// the OpenSearch path spreads index documents verbatim and nobody is logged in
// to vouch for what a future indexed field contains.
// authz: public
router.get('/', publicSearchLimiter, async (req, res) => {
  try {
    const { q, type, vertical, city, lat, lng, lon, radiusKm, size } = req.query;
    const lonValue = lng != null ? lng : lon;
    const out = await searchProviders({
      q,
      vertical: vertical ?? type,
      city,
      lat: lat != null ? Number(lat) : undefined,
      lon: lonValue != null ? Number(lonValue) : undefined,
      radiusKm: radiusKm != null ? Number(radiusKm) : undefined,
      size: Math.min(Number(size) || 20, 50),
    });
    res.set('Cache-Control', 'public, max-age=60');
    res.removeHeader('Pragma');
    res.json({
      success: true,
      engine: isOpenSearchConfigured() ? 'opensearch' : 'mongo',
      source: out.source,
      results: (out.results ?? []).map(toSearchCard),
    });
  } catch (err) {
    logger.error(`Public search error: ${err.message}`);
    res.status(500).json({ success: false, message: err.message });
  }
});

// ─── GET /api/search/suggest?q= — light typeahead for the browse UI ─────────
// Specialties search user spec c#4: suggestions come from the real taxonomy
// (tiles, sub-specialties, conditions, procedures, Hinglish symptoms), not
// generic strings. Sensitive tiles stay out of suggestions; red-flag queries
// surface the emergency banner inline.
// authz: public
router.get('/suggest', publicSearchLimiter, async (req, res) => {
  const q = String(req.query.q || '').toLowerCase().trim();
  const taxonomy = expandSearchQuery(q);
  const taxonomyPayload = {
    isEmergency: taxonomy.isEmergency,
    emergencyMessage: taxonomy.emergencyMessage,
    isSensitive: taxonomy.isSensitive,
    crisisHotline: taxonomy.crisisHotline,
  };
  if (q.length < 2) {
    return res.json({ success: true, q, results: [], taxonomy: taxonomyPayload });
  }

  // A sensitive tile hides itself and everything nested under it (child subs
  // inherit via parent walk; INFERT's IVF chip stays discreet too).
  const byLower = new Map(SPECIALTIES.map((s) => [s.code.toLowerCase(), s]));
  const isHidden = (entry) => {
    for (let hit = entry; hit; ) {
      if (hit.sensitive) return true;
      const parentCode = hit.code.split('.').slice(0, 2).join('.');
      hit = hit.code === parentCode ? null : byLower.get(parentCode.toLowerCase());
    }
    return false;
  };
  // Alias strings that name the sensitive surface itself (Sleep Psychiatry…)
  // must not leak the topic through a search for its own keyword.
  const SENSITIVE_TEXT_RE = /psychiatr|psycholog|sexolog|deaddiction|suicid|hiv|infertil|fertilit|\bivf\b|palliativ/i;

  const scored = [];
  for (const s of SPECIALTIES) {
    if (isHidden(s)) continue;
    const nm = s.name.toLowerCase();
    const subToken = s.code.split('.').pop().replace(/_/g, ' ').toLowerCase();
    const aliases = (s.aliases || []).map((a) => a.toLowerCase());
    let score = Infinity;
    let viaAliasMatch = null;
    if (nm === q) score = 0;
    else if (nm.startsWith(q)) score = 1;
    else if (nm.includes(q)) score = 2;
    else if (subToken.startsWith(q) && subToken.length > 3) score = 3;
    else if ((viaAliasMatch = aliases.find((a) => a.startsWith(q)))) score = 3.5;
    else if ((viaAliasMatch = aliases.find((a) => a.includes(q)))) score = 4;
    // A sensitive keyword must match nothing — not even an alias mention
    // ('Sleep Psychiatry' must not surface when the user types 'psych').
    if (score === Infinity || SENSITIVE_TEXT_RE.test(nm) || (viaAliasMatch && SENSITIVE_TEXT_RE.test(viaAliasMatch))) continue;
    scored.push({
      kind: 'specialty',
      score,
      item: {
        code: s.code,
        name: s.name,
        parent: isTopLevelSpecialty(s) ? null : s.code.split('.').slice(0, 2).join('.'),
        parentName: isTopLevelSpecialty(s)
          ? null
          : (byLower.get(s.code.split('.').slice(0, 2).join('.').toLowerCase())?.name || null),
        nameHi: s.meta?.nameHi || null,
      },
    });
  }

  // Symptom / condition / procedure chips resolve to their parent tile, so the
  // typeahead can plant a query already filtered by that specialty.
  for (const top of SPECIALTIES.filter(isTopLevelSpecialty)) {
    if (isHidden(top)) continue;
    const chipBase = { specialty: { code: top.code, name: top.name, nameHi: top.meta?.nameHi || null, icon: top.meta?.icon || null } };
    const matchChips = (list, kind, offset) => {
      for (const raw of list || []) {
        const lv = String(raw).toLowerCase();
        let rel = -1;
        if (lv === q) rel = 0;
        else if (lv.startsWith(q)) rel = 1;
        else if (lv.includes(q)) rel = 2;
        if (rel < 0) continue;
        scored.push({ kind, score: 5 + offset + rel, item: { ...chipBase, label: String(raw) } });
      }
    };
    matchChips(top.meta?.symptoms, 'symptom', 0);
    matchChips(top.meta?.conditions, 'condition', 1);
    matchChips(top.meta?.procedures, 'procedure', 2);
  }

  // Approved doctor-name suggestions are public directory data. Keep this
  // small and suppress any provider whose specialty surface is discreet.
  try {
    const { default: Doctor } = await import('../models/Doctor.js');
    const doctorMatches = await Doctor.find({
      approved: true,
      name: { $regex: new RegExp(escapeRegex(q), 'i') },
    })
      .select('_id name specialization specialtyCode subSpecialtyCodes location city')
      .sort({ rating: -1, name: 1 })
      .limit(5)
      .lean();
    for (const doctor of doctorMatches) {
      const providerCodes = [doctor.specialtyCode, ...(doctor.subSpecialtyCodes || [])]
        .map(resolveSpecialtyCode)
        .filter(Boolean);
      const discreet = providerCodes.some((code) => {
        const entry = byLower.get(code.toLowerCase());
        return entry ? isHidden(entry) : false;
      }) || SENSITIVE_TEXT_RE.test(String(doctor.specialization || ''));
      if (discreet) continue;
      scored.push({
        kind: 'doctor',
        score: 4.5,
        item: {
          id: String(doctor._id),
          code: String(doctor._id),
          name: doctor.name,
          specialization: doctor.specialization || '',
          city: doctor.city || doctor.location || '',
        },
      });
    }
  } catch (err) {
    logger.warn(`Specialty doctor suggestions unavailable: ${err?.message}`);
  }

  scored.sort((a, b) => a.score - b.score || String(a.item.label || a.item.name).localeCompare(String(b.item.label || b.item.name)));
  const results = scored.slice(0, 10).map(({ kind, item }) => ({ kind, ...item }));

  res.set('Cache-Control', 'public, max-age=300');
  res.json({ success: true, q, total: results.length, results, taxonomy: taxonomyPayload });
});

// ─── GET /api/search/providers?q=&vertical=&city=&lat=&lon=&radiusKm= ───────
