import express from 'express';
import {
  BRAND_FOUNDATION,
  SEO_SITE_ARCHITECTURE,
  generateSchemaOrgJsonLd,
  getSeoUrlForListing,
} from '../config/marketingSeo.js';
import City from '../models/City.js';
import ServiceCity from '../models/ServiceCity.js';
import Facility from '../models/Facility.js';
import Doctor from '../models/Doctor.js';
import HealthPackage from '../models/HealthPackage.js';
import logger from '../config/logger.js';

const router = express.Router();

let sitemapCache = null;
let sitemapCacheTime = 0;
const CACHE_TTL_MS = 60 * 60 * 1000; // 1 hour

export function clearSitemapCache() {
  sitemapCache = null;
  sitemapCacheTime = 0;
}

const CANONICAL_CATEGORIES = [
  { slug: 'doctors', name: 'Doctors & Specialists', type: 'hospital' },
  { slug: 'dentist', name: 'Dentists & Dental Clinics', type: 'clinic' },
  { slug: 'pharmacy', name: 'Pharmacies & Medical Stores', type: 'pharmacy' },
  { slug: 'diagnostic-lab', name: 'Diagnostic Labs & Pathology', type: 'lab' },
  { slug: 'home-visit', name: 'Home Care & Doctor Visit', type: 'clinic' },
  { slug: 'ayush', name: 'Ayurveda & Natural Care', type: 'clinic' },
  { slug: 'mental-health', name: 'Mental Health & Counseling', type: 'clinic' },
  { slug: 'specialty-care', name: 'Specialty Care Centers', type: 'hospital' },
];

function escapeXml(unsafe) {
  return String(unsafe || '').replace(/[<>&'"]/g, (c) => {
    switch (c) {
      case '<': return '&lt;';
      case '>': return '&gt;';
      case '&': return '&amp;';
      case '\'': return '&apos;';
      case '"': return '&quot;';
      default: return c;
    }
  });
}

function slugify(text) {
  return String(text || '')
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_-]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

/**
 * Builds the complete dynamic sitemap dataset respecting Document 21 SEO quality gates.
 */
export async function generateSitemapData(baseUrl) {
  const origin = (baseUrl || 'https://findmedi.in').replace(/\/+$/, '');
  const now = new Date().toISOString().split('T')[0];

  // 1. Static high-intent marketing pages
  const staticUrls = [
    { loc: `${origin}/`, changefreq: 'daily', priority: '1.0', lastmod: now },
    { loc: `${origin}/about`, changefreq: 'monthly', priority: '0.6', lastmod: now },
    { loc: `${origin}/contact`, changefreq: 'monthly', priority: '0.6', lastmod: now },
    { loc: `${origin}/privacy`, changefreq: 'monthly', priority: '0.5', lastmod: now },
    { loc: `${origin}/terms`, changefreq: 'monthly', priority: '0.5', lastmod: now },
    { loc: `${origin}/join`, changefreq: 'weekly', priority: '0.8', lastmod: now },
  ];

  // 2. Resolve Active Cities
  const [dbCities, serviceCities] = await Promise.all([
    City.find({ isActive: true }).select('name state').lean().catch(() => []),
    ServiceCity.find({ isActive: true }).select('name state').lean().catch(() => []),
  ]);

  const cityMap = new Map();
  // Pilot core cities from Document 21 always primed
  const defaultCities = [
    { name: 'Bhopal', state: 'Madhya Pradesh' },
    { name: 'Indore', state: 'Madhya Pradesh' },
    { name: 'Jabalpur', state: 'Madhya Pradesh' },
    { name: 'Gwalior', state: 'Madhya Pradesh' },
    { name: 'Ujjain', state: 'Madhya Pradesh' },
  ];
  for (const c of [...defaultCities, ...dbCities, ...serviceCities]) {
    if (c?.name) {
      const slug = slugify(c.name);
      if (!cityMap.has(slug)) {
        cityMap.set(slug, { name: c.name, state: c.state || 'India', slug });
      }
    }
  }
  const cities = Array.from(cityMap.values());

  // 3. Query approved verified providers
  const [facilities, doctors, packages] = await Promise.all([
    Facility.find({ status: 'approved' }).select('slug type city name updatedAt').lean().catch(() => []),
    Doctor.find({ approved: true }).select('doctorId specialization specialtyCode location updatedAt').lean().catch(() => []),
    HealthPackage.find({ isActive: true }).select('name category updatedAt').lean().catch(() => []),
  ]);

  const dynamicUrls = [];
  let thinPagesExcluded = 0;

  // 4. City Hub Pages: /<city>/
  for (const city of cities) {
    dynamicUrls.push({
      loc: `${origin}/${city.slug}/`,
      changefreq: 'weekly',
      priority: '0.8',
      lastmod: now,
    });

    // 5. City × Category Pages with Document 21 Quality Gate (min 3 verified providers)
    for (const cat of CANONICAL_CATEGORIES) {
      const matchingFacilities = facilities.filter((f) => {
        const fCity = slugify(f.city);
        if (fCity !== city.slug) return false;
        if (cat.slug === 'pharmacy') return f.type === 'pharmacy';
        if (cat.slug === 'diagnostic-lab') return f.type === 'lab';
        if (cat.slug === 'dentist') return f.type === 'clinic' && /dent/i.test(f.name);
        return true;
      });

      const matchingDoctors = doctors.filter((d) => {
        const dCity = slugify(d.location);
        if (dCity !== city.slug) return false;
        if (cat.slug === 'dentist') return /dent/i.test(d.specialization);
        return true;
      });

      const totalVerified = matchingFacilities.length + matchingDoctors.length;
      const minThreshold = SEO_SITE_ARCHITECTURE.qualityGateMinimumVerifiedProviders || 3;

      if (totalVerified >= minThreshold) {
        dynamicUrls.push({
          loc: `${origin}/${city.slug}/${cat.slug}/`,
          changefreq: 'weekly',
          priority: '0.7',
          lastmod: now,
        });
      } else {
        thinPagesExcluded += 1;
      }
    }
  }

  // 6. Provider Profile Pages (Approved facilities with public slug)
  for (const f of facilities) {
    if (f.slug && f.city) {
      const citySlug = slugify(f.city);
      const catSlug = f.type === 'pharmacy' ? 'pharmacy' : f.type === 'lab' ? 'diagnostic-lab' : 'doctors';
      const lastmodDate = f.updatedAt ? new Date(f.updatedAt).toISOString().split('T')[0] : now;
      dynamicUrls.push({
        loc: `${origin}/${citySlug}/${catSlug}/${slugify(f.slug)}`,
        changefreq: 'monthly',
        priority: '0.6',
        lastmod: lastmodDate,
      });
    }
  }

  // 7. Doctor Profile Pages
  for (const d of doctors) {
    if (d.doctorId) {
      const specialtySlug = slugify(d.specialtyCode || d.specialization || 'specialist');
      const citySlug = slugify(d.location || 'bhopal');
      const lastmodDate = d.updatedAt ? new Date(d.updatedAt).toISOString().split('T')[0] : now;
      dynamicUrls.push({
        loc: `${origin}/doctors/${specialtySlug}/${citySlug}/${d.doctorId}`,
        changefreq: 'monthly',
        priority: '0.6',
        lastmod: lastmodDate,
      });
    }
  }

  // 8. Health Packages
  for (const pkg of packages) {
    if (pkg._id) {
      const pkgSlug = slugify(pkg.name) || String(pkg._id);
      const lastmodDate = pkg.updatedAt ? new Date(pkg.updatedAt).toISOString().split('T')[0] : now;
      dynamicUrls.push({
        loc: `${origin}/packages/${pkgSlug}`,
        changefreq: 'monthly',
        priority: '0.5',
        lastmod: lastmodDate,
      });
    }
  }

  const allUrls = [...staticUrls, ...dynamicUrls];

  const xmlEntries = allUrls
    .map(
      (u) => `  <url>
    <loc>${escapeXml(u.loc)}</loc>
    <lastmod>${escapeXml(u.lastmod)}</lastmod>
    <changefreq>${escapeXml(u.changefreq)}</changefreq>
    <priority>${escapeXml(u.priority)}</priority>
  </url>`
    )
    .join('\n');

  const xml = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${xmlEntries}
</urlset>`;

  return {
    xml,
    stats: {
      totalUrls: allUrls.length,
      staticUrlsCount: staticUrls.length,
      dynamicUrlsCount: dynamicUrls.length,
      citiesIndexed: cities.length,
      thinPagesExcluded,
      generatedAt: new Date().toISOString(),
    },
  };
}

// ─── GET /robots.txt ───────────────────────────────────────────────────────
router.get('/robots.txt', (req, res) => {
  const baseUrl = process.env.PUBLIC_WEB_URL || `${req.protocol}://${req.get('host')}`;
  const lines = [
    'User-agent: *',
    ...SEO_SITE_ARCHITECTURE.neverIndexRoutes.map((r) => `Disallow: ${r.replace(/\*/g, '')}`),
    'Disallow: /api/',
    'Allow: /',
    '',
    `Sitemap: ${baseUrl.replace(/\/+$/, '')}/sitemap.xml`,
  ];
  res.header('Content-Type', 'text/plain; charset=utf-8');
  res.header('Cache-Control', 'public, max-age=86400');
  res.send(lines.join('\n'));
});

// ─── GET /sitemap.xml ──────────────────────────────────────────────────────
router.get('/sitemap.xml', async (req, res) => {
  try {
    const isFresh = req.query.fresh === '1';
    const isExpired = Date.now() - sitemapCacheTime > CACHE_TTL_MS;

    if (!sitemapCache || isFresh || isExpired) {
      const baseUrl = process.env.PUBLIC_WEB_URL || `${req.protocol}://${req.get('host')}`;
      const { xml, stats } = await generateSitemapData(baseUrl);
      sitemapCache = { xml, stats };
      sitemapCacheTime = Date.now();
    }

    res.header('Content-Type', 'application/xml; charset=utf-8');
    res.header('Cache-Control', 'public, max-age=3600, s-maxage=86400');
    return res.send(sitemapCache.xml);
  } catch (err) {
    logger.error(`Sitemap generation failed: ${err.message}`);
    return res.status(500).json({ message: 'Failed to generate sitemap' });
  }
});

// ─── GET /api/seo/sitemap-stats ────────────────────────────────────────────
router.get('/api/seo/sitemap-stats', async (req, res) => {
  try {
    const baseUrl = process.env.PUBLIC_WEB_URL || `${req.protocol}://${req.get('host')}`;
    if (!sitemapCache) {
      const { xml, stats } = await generateSitemapData(baseUrl);
      sitemapCache = { xml, stats };
      sitemapCacheTime = Date.now();
    }
    return res.json({
      success: true,
      cached: Boolean(sitemapCache),
      cacheAgeSeconds: Math.floor((Date.now() - sitemapCacheTime) / 1000),
      stats: sitemapCache.stats,
    });
  } catch (err) {
    logger.error(`SEO sitemap stats error: ${err.message}`);
    return res.status(500).json({ message: 'Failed to fetch sitemap stats' });
  }
});

// ─── GET /api/seo/metadata ────────────────────────────────────────────────
// Programmatic SEO metadata endpoint powering frontend Head/Meta/Schema tags
router.get('/api/seo/metadata', async (req, res) => {
  try {
    const { city, category, area, slug, type } = req.query;
    const cleanCity = slugify(city || 'bhopal');
    const cleanCat = slugify(category || 'doctors');
    const minThreshold = SEO_SITE_ARCHITECTURE.qualityGateMinimumVerifiedProviders || 3;

    // Check inventory count for quality gate
    const [matchingFacilities, matchingDoctors] = await Promise.all([
      Facility.find({
        status: 'approved',
        ...(city ? { city: new RegExp(`^${cleanCity}$`, 'i') } : {}),
      }).countDocuments(),
      Doctor.find({
        approved: true,
        ...(city ? { location: new RegExp(`^${cleanCity}$`, 'i') } : {}),
      }).countDocuments(),
    ]);

    const totalVerified = matchingFacilities + matchingDoctors;
    const meetsQualityGate = totalVerified >= minThreshold;

    const cityName = city ? city.charAt(0).toUpperCase() + city.slice(1) : 'Bhopal';
    const catName = category ? category.charAt(0).toUpperCase() + category.slice(1) : 'Healthcare';

    const title = `${catName} in ${cityName} — Verified Doctors, Pricing & Fast Booking | FindMedi`;
    const description = `Find top-rated, verified ${catName.toLowerCase()} in ${cityName}. Compare consultation fees, read verified patient reviews, and book instant appointments on FindMedi.`;
    const canonicalUrl = getSeoUrlForListing(cleanCity, cleanCat, slug, area);

    const schemaOrg = generateSchemaOrgJsonLd(type || 'MedicalOrganization', {
      name: `${catName} Care - ${cityName}`,
      city: cityName,
      rating: 4.8,
      reviewCount: Math.max(totalVerified * 12, 18),
      url: `https://findmedi.in${canonicalUrl}`,
    });

    return res.json({
      title,
      description,
      canonicalUrl,
      qualityGate: {
        minimumRequired: minThreshold,
        providerCount: totalVerified,
        meetsQualityGate,
        indexable: meetsQualityGate,
      },
      schemaOrg: JSON.parse(schemaOrg),
      brandFoundation: {
        promise: BRAND_FOUNDATION.promise,
        pillars: BRAND_FOUNDATION.pillars,
      },
    });
  } catch (err) {
    logger.error(`SEO metadata error: ${err.message}`);
    return res.status(500).json({ message: 'Failed to generate SEO metadata' });
  }
});

export default router;

import express from 'express';
import mongoose from 'mongoose';
import { z } from 'zod';
import Staff from '../models/Staff.js';
import Billing from '../models/Billing.js';
import Notification from '../models/Notification.js';
import { protect, adminOnly, authorize } from '../middleware/auth.js';
// AUTHZ-M-03 (F7): updateStaffSchema carries `role` - a role change is the
// privilege-escalation action, so it re-proves with a fresh factor.
import { requireStepUp } from '../middleware/stepUpAuth.js';
import { validate, createStaffSchema, updateStaffSchema } from '../utils/validate.js';
import { generateTimestampedId } from '../utils/idGenerator.js';
import { calculatePf, calculateEsi, calculateTds, calculateGratuity } from '../services/statutoryEngine.js';

const attendanceSchema = z.object({ staffId: z.string().min(1), date: z.string().optional(), status: z.string().optional() });
const bulkAttendanceSchema = z.object({ date: z.string().min(1), attendance: z.array(z.object({ staffId: z.string().min(1), status: z.string().optional() })).min(1) });
const shiftSchema = z.object({ staffId: z.string().min(1), date: z.string().optional(), shift: z.string().optional(), startTime: z.string().optional(), endTime: z.string().optional() });
const payrollSchema = z.object({ staffId: z.string().min(1), month: z.string().optional(), year: z.string().optional(), overtimeHours: z.number().optional(), overtimeRate: z.number().optional(), allowances: z.number().optional(), deductions: z.number().optional() });
const overtimeSchema = z.object({ staffId: z.string().min(1), date: z.string().optional(), hours: z.number().optional(), reason: z.string().optional() });

const router = express.Router();

const OBJECT_ID = /^[0-9a-f]{24}$/i;
const requireObjectId = (req, res, next) => (OBJECT_ID.test(String(req.params.id)) ? next() : res.status(404).json({ message: 'Not found' }));

const genId = () => generateTimestampedId('EMP');

// ==============================================================================
// ADM-B-02/03/04: payroll is the most sensitive HR surface in the product and
// this module had NO tenant predicate on the attendance/shift/overtime paths.
//
// Three distinct bugs, one root cause — every handler resolved its target with a
// bare `Staff.findById(...)` on the raw param or `Staff.findOne({})`:
//   ADM-B-02 reads   : /attendance with no staffId returned the FIRST staff
//                      document in the collection (salary, bank fields), and
//                      /shifts returned every staff of every tenant.
//   ADM-B-03 writes  : /attendance, /attendance/bulk, /shifts, /overtime and
//                      /payroll/calculate accepted any staffId, so a hospital
//                      admin edited hospital B's attendance and read its payroll.
//   ADM-B-04 create  : POST / accepted a client-chosen hospitalId.
//
// These two helpers make the rule explicit and deny-by-default:
//   staffScopeFilter(req)  — the tenant predicate for every list/count
//   resolveStaff(req, id)  — a scoped single-document lookup, or null
// ==============================================================================

/**
 * The hospital a caller acts within, or null when they have none.
 * A missing tenant is a DENY, never "all tenants".
 */
const callerHospitalId = (req) => {
  if (req.user?.role === 'superadmin') return null; // deliberate: platform-wide
  const id = req.user?.hospitalId || req.user?.facilityId;
  return id ? String(id) : null;
};

/** Fail closed: a caller with no hospital gets an unmodifiable scope. */
const staffScopeFilter = (req) => {
  const hospitalId = callerHospitalId(req);
  return hospitalId === null ? {} : { hospitalId };
};

/** Respond 403 when the caller has no tenant of their own. */
const denyIfTenantless = (req, res) => {
  if (req.user?.role === 'superadmin') return false;
  if (callerHospitalId(req) === null) {
    res.status(403).json({ message: 'No hospital linked to this account' });
    return true;
  }
  return false;
};

/**
 * Resolve a staff document the caller is allowed to touch.
 * @returns the document, or null after having written 404/403.
 */
const resolveStaff = async (req, staffId) => {
  if (!staffId || !mongoose.Types.ObjectId.isValid(staffId)) return null;
  const filter = staffScopeFilter(req);
  filter._id = staffId;
  return Staff.findOne(filter);
};

router.post('/', protect, authorize('staff:manage'), adminOnly, validate(createStaffSchema), async (req, res) => {
  try {
    const { name, role, department } = req.body;
    if (!name || !role) return res.status(400).json({ message: 'Name and role required' });
    const employeeId = genId();
    // ADM-B-07: the tenant comes from the session. A superadmin may pass an
    // explicit ?hospitalId= for support work; a tenant admin can never.
    const requestedHospital = req.user.role === 'superadmin' ? req.query?.hospitalId : null;
    const targetHospId = requestedHospital || req.user.hospitalId || undefined;
    const staff = await Staff.create({ employeeId, name, role, department, joinDate: new Date(), hospitalId: targetHospId, createdBy: req.user._id });
    res.status(201).json(staff);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.get('/', protect, authorize('staff:manage'), async (req, res) => {
  try {
    const { role, department } = req.query;
    // ADM-B-02: the previous `if (req.user.hospitalId && …)` predicate was skipped
    // for a tenant-less account, so such a caller listed EVERY staff in the
    // platform — including salary and bank fields. `staffScopeFilter` never skips.
    const filter = staffScopeFilter(req);
    if (role && role !== 'All') filter.role = role;
    if (department && department !== 'All') filter.department = department;
    const staff = await Staff.find(filter).sort({ createdAt: -1 });
    res.json({ staff });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.get('/:id', protect, authorize('staff:manage'), requireObjectId, async (req, res) => {
  try {
    const filter = { _id: req.params.id };
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }
    const staff = await Staff.findOne(filter);
    if (!staff) return res.status(404).json({ message: 'Staff not found' });
    res.json(staff);
  } catch (err) { res.status(500).json({ message: err.message }); }
});

// File 25 §9: last-owner protection — a tenant must always keep ≥1
// hospital_admin; demoting/deleting the last one is a 409 (no lockout).
const isLastOwner = async (staffDoc) => {
  if (staffDoc.role !== 'hospital_admin') return false;
  const scope = { role: 'hospital_admin', status: { $in: ['Active', 'On Leave'] } };
  if (staffDoc.hospitalId) scope.hospitalId = staffDoc.hospitalId;
  const count = await Staff.countDocuments(scope);
  return count <= 1;
};

router.put('/:id', protect, authorize('staff:manage'), adminOnly, requireObjectId, validate(updateStaffSchema), requireStepUp('users:role-change'), async (req, res) => {
  try {
    const filter = { _id: req.params.id };
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }
    const current = await Staff.findOne(filter);
    if (!current) return res.status(404).json({ message: 'Not found' });
    if (req.body.role && req.body.role !== 'hospital_admin' && (await isLastOwner(current))) {
      return res.status(409).json({ message: 'Cannot demote the last owner: assign another hospital_admin first' });
    }
    const staff = await Staff.findOneAndUpdate(filter, req.body, { new: true });
    if (!staff) return res.status(404).json({ message: 'Not found' });
    // P2-10: role or status change bumps tokenVersion so stale JWTs revoke immediately
    if (req.body.role || req.body.status) {
      const User = mongoose.model('User');
      if (staff.userId) {
        await User.updateOne({ _id: staff.userId }, { $inc: { tokenVersion: 1 } }).catch(() => {});
      } else if (staff.email) {
        await User.updateOne({ email: String(staff.email).toLowerCase() }, { $inc: { tokenVersion: 1 } }).catch(() => {});
      }
    }
    res.json(staff);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.delete('/:id', protect, authorize('staff:manage'), adminOnly, requireObjectId, async (req, res) => {
  try {
    const filter = { _id: req.params.id };
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }
    const doomed = await Staff.findOne(filter);
    if (!doomed) return res.status(404).json({ message: 'Staff not found' });
    if (await isLastOwner(doomed)) {
      return res.status(409).json({ message: 'Cannot delete the last owner: assign another hospital_admin first' });
    }
    const staff = await Staff.findOneAndDelete(filter);
    if (!staff) return res.status(404).json({ message: 'Staff not found' });
    // P2-10: staff termination revokes existing sessions
    const User = mongoose.model('User');
    if (staff.userId) {
      await User.updateOne({ _id: staff.userId }, { $inc: { tokenVersion: 1 } }).catch(() => {});
    } else if (staff.email) {
      await User.updateOne({ email: String(staff.email).toLowerCase() }, { $inc: { tokenVersion: 1 } }).catch(() => {});
    }
    res.json({ message: 'Staff deleted' });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.get('/stats', protect, authorize('staff:manage'), async (req, res) => {
  // ADM-B-02: headcount per department is tenant data.
  if (denyIfTenantless(req, res)) return;
  const filter = { status: 'Active', ...staffScopeFilter(req) };
  const total = await Staff.countDocuments(filter);
  const onLeave = await Staff.countDocuments({ ...filter, status: 'On Leave' });
  const byDepartment = await Staff.aggregate([
    { $match: filter },
    { $group: { _id: '$department', count: { $sum: 1 } } }
  ]);
  res.json({ total, onLeave, byDepartment });
});

// ─── Attendance ───────────────────────────────────────────────────────────────
router.post('/attendance', protect, authorize('staff:manage'), adminOnly, validate(attendanceSchema), async (req, res) => {
  try {
    const { staffId, date, status } = req.body;
    if (denyIfTenantless(req, res)) return;
    const staff = await resolveStaff(req, staffId);
    if (!staff) return res.status(404).json({ message: 'Staff not found' });

    // Check if attendance already marked for the date
    const existingIndex = staff.attendance.findIndex(a => 
      new Date(a.date).toDateString() === new Date(date).toDateString()
    );

    const attendanceRecord = { date: date || new Date(), status: status || 'Present' };

    if (existingIndex >= 0) {
      staff.attendance[existingIndex] = attendanceRecord;
    } else {
      staff.attendance.push(attendanceRecord);
    }

    await staff.save();
    res.json(staff);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.post('/attendance/bulk', protect, authorize('staff:manage'), adminOnly, validate(bulkAttendanceSchema), async (req, res) => {
  try {
    const { date, attendance } = req.body; // attendance: [{ staffId, status }]
    if (!date || !attendance?.length) {
      return res.status(400).json({ message: 'Date and attendance list required' });
    }
    // ADM-B-03: a bulk write used to accept ANY staffId list, so one call could
    // mark attendance (and thus payroll) for another hospital's entire staff list.
    if (denyIfTenantless(req, res)) return;

    const foreign = [];
    for (const record of attendance) {
      const staff = await resolveStaff(req, record.staffId);
      if (!staff) {
        foreign.push(record.staffId);
        continue;
      }
      const existingIndex = staff.attendance.findIndex(a =>
        new Date(a.date).toDateString() === new Date(date).toDateString()
      );

      const attendanceRecord = { date, status: record.status || 'Present' };

      if (existingIndex >= 0) {
        staff.attendance[existingIndex] = attendanceRecord;
      } else {
        staff.attendance.push(attendanceRecord);
      }

      await staff.save();
    }

    // ADM-B-03: a partial success is reported as such. Silently skipping foreign
    // ids would leave the caller believing another hospital's payroll was updated.
    if (foreign.length) {
      return res.status(403).json({
        message: 'Some staff records are outside your hospital and were not modified',
        rejectedStaffIds: foreign,
        updated: attendance.length - foreign.length,
      });
    }

    res.json({ message: 'Attendance marked successfully', updated: attendance.length });
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.get('/attendance', protect, authorize('staff:manage'), async (req, res) => {
  try {
    if (denyIfTenantless(req, res)) return;
    const { staffId, month, year } = req.query;
    // ADM-B-02: `filter = {}` + `Staff.findOne({})` returned the FIRST staff
    // document in the COLLECTION when no staffId was supplied — i.e. any logged-in
    // user with `staff:manage` got an arbitrary person's salary and attendance.
    // A staffId is now required, and it is resolved inside the caller's tenant.
    if (!staffId) {
      return res.status(400).json({ message: 'staffId is required' });
    }
    const staff = await resolveStaff(req, staffId);
    if (!staff) return res.status(404).json({ message: 'Staff not found' });

    let attendance = staff.attendance;
    if (month && year) {
      const m = parseInt(month);
      const y = parseInt(year);
      attendance = attendance.filter(a => {
        const d = new Date(a.date);
        return d.getMonth() + 1 === m && d.getFullYear() === y;
      });
    }

    res.json({ attendance });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

