import express from 'express';
import { z } from 'zod';
import Token from '../models/Token.js';
import Notification from '../models/Notification.js';
import Appointment from '../models/Appointment.js';
import { protect, adminOnly } from '../middleware/auth.js';
import { validate, createTokenSchema } from '../utils/validate.js';
import logger from '../config/logger.js';

const tokenSkipSchema = z.object({ reason: z.string().optional() });

const router = express.Router();

// File 09 §9.4: token desk = admin + front-desk + clinicians (call-next,
// call, start, complete). Public display stays on the separate endpoint below.
const tokenDeskOnly = (req, res, next) => {
  if (!['superadmin', 'hospital_admin', 'receptionist', 'doctor', 'clinic_doctor', 'nurse'].includes(req.user?.role)) {
    return res.status(403).json({ message: 'Token desk access required' });
  }
  return next();
};

const emitQueueUpdate = async (token) => {
  try {
    const { getIO } = await import('../services/socketService.js');
    const io = getIO();
    const room = `queue:${token.hospitalId || 'global'}:${token.department || 'all'}`;
    io?.to(room)?.emit('queue:update', {
      tokenNumber: token.tokenNumber, status: token.status,
      department: token.department, roomNumber: token.roomNumber,
      doctorId: token.doctorId, calledAt: token.calledAt,
    });
  } catch { /* realtime is best-effort */ }
};

// Public read-only display screen (TV mode): token numbers + status ONLY,
// no patient names/phones — safe without auth (file 09 §9.4).
router.get('/display', async (req, res) => {
  try {
    const { department, doctorId, hospitalId, limit } = req.query;
    const filter = { status: { $in: ['Waiting', 'Called', 'In Consultation'] } };
    if (department) filter.department = department;
    if (doctorId) filter.doctorId = doctorId;
    if (hospitalId && OBJECT_ID.test(String(hospitalId))) filter.hospitalId = hospitalId;
    const rows = await Token.find(filter)
      .select('tokenNumber status department roomNumber calledAt priority createdAt')
      .sort({ priority: -1, queuePosition: 1 })
      .limit(Math.min(50, Number(limit) || 20))
      .lean();
    res.json({ tokens: rows });
  } catch (err) { res.status(500).json({ message: err.message }); }
});
const OBJECT_ID = /^[0-9a-f]{24}$/i;

// Generate token with auto-increment
router.post('/generate', protect, tokenDeskOnly, validate(createTokenSchema), async (req, res) => {
  try {
    const { patientId, patientName, uhid, doctorId, doctorName, department, appointmentId, type, priority } = req.body;
    if (!patientId || !patientName || !department) {
      return res.status(400).json({ message: 'Patient and department required' });
    }

    // File 22 P0-left: blacklisted/deceased patients cannot get tokens.
    try {
      const { patientHardStop } = await import('./masters.js');
      const stop = await patientHardStop(req.user.hospitalId, patientId);
      if (stop) return res.status(409).json({ message: `Token blocked: patient is ${stop}`, code: 'PATIENT_HARD_STOP' });
    } catch { /* flag lookup must never break token generation on infra errors */ }

    // Check for existing waiting token for same patient
    const existingToken = await Token.findOne({ patientId, status: { $in: ['Waiting', 'Called', 'In Consultation'] } });
    if (existingToken) {
      return res.status(400).json({ message: 'Patient already has an active token', token: existingToken });
    }

    // Calculate queue position and estimated wait time
    const currentQueueLength = await Token.countDocuments({ 
      department, 
      status: { $in: ['Waiting', 'Called', 'In Consultation'] },
      createdAt: { $gte: new Date().setHours(0,0,0,0) }
    });

    const estimatedWaitTime = currentQueueLength * 15; // 15 minutes average per patient

    const token = await Token.create({
      patientId, patientName, uhid, doctorId, doctorName,
      department, appointmentId, type: type || 'OPD', priority: priority || 'Normal',
      hospitalId: req.user.hospitalId || undefined,
      queuePosition: currentQueueLength + 1,
      estimatedWaitTime,
      checkedInAt: new Date(),
    });

    // Notify relevant staff
    await Notification.create({
      title: 'New Token Generated',
      message: `Token ${token.tokenNumber} generated for ${patientName} at ${department}`,
      type: 'token',
      userId: req.user._id.toString(),
    });

    res.status(201).json(token);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.get('/', protect, async (req, res) => {
  try {
    const { status, department, date, doctorId } = req.query;
    const filter = {};
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }

    if (status && status !== 'All') filter.status = status;
    if (department && department !== 'All') filter.department = department;
    if (doctorId) filter.doctorId = doctorId;

    if (date) {
      const startDate = new Date(date);
      const endDate = new Date(date);
      endDate.setHours(23, 59, 59);
      filter.createdAt = { $gte: startDate, $lte: endDate };
    } else {
      // Default to today
      const startDate = new Date().setHours(0,0,0,0);
      filter.createdAt = { $gte: startDate };
    }

    const tokens = await Token.find(filter)
      .populate('patientId', 'name email phone')
      .populate('doctorId', 'name')
      .sort({ queuePosition: 1, createdAt: -1 });

    res.json({ tokens });
  } catch (err) { res.status(500).json({ message: err.message }); }
});

router.get('/current/:department?', protect, async (req, res) => {
  try {
    const { department } = req.params;
    const filter = { status: { $in: ['Waiting', 'Called', 'In Consultation'] } };
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }
    if (department && department !== 'All') filter.department = department;

    const tokens = await Token.find(filter)
