router.put('/:id/call', protect, tokenDeskOnly, async (req, res) => {
  try {
    const token = await Token.findById(req.params.id);
    if (!token) return res.status(404).json({ message: 'Token not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || token.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Not authorized to call this token' });
    }
    token.status = 'Called';
    token.calledAt = new Date();
    await token.save();
    void emitQueueUpdate(token);

    // Notify patient
    await Notification.create({
      title: 'Token Called',
      message: `Token ${token.tokenNumber} is now being called. Please proceed to ${token.department}`,
      type: 'token',
      userId: token.patientId,
    });

    res.json(token);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.put('/:id/start-consultation', protect, tokenDeskOnly, async (req, res) => {
  try {
    const token = await Token.findById(req.params.id);
    if (!token) return res.status(404).json({ message: 'Token not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || token.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Access denied' });
    }
    token.status = 'In Consultation';
    token.consultationStartTime = new Date();
    await token.save();
    // File 22 P0-left: visit start opens the OPD Encounter (idempotent).
    if (token.patientId && !token.encounterId) {
      try {
        const { ensureEncounter } = await import('../lib/encounter.js');
        const enc = await ensureEncounter({
          hospitalId: token.hospitalId, patientId: token.patientId, type: 'OPD',
          appointmentId: token.appointmentId || null,
          createdBy: req.user._id ?? req.user.id,
        });
        token.encounterId = enc._id;
        await token.save();
      } catch (e) {
        logger.warn(`token encounter auto-create failed: ${e.message}`);
      }
    }
    void emitQueueUpdate(token);
    res.json(token);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.put('/:id/complete', protect, tokenDeskOnly, async (req, res) => {
  try {
    const token = await Token.findById(req.params.id);
    if (!token) return res.status(404).json({ message: 'Token not found' });
    if (req.user.role !== 'superadmin' && (!req.user.hospitalId || token.hospitalId?.toString() !== req.user.hospitalId.toString())) {
      return res.status(403).json({ message: 'Access denied' });
    }

    token.status = 'Completed';
    token.completedAt = new Date();
    if (token.consultationStartTime) {
      token.totalConsultationTime = Math.round((token.completedAt - token.consultationStartTime) / 60000);
    }
    await token.save();

    // Update appointment if linked
    if (token.appointmentId) {
      await Appointment.findByIdAndUpdate(token.appointmentId, { status: 'Completed', consultationEndTime: new Date() });
    }
    // File 22 P0-3: visit end closes the OPD Encounter (idempotent).
    if (token.encounterId || token.appointmentId) {
      try {
        const { closeEncounter } = await import('../lib/encounter.js');
        await closeEncounter({ encounterId: token.encounterId, hospitalId: token.hospitalId });
        if (token.appointmentId) {
          const appt = await Appointment.findById(token.appointmentId).select('encounterId').lean();
          if (appt?.encounterId) await closeEncounter({ encounterId: appt.encounterId, hospitalId: token.hospitalId });
        }
      } catch (e) {
        logger.warn(`token encounter close failed: ${e.message}`);
      }
    }
    void emitQueueUpdate(token);

    res.json(token);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

// Call next: highest priority, lowest queue position among Waiting (file 09 §9.4).
router.post('/call-next', protect, tokenDeskOnly, async (req, res) => {
  try {
    const { department, doctorId } = req.body || {};
    const filter = { status: 'Waiting' };
    if (req.user.role !== 'superadmin') { if (!req.user.hospitalId) return res.status(403).json({ message: 'Hospital scope required' }); filter.hospitalId = req.user.hospitalId; }
    if (department) filter.department = department;
    if (doctorId) filter.doctorId = doctorId;
    const priorityRank = { Emergency: 0, Urgent: 1, Normal: 2 };
    const candidates = await Token.find(filter).sort({ queuePosition: 1 }).limit(50);
    candidates.sort((a, b) => (priorityRank[a.priority] ?? 2) - (priorityRank[b.priority] ?? 2));
    const next = candidates[0];
    if (!next) return res.status(404).json({ message: 'No waiting tokens' });
    next.status = 'Called';
    next.calledAt = new Date();
    await next.save();
    void emitQueueUpdate(next);
    await Notification.create({
      title: 'Token Called',
      message: `Token ${next.tokenNumber} is now being called. Please proceed to ${next.department}`,
      type: 'token',
      userId: next.patientId,
    }).catch(() => {});
    res.json(next);
  } catch (err) { res.status(400).json({ message: err.message }); }
});

router.put('/:id/no-show', protect, tokenDeskOnly, async (req, res) => {
