import { publicOrigin } from '../utils/publicOrigin.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const UPLOAD_DIR = path.join(__dirname, '..', '..', 'public', 'uploads', 'documents');
if (!fs.existsSync(UPLOAD_DIR)) {
  fs.mkdirSync(UPLOAD_DIR, { recursive: true });
}

// Save file locally (fallback when Cloudinary fails)
const saveFileLocally = (file, baseUrl) => {
  const ext = path.extname(file.originalname).replace(/[^a-zA-Z0-9.]/g, '') || '.bin';
  const filename = `${Date.now()}-${Math.random().toString(36).substring(2, 10)}${ext}`;
  const filepath = path.join(UPLOAD_DIR, filename);
  fs.writeFileSync(filepath, file.buffer);
  return {
    url: `${baseUrl}/uploads/documents/${filename}`,
    filename: file.originalname,
    fileId: filename,
    size: file.size,
    format: ext.replace('.', ''),
    mimeType: file.mimetype,
    storedIn: 'local',
  };
};

const router = express.Router();

const ALLOWED_MIME_TYPES = new Set([
  'image/jpeg',
  'image/png',
  'image/webp',
  'image/gif',
  'application/pdf',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.ms-excel',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'text/plain',
]);

const storage = multer.memoryStorage();
const upload = multer({
  storage,
  limits: { fileSize: 25 * 1024 * 1024 },
  fileFilter: (_req, file, cb) => {
    if (!ALLOWED_MIME_TYPES.has(file.mimetype)) {
      return cb(new Error('Invalid file type. Only images, PDFs, documents, and text files are allowed.'), false);
    }
    cb(null, true);
  },
});

// Proxy download route — redirect to stored file URL (Cloudinary or legacy Drive)
router.get('/download/:fileId', protect, authorize('upload:read:own'), async (req, res, next) => {
  try {
    const { fileId } = req.params;
    const record = await Record.findOne({
      'data.uploadedFile.fileId': fileId,
      patientId: req.user._id,
    });

    if (!record) {
      return res.status(404).json({ error: 'File not found or access denied' });
    }

    const fileUrl = record.data.uploadedFile.url;
    if (fileUrl) {
      res.redirect(fileUrl);
    } else {
      res.status(404).json({ error: 'File URL not found' });
    }
  } catch (error) {
    next(error);
  }
});

router.post('/', protect, authorize('upload:write', 'upload:write:own'), upload.single('file'), async (req, res, next) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No file uploaded' });
    }

    // Content-based file type verification (magic bytes) — prevents MIME type spoofing
    if (!(await validateFileContent(req.file.buffer, req.file.mimetype))) {
      return res.status(400).json({
        error: 'File content does not match its claimed type. Upload rejected for security.',
      });
    }

    // Native Rust image optimization (resize & compress)
    if (req.file.mimetype.startsWith('image/') && req.file.mimetype !== 'image/gif') {
      try {
        if (NATIVE_AVAILABLE) {
          const optimized = napiResizeToFit(req.file.buffer, 1920, 1920, 85);
          if (optimized && optimized.length > 0) {
            req.file.buffer = optimized;
            req.file.size = optimized.length;
          }
        }
      } catch (optErr) {
        console.warn('Native image optimization skipped:', optErr?.message || optErr);
      }
    }

    const storedIn = req.body?.storedIn || 'cloudinary';
    const clientUploadType = req.body?.uploadType;
    const detectRecordType = (type) => {
      if (type && ['prescription', 'lab_report', 'medical_image', 'xray', 'bill_invoice', 'discharge_summary', 'document'].includes(type)) {
        return type;
      }
      // Fallback by mimetype
      let fallback = 'prescription';
      if (req.file.mimetype.startsWith('image/')) {
        fallback = 'lab_report';
      } else if (req.file.mimetype === 'application/pdf') {
        fallback = 'discharge_summary';
      }
      return fallback;
    };

    // ─── Upload to user's Google Drive ──────────────────────────────────────
    if (storedIn === 'drive') {
      if (!isDriveConfigured()) {
        return res.status(503).json({ error: 'Google Drive is not configured on the server.' });
      }

      const user = await User.findById(req.user.id).select('driveTokens');
      if (!user?.driveTokens?.refresh_token) {
        return res.status(400).json({ error: 'Google Drive is not connected. Connect it first.' });
      }

      const driveResult = await uploadFileToDrive(
        user.driveTokens,
        req.file.buffer,
        req.file.originalname,
        req.file.mimetype
      );

      const recordType = detectRecordType(clientUploadType);

      const record = await Record.create({
        patient: req.user.name,
        patientId: req.user._id,
        doctor: 'Self Upload',
        date: getISTDateString(),
        diagnosis: `Uploaded ${req.file.originalname}`,
        type: recordType,
        notes: `File: ${req.file.originalname}`,
        data: {
          patient: { name: req.user.name },
          doctor: { name: 'Self Upload' },
          uploadedFile: {
            filename: driveResult.filename,
            url: driveResult.url,
            fileId: driveResult.fileId,
            size: driveResult.size,
            format: driveResult.format,
            mimeType: driveResult.mimeType,
            storedIn: 'drive',
          },
          date: getISTDateString(),
        },
      });

      await Notification.create({
        title: 'File Uploaded',
        message: `Your file "${req.file.originalname}" has been saved to your Google Drive`,
        type: 'records',
        read: false,
        userId: req.user._id,
        date: getISTDateString(),
      });

      return res.json({
        success: true,
        url: driveResult.url,
        filename: driveResult.filename,
        size: driveResult.size,
        format: driveResult.format,
        fileId: driveResult.fileId,
        storedIn: 'drive',
        uploadType: recordType,
        recordId: record._id,
      });
    }

    // ─── Upload to Cloudinary (default) w/ local fallback ───────────────────
    let cloudResult;
    try {
      cloudResult = await uploadFileToCloudinary(
        req.file.buffer,
        req.file.originalname,
        req.file.mimetype
      );
    } catch (cloudErr) {
      console.warn('Cloudinary upload failed, using local storage:', cloudErr.message);
      // AUTH host-header (P1 #7): publicOrigin pins the configured origin —
      // a forged Host header must not poison the persisted attachment URL.
      cloudResult = saveFileLocally(req.file, publicOrigin(req));
    }

    const recordType = detectRecordType(clientUploadType);
    const shouldCreateRecord = req.body?.createRecord !== 'false' && req.body?.purpose !== 'intake' && req.body?.isTemp !== 'true';

    let record = null;
    if (shouldCreateRecord) {
      record = await Record.create({
        patient: req.user.name,
        patientId: req.user._id,
        doctor: 'Self Upload',
        date: getISTDateString(),
        diagnosis: `Uploaded ${req.file.originalname}`,
        type: recordType,
        notes: `File: ${req.file.originalname}`,
        data: {
          patient: { name: req.user.name },
          doctor: { name: 'Self Upload' },
          uploadedFile: {
            filename: req.file.originalname,
            url: cloudResult.url,
            fileId: cloudResult.fileId,
            size: cloudResult.size || req.file.size,
            format: path.extname(req.file.originalname).replace('.', '') || cloudResult.format || '',
            mimeType: req.file.mimetype,
            storedIn: cloudResult.storedIn || 'cloudinary',
          },
          date: getISTDateString(),
        },
      });

      await Notification.create({
        title: 'File Uploaded',
        message: `Your file "${req.file.originalname}" has been uploaded successfully`,
        type: 'records',
        read: false,
        userId: req.user._id,
        date: getISTDateString(),
      });
    }

    res.json({
      success: true,
      url: cloudResult.url,
      filename: req.file.originalname,
      size: cloudResult.size || req.file.size,
      format: path.extname(req.file.originalname).replace('.', '') || cloudResult.format || '',
      fileId: cloudResult.fileId,
      storedIn: cloudResult.storedIn || 'cloudinary',
      uploadType: recordType,
      recordId: record?._id,
    });
  } catch (error) {
    next(error);
  }
});

// ─── Public Document / Photo Upload (for Registration / Onboarding) ─────────
//
// DLB-22: this endpoint had NO authentication and NO rate limit at all, so any
// anonymous script could fill the platform's storage (and Cloudinary quota) with
// arbitrary files behind the findmedi.online origin. It is still reachable before
// login (the onboarding forms need it), so the control is applied here:
//   * a dedicated per-IP limiter,
//   * a strict type allow-list (images / PDF only),
//   * a per-IP hourly cap,
//   * magic-byte content validation (already below).
const PUBLIC_UPLOAD_TYPES = new Set([
  'image/jpeg', 'image/png', 'image/webp', 'image/gif', 'application/pdf',
]);
const publicUploadLimiter = createGrlRateLimiter({
  windowMs: 60 * 1000,
  max: 10,
  keyPrefix: 'rl:publicupload',
});

router.post('/public', publicUploadLimiter, upload.single('file'), async (req, res, next) => {
  try {
    if (!req.file) {
      return res.status(400).json({ error: 'No file uploaded' });
    }

    if (!PUBLIC_UPLOAD_TYPES.has(req.file.mimetype)) {
      return res.status(415).json({ error: 'Only JPG, PNG, WEBP, GIF or PDF uploads are allowed' });
    }

    // Per-IP hourly budget so a script cannot use this as a free file host.
    try {
      const { redisClient, isRedisReady } = await import('../config/redis.js');
      if (isRedisReady() && redisClient.isOpen) {
        const hourKey = `rl:publicupload:h:${req.ip}`;
        const used = Number(await redisClient.incr(hourKey));
        if (used === 1) await redisClient.expire(hourKey, 3600);
        if (used > 100) {
          return res.status(429).json({ error: 'Too many uploads from this network. Try again later.' });
        }
      }
    } catch { /* limiter is best effort */ }

    if (!(await validateFileContent(req.file.buffer, req.file.mimetype))) {
      return res.status(400).json({
        error: 'File content does not match its claimed type. Upload rejected for security.',
      });
    }

    if (req.file.mimetype.startsWith('image/') && req.file.mimetype !== 'image/gif') {
      try {
        if (NATIVE_AVAILABLE) {
          const optimized = napiResizeToFit(req.file.buffer, 1920, 1920, 85);
          if (optimized && optimized.length > 0) {
            req.file.buffer = optimized;
            req.file.size = optimized.length;
          }
        }
      } catch (optErr) {
        console.warn('Native image optimization skipped:', optErr?.message || optErr);
      }
    }

    let cloudResult;
    try {
      cloudResult = await uploadFileToCloudinary(
        req.file.buffer,
        req.file.originalname,
        req.file.mimetype
      );
    } catch (cloudErr) {
      console.warn('Cloudinary public upload failed, using local storage:', cloudErr.message);
      cloudResult = saveFileLocally(req.file, publicOrigin(req));
    }

    res.json({
      success: true,
      url: cloudResult.url,
      filename: req.file.originalname,
      size: cloudResult.size || req.file.size,
      fileId: cloudResult.fileId,
    });
  } catch (error) {
    next(error);
  }
});

export default router;

import express from 'express';
import VaccinationSchedule from '../models/VaccinationSchedule.js';
import FamilyMember from '../models/FamilyMember.js';
import Record from '../models/Record.js';
import { protect, authorize } from '../middleware/auth.js';
import { auditLog } from '../middleware/audit.js';
import {
  validate, createVaccinationScheduleSchema, doseGivenSchema,
} from '../utils/validate.js';
import logger from '../config/logger.js';

// A4 / rolesmd 6.md §2.5 (page /patient/vaccinations: "Vaccine schedule &
// certificates") + 10.md §4.3 (GET /api/patient/vaccinations).
//
// This is the SCHEDULE; a Record of type `vaccination_record` is ONE
// administered dose's certificate. "due/overdue" is a date comparison against
// the row, so it is derived at READ time (Event `full` pattern) and never
// stored - a stored flag goes stale the moment the clock crosses the due date,
// and backfilling it would be a migration for a value that is pure arithmetic.
//
// Gating: protect + authorize(records:*:own) - the clinical-records permission
// the patient role holds - with the handler additionally scoped to the
// session's own rows, so a foreign id answers 404 rather than an empty 200
// (AUTHZ-M-01's existence oracle). The `// authz: role` tags record the
// middleware gate, which is what classify() sees on these definition lines.
const router = express.Router();
router.use(protect);

const OBJECT_ID = /^[0-9a-f]{24}$/i;
const requireObjectId = (req, res, next) => (
  OBJECT_ID.test(String(req.params.id))
    ? next()
    : res.status(404).json({ message: 'Not found' })
);

const actorId = (req) => req.user._id ?? req.user.id;

// Read-time reminder window: "overdue" = past due and not yet given, "due" =
// within the next 30 days, otherwise "upcoming". Data, not a calendar lookup
// the client performs - the page renders straight from these tokens.
const DUE_WINDOW_MS = 30 * 24 * 60 * 60 * 1000;

/**
 * Attach the derived read-time state. Nothing here is written back: the row
 * keeps only `doses[].givenAt`, and every list/detail response recomputes
 * state/overdueCount/nextDueAt against the clock it was read at.
 */
const derive = (row) => {
  const plain = typeof row?.toObject === 'function' ? row.toObject() : { ...row };
  const now = Date.now();
  let overdueCount = 0;
  let nextDueMs = null;
  const doses = (plain.doses || []).map((dose) => {
    const dueMs = dose.dueAt ? new Date(dose.dueAt).getTime() : NaN;
    const given = Boolean(dose.givenAt);
    let state = 'upcoming';
    if (given) {
      state = 'given';
    } else if (Number.isFinite(dueMs)) {
      if (dueMs < now) {
        state = 'overdue';
        overdueCount += 1;
      } else if (dueMs <= now + DUE_WINDOW_MS) {
        state = 'due';
      }
      if (nextDueMs === null || dueMs < nextDueMs) nextDueMs = dueMs;
    }
    return { ...dose, state };
  });
  return {
    ...plain,
    doses,
    overdueCount,
    nextDueAt: nextDueMs === null ? null : new Date(nextDueMs),
  };
};

// ─── List / create ──────────────────────────────────────────────────────────

// authz: role
router.get('/', authorize('records:read:own'), async (req, res) => {
  try {
    const filter = { userId: actorId(req) };
    if (req.query.status) filter.status = req.query.status;
    if (req.query.familyMemberId !== undefined) {
      if (!OBJECT_ID.test(String(req.query.familyMemberId))) {
        return res.status(400).json({ message: 'familyMemberId must be a valid id' });
      }
      filter.familyMemberId = req.query.familyMemberId;
    }
    const rows = await VaccinationSchedule.find(filter).sort({ createdAt: -1 }).limit(200).lean();
    return res.json({ schedules: rows.map(derive) });
  } catch (err) {
    logger.error(`List vaccination schedules error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

// authz: role
router.post('/', authorize('records:write:own'), validate(createVaccinationScheduleSchema), async (req, res) => {
  try {
    // A child schedule belongs to a FAMILY MEMBER of this account: a
    // familyMemberId outside that set is a 404, never a silently-adopted
    // stranger's row (the same re-parenting hole P1-5 closed on FamilyMember).
    if (req.body.familyMemberId) {
      const member = await FamilyMember.findOne({ _id: req.body.familyMemberId, patientId: actorId(req) });
      if (!member) return res.status(404).json({ message: 'Family member not found' });
    }
    const created = await VaccinationSchedule.create({ ...req.body, userId: actorId(req) });
    await auditLog('vaccination_schedule_created', actorId(req), {
      scheduleId: created._id, familyMemberId: created.familyMemberId ?? null, ip: req.ip,
    });
    return res.status(201).json(derive(created));
  } catch (err) {
    logger.error(`Create vaccination schedule error: ${err.message}`);
    return res.status(400).json({ message: err.message });
  }
});

// ─── Detail / dose check-off / cancel ───────────────────────────────────────

// authz: role
router.get('/:id', authorize('records:read:own'), requireObjectId, async (req, res) => {
  try {
    const row = await VaccinationSchedule.findOne({ _id: req.params.id, userId: actorId(req) }).lean();
    // 404 rather than 403 for a foreign id: confirming the id exists is itself
    // a disclosure (deletionRequests' rule).
    if (!row) return res.status(404).json({ message: 'Vaccination schedule not found' });
    return res.json(derive(row));
  } catch (err) {
    logger.error(`Get vaccination schedule error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

// authz: role
router.post('/:id/doses/:number/given', authorize('records:write:own'), requireObjectId, validate(doseGivenSchema), async (req, res) => {
  try {
    const row = await VaccinationSchedule.findOne({ _id: req.params.id, userId: actorId(req) });
    if (!row) return res.status(404).json({ message: 'Vaccination schedule not found' });
    if (row.status === 'cancelled') {
      return res.status(409).json({ message: `Cannot record a dose on a '${row.status}' schedule` });
    }
    const dose = (row.doses || []).find((d) => Number(d.number) === Number(req.params.number));
    if (!dose) return res.status(404).json({ message: 'Dose not found' });
    if (dose.givenAt) return res.status(409).json({ message: 'Dose already given' });

    // The certificate is a Record; it must exist AND belong to this account
    // before it can be cited, or the link would become a cross-account read.
    if (req.body.recordId) {
      const record = await Record.findById(req.body.recordId).select('_id patientId').lean();
      if (!record || String(record.patientId) !== String(actorId(req))) {
        return res.status(404).json({ message: 'Record not found' });
      }
    }

    dose.givenAt = req.body.givenAt ?? new Date();
    if (req.body.centre !== undefined) dose.centre = req.body.centre;
    if (req.body.batchNo !== undefined) dose.batchNo = req.body.batchNo;
    if (req.body.recordId !== undefined) dose.recordId = req.body.recordId;

    // Completion is derived from the rows: every dose given means the schedule
    // is done. There is no client-writable `status`.
    const allGiven = (row.doses || []).every((d) => d.givenAt);
    if (allGiven && row.status === 'scheduled') {
      row.status = 'completed';
      row.completedAt = new Date();
    }
    await row.save();

    await auditLog('vaccination_dose_recorded', actorId(req), {
      scheduleId: row._id, doseNumber: Number(req.params.number), ip: req.ip,
    });
    return res.json(derive(row));
  } catch (err) {
    logger.error(`Record vaccination dose error: ${err.message}`);
    return res.status(400).json({ message: err.message });
  }
});

// Cancel-in-place: the schedule is history (doses were checked off against it),
// so DELETE flips `status` rather than removing the row - the same reasoning as
// providerCatalog's archive-on-delete.
// authz: role
router.delete('/:id', authorize('records:write:own'), requireObjectId, async (req, res) => {
  try {
    const row = await VaccinationSchedule.findOne({ _id: req.params.id, userId: actorId(req) });
    if (!row) return res.status(404).json({ message: 'Vaccination schedule not found' });
    if (row.status !== 'scheduled') {
      return res.status(409).json({ message: `Cannot cancel a schedule in status '${row.status}'` });
    }
    row.status = 'cancelled';
    await row.save();
    await auditLog('vaccination_schedule_cancelled', actorId(req), {
      scheduleId: row._id, ip: req.ip,
    });
    return res.json({ _id: row._id, status: row.status });
  } catch (err) {
    logger.error(`Cancel vaccination schedule error: ${err.message}`);
    return res.status(500).json({ message: err.message });
  }
});

export default router;

import express from 'express';
import VitalsLog from '../models/VitalsLog.js';
import VitalsReminder from '../models/VitalsReminder.js';
import ChronicCarePlan from '../models/ChronicCarePlan.js';
import Notification from '../models/Notification.js';
import { protect } from '../middleware/auth.js';
import logger from '../config/logger.js';

const router = express.Router();

// Helper: Calculate clinical normal/high/low/fever flag
function computeVitalFlag(vitalType, values, personalizedTarget = null) {
  if (personalizedTarget && personalizedTarget.min != null && personalizedTarget.max != null) {
    let checkVal = null;
    if (vitalType === 'bp') checkVal = values.systolic;
    else if (vitalType === 'blood_sugar') checkVal = values.sugarValue;
    else if (vitalType === 'weight') checkVal = values.weightKg;
    else if (vitalType === 'temperature') checkVal = values.tempValue;

    if (checkVal != null) {
      if (checkVal > personalizedTarget.max) return 'high';
      if (checkVal < personalizedTarget.min) return 'low';
      return 'normal';
    }
  }

  if (vitalType === 'bp') {
    const sys = values.systolic;
    const dia = values.diastolic;
    if (sys == null || dia == null) return 'normal';
    if (sys > 140 || dia > 90) return 'high';
    if (sys < 90 || dia < 60) return 'low';
    return 'normal';
  }

  if (vitalType === 'blood_sugar') {
    const val = values.sugarValue;
    if (val == null) return 'normal';
    const ctx = values.sugarContext || 'random';
    if (ctx === 'fasting') {
      if (val > 126) return 'high';
      if (val < 70) return 'low';
      return 'normal';
    } else if (ctx === 'post_meal') {
      if (val > 180) return 'high';
      if (val < 70) return 'low';
      return 'normal';
    } else {
      if (val > 180) return 'high';
      if (val < 70) return 'low';
      return 'normal';
    }
  }

  if (vitalType === 'temperature') {
    let val = values.tempValue;
    if (val == null) return 'normal';
    // Convert to Fahrenheit if unit is C for uniform evaluation
    if (values.tempUnit === 'C') {
      val = (val * 9 / 5) + 32;
    }
    if (val >= 100.4) return 'fever';
    if (val < 95.0) return 'low';
    return 'normal';
  }

  return 'normal';
}

// ── GET /api/vitals/reference-ranges ─────────────────────────────────────────
router.get('/reference-ranges', (req, res) => {
  return res.json({
    ranges: {
      bp: {
        systolic: { normalMin: 90, normalMax: 120, highThreshold: 140, lowThreshold: 90, unit: 'mmHg' },
        diastolic: { normalMin: 60, normalMax: 80, highThreshold: 90, lowThreshold: 60, unit: 'mmHg' },
        disclaimer: 'General clinical adult reference range. Consult your doctor for personalized targets.',
      },
      blood_sugar: {
        fasting: { normalMin: 70, normalMax: 100, highThreshold: 126, lowThreshold: 70, unit: 'mg/dL' },
        post_meal: { normalMin: 90, normalMax: 140, highThreshold: 180, lowThreshold: 70, unit: 'mg/dL' },
        random: { normalMin: 70, normalMax: 140, highThreshold: 180, lowThreshold: 70, unit: 'mg/dL' },
        bedtime: { normalMin: 100, normalMax: 140, highThreshold: 180, lowThreshold: 90, unit: 'mg/dL' },
      },
      temperature: {
        normalMinF: 97.0,
        normalMaxF: 99.0,
        feverThresholdF: 100.4,
        unit: '°F',
      },
      weight: {
        unit: 'kg',
        note: 'Monitored as percentage change trend over time.',
      },
    },
  });
});

// ── GET /api/vitals/trends ───────────────────────────────────────────────────
router.get('/trends', protect, async (req, res) => {
  try {
    const vitalType = req.query.vitalType || 'bp';
    const days = parseInt(req.query.days, 10) || 30;

    const sinceDate = new Date();
    sinceDate.setDate(sinceDate.getDate() - days);
    sinceDate.setHours(0, 0, 0, 0);

    const matchQuery = {
      userId: req.user._id,
      vitalType,
      recordedAt: { $gte: sinceDate },
    };

    if (req.query.carePlanId) {
      matchQuery.carePlanId = req.query.carePlanId;
    }

    const readings = await VitalsLog.find(matchQuery)
      .sort({ recordedAt: 1 })
      .lean();

    // Summary calculations
    let avg = null;
    let min = null;
    let max = null;

    if (readings.length > 0) {
      if (vitalType === 'bp') {
        const sysVals = readings.map(r => r.values.systolic).filter(v => v != null);
        const diaVals = readings.map(r => r.values.diastolic).filter(v => v != null);
        if (sysVals.length > 0 && diaVals.length > 0) {
          const avgSys = Math.round(sysVals.reduce((a, b) => a + b, 0) / sysVals.length);
          const avgDia = Math.round(diaVals.reduce((a, b) => a + b, 0) / diaVals.length);
          avg = `${avgSys}/${avgDia}`;
          min = `${Math.min(...sysVals)}/${Math.min(...diaVals)}`;
          max = `${Math.max(...sysVals)}/${Math.max(...diaVals)}`;
        }
      } else if (vitalType === 'blood_sugar') {
        const vals = readings.map(r => r.values.sugarValue).filter(v => v != null);
        if (vals.length > 0) {
          avg = Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
          min = Math.min(...vals);
          max = Math.max(...vals);
        }
      } else if (vitalType === 'weight') {
        const vals = readings.map(r => r.values.weightKg).filter(v => v != null);
        if (vals.length > 0) {
          avg = +(vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(1);
          min = Math.min(...vals);
          max = Math.max(...vals);
        }
      } else if (vitalType === 'temperature') {
        // Sab °F me badlo — °C aur °F mix ho to avg galat aata tha
        const vals = readings
          .filter(r => r.values.tempValue != null)
          .map(r => r.values.tempUnit === 'C'
            ? +((r.values.tempValue * 9) / 5 + 32).toFixed(1)
            : r.values.tempValue);
        if (vals.length > 0) {
          avg = +(vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(1);
          min = Math.min(...vals);
          max = Math.max(...vals);
        }
      }
    }

    return res.json({
      vitalType,
      days,
      count: readings.length,
      stats: { avg, min, max },
      readings,
    });
  } catch (err) {
    logger.error('Error fetching vitals trends:', err);
    return res.status(500).json({ message: 'Failed to fetch vitals trends' });
  }
});

