  doc.text('Subtotal', bx + 14, cy, { width: 90 }); doc.text(money(subtotal), bx + 104, cy, { width: 80, align: 'right' }); cy += 22;
  const dl = discountCode ? `Discount (${discountCode})` : 'Discount';
  doc.fillColor(discount > 0 ? '#b45309' : C.ink).text(dl, bx + 14, cy, { width: 90 });
  doc.fillColor(discount > 0 ? '#b45309' : C.ink).text(`-${money(discount)}`, bx + 104, cy, { width: 80, align: 'right' }); cy += 22;
  doc.fillColor(C.ink).text('Delivery', bx + 14, cy, { width: 90 }); doc.text(money(deliveryFee), bx + 104, cy, { width: 80, align: 'right' }); cy += 22;
  doc.fillColor(C.ink).text('Paid', bx + 14, cy, { width: 90 }); doc.text(money(amount), bx + 104, cy, { width: 80, align: 'right' }); cy += 22;
  doc.moveTo(bx + 14, cy - 6).lineTo(bx + bw - 14, cy - 6).strokeColor(C.border).lineWidth(0.5).stroke();
  doc.fillColor(amount > 0 ? C.success : C.muted).font('Helvetica-Bold', 10);
  doc.text('Outstanding', bx + 14, cy, { width: 90 }); doc.text('Rs. 0', bx + 104, cy, { width: 80, align: 'right' });
  doc.y = ty + 18 + rowsCount * 22 + 16;

  // ── Payment Notes ──
  ES(doc, 40);
  doc.fillColor(C.primaryDark).font('Helvetica-Bold', 11).text('PAYMENT NOTES');
  doc.moveDown(0.4);
  const note = rxNote ? `Prescription ${rxNote} Thank you for your order.` : 'Thank you for your order.';
  doc.fillColor(C.ink).font('Helvetica', 9).text(note, l, doc.y, { width: pw, lineGap: 4 });
  doc.moveDown(0.3);
  doc.fillColor(C.muted).font('Helvetica-Bold', 8.5).text('Transaction ID:', l, doc.y, { width: 80 });
  doc.fillColor(C.ink).font('Helvetica', 9).text(payment.transaction_id || '-', l + 80, doc.y - 8, { width: pw - 80 });
  doc.moveDown(1.2);

  // ── Signature ──
  ES(doc, 50);
  const sx = l + pw - 180;
  doc.strokeColor(C.border).lineWidth(0.6).moveTo(sx, doc.y).lineTo(sx + 180, doc.y).stroke();
  doc.fillColor(C.muted).font('Helvetica', 8).text(storeName, sx, doc.y + 8, { width: 180, align: 'center' });
  doc.text('Auth Signatory', sx, doc.y + 20, { width: 180, align: 'center' });
});

// ── Shared table drawer ──

const drawTable = (doc, columns, rows, left, tableWidth) => {
  const widths = columns.map(col => Math.round(tableWidth * col.w));
  let y = doc.y;
  const hdrH = 22;
  const rowH = 20;
  const fs = 8;

  const drawHdr = () => {
    doc.rect(left, y, tableWidth, hdrH).fill(C.primaryDark);
    doc.fillColor('#ffffff').font('Helvetica-Bold', 7.5);
    let x = left;
    columns.forEach((col, i) => {
      doc.text(col.label, x + 6, y + 7, { width: widths[i] - 10, align: col.a || 'left' });
      x += widths[i];
    });
    y += hdrH;
  };

  drawHdr();

  rows.forEach((row, ri) => {
    if (y + rowH > B(doc)) { doc.addPage(); drawHdr(); }
    doc.rect(left, y, tableWidth, rowH).fill(ri % 2 === 0 ? '#ffffff' : C.soft);
    doc.strokeColor(C.border).lineWidth(0.4).rect(left, y, tableWidth, rowH).stroke();
    doc.fillColor(C.ink).font('Helvetica', fs);
    let x = left;
    columns.forEach((col, ci) => {
      doc.font(col.b ? 'Helvetica-Bold' : 'Helvetica', fs)
        .text(val(row[col.key]), x + 6, y + 6, { width: widths[ci] - 10, align: col.a || 'left' });
      x += widths[ci];
    });
    y += rowH;
  });

  doc.y = y + 6;
};

import crypto from 'crypto';
import logger from '../config/logger.js';
import TwoPersonApproval from '../models/TwoPersonApproval.js';
import Notification from '../models/Notification.js';
import { getISTDateString } from '../utils/dateUtils.js';

// Active in-memory session registry for break-glass tokens (backed by DB TwoPersonApproval)
const activeBreakGlassSessions = new Map();

/**
 * Declares an emergency break-glass procedure to access locked PHI/facilities.
 * Emits CRITICAL audit logs and initiates a mandatory two-person post-incident review.
 */
export async function declareBreakGlass({
  userId,
  userName = 'Emergency Personnel',
  role = 'doctor',
  targetPatientId,
  targetHospitalId,
  emergencyReason,
  durationMinutes = 60,
  ip = '',
}) {
  if (!emergencyReason || emergencyReason.trim().length < 10) {
    const err = new Error('A detailed medical or administrative emergency reason (min 10 chars) is mandatory for break-glass');
    err.status = 400;
    throw err;
  }

  const token = crypto.randomBytes(32).toString('hex');
  const sessionId = `bg_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
  const expiresAt = new Date(Date.now() + durationMinutes * 60 * 1000);

  // Create four-eyes post-incident review requirement
  const approvalRecord = await TwoPersonApproval.requestAction({
    actionType: 'break_glass',
    targetModel: 'Patient',
    targetId: String(targetPatientId || targetHospitalId || 'system'),
    requestedBy: userId,
    requestedByName: userName,
    payload: {
      sessionId,
      role,
      emergencyReason,
      durationMinutes,
      ip,
      targetPatientId,
      targetHospitalId,
    },
    requiredApprovalsCount: 2,
    expiresInHours: 72,
  });

  const session = {
    sessionId,
    token,
    userId: String(userId),
    userName,
    role,
    targetPatientId: targetPatientId ? String(targetPatientId) : null,
    targetHospitalId: targetHospitalId ? String(targetHospitalId) : null,
    emergencyReason,
    expiresAt,
    approvalId: approvalRecord._id,
    ip,
    declaredAt: new Date(),
  };

  activeBreakGlassSessions.set(token, session);

  logger.warn(`🚨 BREAK-GLASS DECLARED by ${userName} (${role}, ID=${userId}) for patient=${targetPatientId}. Reason: "${emergencyReason}"`);

  // Alert security and compliance officers
  try {
    const { default: User } = await import('../models/User.js');
    const securityAdmins = await User.find({ role: 'superadmin' }).select('_id').limit(10).lean();
    if (securityAdmins.length) {
      await Promise.allSettled(
        securityAdmins.map((admin) =>
          Notification.create({
            userId: admin._id,
            title: 'CRITICAL: Emergency Break-Glass Declared',
            message: `User ${userName} (${role}) invoked break-glass access for patient ${targetPatientId}. Reason: ${emergencyReason}`,
            type: 'security_alert',
            date: getISTDateString(),
          })
        )
      );
    }
  } catch (notifErr) {
    logger.error(`Failed to dispatch break-glass security notifications: ${notifErr.message}`);
  }

  return {
    sessionId,
    token,
    expiresAt,
    emergencyReason,
    approvalId: approvalRecord._id,
  };
}

/**
 * Validates whether an active break-glass token authorizes access to the target patient.
 */
export function verifyBreakGlassSession({ token, targetPatientId }) {
  if (!token) return { valid: false, reason: 'No break-glass token supplied' };

  const session = activeBreakGlassSessions.get(token);
  if (!session) return { valid: false, reason: 'Invalid or unknown break-glass session token' };

  if (new Date() > session.expiresAt) {
    activeBreakGlassSessions.delete(token);
    return { valid: false, reason: 'Break-glass session has expired' };
  }

  if (targetPatientId && session.targetPatientId && String(targetPatientId) !== String(session.targetPatientId)) {
    return { valid: false, reason: 'Break-glass token not authorized for this patient ID' };
  }

  return { valid: true, session };
}

// CHAT-M-02: single source of truth for the chat attachment policy.
//
// Findings this closes (audit-reports/chat-realtime-missing.md):
//   * The /api/chat/upload endpoint accepted any MIME in its map but content-
//     sniffed ONLY the four inline image types — pdf/office/video/audio bytes
//     were written to disk unverified (polyglot/renamed-payload bypass).
//   * No anti-malware scan ran on chat uploads even though the ClamAV scanner
//     (`scanBufferForMalware`) already existed for medical-record uploads.
//   * There was no quarantine concept: a detected payload was either not
//     scanned at all or (in the dead middleware path) only rejected in-memory.
//   * POST /api/chat/messages trusted the client `attachments` array verbatim —
//     any external URL / mime / size could be persisted and later rendered to
//     other conversation members (stored content injection + dead links).
//
// Policy enforced here:
//   MIME allow-list  → exactly the ext map below (extension derived from MIME,
//                      never from the client filename — CHAT-B-06).
//   Content sniff     → magic-byte check for EVERY allowed MIME (not just
//                      images); unknown/unsupported MIME fails closed.
//   Malware scan      → ClamAV via scanBufferForMalware() (env-gated:
//                      CLAMAV_HOST unset = skip in dev/test, CLAMAV_REQUIRED
//                      = block unscanned files in prod).
//   Quarantine        → a detected payload is written to backend/quarantine/chat
//                      (OUTSIDE public/, so it can never be served) for forensic
//                      review, audited, and never reaches the upload dir.
//   Size              → MAX_CHAT_UPLOAD_BYTES (25MB), checked before decode I/O.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { v4 as uuidv4 } from 'uuid';
import { scanBufferForMalware } from '../middleware/upload.js';
import { auditLog } from '../middleware/audit.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

export const CHAT_UPLOAD_DIR = path.join(__dirname, '..', '..', 'public', 'uploads', 'chat');
// Deliberately NOT under public/ — the /uploads gate serves from public/uploads,
// so quarantined bytes must live elsewhere to be unreachable over HTTP.
export const CHAT_QUARANTINE_DIR = path.join(__dirname, '..', '..', 'quarantine', 'chat');

export const MAX_CHAT_UPLOAD_BYTES = 25 * 1024 * 1024; // 25MB

// MIME → extension. The stored extension comes from THIS map only (CHAT-B-06:
// client-supplied extensions are ignored so svg/html payloads can never be
// served from our origin). Keep in sync with ChatDashboard.tsx `accept`.
export const CHAT_EXT_MAP = {
  'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/webp': 'webp',
  'video/mp4': 'mp4', 'video/webm': 'webm',
  'audio/webm': 'webm', 'audio/mpeg': 'mp3', 'audio/ogg': 'ogg', 'audio/mp4': 'm4a',
  'application/pdf': 'pdf',
  // Office/legacy formats are stored but always served as an attachment by
  // the browser (never rendered inline on our origin).
  'application/msword': 'doc',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.ms-excel': 'xls',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
};

export const CHAT_ACCEPT_ATTR = 'image/*,video/*,audio/*,application/pdf,.doc,.docx,.xls,.xlsx';

const ascii = (buf, offset, length) => buf.slice(offset, offset + length).toString('latin1');

// Magic-byte signatures for EVERY allowed chat MIME (previously images only).
// Returns false for short/unknown buffers — fail closed.
export function chatMagicMatches(buffer, mimeType) {
  if (!buffer || buffer.length < 8) return false;
  switch (mimeType) {
    case 'image/png':
      return buffer.slice(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]));
    case 'image/jpeg':
      return buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff;
    case 'image/gif':
      return ascii(buffer, 0, 4) === 'GIF8';
    case 'image/webp':
      return ascii(buffer, 0, 4) === 'RIFF' && ascii(buffer, 8, 4) === 'WEBP';
    case 'video/mp4':
    case 'audio/mp4':
      return ascii(buffer, 4, 4) === 'ftyp';
    case 'video/webm':
    case 'audio/webm':
      return buffer[0] === 0x1a && buffer[1] === 0x45 && buffer[2] === 0xdf && buffer[3] === 0xa3;
    case 'audio/mpeg':
      // "ID3" tag or an MPEG frame sync (11 set bits).
      return ascii(buffer, 0, 3) === 'ID3'
        || (buffer[0] === 0xff && (buffer[1] & 0xe0) === 0xe0);
    case 'audio/ogg':
      return ascii(buffer, 0, 4) === 'OggS';
    case 'application/pdf':
      return ascii(buffer, 0, 4) === '%PDF';
    case 'application/msword':
    case 'application/vnd.ms-excel':
      // OLE2 compound file (D0 CF 11 E0 A1 B1 1A E1)
      return buffer[0] === 0xd0 && buffer[1] === 0xcf && buffer[2] === 0x11 && buffer[3] === 0xe0;
    case 'application/vnd.openxmlformats-officedocument.wordprocessingml.document':
    case 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet':
      // docx/xlsx are ZIP containers (PK\x03\x04)
      return buffer[0] === 0x50 && buffer[1] === 0x4b && buffer[2] === 0x03 && buffer[3] === 0x04;
    default:
      return false; // unknown MIME → fail closed
  }
}

export function isAllowedChatMime(mimeType) {
  return Object.prototype.hasOwnProperty.call(CHAT_EXT_MAP, mimeType);
}

// Returns null when the attachment list is acceptable, otherwise an
// Express-ready { status, message }. Used by POST /api/chat/messages so the
// client-supplied attachments array can no longer smuggle external URLs,
// lying mimes, oversize values, or references to files that do not exist.
export function validateChatAttachments(attachments) {
  if (attachments == null) return null;
  if (!Array.isArray(attachments)) {
    return { status: 400, message: 'attachments must be an array' };
  }
  if (attachments.length > 16) {
    return { status: 400, message: 'Too many attachments (max 16)' };
  }
  for (const att of attachments) {
    if (!att || typeof att !== 'object') {
      return { status: 400, message: 'Invalid attachment entry' };
    }
    const { url, size } = att;
    const mimeType = att.mimeType ?? att.mimetype; // legacy lowercase tolerated on READ, never written
    if (typeof url !== 'string' || !url.startsWith('/uploads/chat/')) {
      return { status: 400, message: 'Attachment must be an uploaded chat file' };
    }
    // basename only — rejects traversal ("..") and absolute/external URLs.
    const fileName = path.posix.basename(url);
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.[a-z0-9]{1,5}$/.test(fileName)) {
      return { status: 400, message: 'Attachment filename is not valid' };
    }
    if (!isAllowedChatMime(mimeType)) {
      return { status: 415, message: `Unsupported file type: ${mimeType || 'unknown'}` };
    }
    const ext = CHAT_EXT_MAP[mimeType];
    if (fileName.endsWith(`.${ext}`) === false) {
      return { status: 415, message: 'Attachment type does not match its stored file' };
    }
    if (typeof size !== 'number' || !Number.isFinite(size) || size <= 0 || size > MAX_CHAT_UPLOAD_BYTES) {
      return { status: 413, message: 'File too large (max 25MB)' };
    }
    if (!fs.existsSync(path.join(CHAT_UPLOAD_DIR, fileName))) {
      return { status: 400, message: 'Attachment file is no longer available' };
    }
  }
  return null;
}

// Full gate for one decoded upload buffer: size → MIME allow-list → magic bytes
// → malware scan (quarantining on detection) → write to the upload dir.
// Returns { url, name, mimeType, size } or throws { status, message }.
export async function storeChatUpload({ buffer, mimeType, name, userId }) {
  if (buffer.length > MAX_CHAT_UPLOAD_BYTES) {
    throw { status: 413, message: 'File too large (max 25MB)' };
  }
  const ext = CHAT_EXT_MAP[mimeType];
  if (!ext) {
    throw { status: 415, message: `Unsupported file type: ${mimeType}` };
  }
  if (!chatMagicMatches(buffer, mimeType)) {
    throw { status: 415, message: 'File content does not match its type' };
  }

  const { clean, malware, blocked } = await scanBufferForMalware(buffer);
  if (!clean) {
    // Quarantine the bytes (outside public/) so the sample is available for
    // review, and record who/what was rejected. Never written to UPLOAD_DIR.
    const quarantinedName = `${uuidv4()}.${ext}.quarantined`;
    try {
      if (!fs.existsSync(CHAT_QUARANTINE_DIR)) fs.mkdirSync(CHAT_QUARANTINE_DIR, { recursive: true });
      fs.writeFileSync(path.join(CHAT_QUARANTINE_DIR, quarantinedName), buffer);
    } catch { /* quarantine must not mask the rejection */ }
    // AuditLog.userId is required (ADM-M-02) — the route always passes the
    // authenticated uploader; a missing id is swallowed by auditLog's catch.
    await auditLog('chat_upload_quarantined', userId ?? null, {
      quarantineName: quarantinedName,
      originalName: typeof name === 'string' ? name.slice(0, 200) : 'file',
      mimeType,
      size: buffer.length,
      reason: blocked ? 'scan_unavailable' : (malware || 'malware'),
    });
    throw blocked
      ? { status: 503, message: 'File scanning is unavailable, upload rejected. Try again later.' }
      : { status: 422, message: 'File rejected: malware detected' };
  }

  if (!fs.existsSync(CHAT_UPLOAD_DIR)) fs.mkdirSync(CHAT_UPLOAD_DIR, { recursive: true });
  const filename = `${uuidv4()}.${ext}`;
  fs.writeFileSync(path.join(CHAT_UPLOAD_DIR, filename), buffer);
  return { url: `/uploads/chat/${filename}`, name, mimeType, size: buffer.length };
}

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const configPath = path.join(__dirname, '../config/interactions.json');
let interactionDb;
try {
  interactionDb = JSON.parse(fs.readFileSync(configPath, 'utf8'));
} catch {
  interactionDb = [];
}

// T3: knowledge-base provenance lives NEXT TO the pair data (not inside it —
// interactions.json must remain a pure array for the data-lint test).
const metaPath = path.join(__dirname, '../config/interactions.meta.json');
let knowledgeBaseMeta;
try {
  knowledgeBaseMeta = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
} catch {
  knowledgeBaseMeta = null;
}

/**
 * Provenance for /ddi/check consumers: version, review status and the
 * clinical disclaimer. `pairCount` is computed live so it can never drift
 * from the actual knowledge base.
 */
export function getKnowledgeBase() {
  return {
    version: knowledgeBaseMeta?.version || 'unversioned',
    updatedAt: knowledgeBaseMeta?.updatedAt || null,
    pairCount: NORMALIZED_DB.length,
    reviewStatus: knowledgeBaseMeta?.reviewStatus || 'unknown',
    reviewedBy: knowledgeBaseMeta?.reviewedBy || null,
    reviewedAt: knowledgeBaseMeta?.reviewedAt || null,
    reviewCadence: knowledgeBaseMeta?.reviewCadence || null,
    disclaimer:
      knowledgeBaseMeta?.disclaimer
      || 'Clinical decision support — not a substitute for professional judgement.',
  };
}

// Pre-compute normalized keys once at load — the hot loop below used to
// re-normalize every entry for every (drug_i, drug_j) pair: O(n² · db).
const NORMALIZED_DB = interactionDb.map((entry) => ({
  entry,
  keyA: normalizeName(entry.drugA),
  keyB: normalizeName(entry.drugB),
  pairKey: [normalizeName(entry.drugA), normalizeName(entry.drugB)].sort().join('::'),
}));

/**
 * Normalizes drug name: lowercases, trims, strips strength tokens
 * (500mg, 0.5mg, 10ml), brackets and generic suffixes.
 */
function normalizeName(name) {
  if (!name || typeof name !== 'string') return '';
  return name
    .toLowerCase()
    .trim()
    .replace(/\s*\([^)]*\)/g, '')
    .replace(/\b\d+(\.\d+)?\s*(mg|mcg|g|ml|iu|units?)\b/g, '')
    .replace(/[^a-z0-9 ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// T3: memoize repeated checks (pharmacy re-checks the same Rx on every render
// pass; the doctor's draft re-checks on each keystroke via the route layer).
const checkCache = new Map();
const CACHE_MAX = 500;

/**
 * Checks a list of prescribed drug names against known drug-drug interaction pairs.
 * Matching is symmetric (A+B = B+A) and subsumption-based ("warfarin 5mg"
 * matches entry "warfarin"). Unknown drugs are reported as `unknownDrugs` so
 * the UI can say "not checked" instead of silently showing "safe".
 * @param {Array<string|object>} drugs - list of drug / medicine names
 * @returns {{interactions: Array<object>, unknownDrugs: Array<string>}}
 */
export function checkDrugInteractionsDetailed(drugs = []) {
  if (!Array.isArray(drugs) || drugs.length < 2) {
    return { interactions: [], unknownDrugs: Array.isArray(drugs) ? drugs.map((d) => label(d)).filter(Boolean) : [] };
  }

  const labels = drugs.map((d) => label(d));
  const normalizedList = drugs
    .map((d) => normalizeName(typeof d === 'string' ? d : d?.name || d?.medicineName || d?.genericName || ''))
    .filter(Boolean);

  const cacheKey = [...normalizedList].sort().join('|');
  const cached = checkCache.get(cacheKey);
  if (cached) return cached;

  const matched = [];
  const seenPairKeys = new Set();
  const matchedDrugIdx = new Set();

  for (let i = 0; i < normalizedList.length; i++) {
    for (let j = i + 1; j < normalizedList.length; j++) {
      const drug1 = normalizedList[i];
      const drug2 = normalizedList[j];

      for (const { entry, keyA, keyB, pairKey } of NORMALIZED_DB) {
        if (!keyA || !keyB) continue;
        // Symmetric subsumption match.
        const match =
          (drug1.includes(keyA) && drug2.includes(keyB)) ||
          (drug1.includes(keyB) && drug2.includes(keyA));
        if (!match) continue;
        if (!seenPairKeys.has(pairKey)) {
          seenPairKeys.add(pairKey);
          matched.push({
            drugA: entry.drugA,
            drugB: entry.drugB,
            detectedPair: [labels[i], labels[j]],
            severity: entry.severity,
            effect: entry.effect,
            recommendation: entry.recommendation,
          });
        }
        matchedDrugIdx.add(i);
        matchedDrugIdx.add(j);
      }
    }
  }

  const severityOrder = { major: 1, moderate: 2, minor: 3 };
  matched.sort((a, b) => (severityOrder[a.severity] || 99) - (severityOrder[b.severity] || 99));

  // Any prescribed drug that matched NOTHING against the DB may still be
  // unknown to the knowledge base — surface it as "not checked". A drug that
  // matched at least one pair is obviously known, so we only report the rest
  // when the DB did not cover them at all. This is heuristic: an unknown drug
  // paired with a known drug with no interaction row is indistinguishable from
  // "checked, no interaction" without a drug formulary — so we mark ALL
  // non-matching drugs as unchecked when they don't appear verbatim in the DB.
  const dbKeys = new Set();
  for (const { keyA, keyB } of NORMALIZED_DB) {
    if (keyA) dbKeys.add(keyA);
    if (keyB) dbKeys.add(keyB);
  }
  const unknownDrugs = normalizedList.filter((n, idx) => !matchedDrugIdx.has(idx) && !dbKeys.has(n));

  const result = { interactions: matched, unknownDrugs };
  if (checkCache.size >= CACHE_MAX) checkCache.clear();
  checkCache.set(cacheKey, result);
  return result;
}

function label(d) {
  if (typeof d === 'string') return d;
  return d?.name || d?.medicineName || d?.genericName || '';
}

/**
 * Back-compat wrapper: returns just the interaction list (sorted by severity).
 */
export function checkDrugInteractions(drugs = []) {
  return checkDrugInteractionsDetailed(drugs).interactions;
}

export default {
  checkDrugInteractions,
  checkDrugInteractionsDetailed,
  getKnowledgeBase,
};

