/**
 * LIS Auto-Analyzer Driver Engine (ASTM E1381 / E1394 & HL7 v2.5 LIS Parser)
 * Connects to Biochemistry / Hematology / Immunoassay Analyzers via RS-232 / TCP Socket.
 * Emulates bidirectional communication:
 * 1. Queries LIS for test orders by Accession Number / Barcode
 * 2. Receives raw machine result packets and automatically parses them into structured lab results.
 */

const processedMessageIds = new Set();

export function resetProcessedMessages() {
  processedMessageIds.clear();
}

export function parseAstmPacket(rawAstmText, options = {}) {
  // ASTM E1394 Record Types:
  // H = Header, P = Patient, O = Order, R = Result, C = Comment, L = Terminator
  const lines = rawAstmText.split(/\r?\n|\r/);
  const results = [];
  let currentSampleId = '';

  for (const line of lines) {
    if (!line.trim()) continue;
    const fields = line.split('|');
    const recordType = fields[0]?.replace(/^\d+/, ''); // strip sequence digit if present

    if (recordType === 'O') {
      // Order Record: O|1|SampleBarcode|...
      currentSampleId = fields[2] || fields[3] || 'UNKNOWN_SAMPLE';
    } else if (recordType === 'R') {
      // Result Record: R|1|^^^TestCode|Value|Units|RefRange|AbnormalFlag|...
      const testIdent = fields[2] || '';
      const testCode = (testIdent.split('^').filter(Boolean).pop() || testIdent).trim();
      const value = fields[3] || '';
      const units = fields[4] || '';
      const refRange = fields[5] || '';
      const flag = fields[6] || 'N'; // N = Normal, H = High, L = Low, A = Abnormal

      const isUnknown = !testCode
        || testCode.toUpperCase().includes('UNKNOWN')
        || (options.knownTestCodes && !options.knownTestCodes.includes(testCode));

      const isQuarantined = Boolean(isUnknown && (options.quarantineUnknown ?? true));

      results.push({
        sampleId: currentSampleId,
        testCode,
        value: parseFloat(value) || value,
        units: units.trim(),
        referenceRange: refRange.trim(),
        flag: flag.trim(),
        status: isQuarantined
          ? 'QUARANTINE'
          : (flag === 'N' ? 'NORMAL' : 'CRITICAL_ABNORMAL'),
        isQuarantined,
        receivedAt: new Date().toISOString(),
      });
    }
  }

  return {
    protocol: 'ASTM_E1394',
    sampleCount: currentSampleId ? 1 : 0,
    results,
    quarantinedCount: results.filter((r) => r.isQuarantined).length,
  };
}

export function parseHl7OruR01Packet(rawHl7Text, options = {}) {
  // HL7 v2.5 ORU^R01 (Observation Result Unsolicited)
  const segments = rawHl7Text.split(/\r?\n|\r/);
  const results = [];
  let sampleId = '';

  for (const seg of segments) {
    if (seg.startsWith('OBR')) {
      const parts = seg.split('|');
      sampleId = parts[3] || parts[2] || '';
    } else if (seg.startsWith('OBX')) {
      // OBX|1|NM|WBC^White Blood Count^LN||8.5|10*3/uL|4.0-11.0|N|...
      const parts = seg.split('|');
      const testId = parts[3] || '';
      const rawCode = (testId.split('^')[0] || '').trim();
      const testName = testId.split('^')[1] || rawCode || 'Unknown';
      const value = parts[5] || '';
      const units = parts[6] || '';
      const ref = parts[7] || '';
      const flag = parts[8] || 'N';

      const isUnknown = !rawCode
        || rawCode.toUpperCase().includes('UNKNOWN')
        || (options.knownTestCodes && !options.knownTestCodes.includes(rawCode));

      const isQuarantined = Boolean(isUnknown && (options.quarantineUnknown ?? true));

      results.push({
        sampleId,
        testCode: rawCode,
        testName,
        value: parseFloat(value) || value,
        units,
        referenceRange: ref,
        flag,
        status: isQuarantined
          ? 'QUARANTINE'
          : (flag === 'N' ? 'NORMAL' : 'ABNORMAL'),
        isQuarantined,
        receivedAt: new Date().toISOString(),
      });
    }
  }

  return {
    protocol: 'HL7_v2.5_ORU_R01',
    sampleId,
    results,
    quarantinedCount: results.filter((r) => r.isQuarantined).length,
  };
}

export async function processAnalyzerResultUpload({
  analyzerId,
  model,
  rawPayload,
  protocol = 'ASTM',
  messageId,
  knownTestCodes,
  quarantineUnknown = true,
}) {
  if (messageId && processedMessageIds.has(messageId)) {
    return {
      duplicate: true,
      idempotent: true,
      messageId,
      analyzerId: analyzerId || 'BIOCHEM-XL-640',
      analyzerModel: model || 'Erba Lachema XL-640',
      parsedRecords: 0,
      data: { protocol, results: [], sampleCount: 0 },
      importedAt: new Date(),
    };
  }

  if (messageId) {
    processedMessageIds.add(messageId);
  }

  const parseOpts = { knownTestCodes, quarantineUnknown };
  let parsed;
  if (protocol.toUpperCase() === 'HL7') {
    parsed = parseHl7OruR01Packet(rawPayload, parseOpts);
  } else {
    parsed = parseAstmPacket(rawPayload, parseOpts);
  }

  return {
    analyzerId: analyzerId || 'BIOCHEM-XL-640',
    analyzerModel: model || 'Erba Lachema XL-640',
    messageId: messageId || null,
    duplicate: false,
    idempotent: false,
    parsedRecords: parsed.results.length,
    quarantinedRecords: parsed.quarantinedCount || 0,
    data: parsed,
    importedAt: new Date(),
  };
}

const activeAnalyzerConnections = new Map();

/**
 * Creates an in-process TCP listener for LIS analyzers connecting over LAN (ASTM/HL7).
 */
export async function startLisTcpServer({ port = 5100, onResult } = {}) {
  const net = await import('node:net');
  const server = net.createServer((socket) => {
    const remoteId = `${socket.remoteAddress}:${socket.remotePort}`;
    activeAnalyzerConnections.set(remoteId, {
      connectedAt: new Date(),
      lastHeartbeat: new Date(),
      socket,
    });

    let buffer = '';
    socket.on('data', async (chunk) => {
      const conn = activeAnalyzerConnections.get(remoteId);
      if (conn) conn.lastHeartbeat = new Date();

      buffer += chunk.toString('utf8');
      if (buffer.includes('\r\n') || buffer.includes('\r') || buffer.includes('\x1c')) {
        try {
          const res = await processAnalyzerResultUpload({
            analyzerId: `TCP-${remoteId}`,
            rawPayload: buffer,
            protocol: buffer.startsWith('MSH') ? 'HL7' : 'ASTM',
          });
          if (onResult) onResult(res);
          socket.write('\x06'); // ACK character
        } catch {}
        buffer = '';
      }
    });

    socket.on('close', () => {
      activeAnalyzerConnections.delete(remoteId);
    });

    socket.on('error', () => {
      activeAnalyzerConnections.delete(remoteId);
    });
  });

  return server;
}

/**
 * Returns active analyzer connection heartbeats and connection health.
 */
export function getActiveAnalyzerHeartbeats() {
  const now = Date.now();
  const list = [];
  for (const [id, info] of activeAnalyzerConnections.entries()) {
    const ageSec = Math.round((now - info.lastHeartbeat.getTime()) / 1000);
    list.push({
      connectionId: id,
      connectedAt: info.connectedAt,
      lastHeartbeat: info.lastHeartbeat,
      healthy: ageSec < 60,
      ageSec,
    });
  }
  return list;
}

import mongoose from 'mongoose';
import LoyaltyLedger from '../models/LoyaltyLedger.js';
import LoyaltyEarnRule from '../models/LoyaltyEarnRule.js';
import User from '../models/User.js';
import Referral from '../models/Referral.js';
import RewardCatalogItem from '../models/RewardCatalogItem.js';
import RewardRedemption from '../models/RewardRedemption.js';
import logger from '../config/logger.js';
import { randomInt } from 'node:crypto';

export const loyaltyService = {
  /**
   * Initialize default earn rules if they don't exist
   */
  async initializeEarnRules() {
    const rules = [
      { action: 'ride_completed', points: 25 },
      { action: 'consultation_completed', points: 30 },
      { action: 'blood_donation_completed', points: 500 },
      { action: 'appointment_completed', points: 20 },
      { action: 'lab_order_completed', points: 50 },
      { action: 'pharmacy_order_completed', points: 30 },
      { action: 'review_submitted', points: 10 },
      { action: 'referral_qualified', points: 100 },
      { action: 'profile_completed', points: 50 },
    ];

    for (const rule of rules) {
      const exists = await LoyaltyEarnRule.findOne({ action: rule.action }).lean();
      if (!exists) {
        await LoyaltyEarnRule.create(rule);
      }
    }
  },

  /**
   * Earn points for a qualifying action.
   * LOY-M-01: idempotent per (user, action, refId). Dispatch/booking retries
   * and double webhook deliveries used to credit the same completion twice
   * with no unique guard on `earn` rows. A pre-check plus the
   * `loyalty_earn_once` partial unique index (see LoyaltyLedger) makes a
   * duplicate earn a no-op returning 0.
   */
  async earnPoints(userId, actionType, refId = null) {
    if (refId) {
      const dupe = await LoyaltyLedger.findOne({ userId, type: 'earn', reason: actionType, refId }).lean();
      if (dupe) return 0;
    }
    const rule = await LoyaltyEarnRule.findOne({ action: actionType, isActive: true }).lean();
    if (!rule) return 0;

    const user = await User.findById(userId);
    if (!user) return 0;

    const points = rule.points;

    // Update user balances
    user.loyalty.pointsBalance += points;
    user.loyalty.lifetimePoints += points;

    // Tier recalculation based on lifetime points
    if (user.loyalty.lifetimePoints >= 500) user.loyalty.tier = 'Silver';
    if (user.loyalty.lifetimePoints >= 1500) user.loyalty.tier = 'Gold';
    if (user.loyalty.lifetimePoints >= 3000) user.loyalty.tier = 'Platinum';

    await user.save();

    // Log in ledger (LOY-M-01: concurrent double-earns lose the race here).
    try {
      await LoyaltyLedger.create({
        userId,
        type: 'earn',
        points,
        reason: actionType,
        refId,
        balanceAfter: user.loyalty.pointsBalance,
      });
    } catch (err) {
      if (err?.code === 11000) return 0;
      throw err;
    }

    return points;
  },

  /**
   * LOY-M-01 reconciliation: ledger truth vs cached user balances.
   * Returns the earn/reverse/redeem totals, the ledger-derived balance, the
   * stored balance, and whether they agree. Callers (jobs/support) use the
   * mismatch to decide on a repair; this function never writes.
   */
  async reconcileBalance(userId) {
    const rows = await LoyaltyLedger.find({ userId }).select('type points').lean();
    let earned = 0;
    let reversed = 0;
    let redeemed = 0;
    for (const r of rows) {
      if (r.type === 'earn') earned += Number(r.points) || 0;
      else if (r.type === 'reverse') reversed += Number(r.points) || 0; // negative
      else if (r.type === 'redeem') redeemed += Number(r.points) || 0; // negative
    }
    const ledgerBalance = earned + reversed + redeemed;
    const user = await User.findById(userId).select('loyalty').lean();
    const storedBalance = user?.loyalty?.pointsBalance ?? null;
    return {
      earned, reversed, redeemed, ledgerBalance, storedBalance,
      matches: storedBalance === null ? null : storedBalance === ledgerBalance,
      entries: rows.length,
    };
  },

  /**
   * Reverse a previous earn when the booking it belongs to is cancelled
   * (LOYAL-M-02). Guarantees:
   * - Idempotent: at most one `reverse` ledger row per (user, action, refId),
   *   enforced by a partial unique index and a cheap pre-check, so a retried
   *   cancel never deducts twice.
   * - Exact: claws back the points the earn ACTUALLY credited (read from the
   *   ledger), not the current rule amount — a rule edit between earn and
   *   cancel must not change the refund.
   * - No earn → no-op: cancelling a booking that never earned (rides only earn
   *   on completion) must not move balances or create rows.
   * - Reverses BOTH balances: pointsBalance (spendable) and lifetimePoints
   *   (drives tier), then walks the tier down the same 500/1500/3000 ladder
   *   earnPoints climbs. The spendable balance may go negative when the user
   *   already redeemed the points — an honest visible debt; clamping to zero
   *   would keep exactly the inflated points this removes (redeemReward
   *   already refuses to spend a negative balance).
   * Fail-soft by design: callers fire-and-forget with a .catch — a reversal
   * failure must never fail the cancellation it accompanies.
   */
  async reversePoints(userId, actionType, refId = null) {
    const reversalReason = `reversed:${actionType}`;

    const existing = await LoyaltyLedger.findOne({
      userId,
      type: 'reverse',
      reason: reversalReason,
      ...(refId ? { refId } : {}),
    }).lean();
    if (existing) return { reversed: 0, alreadyReversed: true };

    const earn = await LoyaltyLedger.findOne({
      userId,
      type: 'earn',
      reason: actionType,
      ...(refId ? { refId } : {}),
    })
      .sort({ createdAt: -1 })
      .lean();
    if (!earn || !(earn.points > 0)) return { reversed: 0 };

    const points = earn.points;
    const updated = await User.findOneAndUpdate(
      { _id: userId },
      { $inc: { 'loyalty.pointsBalance': -points, 'loyalty.lifetimePoints': -points } },
      { new: true },
    ).select('loyalty');
    if (!updated) return { reversed: 0 };

    try {
      await LoyaltyLedger.create({
        userId,
        type: 'reverse',
        points: -points,
        reason: reversalReason,
        refId,
        balanceAfter: updated.loyalty.pointsBalance,
      });
    } catch (err) {
      if (err?.code === 11000) {
        // A concurrent reversal won the unique-index race — give the points
        // back so the balance is decremented exactly once, then report the
        // no-op.
        try {
          await User.updateOne(
            { _id: userId },
            { $inc: { 'loyalty.pointsBalance': points, 'loyalty.lifetimePoints': points } },
          );
        } catch (undoErr) {
          logger.error(
            `loyalty reversePoints: undo of double-decrement failed for user ${userId}: ${undoErr.message}`,
          );
        }
        return { reversed: 0, alreadyReversed: true };
      }
      throw err;
    }

    const lifetime = updated.loyalty.lifetimePoints;
    const tier =
      lifetime >= 3000 ? 'Platinum' : lifetime >= 1500 ? 'Gold' : lifetime >= 500 ? 'Silver' : 'Bronze';
    if (tier !== updated.loyalty.tier) {
      await User.updateOne({ _id: userId }, { $set: { 'loyalty.tier': tier } });
    }

    return { reversed: points, newBalance: updated.loyalty.pointsBalance, tier };
  },

  /**
   * Redeem reward - user spends points
   */
  async redeemReward(userId, catalogItemId) {
    const catalogItem = await RewardCatalogItem.findById(catalogItemId).lean();
    if (!catalogItem || !catalogItem.isActive) return { success: false, message: 'Reward not available' };

    // Check stock limit
    if (catalogItem.stockLimit > 0 && catalogItem.redeemedCount >= catalogItem.stockLimit) {
      return { success: false, message: 'Reward out of stock' };
    }

    // LOYALTY-BUG-01: Atomic conditional debit to prevent double-spending & race conditions
    const updatedUser = await User.findOneAndUpdate(
      {
        _id: userId,
        'loyalty.pointsBalance': { $gte: catalogItem.pointsRequired },
      },
      {
        $inc: { 'loyalty.pointsBalance': -catalogItem.pointsRequired },
      },
      { new: true }
    ).select('loyalty');

    if (!updatedUser) {
      return { success: false, message: 'Insufficient points' };
    }

    // Create redemption record
    const code = generateUniqueCode(8).toUpperCase();
    const expiresAt = new Date(Date.now() + catalogItem.validityDays * 24 * 60 * 60 * 1000);

    const redemption = new RewardRedemption({
      userId,
      rewardCatalogItemId: catalogItemId,
      pointsSpent: catalogItem.pointsRequired,
      code,
      expiresAt,
    });
    await redemption.save();

    // Log in ledger
    await LoyaltyLedger.create({
      userId,
      type: 'redeem',
      points: -catalogItem.pointsRequired,
      reason: `reward_redeemed:${catalogItem.code}`,
      refId: catalogItemId,
      balanceAfter: updatedUser.loyalty.pointsBalance,
    });

    // Update catalog redeemed count
    await RewardCatalogItem.findByIdAndUpdate(catalogItemId, { $inc: { redeemedCount: 1 } });

    return {
      success: true,
      code,
      pointsSpent: catalogItem.pointsRequired,
      newBalance: updatedUser.loyalty.pointsBalance,
      expiresAt,
    };
  },

  /**
   * Get user's loyalty summary
   */
  async getSummary(userId) {
    const user = await User.findById(userId).select('loyalty');
    if (!user) return null;

    return {
      pointsBalance: user.loyalty.pointsBalance,
      lifetimePoints: user.loyalty.lifetimePoints,
      tier: user.loyalty.tier,
    };
  },

  /**
   * Get user's redemption history
   */
  async getRedemptions(userId) {
    return await RewardRedemption.find({ userId })
      .sort({ createdAt: -1 })
      .lean();
  },

  /**
   * Get active rewards catalog (filtered by user's balance)
   */
  async getCatalog(userId) {
    const catalog = await RewardCatalogItem.find({ isActive: true }).lean();

    const user = await User.findById(userId);
    if (!user) return catalog;

    return catalog.map(item => ({
      ...item,
      isUnlocked: user.loyalty.pointsBalance >= item.pointsRequired,
      pointsNeeded: item.pointsRequired - user.loyalty.pointsBalance,
    }));
  },

  /**
   * Apply reward at checkout - validate and calculate discount
   */
  async applyRewardAtCheckout(userId, code, orderType) {
    const redemption = await RewardRedemption.findOne({
      code,
      userId,
      status: 'active',
    }).lean();

    if (!redemption) return { success: false, message: 'Invalid or expired reward code' };

    if (redemption.expiresAt < new Date()) {
      return { success: false, message: 'Reward code expired' };
    }

    // Check applicable service
    const catalogItem = await RewardCatalogItem.findById(redemption.rewardCatalogItemId).lean();
    if (!catalogItem) return { success: false, message: 'Reward catalog item not found' };

    // Check if this reward applies to this order type
    const serviceMap = {
      pharmacy: 'pharmacy',
      lab: 'lab',
      delivery: 'delivery',
      consultation: 'consultation',
    };

    if (catalogItem.applicableService !== 'all' && catalogItem.applicableService !== serviceMap[orderType]) {
      return { success: false, message: 'This reward does not apply to this order type' };
    }

    // Calculate discount
    let discount = 0;
    let discountType = 'fixed';
    const capAmount = catalogItem.maxCapAmount || 0;

    if (catalogItem.rewardType === 'percentage') {
      // percentage discount - will be calculated at checkout based on order total
      discount = catalogItem.rewardValue; // e.g. 20 means 20%
      discountType = 'percentage';
    } else if (catalogItem.rewardType === 'fixed') {
      discount = catalogItem.rewardValue; // e.g. 300 means ₹300 off
      discountType = 'fixed';
    } else if (catalogItem.rewardType === 'free_item') {
      discount = capAmount; // free delivery up to cap amount
      discountType = 'free_item';
    }

    return {
      success: true,
      discount,
      discountType,
      capAmount,
      rewardTitle: catalogItem.title,
    };
  },
};

/**
 * Generate a unique code (helper)
 */
function generateUniqueCode(length = 8) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let code = '';
  for (let i = 0; i < length; i++) {
    code += chars.charAt(randomInt(0, chars.length));
  }
  return code;
}

/**
 * MIND-M-01: validated screening instruments with real scoring.
 *
 * The finding said intake had free-text fields and no standardised scoring. That
 * is not just a feature gap here - free-text "how have you been feeling" cannot
 * be trended, cannot trigger a protocol, and cannot tell a clinician that a
 * patient's score fell from 22 to 17. Severity, in mental health, is the number.
 *
 * WHY THE SCORING IS WRITTEN OUT RATHER THAN APPROXIMATED
 * PHQ-9 and GAD-7 have published cut-points, and they are not interchangeable
 * with intuition. A PHQ-9 of 12 is "moderate"; a GAD-7 of 12 is also "moderate"
 * but the maxima differ (27 vs 21), so a shared percentage would misclassify.
 * The bands below are the validated ones.
 *
 * ITEM 9 OF PHQ-9 IS NOT A SCORE ITEM
 * It is a suicidality indicator. It contributes to the total (it must, or the
 * instrument is not PHQ-9) but any non-zero answer is a SEPARATE signal that must
 * reach a human. Scoring it into a total and losing the distinction is how a
 * risk flag disappears into a dashboard. `suicidalityFlagged` is therefore
 * surfaced independently of severity and never suppressed by a low total.
 */

export const RESPONSE_OPTIONS = [
  { value: 0, label: 'Not at all' },
  { value: 1, label: 'Several days' },
  { value: 2, label: 'More than half the days' },
  { value: 3, label: 'Nearly every day' },
];

const band = (score, ranges) =>
  ranges.find(([max, label]) => score <= max)?.[1] ?? ranges[ranges.length - 1][1];

/**
 * PHQ-9 - Patient Health Questionnaire, 9 items.
 * https://www.phqscreeners.com/select-screener
 */
export const PHQ9 = {
  id: 'PHQ-9',
  label: 'PHQ-9 (Patient Health Questionnaire-9)',
  itemCount: 9,
  maxScore: 27,
  // Validated severity bands for the total.
  severity: (score) => band(score, [[4, 'Minimal'], [9, 'Mild'], [14, 'Moderate'], [19, 'Moderately severe'], [27, 'Severe']]),
  // The accepted threshold for clinically significant change on re-administration.
  reliableChange: 5,
  // A validated referral trigger: moderate or worse should not sit un-actioned.
  referralThreshold: 10,
  items: [
    { id: 'phq9_1', text: 'Little interest or pleasure in doing things' },
    { id: 'phq9_2', text: 'Feeling down, depressed, or hopeless' },
    { id: 'phq9_3', text: 'Trouble falling or staying asleep, or sleeping too much' },
    { id: 'phq9_4', text: 'Feeling tired or having little energy' },
    { id: 'phq9_5', text: 'Poor appetite or overeating' },
    { id: 'phq9_6', text: 'Feeling bad about yourself, or that you are a failure or have let yourself or your family down' },
    { id: 'phq9_7', text: 'Trouble concentrating on things' },
    { id: 'phq9_8', text: 'Moving or speaking so slowly that other people could have noticed, or the opposite - being so fidgety or restless that you have been moving around a lot more than usual' },
    { id: 'phq9_9', text: 'Thoughts that you would be better off dead, or of hurting yourself in some way', suicidalityItem: true },
  ],
};

/**
 * GAD-7 - Generalized Anxiety Disorder scale, 7 items.
 * https://www.phqscreeners.com/select-screener
 */
export const GAD7 = {
  id: 'GAD-7',
  label: 'GAD-7 (Generalized Anxiety Disorder scale)',
  itemCount: 7,
  maxScore: 21,
  severity: (score) => band(score, [[4, 'Minimal'], [9, 'Mild'], [14, 'Moderate'], [21, 'Severe']]),
  // Validated reliable-change threshold for GAD-7 (vs PHQ-9's 5).
  reliableChange: 4,
  referralThreshold: 10,
  items: [
    { id: 'gad7_1', text: 'Feeling nervous, anxious, or on edge' },
    { id: 'gad7_2', text: 'Not being able to stop or control worrying' },
    { id: 'gad7_3', text: 'Worrying too much about different things' },
    { id: 'gad7_4', text: 'Trouble relaxing' },
    { id: 'gad7_5', text: 'Being so restless that it is hard to sit still' },
    { id: 'gad7_6', text: 'Becoming easily annoyed or irritable' },
    { id: 'gad7_7', text: 'Feeling afraid, as if something awful might happen' },
  ],
};

export const INSTRUMENTS = { 'PHQ-9': PHQ9, 'GAD-7': GAD7 };
export const INSTRUMENT_IDS = Object.keys(INSTRUMENTS);

/**
 * Score a completed instrument.
 *
 * REJECTS rather than coercing. A screening instrument with a missing item is
 * not a low score, it is an invalid one - and an invalid screen that scores 0
 * is the most dangerous possible output here, because it reads as "well" to
 * everything downstream.
 *
 * @param {string} instrumentId
 * @param {Record<string, number>} answers keyed by item id
 * @returns {{ valid, reason?, instrument, total, maxScore, severity, percentage, suicidalityFlagged, referralSuggested, responses }}
 */
export const score = (instrumentId, answers = {}) => {
  const instrument = INSTRUMENTS[instrumentId];
  if (!instrument) {
    return { valid: false, reason: `Unknown instrument "${instrumentId}". Expected one of: ${INSTRUMENT_IDS.join(', ')}` };
  }
  if (!answers || typeof answers !== 'object') {
    return { valid: false, reason: 'answers must be an object keyed by item id' };
  }

  const missing = [];
  const outOfRange = [];
  let total = 0;

  for (const item of instrument.items) {
    const raw = answers[item.id];
    if (raw === undefined || raw === null || raw === '') {
      missing.push(item.id);
      continue;
    }
    const value = Number(raw);
    if (!Number.isInteger(value) || value < 0 || value > 3) {
      outOfRange.push(item.id);
      continue;
    }
    total += value;
  }

  if (missing.length) {
    return { valid: false, reason: `Missing response(s) for: ${missing.join(', ')}`, instrument: instrument.id };
  }
  if (outOfRange.length) {
    return { valid: false, reason: `Response(s) out of range (0-3) for: ${outOfRange.join(', ')}`, instrument: instrument.id };
  }

  const responses = instrument.items.map((item) => ({ itemId: item.id, value: Number(answers[item.id]) }));

  // Computed from the ITEM definition, not from a hardcoded 9. If the instrument
  // ever changes, the flag follows it instead of silently going stale.
  const suicidalityFlagged = instrument.items.some(
    (item) => item.suicidalityItem && Number(answers[item.id]) > 0
  );

  const severity = instrument.severity(total);

  const helplines = suicidalityFlagged ? [
    {
      name: 'National Tele-MANAS',
      phone: '14416',
      tollFree: '1800-891-4416',
      available: '24x7 Toll-Free',
      description: 'National Tele Mental Health Programme of India, Government of India',
    },
    {
      name: 'KIRAN Mental Health Helpline',
      phone: '1800-599-0019',
      tollFree: '1800-599-0019',
      available: '24x7 Toll-Free',
      description: 'Ministry of Social Justice and Empowerment, Government of India',
    },
    {
      name: 'Vandrevala Foundation',
      phone: '+91 9999 666 555',
      available: '24x7 Free',
      description: 'Free confidential 24x7 crisis intervention and suicide prevention helpline',
    },
  ] : [];

  return {
    valid: true,
    instrument: instrument.id,
    total,
    maxScore: instrument.maxScore,
    // Rounded, not raw: 12/27 = 44.4444... in a report looks like false precision.
    percentage: Math.round((total / instrument.maxScore) * 100),
    severity,
    // Reported independently of severity, always. A patient can score "Mild"
    // overall and still have answered item 9.
    suicidalityFlagged,
    referralSuggested: total >= instrument.referralThreshold || suicidalityFlagged,
    crisis: suicidalityFlagged,
    helplines,
    responses,
  };
};

/**
 * Trend across administrations - MIND-M-01's "trend tracking over sessions".
 *
 * Returns direction, the delta, and whether the change is CLINICALLY meaningful
 * rather than just numerically different. A 1-point move is noise; reporting it
 * as "improving" is how a clinician stops trusting the trend line.
 */
export const trend = (instrumentId, administrations = []) => {
  const instrument = INSTRUMENTS[instrumentId];
  if (!instrument) return { instrument: instrumentId, valid: false, reason: 'Unknown instrument' };

  const points = administrations
    .filter((a) => a?.valid !== false && Number.isFinite(Number(a?.total)))
    .map((a) => ({ at: a.completedAt || a.createdAt || null, total: Number(a.total) }))
    .sort((a, b) => (a.at ? new Date(a.at) : 0) - (b.at ? new Date(b.at) : 0));

  if (points.length === 0) return { instrument: instrument.id, valid: true, points: [], direction: 'no-data', change: null, clinicallyMeaningful: false };

  const first = points[0];
  const latest = points[points.length - 1];
  const change = latest.total - first.total;

  // Midpoint between the two administrations. One administration is not a trend.
  const elapsedDays = first.at && latest.at ? (new Date(latest.at) - new Date(first.at)) / 86400000 : null;

  let direction = 'no-data';
  if (points.length > 1) {
    if (change <= -instrument.reliableChange) direction = 'improving';
    else if (change >= instrument.reliableChange) direction = 'worsening';
    else direction = 'stable';
  }

  return {
    instrument: instrument.id,
    valid: true,
    points,
    administrations: points.length,
    first: first.total,
    latest: latest.total,
    change,
    // Signed so a reader cannot mistake "down 6" for a worsening.
    direction,
    clinicallyMeaningful: points.length > 1 && Math.abs(change) >= instrument.reliableChange,
    elapsedDays,
    reliableChangeThreshold: instrument.reliableChange,
  };
};

/**
 * Native Rust-backed CSV service (Phase 7 migration).
 *
 * Provides fast CSV serialization and parsing via the napi-core native module.
 * Falls back to JavaScript implementations when the native module is unavailable.
 *
 * Migration targets (per baseline-2026-09-08.json):
 *   - toCSV:    0.5ms (100 rows) → 4.5ms (1k rows) → 47.6ms (10k rows)
 *   - json2csv: 6.7ms (1k rows) → 66.2ms (10k rows)
 *   - ExcelJS xlsx parse: 7.4ms (50) → 20.8ms (500) → 206.9ms (5k rows)
 */
import { createRequire } from 'module';

const require = createRequire(import.meta.url);

let _napi = null;
let _loadError = null;

const NATIVE_NOT_AVAILABLE = 'NATIVE_NOT_AVAILABLE';

function getNapi() {
  if (_napi !== null) return _napi;
  if (_loadError !== null) throw Object.assign(new Error(_loadError.message), { code: NATIVE_NOT_AVAILABLE });

  try {
    _napi = require('../../rust-helper/index.js');
  } catch (e) {
    // MUST throw, not return null — see napiImageService.js for the full
    // reasoning. NATIVE_CSV_AVAILABLE is computed as
    // `try { getNapi(); return true } catch { return false }`, so a null return
    // on first failure would report the native module as present when it is not.
    _loadError = e;
    throw Object.assign(new Error(e.message), { code: NATIVE_NOT_AVAILABLE });
  }
  if (_napi === null) throw Object.assign(new Error('native module resolved to null'), { code: NATIVE_NOT_AVAILABLE });
  return _napi;
}

/**
 * Serialize an array of objects to a CSV string using the Rust native module.
 *
 * Mirrors `toCSV` in server/routes/export.js — always quotes fields (CSV QuoteStyle::All).
 *
 * @param {Array<Object>} rows     - Array of row objects
 * @param {Array<string>} fields   - Column/field names (order matters)
 * @returns {string} CSV string with header row
 */
export function toCsvNative(rows, fields) {
  const napi = getNapi();
  return napi.toCsv(JSON.stringify(rows), JSON.stringify(fields));
}

/**
 * Parse a CSV string into an array of objects using the Rust native module.
 *
 * @param {string} input - Raw CSV text (UTF-8)
 * @returns {Array<Object>} Array of row objects with keys from the header row
 */
export function parseCsvNative(input) {
  const napi = getNapi();
  const json = napi.parseCsv(input);
  return JSON.parse(json);
}

/**
 * Whether the native Rust CSV functions are available.
 * @type {boolean}
 */
export const NATIVE_CSV_AVAILABLE = (() => {
  try {
    getNapi();
    return true;
  } catch {
    return false;
  }
})();

// ── Fallback implementations (pure JavaScript, mirrors original logic) ─────

/**
 * Hand-rolled CSV writer — matches the `toCSV` function in server/routes/export.js.
 * Always wraps fields in double quotes; doubles embedded quotes.
 *
 * @param {Array<Object>} data - Array of row objects
 * @param {Array<string>} fields - Column/field names (order matters)
 * @returns {string} CSV string
 */
export function toCsvFallback(data, fields) {
  const header = fields.map(f => `"${f}"`).join(',');
  const rows = data.map(row => fields.map(f => {
    const val = row[f];
    if (val === null || val === undefined) return '""';
    return `"${String(val).replace(/"/g, '""')}"`;
  }).join(','));
  return [header, ...rows].join('\n');
}

/**
 * Pure-JS CSV parser using a minimal RFC-4180 compliant reader.
 *
 * @param {string} input - Raw CSV text
 * @returns {Array<Object>} Parsed rows
 */
export function parseCsvFallback(input) {
  const rows = [];
  const cur = '';
  let field = '';
  let inQuotes = false;
  let row = [];
  let headers = null;

  const flushField = () => {
    row.push(field);
    field = '';
  };

  const flushRow = () => {
    if (headers === null) {
      headers = row.slice();
    } else {
      const obj = {};
      headers.forEach((h, i) => { obj[h] = row[i] ?? ''; });
      rows.push(obj);
    }
    row = [];
  };

  for (let i = 0; i < input.length; i++) {
    const ch = input[i];
    const next = input[i + 1];

    if (inQuotes) {
      if (ch === '"') {
        if (next === '"') { field += '"'; i++; }
        else { inQuotes = false; }
      } else {
        field += ch;
      }
    } else {
      if (ch === '"') {
        inQuotes = true;
      } else if (ch === ',') {
        flushField();
      } else if (ch === '\r') {
        // handled with \n below
      } else if (ch === '\n') {
        flushField();
        flushRow();
      } else {
        field += ch;
      }
    }
  }

  // Handle last field/row if no trailing newline
  if (field || row.length > 0) {
    flushField();
    flushRow();
  }

  return rows;
}

/**
 * Native Rust-backed image service (Phase 7 migration).
 *
 * Provides magic-byte validation, image resize/compression, and metadata
 * extraction via the napi-core native module. Falls back to no-op or
 * throws if the native module is unavailable — callers should handle
 * the NATIVE_NOT_AVAILABLE error and fall back to JavaScript/Sharp.
 */
import { createRequire } from 'module';

const require = createRequire(import.meta.url);

let _napi = null;
let _loadError = null;

const NATIVE_NOT_AVAILABLE = 'NATIVE_NOT_AVAILABLE';

function getNapi() {
  if (_napi !== null) return _napi;
  if (_loadError !== null) throw Object.assign(new Error(_loadError.message), { code: NATIVE_NOT_AVAILABLE });

  try {
    _napi = require('../../rust-helper/index.js');
  } catch (e) {
    // MUST throw, not return null: NATIVE_AVAILABLE below is computed as
    // `try { getNapi(); return true } catch { return false }`. Returning null
    // here would make that report `true` when the native module is missing,
    // sending callers into the native branch where they hit a *second*,
    // uncaught NATIVE_NOT_AVAILABLE instead of the JavaScript fallback.
    _loadError = e;
    throw Object.assign(new Error(e.message), { code: NATIVE_NOT_AVAILABLE });
  }
  if (_napi === null) throw Object.assign(new Error('native module resolved to null'), { code: NATIVE_NOT_AVAILABLE });
  return _napi;
}

/**
 * Validate file magic bytes against claimed MIME type.
 * Returns { valid: bool, error?: string }.
 */
export function validateMagicBytes(buffer, mimetype) {
  try {
    const napi = getNapi();
    const valid = napi.validateMagicBytes(buffer, mimetype);
    return { valid, error: valid ? undefined : 'File content does not match its claimed type (magic bytes)' };
  } catch (e) {
    // Fallback: basic magic byte check (mirrors upload.js MAGIC_BYTES)
    return fallbackValidateMagicBytes(buffer, mimetype);
  }
}

export const MIN_IMAGE_DIMENSION = 1;
export const MAX_IMAGE_DIMENSION = 4096;

/**
 * Resize an image buffer to exact dimensions and re-encode as JPEG.
 * `quality` is 1-100. Clamps dimensions between 1 and 4096 for DoS protection.
 */
export function resizeImage(inputBuffer, width, height, quality = 75) {
  const w = Math.max(MIN_IMAGE_DIMENSION, Math.min(Math.round(width || 1), MAX_IMAGE_DIMENSION));
  const h = Math.max(MIN_IMAGE_DIMENSION, Math.min(Math.round(height || 1), MAX_IMAGE_DIMENSION));
  const q = Math.max(1, Math.min(Math.round(quality || 75), 100));
  const napi = getNapi();
  return Buffer.from(napi.resizeImage(inputBuffer, w, h, q));
}

/**
 * Get image format and dimensions (returns parsed object).
 */
export function getImageInfo(inputBuffer) {
  const napi = getNapi();
  const raw = napi.getImageInfo(inputBuffer);
  return JSON.parse(raw);
}

/**
 * Resize to fit inside maxW × maxH while maintaining aspect ratio.
 * Does not enlarge if the source is smaller than the target.
 * Clamps bounds to MAX_IMAGE_DIMENSION (4096).
 */
export function resizeToFit(inputBuffer, maxWidth, maxHeight, quality = 80) {
  const napi = getNapi();
  const info = JSON.parse(napi.getImageInfo(inputBuffer));
  const { width, height } = info;

  const maxW = Math.min(maxWidth || 4096, MAX_IMAGE_DIMENSION);
  const maxH = Math.min(maxHeight || 4096, MAX_IMAGE_DIMENSION);
  const q = Math.max(1, Math.min(Math.round(quality || 80), 100));

  // Don't enlarge
  if (width <= maxW && height <= maxH) {
    // Still re-encode to ensure consistent quality
    return Buffer.from(napi.resizeImage(inputBuffer, width, height, q));
  }

  const ratio = Math.min(maxW / width, maxH / height, 1);
  const targetW = Math.max(1, Math.round(width * ratio));
  const targetH = Math.max(1, Math.round(height * ratio));

  return Buffer.from(napi.resizeImage(inputBuffer, targetW, targetH, q));
}

export const NATIVE_AVAILABLE = (() => {
  try {
    getNapi();
    return true;
  } catch {
    return false;
  }
})();

// ── Fallback implementation (when Rust module unavailable) ─────────────────
const MAGIC_BYTES = {
  'image/jpeg': [Buffer.from([0xff, 0xd8, 0xff])],
  'image/png': [Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a])],
  'image/gif': [Buffer.from([0x47, 0x49, 0x46, 0x38])],
  'image/webp': [Buffer.from([0x52, 0x49, 0x46, 0x46])],
};

function fallbackValidateMagicBytes(buffer, mimetype) {
  if (!buffer || buffer.length < 4) return { valid: false, error: 'Empty or too-small file' };
  const sigs = MAGIC_BYTES[mimetype];
  if (!sigs) return { valid: true, error: undefined };
  for (const sig of sigs) {
    if (buffer.slice(0, sig.length).equals(sig)) {
      if (mimetype === 'image/webp' && buffer.length >= 12 &&
          buffer.slice(8, 12).toString('ascii') === 'WEBP') {
        return { valid: true, error: undefined };
      }
      if (mimetype !== 'image/webp') return { valid: true, error: undefined };
    }
  }
  return { valid: false, error: 'File content does not match its claimed type (magic bytes)' };
}

/**
 * Native Rust-backed OTP/2FA hashing service (Phase 7 migration).
 *
 * Provides fast OTP hashing and constant-time verification via the napi-core
 * native module. Falls back to bcryptjs when the native module is unavailable
 * or when a legacy bcrypt hash is encountered.
 *
 * Migration rationale:
 *   - bcrypt (cost 10) takes ~80-100ms for OTP hashing/verification
 *   - Rust SHA256 with salt + constant-time compare takes ~0.01ms
 *   - OTPs are short-lived (10 min) and single-use, so SHA-256 provides
 *     adequate security while being ~1000x faster than bcrypt
 *
 * Hash format: `salt_hex:hash_hex` (SHA256(salt ++ otp))
 * Legacy format: `$2b$...` (bcrypt) — verified via JS fallback
 */
import { createRequire } from 'module';
import bcrypt from 'bcryptjs';
import { randomDigits } from '../utils/secureRandom.js';
import logger from '../config/logger.js';

const require = createRequire(import.meta.url);

let _napi = null;
let _loadError = null;

function getNapi() {
  if (_napi !== null) return _napi;
  if (_loadError !== null) return null;
  try {
    _napi = require('../../rust-helper/index.js');
  } catch (e) {
    _loadError = e;
  }
  return _napi;
}

/**
 * RUST-B-01: startup visibility for the native-module decision.
 *
 * The fallback to bcryptjs is CORRECT and must not break startup — but it was
 * completely silent, which is why this defect survived: a Linux deploy that
 * never loaded the native module looked identical to a healthy one from the logs,
 * and the only symptom was OTP latency under load (bcrypt ~80-100ms vs Rust
 * SHA-256 ~0.01ms, per the module's own notes). A performance regression that
 * also weakens the security posture (bcrypt for a 6-digit OTP is brute-forceable
 * far more cheaply than a salted SHA-256 with a server-side pepper) should never
 * be invisible.
 *
 * Rules:
 *   - PRODUCTION and a missing module is an ERROR, not a warning. A deploy that
 *     was supposed to ship the native path must fail loudly.
 *   - Everywhere else it is a warning naming the platform and the reason.
 */
export function reportNativeModuleStatus({ available, error, env = process.env } = {}) {
  const platform = `${process.platform}/${process.arch}`;
  const isProd = env.NODE_ENV === 'production';
  const context = {
    available,
    platform,
    nativeArtifact: available ? 'loaded' : 'missing',
    fallbackAlgo: 'bcryptjs',
    fallbackReason: error ? String(error.message || error).slice(0, 200) : 'not_built_for_platform',
    // The fallback is materially slower; an operator reading this needs to know
    // the number, not just that "something changed".
    otpHashCost: available ? 'rust-sha256 (~0.01ms)' : 'bcrypt cost=10 (~80-100ms)',
  };

  if (available) {
    logger.info('Native Rust module loaded', context);
    return context;
  }

  if (isProd) {
    logger.error(
      'RUST-B-01: native Rust module did NOT load in production - falling back to '
      + 'bcryptjs. OTP hashing is ~1000x slower and weaker. This deployment is '
      + 'missing its linux-gnu/linux-musl artifact; build it in CI and ship it in '
      + 'the image.',
      context
    );
  } else {
    logger.warn(
      'RUST-B-01: native Rust module not loaded - using bcryptjs fallback (development)',
      context
    );
  }

  return context;
}

export const NATIVE_OTP_AVAILABLE = (() => {
  const ok = !!getNapi();
  reportNativeModuleStatus({ available: ok, error: _loadError });
  return ok;
})();

/**
 * Explicit shared contract for which backend produced / verifies an OTP hash.
 *
 * Single source of truth — every consumer (OTP model, twoFactorService)
 * must reference these values instead of implicitly assuming a backend
 * from `NATIVE_OTP_AVAILABLE` or from the hash string shape.
 *
 * - `RUST_SHA256` ('rust-sha256'): salted SHA-256 produced/verified by the
 *   Rust native module (`salt_hex:hash_hex`, SHA256(salt ++ otp)).
 * - `JS_SHA256_FALLBACK` ('js-sha256-fallback'): same `salt_hex:hash_hex`
 *   format but verified via the Node.js `crypto` fallback because the
 *   native module is unavailable in this process.
 * - `BCRYPT` ('bcrypt'): legacy/fallback `$2a$`/`$2b$`/`$2y$` hash produced
 *   and verified via `bcryptjs`.
 * - `UNKNOWN` ('unknown'): unrecognized format (verification returns false).
 */
export const OTP_HASH_ALGO = {
  RUST_SHA256: 'rust-sha256',
  JS_SHA256_FALLBACK: 'js-sha256-fallback',
  BCRYPT: 'bcrypt',
  UNKNOWN: 'unknown',
};

/**
 * Which backend `hashOtp()` in this process will use for NEW hashes.
 * Explicit alias over the implicit `NATIVE_OTP_AVAILABLE` flag.
 */
export const ACTIVE_OTP_HASH_ALGO = NATIVE_OTP_AVAILABLE
  ? OTP_HASH_ALGO.RUST_SHA256
  : OTP_HASH_ALGO.BCRYPT;

/**
 * Live check of the production backend (re-queries the native binding
 * instead of relying on the import-time `ACTIVE_OTP_HASH_ALGO` snapshot).
 *
 * @returns {'rust-sha256' | 'bcrypt'}
 */
export function getActiveOtpHashAlgo() {
  return getNapi() ? OTP_HASH_ALGO.RUST_SHA256 : OTP_HASH_ALGO.BCRYPT;
}

/**
 * Resolve which backend verifies a given stored hash in this process.
 * Maps the structural `OtpHashKind` to the explicit `OTP_HASH_ALGO` contract,
 * distinguishing native vs JS-fallback verification for SHA-256 hashes.
 *
 * @param {string} storedHash - Stored hash string
 * @returns {'rust-sha256' | 'js-sha256-fallback' | 'bcrypt' | 'unknown'}
 */
export function resolveOtpHashAlgo(storedHash) {
  const kind = classifyOtpHash(storedHash);
  if (kind === OtpHashKind.Bcrypt) return OTP_HASH_ALGO.BCRYPT;
  if (kind === OtpHashKind.Sha256) {
    return getNapi() ? OTP_HASH_ALGO.RUST_SHA256 : OTP_HASH_ALGO.JS_SHA256_FALLBACK;
  }
  return OTP_HASH_ALGO.UNKNOWN;
}

/**
 * Hash an OTP for storage.
 * Uses Rust SHA-256 with random salt when available, falls back to bcrypt.
 *
 * @param {string} otp - Plain-text OTP (e.g. "123456")
 * @returns {Promise<string>} Hash string (format: salt_hex:hash_hex or bcrypt hash)
 */
export async function hashOtp(otp) {
  const napi = getNapi();
  if (napi) {
    return napi.hashOtp(otp);
  }
  // Fallback: bcrypt (slower but still secure)
  return await bcrypt.hash(otp, 10);
}

/**
 * Hash an OTP and report which backend produced the hash.
 * Same behavior as `hashOtp()` plus the explicit `OTP_HASH_ALGO` value,
 * so callers can store which backend produced each hash.
 *
 * @param {string} otp - Plain-text OTP (e.g. "123456")
 * @returns {Promise<{ hash: string, algo: string }>} Hash + `OTP_HASH_ALGO` value
 */
export async function hashOtpWithMeta(otp) {
  const hash = await hashOtp(otp);
  return { hash, algo: resolveOtpHashAlgo(hash) };
}

export const OtpHashKind = {
  Sha256: 'Sha256',
  Bcrypt: 'Bcrypt',
  Unknown: 'Unknown',
};

/**
 * Classify the format of a stored OTP hash.
 * Delegates to Rust native module when available.
 *
 * @param {string} storedHash - Stored hash string
 * @returns {'Sha256' | 'Bcrypt' | 'Unknown'}
 */
export function classifyOtpHash(storedHash) {
  const napi = getNapi();
  if (napi && typeof napi.classifyOtpHash === 'function') {
    return napi.classifyOtpHash(storedHash);
  }
  if (typeof storedHash !== 'string') return OtpHashKind.Unknown;
  if (storedHash.startsWith('$2a$') || storedHash.startsWith('$2b$') || storedHash.startsWith('$2y$')) {
    return OtpHashKind.Bcrypt;
  }
  const parts = storedHash.split(':');
  if (parts.length === 2 && parts[0].length === 32 && parts[1].length === 64) {
    return OtpHashKind.Sha256;
  }
  return OtpHashKind.Unknown;
}

/**
 * Verify an OTP against a stored hash.
 * Branches on explicit OtpHashKind:
 * - Bcrypt: falls back to JS bcrypt.compare
 * - Sha256: verifies via Rust constant-time comparison (or crypto fallback)
 * - Unknown: returns false
 *
 * @param {string} otp - Plain-text OTP to verify
 * @param {string} storedHash - Stored hash (new format or legacy bcrypt)
 * @returns {Promise<boolean>} True if OTP matches
 */
export async function verifyOtpHash(otp, storedHash) {
  const kind = classifyOtpHash(storedHash);

  if (kind === OtpHashKind.Bcrypt) {
    return await bcrypt.compare(otp, storedHash);
  }

  if (kind === OtpHashKind.Sha256) {
    const napi = getNapi();
    if (napi) {
      return napi.verifyOtpHash(otp, storedHash);
    }
    // JS fallback for Sha256 format when native module unavailable
    try {
      const crypto = await import('crypto');
      const [saltHex, expectedHashHex] = storedHash.split(':');
      const computed = crypto.default.createHash('sha256').update(Buffer.from(saltHex, 'hex')).update(otp).digest('hex');
      return crypto.default.timingSafeEqual(Buffer.from(computed, 'utf8'), Buffer.from(expectedHashHex, 'utf8'));
    } catch {
      return false;
    }
  }

  return false;
}

/**
 * Generate a 6-digit numeric OTP.
 * Uses Node.js crypto for cryptographic randomness (AUTH-009).
 *
 * @returns {string} 6-digit OTP string
 */
export function generateOtp() {
  return randomDigits(6);
}


/**
 * Constant-time string comparison.
 * Uses Rust implementation when available, Node.js fallback otherwise.
 *
 * @param {string} a - First string to compare
 * @param {string} b - Second string to compare
 * @returns {boolean} True if strings are equal (constant time when native available)
 */
export function constantTimeCompare(a, b) {
  const napi = getNapi();
  if (napi) {
    return napi.constantTimeCompare(a, b);
  }
  // Fallback: simple comparison (not truly constant-time, but sufficient for non-security-critical use)
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

