}

// ─── DLM-06: erasure across the search tier ────────────────────────────────
//
// The Mongo row is not the only copy of a person. Search keeps providers and
// pseudonymised EHR text, and an erasure that left them behind would be
// invisible in the database but still served by the search endpoint.
//
// EHR documents are keyed by PSEUDONYM (DP-B-06), not the raw user id, so the
// purge has to recompute that pseudonym with the same salt to find them. This
// is also why a rotated OPENSEARCH_PSEUDONYM_SALT orphans the old rows rather
// than exposing them - but it means the purge must use the current salt.
const PII_INDICES = [PROVIDERS_INDEX, EHR_INDEX];

/**
 * @returns {Promise<{status:'ok'|'skipped'|'failed', detail:string, purged:Record<string,number>}>}
 *   `skipped` when OpenSearch is not configured (there is no index to purge -
 *   reported as a skip rather than an ok so the certificate cannot claim a
 *   purge that never happened).
 */
export async function purgeUserFromSearch(userId) {
  if (!isOpenSearchConfigured()) {
    return { status: 'skipped', detail: 'opensearch_not_configured', purged: {} };
  }

  const raw = String(userId);
  const pseudonym = pseudonymizePatientId(raw);
  const purged = {};

  try {
    for (const index of PII_INDICES) {
      // Two different identifiers: provider docs carry the raw id, EHR docs
      // carry only the pseudonym. Matching on the wrong one deletes nothing and
      // reports success, so both are queried.
      const query =
        index === EHR_INDEX
          ? { bool: { should: [{ term: { patientPseudonym: pseudonym } }, { term: { patientId: pseudonym } }], minimum_should_match: 1 } }
          : { bool: { should: [{ term: { providerId: raw } }, { term: { userId: raw } }], minimum_should_match: 1 } };

      const data = await osReq('POST', `/${index}/_delete_by_query?refresh=true`, {
        query,
        // A user with a large footprint can exceed the default 10k slice; the
        // purge must see every match, not the first page of them.
        conflicts: 'proceed',
        slices: 'auto',
      });
      purged[index] = Number(data?.deleted ?? 0);
    }
    return { status: 'ok', detail: `purged ${Object.values(purged).reduce((a, b) => a + b, 0)} doc(s)`, purged };
  } catch (err) {
    // Thrown, not swallowed: the caller records this as a FAILED step, which
    // blocks the certificate. A log line here is exactly the failure mode
    // DLM-06 is about.
    const e = new Error(`opensearch purge failed: ${err.message}`);
    e.cause = err;
    throw e;
  }
}

// ─── Tech 07: drug / ICD / EHR indexing + search ─────────────────────────────
export function saltKeyFor(genericName = '') {
  return String(genericName).toLowerCase().replace(/[^a-z0-9]+/g, '+').replace(/^\++|\++$/g, '');
}

export async function indexDrugDoc(med) {
  if (!isOpenSearchConfigured() || !med?._id) return null;
  try {
    await osReq('POST', `/${DRUGS_INDEX}/_doc/${encodeURIComponent(String(med._id))}`, {
      medicineId: String(med._id),
      brand: med.name,
      salt: med.genericName,
      saltKey: saltKeyFor(med.genericName),
      strength: med.strength || '',
      therapeuticClass: med.category,
      form: med.form,
      sellingPrice: med.sellingPrice,
      inStock: (med.currentStock ?? 0) > 0,
      facilityId: String(med.facilityId || med.hospitalId || ''),
    });
    // DP-B-05: indexing succeeded, so the search index is fresh.
    recordPipelineEvent('opensearch_indexer', 'success');
    return true;
  } catch (err) {
    // DP-B-05: an index write that only logs leaves search results
    // silently stale — the search endpoint keeps serving old data
    // with no signal that indexing stopped.
    recordPipelineEvent('opensearch_indexer', 'error', { error: err });
    logger.warn(`indexDrugDoc skipped: ${err.message}`);
    return null;
  }
}

/**
 * DP-B-06: pseudonymisation + masking for the analytics tier.
 *
 * `ehr_docs` used to store the raw patient Mongo id plus the verbatim clinical
 * text, which made the search index a second, un-consented copy of the medical
 * record — readable by anything with cluster access (DL-13/15). Now:
 *   - the subject id is replaced by a keyed, deterministic hash (correlation is
 *     preserved, identity is not);
 *   - direct identifiers inside the free text (Aadhaar, phone, email, MRN-like
 *     numbers) are masked before indexing;
 *   - the key comes from the environment and must never be committed, so the same
 *     input cannot be reversed by an attacker who reads the index.
 */
// DP-B-01/DL-B-01: read the salt per call, not once at import. A module-load
// snapshot makes the "salt absent -> throw" contract untestable (the test
// cannot re-import with different env) and hides rotation: a rotated salt
// would keep producing old keys until restart with no signal.
export function getPseudonymSalt() {
  return process.env.OPENSEARCH_PSEUDONYM_SALT || '';
}

export function pseudonymizePatientId(patientId) {
  const raw = String(patientId || '');
  if (!raw) return '';
  const salt = getPseudonymSalt();
  if (!salt || salt.length < 32) {
    throw new Error('OPENSEARCH_PSEUDONYM_SALT must be configured with at least 32 characters');
  }
  return createHmac('sha256', salt).update(raw).digest('hex').slice(0, 32);
}

const MASK_PATTERNS = [
  /\b\d{4}[\s-]?\d{4}[\s-]?\d{4}\b/g,                     // Aadhaar-like 12 digits
  /\b[6-9]\d{9}\b/g,                                       // Indian mobile
  /\b[\w.+-]+@[\w-]+\.[\w.]+\b/g,                          // email
  /\b\d{2,4}\s*\/\s*\d{2,4}\s*\/\s*\d{2,4}\b/g,            // DOB
];

export function redactClinicalText(input) {
  let text = String(input ?? '').slice(0, 20000);
  for (const pattern of MASK_PATTERNS) text = text.replace(pattern, '[redacted]');
  return text;
}

export async function indexEhrDoc({ recordId, patientId, docType, text, allergies = [], hospitalId = '', facilityId = '' }) {
  if (!isOpenSearchConfigured() || !recordId) return null;
  try {
    // DP-B-06: pseudonymize the subject id before it reaches the analytics store.
    // The raw Mongo id is a direct identifier; a keyed hash lets the same patient
    // be correlated across documents without the index being a patient directory.
    const pseudonym = pseudonymizePatientId(patientId);
    await osReq('POST', `/${EHR_INDEX}/_doc/${encodeURIComponent(String(recordId))}`, {
      recordId: String(recordId),
      patientId: pseudonym,
      patientPseudonym: pseudonym,
      hospitalId: String(hospitalId || ''),
      facilityId: String(facilityId || ''),
      docType: docType || 'note',
      text: redactClinicalText(text),
      allergies: (Array.isArray(allergies) ? allergies : []).map((a) => String(a).slice(0, 120)),
      createdAt: new Date().toISOString(),
    });
    // DP-B-05: indexing succeeded, so the search index is fresh.
    recordPipelineEvent('opensearch_indexer', 'success');
    return true;
  } catch (err) {
    // DP-B-05: an index write that only logs leaves search results
    // silently stale — the search endpoint keeps serving old data
    // with no signal that indexing stopped.
    recordPipelineEvent('opensearch_indexer', 'error', { error: err });
    logger.warn(`indexEhrDoc skipped: ${err.message}`);
    return null;
  }
}

async function mongoDrugSearch({ q, salt, size }) {
  const rx = new RegExp(String(q || salt || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
  try {
    const mongoose = (await import('mongoose')).default;
    if (mongoose.connection.readyState !== 1) return [];
    const { default: Medicine } = await import('../models/Medicine.js');
    const or = [{ name: rx }];
    if (salt) or.push({ genericName: rx });
    else or.push({ genericName: rx }, { category: rx });
    const docs = await Medicine.find({ $or: or, currentStock: { $gt: 0 } })
      .select('name genericName category form sellingPrice currentStock').limit(size).lean();
    return docs;
  } catch {
    return [];
  }
}

// Brand → in-stock bio-equivalents ranked by savings (<15ms target on cluster).
export async function searchDrugs({ q, salt, size = 20 } = {}) {
  if (!q && !salt) return { source: 'none', results: [], substitutes: [] };
  if (!isOpenSearchConfigured()) {
    const results = await mongoDrugSearch({ q, salt, size });
    return { source: 'mongo_fallback', results, substitutes: substitutesFrom(results) };
  }
  try {
    const data = await osReq('POST', `/${DRUGS_INDEX}/_search`, {
      size,
      query: {
        bool: {
          must: [{ multi_match: {
            query: q || salt,
            fields: ['brand^3', 'salt^3', 'therapeuticClass'],
            fuzziness: 'AUTO',
          } }],
          filter: [{ term: { inStock: true } }],
        },
      },
    });
    const results = (data?.hits?.hits || []).map((h) => ({ score: h._score, ...h._source }));
    // Substitutes: same salt as top hit, cheapest first, with savings.
    let substitutes = [];
    const topSalt = results[0]?.saltKey;
    if (topSalt) {
      const sub = await osReq('POST', `/${DRUGS_INDEX}/_search`, {
        size: 5,
        query: { bool: { must: [{ term: { saltKey: topSalt } }], filter: [{ term: { inStock: true } }] } },
        sort: [{ sellingPrice: 'asc' }],
      });
      const rows = (sub?.hits?.hits || []).map((h) => h._source);
      const brandPrice = Math.max(...results.slice(0, 3).map((r) => r.sellingPrice || 0), 0);
      substitutes = rows.map((r) => ({ ...r, savingsVsTop: Math.round((brandPrice - (r.sellingPrice || 0)) * 100) / 100 }));
    }
    return { source: 'opensearch', results, substitutes };
  } catch (err) {
    logger.warn(`Drug search failed, mongo fallback: ${err.message}`);
    const results = await mongoDrugSearch({ q, salt, size });
    return { source: 'mongo_fallback', results, substitutes: substitutesFrom(results) };
  }
}

function substitutesFrom(rows) {
  if (!rows?.length) return [];
  const salt = String(rows[0].genericName || '').toLowerCase();
  const same = rows.filter((r) => String(r.genericName || '').toLowerCase() === salt);
  const sorted = [...same].sort((a, b) => (a.sellingPrice || 0) - (b.sellingPrice || 0));
  const top = Math.max(...rows.slice(0, 3).map((r) => r.sellingPrice || 0), 0);
  return sorted.slice(0, 5).map((r) => ({ ...r, savingsVsTop: Math.round((top - (r.sellingPrice || 0)) * 100) / 100 }));
}

export async function searchIcd({ q, size = 20 } = {}) {
  if (!q) return { source: 'none', results: [] };
  if (!isOpenSearchConfigured()) return { source: 'mongo_fallback', results: [] };
  try {
    const data = await osReq('POST', `/${ICD_INDEX}/_search`, {
      size,
      query: { bool: { should: [
        { prefix: { code: String(q).toUpperCase() } },
        { multi_match: { query: q, fields: ['title^2'], fuzziness: 'AUTO' } },
      ] } },
    });
    return { source: 'opensearch', results: (data?.hits?.hits || []).map((h) => ({ score: h._score, ...h._source })) };
  } catch (err) {
    logger.warn(`ICD search failed: ${err.message}`);
    return { source: 'mongo_fallback', results: [] };
  }
}

// EHR search: consent-gated (ABDM ConsentRecord GRANTED + unexpired) with
// snippet highlight + allergy warnings for unconscious-patient ER.
export async function searchEhr({ patientId, q, consentId, size = 10 } = {}) {
  if (!patientId || !q) return { source: 'none', results: [] };
  const { default: ConsentRecord } = await import('../models/ConsentRecord.js');
  const grant = consentId
    ? await ConsentRecord.findOne({ consentId, patientId }).lean()
    : await ConsentRecord.findOne({
      patientId, status: 'GRANTED', expiresAt: { $gt: new Date() },
    }).sort({ grantedAt: -1 }).lean();
  if (!grant || grant.status !== 'GRANTED' || (grant.expiresAt && new Date(grant.expiresAt) < new Date())) {
    return { source: 'denied', results: [], message: 'Active EHR consent required (ABDM M2/M3)' };
  }
  const { default: User } = await import('../models/User.js');
  const patient = await User.findById(patientId).select('allergies').lean().catch(() => null);
  const allergyTerms = (patient?.allergies || []).map((a) => String(a.allergen || a).toLowerCase()).filter(Boolean);
  if (!isOpenSearchConfigured()) {
    const { default: Record } = await import('../models/Record.js');
    const rx = new RegExp(String(q).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    const docs = await Record.find({ patientId, $or: [{ diagnosis: rx }, { notes: rx }, { symptoms: rx }] }).limit(size).lean().catch(() => []);
    return { source: 'mongo_fallback', results: docs, allergyFlags: allergyFlagsFor(docs, allergyTerms) };
  }
  try {
    // DP-B-06: the index stores the pseudonym, so the filter must use the same
    // keyed value — filtering on the raw id would silently return nothing and
    // push every consent-gated EHR search onto the Mongo fallback.
    const pseudonym = pseudonymizePatientId(patientId);
    const data = await osReq('POST', `/${EHR_INDEX}/_search`, {
      size,
      _source: ['recordId', 'docType', 'allergies', 'createdAt'],
      query: { bool: { must: [{ match: { text: q } }], filter: [{ term: { patientId: pseudonym } }] } },
      highlight: { fields: { text: { fragment_size: 200, number_of_fragments: 2 } } },
    });
    const results = (data?.hits?.hits || []).map((h) => ({ score: h._score, ...h._source, highlight: h.highlight?.text || [] }));
    if (!results.length) {
      // DP-B-06: the index may still hold documents written before pseudonymisation
      // (or with a different salt). Falling back to Mongo keeps the consent-gated
      // feature working instead of returning an empty, misleading result.
      const { default: Record } = await import('../models/Record.js');
      const rx = new RegExp(String(q).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
      const docs = await Record.find({ patientId, $or: [{ diagnosis: rx }, { notes: rx }, { symptoms: rx }] }).limit(size).lean().catch(() => []);
      if (docs.length) return { source: 'mongo_fallback', results: docs, allergyFlags: allergyFlagsFor(docs, allergyTerms) };
    }
    return { source: 'opensearch', results, allergyFlags: allergyFlagsFor(results, allergyTerms) };
  } catch (err) {
    logger.warn(`EHR search failed: ${err.message}`);
    const { default: Record } = await import('../models/Record.js');
    const rx = new RegExp(String(q).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
    const docs = await Record.find({ patientId, $or: [{ diagnosis: rx }, { notes: rx }, { symptoms: rx }] }).limit(size).lean().catch(() => []);
    return { source: 'mongo_fallback', results: docs, allergyFlags: allergyFlagsFor(docs, allergyTerms) };
  }
}

function allergyFlagsFor(docs, allergyTerms) {
  if (!allergyTerms?.length) return [];
  const flags = [];
  for (const d of docs || []) {
    const hay = JSON.stringify([d.text, d.highlight, d.diagnosis, d.notes, d.symptoms]).toLowerCase();
    for (const term of allergyTerms) {
      if (term && hay.includes(term)) flags.push({ recordId: d.recordId || String(d._id), allergy: term });
    }
  }
  return flags;
}

async function mongoProviderSearch({ q, vertical, city, size }) {
  // Fallback discovery across provider directories (regex, capped).
  const rx = new RegExp(String(q || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i');
  const results = [];
  try {
    const want = (v) => !vertical || vertical === v || vertical === 'all';
    if (want('doctor')) {
      const { default: Doctor } = await import('../models/Doctor.js');
      const docs = await Doctor.find({ $or: [{ name: rx }, { specialization: rx }, { 'conditionsTreated.label': rx }, { 'procedures.label': rx }] })
        .select('name specialization emergencySupport isEmergencyDutyActive conditionsTreated procedures').limit(size).lean();
      docs.forEach((d) => results.push({ providerId: String(d._id), vertical: 'doctor', fullName: d.name, specialization: d.specialization, conditionsTreated: d.conditionsTreated, procedures: d.procedures }));
    }
    if (want('lawyer') && results.length < size) {
      const { default: LawyerProfile } = await import('../models/LawyerProfile.js');
      const docs = await LawyerProfile.find({ lawyerStatus: 'active' })
        .populate({ path: 'userId', select: 'name', match: { name: rx } }).limit(size).lean();
      docs.filter((d) => d.userId).forEach((d) => results.push({ providerId: String(d.userId._id || d.userId), vertical: 'lawyer', fullName: d.userId.name }));
    }
    if (want('assistant') && results.length < size) {
      const { default: AssistantProfile } = await import('../models/AssistantProfile.js');
      const docs = await AssistantProfile.find({ assistantStatus: 'active', ...(city ? { operatingCity: city } : {}) })
        .populate({ path: 'userId', select: 'name', match: { name: rx } }).limit(size).lean();
      docs.filter((d) => d.userId).forEach((d) => results.push({ providerId: String(d.userId._id || d.userId), vertical: 'assistant', fullName: d.userId.name }));
    }
    if (want('rider') && results.length < size) {
      const { default: RiderProfile } = await import('../models/RiderProfile.js');
      const docs = await RiderProfile.find({ riderStatus: 'active', isOnline: true })
        .populate({ path: 'userId', select: 'name', match: { name: rx } }).limit(size).lean();
      docs.filter((d) => d.userId).forEach((d) => results.push({ providerId: String(d.userId._id || d.userId), vertical: 'rider', fullName: d.userId.name }));
    }
  } catch (err) {
    logger.warn(`mongoProviderSearch error: ${err.message}`);
  }
  return results.slice(0, size);
}

export async function searchProviders({ q, vertical, city, lat, lon, radiusKm = 15, size = 20 } = {}) {
  if (!q) return { source: isOpenSearchConfigured() ? 'opensearch' : 'mongo_fallback', results: [] };
  if (!isOpenSearchConfigured()) {
    return { source: 'mongo_fallback', results: await mongoProviderSearch({ q, vertical, city, size }) };
  }
  try {
    const must = [{
      multi_match: { query: q, fields: ['fullName^2', 'specialization^3', 'conditionsTreated.label^2', 'procedures.label^2'], fuzziness: 'AUTO' },
    }];
    const filter = [];
    if (vertical && vertical !== 'all') filter.push({ term: { vertical } });
    if (city) filter.push({ term: { city } });
    if (lat != null && lon != null) {
      filter.push({ geo_distance: { distance: `${Number(radiusKm) || 15}km`, geoPoint: { lat: Number(lat), lon: Number(lon) } } });
    }
    const data = await osReq('POST', `/${PROVIDERS_INDEX}/_search`, {
      size, query: { bool: { must, filter } },
    });
    const results = (data?.hits?.hits || []).map((h) => ({ score: h._score, ...h._source }));
    return { source: 'opensearch', results };
  } catch (err) {
    logger.warn(`OpenSearch query failed, mongo fallback: ${err.message}`);
    return { source: 'mongo_fallback', results: await mongoProviderSearch({ q, vertical, city, size }) };
  }
}

import OTP from '../models/OTP.js';
import { randomDigits } from '../utils/secureRandom.js';
import { sendEmail } from './notificationService.js';
import { renderEmailTemplate, renderPlainText } from './emailTemplates.js';
import {
  setRedisOTP,
  getRedisOTP,
  delRedisOTP,
  setOTPCooldown,
  checkOTPCooldown,
  checkOTPLockout,
  incrementOTPFailures,
  resetOTPFailures,
} from '../config/redis.js';

// OTP validity: 10 minutes
const OTP_VALIDITY_MINUTES = 10;
const OTP_VALIDITY_MS = OTP_VALIDITY_MINUTES * 60 * 1000;

// Minimum gap between OTP requests: 1 minute
const MIN_OTP_REQUEST_GAP_MS = 60 * 1000;

// Generate 6-digit numeric OTP (CSPRNG — AUTH-009)
/**
 * AUTH-B-08: daily OTP quota per identifier (cost + spam control).
 * A Redis counter with a 24 h window, falling back to a Mongo count.
 */
export const OTP_DAILY_QUOTA = 10;

export const checkDailyOtpQuota = async (email, limit = OTP_DAILY_QUOTA) => {
  const key = `otp:quota:day:${email}`;
  try {
    const { redisClient, isRedisReady } = await import('../config/redis.js');
    if (isRedisReady() && redisClient.isOpen) {
      const used = Number(await redisClient.incr(key));
      if (used === 1) await redisClient.expire(key, 24 * 60 * 60);
      if (used > limit) {
        return {
          allowed: false,
          message: 'Daily OTP limit reached. Please try again tomorrow.',
          waitSeconds: 24 * 60 * 60,
        };
      }
      return { allowed: true, used };
    }
  } catch { /* fall through to the Mongo count */ }

  const dayStart = new Date();
  dayStart.setHours(0, 0, 0, 0);
  const count = await OTP.countDocuments({ email, createdAt: { $gte: dayStart } });
  if (count >= limit) {
    return {
      allowed: false,
      message: 'Daily OTP limit reached. Please try again tomorrow.',
      waitSeconds: 24 * 60 * 60,
    };
  }
  return { allowed: true, used: count + 1 };
};

export const generateOTP = () => randomDigits(6);

/**

/**
 * Check if user can request a new OTP (minimum 1 minute gap)
 * Uses Redis cooldown with fallback to DB
 * @param {string} email - User email
 * @returns {Promise<{allowed: boolean, waitSeconds?: number, lastRequestAt?: Date}>}
 */
export const checkRateLimit = async (email) => {
  // Check fast Redis cooldown first
  const redisCheck = await checkOTPCooldown(email);
  if (!redisCheck.allowed) {
    return {
      allowed: false,
      waitSeconds: redisCheck.waitSeconds,
    };
  }

  // Fallback to MongoDB check
  const lastOtp = await OTP.findOne({ email })
    .sort({ createdAt: -1 })
    .select('createdAt')
    .limit(1);

  if (!lastOtp) {
    return { allowed: true };
  }

  const timeSinceLastRequest = Date.now() - new Date(lastOtp.createdAt).getTime();
  const waitTime = MIN_OTP_REQUEST_GAP_MS - timeSinceLastRequest;

  if (timeSinceLastRequest < MIN_OTP_REQUEST_GAP_MS) {
    return {
      allowed: false,
      waitSeconds: Math.ceil(waitTime / 1000),
      lastRequestAt: lastOtp.createdAt
    };
  }

  return { allowed: true };
};

/**
 * Create and send OTP
 * @param {Object} params - { userId, email, type = 'email', phone? }
 * @returns {Promise<{success: boolean, message: string, otpId?: string}>}
 */
export const createAndSendOTP = async ({ userId, email, type = 'email', phone = '' }) => {
  try {
    const normalizedEmail = email.toLowerCase();

    // AUTH-B-08: daily quota per identifier. The 60 s cooldown alone still allows
    // ~1 400 mails/day to one address (SMS/email pumping cost + OTP spam).
    const dailyQuota = await checkDailyOtpQuota(normalizedEmail);
    if (!dailyQuota.allowed) {
      return {
        success: false,
        message: dailyQuota.message,
        rateLimited: true,
        waitSeconds: dailyQuota.waitSeconds,
        quotaExceeded: true,
      };
    }

    // Check rate limit
    const rateLimitCheck = await checkRateLimit(normalizedEmail);
    if (!rateLimitCheck.allowed) {
      return {
        success: false,
        message: `Please wait ${rateLimitCheck.waitSeconds} seconds before requesting a new OTP`,
        rateLimited: true,
        waitSeconds: rateLimitCheck.waitSeconds
      };
    }

    // Generate OTP
    const otpPlain = generateOTP();
    const otpHash = await OTP.hashOTP(otpPlain);
    const expiresAt = new Date(Date.now() + OTP_VALIDITY_MS);

    // Create OTP record
    const otpRecord = await OTP.create({
      user: userId,
      email: normalizedEmail,
      otpHash,
      type,
      phone,
      used: false,
      expiresAt,
      lastRequestAt: new Date()
    });

    // Save in Redis OTP cache and activate 60s cooldown
    await setRedisOTP(`${normalizedEmail}:${type}`, otpHash, OTP_VALIDITY_MINUTES * 60);
    await setOTPCooldown(normalizedEmail, 60);

    // Send OTP via email only (SMS removed)
    const isPasswordReset = type === 'password_reset';
    const subject = isPasswordReset
      ? 'Reset Your FindMedi Password'
      : 'Your OTP Verification - FindMedi Hospital';
    const intro = isPasswordReset
      ? 'Use this code to reset your FindMedi password.'
      : 'Use this code to verify your FindMedi account.';
    const template = {
      title: isPasswordReset ? 'Reset your password' : 'Verify your email',
      subtitle: intro,
      badge: isPasswordReset ? 'Password Reset' : 'Email Verification',
      paragraphs: [
        `This secure code will expire in ${OTP_VALIDITY_MINUTES} minutes.`,
        'For your safety, never share this code with anyone.',
      ],
      code: otpPlain,
      details: [
        { label: 'Purpose', value: isPasswordReset ? 'Password reset' : 'Email verification' },
        { label: 'Expires in', value: `${OTP_VALIDITY_MINUTES} minutes` },
      ],
      note: "If you didn't request this code, you can safely ignore this email.",
      tone: isPasswordReset ? 'warning' : 'default',
      preheader: `Your FindMedi verification code is ${otpPlain}.`,
    };

    const sendResult = await sendEmail({
      to: normalizedEmail,
      subject,
      text: renderPlainText(template),
      html: renderEmailTemplate(template)
    });

    if (!sendResult.success) {
      // Delete OTP record if sending failed
      await otpRecord.deleteOne();
      return {
        success: false,
        message: `Failed to send OTP email: ${sendResult.error || sendResult.message}`
      };
    }

    // Only the newest delivered OTP for this email/purpose should remain valid.
    await OTP.updateMany(
      {
        email: normalizedEmail,
        type,
        used: false,
        _id: { $ne: otpRecord._id },
      },
      { used: true }
    );

    return {
      success: true,
      message: 'OTP sent successfully',
      otpId: otpRecord._id,
      sentTo: normalizedEmail,
      messageId: sendResult.messageId,
      simulated: sendResult.simulated === true,
    };

  } catch (error) {
    console.error('OTP creation error:', error);
    return {
      success: false,
      message: 'Failed to create OTP',
      error: error.message
    };
  }
};

/**
 * Verify OTP
 * @param {Object} params - { email, otp } or { phone, otp }
 * @returns {Promise<{success: boolean, message: string, otpRecord?: Object}>}
 */
export const verifyOTP = async ({ email, otp, type = 'email' }) => {
  try {
    const normalizedEmail = email.toLowerCase();

    // Check if the IP/email is locked out from too many failed attempts
    const lockout = await checkOTPLockout(normalizedEmail, type);
    if (lockout.locked) {
      return {
        success: false,
        message: `Too many failed OTP attempts. Please try again in ${lockout.waitSeconds} seconds.`,
        locked: true,
        waitSeconds: lockout.waitSeconds,
      };
    }

    // Find valid, unused OTP for this email
    const otpRecord = await OTP.findOne({
      email: normalizedEmail,
      type,
      used: false,
      expiresAt: { $gt: new Date() }
    }).sort({ createdAt: -1 }); // Get the most recent

    if (!otpRecord) {
      // No valid OTP found — still increment failure count to prevent enumeration
      const failResult = await incrementOTPFailures(normalizedEmail, type);
      if (failResult.locked) {
        return {
          success: false,
          message: `Too many failed attempts. Please try again in ${failResult.waitSeconds} seconds.`,
          locked: true,
          waitSeconds: failResult.waitSeconds,
        };
      }
      return {
        success: false,
        message: 'Invalid or expired OTP. Please request a new one.'
      };
    }

    // Check if OTP matches (constant-time comparison via Rust SHA-256 with bcrypt fallback)
    const isMatch = await otpRecord.compareOTP(otp);
    if (!isMatch) {
      const failResult = await incrementOTPFailures(normalizedEmail, type);
      if (failResult.locked) {
        return {
          success: false,
          message: `Too many failed attempts. Please try again in ${failResult.waitSeconds} seconds.`,
          locked: true,
          waitSeconds: failResult.waitSeconds,
        };
      }
      return {
        success: false,
        message: 'Invalid OTP'
      };
    }

    // Mark as used (single-use)
    otpRecord.used = true;
    await otpRecord.save();
    await delRedisOTP(`${normalizedEmail}:${type}`);
    await resetOTPFailures(normalizedEmail, type);
    await OTP.updateMany(
      {
        email: normalizedEmail,
        type,
        used: false,
        _id: { $ne: otpRecord._id },
      },
      { used: true }
    );

    return {
      success: true,
      message: 'OTP verified successfully',
      otpRecord: {
        id: otpRecord._id,
        userId: otpRecord.user,
        email: otpRecord.email,
        type: otpRecord.type,
        expiresAt: otpRecord.expiresAt
      }
    };

  } catch (error) {
    console.error('OTP verification error:', error);
    return {
      success: false,
      message: 'Verification failed',
      error: error.message
    };
  }
};

/**
 * Resend OTP (with rate limiting)
 * @param {Object} params - { userId, email, type = 'email', phone? }
 * @returns {Promise<Object>} - Same as createAndSendOTP
 */
export const resendOTP = async (params) => {
  // For resend, we simply create a new OTP (rate limiting will apply)
  return await createAndSendOTP(params);
};

/**
 * Get OTP details (for debugging/admin purposes)
 * @param {string} email
 * @returns {Promise<Object|null>}
 */
export const getLatestOTP = async (email) => {
  return await OTP.findOne({ email })
    .sort({ createdAt: -1 })
    .select('-otpHash') // Don't expose hash
    .lean();
};

import crypto from 'node:crypto';
import Prescription from '../models/Prescription.js';
import logger from '../config/logger.js';

/**
 * REC-M-05: tamper-evident prescriptions with a public verification endpoint.
 *
 * THE PROBLEM
 * A prescription PDF renders a `signatureUrl` image. An image is not a
 * signature - anyone with a text editor can produce a pixel-identical one. There
 * was no cryptographic integrity value and no public way to check, so a forged
 * prescription was indistinguishable from a real one to a pharmacist holding it.
 *
 * WHAT "SIGNED" MEANS HERE, PRECISELY
 * An HMAC over a canonical digest of the clinical content, keyed by a server
 * secret. A forger can edit the medicines freely; what they cannot do is produce
 * a digest that verifies without the key. This attests "the platform issued this
 * and has not altered it since" - it is NOT a digital signature by a licensed
 * prescriber and must never be presented as one. That would need a per-doctor key
 * and a regulatory-grade HSM.
 *
 * WHY THE PUBLIC VERIFY ENDPOINT RETURNS SO LITTLE
 * It is unauthenticated, because the point is a pharmacist checking a paper
 * script. That makes it an oracle unless designed not to be one: it confirms
 * authenticity and returns a few non-identifying facts, and NEVER the patient,
 * the medicines or the diagnosis. A verify endpoint that echoes a patient's name
 * for any valid token is a patient lookup service with a URL.
 */

const TOKEN_VERSION = 'FM1';

const getSecret = () => process.env.PRESCRIPTION_SIGNING_SECRET || process.env.JWT_SECRET;

/**
 * Canonical form of the fields a pharmacist relies on.
 *
 * Key order is fixed and values stringified, because an HMAC over
 * `JSON.stringify` of a Mongoose subdocument is not stable across versions -
 * `__v`, key insertion order and undefined-vs-missing all leak in. If this ever
 * drifts, every previously issued prescription fails verification.
 */
export const canonicalise = (p = {}) => JSON.stringify({
  prescriptionId: String(p.prescriptionId ?? ''),
  patientId: String(p.patientId ?? ''),
  doctorId: String(p.doctorId ?? ''),
  appointmentId: String(p.appointmentId ?? ''),
  hospitalId: String(p.hospitalId ?? ''),
  // Medicines in order: reordering changes the prescription.
  medicines: (p.medicines || []).map((m) => [
    String(m.name ?? ''), String(m.dosage ?? ''), String(m.frequency ?? ''), String(m.duration ?? ''),
  ]),
  diagnosis: String(p.diagnosis ?? ''),
  createdAt: new Date(p.createdAt ?? 0).toISOString(),
});

export const computeDigest = (prescription) =>
  crypto.createHash('sha256').update(canonicalise(prescription)).digest('hex');

/**
 * Keyed signature over the digest. Constant-time comparison everywhere it is
 * checked - a `===` on an HMAC leaks prefix length by timing, which is enough to
 * forge one byte at a time.
 */
export const signDigest = (digest) => {
  const secret = getSecret();
  if (!secret) throw new Error('PRESCRIPTION_SIGNING_SECRET is not configured');
  return crypto.createHmac('sha256', secret).update(digest).digest('hex');
};

const safeEqual = (a, b) => {
  const bufA = Buffer.from(String(a));
  const bufB = Buffer.from(String(b));
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
};

/** Recompute and compare. Never trusts the stored signature. */
/**
 * Issue (or re-issue) the integrity block.
 *
 * Returns null when no signing secret is configured, so an unconfigured
 * deployment degrades to "no integrity value" rather than to a value signed with
 * an empty key, which would verify against anything.
 */
export const sealPrescription = (prescription, { nonce } = {}) => {
  if (!getSecret()) {
    logger.warn('[prescription-integrity] PRESCRIPTION_SIGNING_SECRET not set - prescription left unsigned');
    return null;
  }
  const digest = computeDigest(prescription);
  const signature = signDigest(digest);
  prescription.integrity = {
    version: TOKEN_VERSION,
    digest,
    signature,
    algorithm: 'HMAC-SHA256',
    issuedAt: new Date(),
    // Only a hash of the nonce is stored, so a database leak does not hand out
    // usable verification tokens for every live prescription on the platform.
    nonceHash: nonce ? crypto.createHash('sha256').update(nonce).digest('hex') : null,
  };
  return prescription.integrity;
};

/**
 * Mint a scannable token: `FM1.<prescriptionId>.<nonce>.<sig>`
 *
 * The signature covers the prescription id AND the nonce, so a token for one
 * prescription cannot be edited into a token for another.
 */
export const issueToken = (prescription, { nonce } = {}) => {
  const n = nonce || crypto.randomBytes(16).toString('hex');
  const body = `${TOKEN_VERSION}.${prescription.prescriptionId}.${n}`;
  const sig = crypto.createHmac('sha256', getSecret()).update(body).digest('hex').slice(0, 32);
  return { token: `${body}.${sig}`, nonce: n };
};

export const parseToken = (token) => {
  if (typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 4 || parts[0] !== TOKEN_VERSION) return null;
  const [, prescriptionId, nonce, sig] = parts;
  // Shape-validated BEFORE any lookup. `prescriptionId` goes into a query, and
  // `$` / `.` in a Mongo id is a query-operator injection surface.
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(prescriptionId)) return null;
  if (!/^[a-f0-9]{32}$/.test(nonce) || !/^[a-f0-9]{32}$/.test(sig)) return null;
  return { prescriptionId, nonce, sig };
};

/** Is this token authentic, before any database work? */
export const verifyTokenSignature = ({ prescriptionId, nonce, sig }) => {
  if (!getSecret()) return false;
  const body = `${TOKEN_VERSION}.${prescriptionId}.${nonce}`;
  const expected = crypto.createHmac('sha256', getSecret()).update(body).digest('hex').slice(0, 32);
  return safeEqual(expected, sig);
};

/**
 * Verify a scanned token end to end.
 *
 * Returns ONLY non-identifying facts. Callers must not widen this.
 */
export const verifyToken = async (token) => {
  const parsed = parseToken(token);
  if (!parsed) return { valid: false, reason: 'malformed' };
  if (!verifyTokenSignature(parsed)) return { valid: false, reason: 'bad-token-signature' };

  const prescription = await Prescription.findOne({ prescriptionId: parsed.prescriptionId })
    .select('integrity status cancelledAt revokedAt doctorId medicines createdAt')
    .lean();
  if (!prescription) return { valid: false, reason: 'not-found' };

  const integrity = verifyIntegrity(prescription);
  if (!integrity.valid) return { valid: false, reason: integrity.reason };

  if (prescription.revokedAt || prescription.cancelledAt || ['cancelled', 'revoked'].includes(prescription.status)) {
    return { valid: false, reason: 'revoked', issuedAt: integrity.issuedAt };
  }

  // A prescriber must still be an active, registered prescriber on the day of
  // dispensing. An integrity check that keeps passing after the doctor has been
  // struck off answers the wrong question.
  const doctor = await Prescription.db.model('User')
    .findById(prescription.doctorId)
    .select('status role')
    .lean();

  return {
    valid: true,
    issuedAt: integrity.issuedAt,
    // Boolean only - not the doctor, not the hospital.
    prescriberActive: !!doctor && doctor.status !== 'blocked',
    prescriberRoleIsClinical: !!doctor && ['doctor', 'clinic_doctor', 'psychiatrist', 'therapist'].includes(doctor.role),
    // Counts, not contents.
    medicineCount: (prescription.medicines || []).length,
  };
};
export const verifyIntegrity = (prescription) => {
  const integrity = prescription?.integrity;
  if (!integrity?.digest || !integrity?.signature) return { valid: false, reason: 'unsigned' };
  const digest = computeDigest(prescription);
  if (digest !== integrity.digest) return { valid: false, reason: 'content-changed' };
  if (!safeEqual(signDigest(digest), integrity.signature)) return { valid: false, reason: 'bad-signature' };
  return { valid: true, digest, signature: integrity.signature, issuedAt: integrity.issuedAt };
};

import mongoose from 'mongoose';
import Referral from '../models/Referral.js';
import ReferralSettings from '../models/ReferralSettings.js';
import User from '../models/User.js';
import crypto from 'crypto';

const generateReferralCode = (length = 6) => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let code = '';
  for (let i = 0; i < length; i++) {
    code += chars.charAt(crypto.randomInt(0, chars.length));
  }
  return code.toUpperCase();
};

export const referralService = {
  /**
   * Generate and save a referral code for a user (called on first access to Referral page)
   */
  async generateReferralCode(userId) {
    const user = await User.findById(userId);
    if (!user.referral.code) {
      let code = generateReferralCode(6);
      // Unique check loop
      let exists = await Referral.findOne({ code }).lean();
      while (exists) {
        code = generateReferralCode(6);
        exists = await Referral.findOne({ code }).lean();
      }
      user.referral.code = code;
      await user.save();
    }
    return user.referral.code;
  },

  /**
   * Apply referral code during signup
   * Called from auth signup handler
   */
  async applyReferralCode(userId, referralCode, context = {}) {
    if (!referralCode) return;

    const referrer = await User.findOne({ 'referral.code': referralCode }).select('_id email');
    if (!referrer) return; // invalid code

    // Self-referral block
    if (String(referrer._id) === String(userId)) return;

    // Check if this referee already has a referrer
    const existingReferral = await Referral.findOne({ refereeId: userId }).lean();
    if (existingReferral) return; // already referred

    // Spec 25 §4: device/IP ring detection — hash PII, never store raw IP.
    const ipHash = context.ip ? crypto.createHash('sha256').update(String(context.ip)).digest('hex').slice(0, 32) : '';
    const deviceHash = context.userAgent ? crypto.createHash('sha256').update(String(context.userAgent)).digest('hex').slice(0, 32) : '';

    // LOYALTY-BUG-02: Self-referral Sybil check — block if referrer has matching IP or device hash
    if (ipHash || deviceHash) {
      const selfReferralRing = await Referral.findOne({
        $or: [
          { referrerId: referrer._id, ipHash: { $ne: '', $eq: ipHash } },
          { referrerId: referrer._id, deviceHash: { $ne: '', $eq: deviceHash } },
          { refereeId: referrer._id, ipHash: { $ne: '', $eq: ipHash } },
          { refereeId: referrer._id, deviceHash: { $ne: '', $eq: deviceHash } },
        ],
      }).lean();
      if (selfReferralRing) {
        return; // Reject self-referral Sybil loop
      }
    }

    // Create pending referral record
    const referral = new Referral({
      referrerId: referrer._id,
      refereeId: userId,
      code: referralCode,
      status: 'pending',
      ipHash,
      deviceHash,
    });

    // Fraud ring: 3+ referees from the same IP within 24h → flag, no rewards ever.
    if (ipHash) {
      const since = new Date(Date.now() - 24 * 3600 * 1000);
      const sameIpCount = await Referral.countDocuments({ ipHash, createdAt: { $gte: since } });
      if (sameIpCount >= 3) {
        referral.status = 'fraud_flagged';
      }
    }
    await referral.save();

    // Update user referral fields
    await User.findByIdAndUpdate(userId, {
      $set: { 'referral.referredBy': referrer._id, 'referral.referredByCode': referralCode },
    });

    return referral;
  },

  /**
   * Check if a qualifying event should trigger rewards
   * Called when referee completes a qualifying action (appointment, order, etc.)
   */
  async checkAndRewardReferral(refereeId, actionType) {
    const settings = await ReferralSettings.findOne().lean();
    if (!settings?.isEnabled) return;

    const referral = await Referral.findOne({
      refereeId,
      status: 'pending',
    }).populate('referrerId');

    if (!referral) return;

    // Check if qualifying action matches config
    const qualifyingActions = {
      signup_only: true,
      first_appointment: actionType === 'first_appointment' || actionType === 'appointment_completed',
      first_order: actionType === 'first_order' || actionType === 'order_completed',
      first_lab_test: actionType === 'first_lab_test' || actionType === 'lab_test_completed',
    };

    if (!qualifyingActions[settings.qualifyingAction]) return;

    // Update referral status
    await Referral.findByIdAndUpdate(referral._id, {
      status: 'qualified',
      qualifyingAction: actionType,
      qualifiedAt: new Date(),
    });

    // Credit rewards to both via the loyalty points ledger (cooling-off over:
    // credits land only after the referee's first qualifying trip, never at signup).
    let referrerCredited = 0;
    let refereeCredited = 0;
    try {
      const { loyaltyService } = await import('./loyaltyService.js');
      referrerCredited = await loyaltyService.earnPoints(referral.referrerId._id, 'referral_qualified', referral._id);
      refereeCredited = await loyaltyService.earnPoints(refereeId, 'referral_qualified', referral._id);
    } catch {
      // Ledger failure must not roll back the qualified referral state.
    }
    await Referral.findByIdAndUpdate(referral._id, {
      status: 'rewarded',
      rewardedAt: new Date(),
      referrerRewardPoints: settings.referrerPoints,
      refereeRewardPoints: settings.refereePoints,
    });

    return {
      referrerId: referral.referrerId._id,
      refereeId: refereeId,
      referrerPoints: settings.referrerPoints,
      refereePoints: settings.refereePoints,
      referrerCredited,
      refereeCredited,
    };
  },

  /**
   * Get user's referral stats
   */
  async getReferralStats(userId) {
    const [totalReferred, qualified, rewarded, pending] = await Promise.all([
      Referral.countDocuments({ referrerId: userId }),
      Referral.countDocuments({ referrerId: userId, status: 'qualified' }),
      Referral.countDocuments({ referrerId: userId, status: 'rewarded' }),
      Referral.countDocuments({ referrerId: userId, status: 'pending' }),
    ]);

    return {
      totalReferred,
      qualified,
      rewarded,
      pending,
    };
  },

  /**
   * Get recent referrals (admin)
   */
  async getRecentReferrals(filter = {}) {
    return await Referral.find(filter)
      .populate('referrerId', 'name email')
      .populate('refereeId', 'name email')
      .sort({ createdAt: -1 })
      .limit(50);
  },
};

import PDFDocument from 'pdfkit';
import { signTxnRef } from '../lib/receiptSecurity.js';

const C = {
  primary: '#0f766e',
  primaryDark: '#134e4a',
  ink: '#111827',
  muted: '#6b7280',
  border: '#e5e7eb',
  soft: '#f9fafb',
  success: '#15803d',
};

const money = (v = 0) => `Rs. ${Number(v || 0).toLocaleString('en-IN')}`;

export async function generateRideReceiptPdf(ride, user, rider, vehicle) {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: 'A4', margin: 40 });
    const chunks = [];

    doc.on('data', chunk => chunks.push(chunk));
    doc.on('end', () => resolve(Buffer.concat(chunks)));
    doc.on('error', reject);

    // Header with branding
    doc.rect(0, 0, doc.page.width, 100).fill(C.primaryDark);

    doc.fillColor('#ffffff').fontSize(22).font('Helvetica-Bold').text('FindMedi Transport', 40, 30);
    doc.fontSize(11).font('Helvetica').text('Patient & Emergency Transport Service', 40, 58);
    doc.fontSize(10).text('Official Ride Receipt', doc.page.width - 160, 35, { align: 'right' });
    doc.fontSize(9).text(`Booking #${ride.bookingNumber || String(ride._id).slice(-6).toUpperCase()}`, doc.page.width - 160, 52, { align: 'right' });

    doc.fillColor(C.ink);
    let y = 130;

    // Ride Summary Card
