      if (isSocketEventRateLimited(socket, 'emergency_provider_location')) return;
      const access = await assertRoomAccess(actor, socket.userRole, 'emergency', requestId);
      if (!access.ok) return;
      const EmergencyRequest = (await import('../models/EmergencyRequest.js')).default;
      const activeRequest = await EmergencyRequest.findOne({ _id: requestId, status: { $in: ['assigned', 'en_route'] } }).select('assignedProviderId assignedProviderType').lean();
      if (!activeRequest) return;
      if (activeRequest.assignedProviderType !== providerType) return;
      if (providerType === 'ambulance' && providerId) {
        const Ambulance = (await import('../models/Ambulance.js')).default;
        const ambulance = await Ambulance.findOne({ _id: activeRequest.assignedProviderId, userId: actor, currentEmergencyId: requestId }).select('_id currentLocation').lean();
        if (!ambulance) return;
        if (await isEmergencyVelocityRejected(ambulance?.currentLocation, lat, lng)) return;
        await Ambulance.findByIdAndUpdate(ambulance._id, {
          'currentLocation.coordinates': [lng, lat],
          'currentLocation.updatedAt': new Date(),
          ...(accuracy != null ? { 'currentLocation.accuracy': Number(accuracy) } : {}),
          lastLocationAt: new Date(),
        }).catch(() => {});
      } else if (providerType === 'rider' && providerId) {
        const rider = await RiderProfile.findOne({ userId: actor }).select('_id currentLocation').lean();
        if (!rider || String(activeRequest.assignedProviderId) !== String(actor)) return;
        if (await isEmergencyVelocityRejected(rider?.currentLocation, lat, lng)) return;
        await RiderProfile.findOneAndUpdate(
          { _id: rider._id, userId: actor },
          {
            'currentLocation.lat': lat,
            'currentLocation.lng': lng,
            'currentLocation.coordinates': [lng, lat],
            ...(accuracy != null ? { 'currentLocation.accuracy': Number(accuracy) } : {}),
            'currentLocation.updatedAt': new Date(),
            lastLocationAt: new Date(),
          }
        ).catch(() => {});
      }

      if (requestId) {
        const updatePayload = { requestId, lat, lng, timestamp: Date.now() };
        namespace.to(`emergency:${requestId}`).emit('emergency_provider_location_update', updatePayload);
        if (io && namespace !== io) {
          io.to(`emergency:${requestId}`).emit('emergency_provider_location_update', updatePayload);
        }
      }
    } catch (err) {
      logger.error(`emergency_provider_location error: ${err.message}`);
    }
  });
}


const HOSPITAL_ROOM_RE = /^hospital:([A-Za-z0-9_-]{1,64})$/;

export function attachHospitalSocketHandlers(socket) {
  socket.on('join_room', async (payload) => {
    const room = typeof payload === 'string' ? payload : payload?.room;
    if (typeof room !== 'string') return;
    const match = HOSPITAL_ROOM_RE.exec(room);
    if (!match) return;
    const hospitalId = match[1];
    const { userId, role } = socketIdentity(socket);
    if (!userId) {
      socket.emit('error:room', { room: 'hospital', id: hospitalId, message: 'Not authorized' });
      return;
    }
    if (role !== 'superadmin') {
      let caller;
      try {
        caller = await User.findById(userId).select('hospitalId').lean();
      } catch (err) {
        logger.warn(`hospital room join lookup failed user=${userId}: ${err.message}`);
      }
      if (!caller?.hospitalId || String(caller.hospitalId) !== hospitalId) {
        logger.warn(`hospital room join denied user=${userId} hospital=${hospitalId}`);
        socket.emit('error:room', { room: 'hospital', id: hospitalId, message: 'Not authorized' });
        return;
      }
    }
    socket.join(`hospital:${hospitalId}`);
  });
  socket.on('leave_room', (payload) => {
    const room = typeof payload === 'string' ? payload : payload?.room;
    if (typeof room === 'string' && HOSPITAL_ROOM_RE.test(room)) socket.leave(room);
  });
}

const getAllowedSocketOrigins = () => {
  const envOrigins = [
    ...(process.env.CLIENT_URL ? process.env.CLIENT_URL.split(',') : []),
    ...(process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN.split(',') : []),
  ];
  const defaults = [
    'https://findmedi.online',
    'https://www.findmedi.online',
    ...(process.env.NODE_ENV === 'production' ? [] : [
      'http://localhost:5173',
      'http://localhost:3000',
      'http://localhost:5001',
    ]),
  ];
  return Array.from(new Set([...envOrigins, ...defaults]))
    .map(o => o.trim().replace(/\/+$/, ''))
    .filter(Boolean);
};

/**
 * Socket.IO handshake authentication (audit CHAT-001).
 *
 * Before this existed there was no `io.use()` anywhere in the backend, so the
 * `join` handler trusted the `userId`/`role` in the client payload. Any
 * anonymous socket could therefore claim to be any user, join that user's
 * `user:<id>` room and receive their notifications and chat, and forge events
 * that carried a client-supplied `riderId` / `senderId`.
 *
 * Identity is now derived ONLY from a verified JWT, and the token is taken
 * from the handshake (auth token first, then the httpOnly cookie) so this
 * reuses exactly the credentials the REST layer already validates.
 */
function readHandshakeToken(socket) {
  const authToken = socket.handshake?.auth?.token;
  if (authToken) return String(authToken).replace(/^Bearer\s+/i, '');

  const header = socket.handshake?.headers?.authorization;
  if (header && header.startsWith('Bearer ')) return header.slice(7);

  // Cookie header fallback: the REST layer accepts `cookies.token` too, so a
  // same-origin socket connects without the client having to duplicate the
  // token into the handshake payload.
  const cookieHeader = socket.handshake?.headers?.cookie || '';
  const match = cookieHeader.match(/(?:^|;\s*)(?:__Host-)?token=([^;]+)/);
  if (match) return decodeURIComponent(match[1]);

  return null;
}

// Exported for test/security coverage of the handshake gate.
export async function verifySocketAuth(socket, next) {
  const token = readHandshakeToken(socket);
  if (!token) {
    return next(new Error('unauthorized: no token'));
  }

  let decoded;
  try {
    decoded = verifyAccessToken(token);
  } catch {
    return next(new Error('unauthorized: invalid token'));
  }

  try {
    const user = await User.findById(decoded.id).select('role status isVerified tokenVersion');
    if (!user) return next(new Error('unauthorized: user not found'));
    if (user.status === 'blocked') return next(new Error('unauthorized: blocked'));
    // AUTH-F-04: logout-all / password change bump tokenVersion; a socket that
    // only checked the signature stayed authenticated on a revoked token until
    // it expired.
    if ((decoded.tv ?? 0) !== (user.tokenVersion || 0)) {
      return next(new Error('unauthorized: session revoked'));
    }

    // CHAT-B-04: written once, through one accessor, so `socket.data.*` and the
    // legacy mirrors can never diverge after a reconnect or a merge flow.
    setSocketIdentity(socket, user._id, user.role);
    return next();
  } catch (err) {
    // A DB error must not silently become "authenticated".
    logger.error(`Socket auth lookup failed: ${err.message}`);
    return next(new Error('unauthorized: auth lookup failed'));
  }
}

export function attachDeliverySocketHandlers(socket, io) {
  socket.on('deliveryboy:location', async ({ deliveryPartnerId, orderId, lat, lng }) => {
    try {
      const actor = selfOrReject(socket, deliveryPartnerId);
      if (!actor || !Number.isFinite(Number(lat)) || Number(lat) < -90 || Number(lat) > 90 || !Number.isFinite(Number(lng)) || Number(lng) < -180 || Number(lng) > 180) return;
      if (isSocketEventRateLimited(socket, 'deliveryboy:location')) return;
      const partner = await DeliveryPartner.findOne({ userId: actor, status: 'approved' }).select('_id userId').lean();
      if (!partner) return;
      if (orderId) {
        const verdict = await assertRoomAccess(actor, socket.userRole, 'order', orderId);
        if (!verdict.ok) return;
        const assigned = await PharmacyDelivery.findOne({ orderId, deliveryPartnerId: partner._id, status: { $in: ['Assigned', 'Picked Up', 'Out for Delivery'] } }).select('_id').lean();
        if (!assigned) return;
      }
      try {
        await updateDeliveryBoyLocation(actor, lat, lng);
      } catch (redisErr) {
        logger.warn(`Delivery location Redis cache skipped: ${redisErr.message}`);
      }
      await DeliveryPartner.findOneAndUpdate({ _id: partner._id, userId: actor }, {
        currentLocation: { lat, lng, updatedAt: new Date() },
      });
      if (orderId) {
        await PharmacyDelivery.findOneAndUpdate({ orderId, deliveryPartnerId: partner._id, status: { $in: ['Assigned', 'Picked Up', 'Out for Delivery'] } }, {
          $push: { trackingHistory: { lat, lng, timestamp: new Date() } },
        });
        io.to(`order:${orderId}`).emit('location:updated', { lat, lng, timestamp: Date.now() });
      }
    } catch (err) {
      logger.error(`location update failed: ${err.message}`);
    }
  });

  socket.on('deliveryboy:online', async ({ deliveryPartnerId, online }) => {
    const actor = selfOrReject(socket, deliveryPartnerId);
    if (!actor || typeof online !== 'boolean') return;
    await DeliveryPartner.findOneAndUpdate({ userId: actor, status: 'approved' }, { isOnline: online, isAvailable: online });
  });
}

export async function initSocket(server) {
  io = new Server(server, {
    cors: {
      origin: (origin, callback) => {
        if (!origin) return callback(null, true);
        // AUTH-B-07: the allowlist applies in EVERY environment. The old
        // `if (process.env.NODE_ENV !== 'production') return callback(null, true)`
        // accepted any origin on staging/preview, so a malicious page could open
        // an authenticated socket from a browser that already holds a token.
        const allowed = getAllowedSocketOrigins();
        const normalized = origin.trim().replace(/\/+$/, '');
        // AUTH-001/AUTH-020: exact match only — no endsWith suffix bypass.
        if (allowed.includes(normalized)) {
          return callback(null, true);
        }
        logger.warn(`Socket.IO CORS blocked for origin ${origin}`);
        return callback(new Error(`Socket.IO CORS blocked for origin ${origin}`));
      },
      methods: ['GET', 'POST'],
      credentials: true,
    },
  });

  // Redis adapter sirf tab lagao jab REDIS_URL set ho aur actual connect ho sake.
  if (process.env.REDIS_URL) {
    try {
      await connectRedis();
      if (isRedisReady()) {
        io.adapter(createAdapter(redisPub, redisSub));
        logger.info('Socket.IO initialized (with Redis adapter)');
      } else {
        logger.warn('Redis not ready — using in-memory Socket.IO adapter');
      }
    } catch (err) {
      logger.warn(`Redis unavailable (${err.message}) — falling back to in-memory Socket.IO adapter`);
    }
  } else {
    logger.info('Socket.IO initialized (in-memory adapter — single instance mode)');
  }

  // Every connection must present a valid token. Applied on the parent so the
  // default namespace is covered; each `io.of(...)` namespace gets it explicitly
  // below because namespaces do NOT inherit middleware from the parent.
  io.use(verifySocketAuth);

  io.on('connection', (socket) => {
    logger.info(`Socket connected: ${socket.id}`);

    socket.on('join', async (payload) => {
      // The client used to supply `userId`/`role` here and the server trusted
      // both, so any socket could join an arbitrary `user:<id>` room and read
      // that user's notifications and chat (audit CHAT-001). Identity now comes
      // exclusively from the token verified in verifySocketAuth; the payload is
      // retained only for the non-identity fields older clients still send.
      const userId = socket.data?.userId;
      const role = socket.data?.role;

      if (userId) {
        socket.userId = userId;
        socket.userRole = role;
        socket.join(`user:${userId}`);

        // Mark presence in Redis + DB (last seen / online indicator ke liye)
        try {
          await setUserPresence(userId, role);
          await User.findByIdAndUpdate(userId, { isOnline: true, lastActive: new Date() }).catch(() => {});
          io.emit('presence:change', { userId: String(userId), online: true, role });
        } catch (e) {}
      }
    });

    socket.on('presence:ping', async () => {
      if (socket.userId) {
        await setUserPresence(socket.userId, socket.userRole);
      }
    });

    socket.on('order:join_tracking', async (orderId) => {
      const verdict = await assertRoomAccess(socket.userId, socket.userRole, 'order', orderId);
      if (!verdict.ok) {
        socket.emit('error:room', { room: 'order', id: orderId, message: 'Not authorized' });
        return;
      }
      socket.join(verdict.room);
    });
    socket.on('order:leave_tracking', (orderId) => {
      if (orderId) socket.leave(`order:${orderId}`);
    });

    attachDeliverySocketHandlers(socket, io);

    // ─── Vehicle & Ride Events (Doc 05 §4) ───────────────────────────
    attachRideSocketHandlers(socket, io);

    // ─── Hospital Assistant Events (Doc 05 §4) ────────────────────────
    attachAssistantSocketHandlers(socket, io);

    // ─── Lawyer & Legal Events (Doc 05 §4) ─────────────────────────────
    attachLawyerSocketHandlers(socket, io);

    // ─── Emergency SOS Events ──────────────────────────────────────────
    attachEmergencySocketHandlers(socket, io);

    attachHospitalSocketHandlers(socket);

    // Chat Events
    // CHAT-B-01: joining used to be `socket.join('chat:'+id)` on a client-supplied
    // id with NO membership lookup, while the REST layer (chatMembership.js)
    // correctly enforced participants-only. Once joined, the socket received
    // typing, recording, delivered and read events for a doctor<->patient thread
    // it was not part of — and would receive message content the moment any event
    // carried it through the room.
    socket.on('chat:join', async (conversationId) => {
      const id = conversationId?.conversationId ?? conversationId;
      const verdict = await assertRoomAccess(socket.userId, socket.userRole, 'chat', id);
      if (!verdict.ok) {
        logger.warn(`CHAT-B-01: chat join denied user=${socket.userId} conversation=${id} reason=${verdict.reason}`);
        socket.emit('error:room', { room: 'chat', id, message: 'Not authorized' });
        return;
      }
      socket.join(`chat:${id}`);
    });

    socket.on('chat:leave', (conversationId) => {
      socket.leave(`chat:${conversationId}`);
    });

    // CHAT-B-03/05: typing/recording are broadcasts into the room, so the SENDER
    // must itself be a member. Without this an outsider could emit typing events
    // into a thread they were never in, and `socket.to(room)` would faithfully
    // deliver them to both participants.
    socket.on('chat:typing', async ({ conversationId, userId, isTyping }) => {
      const actor = selfOrReject(socket, userId);
      if (!actor || !(await isRoomMember(socket, 'chat', conversationId))) return;
      socket.to(`chat:${conversationId}`).emit('chat:typing', { conversationId, userId: actor, isTyping });
    });

    // Recording a voice message (mic button pressed)
    socket.on('chat:recording', async ({ conversationId, userId, isRecording }) => {
      const actor = selfOrReject(socket, userId);
      if (!actor || !(await isRoomMember(socket, 'chat', conversationId))) return;
      socket.to(`chat:${conversationId}`).emit('chat:recording', { conversationId, userId: actor, isRecording });
    });

    // Delivery receipts — sender ko wapas broadcast karo
    // CHAT-002: a receipt is an assertion about the RECIPIENT, so it may only be
    // written for the authenticated socket identity. Previously the payload
    // `userId` was used, letting any client mark another user's messages as
    // delivered and corrupt the sender's tick state.
    socket.on('chat:delivered', async ({ conversationId, userId }) => {
      if (!conversationId) return;
      const actor = selfOrReject(socket, userId);
      if (!actor) return;
      // CHAT-B-03: pinning the ACTOR to the token is necessary but not sufficient —
      // the actor must also be a member of THAT conversation. Otherwise (while
      // CHAT-B-01 was open) an outsider could clear a victim's unread badges.
      if (!(await isRoomMember(socket, 'chat', conversationId))) {
        logger.warn(`CHAT-B-03: chat:delivered rejected — user=${actor} conversation=${conversationId}`);
        return;
      }
      try {
        const ChatMessage = (await import('../models/ChatMessage.js')).default;
        await ChatMessage.updateMany(
          { conversationId, sender: { $ne: actor }, 'deliveredTo.userId': { $ne: actor } },
          { $push: { deliveredTo: { userId: actor, at: new Date() } } }
        );
      } catch (e) {}
      socket.to(`chat:${conversationId}`).emit('chat:delivered', { conversationId, userId: actor, at: new Date() });
    });

    // Read receipts — sender ko wapas broadcast karo (participant sirf apne messages ke ticks update kare)
    socket.on('chat:read', async ({ conversationId, userId }) => {
      if (!conversationId) return;
      const actor = selfOrReject(socket, userId);
      if (!actor) return;
      // CHAT-B-03: same membership gate as chat:delivered.
      if (!(await isRoomMember(socket, 'chat', conversationId))) {
        logger.warn(`CHAT-B-03: chat:read rejected — user=${actor} conversation=${conversationId}`);
        return;
      }
      let shareReceipt = true;
      try {
        const [{ default: ChatMessage }, { default: ChatPrivacy }] = await Promise.all([
          import('../models/ChatMessage.js'),
          import('../models/ChatPrivacy.js'),
        ]);
        // Privacy: user ne read receipts OFF kiye hain to sender ko blue tick nahi milega
        const privacy = await ChatPrivacy.findOne({ userId: actor }).select('readReceipts').lean();
        shareReceipt = privacy ? privacy.readReceipts !== false : true;

        if (shareReceipt) {
          const now = new Date();
          await ChatMessage.updateMany(
            { conversationId, sender: { $ne: actor }, 'readBy.userId': { $ne: actor } },
            { $push: { readBy: { userId: actor, at: now }, deliveredTo: { userId: actor, at: now } } }
          );
        }
      } catch (e) {}
      if (shareReceipt) {
        socket.to(`chat:${conversationId}`).emit('chat:read', { conversationId, userId: actor, at: new Date() });
      }
    });

    // Presence ping from chat page — last seen fresh rakhta hai
    // CHAT-002: presence is a property of the caller, never of a payload id.
    socket.on('chat:presence', async ({ userId }) => {
      const actor = selfOrReject(socket, userId);
      if (actor) {
        await setUserPresence(actor, socket.userRole);
        try {
          await User.findByIdAndUpdate(actor, { isOnline: true, lastActive: new Date() });
        } catch (e) {}
      }
    });

    // ── WebRTC 1-to-1 Audio & Video Call Signalling ──────────────────────────────
    // Socket.IO is solely used for signaling (SDP & ICE exchange); media travels directly via WebRTC peer connection.
    const allCallEvents = [
      // 1-to-1 Audio Calls
      'call:invite', 'call:ringing', 'call:accept', 'call:reject',
      'call:cancel', 'call:end', 'call:busy', 'call:timeout',
      'call:offer', 'call:answer', 'call:ice', 'call:state', 'call:missed',
      'chat:call_invite', 'chat:call_ringing', 'chat:call_accept', 'chat:call_reject',
      'chat:call_cancel', 'chat:call_end', 'chat:call_offer', 'chat:call_answer',
      'chat:call_ice', 'chat:call_state', 'chat:call_missed',
      // 1-to-1 Full HD Video Calls (Strictly isolated channel)
      'videocall:invite', 'videocall:ringing', 'videocall:accept', 'videocall:reject',
      'videocall:cancel', 'videocall:end', 'videocall:busy', 'videocall:timeout',
      'videocall:offer', 'videocall:answer', 'videocall:ice', 'videocall:state',
      'videocall:track_state', 'videocall:switch_camera', 'videocall:message', 'videocall:screen_share',
    ];

    allCallEvents.forEach((event) => {
      socket.on(event, async (payload = {}) => {
        const target = payload.to || payload.recipientId || payload.peerId || payload.targetUserId;
        // CHAT-002: `from` is the authenticated identity. A caller-supplied
        // `from` would let anyone place a call invite or SDP offer in someone
        // else's name.
        const from = socket.userId;
        if (!target || !from) return;
        if (event.startsWith('chat:call_')) {
          const conversationId = payload.conversationId;
          if (!conversationId) return;
          try {
            const verdict = await assertRoomAccess(from, socket.userRole, 'chat', conversationId);
            if (!verdict.ok) return;
            const ChatConversation = (await import('../models/ChatConversation.js')).default;
            const conversation = await ChatConversation.findById(conversationId).select('participants').lean();
            const participants = (conversation?.participants || []).map((participant) => String(participant?._id || participant));
            if (!participants.includes(String(from)) || !participants.includes(String(target)) || String(target) === String(from)) return;
          } catch (error) {
            logger.warn(`chat call relay denied after membership lookup failure: ${error.message}`);
            return;
          }
        }
        const body = { ...payload, from };
        io.to(`user:${target}`).emit(event, body);
        if (payload.conversationId) {
          socket.to(`chat:${payload.conversationId}`).emit(event, body);
        }
      });
    });

    socket.on('disconnect', async () => {
      logger.info(`Socket disconnected: ${socket.id}`);
      if (socket.userId) {
        try {
          await removeUserPresence(socket.userId, socket.userRole);
          await User.findByIdAndUpdate(socket.userId, { isOnline: false, lastActive: new Date() }).catch(() => {});
          io.emit('presence:change', { userId: socket.userId, online: false, role: socket.userRole });
        } catch (e) {}
      }
    });
  });

  const rideNsp = io.of('/ride');
  rideNsp.use(verifySocketAuth);
  rideNsp.on('connection', (socket) => {
    attachRideSocketHandlers(socket, rideNsp);
  });

  const assistantNsp = io.of('/assistant');
  assistantNsp.use(verifySocketAuth);
  assistantNsp.on('connection', (socket) => {
    attachAssistantSocketHandlers(socket, assistantNsp);
  });

  const lawyerNsp = io.of('/lawyer');
  lawyerNsp.use(verifySocketAuth);
  lawyerNsp.on('connection', (socket) => {
    attachLawyerSocketHandlers(socket, lawyerNsp);
  });

  logger.info('Socket.IO ready');
  return io;
}


// 6.md §2.15: the live toast is a PREVIEW surface exactly like the list and
// the read-ack, so it carries the same neutral copy for a discreet-mode user
// (applyDiscreetCopy reads the OWNER's preference). The io guard runs BEFORE
// the preference read: with no server there is nothing to emit, and a process
// that never called initIo (tests, workers) must not pay a preference lookup
// - or a buffered Mongo query - for a no-op. The read is awaited inside a
// fire-and-forget promise, so callers keep their sync contract; the toast may
// now land a few ms after the HTTP response, which is harmless because the
// list itself is redacted too.
async function emitPreview(userId, notification) {
  const pref = await loadPreference(userId).catch(() => null);
  try {
    io?.to(`user:${userId}`).emit('notification', applyDiscreetCopy(notification, pref));
  } catch {
    // io closed between the guard and the emit - the toast is lost either way.
  }
}

export function notifyUser(userId, notification) {
  if (io) void emitPreview(userId, notification);
}

/**
 * Chat REST handlers se room-wide realtime event bhejne ke liye helper.
 * DB mutation ke baad route code ise call karta hai — clients turant
 * update ho jaate hain bina refetch kiye. Silent no-op agar socket band ho.
 */
export function emitChatEvent(conversationId, event, payload) {
  if (!io || !conversationId) return;
  try {
    io.to(`chat:${conversationId}`).emit(event, payload);
  } catch (e) {}
}

/** Specific user ke personal room me event (notifications, force-refresh etc.) */
export function emitChatNotification(userId, event, payload) {
  if (!io || !userId) return;
  try {
    io.to(`user:${userId}`).emit(event, payload);
  } catch (e) {}
}


export function notifyUsers(userIds, notification) {
  if (io) {
    userIds.forEach((userId) => {
      // Per user, not per batch: each recipient reads their OWN preference.
      void emitPreview(userId, notification);
    });
  }
}

export function emitDeliveryStatus(orderId, status, extra = {}) {
  if (io) io.to(`order:${orderId}`).emit('delivery:status', { status, ...extra, timestamp: Date.now() });
}

/**
 * Notify a doctor (by their user ID) that a schedule change request was reviewed.
 * The doctor's My Schedule page listens for this event to auto-remove the blur
 * and render blue/red highlights without requiring a page refresh.
 */
export function emitScheduleRequestUpdate(doctorUserId, payload) {
  if (io) io.to(`user:${doctorUserId}`).emit('schedule-request-updated', payload);
}

/**
 * Realtime appointment updates — naya booking ya status change hone par
 * doctor, clinic staff aur patient ke rooms ko notify karta hai. Client pages
 * 'appointment:updated' sun kar data reload kar lete hain (koi polling nahi chahiye).
 */
export async function emitAppointmentUpdate(appointment) {
  if (!io || !appointment) return;
  try {
    const rooms = new Set();

    const doctorId = appointment.doctorId?._id || appointment.doctorId;
    if (doctorId) {
      const doctor = await Doctor.findById(doctorId).select('user_id facilityId hospitalId').lean();
      if (doctor?.user_id) rooms.add(`user:${doctor.user_id}`);
      // Clinic admins/staff bhi usi facility ke appointments dekhte hain
      if (doctor?.facilityId) {
        const staff = await User.find({ role: { $in: ['clinic_admin', 'clinic_doctor'] }, facilityId: doctor.facilityId }).select('_id').lean();
        staff.forEach(u => rooms.add(`user:${u._id}`));
      }
      if (doctor?.hospitalId) {
        const admins = await User.find({ role: 'hospital_admin', hospitalId: doctor.hospitalId }).select('_id').lean();
        admins.forEach(u => rooms.add(`user:${u._id}`));
      }
    }

    const patientId = appointment.patientId?._id || appointment.patientId;
    if (patientId) {
      const patient = await Patient.findById(patientId).select('userId').lean();
      if (patient?.userId) rooms.add(`user:${patient.userId}`);
    }

    const payload = { appointmentId: String(appointment._id) };
    rooms.forEach(room => io.to(room).emit('appointment:updated', payload));
  } catch (err) {
    logger.error(`appointment socket emit failed: ${err.message}`);
  }
}

import EmergencyRequest from '../models/EmergencyRequest.js';
import {
  findEligibleAmbulances,
  findEligibleEmergencyVehicles,
  finalizeWave,
  buildResponderPayload,
} from './emergencyDispatchService.js';
import Ambulance from '../models/Ambulance.js';
import { getIO } from './socketService.js';
import Notification from '../models/Notification.js';
import logger from '../config/logger.js';
import SOSVehicleSettings from '../models/SOSVehicleSettings.js';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function getSettings() {
  try {
    const s = await SOSVehicleSettings.findOne().lean();
    if (s) return s;
  } catch {}
  return { radiusSteps: [5, 10, 15, 20], windowSeconds: 30, maxRetriesPerRadius: 3, retryPauseSeconds: 3 };
}

function buildAlert(request, item, kind) {
  const base = {
    requestId: String(request._id),
    category: request.category,
    isSelf: request.reporterMode === 'self',
    patient: request.patientDetails,
    reporter: request.reporterOwnDetailsShared ? request.reporterDetails : null,
    location: request.location,
    distanceKm: item.distanceKm,
    windowSeconds: 30,
    providerType: kind,
  };
  if (kind === 'ambulance') {
    return { ...base, ambulanceId: String(item._id), hospitalName: item.hospital?.name || 'Hospital Ambulance' };
  }
  return { ...base, providerId: String(item.user?._id || item.userId), vehicleType: item.vehicle?.type || 'Vehicle' };
}

function sendAlert(io, requestId, c) {
  if (!io) return;
  const payload = c.raw;
  io.to(`user:${c.userId}`).emit('incoming_emergency', payload);
  if (c.providerType === 'ambulance') io.to(`ambulance:${c.providerId}`).emit('incoming_emergency', payload);
}

async function buildCandidates(request, radiusKm, { fresh = false } = {}) {
  const [lng, lat] = request.location.coordinates;
  // fresh=true (Search Again): pehle alert gaye providers ko dobara alert bhejna allowed hai
  const ever = fresh ? [] : (request.everNotified || []).map((e) => (typeof e === 'string' ? e : e.providerId));
  const types = request.selectedVehicleTypes || [];
  const wantAmb = types.includes('ambulance') || request.requestMode === 'auto_select_ambulance';
  const wantVeh = types.some((t) => ['auto', 'e_rickshaw', 'car', 'van'].includes(t)) || request.requestMode === 'auto_select_vehicle';
  const out = [];

  if (wantAmb) {
    const found = await findEligibleAmbulances(lng, lat, radiusKm, ever);
    found.filter((a) => a.userId).forEach((a) =>
      out.push({ providerId: String(a._id), providerType: 'ambulance', userId: String(a.userId), distanceKm: a.distanceKm, raw: buildAlert(request, a, 'ambulance') })
    );
  }
  if (wantVeh) {
    const found = await findEligibleEmergencyVehicles(lng, lat, radiusKm, ever);
    const allowed = new Set(types.filter((t) => t !== 'ambulance'));
    found.forEach((v) => {
      const vt = v.vehicle?.type;
      if (request.requestMode === 'manual_select' && allowed.size && !allowed.has(vt)) return;
      const uid = String(v.user?._id || v.userId);
      if (!uid || uid === 'undefined') return;
      out.push({ providerId: uid, providerType: 'rider', userId: uid, distanceKm: v.distanceKm, raw: buildAlert(request, v, 'rider') });
    });
  }
  return out;
}

async function openWave(requestId, radiusKm, candidates, attemptNumber = 1) {
  const settings = await getSettings();
  const windowMs = (settings.windowSeconds || 30) * 1000;
  const req = await EmergencyRequest.findById(requestId).select('currentSearchPhase');
  const phase = req?.currentSearchPhase || 'vehicle';
  await EmergencyRequest.findByIdAndUpdate(requestId, {
    $set: {
      currentSearchRadiusKm: radiusKm,
      notified: candidates.map((c) => ({ providerId: c.providerId, providerType: c.providerType, userId: c.userId })),
      acceptances: [],
      rejections: [],
      windowEndsAt: new Date(Date.now() + windowMs),
    },
    $addToSet: { everNotified: { $each: candidates.map((c) => ({ providerId: c.providerId })) } },
    $push: { dispatchLog: { radiusKm, phase, attemptNumber, candidateCount: candidates.length, outcome: 'escalated' } },
  });
  const io = getIO();
  if (io) {
    io.to(`emergency:${requestId}`).emit('emergency_searching_update', {
      requestId: String(requestId), phase, radiusKm, attemptNumber,
      statusText: `${radiusKm} km me dhoondh rahe hain…`,
    });
  }
  candidates.forEach((c) => sendAlert(io, requestId, c));
  return { windowMs, phase };
}

async function waitWindow(requestId, windowMs) {
  const deadline = Date.now() + windowMs;
  while (Date.now() < deadline) {
    await sleep(1000);
    const r = await EmergencyRequest.findById(requestId).select('status notified acceptances rejections');
    if (!r || r.status !== 'searching') return { stopped: true };
    // Sab ne reject kar diya to hi jaldi band karo; accept ho to poori window wait (closest wins)
    if (r.notified?.length && r.rejections.length >= r.notified.length) break;
  }
  return { stopped: false };
}

/**
 * Window band hone par patient ko (aur bina-accept wale providers ko) batao.
 * Accepted providers overlay me "waiting" rehte hain jab tak patient book / cancel na kare.
 */
async function announceWindowClosed(requestId, radiusKm) {
  const r = await EmergencyRequest.findById(requestId).select('status notified acceptances');
  if (!r || r.status !== 'searching') return { accepted: [], stopped: true };
  const accepted = [...(r.acceptances || [])].sort((a, b) => a.distanceKm - b.distanceKm);
  const io = getIO();
  if (io) {
    io.to(`emergency:${requestId}`).emit('emergency_window_closed', {
      requestId: String(requestId),
      radiusKm,
      accepted: accepted.map((a) => ({ providerId: a.providerId, providerType: a.providerType, userId: a.userId, distanceKm: a.distanceKm })),
    });
    const acceptedUsers = new Set(accepted.map((a) => String(a.userId)));
    (r.notified || [])
      .filter((n) => !acceptedUsers.has(String(n.userId)))
      .forEach((n) => io.to(`user:${n.userId}`).emit('emergency_expired_no_response', { requestId: String(requestId) }));
  }
  return { accepted, stopped: false };
}

export async function startManualModeSearch(requestId, radiusKm, opts = {}) {
  const request = await EmergencyRequest.findById(requestId);
  if (!request || request.status !== 'searching') return { error: 'Request not searching' };

  // Pichli wave ke providers (accepted waiting wale bhi) ke overlay band karo
  const io0 = getIO();
  (request.notified || []).forEach((n) => io0?.to(`user:${n.userId}`).emit('emergency_closed', { requestId: String(requestId) }));

  const cands = await buildCandidates(request, radiusKm, { fresh: !!opts.fresh });
  if (!cands.length) {
    await EmergencyRequest.findByIdAndUpdate(requestId, {
      $set: { currentSearchRadiusKm: radiusKm, notified: [], acceptances: [], rejections: [] },
      $push: { dispatchLog: { radiusKm, phase: request.currentSearchPhase, attemptNumber: 1, candidateCount: 0, outcome: 'no_acceptance' } },
    });
    await announceWindowClosed(requestId, radiusKm); // 0 candidates ho tab bhi patient ko result do
    return { accepted: [], done: false };
  }
  const { windowMs } = await openWave(requestId, radiusKm, cands, 1);
  await waitWindow(requestId, windowMs);
  const { accepted, stopped } = await announceWindowClosed(requestId, radiusKm);
  if (stopped) return { accepted: [], done: true };
  return { accepted, done: false };
}

export async function bookChosenProvider(requestId, providerId) {
  const request = await EmergencyRequest.findById(requestId);
  if (!request || request.status !== 'searching') return { error: 'Request not searching' };
  const acc = (request.acceptances || []).find((a) => String(a.providerId) === String(providerId));
  if (!acc) return { error: 'Provider ne accept nahi kiya' };
  const providerType = acc.providerType;
  const update = { status: 'assigned', assignedProviderId: providerId, assignedProviderType: providerType, assignedAt: new Date() };
  if (providerType === 'ambulance') {
    const amb = await Ambulance.findById(providerId).select('hospitalId').lean();
    if (amb?.hospitalId) update.assignedHospitalId = amb.hospitalId;
  }
  const updated = await EmergencyRequest.findOneAndUpdate({ _id: requestId, status: 'searching' }, update, { new: true });
  if (!updated) return { error: 'Could not book - already assigned' };
  if (providerType === 'ambulance') {
    await Ambulance.findByIdAndUpdate(providerId, { isOnDuty: true, currentEmergencyId: request._id }).catch(() => {});
  }
  const payload = await buildResponderPayload({ providerId, providerType, userId: acc.userId, distanceKm: acc.distanceKm }).catch(() => ({ providerType }));
  const losers = (request.acceptances || []).filter((a) => String(a.providerId) !== String(providerId));
  const io = getIO();
  if (io) {
    io.to(`emergency:${requestId}`).emit('emergency_assigned', { requestId: String(requestId), ...payload, manualChoice: true });
    io.to(`user:${acc.userId}`).emit('emergency_assigned_to_you', { requestId: String(requestId), ...payload });
    if (providerType === 'ambulance') {
      io.to(`ambulance:${providerId}`).emit('emergency_assigned_to_you', { requestId: String(requestId), ...payload });
    }
    losers.forEach((l) => io.to(`user:${l.userId}`).emit('emergency_lost', {
      requestId: String(requestId),
      message: 'Ye emergency patient ne kisi aur responder ko book kar diya.',
    }));
    (request.notified || [])
      .filter((n) => n.userId !== acc.userId)
      .forEach((n) => io.to(`user:${n.userId}`).emit('emergency_closed', { requestId: String(requestId) }));
  }
  try {
    if (acc?.userId) {
      await Notification.create({
        title: 'Emergency Assigned',
        message: `Patient ne aapko book kiya — ${request.category || 'General'}`,
        type: 'system',
        userId: String(acc.userId),
      });
    }
  } catch {}
  return { success: true, request: updated };
}

export async function startAutoBookSearch(requestId, radiusKm) {
  const request = await EmergencyRequest.findById(requestId);
  if (!request || request.status !== 'searching') return { error: 'Request not searching' };
  const cands = await buildCandidates(request, radiusKm);
  if (!cands.length) return { success: false, assigned: false };
  const { windowMs } = await openWave(requestId, radiusKm, cands, 1);
  await waitWindow(requestId, windowMs);
  const out = await finalizeWave(requestId);
  if (out.done) {
    const updatedRequest = await EmergencyRequest.findById(requestId);
    return { success: true, assigned: true, request: updatedRequest };
  }
  return { success: false, assigned: false };
}

export async function startAutoFindLoop(requestId, radiusSteps, maxRetriesPerRadius = 3, retryPauseMs = 3000) {
  const steps = Array.isArray(radiusSteps) && radiusSteps.length ? radiusSteps : [5, 10, 15, 20];
  for (const radiusKm of steps) {
    for (let attempt = 1; attempt <= maxRetriesPerRadius; attempt++) {
      const cur = await EmergencyRequest.findById(requestId).select('status location selectedVehicleTypes requestMode everNotified currentSearchPhase');
      if (!cur || cur.status !== 'searching') return { stopped: true };
      const cands = await buildCandidates(cur, radiusKm);
      if (!cands.length) {
        await EmergencyRequest.findByIdAndUpdate(requestId, {
          $set: { currentSearchRadiusKm: radiusKm },
          $push: { dispatchLog: { radiusKm, phase: cur.currentSearchPhase, attemptNumber: attempt, candidateCount: 0, outcome: 'no_acceptance' } },
        });
        const io = getIO();
        if (io) io.to(`emergency:${requestId}`).emit('emergency_searching_update', { requestId: String(requestId), phase: cur.currentSearchPhase, radiusKm, attemptNumber: attempt, maxRetries: maxRetriesPerRadius, statusText: `${radiusKm} km me attempt ${attempt}…` });
        if (attempt < maxRetriesPerRadius) await sleep(retryPauseMs);
        continue;
      }
      const { windowMs } = await openWave(requestId, radiusKm, cands, attempt);
      const io = getIO();
      if (io) io.to(`emergency:${requestId}`).emit('emergency_searching_update', { requestId: String(requestId), phase: cur.currentSearchPhase, radiusKm, attemptNumber: attempt, maxRetries: maxRetriesPerRadius, statusText: `${radiusKm} km me attempt ${attempt}…` });
      await waitWindow(requestId, windowMs);
      const out = await finalizeWave(requestId);
      if (out.done) {
        const updatedRequest = await EmergencyRequest.findById(requestId);
        return { success: true, assigned: true, request: updatedRequest };
      }
      if (attempt < maxRetriesPerRadius) await sleep(retryPauseMs);
    }
    await sleep(retryPauseMs);
  }
  const cur = await EmergencyRequest.findById(requestId);
  if (cur && cur.status === 'searching') {
    await EmergencyRequest.updateOne({ _id: requestId, status: 'searching' }, { $set: { status: 'no_responders_found' } });
    const io = getIO();
    if (io) io.to(`emergency:${requestId}`).emit('emergency_no_responders_found', { requestId: String(requestId), message: 'No emergency responders could be dispatched in your area right now. Please call emergency services directly (108 / 112).' });
    logger.warn(`Auto-find ${requestId}: no responders found.`);
  }
  return { success: false, assigned: false };
}

/**
 * Auto-escalate loop (single wave per radius, no retries).
 * Used by auto-book modes WITHOUT auto-find: startingRadius se shuru karke
 * har radius pe ek wave, assign hote hi stop, warna next radius. Sab khatam
 * ho to no_responders_found — request kabhi orphan 'searching' me nahi atki.
 */
export async function startAutoEscalateLoop(requestId, radiusSteps, startingRadiusKm = 5) {
  const steps = (Array.isArray(radiusSteps) && radiusSteps.length ? radiusSteps : [5, 10, 15, 20])
    .filter((r) => Number(r) >= Number(startingRadiusKm || 0));
  const list = steps.length ? steps : [Number(startingRadiusKm) || 5];
  for (const radiusKm of list) {
    const cur = await EmergencyRequest.findById(requestId).select('status');
    if (!cur || cur.status !== 'searching') return { stopped: true };
    const res = await startAutoBookSearch(requestId, radiusKm);
    if (res.error) return res;
    if (res.assigned) return res;
  }
  const cur = await EmergencyRequest.findById(requestId);
  if (cur && cur.status === 'searching') {
    await EmergencyRequest.updateOne({ _id: requestId, status: 'searching' }, { $set: { status: 'no_responders_found' } });
    const io = getIO();
    if (io) io.to(`emergency:${requestId}`).emit('emergency_no_responders_found', { requestId: String(requestId), message: 'No emergency responders could be dispatched in your area right now. Please call emergency services directly (108 / 112).' });
    logger.warn(`Auto-escalate ${requestId}: no responders found.`);
  }
  return { success: false, assigned: false };
}

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const configPath = path.join(__dirname, '../config/statutory.json');

/** Legacy flat fallback (pre-versioning shape) — used only if the JSON is unreadable. */
const LEGACY_CONFIG = {
  versions: [{
    fy: '2025-26',
    effectiveFrom: '2025-04-01',
    verified: false,
    verifiedBy: null,
    pf: { employeeRate: 0.12, employerRate: 0.12, wageCeiling: 15000, maxEmployeeMonthlyContribution: 1800 },
    esi: { grossWageCeiling: 21000, employeeRate: 0.0075, employerRate: 0.0325 },
    gratuity: { daysFactorNumerator: 15, daysFactorDenominator: 26, minimumTenureYears: 5 },
    tds: { standardDeduction: 75000, rebate87aTaxableLimit: 1200000 },
    newTaxRegimeSlabs: [
      { upTo: 400000, rate: 0.0 },
      { upTo: 800000, rate: 0.05 },
      { upTo: 1200000, rate: 0.10 },
      { upTo: 1600000, rate: 0.15 },
      { upTo: 2000000, rate: 0.20 },
      { upTo: 2400000, rate: 0.25 },
      { upTo: null, rate: 0.30 },
    ],
  }],
};

let statutoryConfig;
try {
  const parsed = JSON.parse(fs.readFileSync(configPath, 'utf8'));
  if (Array.isArray(parsed?.versions) && parsed.versions.length > 0) {
    statutoryConfig = parsed;
  } else if (parsed?.pf) {
    // Legacy flat shape → wrap as a single version so resolve() works uniformly.
    statutoryConfig = { versions: [{ fy: parsed.financialYear || 'unknown', effectiveFrom: '2025-04-01', verified: false, verifiedBy: null, ...parsed }] };
  } else {
    statutoryConfig = LEGACY_CONFIG;
  }
} catch {
  statutoryConfig = LEGACY_CONFIG;
}

// Ascending effectiveFrom so the newest applicable version wins.
const VERSIONS = [...statutoryConfig.versions].sort(
  (a, b) => new Date(a.effectiveFrom).getTime() - new Date(b.effectiveFrom).getTime(),
);

/**
 * T4 (file 31): pick the statutory version in force for a payroll month.
 * Backdated / arrears runs pass the actual wage-month and get that era's rules.
 *
 * @param {string|Date|number} [asOf] — payroll date; defaults to "now"
 * @returns {object} the version object { fy, effectiveFrom, verified, pf, ... }
 */
export function resolveStatutoryVersion(asOf) {
  const when = asOf == null ? Date.now() : new Date(asOf).getTime();
  if (Number.isNaN(when)) return VERSIONS[VERSIONS.length - 1];
  let picked = VERSIONS[0];
  for (const v of VERSIONS) {
    if (new Date(v.effectiveFrom).getTime() <= when) picked = v;
  }
  return picked;
}

/**
 * Version metadata for payslip footer / PayrollRun.statutoryVersion audit.
 */
export function getStatutoryVersionMeta(asOf) {
  const v = resolveStatutoryVersion(asOf);
  return {
    fy: v.fy,
    effectiveFrom: v.effectiveFrom,
    verified: v.verified === true,
    verifiedBy: v.verifiedBy || null,
    sourceNote: v.sourceNote || null,
  };
}

/**
 * Calculates Employee & Employer Provident Fund (PF).
 * Wage base = Basic + DA.
 * If wage <= 15000: 12% employee capped at ₹1800, employer 12% (3.67% EPF + 8.33% EPS).
 * @param {string|Date} [asOf] payroll month → statutory version selector
 */
export function calculatePf(basicPay, da = 0, optVoluntaryHigher = false, asOf = undefined) {
  const wage = Math.max(0, Number(basicPay || 0) + Number(da || 0));
  const { employeeRate, wageCeiling, maxEmployeeMonthlyContribution } = resolveStatutoryVersion(asOf).pf;

  let employeePf;
  if (!optVoluntaryHigher && wage > wageCeiling) {
    employeePf = maxEmployeeMonthlyContribution;
  } else {
    employeePf = Math.min(Math.round(wage * employeeRate), wage <= wageCeiling ? maxEmployeeMonthlyContribution : Infinity);
  }

  const employerPension = Math.round(Math.min(wage, wageCeiling) * 0.0833);
  const employerEpfs = Math.round(employeePf - employerPension);
  const employerPf = employerPension + employerEpfs;

  return {
    pfWage: wage,
    employeePf,
    employerPf,
    employerPension,
    employerEpfs,
  };
}

/**
 * Calculates Employee & Employer State Insurance (ESI).
 * Applicable if gross monthly wages <= ₹21,000.
 * Employee: 0.75%, Employer: 3.25%.
 * @param {string|Date} [asOf] payroll month → statutory version selector
 */
export function calculateEsi(grossSalary, asOf = undefined) {
  const gross = Math.max(0, Number(grossSalary || 0));
  const { grossWageCeiling, employeeRate, employerRate } = resolveStatutoryVersion(asOf).esi;

  if (gross > grossWageCeiling) {
    return {
      isEligible: false,
      grossWage: gross,
      employeeEsi: 0,
      employerEsi: 0,
    };
  }

  const employeeEsi = Math.round(gross * employeeRate);
  const employerEsi = Math.round(gross * employerRate);

  return {
    isEligible: true,
    grossWage: gross,
    employeeEsi,
    employerEsi,
  };
}

/**
 * Calculates Payment of Gratuity.
 * Formula: (15 / 26) * Last Drawn Basic * Tenure in Completed Years.
 * Minimum eligibility: 5 years of service.
 * @param {string|Date} [asOf] payroll month → statutory version selector
 */
export function calculateGratuity(lastDrawnBasic, tenureYears, asOf = undefined) {
  const basic = Math.max(0, Number(lastDrawnBasic || 0));
  const years = Math.max(0, Number(tenureYears || 0));
  const { daysFactorNumerator, daysFactorDenominator, minimumTenureYears } = resolveStatutoryVersion(asOf).gratuity;

  const isEligible = years >= minimumTenureYears;
  const gratuityAmount = isEligible
    ? Math.round((daysFactorNumerator / daysFactorDenominator) * basic * years)
    : 0;

  return {
    isEligible,
    tenureYears: years,
    lastDrawnBasic: basic,
    gratuityAmount,
  };
}

/**
 * Calculates Annual & Monthly Estimated Tax Deducted at Source (TDS)
 * under the New Tax Regime slabs of the version in force for `asOf`.
 * Standard deduction + 87A rebate limits come from the version (they changed
 * across FYs — do not hardcode them here).
 * @param {string|Date} [asOf] payroll / assessment date → statutory version selector
 */
export function calculateTds(annualTaxableIncome, deductions80C = 0, deductions80D = 0, asOf = undefined) {
  const version = resolveStatutoryVersion(asOf);
  const gross = Math.max(0, Number(annualTaxableIncome || 0));
  const standardDeduction = version.tds?.standardDeduction ?? 75000;
  const rebateLimit = version.tds?.rebate87aTaxableLimit ?? 1200000;
  const taxable = Math.max(0, gross - standardDeduction - Number(deductions80C || 0) - Number(deductions80D || 0));

  let tax = 0;
  let prevLimit = 0;

  for (const slab of version.newTaxRegimeSlabs) {
    if (taxable <= prevLimit) break;
    const currentLimit = slab.upTo != null ? slab.upTo : taxable;
    const taxableInChunk = Math.min(taxable, currentLimit) - prevLimit;
    if (taxableInChunk > 0) {
      tax += taxableInChunk * slab.rate;
    }
    if (slab.upTo == null) break;
    prevLimit = slab.upTo;
  }

  // Rebate under section 87A (limit is version-specific, e.g. ₹12L under the
  // revised slabs) — a zero tax bill below the rebate threshold.
  if (taxable <= rebateLimit) {
    tax = 0;
  }

  // Health and Education cess 4%
  const cess = Math.round(tax * 0.04);
  const totalAnnualTax = tax + cess;
  const monthlyTds = Math.round(totalAnnualTax / 12);

  return {
    statutoryVersion: { fy: version.fy, effectiveFrom: version.effectiveFrom, verified: version.verified === true },
    grossAnnualIncome: gross,
    taxableIncome: taxable,
    annualTax: totalAnnualTax,
    monthlyTds,
    cess,
  };
}

export default {
  calculatePf,
  calculateEsi,
  calculateGratuity,
  calculateTds,
  resolveStatutoryVersion,
  getStatutoryVersionMeta,
};

import crypto from 'node:crypto';
import mongoose from 'mongoose';
import SystemSetting from '../models/SystemSetting.js';
import { redisClient, isRedisReady } from '../config/redis.js';
import logger from '../config/logger.js';
import { ADMIT_LUA } from '../lib/admitLua.js';
import { securityFailOpenTotal } from '../lib/metrics.js';

/**
 * ADM-M-06 - per-tenant API quotas ("one tenant can starve the platform").
 *
 * Before this, every throttle keyed on USER or IP (rateLimit.js). A hospital
 * with N staff accounts therefore had N independent buckets, so a single
 * tenant could multiply its share of Mongo/Redis/Kafka until everyone else
 * degraded - no amount of per-user tuning closes that gap. This service adds
 * the missing AGGREGATE dimension: one sliding-window bucket per hospital,
 * enforced from `protect` so it covers every authenticated tenant request
 * without touching 130+ route files.
 *
 * Design constraints (deliberate):
 *   - FAIL-OPEN: a quota is an abuse/capacity control, not a security gate.
 *     Redis down must never lock a hospital out of its own data (unlike
 *     authLimiter, which fails closed because brute-force defence is a gate).
 *   - SOS paths bypass, mirroring the GRL limiters: life safety is never
 *     throttled, and only the PATH counts - client-supplied flags don't.
 *   - SUPERADMIN exempt: platform operators are not tenant traffic.
 *   - Config in SystemSetting (`tenantQuota:<hospitalId>`, `tenantQuota:default`)
 *     so overrides survive restarts without a new collection; the hot path
 *     reads an in-process cache and only touches Mongo when the connection is
 *     actually up (readyState gate keeps tests/offline boots on the default).
 */

export const DEFAULT_QUOTA = Object.freeze({ windowMs: 60_000, max: 1_000 });

// Bounds shared by the setter and the DB reader: a corrupt or hostile
// SystemSetting row can never turn into an unbounded or zero-length window.
const WINDOW_MIN_MS = 1_000;
const WINDOW_MAX_MS = 3_600_000;
const MAX_MIN = 1;
const MAX_MAX = 1_000_000;

const QUOTA_CACHE_TTL_MS = 30_000;
const DEFAULT_KEY = 'tenantQuota:default';

/** hospitalId -> { quota, source, expiresAt } */
const quotaCache = new Map();

export function _resetQuotaCache() {
  quotaCache.clear();
}

function normalizeQuota(value) {
  if (!value || typeof value !== 'object') return null;
  const windowMs = Number(value.windowMs);
  const max = Number(value.max);
  if (!Number.isFinite(windowMs) || windowMs < WINDOW_MIN_MS || windowMs > WINDOW_MAX_MS) return null;
  if (!Number.isInteger(max) || max < MAX_MIN || max > MAX_MAX) return null;
  return { windowMs, max };
}

function quotaKey(hospitalId) {
  return hospitalId === 'default' ? DEFAULT_KEY : `tenantQuota:${hospitalId}`;
}

/**
 * Cold-path DB read. Returns { quota, source } or null when nothing is
 * configured. readyState gate: mongoose buffers queries for 10s when offline
 * and then rejects - a quota lookup must never add that latency to `protect`.
 */
async function loadQuotaFromDb(hospitalId) {
  if (mongoose.connection.readyState !== 1) return null;
  try {
    const override = normalizeQuota(
      (await SystemSetting.findOne({ key: quotaKey(hospitalId) }).maxTimeMS(500).lean())?.value
    );
    if (override) return { quota: override, source: 'override' };
    if (hospitalId !== 'default') {
      const fallback = normalizeQuota(
        (await SystemSetting.findOne({ key: DEFAULT_KEY }).maxTimeMS(500).lean())?.value
      );
      if (fallback) return { quota: fallback, source: 'default' };
    }
  } catch (err) {
    // Availability again: a settings read failure degrades to the built-in
    // quota, it never fails the request.
    logger.warn(`tenant quota lookup failed for ${hospitalId}: ${err.message}. Using built-in default.`);
  }
  return null;
}

/** Effective quota for a tenant: cache -> SystemSetting -> built-in. */
export async function getQuota(hospitalId) {
  const cached = quotaCache.get(hospitalId);
  if (cached && cached.expiresAt > Date.now()) return cached.quota;

  const resolved = (await loadQuotaFromDb(hospitalId)) || { quota: DEFAULT_QUOTA, source: 'builtin' };
  quotaCache.set(hospitalId, { ...resolved, expiresAt: Date.now() + QUOTA_CACHE_TTL_MS });
  return resolved.quota;
}

/** Upsert an override; the cache is updated in-process so PUT takes effect on the next request. */
export async function setQuota(hospitalId, { windowMs, max }, updatedBy) {
  const quota = normalizeQuota({ windowMs, max });
  if (!quota) throw Object.assign(new Error('Invalid quota'), { statusCode: 400 });
  await SystemSetting.findOneAndUpdate(
    { key: quotaKey(hospitalId) },
    { value: quota, description: 'Per-tenant API request quota (ADM-M-06)', updatedBy, updatedAt: new Date() },
    { upsert: true, new: true }
  );
  if (hospitalId === 'default') {
    // Every cached tenant may be deriving from the default - drop them all.
    _resetQuotaCache();
  } else {
    quotaCache.set(hospitalId, { quota, source: 'override', expiresAt: Date.now() + QUOTA_CACHE_TTL_MS });
  }
  return quota;
}

/** Remove an override; the tenant falls back to default (or the built-in quota). */
export async function deleteQuota(hospitalId) {
  await SystemSetting.deleteOne({ key: quotaKey(hospitalId) });
  if (hospitalId === 'default') _resetQuotaCache();
  else quotaCache.delete(hospitalId);
}

/**
 * Live per-tenant usage from the actual counter keys (SCAN, never KEYS -
 * KEYS blocks Redis for the whole keyspace and this runs from an admin page).
 * Best-effort: Redis down -> empty usage object, quotas still listed.
 */
async function currentUsage() {
  const usage = {};
  if (!isRedisReady() || !redisClient.isOpen) return usage;
  try {
    for await (const batch of redisClient.scanIterator({ MATCH: 'rl:tenant:*', COUNT: 200 })) {
      const keys = Array.isArray(batch) ? batch : [batch];
      for (const key of keys) {
        const hospitalId = String(key).slice('rl:tenant:'.length);
        usage[hospitalId] = Number(await redisClient.zCard(key));
      }
    }
  } catch (err) {
    logger.warn(`tenant quota usage scan failed: ${err.message}`);
  }
  return usage;
}

/** Admin listing: platform default + every override + current window usage. */
export async function listQuotas() {
  let rows = [];
  if (mongoose.connection.readyState === 1) {
    try {
      rows = await SystemSetting.find({ key: { $regex: '^tenantQuota:' } }).lean();
    } catch (err) {
      logger.warn(`tenant quota listing failed: ${err.message}`);
    }
  }
  const defaultRow = rows.find((r) => r.key === DEFAULT_KEY);
  const overrides = rows
    .filter((r) => r.key !== DEFAULT_KEY)
    .map((r) => ({
      hospitalId: r.key.slice('tenantQuota:'.length),
      ...(normalizeQuota(r.value) || DEFAULT_QUOTA),
    }))
    .sort((a, b) => a.hospitalId.localeCompare(b.hospitalId));
  return {
    default: normalizeQuota(defaultRow?.value) || DEFAULT_QUOTA,
    defaultSource: defaultRow ? 'override' : 'builtin',
    overrides,
    usage: await currentUsage(),
  };
}

/**
 * The guard itself - the last thing `protect` calls before `next()`.
 *
 * Counts the request against `rl:tenant:<hospitalId>` with the SAME Lua
 * contract as the per-user limiters (>= at the cap, RL-01), then either
 * passes, or refuses with 429 TENANT_QUOTA_EXCEEDED + Retry-After.
 */
/** P2-15: opt-in fail-closed posture (TENANT_QUOTA_STRICT=true). */
const tenantQuotaStrict = () => /^(1|true|yes)$/i.test(String(process.env.TENANT_QUOTA_STRICT || ''));

/** Shared 503 for both strict-mode refusal paths. */
function refuseUnavailable(res) {
  res.setHeader('Retry-After', '30');
  return res.status(503).json({
    success: false,
    error: 'TENANT_QUOTA_UNAVAILABLE',
    message: 'Capacity control is temporarily unavailable. Please retry shortly.',
  });
}
export async function tenantQuotaGuard(req, res, next) {
  try {
    const hospitalId = req.user?.hospitalId;
    // Not tenant traffic: patients, platform staff, unlinked accounts.
    if (!hospitalId || req.user?.role === 'superadmin') return next();

    // Life-safety bypass - path only, never a body field (AUTH-006 rule).
    const url = req.originalUrl || req.url || '';
    if (url.includes('/emergency') || url.includes('/sos')) return next();

    // Fail-open: quota is capacity control, availability wins (see header).
    // F9: count it - a silent fail-open is indistinguishable from a healthy
    // one, and "how long were quotas unenforced?" must be graphable.
    if (!isRedisReady() || !redisClient.isOpen) {
      securityFailOpenTotal.inc({ control: 'tenant_quota' });
      // P2-15: default is the documented fail-open (quota = capacity control),
      // TENANT_QUOTA_STRICT=true flips it to 503 for deployments that would
      // rather refuse than run un-metered.
      if (tenantQuotaStrict()) {
        logger.warn('tenant quota guard: Redis unavailable and TENANT_QUOTA_STRICT set - failing closed');
        return refuseUnavailable(res);
      }
      return next();
    }

    const { windowMs, max } = await getQuota(hospitalId);
    const now = Date.now();
    const member = `${now}_${crypto.randomBytes(4).toString('hex')}`;

    const admitted = Number(await redisClient.eval(ADMIT_LUA, {
      keys: [`rl:tenant:${hospitalId}`],
      arguments: [String(now), String(windowMs), String(max), member],
    }));

    res.setHeader('X-TenantQuota-Limit', max);
    res.setHeader('X-TenantQuota-Remaining', Math.max(0, max - admitted));

    if (admitted >= max) {
      const retryAfterSeconds = Math.ceil(windowMs / 1000);
      res.setHeader('Retry-After', retryAfterSeconds);
      return res.status(429).json({
        success: false,
        error: 'TENANT_QUOTA_EXCEEDED',
        message: 'Hospital API quota exceeded. Contact the platform admin to raise the limit.',
        retryAfterSeconds,
      });
    }
    return next();
  } catch (err) {
    securityFailOpenTotal.inc({ control: 'tenant_quota' });
    if (tenantQuotaStrict()) {
      logger.warn(`tenant quota guard error: ${err.message}. TENANT_QUOTA_STRICT set - failing closed.`);
      return refuseUnavailable(res);
    }
    logger.warn(`tenant quota guard error: ${err.message}. Passing through.`);
    return next();
  }
}

import crypto from 'crypto';
import { constantTimeCompare, OTP_HASH_ALGO, ACTIVE_OTP_HASH_ALGO } from './napiOtpService.js';

const BACKUP_CODE_COUNT = 10;
const BACKUP_CODE_LENGTH = 10;

// RFC 4648 base32 alphabet — the encoding authenticator apps actually speak.
// (This file previously generated base32-SHAPED secrets but decoded them as
// base64 when computing the HMAC, so every authenticator-app code failed.
// See verifyToken/generateTOTP below for the fix.)
const BASE32_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';

/** RFC 4648 base32 encode (no padding — otpauth secrets omit it). */
function base32Encode(buffer) {
  let bits = 0;
  let value = 0;
  let output = '';
  for (const byte of buffer) {
    value = (value << 8) | byte;
    bits += 8;
    while (bits >= 5) {
      output += BASE32_ALPHABET[(value >>> (bits - 5)) & 31];
      bits -= 5;
    }
  }
  if (bits > 0) output += BASE32_ALPHABET[(value << (5 - bits)) & 31];
  return output;
}

/** RFC 4648 base32 decode. Throws on characters outside the alphabet. */
export function base32Decode(secret) {
  const clean = String(secret || '').toUpperCase().replace(/[\s=]+/g, '');
  if (!clean) throw new Error('Empty TOTP secret');
  let bits = 0;
  let value = 0;
  const bytes = [];
  for (const char of clean) {
    const index = BASE32_ALPHABET.indexOf(char);
    if (index === -1) throw new Error('Invalid base32 character in TOTP secret');
    value = (value << 5) | index;
    bits += 5;
    if (bits >= 8) {
      bytes.push((value >>> (bits - 8)) & 0xff);
      bits -= 8;
    }
  }
  return Buffer.from(bytes);
}

/**
 * Generate a TOTP-compatible secret for authenticator apps.
 * 20 random bytes (160-bit key, RFC 4226 recommendation) base32-encoded —
 * ready to drop straight into an otpauth:// URL.
 */
export function generateSecret() {
  return base32Encode(crypto.randomBytes(20));
}

/**
 * Generate the otpauth:// URL for QR code
 * @param {string} secret - Base32 secret
 * @param {string} email - User email (for label)
 * @param {string} issuer - App name
 */
export function generateOtpAuthUrl(secret, email, issuer = 'FindMedi') {
  return `otpauth://totp/${encodeURIComponent(issuer)}:${encodeURIComponent(email)}?secret=${secret}&issuer=${encodeURIComponent(issuer)}&algorithm=SHA1&digits=6&period=30`;
}

/**
 * Verify a TOTP token against the secret
 * Uses time-based window of +/- 30 seconds to account for clock drift
 * @param {string} token - 6-digit code from authenticator app
 * @param {string} secret - Base32 secret
 * @returns {boolean}
 */
export function verifyToken(token, secret) {
  if (!token || !secret) return false;
  if (!/^\d{6}$/.test(token)) return false;

  const timeStep = 30; // seconds
  const currentTime = Math.floor(Date.now() / 1000);
  const currentCounter = Math.floor(currentTime / timeStep);

  try {
    // Check current, previous, and next counter (3 windows) with a
    // constant-time comparison so a timing side-channel can't narrow guesses.
    for (let offset = -1; offset <= 1; offset++) {
      const counter = currentCounter + offset;
      const expected = generateTOTP(secret, counter);
      if (constantTimeCompare(expected, token)) return true;
    }
  } catch {
    // Malformed stored secret (not valid base32) → treat as not verified
    // instead of throwing a 500 out of the login path.
    return false;
  }
  return false;
}

/**
 * Generate TOTP code for a given counter.
 * Implements RFC 6238 / RFC 4226 (exported for tests).
 */
export function generateTOTP(secret, counter) {
  // HMAC-SHA1 as per the TOTP standard. The secret from
  // generateSecret/generateOtpAuthUrl is BASE32 — decoding it as base64 here
  // (the previous behaviour) produced a different key than every authenticator
  // app derives, so no code ever matched.
  const decodedSecret = base32Decode(secret);
  const counterBuffer = Buffer.alloc(8);
  for (let i = 7; i >= 0; i--) {
    counterBuffer[i] = counter & 0xff;
    counter >>>= 8;
  }

  const hmac = crypto.createHmac('sha1', decodedSecret).update(counterBuffer).digest();
  const offset = hmac[hmac.length - 1] & 0xf;
  const binary = (
    ((hmac[offset] & 0x7f) << 24) |
    ((hmac[offset + 1] & 0xff) << 16) |
    ((hmac[offset + 2] & 0xff) << 8) |
    (hmac[offset + 3] & 0xff)
  );

  const otp = binary % 1000000;
  return String(otp).padStart(6, '0');
}

/**
 * Generate backup codes for recovery
 * @returns {string[]} Array of backup codes
 */
export function generateBackupCodes() {
  const codes = [];
  for (let i = 0; i < BACKUP_CODE_COUNT; i++) {
    const code = crypto.randomBytes(BACKUP_CODE_LENGTH)
      .toString('hex')
      .toUpperCase()
      .slice(0, BACKUP_CODE_LENGTH);
    codes.push(code);
  }
  return codes;
}

/**
 * Hash a backup code for storage
 * @param {string} code
 * @returns {string}
 */
export function hashBackupCode(code) {
  return crypto.createHash('sha256').update(code).digest('hex');
}

/**
 * Verify a backup code against hashed codes
 * @param {string} code - User-provided backup code
 * @param {string[]} hashedCodes - Stored hashed codes
 * @returns {{ valid: boolean, codeIndex: number }}
 */
export function verifyBackupCode(code, hashedCodes) {
  if (!code || !hashedCodes?.length) return { valid: false, codeIndex: -1 };
  const hashed = hashBackupCode(code.toUpperCase());

  // Explicit contract: native constant-time compare is available exactly
  // when the active OTP hash backend is Rust ('rust-sha256').
  // Same behavior as the former implicit NATIVE_OTP_AVAILABLE check.
  if (ACTIVE_OTP_HASH_ALGO === OTP_HASH_ALGO.RUST_SHA256) {
    let found = false;
    let foundIndex = -1;
    hashedCodes.forEach((stored, i) => {
      if (constantTimeCompare(hashed, stored)) {
        found = true;
        foundIndex = i;
      }
    });
    return { valid: found, codeIndex: foundIndex };
  }

  const index = hashedCodes.indexOf(hashed);
  return { valid: index !== -1, codeIndex: index };
}

/**
 * PAY-B-06: one shared, mandatory webhook verification path.
 *
 * The finding was not "webhook.js is insecure" — it is that there was no SINGLE
 * definition of "a verified webhook", so each provider route re-implemented it and
 * the easy-to-get-wrong parts (raw body, constant-time compare, replay window,
 * replay cache) were opt-in. This module makes them the default and reusable.
 *
 * The four properties, in order:
 *   1. RAW BODY      — HMAC is computed over the exact bytes received. Any
 *       re-serialisation of the parsed body changes the bytes and breaks the
 *       signature.
 *   2. CONSTANT TIME — timingSafeEqual, so a byte-at-a-time oracle cannot recover
 *       the expected digest.
 *   3. TIMESTAMP     — MANDATORY. A signature older than WINDOW_SECONDS is
 *       rejected, and a MISSING timestamp is rejected too: without it the window
 *       means nothing and a captured event can be replayed forever.
 *   4. REPLAY CACHE  — the same signature inside the window is accepted ONCE.
 *       (3) alone still allows a replay inside the window, and (4) degrades to a
 *       no-op when Redis is absent — hence the fail-closed switch.
 *
 * Fails CLOSED: a missing secret is a 503, never an accept.
 */
import crypto from 'crypto';
import logger from '../config/logger.js';
import { redisClient, isRedisReady } from '../config/redis.js';

/** 5 minutes is the usual gateway tolerance; anything older is a capture. */
export const WEBHOOK_WINDOW_SECONDS = Number(process.env.WEBHOOK_WINDOW_SECONDS || 300);

/**
 * Whether an unavailable replay cache should REJECT the event.
 *
 * The trade-off is explicit rather than implicit:
 *   * production (or REQUIRE_WEBHOOK_REPLAY_PROTECTION=true) -> reject.
 *     A Redis outage must not silently remove replay protection; an operator
 *     capturing a legitimate webhook and replaying it inside the window is
 *     exactly the attack this cache exists to stop, and the HMAC check does not
 *     catch it.
 *   * development -> warn and accept, so a developer without Redis can still work
 *     on the webhook path.
 */
export const requireReplayProtection = () =>
  process.env.REQUIRE_WEBHOOK_REPLAY_PROTECTION === 'true'
  || process.env.NODE_ENV === 'production';

export const verifyWebhook = (providerOrResolver, {
  secretEnv = null,
  resolveSecret = null,
  signatureHeaders = ['x-signature', 'x-hub-signature-256', 'x-razorpay-signature'],
  timestampHeaders = ['x-webhook-timestamp', 'x-signature-timestamp', 'x-timestamp'],
  algorithm = 'sha256',
  windowSeconds = WEBHOOK_WINDOW_SECONDS,
  prefix = 'webhook',
  requireReplayCache = requireReplayProtection(),
} = {}) => async (req, res, next) => {
  const provider = typeof providerOrResolver === 'function'
    ? providerOrResolver(req)
    : providerOrResolver;

  // Either a fixed WEBHOOK_SECRET_<PROVIDER> env var, or a resolver for routes
  // where the provider is a path segment (e.g. /webhooks/:provider).
  const secret = resolveSecret
    ? resolveSecret(req, provider)
    : process.env[secretEnv || `WEBHOOK_SECRET_${String(provider).toUpperCase()}`];

  if (!secret) {
    logger.error(`Webhook secret for ${provider} is not configured — refusing the callback`);
    return res.status(503).json({ error: 'Webhook provider not configured' });
  }

  const raw = Buffer.isBuffer(req.body) ? req.body : Buffer.from(req.body || '');
  const provided = signatureHeaders.map((h) => req.headers[h]).find(Boolean);

  if (!provided) {
    logger.warn(`Webhook for ${provider} had no signature header`);
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // The timestamp is part of the signed material; accept `ts.digest` (some
  // gateways) or a separate timestamp header.
  const tsHeader = timestampHeaders.map((h) => req.headers[h]).find(Boolean);
  let timestamp = tsHeader ? Number(tsHeader) : null;
  let signature = provided;

  if (provided.includes('.')) {
    const [maybeTs, maybeSig] = provided.split('.', 2);
    if (/^\d+$/.test(maybeTs)) {
      timestamp = Number(maybeTs);
      signature = maybeSig;
    }
  }

  const signedPayload = Buffer.concat([Buffer.from(`${timestamp}.`, 'utf8'), raw]);

  // A missing timestamp is a FAILURE, not a pass.
  //
  // `if (timestamp !== null)` meant a provider that simply omits the header got
  // an unlimited-lifetime signature: capture one valid webhook, and replay it
  // forever. The freshness window is only meaningful if the timestamp is
  // MANDATORY — an absent timestamp is indistinguishable from an attacker
  // stripping it.
  if (timestamp === null || !Number.isFinite(timestamp)) {
    logger.warn(`Webhook for ${provider} arrived without a usable timestamp`);
    return res.status(401).json({ error: 'Missing timestamp' });
  }

  const ageSeconds = Math.abs(Math.floor(Date.now() / 1000) - timestamp);
  if (ageSeconds > windowSeconds) {
    logger.warn(`Webhook for ${provider} outside the ${windowSeconds}s window (age ${ageSeconds}s)`);
    return res.status(401).json({ error: 'Expired signature' });
  }

  const expected = crypto.createHmac(algorithm, secret).update(signedPayload).digest('hex');
  if (!constantTimeEqual(signature, expected)) {
    logger.warn(`Invalid webhook signature for ${provider}`);
    return res.status(401).json({ error: 'Invalid signature' });
  }

// Replay cache: the signature is single-use inside the window.
  const replayKey = `${prefix}:${provider}:${crypto.createHash('sha256').update(String(signature)).digest('hex')}`;
  try {
    if (isRedisReady() && redisClient.isOpen) {
      const firstUse = await redisClient.set(replayKey, '1', { EX: windowSeconds + 60, NX: true });
      if (firstUse !== 'OK') {
        logger.warn(`Replayed webhook signature rejected for ${provider}`);
        return res.status(401).json({ error: 'Replayed signature' });
      }
    } else if (requireReplayCache) {
      logger.error(
        `Webhook replay protection unavailable for ${provider} and `
        + 'REQUIRE_WEBHOOK_REPLAY_PROTECTION is set — refusing the event.'
      );
      return res.status(503).json({ error: 'Webhook verification temporarily unavailable' });
    } else {
      logger.warn(
        `Webhook replay cache not active for ${provider}. The HMAC was verified, but `
        + `a captured event could be replayed inside the ${windowSeconds}s window. `
        + 'Set REDIS_URL, or REQUIRE_WEBHOOK_REPLAY_PROTECTION=true to fail closed.'
      );
    }
  } catch (err) {
    // An exception is an outage, and an outage must not mean "accept everything".
    logger.error(`Webhook replay cache error for ${provider}: ${err.message}`);
    if (requireReplayCache) {
      return res.status(503).json({ error: 'Webhook verification temporarily unavailable' });
    }
  }

  req.webhook = { provider, raw, verifiedAt: new Date() };
  return next();
};

/**
 * PAY-B-06: freshness + single-use check for a caller that has already verified
 * the HMAC itself (e.g. a route that resolves its secret dynamically).
 *
 * @returns {{ ok: true } | { ok: false, reason: string }}
 */
export async function assertWebhookFresh(req, {
  windowSeconds = WEBHOOK_WINDOW_SECONDS,
  provider = 'webhook',
  timestampHeaders = ['x-webhook-timestamp', 'x-signature-timestamp', 'x-timestamp'],
  signatureHeaders = ['x-signature', 'x-hub-signature-256', 'x-razorpay-signature'],
  prefix = 'webhook',
  // Same default as verifyWebhook: production fails closed.
  requireReplayCache = requireReplayProtection(),
} = {}) {
  const tsHeader = timestampHeaders.map((h) => req.headers?.[h]).find(Boolean);
  let timestamp = tsHeader ? Number(tsHeader) : null;
  let signature = signatureHeaders.map((h) => req.headers?.[h]).find(Boolean);

  // `ts.digest` form (several gateways): the timestamp is inside the signature.
  if (signature?.includes('.')) {
    const [maybeTs, maybeSig] = signature.split('.', 2);
    if (/^\d+$/.test(maybeTs)) {
      timestamp = Number(maybeTs);
      signature = maybeSig;
    }
  }

  // Same rule as verifyWebhook: a missing timestamp is a FAILURE.
  //
  // `if (timestamp !== null && ...)` meant a caller that verifies the HMAC itself
  // and forgets to send a timestamp got an unlimited-lifetime verdict — the same
  // replay exposure, in the sibling entry point. Fixing only the middleware would
  // have left a second door open.
  if (timestamp === null || !Number.isFinite(timestamp)) {
    logger.warn(`Webhook for ${provider} arrived without a usable timestamp`);
    return { ok: false, reason: 'missing-timestamp' };
  }

  const ageSeconds = Math.abs(Math.floor(Date.now() / 1000) - timestamp);
  if (ageSeconds > windowSeconds) return { ok: false, reason: 'expired' };

  if (signature) {
    const replayKey = `${prefix}:${provider}:${crypto.createHash('sha256').update(String(signature)).digest('hex')}`;
    try {
      if (isRedisReady() && redisClient.isOpen) {
        const firstUse = await redisClient.set(replayKey, '1', { EX: windowSeconds + 60, NX: true });
        if (firstUse !== 'OK') return { ok: false, reason: 'replayed' };
      } else if (requireReplayCache) {
        logger.error(
          `Webhook replay protection unavailable for ${provider} and `
          + 'REQUIRE_WEBHOOK_REPLAY_PROTECTION is set — refusing the event.'
        );
        return { ok: false, reason: 'replay-cache-unavailable' };
      } else {
        logger.warn(
          `Webhook replay cache not active for ${provider}. The HMAC was verified, but `
          + `a captured event could be replayed inside the ${windowSeconds}s window.`
        );
      }
    } catch (err) {
      logger.error(`Webhook replay cache error for ${provider}: ${err.message}`);
      if (requireReplayCache) return { ok: false, reason: 'replay-cache-unavailable' };
    }
  }

  return { ok: true };
}

/**
 * Length-checked constant-time comparison. `timingSafeEqual` throws on a length
 * mismatch, so the lengths are compared first (that check leaks only the length).
 */
export function constantTimeEqual(a, b) {
  const given = Buffer.from(String(a ?? ''), 'utf8');
  const want = Buffer.from(String(b ?? ''), 'utf8');
  if (given.length !== want.length) return false;
  return crypto.timingSafeEqual(given, want);
}

