import sharp from 'sharp';
import path from 'path';
import fs from 'fs';
import { fileURLToPath } from 'url';
import { v4 as uuidv4 } from 'uuid';
import {
  resizeImage as napiResizeImage,
  resizeToFit as napiResizeToFit,
  getImageInfo as napiGetImageInfo,
  NATIVE_AVAILABLE,
} from '../services/napiImageService.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const ALLOWED_IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
const ALLOWED_DOCUMENT_TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];
const MAX_IMAGE_SIZE = 10 * 1024 * 1024;
const MAX_DOCUMENT_SIZE = 25 * 1024 * 1024;

const getUploadDir = (subDir = '') => {
  const baseDir = path.join(__dirname, '..', '..', 'public', 'uploads', subDir);
  if (!fs.existsSync(baseDir)) {
    fs.mkdirSync(baseDir, { recursive: true });
  }
  return baseDir;
};

export const validateFile = (file, type = 'image') => {
  const allowedTypes = type === 'image' ? ALLOWED_IMAGE_TYPES : ALLOWED_DOCUMENT_TYPES;
  const maxSize = type === 'image' ? MAX_IMAGE_SIZE : MAX_DOCUMENT_SIZE;

  if (!allowedTypes.includes(file.mimetype)) {
    return { valid: false, error: `Invalid file type. Allowed: ${allowedTypes.join(', ')}` };
  }

  if (file.size > maxSize) {
    return { valid: false, error: `File too large. Max size: ${maxSize / 1024 / 1024}MB` };
  }

  return { valid: true };
};

export const processAndSaveImage = async (file, options = {}) => {
  const {
    width = 800,
    height = 800,
    quality = 80,
    format = 'jpeg',
    outputDir = 'images',
  } = options;

  const uploadDir = getUploadDir(outputDir);
  const ext = format === 'jpg' ? 'jpeg' : format;
  const filename = `${uuidv4()}.${ext}`;
  const filepath = path.join(uploadDir, filename);

  let buffer;

  // Use native Rust resize for JPEG output (faster than Sharp)
  if ((format === 'jpeg' || format === 'jpg') && NATIVE_AVAILABLE) {
    buffer = napiResizeToFit(file.buffer, width, height, quality);
  } else {
    // Fallback to Sharp (also handles PNG/WebP with quality control)
    let pipeline = sharp(file.buffer)
      .resize(width, height, { fit: 'inside', withoutEnlargement: true });

    if (format === 'jpeg' || format === 'jpg') {
      pipeline = pipeline.jpeg({ quality });
    } else if (format === 'png') {
      pipeline = pipeline.png({ quality: Math.min(quality, 100) });
    } else if (format === 'webp') {
      pipeline = pipeline.webp({ quality });
    }

    buffer = await pipeline.toBuffer();
  }

  await fs.promises.writeFile(filepath, buffer);

  return {
    filename,
    filepath: `/uploads/${outputDir}/${filename}`,
    originalName: file.originalname,
    size: buffer.length,
    width,
    height,
    format,
  };
};

export const compressImage = async (file, options = {}) => {
  const { quality = 70, format = 'jpeg' } = options;

  const uploadDir = getUploadDir('compressed');
  const filename = `compressed-${uuidv4()}.${format}`;
  const filepath = path.join(uploadDir, filename);

  let buffer;

  // Use native Rust resize for JPEG output
  if ((format === 'jpeg' || format === 'jpg') && NATIVE_AVAILABLE) {
    const info = napiGetImageInfo(file.buffer);
    const targetW = Math.min(info.width, 4096);
    const targetH = Math.min(info.height, 4096);
    buffer = napiResizeImage(file.buffer, targetW, targetH, quality);
  } else {
    let pipeline = sharp(file.buffer);

    if (format === 'jpeg' || format === 'jpg') {
      pipeline = pipeline.jpeg({ quality });
    } else if (format === 'png') {
      pipeline = pipeline.png({ compressionLevel: 9 });
    } else if (format === 'webp') {
      pipeline = pipeline.webp({ quality });
    }

    buffer = await pipeline.toBuffer();
  }

  await fs.promises.writeFile(filepath, buffer);

  return {
    filename,
    filepath: `/uploads/compressed/${filename}`,
    size: buffer.length,
  };
};

export const generateThumbnail = async (file, size = 150) => {
  const uploadDir = getUploadDir('thumbnails');
  const filename = `thumb-${uuidv4()}.jpg`;
  const filepath = path.join(uploadDir, filename);

  let buffer;

  // Use native Rust resize for JPEG thumbnails (exact resize, faster)
  if (NATIVE_AVAILABLE) {
    buffer = napiResizeImage(file.buffer, size, size, 60);
  } else {
    buffer = await sharp(file.buffer)
      .resize(size, size, { fit: 'cover' })
      .jpeg({ quality: 60 })
      .toBuffer();
  }

  await fs.promises.writeFile(filepath, buffer);

  return {
    filename,
    filepath: `/uploads/thumbnails/${filename}`,
    size: buffer.length,
  };
};

export const getImageMetadata = async (file) => {
  // Use native Rust image info when available (faster, no dependency on Sharp)
  if (NATIVE_AVAILABLE) {
    try {
      const info = napiGetImageInfo(file.buffer);
      return {
        width: info.width,
        height: info.height,
        format: info.format.toLowerCase(),
        size: file.size,
        hasAlpha: info.format.toLowerCase() !== 'jpeg', // JPEG doesn't support alpha
      };
    } catch {
      // Fall through to Sharp if Rust fails (e.g. unsupported format)
    }
  }

  const metadata = await sharp(file.buffer).metadata();
  return {
    width: metadata.width,
    height: metadata.height,
    format: metadata.format,
    size: file.size,
    hasAlpha: metadata.hasAlpha,
  };
};

export const convertToJPEG = async (file) => {
  const uploadDir = getUploadDir('converted');
  const filename = `converted-${uuidv4()}.jpeg`;
  const filepath = path.join(uploadDir, filename);

  let buffer;

  // Use native Rust for JPEG conversion
  if (NATIVE_AVAILABLE) {
    const info = napiGetImageInfo(file.buffer);
    buffer = napiResizeImage(file.buffer, info.width, info.height, 90);
  } else {
    buffer = await sharp(file.buffer)
      .jpeg({ quality: 90 })
      .toBuffer();
  }

  await fs.promises.writeFile(filepath, buffer);

  return {
    filename,
    filepath: `/uploads/converted/${filename}`,
    size: buffer.length,
  };
};

export const deleteFile = async (filepath) => {
  const fullPath = path.join(process.cwd(), 'public', filepath);
  if (fs.existsSync(fullPath)) {
    fs.unlinkSync(fullPath);
    return true;
  }
  return false;
};

export const processMedicalFile = async (file, type = 'image') => {
  const validation = validateFile(file, type);
  if (!validation.valid) {
    throw new Error(validation.error);
  }

  if (type === 'image') {
    return processAndSaveImage(file, { width: 1200, height: 1200, quality: 85 });
  } else if (type === 'xray') {
    return processAndSaveImage(file, { width: 1920, height: 1920, quality: 90, format: 'png' });
  } else if (type === 'document') {
    const uploadDir = getUploadDir('documents');
    const ext = path.extname(file.originalname);
    const filename = `${uuidv4()}${ext}`;
    const filepath = path.join(uploadDir, filename);

    fs.writeFileSync(filepath, file.buffer);

    return {
      filename,
      filepath: `/uploads/documents/${filename}`,
      originalName: file.originalname,
      size: file.size,
    };
  }
};

import jwt from 'jsonwebtoken';
import crypto from 'node:crypto';
import logger from '../config/logger.js';

/**
 * AUTH-M-06: signing keys with `kid`, and a rotation window.
 *
 * THE PROBLEM THIS SOLVES
 * `JWT_SECRET` was read directly in six places across three files. Rotating it
 * meant editing all of them, and the moment the env var changed, EVERY token in
 * the wild failed verification at once - every user on the platform logged out,
 * with no overlap. There was no `kid` in the header, so a verifier had no way to
 * know which key a token was signed with even if two were live.
 *
 * THE MODEL
 * A keyset, not a secret. `JWT_KEYS` is a JSON array:
 *
 *   JWT_KEYS=[{"kid":"k2","secret":"...","status":"active"},
 *             {"kid":"k1","secret":"...","status":"retiring"}]
 *
 * - `active`   - signs new tokens. Exactly one.
 * - `retiring` - still VERIFIES, signs nothing. This is the overlap window: a
 *                key can be retired, kept for as long as the longest-lived
 *                token signed with it (15 days for refresh), and only then
 *                dropped. Rotation becomes a no-op for existing sessions.
 * - absent     - anything else. A token whose `kid` matches no known key is
 *                REJECTED rather than falling back, because "fall back to the
 *                default secret" is exactly the downgrade an attacker wants.
 *
 * With no JWT_KEYS set, this degrades to a single key derived from JWT_SECRET
 * with a fixed kid, so behaviour is unchanged for every existing deployment and
 * no migration is required.
 *
 * KEYS ARE NOT LOGGED. `describeKeyset()` returns ids and status only.
 */

const LEGACY_KID = 'default';

/**
 * TOKEN PURPOSE (AUTH-F-02).
 *
 * `typ` separates "prove who you are for one request" (access, 15 min) from
 * "prove you still hold the rotating session secret" (refresh, 7 d). Before
 * this, both were the same shape of JWT signed by the same keyset, and
 * `protect` only checked the signature + `id` + `tv` - so a LEAKED REFRESH
 * TOKEN was a valid 7-day access token that bypassed the whole 15-minute
 * expiry design.
 *
 * The rules are written so a token minted BEFORE this module change still
 * works for its own purpose (see verifyAccessToken): a legacy access token
 * carries neither `typ` nor `family`, a legacy refresh token always carries
 * `family` (signRefreshToken has set it from day one).
 */
export const ACCESS_TOKEN_TYP = 'access';
export const REFRESH_TOKEN_TYP = 'refresh';

// Issued on every NEW token (legacy tokens predate these and pass the
// tolerant check below for one rotation window).
export const ISSUER = 'findmedi';
export const AUDIENCE = 'findmedi-api';

let cache = null;

/** @returns {Array<{kid:string, secret:string, status:'active'|'retiring'}>} */
export function loadKeyset() {
  if (cache) return cache;

  const raw = process.env.JWT_KEYS;
  if (!raw) {
    const secret = process.env.JWT_SECRET || '';
    cache = secret ? [{ kid: LEGACY_KID, secret, status: 'active' }] : [];
    return cache;
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    // Refuse to start signing on a keyset we cannot read. Falling back to
    // JWT_SECRET here would silently downgrade a configured rotation policy to a
    // single key, which is the failure this module exists to prevent.
    logger.error(`JWT_KEYS is not valid JSON - refusing to fall back to JWT_SECRET: ${err.message}`);
    throw new Error('JWT_KEYS is not valid JSON', { cause: err });
  }

  if (!Array.isArray(parsed) || parsed.length === 0) {
    logger.error('JWT_KEYS must be a non-empty JSON array of {kid, secret, status}');
    throw new Error('JWT_KEYS must be a non-empty array');
  }

  const seen = new Set();
  const active = [];
  for (const k of parsed) {
    if (!k?.kid || !k?.secret) {
      logger.error(`JWT_KEYS entry missing kid or secret: ${JSON.stringify(Object.keys(k || {}))}`);
      throw new Error('JWT_KEYS entry missing kid or secret');
    }
    if (seen.has(k.kid)) {
      logger.error(`JWT_KEYS contains duplicate kid "${k.kid}"`);
      throw new Error('JWT_KEYS contains duplicate kid');
    }
    seen.add(k.kid);
    active.push({ kid: k.kid, secret: k.secret, status: k.status === 'retiring' ? 'retiring' : 'active' });
  }

  const activeCount = active.filter((k) => k.status === 'active').length;
  if (activeCount !== 1) {
    // Two active keys means "which one signs?" is ambiguous. Zero means nothing
    // can be issued at all.
    logger.error(`JWT_KEYS must have exactly one active key, found ${activeCount}`);
    throw new Error(`JWT_KEYS must have exactly one active key, found ${activeCount}`);
  }

  cache = active;
  return cache;
}

/** Test hook: forget the parsed keyset so a new env takes effect. */
export function resetKeysetCache() {
  cache = null;
}

const activeKey = () => loadKeyset().find((k) => k.status === 'active');

/** Operational view - safe to log. Never returns secret material. */
export function describeKeyset() {
  return loadKeyset().map((k) => ({ kid: k.kid, status: k.status, fingerprint: crypto.createHash('sha256').update(k.secret).digest('hex').slice(0, 12) }));
}

export const currentKid = () => activeKey()?.kid || null;

/**
 * Sign with the active key and stamp `kid` into the header.
 *
 * `jsonid` (RFC 7519) is generated here rather than in each caller, so a token
 * always has an id to trace and the refresh-rotation `jti` chain has something
 * to hang off.
 */
export function signToken(payload, options = {}) {
  const key = activeKey();
  if (!key) throw new Error('No active signing key');
  return jwt.sign(
    { jti: crypto.randomUUID(), iss: ISSUER, aud: AUDIENCE, ...payload },
    key.secret,
    // AUTH hardening: pin the algorithm LAST so neither a caller option nor a
    // poisoned payload spread can mint an `none`/asymmetric token.
    { ...options, keyid: key.kid, algorithm: 'HS256' }
  );
}

/**
 * Issuer/audience, checked TOLERANTLY: a token that carries them must match,
 * a token that predates them (no `iss` claim) passes. Rejecting the absent
 * claim would log out every live session the moment this ships; accepting a
 * WRONG one would make `iss`/`aud` decorative.
 */
const assertIssuerAudience = (payload) => {
  if (payload.iss != null && payload.iss !== ISSUER) {
    throw new Error('Invalid token issuer');
  }
  if (payload.aud != null && payload.aud !== AUDIENCE) {
    throw new Error('Invalid token audience');
  }
  return payload;
};

/**
 * AUTH hardening: algorithms pinned to HS256 — jsonwebtoken must never be
 * steered by the token's own header (alg:none / RS256-confusion), and
 * `clockTolerance: 5` absorbs ≤5s of skew between NTP-synced nodes without
 * turning into an open expiry window.
 */
const VERIFY_OPTIONS = { algorithms: ['HS256'], clockTolerance: 5 };

/**
 * Verify against the key named in the token's own header.
 *
 * Throws on unknown kid - deliberately. The alternative (try every key) turns a
 * compromised retired key into a permanent forgery oracle for anything it ever
 * signed, and makes key removal impossible to audit.
 */
export function verifyToken(token) {
  const decoded = jwt.decode(token, { complete: true });
  const kid = decoded?.header?.kid;
  // No throw on a missing kid. The migration contract below (and the raw
  // verify that AUTH-F-01 replaced) accepts a token signed directly with
  // JWT_SECRET; rejecting it here would make the `|| !kid` fallback dead
  // code, contradict this module's own comments, and 401 every token minted
  // before kid stamping the moment auth.js switched to verifyAccessToken.
  const key = kid ? loadKeyset().find((k) => k.kid === kid) : undefined;

  // Zero-downtime migration path. Tokens minted BEFORE this module existed were
  // signed with the bare JWT_SECRET and carry no kid, so their header decodes to
  // undefined above - but if JWT_KEYS is now configured, falling through to
  // "unknown kid" would reject every live session the instant an operator set
  // the env var. That is a self-inflicted mass logout, discovered in
  // production, by the act of rotating a key.
  //
  // Only for a token with NO kid, and only against JWT_SECRET. A token that
  // CLAIMS some other kid is never given the legacy fallback: claiming a kid you
  // do not hold the secret for must fail, or `kid` becomes advisory.
  // A token with no kid at all predates this module; one with kid=LEGACY_KID was
  // minted by this module running WITHOUT JWT_KEYS, which is the same situation
  // from the verifier's point of view and was caught by the first version of
  // this function testing only `!kid`.
  if (!key && (kid === LEGACY_KID || !kid) && process.env.JWT_SECRET) {
    return assertIssuerAudience(jwt.verify(token, process.env.JWT_SECRET, VERIFY_OPTIONS));
  }

  if (!key) {
    throw new Error(kid ? `Unknown kid "${kid}"` : 'Token has no kid header');
  }
  return assertIssuerAudience(jwt.verify(token, key.secret, VERIFY_OPTIONS));
}

/**
 * THE access-token gate. Every authenticated request path verifies through
 * here (protect, optionalProtect, /uploads, socket handshake, the optional
 * admin checks in doctors/facilities/hospitals, mind-support room joins) -
 * never through a bare `jwt.verify(token, JWT_SECRET)`, which cannot rotate
 * keys and accepts a refresh token as if it were an access token.
 *
 * Purpose rules:
 *   - `typ` present and not 'access'  -> reject (refresh presented as access).
 *   - `typ` absent AND `family` present -> reject. That is a legacy refresh
 *     token (pre-`typ`), and it must not reach a data endpoint.
 *   - `typ` absent, no `family`       -> legacy access token; allowed.
 */
export function verifyAccessToken(token) {
  const payload = verifyToken(token);
  if (payload.typ != null && payload.typ !== ACCESS_TOKEN_TYP) {
    throw new Error('Token is not an access token');
  }
  if (payload.typ == null && payload.family != null) {
    throw new Error('Refresh token presented as access token');
  }
  return payload;
}

/**
 * THE refresh-token gate, used only by POST /auth/refresh (and the two
 * session-listing routes that read a refresh cookie's `jti`).
 *
 *   - no `family` -> it is an access token; an access token must not be able
 *     to mint a new 7-day session (that would defeat rotation entirely).
 *   - `typ` present and not 'refresh' -> reject.
 */
export function verifyRefreshToken(token) {
  const payload = verifyToken(token);
  if (payload.family == null) {
    throw new Error('Access token presented as refresh token');
  }
  if (payload.typ != null && payload.typ !== REFRESH_TOKEN_TYP) {
    throw new Error('Token is not a refresh token');
  }
  return payload;
}

export { LEGACY_KID };

/**
 * PAY-M-06: the money rounding policy.
 *
 * Before this file there was no policy at all. `createPaymentSchema` accepted
 * any positive number, `Payment.create({...req.body})` stored it verbatim, and
 * a value like `0.1 + 0.2` could sit in an invoice total as
 * 0.30000000000000004 - unnoticed until it failed to reconcile against the
 * ledger.
 *
 * WHY MULTIPLY-THEN-ROUND RATHER THAN `Number.toFixed(2)`
 * ------------------------------------------------------
 * Two reasons, and the second is the one that actually matters:
 *
 * 1. `toFixed` returns a STRING. Money that has to be added up needs to come
 *    back as a number, and Number(x.toFixed(2)) is the same arithmetic with an
 *    extra parse in the middle.
 *
 * 2. It is the same operation `toPaise` in ledgerService already performs, so
 *    the whole codebase has ONE rounding convention. Two conventions that each
 *    look reasonable is how a commission line and a payout line end up one
 *    paisa apart.
 *
 * Note this is deliberately NOT advertised as "correct half-up rounding".
 * `(1.005).toFixed(2)` is '1.00' and roundRupees(1.005) is also 1 - IEEE-754
 * simply does not represent 1.005 exactly, and no amount of rounding fixes
 * that. What this DOES guarantee is that a stored money value never carries a
 * third decimal: the float noise is absorbed at the write boundary instead of
 * accumulating across writes.
 *
 * Rounding to 2dp (one paisa) is the storage precision. Arithmetic still
 * happens in integer paise where it matters - see ledgerService - but every
 * value that reaches the database is at most one paisa wide.
 */

/** @param {unknown} value @returns {number} rupees at 2dp, or 0 for non-numbers */
export function roundRupees(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.round(n * 100) / 100;
}

/** Same policy, expressed as an integer count of paise. */
export function toPaise(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.round(n * 100);
}

/** Inverse of `toPaise`: an integer-paisa count back to rupees at 2dp. */
export function fromPaise(paise) {
  return Math.round(Number(paise) || 0) / 100;
}

/**
 * Mongoose plugin: round the named fields at write time.
 *
 * Both document saves AND query updates are covered on purpose. Covering only
 * `validate` would leave `Payment.updateOne({ $set: { amount } })` - the path
 * an admin correction takes - writing unrounded floats, and a policy that
 * holds for half the writes is not a policy.
 */
/** A value worth rounding (not undefined/null/empty-string). */
const isSet = (v) => v !== undefined && v !== null && v !== '';

/**
 * Field specs are strings, either:
 *   'amount'               - a top-level path
 *   'services[].price'     - the same field on EVERY element of an array
 *
 * The array form exists because the money that actually gets added up on an
 * invoice is per-line: 3 x 10.005 is 30.015, and rounding only the document
 * total while leaving the lines unrounded moves the error somewhere else
 * instead of removing it.
 */
function forEachTarget(doc, spec, apply) {
  const nested = spec.match(/^(.+)\[\]\.(.+)$/);
  if (!nested) {
    const current = doc.get(spec);
    if (isSet(current)) apply(current, (rounded) => doc.set(spec, rounded));
    return;
  }
  const [, arrayPath, field] = nested;
  const rows = doc.get(arrayPath);
  if (!Array.isArray(rows)) return;
  for (const row of rows) {
    if (row && isSet(row[field])) apply(row[field], (rounded) => { row[field] = rounded; });
  }
}

export const moneyRounding = (fields) => (schema) => {
  // Deliberately SYNCHRONOUS - declared with NO `next` parameter.
  //
  // Being sync is not what makes it work on the validate path, though: it was
  // assumed that `doc.validateSync()` would run sync hooks but skip async ones,
  // and on mongoose 8.23 it runs NEITHER (verified - the hook body never
  // executed under validateSync regardless of arity). Only the async
  // `doc.validate()` runs pre('validate') hooks, and `save()` goes through
  // that, so the production path is covered.
  //
  // It is still sync because there is nothing to await: rounding a number is
  // pure, and a callback here would only add a way to forget to call it.
  schema.pre('validate', function moneyRoundingPreValidate() {
    for (const spec of fields) {
      forEachTarget(this, spec, (current, set) => set(roundRupees(current)));
    }
  });

  const roundUpdate = (update) => {
    if (!update || typeof update !== 'object') return;
    for (const clause of ['$set', '$setOnInsert', '$inc']) {
      const bag = update[clause];
      if (!bag || typeof bag !== 'object') continue;
      for (const spec of fields) {
        const nested = spec.match(/^(.+)\[\]\.(.+)$/);
        if (nested) {
          // Updates address array members positionally: 'services.2.price'.
          // Scan the keys rather than trusting a fixed position.
          const [, arrayPath, field] = nested;
          const pattern = new RegExp(`^${arrayPath}\\.\\d+\\.${field}$`);
          for (const key of Object.keys(bag)) {
