// P2-9: Have I Been Pwned password range check (k-anonymity). Only the 5-char
// SHA-1 prefix of the candidate leaves this server - the full hash is never
// transmitted. POST /register, /reset-password and PUT /change-password call
// this before a chosen password is persisted.
//
// Posture on outage is FAIL-OPEN (with the shared F8 counter): this control
// raises the bar against reuse of known-breached passwords; refusing every
// signup because api.pwnedpasswords.com is unreachable would turn a hygiene
// check into a self-inflicted outage. Tests never touch the network.

const RANGE_URL = (prefix) => `https://api.pwnedpasswords.com/range/${prefix}`;

export async function isPwnedPassword(password, { timeoutMs = 2000 } = {}) {
  if (process.env.NODE_ENV !== 'production' || process.env.DISABLE_PWNED_CHECK === 'true') return false;
  try {
    const sha1 = crypto
      .createHash('sha1')
      .update(String(password), 'utf8')
      .digest('hex')
      .toUpperCase();
    const prefix = sha1.slice(0, 5);
    const suffix = sha1.slice(5);
    const res = await fetch(RANGE_URL(prefix), {
      headers: { 'Add-Padding': 'true' },
      signal: AbortSignal.timeout(timeoutMs),
    });
    if (!res.ok) throw new Error(`http-${res.status}`);
    const body = await res.text();
    for (const line of body.split('\n')) {
      const [hashSuffix, count] = line.trim().split(':');
      if (hashSuffix === suffix && Number(count) > 0) return true;
    }
    return false;
  } catch (err) {
    securityFailOpenTotal.inc({ control: 'pwned_password' });
    logger.warn(`pwnedPassword check unavailable (${err?.message || err}); allowing password (fail-open)`);
    return false;
  }
}

import logger from '../config/logger.js';

/**
 * RIDE-B-06: turn an internal error into a response that is useful to the user and
 * useless to an attacker.
 *
 * The handlers used `res.status(500).json({ message: '...', error: err.message })`,
 * which handed out raw CastError / MongoServerError / path text on every ride
 * route: internal schema and collection names, and occasionally a connection
 * string fragment. A 500 body should describe the failure, not the system.
 *
 * The real message goes to the log together with a short, opaque `errorId`; the
 * client gets that id, which is enough to find the matching log line in support.
 */
export const ERROR_ID_ALPHABET = 'abcdefghijklmnopqrstuvwxyz0123456789';

export function newErrorId() {
  // 8 chars from 36 — enough entropy for a correlation id, not a secret.
  let id = '';
  for (let i = 0; i < 8; i += 1) {
    id += ERROR_ID_ALPHABET[Math.floor(Math.random() * ERROR_ID_ALPHABET.length)];
  }
  return id;
}

/**
 * Write a 500 that leaks nothing, and log the cause with a correlation id.
 *
 * @param {object} res   express response
 * @param {Error}  err   the caught error
 * @param {string} clientMessage safe, user-facing summary
 * @param {object} [ctx] extra log context (never sent to the client)
 */
export function sendSafeError(res, err, clientMessage = 'Something went wrong', ctx = {}) {
  const errorId = newErrorId();
  logger.error(`[${errorId}] ${clientMessage}`, {
    errorId,
    message: err?.message,
    stack: err?.stack,
    ...ctx,
  });
  return res.status(500).json({ message: clientMessage, errorId });
}

// §5.3/§5.4: response-DTO allowlist guard — `...doc` / full-object returns leak
// password, tokenVersion, 2FA secrets, __v, KYC/bank fields. Strip at the DTO
// boundary (select:false is bypassed by .lean()/.select('+password')).
const FORBIDDEN_RESPONSE_FIELDS = new Set([
  'password', 'passwordHash', 'tokenVersion', 'tokenKey',
  'twoFactorSecret', 'twoFactorTempSecret', 'twoFactorBackupCodes',
  'driveTokens', 'abhaOtpHash', 'otp', 'otpHash',
  'bankAccount', 'bankAccountNumber', 'accountNumber', 'ifsc', 'upiId',
  'aadhaar', 'aadhaarNumber', 'pan', 'panNumber', 'passportNumber',
  'voterId', 'kyc', 'kycDocs', '__v',
]);

export function sanitizeDto(input) {
  if (!input || typeof input !== 'object') return input;
  const obj = typeof input.toObject === 'function' ? input.toObject() : { ...input };
  for (const field of FORBIDDEN_RESPONSE_FIELDS) delete obj[field];
  return obj;
}

export { FORBIDDEN_RESPONSE_FIELDS };

/**
 * Handle an unexpected failure inside an async route.
 *
 *   router.get('/:id', protect, async (req, res) => {
 *     try { … } catch (err) { sendServerError(res, err, 'Failed to fetch ride details', { rideId: req.params.id }); }
 *   });
 */
export function sendServerError(res, err, clientMessage, ctx) {
  return sendSafeError(res, err, clientMessage, ctx);
}

import fs from 'fs';

// KEY=VALUE, optionally `export KEY=VALUE` (shell-rendered files often add it).
// Secret values may contain '=' (base64 padding), so only the FIRST '=' splits.
const LINE_RE = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*([\s\S]*?)\s*$/;

/**
 * Parse a dotenv-shaped secrets file into a flat object.
 * Ignores blank lines and '#' comments; surrounding quotes are stripped so
 * `DB_URL="postgres://..."` and `DB_URL=postgres://...` are equivalent.
 *
 * Pure + exported separately so the parsing rules above are unit-testable
 * without touching process.env or the filesystem.
 */
export const parseSecretsFile = (raw) =>
  String(raw ?? '')
    .split(/\r?\n/)
    .reduce((acc, line) => {
      if (!line.trim() || line.trimStart().startsWith('#')) return acc;
      const m = line.match(LINE_RE);
      if (!m) return acc;
      acc[m[1]] = m[2].replace(/^(['"])([\s\S]*)\1$/, '$2');
      return acc;
    }, {});

/**
 * Overlay an externally-rendered secrets file (Doppler `secrets render`,
 * Vault Agent template, AWS Secrets Manager → KEY=VALUE) onto `target`.
 *
 * Precedence chain: platform-injected env > secrets file > .env
 *   - `.env` was already merged into process.env by dotenv before this runs,
 *     and a stale local .env must NOT shadow the real secrets file;
 *   - but vars the operator injected on the platform must survive, which is
 *     why the caller passes `protectedKeys` (the environment snapshot taken
 *     BEFORE dotenv ran).
 *
 * Throws if the file cannot be read — callers decide whether that is fatal.
 * Returns the count applied/protected so boot logs can prove the file was used.
 */
export const applySecretsFile = (filePath, protectedKeys, target = process.env) => {
  const protectedSet = protectedKeys instanceof Set
    ? protectedKeys
    : new Set(protectedKeys ?? []);
  const parsed = parseSecretsFile(fs.readFileSync(filePath, 'utf8'));
  let applied = 0;
  for (const [key, value] of Object.entries(parsed)) {
    if (protectedSet.has(key)) continue;
    target[key] = value;
    applied += 1;
  }
  return { applied, skipped: Object.keys(parsed).length - applied };
};

