// PDF worker: drains findmedi-pdf (heavy report/invoice generation).
// Job data: { kind: 'prescription'|'lab-report'|'discharge-summary'|'invoice', data }
// Returns: { filename, base64 } — polled via GET /api/reports/jobs/:id.
// Validation errors are Unrecoverable (no pointless retries).

import crypto from 'node:crypto';
import logger from '../config/logger.js';
import { QUEUE_NAMES } from '../lib/queues.js';

const MAX_PDF_BYTES = 10 * 1024 * 1024;
const CACHE_TTL_SECONDS = 3600; // 1 hour

let worker = null;

async function generatePdf(kind, data, UnrecoverableError, job) {
  const pdf = await import('../services/pdfService.js');
  switch (kind) {
    case 'template': {
      const { docType, templateVersion, payload, html, css, duplicate, lang } = data || {};
      const printEngine = await import('../lib/printEngine.js');
      const pdfRender = await import('../lib/pdfRender.js');
      try {
        const rendered = printEngine.renderTemplate(html || '', css || '', payload || {}, { duplicate, lang });
        const buffer = await pdfRender.renderHtmlToPdf({ html: rendered.html, css });
        return { buffer, filename: `${docType || 'document'}-${templateVersion || Date.now()}.pdf` };
      } catch (err) {
        if (job?.log) job.log(`[pdfWorker] template render failed (${err.message}), falling back to pdfkit`);
        logger.warn(`[pdfWorker] template render fallback for ${docType}: ${err.message}`);
        if (docType && ['prescription', 'lab-report', 'discharge-summary', 'invoice'].includes(docType)) {
          return generatePdf(docType, payload || data, UnrecoverableError, job);
        }
        throw err;
      }
    }
    case 'prescription':
      return { buffer: await pdf.generatePrescriptionPDF(data), filename: `prescription-${Date.now()}.pdf` };
    case 'lab-report':
      return { buffer: await pdf.generateLabReportPDF(data), filename: `lab-report-${Date.now()}.pdf` };
    case 'discharge-summary':
      return { buffer: await pdf.generateDischargeSummaryPDF(data), filename: `discharge-summary-${Date.now()}.pdf` };
    case 'invoice':
      return { buffer: await pdf.generateInvoicePDF(data), filename: `invoice-${Date.now()}.pdf` };
    default:
      throw new UnrecoverableError(`unknown pdf kind: ${kind}`);
  }
}

export async function startPdfWorker() {
  if (worker) return worker;
  if (!process.env.REDIS_URL) {
    logger.info('[workers] REDIS_URL unset — pdf worker not started.');
    return null;
  }
  try {
    const [{ Worker, UnrecoverableError }, { default: IORedis }] = await Promise.all([
      import('bullmq'),
      import('ioredis'),
    ]);
    const connection = new IORedis(process.env.REDIS_URL, {
      maxRetriesPerRequest: null,
      enableReadyCheck: false,
    });
    connection.on('error', (err) => logger.warn(`[workers] pdf redis error: ${err.message}`));

    worker = new Worker(
      QUEUE_NAMES.pdf,
      async (job) => {
        const { kind, data } = job.data || {};
        if (!kind) throw new UnrecoverableError('pdf job missing kind');

        // Redis cache check for template jobs
        let cacheKey = null;
        if (kind === 'template' && data?.docType) {
          const rawHash = `${data.docType}|${data.templateVersion || ''}|${JSON.stringify(data.payload || {})}`;
          const dataHash = crypto.createHash('sha256').update(rawHash).digest('hex');
          cacheKey = `pdf:cache:${dataHash}`;
          try {
            const cached = await connection.get(cacheKey);
            if (cached) {
              return { filename: `${data.docType}-${Date.now()}.pdf`, base64: cached, fromCache: true };
            }
          } catch {}
        }

        const { buffer, filename } = await generatePdf(kind, data || {}, UnrecoverableError, job);
        if (!buffer?.length) throw new Error('empty pdf buffer');
        if (buffer.length > MAX_PDF_BYTES) throw new UnrecoverableError('pdf exceeds 10MB result cap');
        const base64 = Buffer.from(buffer).toString('base64');

        if (cacheKey) {
          try {
            await connection.setex(cacheKey, CACHE_TTL_SECONDS, base64);
          } catch {}
        }

        return { filename, base64 };
      },
      { connection, concurrency: 2 }
    );
    worker.on('completed', (job) => logger.info(`[workers] pdf done (job ${job.id})`));
    worker.on('failed', (job, err) =>
      logger.warn(`[workers] pdf job ${job?.id} attempt ${job?.attemptsMade} failed: ${err.message}`)
    );
    worker.on('error', (err) => logger.warn(`[workers] pdf worker error: ${err.message}`));
    logger.info('[workers] pdf worker started (concurrency 2).');
    return worker;
  } catch (err) {
    logger.warn(`[workers] pdf worker not started: ${err.message}`);
    return null;
  }
}

export async function stopPdfWorker() {
  if (!worker) return;
  try { await worker.close(); } catch {}
  worker = null;
}

/**
 * File 13 §13.1/§13.5 + File 16 + File 17: in-process cron scheduler.
 * Enabled ONLY with SCHEDULER_ENABLED=1 (default off — safe in dev/test).
 * Every tick iterates hospitals and calls the exported tenant sweep
 * functions; failures are logged, never thrown.
 */
import cron from 'node-cron';
import logger from '../config/logger.js';

let tasks = [];

async function eachHospital(fn, label) {
  const out = [];
  try {
    const { default: Hospital } = await import('../models/Hospital.js');
    const hospitals = await Hospital.find({}).select('_id').limit(500).lean();
    for (const h of hospitals) {
      try {
        out.push(await fn(h._id));
      } catch (e) {
        logger.warn(`[scheduler:${label}] hospital ${h._id}: ${e.message}`);
      }
    }
  } catch (e) {
    logger.warn(`[scheduler:${label}] ${e.message}`);
  }
  return out;
}

export async function escalateUnackedClinicalAlerts(minutes = 15) {
  const results = await eachHospital(async (hid) => {
    const { escalateAlertsTenant } = await import('../lib/alerts.js');
    return escalateAlertsTenant(hid, minutes);
  }, 'escalation');
  return results.reduce(
    (acc, r) => ({
      escalated: acc.escalated + Number(r?.escalated || 0),
      notified: acc.notified + Number(r?.notified || 0),
      hospitals: acc.hospitals + 1,
    }),
    { escalated: 0, notified: 0, hospitals: 0 },
  );
}

export function startScheduler() {
  if (process.env.SCHEDULER_ENABLED !== '1') {
    logger.info('[scheduler] disabled (set SCHEDULER_ENABLED=1 to enable)');
    return;
  }
  // Every 15 min: rules sweep + RCM detectors.
  tasks.push(cron.schedule('*/15 * * * *', async () => {
    const { sweepRulesTenant } = await import('../routes/rules.js');
    const { detectRcmTenant } = await import('../routes/rcm.js');
    await eachHospital((hid) => sweepRulesTenant(hid), 'rules');
    await eachHospital((hid) => detectRcmTenant(hid), 'rcm');
    await escalateUnackedClinicalAlerts();
  }));
  // Hourly: workflow SLA sweep + approval expiry + contract expiry + webhook retries.
  tasks.push(cron.schedule('0 * * * *', async () => {
    const { default: WorkflowInstance } = await import('../models/WorkflowInstance.js');
    const { default: ApprovalRequest } = await import('../models/ApprovalRequest.js');
    const { default: Contract } = await import('../models/Contract.js');
    const { retryDueWebhooks } = await import('../routes/hub.js');
    const now = new Date();
    await eachHospital(async (hid) => {
      const due = await WorkflowInstance.find({
        hospitalId: hid, status: 'Active',
        timers: { $elemMatch: { dueAt: { $lte: now }, escalatedAt: null } },
      }).limit(200);
      for (const inst of due) {
        const timer = inst.timers.find((t) => t.dueAt <= now && !t.escalatedAt);
        if (timer) {
          timer.escalatedAt = now;

          await inst.save();
        }
      }
      const escalationThreshold = new Date(now.getTime() - 0.75 * 48 * 3600 * 1000);
      await ApprovalRequest.updateMany(
        {
          hospitalId: hid, status: 'pending', escalatedAt: null,
          createdAt: { $lte: escalationThreshold }, dueAt: { $gt: now },
        },
        {
          $set: { escalatedAt: now, escalationLevel: 1 },
          $push: { requiredRoles: 'hospital_admin' },
        },
      );
      await ApprovalRequest.updateMany(
        { hospitalId: hid, status: 'pending', dueAt: { $lte: now } },
        { $set: { status: 'expired' } },
      );
      await Contract.updateMany(
        { hospitalId: hid, status: 'active', endDate: { $lt: now } },
        { $set: { status: 'expired' } },
      );
    }, 'hourly');
    await escalateUnackedClinicalAlerts();
    // 20.md §2-§3: SLA-breached support tickets auto-escalate (hourly).
    try {
      const { runTicketEscalationsOnce } = await import('../jobs/ticketEscalation.job.js');
      const out = await runTicketEscalationsOnce();
      if (out?.escalated) logger.info(`[scheduler:tickets] escalated ${out.escalated} breached ticket(s)`);
    } catch (e) {
      logger.warn(`[scheduler:tickets] ${e.message}`);
    }
    try {
      await retryDueWebhooks();
    } catch (e) {
      logger.warn(`[scheduler:webhooks] ${e.message}`);
    }
    // File 22 P0-9: gateway settlement reconcile (no-op without credentials).
    try {
      const { reconcileGatewayTenant } = await import('../routes/checkout.js');
      const { default: Hospital } = await import('../models/Hospital.js');
      const hospitals = await Hospital.find({}).select('_id').limit(500).lean();
      for (const h of hospitals) {
        for (const gw of ['razorpay', 'cashfree', 'payu', 'phonepe']) {
          try {
            // eslint-disable-next-line no-await-in-loop
            await reconcileGatewayTenant(h._id, gw);
          } catch (e) {
            logger.warn(`[scheduler:reconcile] ${h._id}/${gw}: ${e.message}`);
          }
        }
      }
    } catch (e) {
      logger.warn(`[scheduler:reconcile] ${e.message}`);
    }
    // File 22 P1-27: call-recording retention purge.
    try {
      const { purgeOldRecordings } = await import('../routes/contactCenter.js');
      await purgeOldRecordings();
    } catch (e) {
      logger.warn(`[scheduler:recordings] ${e.message}`);
    }
    // File 22 P2-31: breach 72h clock watch.
    try {
      const { breachDeadlineSweep } = await import('../routes/breach.js');
      await breachDeadlineSweep();
    } catch (e) {
      logger.warn(`[scheduler:breach] ${e.message}`);
    }
    // File 24 §5: CRM automation rules sweep (platform-scoped, never throws).
    try {
      const { runCrmAutomation } = await import('../lib/crmAutomation.js');
      await runCrmAutomation({});
    } catch (e) {
      logger.warn(`[scheduler:crmAutomation] ${e.message}`);
    }
  }));
  // Nightly 01:30: daily metrics + report schedules due.
  tasks.push(cron.schedule('30 1 * * *', async () => {
    const { computeDailyMetricsTenant } = await import('../routes/insights.js');
    const { runScheduleOnce } = await import('../routes/reportStudio.js').catch(() => ({}));
    const { default: ReportSchedule } = await import('../models/ReportSchedule.js').catch(() => ({}));
    const day = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
    await eachHospital((hid) => computeDailyMetricsTenant(hid, day), 'metrics');
    if (ReportSchedule && runScheduleOnce) {
      try {
        const { default: cronLib } = await import('node-cron');
        void cronLib;
        const due = await ReportSchedule.find({ active: true }).limit(100);
        for (const s of due) {
          try {

            await runScheduleOnce(s);
          } catch (e) {
            logger.warn(`[scheduler:reports] ${s._id}: ${e.message}`);
          }
        }
      } catch (e) {
        logger.warn(`[scheduler:reports] ${e.message}`);
      }
    }
    // File 24 §4.12: due CRM report schedule emails (aggregates only).
    try {
      const { runCrmReportSchedules } = await import('../routes/crm.js');
      const out = await runCrmReportSchedules();
      if (out?.sent) logger.info(`[scheduler:crmReports] sent ${out.sent} report email(s)`);
    } catch (e) {
      logger.warn(`[scheduler:crmReports] ${e.message}`);
    }
    // File 25 §10: quarterly IAM access-certification campaigns.
    // Idempotent (one per tenant per calendar quarter) — a daily check is safe.
    try {
      const { runIamReviewCampaigns } = await import('../lib/iamReviewSweep.js');
      const out = await runIamReviewCampaigns();
      if (out?.created) logger.info(`[scheduler:iamReviews] created ${out.created} campaign(s) for ${out.cycle}`);
    } catch (e) {
      logger.warn(`[scheduler:iamReviews] ${e.message}`);
    }
  }));
  logger.info('[scheduler] started (rules/rcm 15m, hourly sweeps, nightly metrics)');
}

export function stopScheduler() {
  for (const t of tasks) {
    try { t.stop(); } catch { /* noop */ }
  }
  tasks = [];
}

import { describe, it, expect } from '@jest/globals';
import { sanitizeDto, FORBIDDEN_RESPONSE_FIELDS } from '../../src/utils/safeError.js';
import { toProductCard } from '../../src/routes/products.js';
import { toSearchCard } from '../../src/utils/searchDto.js';

// Extension of test/security/dtoLeak.spec.js for the newer public surfaces:
// Provider (directory), Product (storefront), Event (camps). Same rule — a
// public DTO is built by ALLOWLIST, so auth secrets (password/tokenVersion),
// money rails (bank/ifsc/upi) and licence/regulatory internals must never
// survive the mapper, even when the underlying row holds them.
const AUTH_SECRETS = ['password', 'passwordHash', 'tokenVersion', 'otpHash'];
const MONEY_RAILS = ['bankAccount', 'bankAccountNumber', 'accountNumber', 'ifsc', 'upiId'];
const LICENCE_INTERNALS = ['licenseNumber', 'fssaiNo', 'cdscoNo', 'hsn', 'gstRate'];

describe('public DTO leak guard — Provider/Product/Event extension', () => {
  it('FORBIDDEN_RESPONSE_FIELDS covers auth secrets and money rails', () => {
    for (const key of [...AUTH_SECRETS, ...MONEY_RAILS, 'aadhaar', 'pan', '__v']) {
      expect(FORBIDDEN_RESPONSE_FIELDS.has(key)).toBe(true);
    }
  });

  it('sanitizeDto strips secrets from a Provider-shaped row but keeps the card fields', () => {
    const out = sanitizeDto({
      name: 'City Care Hospital',
      kind: 'hospital',
      city: 'Pune',
      slug: 'city-care',
      ownerUserId: 'user-77',
      password: 'hash',
      tokenVersion: 3,
      bankAccount: '501000123456',
      ifsc: 'HDFC0001234',
      upiId: 'citycare@upi',
      licenseNumber: 'FULL-LIC-998877',
      aadhaar: '999988887777',
      __v: 0,
    });
    for (const forbidden of [...AUTH_SECRETS, ...MONEY_RAILS, 'aadhaar', '__v']) {
      expect(out[forbidden]).toBeUndefined();
    }
    // sanitizeDto is a denylist: public display fields pass through.
    expect(out.name).toBe('City Care Hospital');
    expect(out.city).toBe('Pune');
  });

  it('sanitizeDto strips secrets from an Event-shaped row', () => {
    const out = sanitizeDto({
      title: 'Free Eye Camp',
      type: 'camp',
      city: 'Nagpur',
      organizerId: 'prov-1',
      password: 'hash',
      tokenVersion: 1,
      bankAccount: 'acc',
      ifsc: 'IFSC1',
      pan: 'ABCDE1234F',
      __v: 0,
    });
    for (const forbidden of [...AUTH_SECRETS, ...MONEY_RAILS, 'pan', '__v']) {
      expect(out[forbidden]).toBeUndefined();
    }
    expect(out.title).toBe('Free Eye Camp');
  });

  it('toProductCard never emits auth/bank/licence internals even on a fully-loaded row', () => {
    const card = toProductCard({
      _id: 'p9',
      kind: 'device',
      categoryCodes: ['DEV.NEB'],
      brand: 'MediCo',
      name: 'Nebulizer X1',
      images: [],
      rxSchedule: 'OTC',
      storage: 'ambient',
      claims: [],
      warrantyMonths: 12,
      rentable: { perDay: 50, deposit: 500, available: true },
      variants: [{ sku: 'S1', pack: '1 pc', price: 999, mrp: 1299, stock: 4, batch: 'B-1', expiry: new Date() }],
      // Back-office / secret-shaped fields a future select() might pull in:
      vendorId: 'v-1',
      password: 'hash',
      tokenVersion: 2,
      bankAccount: 'acc',
      ifsc: 'IFSC9',
      licenseNumber: 'FULL-LIC-112233',
      composition: 'secret formula',
      fssaiNo: 'F-1',
      cdscoNo: 'C-1',
