  it('generates sealed PDF with tamper-evident headers, verify URL, and SignatureEvent', async () => {
    const existingCert = mockRecords[0];
    expect(existingCert).toBeDefined();

    const res = await as(doctor)
      .get(`/${existingCert._id}/pdf`)
      .expect(200);

