  });

  it('lists gate passes (requires audit:read or records:read)', async () => {
    const res = await asSec(securityAdmin).get('/gate-passes').expect(200);
    expect(res.body.passes).toBeDefined();
    expect(res.body.total).toBeGreaterThan(0);
  });
});

