    create: async (doc) => {
      const row = { _id: `ch-${chargeItems.length + 1}`, ...doc };
      chargeItems.push(row);
      return row;
    },
    updateMany: async (filter, update) => {
      let n = 0;
      for (const c of chargeItems.filter((r) => matchCharge(r, filter))) {
