  '../../src/models/Feedback.js': () => ({
    default: {
      create: async (data) => {
        const item = {
          _id: '507f191e810c19729de860f1',
          createdAt: new Date(),
          status: 'new',
          ...data,
        };
        feedbackStore.push(item);
        return item;
      },
      find: (filter) => {
        let results = [...feedbackStore];
        if (filter?.patientId) {
          results = results.filter((r) => String(r.patientId) === String(filter.patientId));
        }
        if (filter?.status) {
          results = results.filter((r) => r.status === filter.status);
        }
        return {
          sort: () => ({
            limit: () => ({
              lean: async () => results,
            }),
          }),
          lean: async () => results,
        };
      },
      findOne: (filter) => {
        let results = [...feedbackStore];
        if (filter?.patientId) {
          results = results.filter((r) => String(r.patientId) === String(filter.patientId));
        }
        if (filter?.refId) {
          results = results.filter((r) => String(r.refId) === String(filter.refId));
        }
        if (filter?.context) {
          results = results.filter((r) => r.context === filter.context);
        }
        const item = results[0] || null;
        return {
          lean: async () => item,
        };
      },
      findById: async (id) => {
        const item = feedbackStore.find((r) => String(r._id) === String(id));
        if (!item) return null;
        return {
          ...item,
          save: async () => item,
        };
      },
    },
  }),
  '../../src/middleware/audit.js': () => ({
    auditLog: async () => ({}),
