/**
 * AUTHZ-M-02 + AUTHZ-M-07: the authorization manifest and the matrix it feeds.
 *
 * The finding was that nothing machine-readable said who may call what, and
 * that regressions were caught "by chance". Both are addressed by one artefact -
 * `authz-manifest.json` - and this suite is what stops it rotting.
 *
 * The load-bearing test here is FRESHNESS. A committed manifest nobody
 * re-derives is worse than no manifest: it is a snapshot that looks current,
 * and it will confidently report a route as guarded after someone deleted the
 * guard. So the manifest is rebuilt from source on every run and compared
 * byte-for-byte; any route change without a regenerated manifest fails.
 *
 * It also asserts the AUTHZ-M-01 number out loud. The central object-layer
 * migration is NOT done, and a test that printed the share without asserting
 * anything about it would let the number decay in a file nobody reads.
 */
import { describe, it, expect } from '@jest/globals';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const BACKEND = path.resolve(__dirname, '..', '..');
const ROUTES_DIR = path.join(BACKEND, 'src', 'routes');
const MANIFEST_FILE = path.join(BACKEND, 'authz-manifest.json');

// scanRoutes comes from the parser's own module rather than through
// authzClassify: re-exporting it would blur which file owns the grammar, and
// this test is checking the parser did not lose a guard on the way through.
const { buildInventory, countByTag, buildOwnershipMatrix } =
  await import('../../scripts/lib/authzClassify.mjs');
const { scanRoutes } = await import('../../scripts/lib/routeScan.mjs');

const manifest = JSON.parse(fs.readFileSync(MANIFEST_FILE, 'utf8'));

describe('AUTHZ-M-02 the manifest exists and is self-consistent', () => {
  it('has the expected shape', () => {
    expect(manifest.schemaVersion).toBe(1);
    expect(Array.isArray(manifest.routes)).toBe(true);
    expect(manifest.routes.length).toBeGreaterThan(0);
    expect(manifest.note).toMatch(/Do not hand-edit/);
  });

  it('counts sum to the total', () => {
    const sum = Object.values(manifest.counts).reduce((a, b) => a + b, 0);
    expect(sum).toBe(manifest.total);
    expect(manifest.total).toBe(manifest.routes.length);
  });

  it('uses only declared tags', () => {
    const declared = new Set(Object.keys(manifest.tags));
    for (const r of manifest.routes) expect(declared.has(r.tag)).toBe(true);
  });

  it('every route carries a file, line, method and target', () => {
    for (const r of manifest.routes) {
      expect(typeof r.file).toBe('string');
      expect(Number.isInteger(r.line)).toBe(true);
      expect(typeof r.method).toBe('string');
    }
  });
});

describe('AUTHZ-M-02 the manifest is CURRENT, not a stale snapshot', () => {
  it('matches what the parser sees in the source right now', () => {
    const fresh = buildInventory(ROUTES_DIR);
    const freshCounts = countByTag(fresh);

    expect(
      manifest.routes.map((r) => `${r.file}:${r.line}:${r.method}:${r.target}:${r.tag}`).join('\n')
    ).toBe(fresh.map((r) => `${r.file}:${r.line}:${r.method}:${r.target}:${r.tag}`).join('\n'));

    expect(manifest.counts).toEqual(
      Object.fromEntries(Object.entries(freshCounts).sort(([a], [b]) => a.localeCompare(b)))
    );
  });

  it('is sorted, so the file is stable across runs', () => {
    // Without the sort, scan order alone would churn the git diff on every run
    // and the one-line-diff property that makes the manifest reviewable is lost.
    const keys = manifest.routes.map((r) => `${r.file}�${String(r.line).padStart(6, '0')}`);
    expect(keys).toEqual([...keys].sort());
  });

  it('agrees with its own matrix on how many routes are gaps', () => {
    // Two gap counters in one artefact that disagree is how a reader learns to
    // trust neither. This caught a real 23-vs-16 divergence during development.
    // `?? 0` because countByTag omits a key whose value is zero, so an absent
    // `unclassified` key means "none", not "unknown".
    expect(manifest.unrecognised.length).toBe(manifest.counts.unclassified ?? 0);
    for (const u of manifest.unrecognised) expect(u.id).toMatch(/^[^:]+:\d+$/);
  });
});

describe('AUTHZ-M-07 the matrix attributes every guard it can see', () => {
  const { byMechanism, centralLayer, alternatives, unnamedHandlerGuard } =
    buildOwnershipMatrix(ROUTES_DIR);

  it('accounts for every guard the parser detected on a route line', () => {
    // Cross-check against a raw census. If the matrix silently dropped a guard
    // name, this is where it shows - a matrix that undercounts is worse than
    // none, because it reads as evidence the migration is nearly finished.
    const census = {};
    for (const r of scanRoutes(ROUTES_DIR)) {
      for (const g of r.guards) census[g] = (census[g] || 0) + 1;
    }
    for (const [guard, n] of Object.entries(census)) {
      expect(byMechanism[guard]).toBeGreaterThanOrEqual(n);
    }
  });

  it('matches the numbers committed in the manifest', () => {
    expect(byMechanism).toEqual(manifest.byMechanism);
    expect(centralLayer.length).toBe(manifest.centralLayer.routes);
    expect(unnamedHandlerGuard).toBe(manifest.centralLayer.unnamedHandlerGuard);
    expect(
      Object.fromEntries(Object.entries(alternatives).sort(([a], [b]) => a.localeCompare(b)))
    ).toEqual(
      Object.fromEntries(
        manifest.centralLayer.alternatives
          .map((a) => [a.mechanism, a.routes])
          .sort(([a], [b]) => a.localeCompare(b))
      )
    );
  });

  it('reports a central-layer share that is arithmetically true', () => {
    const alternativeTotal = Object.values(alternatives).reduce((a, b) => a + b, 0);
    expect(manifest.centralLayer.objectScopedTotal).toBe(centralLayer.length + alternativeTotal);
    expect(manifest.centralLayer.share).toBeCloseTo(
      centralLayer.length / manifest.centralLayer.objectScopedTotal,
      3
    );
  });
});

describe('AUTHZ-M-01 the central object-layer is still OPEN, and the number says so', () => {
  it('has NOT regressed', () => {
    // The ratchet is on the ABSOLUTE count, not the share.
    //
    // This was originally `share >= 0.035` and it failed the moment six routes
    // were legitimately re-gated: `booked-slots` moved into the object-scoped
    // bucket (scopeToHospital), so the denominator grew 86 -> 87 while
    // authorizeObject stayed at 3, and the ratio slid to 0.034. That is the
    // opposite of a regression - it was routes being classified MORE precisely -
    // which is exactly why a ratio is the wrong thing to pin. A share couples
    // the central layer's progress to unrelated edits elsewhere in the codebase,
    // so a careful reviewer tightening an authorization elsewhere gets punished
    // with a failing test and learns to ignore the gate.
    //
    // The count is the real signal: it can only fall if someone removes
    // `authorizeObject` from a route.
    expect(manifest.centralLayer.routes).toBeGreaterThanOrEqual(3);
  });

  it('reports the share, and the share is merely informational', () => {
    // Asserted for arithmetically-true-ness elsewhere; here only that it exists
    // and is a real fraction, with no floor attached.
    expect(typeof manifest.centralLayer.share).toBe('number');
    expect(manifest.centralLayer.share).toBeGreaterThan(0);
    expect(manifest.centralLayer.share).toBeLessThan(1);
  });

  it('records that the migration is incomplete rather than implying it is done', () => {
    // Deliberately asserts the CURRENT, unflattering state. When the migration
    // does land, this test is what has to be edited - which is the point. A
    // report that quietly stops mentioning the gap is how AUTHZ-M-01 survived
    // this long.
    expect(manifest.centralLayer.alternatives.length).toBeGreaterThan(0);
    expect(manifest.centralLayer.note).toMatch(/AUTHZ-M-01 is OPEN/);
    // Inverted 2026-10-07: the provider verticals (second-opinions, dental,
    // eye, dialysis) standardized on authorizeObject with provider ownership,
    // so the central layer now holds the majority (share >= 0.5). The
    // migration is still OPEN — the handler-level alternatives (self-or-family
    // profileAccess decisions on the patient dashboard slices) remain by
    // design, since a query-parameter profile is not a row id authorizeObject
    // can name — but they no longer dominate.
    expect(manifest.centralLayer.share).toBeGreaterThanOrEqual(0.5);
  });

  it('flags the object-scoped routes that no mechanism can even name', () => {
    // Handler-body guards behind a regex: real authorization, but invisible to
    // the migration tooling. A non-zero value here is the honest reason AUTHZ-M-01
    // cannot be closed by pattern-matching alone.
    expect(manifest.centralLayer.unnamedHandlerGuard).toBeGreaterThan(0);
  });
});

/**
 * The two authorization tools must agree.
 *
 * `check-authz-coverage.mjs` reported 289 unclassified routes while
 * `triage-authz-gaps.mjs` reported 0 unguarded. Both were "correct" and they
 * contradicted each other, because each had its own parser: the coverage gate
 * read only the route definition line, so a route guarded by
 * `applyTenantScope()` inside its handler looked bare to it.
 *
 * These tests assert they now share one source of truth, and that the shared
 * parser still behaves. A duplicated parser is the defect, so the duplication
 * itself is what needs a regression test.
 */
import { describe, it, expect } from '@jest/globals';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { scanRoutes, stripComments, middlewareChain, guardMiddleware, HANDLER_GUARDS } from '../../scripts/lib/routeScan.mjs';

const ROUTES = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', '..', 'src', 'routes');
const triage = fs.readFileSync(
  path.join(ROUTES, '..', '..', 'scripts', 'triage-authz-gaps.mjs'), 'utf8'
);
const coverage = fs.readFileSync(
  path.join(ROUTES, '..', '..', 'scripts', 'check-authz-coverage.mjs'), 'utf8'
);
// The grammar module that now sits between the coverage tool and the parser.
const grammar = fs.readFileSync(
  path.join(ROUTES, '..', '..', 'scripts', 'lib', 'authzClassify.mjs'), 'utf8'
);

describe('AUTHZ · both tools use the shared parser', () => {
  it('triage imports scanRoutes instead of re-parsing files itself', () => {
    expect(triage).toMatch(/import \{[^}]*scanRoutes[^}]*\} from '\.\/lib\/routeScan\.mjs'/);
  });

  it('coverage reaches the parser through the shared grammar module', () => {
    // Was: `expect(coverage).toMatch(scanRoutes import)`. That asserted a
    // particular IMPORT LINE rather than the invariant behind it, so extracting
    // the grammar into lib/authzClassify.mjs — which is what let the manifest
    // freshness test re-derive the classification instead of re-implementing it —
    // failed here despite strictly improving the guarantee.
    //
    // The invariant is "coverage never parses or classifies on its own". So:
    // it must import the grammar module, and the grammar module must import the
    // one parser. Two hops is still one definition; the old assertion would
    // have failed a design that is strictly better.
    expect(coverage).toMatch(/import \{[^}]*\} from '\.\/lib\/authzClassify\.mjs'/);
    expect(grammar).toMatch(/import \{[^}]*scanRoutes[^}]*\} from '\.\/routeScan\.mjs'/);
    // ...and coverage must NOT have picked up a direct parser import purely to
    // satisfy the old shape.
    expect(coverage).not.toMatch(/from '\.\/lib\/routeScan\.mjs'/);
  });

  it('neither file re-declares the guard patterns', () => {
    // A second copy of HANDLER_GUARDS is exactly how the two drifted.
    // The grammar module is included because it now sits in the same chain: it
    // OWNS the classification rules, but it must still IMPORT the parser's
    // guard lists rather than restating them, or the drift simply moves one
    // file down.
    for (const src of [triage, coverage, grammar]) {
      expect(src).not.toMatch(/^const HANDLER_GUARDS/m);
      expect(src).not.toMatch(/^const AUTHZ_MARKERS/m);
      expect(src).not.toMatch(/^function middlewareChain/m);
      expect(src).not.toMatch(/^function handlerBody/m);
    }
  });

  it('only the grammar module declares the classification rules', () => {
    // The converse: exactly ONE file may own the vocabulary, or the grammar is
    // duplicated in the direction this suite cannot otherwise see.
    expect(grammar).toMatch(/export const ROLE_MARKERS/);
    expect(grammar).toMatch(/export const classify/);
    for (const src of [triage, coverage]) {
      expect(src).not.toMatch(/ROLE_MARKERS\s*=/);
      expect(src).not.toMatch(/const classify\s*=/);
    }
  });

  it('neither file reads the routes directory on its own', () => {
    for (const src of [triage, coverage]) {
      expect(src).not.toMatch(/readdirSync\(ROUTES_DIR\)/);
    }
  });
});

describe('AUTHZ · the shared parser still parses correctly', () => {
  it('finds the same number of routes the coverage gate counts', () => {
    const rows = scanRoutes(ROUTES);
    expect(rows.length).toBeGreaterThan(700);
  });

  it('splits a middleware chain into its parts', () => {
    const parts = middlewareChain("router.get('/x', protect, adminOnly, async (req, res) => {");
    expect(parts).toContain('protect');
    expect(parts).toContain('adminOnly');
  });

  it('does not treat authentication or validation as authorization', () => {
    const parts = middlewareChain("router.get('/x', protect, validate(schema), async (req, res) => {");
    expect(guardMiddleware("router.get('/x', protect, validate(schema), async (req, res) => {")).toEqual([]);
  });

  it('strips comments, so a comment cannot pose as a control', () => {
    // The real case: the comment above GET /search/ehr names `consentId`, and
    // GET /search/icd was reported consent-guarded because of it.
    const src = 'const a = 1; // mentions consentId and forbidden\nconst b = 2;';
    expect(stripComments(src)).not.toMatch(/consentId/);
    expect(stripComments(src)).toMatch(/const b = 2/);
  });

  it('keeps a // inside a string literal', () => {
    expect(stripComments("const u = 'https://example.com/x';")).toMatch(/example\.com/);
  });

  it('returns a per-route body with comments already removed', () => {
    const rows = scanRoutes(ROUTES, 'search.js');
    const icd = rows.find((r) => r.target === '/icd');
    expect(icd).toBeDefined();
    // The comment between /icd and /ehr must not leak into /icd's body.
    expect(icd.body).not.toMatch(/consent-gated/);
  });

  it('recognises applyTenantScope as a guard, not just middleware names', () => {
    const guarded = scanRoutes(ROUTES, 'pharmacy.js').filter((r) =>
      HANDLER_GUARDS.some((re) => re.test(r.body))
    );
    // 10 call sites, so this must be well above zero.
    expect(guarded.length).toBeGreaterThanOrEqual(8);
  });

  it('reports the two tools agree: 0 routes are both unguarded and unclassified', () => {
    const rows = scanRoutes(ROUTES);
    const candidates = rows.filter(
      (r) => r.hasProtect && !r.routerGuarded && !r.authzTag &&
        r.guards.length === 0 && !HANDLER_GUARDS.some((re) => re.test(r.body))
    );
    const byKey = new Set(candidates.map((r) => `${r.file}:${r.method} ${r.target}`));
    // Both tools must start from THIS set, or they are looking at different
    // routes and their totals are not comparable. The composition was:
    //   23 raw candidates
    //    -  7 dropped by the /me,/my- naming convention (self-hinted)
    //   = 16 that the coverage gate called "unclassified", and which the triage
    //     then cleared as reviewed-safe
    //
    // On 2026-10-01 all 16 were reviewed and given a real decision, so they no
    // longer reach this set at all (the filter excludes anything with an
    // `// authz:` tag). The 7 self-hinted ones are correctly still here - they
    // are self-service and the naming convention IS their guard.
    //
    // So the number is now 0 rather than 16, and that is a real strengthening:
    // every protected route in the codebase now carries an authorization
    // decision, and a new one without a tag fails here as well as at the gate.
    const selfHinted = new Set(
      candidates
        .filter((r) => ['/me', '/my-', '/profile', '/self', '/mine'].some((h) => r.target.toLowerCase().includes(h)))
        .map((r) => `${r.file}:${r.method} ${r.target}`)
    );
    expect(selfHinted.size).toBe(7);
    expect(byKey.size - selfHinted.size).toBe(0);
  });
});

/**
 * AUTH-M-05 · bot protection (Cloudflare Turnstile) on signup & OTP request.
 *
 * Env-gated: unset TURNSTILE_SECRET_KEY -> no-op, so dev/test and existing
 * clients are unaffected until the secret is configured.
 */
import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';
import express from 'express';
import supertest from 'supertest';

const OLD_ENV = { ...process.env };
const realFetch = globalThis.fetch;

const load = async () => import('../../src/middleware/botProtection.js');

const appWith = (mw) => {
  const app = express();
  app.use(express.json());
  app.post('/x', mw, (req, res) => res.json({ ok: true }));
  return app;
};

describe('AUTH-M-05 · botProtection', () => {
  beforeEach(() => {
    process.env = { ...OLD_ENV };
    delete process.env.TURNSTILE_SECRET_KEY;
    jest.resetModules();
  });
  afterEach(() => {
    process.env = OLD_ENV;
    globalThis.fetch = realFetch;
  });

  it('is a no-op when TURNSTILE_SECRET_KEY is unset (no token needed)', async () => {
    const { botProtection } = await load();
    const res = await supertest(appWith(botProtection())).post('/x').send({ email: 'a@b.c' });
    expect(res.status).toBe(200);
  });

  it('403 BOT_CHECK_REQUIRED when configured but no token is sent', async () => {
    process.env.TURNSTILE_SECRET_KEY = 'secret';
    const { botProtection } = await load();
    const res = await supertest(appWith(botProtection())).post('/x').send({ email: 'a@b.c' });
    expect(res.status).toBe(403);
    expect(res.body.code).toBe('BOT_CHECK_REQUIRED');
  });

  it('passes with a valid token (provider says success)', async () => {
    process.env.TURNSTILE_SECRET_KEY = 'secret';
    globalThis.fetch = async () => ({ ok: true, json: async () => ({ success: true }) });
    const { botProtection } = await load();
    const res = await supertest(appWith(botProtection()))
      .post('/x')
      .send({ email: 'a@b.c', 'cf-turnstile-response': 'tok' });
    expect(res.status).toBe(200);
  });

  it('403 BOT_CHECK_FAILED on an invalid token', async () => {
    process.env.TURNSTILE_SECRET_KEY = 'secret';
    globalThis.fetch = async () => ({ ok: true, json: async () => ({ success: false, 'error-codes': ['invalid-input-response'] }) });
    const { botProtection } = await load();
    const res = await supertest(appWith(botProtection()))
      .post('/x')
      .send({ email: 'a@b.c', 'cf-turnstile-response': 'bad' });
    expect(res.status).toBe(403);
    expect(res.body.code).toBe('BOT_CHECK_FAILED');
  });

  it('fails OPEN (logged) when the provider is unreachable — spam control must not DoS signup', async () => {
    process.env.TURNSTILE_SECRET_KEY = 'secret';
    globalThis.fetch = async () => { throw new Error('down'); };
    const { botProtection } = await load();
    const res = await supertest(appWith(botProtection()))
      .post('/x')
      .send({ email: 'a@b.c', 'cf-turnstile-response': 'tok' });
    expect(res.status).toBe(200);
  });

  it('accepts the header carriage as well as the body field', async () => {
    process.env.TURNSTILE_SECRET_KEY = 'secret';
    globalThis.fetch = async () => ({ ok: true, json: async () => ({ success: true }) });
    const { botProtection } = await load();
    const res = await supertest(appWith(botProtection()))
      .post('/x')
      .set('cf-turnstile-response', 'tok')
      .send({ email: 'a@b.c' });
    expect(res.status).toBe(200);
  });
});

