    expect(res.status).toBe(409);
  });

  it('hides someone else\'s request behind a 404, not a 403', async () => {
    const mine = seed({ userId: OWNER });
    currentUser = asOther;

    const res = await supertest(app).get(`/api/deletion-requests/${mine._id}`);
