import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';

/**
 * F8 / F9: fail-open posture must be COUNTABLE, and Turnstile's outage
 * behaviour must be flippable to fail-closed.
 *
 * Both controls here deliberately fail open by default (spam control and
 * capacity control respectively - refusing everyone when Cloudflare or Redis
 * is down converts their outage into ours). The finding was that neither
 * failure was observable: you could be running unprotected for hours and only
 * a log grep would tell you. So the properties under test are:
 *
 *   1. Every fail-open increments `security_fail_open_total{control=...}`.
 *   2. A fail-open that is actually a REJECTED token (403) does NOT count -
 *      a correct rejection is not a control failure.
 *   3. TURNSTILE_STRICT=true turns the provider-outage path into a 503 and
 *      still counts the event.
 *   4. The tenant quota guard counts both of its pass-through paths (redis
 *      down, unexpected guard error).
 */

// Mutable flag so one test file can drive BOTH tenant-quota paths: redis
// unavailable (the common fail-open) and redis "up" but failing (the error
// path). Registered before any import, as ESM mocks require.
let redisUp = false;
jest.unstable_mockModule('../../src/config/redis.js', () => ({
  redisClient: {
    get isOpen() { return redisUp; },
    eval: jest.fn(() => Promise.reject(new Error('redis eval failed'))),
  },
  isRedisReady: () => redisUp,
}));

const { botProtection, isTurnstileStrict } = await import('../../src/middleware/botProtection.js');
const { tenantQuotaGuard } = await import('../../src/services/tenantQuotaService.js');
const { securityFailOpenTotal } = await import('../../src/lib/metrics.js');

const readCount = async (control) => {
  const data = await securityFailOpenTotal.get();
  const sample = data.values.find((v) => v.labels.control === control);
  return sample ? sample.value : 0;
};

const resMock = () => ({
  statusCode: 200,
  body: undefined,
  status(c) { this.statusCode = c; return this; },
  json(b) { this.body = b; return this; },
  setHeader() {},
});

const runBot = async (req) => {
  const res = resMock();
  let nexted = false;
  await botProtection()(req, res, () => { nexted = true; });
  return { nexted, res };
};

const botReq = (token = 'tok') => ({
  body: { 'cf-turnstile-response': token },
  headers: {},
  ip: '203.0.113.9',
});

let fetchSpy;

beforeEach(() => {
  redisUp = false;
  process.env.TURNSTILE_SECRET_KEY = 'test-secret';
  delete process.env.TURNSTILE_STRICT;
  // Default to a rejection so a test that forgets to stub cannot fire a REAL
  // request at Cloudflare (the call-through would eat a live 400 and flip the
  // posture being asserted).
  fetchSpy = jest.spyOn(globalThis, 'fetch').mockRejectedValue(new Error('fetch not stubbed'));
});

afterEach(() => {
  fetchSpy.mockRestore();
  delete process.env.TURNSTILE_SECRET_KEY;
  delete process.env.TURNSTILE_STRICT;
});

describe('F8: turnstile provider outage', () => {
  it('fails open (default) and counts the fail-open', async () => {
    fetchSpy.mockRejectedValue(new Error('ECONNREFUSED'));
    const before = await readCount('bot_protection');

    const { nexted } = await runBot(botReq());

    expect(nexted).toBe(true);
    expect(await readCount('bot_protection')).toBe(before + 1);
  });

  it('counts a provider HTTP failure too, not just network errors', async () => {
    fetchSpy.mockResolvedValue({ ok: false, status: 502 });
    const before = await readCount('bot_protection');

    const { nexted } = await runBot(botReq());

    expect(nexted).toBe(true);
    expect(await readCount('bot_protection')).toBe(before + 1);
  });

  it('TURNSTILE_STRICT=true fails CLOSED with 503 and still counts', async () => {
    process.env.TURNSTILE_STRICT = 'true';
    fetchSpy.mockRejectedValue(new Error('ECONNREFUSED'));
    const before = await readCount('bot_protection');

    const { nexted, res } = await runBot(botReq());

    expect(nexted).toBe(false);
    expect(res.statusCode).toBe(503);
    expect(res.body.code).toBe('BOT_CHECK_UNAVAILABLE');
    expect(await readCount('bot_protection')).toBe(before + 1);
  });

  it('a REJECTED token is a working control, not a fail-open - no count', async () => {
    fetchSpy.mockResolvedValue({
      ok: true,
      json: async () => ({ success: false, 'error-codes': ['invalid-input-response'] }),
    });
    const before = await readCount('bot_protection');

    const { nexted, res } = await runBot(botReq());

    expect(nexted).toBe(false);
    expect(res.statusCode).toBe(403);
    expect(res.body.code).toBe('BOT_CHECK_FAILED');
    expect(await readCount('bot_protection')).toBe(before);
  });

  it('a verified token passes without counting', async () => {
    fetchSpy.mockResolvedValue({ ok: true, json: async () => ({ success: true }) });
    const before = await readCount('bot_protection');

    const { nexted } = await runBot(botReq());

    expect(nexted).toBe(true);
    expect(await readCount('bot_protection')).toBe(before);
  });

  it('a missing token is still 403 regardless of strict mode', async () => {
    process.env.TURNSTILE_STRICT = '1';
    const before = await readCount('bot_protection');

    // No body field at all - botReq(undefined) would trigger the default param.
    const { nexted, res } = await runBot({ body: {}, headers: {}, ip: '203.0.113.9' });

    expect(nexted).toBe(false);
    expect(res.statusCode).toBe(403);
    expect(res.body.code).toBe('BOT_CHECK_REQUIRED');
    expect(await readCount('bot_protection')).toBe(before);
  });

  it('TURNSTILE_STRICT parses truthy spellings only', () => {
    for (const v of ['1', 'true', 'TRUE', 'yes', 'Yes']) {
      process.env.TURNSTILE_STRICT = v;
      expect(isTurnstileStrict()).toBe(true);
    }
    for (const v of ['', '0', 'false', 'no', 'on-when-the-mood-strikes']) {
      process.env.TURNSTILE_STRICT = v;
      expect(isTurnstileStrict()).toBe(false);
    }
    delete process.env.TURNSTILE_STRICT;
    expect(isTurnstileStrict()).toBe(false);
  });
});

describe('F9: tenant quota guard fail-open is counted', () => {
  const reqFor = () => ({
    user: { _id: 'u1', role: 'hospital_admin', hospitalId: 'h1' },
    originalUrl: '/api/appointments',
    url: '/api/appointments',
  });

  it('redis unavailable: passes through and counts', async () => {
    redisUp = false;
    const before = await readCount('tenant_quota');

    let nexted = false;
    await tenantQuotaGuard(reqFor(), resMock(), () => { nexted = true; });

    expect(nexted).toBe(true);
    expect(await readCount('tenant_quota')).toBe(before + 1);
  });

  it('redis up but failing: the catch path passes through and counts', async () => {
    redisUp = true;
    const before = await readCount('tenant_quota');

    let nexted = false;
    await tenantQuotaGuard(reqFor(), resMock(), () => { nexted = true; });

    expect(nexted).toBe(true);
    expect(await readCount('tenant_quota')).toBe(before + 1);
  });

  it('non-tenant traffic never reaches the fail-open paths', async () => {
    redisUp = false;
    const before = await readCount('tenant_quota');

    let nexted = false;
    await tenantQuotaGuard(
      { user: { _id: 'p1', role: 'patient' }, originalUrl: '/api/appointments', url: '' },
      resMock(),
      () => { nexted = true; }
    );

    expect(nexted).toBe(true);
    expect(await readCount('tenant_quota')).toBe(before);
  });
});

import { describe, it, expect } from '@jest/globals';
import {
  encryptField,
  decryptField,
  isEncrypted,
  blindIndex,
  getEncryptionKeyset,
} from '../../src/utils/fieldEncryption.js';

describe('Field-Level Encryption (AES-256-GCM)', () => {
  const secretDiagnosis = 'Patient diagnosed with Acute Major Depressive Episode with Psychotic Features';
  const aad = 'MentalHealth:rec_987654321';

  it('encrypts and decrypts correctly with matching AAD', () => {
    const ciphertext = encryptField(secretDiagnosis, aad);
    expect(isEncrypted(ciphertext)).toBe(true);
    expect(ciphertext).toMatch(/^v1:1:/);
    expect(ciphertext).not.toContain(secretDiagnosis);

    const decrypted = decryptField(ciphertext, aad);
    expect(decrypted).toBe(secretDiagnosis);
  });

  it('fails decryption when AAD is tampered (prevents record transplantation)', () => {
    const ciphertext = encryptField(secretDiagnosis, 'MentalHealth:doc_A');
    // Attempting to decrypt under doc_B
    expect(() => {
      decryptField(ciphertext, 'MentalHealth:doc_B');
    }).toThrow();
  });

  it('fails decryption when ciphertext payload is tampered', () => {
    const ciphertext = encryptField(secretDiagnosis, aad);
    const parts = ciphertext.split(':');
    // Tamper with ciphertext payload
    parts[4] = Buffer.from('tampered-payload').toString('base64');
    const tampered = parts.join(':');

    expect(() => {
      decryptField(tampered, aad);
    }).toThrow();
  });

  it('fails decryption when auth tag is tampered', () => {
    const ciphertext = encryptField(secretDiagnosis, aad);
    const parts = ciphertext.split(':');
    // Tamper with auth tag
    parts[3] = Buffer.from('badtag1234567890').toString('base64');
    const tampered = parts.join(':');

    expect(() => {
      decryptField(tampered, aad);
    }).toThrow();
  });

  it('handles objects with JSON serialization and parsing', () => {
    const sensitiveObj = {
      bankAccount: '123456789012',
      ifsc: 'HDFC0001234',
      kycVerified: true,
    };
    const ciphertext = encryptField(sensitiveObj, 'Bank:1');
    const decrypted = decryptField(ciphertext, 'Bank:1', true);
    expect(decrypted).toEqual(sensitiveObj);
  });

  it('passes unencrypted legacy data through unchanged for smooth migration', () => {
    const legacyPlaintext = 'Plain text diagnosis from 2024';
    expect(decryptField(legacyPlaintext, aad)).toBe(legacyPlaintext);
  });

  it('generates consistent blind index for identical values (case-insensitive)', () => {
    const idx1 = blindIndex('ABC-12345-XYZ', 'kyc_salt');
    const idx2 = blindIndex('abc-12345-xyz', 'kyc_salt');
    const idx3 = blindIndex('DIFF-VALUE', 'kyc_salt');

    expect(idx1).toBe(idx2);
    expect(idx1).not.toBe(idx3);
    expect(idx1).toMatch(/^[0-9a-f]{64}$/);
  });
});

import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';
import fs from 'node:fs';

/**
 * AUTH-F-06: mustResetPassword (temp-password) enforcement.
 *
 * The old check lived in the LOGIN route, before token issuance, so it (a)
 * never ran for google/2FA-issued tokens or sessions flagged after login and
 * (b) blocked PUT /auth/change-password itself - the one route that clears the
 * flag - making the account permanently stuck. Enforcement now lives in
 * `protect` as a session gate with a four-path exact allowlist.
 *
 * `protect` is unit-tested against the REAL middleware (only `User` and the
 * tenant quota guard are stubbed); a mounted-app harness would replace
 * `protect` with a header-driven stub and test nothing of this logic.
 */

const findById = jest.fn();
jest.unstable_mockModule('../../src/models/User.js', () => ({ default: { findById } }));
jest.unstable_mockModule('../../src/services/tenantQuotaService.js', () => ({
  tenantQuotaGuard: (_req, _res, next) => next(),
}));

process.env.JWT_SECRET = process.env.JWT_SECRET || 'f6-force-reset-test-secret';
delete process.env.JWT_KEYS;

const { protect, optionalProtect } = await import('../../src/middleware/auth.js');
const { signToken, resetKeysetCache } = await import('../../src/utils/jwtKeys.js');

const EXEMPT_PATHS = [
  '/api/auth/change-password',
  '/api/auth/logout',
  '/api/auth/logout-all',
  '/api/auth/me',
];

const makeUser = (over = {}) => ({
  _id: 'u1',
  role: 'patient',
  status: 'active',
  isVerified: true,
  tokenVersion: 0,
  mustResetPassword: true,
  name: 'Temp Account',
  email: 'temp@example.com',
  ...over,
});

const stubFindById = (user) =>
  findById.mockImplementation(() => ({ select: () => Promise.resolve(user) }));

const tokenFor = (claims = {}) =>
  signToken({ id: 'u1', typ: 'access', tv: 0, ...claims }, { expiresIn: '5m' });

const reqFor = (token, originalUrl = '/api/appointments') => ({
  cookies: {},
  headers: token ? { authorization: `Bearer ${token}` } : {},
  originalUrl,
});

const resMock = () => {
  const res = { statusCode: 200, body: null };
  res.status = (code) => {
    res.statusCode = code;
    return res;
  };
  res.json = (body) => {
    res.body = body;
    return res;
  };
  return res;
};

beforeEach(() => {
  resetKeysetCache();
  findById.mockReset();
  stubFindById(makeUser());
});

afterEach(() => {
  jest.restoreAllMocks();
});

describe('protect: a mustResetPassword session is locked to the allowlist', () => {
  it('403s PASSWORD_RESET_REQUIRED on an ordinary endpoint', async () => {
    const req = reqFor(tokenFor());
    const res = resMock();
    const next = jest.fn();

    await protect(req, res, next);

    expect(res.statusCode).toBe(403);
    expect(res.body).toMatchObject({
      code: 'PASSWORD_RESET_REQUIRED',
      mustResetPassword: true,
    });
    expect(next).not.toHaveBeenCalled();
    expect(req.user).toBeUndefined();
  });

  it.each(EXEMPT_PATHS)('allows %s so the flag can actually be cleared', async (path) => {
    const req = reqFor(tokenFor(), path);
    const res = resMock();
    const next = jest.fn();

    await protect(req, res, next);

    expect(next).toHaveBeenCalled();
    expect(res.statusCode).toBe(200);
    expect(req.user?._id).toBe('u1');
  });

  it('allows an exempt path with a query string', async () => {
    const req = reqFor(tokenFor(), '/api/auth/logout?force=1');
    const res = resMock();
    const next = jest.fn();

    await protect(req, res, next);

    expect(next).toHaveBeenCalled();
    expect(res.statusCode).toBe(200);
  });

  it('allows an exempt path with a trailing slash', async () => {
    const req = reqFor(tokenFor(), '/api/auth/change-password/');
    const res = resMock();
    const next = jest.fn();

    await protect(req, res, next);

    expect(next).toHaveBeenCalled();
    expect(res.statusCode).toBe(200);
  });

  it('rejects prefix-lookalike paths - the allowlist is exact, not a prefix match', async () => {
    for (const evil of ['/api/auth/change-password-evil', '/api/auth/change-passwordX', '/api/auth/me/../../appointments']) {
      const req = reqFor(tokenFor(), evil);
      const res = resMock();
      const next = jest.fn();

      await protect(req, res, next);

      expect(res.statusCode).toBe(403);
      expect(res.body?.code).toBe('PASSWORD_RESET_REQUIRED');
      expect(next).not.toHaveBeenCalled();
    }
  });

  it('does not gate a session that has already rotated its password', async () => {
    stubFindById(makeUser({ mustResetPassword: false }));
    const req = reqFor(tokenFor(), '/api/appointments');
    const res = resMock();
    const next = jest.fn();

    await protect(req, res, next);

    expect(next).toHaveBeenCalled();
    expect(res.statusCode).toBe(200);
    expect(req.user.mustResetPassword).toBe(false);
  });

  it('puts the flag on req.user so downstream handlers can react', async () => {
    const req = reqFor(tokenFor(), '/api/auth/me');
    const res = resMock();

    await protect(req, res, jest.fn());

    expect(req.user.mustResetPassword).toBe(true);
  });

  it('the gate runs AFTER the blocked-account check (blocked still wins)', async () => {
    stubFindById(makeUser({ status: 'blocked' }));
    const req = reqFor(tokenFor(), '/api/auth/me');
    const res = resMock();

    await protect(req, res, jest.fn());

    expect(res.statusCode).toBe(403);
    expect(res.body.message).toMatch(/blocked/i);
    expect(res.body?.code).not.toBe('PASSWORD_RESET_REQUIRED');
  });

  it('the gate runs BEFORE the unverified check (reset is reachable first)', async () => {
    stubFindById(makeUser({ isVerified: false }));
    const req = reqFor(tokenFor(), '/api/appointments');
    const res = resMock();

    await protect(req, res, jest.fn());

    expect(res.statusCode).toBe(403);
    expect(res.body?.code).toBe('PASSWORD_RESET_REQUIRED');
    expect(res.body?.requiresVerification).toBeUndefined();
  });
});

describe('optionalProtect: anonymous-but-flagged sessions degrade quietly', () => {
  it('detaches a mustResetPassword user instead of 403-ing public routes', async () => {
    const req = reqFor(tokenFor(), '/api/doctors');
