describe('IDOR - EHR search: the confused-deputy question', () => {
  it('lets a patient read their OWN record', async () => {
    expect((await assertEhrSearchAccess(req({ _id: 'patA', role: 'patient' }), 'patA')).ok).toBe(true);
  });

