  });
});

import { describe, it, expect, jest } from '@jest/globals';

/**
 * NOTIF-M-02 (preferences / quiet hours / DPDP split) and
 * NOTIF-M-06 (the audit trail).
 *
 * `decide()` and `inQuietHours()` are pure and are tested directly. The wiring
