    // age 28: 0, temp 37: 0, map 90: 0, hr 75: 0, rr 14: 0, pao2: 2, ph: 0, na: 0, k: 0, cr: 0, hct: 0, wbc: 0, gcs: 0, chronic: 0
    expect(res.apacheScore).toBe(2);
    expect(res.predictedMortalityPct).toBeGreaterThan(0);
