            { id: 'gender', type: 'select', label: 'Gender', options: ['Male', 'Female'], optionsHi: ['पुरुष', 'महिला'] },
            { id: 'notes', type: 'text', label: 'Clinical Notes' }, // no Hindi label provided, must fallback
