const chain = (rows) => {
  const q = { select: () => q, lean: async () => rows };
  return q;
};

const Q1 = new Date(2026, 0, 15); // Jan → Q1
const Q4 = new Date(2026, 10, 1); // Nov → Q4

beforeEach(() => {
  distinctMock.mockReset();
  findMock.mockReset();
  existsMock.mockReset();
  createMock.mockReset();
  findOneMock.mockReset();
  createMock.mockImplementation(async (doc) => ({ _id: 'rev1', ...doc }));
  existsMock.mockResolvedValue(false);
  findMock.mockReturnValue(chain([{ _id: 'a1' }, { _id: 'a2' }]));
  findOneMock.mockResolvedValue({ _id: 'admin1' });
  distinctMock.mockResolvedValue(['t1']);
});

describe('quarterCycle naming', () => {
  it('maps months to calendar quarters', () => {
    expect(sweep.quarterCycle(Q1)).toBe('2026-Q1-Certification');
    expect(sweep.quarterCycle(new Date(2026, 4, 1))).toBe('2026-Q2-Certification');
    expect(sweep.quarterCycle(new Date(2026, 7, 1))).toBe('2026-Q3-Certification');
    expect(sweep.quarterCycle(Q4)).toBe('2026-Q4-Certification');
  });
});

describe('runIamReviewCampaigns', () => {
  it('creates a campaign with every active assignment when none exists', async () => {
    const out = await sweep.runIamReviewCampaigns(Q1);
    expect(out).toEqual({ created: 1, skipped: 0, cycle: '2026-Q1-Certification' });
    expect(createMock).toHaveBeenCalledTimes(1);
    const doc = createMock.mock.calls[0][0];
    expect(String(doc.tenantId)).toBe('t1');
    expect(doc.cycle).toBe('2026-Q1-Certification');
    expect(String(doc.reviewerId)).toBe('admin1');
    expect(doc.items).toEqual([
      { assignmentId: 'a1', decision: 'pending', note: '' },
      { assignmentId: 'a2', decision: 'pending', note: '' },
    ]);
    // Reviewer lookup scoped to the tenant's own admins.
    const reviewerFilter = findOneMock.mock.calls[0][0];
    expect(reviewerFilter.$or).toEqual([{ hospitalId: 't1' }, { facilityId: 't1' }]);
    expect(reviewerFilter.role).toBe('hospital_admin');
  });

  it('is idempotent: skips tenants that already have this quarter campaign', async () => {
    existsMock.mockResolvedValue(true);
    const out = await sweep.runIamReviewCampaigns(Q1);
    expect(out.created).toBe(0);
    expect(out.skipped).toBe(1);
    expect(createMock).not.toHaveBeenCalled();
  });

  it('skips tenants with no active assignments', async () => {
    findMock.mockReturnValue(chain([]));
    const out = await sweep.runIamReviewCampaigns(Q1);
    expect(out).toMatchObject({ created: 0, skipped: 1 });
    expect(createMock).not.toHaveBeenCalled();
  });

  it('skips (never creates reviewer-less) when the tenant has no admin', async () => {
    findOneMock.mockResolvedValue(null);
    const out = await sweep.runIamReviewCampaigns(Q1);
    expect(out).toMatchObject({ created: 0, skipped: 1 });
    expect(createMock).not.toHaveBeenCalled();
  });

  it('one tenant blowing up does not stop the rest of the sweep', async () => {
    distinctMock.mockResolvedValue(['bad', 'good']);
    existsMock.mockImplementation(async ({ tenantId }) => {
      if (String(tenantId) === 'bad') throw new Error('index glitch');
      return false;
    });
    const out = await sweep.runIamReviewCampaigns(Q1);
    expect(out.created).toBe(1);
    expect(createMock).toHaveBeenCalledTimes(1);
    expect(String(createMock.mock.calls[0][0].tenantId)).toBe('good');
  });

  it('returns { created: 0 } when even the tenant listing fails', async () => {
    distinctMock.mockRejectedValue(new Error('connection reset'));
    const out = await sweep.runIamReviewCampaigns(Q1);
    expect(out).toMatchObject({ created: 0 });
  });

  it('creates nothing in a tenant-less world', async () => {
    distinctMock.mockResolvedValue([]);
    const out = await sweep.runIamReviewCampaigns(Q1);
    expect(out).toMatchObject({ created: 0, skipped: 0 });
    expect(createMock).not.toHaveBeenCalled();
  });
});

/**
 * DOC-M-07: incident & breach-notification playbook guard.
 *
 * The finding: DPDP requires breach-notification timelines, and we had only a
 * five-step summary in SECURITY.md §7 — no severity classes, no roles, no
 * notifiability decision rule, no clock table, no comms templates, no
 * post-mortem template. docs/incident-response.md is the deliverable; this
 * suite keeps it from rotting.
 *
 * A playbook fails in two ways: someone deletes a section under deadline
 * pressure (structure pins below stop that), or the law drifts and the clock
 * table silently lies (timeline pins stop that — they are the exact figures
 * from DPDP Rules 2025 Rule 7 and CERT-In Directions 20(3)/2022, so a legal
 * update must be a conscious edit here too). It also pins that the playbook
 * stays reachable from the two documents that point at breach response
 * (SECURITY.md §7, DPIA §9) and that it remains grounded in this codebase's
 * actual containment mechanisms rather than becoming generic advice.
 */
import { describe, it, expect } from '@jest/globals';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const REPO = path.join(HERE, '..', '..', '..');
const PLAYBOOK = path.join(REPO, 'docs', 'incident-response.md');
const SECURITY = path.join(REPO, 'SECURITY.md');
const DPIA = path.join(REPO, 'docs', 'privacy', 'DPIA.md');

const playbook = fs.readFileSync(PLAYBOOK, 'utf8');
const security = fs.readFileSync(SECURITY, 'utf8');
const dpia = fs.readFileSync(DPIA, 'utf8');

describe('playbook structure', () => {
  it('exists and carries every operational section', () => {
    expect(fs.existsSync(PLAYBOOK)).toBe(true);
    const required = [
      '## 1. Severity classification',
      '## 2. Roles and escalation',
      '## 3. First 15 minutes (checklist)',
      '## 4. Containment runbook by scenario',
      '## 5. Notifiability assessment (the decision that has a clock)',
      '## 6. Notification timelines and obligations',
      '## 7. Notification templates',
      '## 8. Evidence preservation checklist',
      '## 9. Post-mortem',
      '## 10. Drills and maintenance',
    ];
    for (const heading of required) {
      expect(playbook).toContain(heading);
    }
  });

  it('defines SEV1-SEV4 with a default-notifiable posture', () => {
    for (const sev of ['SEV1', 'SEV2', 'SEV3', 'SEV4']) {
      expect(playbook).toContain(sev);
    }
    expect(playbook).toMatch(/default answer to\s+question 4 is\s+\*\*notifiable\*\*/);
    expect(playbook).toContain('it never\nmoves'); // T0 is immutable
  });

  it('assigns the five incident roles and keeps contacts out of the repo', () => {
    for (const role of [
      'Incident Commander',
      'Tech Lead',
      'Privacy Officer',
      'Comms Lead',
      'Scribe',
    ]) {
      expect(playbook).toContain(role);
    }
    expect(playbook).toContain('incident/contacts'); // where real numbers live
    expect(playbook).toContain('Acknowledgement SLA');
  });
});

describe('timeline pins (DPDP Rules 2025 Rule 7 + CERT-In 20(3)/2022)', () => {
  it('pins the DPDP clocks', () => {
    expect(playbook).toContain('DPDP Rules 2025, Rule 7');
    expect(playbook).toMatch(/Board first intimation.*without delay|without delay.*Board first intimation/s);
    expect(playbook).toMatch(/≤ ?72 hours|72 hours.*Board/s);
    expect(playbook).toMatch(/7\(1\)/); // Data Principal intimation rule ref
    expect(playbook).toMatch(/7\(2\)/); // Board intimation rule ref
    expect(playbook).toContain('Data Protection Board');
    expect(playbook).toContain('notified 13 Nov 2025');
  });

  it('pins the CERT-In obligations', () => {
    expect(playbook).toContain('20(3)/2022');
    expect(playbook).toMatch(/6 hours/);
    expect(playbook).toContain('incident@cert-in.org.in');
    expect(playbook).toContain('180 days'); // log retention precondition
    expect(playbook).toContain('Annexure I');
    expect(playbook).toContain('Point of Contact');
    expect(playbook).toMatch(/noticing or being brought to notice|noticing, not at confirming/);
  });

  it('keeps the HIPAA contingency windows', () => {
    expect(playbook).toMatch(/≤ ?60 days/);
    expect(playbook).toContain('§164.400');
  });
});

describe('templates', () => {
  it('ships all seven send-ready templates with placeholders', () => {
    const templates = [
      'Board — first intimation',
      'Board — detailed report',
      'Affected Data Principal notice',
      'CERT-In — preliminary incident report',
      'HIPAA individual notice',
      'Internal all-hands / status-page holding statement',
      'Hospital tenant notice',
    ];
    for (const t of templates) expect(playbook).toContain(t);
    expect(playbook).toContain('[BRACKETS]');
    // Rule 7(1) five content elements must be in the Data Principal template
    for (const el of ['consequences', 'safety measures', 'contact person']) {
      expect(playbook.toLowerCase()).toContain(el);
    }
    // Rule 7(2)(b)(vi) requires the send log, so the template demands one
    expect(playbook).toContain('send log');
  });

  it('post-mortem template carries the notification-compliance table', () => {
    expect(playbook).toContain('## Notification compliance');
    expect(playbook).toContain('Board detailed report | T0 + 72h');
    expect(playbook).toContain('CERT-In (if Annexure I) | T0 + 6h');
    expect(playbook).toContain('Regression test');
    expect(playbook).toContain('5 business days');
  });
});

describe('codebase grounding', () => {
  it('names the containment mechanisms that actually exist here', () => {
    for (const token of [
      'JWT_SECRET',
      'User.tokenVersion',
      'RefreshToken',
      'AuditLog',
      'LoginEvent',
      'DeletionRequest', // erasure hold — evidence destruction guard
      'bulk_export',
      'refresh-token', // or refresh token revocation
    ]) {
      expect(playbook).toContain(token);
    }
    expect(playbook).toContain('docs/data-dictionary.md'); // blast radius via the generated dictionary
    expect(playbook).toContain('X-Export-Truncated');
  });

  it('stays reachable from SECURITY.md and DPIA.md', () => {
    expect(security).toContain('docs/incident-response.md');
    expect(dpia).toContain('incident-response.md');
    expect(security).toContain('72 hours'); // §7 summary updated to the real clock
    expect(security).toContain('6 hours');
  });
});

import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { assertBackupImagePolicy, isImmutableImageDigest } from '../../scripts/check-backup-image-policy.mjs';
import { writeAuditArtifact } from '../../scripts/lib/auditArtifact.mjs';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..');

describe('INF-B-04 backup image policy', () => {
  const compose = fs.readFileSync(path.join(REPO, 'infra', 'docker-compose.prod.yml'), 'utf8');

  it('requires backup and restore drill to share the mandatory immutable image variable', () => {
    expect(assertBackupImagePolicy(compose)).toBe(true);
    expect(assertBackupImagePolicy(compose, `ghcr.io/findmedi/backup@sha256:${'a'.repeat(64)}`)).toBe(true);
  });

  it('rejects floating tags, malformed digests, and a drifted drill image', () => {
    expect(isImmutableImageDigest('findmedi/backup:latest')).toBe(false);
    expect(isImmutableImageDigest(`findmedi/backup@sha256:${'A'.repeat(64)}`)).toBe(false);
    expect(() => assertBackupImagePolicy(compose, 'findmedi/backup:ci')).toThrow(/immutable/);
    const changed = compose.replace(/(backup-drill:\r?\n)[ ]{4}image: .+/, '$1    image: findmedi/backup:latest');
    expect(() => assertBackupImagePolicy(changed)).toThrow(/backup-drill.image/);
  });
});

describe('INF-B-04 restore-drill evidence archive', () => {
  it('archives a per-drill JSON evidence record with the offsite artifacts', () => {
    const drill = fs.readFileSync(path.join(REPO, 'infra', 'backup', 'restore-drill.sh'), 'utf8');
    expect(drill).toContain('drill-evidence-');
    expect(drill).toContain('"verdict": "PASSED"');
    expect(drill).toContain('elapsed_min');
    expect(drill).toContain('rto_budget_min');
    expect(drill).toContain('image_digest');
    // Evidence lands where the backups go (offsite-copied), not in /tmp.
    expect(drill).toMatch(/EVIDENCE_FILE="\$\{ARTIFACT_DIR\}/);
  });
});

describe('INF-M-01 + INF-B-06 deployment digest and provenance', () => {
  it('every k8s image is digest-pinned, never a floating tag', () => {
    const core = fs.readFileSync(path.join(REPO, 'infra', 'k8s', 'core.yaml'), 'utf8');
    const images = [...core.matchAll(/^\s*image:\s*(\S+)\s*$/gm)].map((m) => m[1]);
    expect(images.length).toBeGreaterThan(0);
    for (const image of images) {
      expect(isImmutableImageDigest(image)).toBe(true);
    }
    expect(core).not.toMatch(/image:\s*\S+:latest/);
  });

  it('deploys only through environment approvals from a releasable ref (provenance)', () => {
    const deploy = fs.readFileSync(path.join(REPO, '.github', 'workflows', 'deploy.yml'), 'utf8');
    // Human approval gate: the job blocks until the environment approver clicks.
    expect(deploy).toContain('environment: ${{ inputs.target }}');
    // Provenance: only a vX.Y.Z tag or main-descendant ref may deploy, deploys
    // queue instead of cancelling each other, and the target must prove liveness.
    expect(deploy).toContain("git tag -l 'v*'");
    expect(deploy).toContain('cancel-in-progress: false');
    expect(deploy).toContain('Post-deploy health probe');
  });
});

describe('INF-M-05 audit evidence artifacts', () => {
  it('writes parseable backend/frontend npm audit JSON using predictable artifact names', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'findmedi-audit-artifact-'));
    try {
      const audit = { metadata: { vulnerabilities: { total: 0 } }, vulnerabilities: {} };
      const backendFile = writeAuditArtifact(dir, 'backend', audit);
      const frontendFile = writeAuditArtifact(dir, 'frontend', audit);
      expect(path.basename(backendFile)).toBe('backend-npm-audit.json');
      expect(path.basename(frontendFile)).toBe('frontend-npm-audit.json');
      expect(JSON.parse(fs.readFileSync(backendFile, 'utf8'))).toEqual(audit);
      expect(JSON.parse(fs.readFileSync(frontendFile, 'utf8'))).toEqual(audit);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });

  it('uploads audit JSON even when the vulnerability ratchet fails', () => {
    const workflow = fs.readFileSync(path.join(REPO, '.github', 'workflows', 'ci.yml'), 'utf8');
    expect(workflow).toContain('VULN_AUDIT_ARTIFACT_DIR: ${{ runner.temp }}/findmedi-vulnerability-audit');
    // SITE-SEC 1.3: actions are SHA-pinned (the tag travels in a comment).
    expect(workflow).toMatch(/actions\/upload-artifact@[0-9a-f]{40} # v7/);
    expect(workflow).toContain('if: always()');
    expect(workflow).toContain('findmedi-vulnerability-audit/*.json');
    expect(workflow).toContain('retention-days: 30');
  });
});

