function nearbyRider(id, updatedAt, distanceMeters = 1200) {
  return {
    _id: `profile-${id}`,
    userId: `user-${id}`,
    riderStatus: 'active',
    isOnline: true,
    activeDispatchRequestId: null,
    currentLocation: { type: 'Point', coordinates: [72, 19], updatedAt },
