import { describe, it, expect } from '@jest/globals';
import {
  signFileUrl, verifyFileUrlSignature, SIGNED_FILE_TTL_SECONDS,
} from '../../src/utils/signedFileUrl.js';

// 2.md 5 — signed short-lived preview links for the private application
// uploads. Pure crypto: no models, no clock beyond injectable `now`.

const PATH = '/uploads/documents/abc123.pdf';
const USER = '7000000000000000000000f5';
const OTHER_USER = '7000000000000000000000f1';

const parts = (url) => Object.fromEntries(new URLSearchParams(String(url).split('?')[1]));

describe('signedFileUrl', () => {
  it('round-trips a fresh signature for the exact path + user', () => {
    const url = signFileUrl(PATH, { userId: USER });
    expect(url.startsWith(`${PATH}?exp=`)).toBe(true);
    const { exp, sig } = parts(url);
    expect(sig).toMatch(/^[0-9a-f]{64}$/);
    expect(verifyFileUrlSignature({ path: PATH, exp, sig, userId: USER })).toBe(true);
  });

  it('expires after the default short TTL', () => {
    const { exp } = parts(signFileUrl(PATH, { userId: USER }));
    expect(Number(exp) - Math.floor(Date.now() / 1000)).toBe(SIGNED_FILE_TTL_SECONDS);
    expect(SIGNED_FILE_TTL_SECONDS).toBeLessThanOrEqual(900); // "short-lived" stays short
  });

  it('rejects an expired signature', () => {
    const stale = parts(signFileUrl(PATH, { userId: USER, ttlSeconds: 60, now: Date.now() - 120_000 }));
    expect(verifyFileUrlSignature({ path: PATH, ...stale, userId: USER })).toBe(false);
  });

  it('rejects another user — a copied link is useless to anyone else', () => {
    const { exp, sig } = parts(signFileUrl(PATH, { userId: USER }));
    expect(verifyFileUrlSignature({ path: PATH, exp, sig, userId: OTHER_USER })).toBe(false);
  });

  it('rejects a transplanted path — one file never signs for another', () => {
    const { exp, sig } = parts(signFileUrl(PATH, { userId: USER }));
    expect(verifyFileUrlSignature({ path: '/uploads/documents/OTHER.pdf', exp, sig, userId: USER })).toBe(false);
    expect(verifyFileUrlSignature({ path: '/uploads/reports/leak.pdf', exp, sig, userId: USER })).toBe(false);
  });

  it('rejects tampered exp or sig values', () => {
    const { exp, sig } = parts(signFileUrl(PATH, { userId: USER }));
    const future = String(Number(exp) + 3600);
    expect(verifyFileUrlSignature({ path: PATH, exp: future, sig, userId: USER })).toBe(false);
    expect(verifyFileUrlSignature({ path: PATH, exp, sig: sig.replace(/^./, sig[0] === 'a' ? 'b' : 'a'), userId: USER })).toBe(false);
  });

  it('fails closed on missing or malformed inputs', () => {
    const { exp, sig } = parts(signFileUrl(PATH, { userId: USER }));
    expect(verifyFileUrlSignature({ path: PATH, exp: undefined, sig: undefined, userId: USER })).toBe(false);
    expect(verifyFileUrlSignature({ path: PATH, exp: 'soon', sig, userId: USER })).toBe(false);
    expect(verifyFileUrlSignature({ path: PATH, exp, sig: 'short', userId: USER })).toBe(false);
    expect(verifyFileUrlSignature({ path: PATH, exp, sig, userId: undefined })).toBe(false);
    expect(verifyFileUrlSignature({ path: '', exp, sig, userId: USER })).toBe(false);
  });

  it('refuses to sign anything outside the private upload paths', () => {
    expect(signFileUrl('/etc/passwd', { userId: USER })).toBe('/etc/passwd');
    expect(signFileUrl('/uploads/../secrets.env', { userId: USER })).toBe('/uploads/../secrets.env');
    expect(signFileUrl('', { userId: USER })).toBe('');
    const { exp, sig } = parts(signFileUrl(PATH, { userId: USER }));
    expect(verifyFileUrlSignature({ path: '/uploads/../secrets.env', exp, sig, userId: USER })).toBe(false);
  });
});

// Browse-by-Specialties taxonomy invariants (subcatogary.md v2 rules):
// §4 de-dup via canonical single-record cross-lists, legacy code aliases,
// PSURG→PAEDSURG rename, and the §2/§3 browse meta (groups, chips, symptoms).
import { describe, it, expect } from '@jest/globals';import {
  SPECIALTIES,
  SPECIALTY_GROUPS,
  SPEC_CODE_ALIASES,
  buildSpecialtyTree,
  buildSpecialtyGroups,
  resolveSpecialty,
  resolveSpecialtyCode,
  remapSubSpecialtyCode,
  remapSubSpecialtyCodes,
  isTopLevelSpecialty,
} from '../../src/lib/taxonomy.js';

const tops = SPECIALTIES.filter(isTopLevelSpecialty);
const tree = buildSpecialtyTree();
const treeByCode = new Map(tree.map((t) => [t.code, t]));

describe('Browse-by-Specialties: catalogue shape', () => {
  it('has exactly 43 top-level tiles and 13 browse groups', () => {
    expect(tops.length).toBe(43);
    expect(buildSpecialtyGroups().length).toBe(13);
  });

  it('leaves no top-level tile without children in the tree', () => {
    const childless = tree.filter((top) => top.children.length === 0);
    expect(childless.map((t) => t.code)).toEqual([]);
  });

  it('gives every tile complete browse meta (group, icon, chips, symptoms)', () => {
    for (const top of tops) {
      expect(top.meta).toBeTruthy();
      expect(SPECIALTY_GROUPS.some((g) => g.id === top.meta.group)).toBe(true);
      expect(top.meta.icon.length).toBeGreaterThan(0);
      expect(top.meta.conditions.length).toBeGreaterThan(0);
      expect(top.meta.procedures.length).toBeGreaterThan(0);
      expect(top.meta.symptoms.length).toBeGreaterThan(0);
    }
  });

  it('flags the four sensitive tiles 🔒 (Psychiatry, Sexology, Infertility, Palliative)', () => {
    const sensitive = tops.filter((t) => t.meta.sensitive).map((t) => t.code).sort();
    expect(sensitive).toEqual(['SPEC.INFERT', 'SPEC.PALLI', 'SPEC.PSYCH', 'SPEC.SEXO'].sort());
  });

  it('keeps claims-restricted ⚠ flags on cosmetic/hair/weight-loss/IVF nodes', () => {
    const restricted = SPECIALTIES.filter((s) => s.claimsRestricted).map((s) => s.code);
    expect(restricted).toEqual(
      expect.arrayContaining([
        'SPEC.DERM.COSMETIC', 'SPEC.DERM.TRICHOLOGY', 'SPEC.DERM.LASER',
        'SPEC.INFERT.IVF', 'SPEC.GENSURG.BARIATRIC',
      ]),
    );
    const restrictedTops = tops.filter((t) => t.meta.adClaimsRestricted).map((t) => t.code);
    expect(restrictedTops).toEqual(expect.arrayContaining(['SPEC.PLASTSURG', 'SPEC.SEXO', 'SPEC.INFERT']));
  });
});

describe('Browse-by-Specialties: §4 de-dup + cross-lists', () => {
  it('resolves every legacy duplicate code to its canonical record', () => {
    const cases = {
      'SPEC.PAED.NEONATO': 'SPEC.NEONATO',
      'SPEC.PAED.CARDIOLOGY': 'SPEC.CARDIO.PAED',
      'SPEC.PAED.SURGERY': 'SPEC.PAEDSURG',
      'SPEC.PSURG.NEONATAL': 'SPEC.PAEDSURG.NEONATAL',
      'SPEC.PSURG.UROLOGY': 'SPEC.PAEDSURG.UROLOGY',
      'SPEC.PSURG.ONCOLOGY': 'SPEC.PAEDSURG.ONCOLOGY',
      'SPEC.CTVS.VASCULAR': 'SPEC.VASC',
      'SPEC.OBGY.INFERT_IVF': 'SPEC.INFERT',
      'SPEC.GASTRO.HEPATOLOGY': 'SPEC.HEPAT',
      'SPEC.PULMO.SLEEP': 'SPEC.SLEEP',
      'SPEC.PSYCH.SLEEP': 'SPEC.SLEEP',
      'SPEC.URO.ANDROLOGY': 'SPEC.SEXO',
      'SPEC.URO.SEXUAL_HEALTH': 'SPEC.SEXO',
    };
    for (const [legacy, canonical] of Object.entries(cases)) {
      expect(SPEC_CODE_ALIASES[legacy]).toBe(canonical);
      expect(resolveSpecialty(legacy)?.code).toBe(canonical);
    }
  });

  it('no longer contains the duplicate records themselves', () => {
    for (const legacyCode of Object.keys(SPEC_CODE_ALIASES)) {
      expect(SPECIALTIES.some((s) => s.code === legacyCode)).toBe(false);
    }
  });

  it('cross-lists render the same record under every secondary parent (alsoUnder)', () => {
    // Neonatology under Paediatrics, Sports under Ortho, IVF under OBGY...
    expect(treeByCode.get('SPEC.PAED').children.map((c) => c.code)).toContain('SPEC.NEONATO');
    expect(treeByCode.get('SPEC.PAED').children.map((c) => c.code)).toContain('SPEC.PAEDSURG');
    expect(treeByCode.get('SPEC.ORTHO').children.map((c) => c.code)).toContain('SPEC.SPORTS');
    expect(treeByCode.get('SPEC.OBGY').children.map((c) => c.code)).toContain('SPEC.INFERT');
    expect(treeByCode.get('SPEC.GASTRO').children.map((c) => c.code)).toContain('SPEC.HEPAT');
    expect(treeByCode.get('SPEC.URO').children.map((c) => c.code)).toContain('SPEC.SEXO');
    // A cross-listed record must KNOW both parents, but carry one identity.
    const haemOnc = SPECIALTIES.find((s) => s.code === 'SPEC.PAED.HAEM_ONC');
    expect(haemOnc.alsoUnder).toEqual(expect.arrayContaining(['SPEC.ONCO', 'SPEC.HAEM']));
  });

  it('dedupes and remaps doctor sub-specialty code arrays', () => {
    expect(remapSubSpecialtyCode('SPEC.PAED.NEONATO')).toBe('SPEC.NEONATO');
    expect(remapSubSpecialtyCode('spec.ctvs.vascular')).toBe('SPEC.VASC');
    expect(remapSubSpecialtyCode('not a code')).toBe('not a code');
    // SPEC.ORTHO.SPORTS is canonical now, so remap leaves it untouched
    expect(remapSubSpecialtyCode('SPEC.ORTHO.SPORTS')).toBe('SPEC.SPORTS');
    expect(
      remapSubSpecialtyCodes(['SPEC.PULMO.SLEEP', 'SPEC.SLEEP', 'SPEC.PSURG.ONCOLOGY', 'SPEC.PULMO.SLEEP']),
    ).toEqual(['SPEC.SLEEP', 'SPEC.PAEDSURG.ONCOLOGY']);
  });
});

describe('Browse-by-Specialties: §5 alias + symptom search', () => {
  it('resolves spellings the checklist calls out', () => {
    expect(resolveSpecialtyCode('Orthopedics')).toBe('SPEC.ORTHO');
    expect(resolveSpecialtyCode('Orthopaedics')).toBe('SPEC.ORTHO');
    expect(resolveSpecialtyCode('bone doctor')).toBe('SPEC.ORTHO');
  });

  it('maps IVF phrasing to the canonical Infertility record (not a stale dup)', () => {
    expect(resolveSpecialtyCode('IVF Specialist')).toBe('SPEC.INFERT');
    expect(resolveSpecialtyCode('Fertility Specialist')).toBe('SPEC.INFERT');
  });
});

/**
 * 7.md 3 specialty-vertical roles — the auth-surface half of the roles slice.
 *
 * What it pins (change-detector by design: ANY edit to these lists breaks
 * this spec on purpose, forcing the author to re-justify the privilege):
 *  - the matrix is complete (assertRoleMatrixComplete) and every User.role
 *    enum value is canonical (an alias would deny it everything);
 *  - every canonical role is accepted by the login role hint;
 *  - exact permission sets for the new roles — least-privilege regression net
 *    against future creep (a vendor must never gain records:write by accident);
 *  - new facility roles are NOT in MANDATORY_TWO_FACTOR_ROLES (facility scope,
 *    env-driven like hospital_admin — platform-wide ops roles only);
 *  - PractitionerProfile.roleType is exactly the original nine plus the two
 *    spec-grounded additions (ayush_practitioner, phlebotomist);
 *  - TENANT_STAFF_ROLES admits exactly the facility-inside roles (vendors,
 *    instructors, organizers, reviewers stay out and fail closed).
 */
import { describe, it, expect } from '@jest/globals';
import mongoose from 'mongoose';
import {
  CANONICAL_ROLES, MANDATORY_TWO_FACTOR_ROLES, ROLE_PERMISSIONS,
  assertRoleMatrixComplete,
} from '../../src/config/permissions.js';
import { USER_ROLE_OPTIONS } from '../../src/utils/validate.js';
import { TENANT_STAFF_ROLES } from '../../src/utils/tenantScope.js';

const importModel = async (path, name) => {
  const mod = await import(path);
  return mod.default ?? mongoose.model(name);
};
const enumValues = (model, path) => model.schema.path(path).enumValues ?? [];

const NEW_ROLES = [
  'dentist', 'dental_clinic_admin',
  'optician', 'optical_shop_owner',
  'phlebotomist', 'home_nursing_admin',
  'yoga_instructor', 'yoga_studio_admin', 'gym_owner', 'trainer',
  'wellness_admin', 'therapist',
  'equipment_vendor', 'product_vendor',
  'event_organizer', 'ngo_admin', 'group_host', 'trainer_org',
  'blood_bank_admin', 'dialysis_admin', 'fertility_admin',
  'maternity_admin', 'rehab_admin', 'govt_facility_staff',
  'tpa_agent', 'medical_reviewer',
];

describe('7.md 3 specialty roles', () => {
  it('keeps the matrix complete and the enum canonical', () => {
    expect(() => assertRoleMatrixComplete(ROLE_PERMISSIONS)).not.toThrow();
    expect(CANONICAL_ROLES).toEqual(expect.arrayContaining(NEW_ROLES));
  });

  it('admits every User.role spelling (enum, canonical list, login hint agree)', async () => {
    const User = await importModel('../../src/models/User.js', 'User');
    const modelRoles = enumValues(User, 'role');
    // The three counselor aliases are pre-save-migrated to `counsellor` and
    // resolved by canonicalRole() — they are valid rows but not canonical
    // roles, by design (see the User.js enum comment).
    const LEGACY_ALIASES = ['counselor', 'mid_level_counselor', 'senior_counselor'];
    for (const role of modelRoles) {
      if (LEGACY_ALIASES.includes(role)) continue;
      expect(CANONICAL_ROLES).toContain(role);
    }
    for (const role of CANONICAL_ROLES) {
      expect(USER_ROLE_OPTIONS).toContain(role);
    }
  });

  it('pins the new clinical and desk sets exactly', () => {
    expect([...ROLE_PERMISSIONS.dentist].sort()).toEqual([
      'appointments:read', 'appointments:write', 'chat:read', 'chat:write',
      'notifications:read', 'patients:read', 'prescriptions:write',
      'profile:read', 'profile:write', 'radiology:order', 'radiology:read', 'records:read',
      'records:write', 'upload:write',
    ].sort());
    expect([...ROLE_PERMISSIONS.tpa_agent].sort()).toEqual([
      'billing:read', 'chat:read', 'chat:write', 'insurance:read',
      'insurance:write', 'notifications:read',
    ].sort());
    expect([...ROLE_PERMISSIONS.phlebotomist].sort()).toEqual([
      'lab:book', 'lab:read', 'notifications:read',
    ].sort());
    expect([...ROLE_PERMISSIONS.govt_facility_staff].sort()).toEqual([
      'appointments:read', 'chat:read', 'chat:write', 'notifications:read',
      'patients:read',
    ].sort());
    expect([...ROLE_PERMISSIONS.medical_reviewer].sort()).toEqual([
      'content:read', 'content:write', 'notifications:read',
    ].sort());
  });

  it('pins the vendor and admin sets exactly (no clinical strings)', () => {
    for (const role of ['equipment_vendor', 'product_vendor']) {
      expect(ROLE_PERMISSIONS[role]).toContain('inventory:manage');
      expect(ROLE_PERMISSIONS[role]).not.toContain('records:write');
      expect(ROLE_PERMISSIONS[role]).not.toContain('records:read');
    }
    // dental_clinic_admin additionally carries records:read/write (7.md:3.1
    // co-managed clinical documentation) — effective only through
    // provider-ownership-guarded dental routes, never cross-tenant.
    expect([...ROLE_PERMISSIONS.dental_clinic_admin].sort()).toEqual([
      'appointments:read', 'appointments:write', 'billing:read',
      'chat:read', 'chat:write', 'notifications:read', 'patients:read',
      'records:read', 'records:write', 'reports:read', 'staff:manage',
    ].sort());
    for (const role of ['blood_bank_admin', 'dialysis_admin', 'fertility_admin', 'maternity_admin', 'rehab_admin']) {
      expect([...ROLE_PERMISSIONS[role]].sort()).toEqual([
