/**
 * MISS-AUTHZ-001 regression: `staff:view` is the read counterpart of
 * `staff:manage` (safety/frontoffice/roster/quality/masters/insights/
 * contactCenter/reportStudio all pair `authorize('staff:view')` LIST routes
 * with `authorize('staff:manage')` writes in the same file). It was referenced
 * by 47 route call sites while NO non-superadmin role held it, so every
 * non-superadmin got a permanent 403 on those lists and the
 * checkPermissionMatrix.mjs CI gate failed.
 *
 * The HTTP harness substitutes authorize() with a pass-through marker
 * (appHarness.js), so an integration spec cannot prove permission GRANTS.
 * This spec pins them at the matrix level instead, and re-runs the gate's
 * reachability check over the previously-broken route files so the exact
 * failure cannot come back unnoticed.
 */
import { describe, it, expect } from '@jest/globals';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  ROLE_PERMISSIONS, CANONICAL_ROLES, roleHasPermission,
} from '../../src/config/permissions.js';
import { stripComments } from '../../scripts/lib/routeScan.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const BACKEND = path.join(HERE, '..', '..');
const ROUTES = path.join(BACKEND, 'src', 'routes');

const WORKING_ROLES = CANONICAL_ROLES.filter((r) => r !== 'superadmin');

const authorizeLiterals = (file) => {
  const lines = stripComments(fs.readFileSync(path.join(ROUTES, file), 'utf8')).split('\n');
  const perms = [];
  lines.forEach((line, i) => {
    const at = line.indexOf('authorize(');
    if (at === -1) return;
    const args = line.slice(at + 'authorize('.length);
    const end = args.indexOf(')');
    const argText = end === -1 ? args : args.slice(0, end);
    for (const m of argText.matchAll(/'([^']+)'|"([^"]+)"/g)) {
      perms.push({ perm: m[1] || m[2], site: `${file}:${i + 1}` });
    }
  });
  return perms;
};

const holdersOf = (perm) => WORKING_ROLES.filter((role) => roleHasPermission(role, perm));

describe('staff:view permission hole (MISS-AUTHZ-001)', () => {
  test('every permission the previously-broken list routes require is held by a real role', () => {
    const unreachable = [];
    for (const file of ['safety.js', 'frontoffice.js', 'roster.js']) {
      const used = authorizeLiterals(file);
      expect(used.length).toBeGreaterThan(0);
      for (const { perm, site } of used) {
        if (holdersOf(perm).length === 0) unreachable.push(`${site}  ${perm}`);
      }
    }
    expect(unreachable).toEqual([]);
  });

  test('staff:view is held by the roles that were permanently 403ed on the lists', () => {
    for (const role of [
      'hospital_admin', 'quality_officer', 'nursing_supervisor', 'matron',
      'front_desk', 'receptionist', 'hr_manager', 'infection_control_nurse',
      'medical_records_officer', 'call_center_agent', 'clinic_admin',
    ]) {
      expect(ROLE_PERMISSIONS[role]).toContain('staff:view');
      expect(roleHasPermission(role, 'staff:view')).toBe(true);
    }
  });

  test('nurse family can request shift swaps (roster POST /swaps is staff:view)', () => {
    expect(roleHasPermission('ward_nurse', 'staff:view')).toBe(true);
    expect(roleHasPermission('icu_nurse', 'staff:view')).toBe(true);
  });

  test('staff:view stays least-privilege: self-service and fenced roles do not hold it', () => {
    for (const role of ['patient', 'helper', 'cashier', 'support_agent', 'auditor']) {
      expect(roleHasPermission(role, 'staff:view')).toBe(false);
    }
  });

  test('front_desk still mirrors receptionist exactly', () => {
    expect([...ROLE_PERMISSIONS.front_desk].sort()).toEqual([...ROLE_PERMISSIONS.receptionist].sort());
  });

  test('records:amend (AI human-review decide) is held by a real role', () => {
    expect(ROLE_PERMISSIONS.hospital_admin).toContain('records:amend');
    expect(holdersOf('records:amend').length).toBeGreaterThan(0);
  });
});

import { readFileSync } from 'node:fs';
import { calculatePf, calculateEsi, calculateGratuity, calculateTds, resolveStatutoryVersion, getStatutoryVersionMeta } from '../../src/services/statutoryEngine.js';
import { checkDrugInteractions, checkDrugInteractionsDetailed } from '../../src/services/ddiEngine.js';

describe('Wave 4 Unit Specs — Statutory & DDI Engines', () => {
  describe('Statutory Engine', () => {
    test('calculatePf computes correct 12% contribution with ₹1800 cap', () => {
      // Basic 10,000 + DA 2,000 = 12,000 (<= 15,000)
      const resBelow = calculatePf(10000, 2000);
      expect(resBelow.pfWage).toBe(12000);
      expect(resBelow.employeePf).toBe(1440);
      expect(resBelow.employerPf).toBe(1440);

      // Basic 25,000 + DA 5,000 = 30,000 (> 15,000 wage ceiling) -> capped at 1,800
      const resAbove = calculatePf(25000, 5000);
      expect(resAbove.pfWage).toBe(30000);
      expect(resAbove.employeePf).toBe(1800);
    });

    test('calculateEsi applies 0.75% employee and 3.25% employer if wage <= 21,000', () => {
      const eligible = calculateEsi(20000);
      expect(eligible.isEligible).toBe(true);
      expect(eligible.employeeEsi).toBe(150); // 20000 * 0.0075
      expect(eligible.employerEsi).toBe(650); // 20000 * 0.0325

      const ineligible = calculateEsi(25000);
      expect(ineligible.isEligible).toBe(false);
      expect(ineligible.employeeEsi).toBe(0);
      expect(ineligible.employerEsi).toBe(0);
    });

    test('calculateGratuity requires minimum 5 years tenure', () => {
      const underFive = calculateGratuity(30000, 4);
      expect(underFive.isEligible).toBe(false);
      expect(underFive.gratuityAmount).toBe(0);

      // 6 years: (15 / 26) * 30,000 * 6 = 103,846
      const eligible = calculateGratuity(30000, 6);
      expect(eligible.isEligible).toBe(true);
      expect(eligible.gratuityAmount).toBe(Math.round((15 / 26) * 30000 * 6));
    });

    test('calculateTds handles new tax regime slabs', () => {
      // Annual income 6,00,000 -> eligible for full 87A rebate
      const rebateRes = calculateTds(600000);
      expect(rebateRes.annualTax).toBe(0);
      expect(rebateRes.monthlyTds).toBe(0);

      // Annual income 24,00,000 -> tax calculated across slabs + 4% cess
      const highRes = calculateTds(2400000);
      expect(highRes.taxableIncome).toBe(2400000 - 75000);
      expect(highRes.annualTax).toBeGreaterThan(0);
      expect(highRes.monthlyTds).toBe(Math.round(highRes.annualTax / 12));
    });

    // T4 (file 31): FY-versioned statutory config — payroll month decides
    // which rules apply, so arrears/backdated runs stay correct.
    test('resolveStatutoryVersion picks FY by payroll month (boundary 2026-04-01)', () => {
      const mar = resolveStatutoryVersion('2026-03-31');
      const apr = resolveStatutoryVersion('2026-04-01');
      expect(mar.fy).toBe('2025-26');
      expect(apr.fy).toBe('2026-27');
      expect(resolveStatutoryVersion(new Date('2026-07-15')).fy).toBe('2026-27');
      // Default (no arg) = current version in force
      expect(resolveStatutoryVersion().fy).toBe('2026-27');
    });

    test('getStatutoryVersionMeta reports sign-off status for payslip/audit', () => {
      const meta = getStatutoryVersionMeta('2026-06-01');
      expect(meta.fy).toBe('2026-27');
      expect(meta.effectiveFrom).toBe('2026-04-01');
      // FY 2026-27 must stay unverified until a CA signs off
      expect(meta.verified).toBe(false);
      expect(meta.sourceNote).toContain('CA');

      const old = getStatutoryVersionMeta('2025-10-01');
      expect(old.fy).toBe('2025-26');
      expect(old.verified).toBe(true);
    });

    test('calculations accept an asOf date (backdated runs use that era rules)', () => {
      const pfMar = calculatePf(25000, 5000, false, '2026-03-31');
      const pfApr = calculatePf(25000, 5000, false, '2026-04-01');
      expect(pfMar.employeePf).toBe(1800);
      expect(pfApr.employeePf).toBe(1800); // ceiling unchanged in seeded values

      const tdsBackdated = calculateTds(2400000, 0, 0, '2026-03-31');
      expect(tdsBackdated.statutoryVersion.fy).toBe('2025-26');
      const tdsCurrent = calculateTds(2400000);
      expect(tdsCurrent.statutoryVersion.fy).toBe('2026-27');
    });

    test('statutory.json versions are structurally sound', () => {
      const raw = JSON.parse(readFileSync(new URL('../../src/config/statutory.json', import.meta.url), 'utf8'));
      expect(Array.isArray(raw.versions)).toBe(true);
      expect(raw.versions.length).toBeGreaterThanOrEqual(2);
      for (const v of raw.versions) {
        expect(v.fy).toMatch(/^\d{4}-\d{2}$/);
        expect(v.effectiveFrom).toMatch(/^\d{4}-\d{2}-\d{2}$/);
        expect(v.pf?.employeeRate).toBeGreaterThan(0);
        expect(v.esi?.grossWageCeiling).toBeGreaterThan(0);
        expect(v.gratuity?.minimumTenureYears).toBeGreaterThan(0);
        expect(v.tds?.standardDeduction).toBeGreaterThan(0);
        expect(Array.isArray(v.newTaxRegimeSlabs)).toBe(true);
        expect(typeof v.verified).toBe('boolean');
      }
      // The only verified version must be the CA-approved baseline; the new FY
      // must remain unverified until sign-off happens outside this repo.
      expect(raw.versions.find((v) => v.fy === '2025-26').verified).toBe(true);
      expect(raw.versions.find((v) => v.fy === '2026-27').verified).toBe(false);
      // No silent gap: versions must be contiguous FYs
      const fys = raw.versions.map((v) => v.fy);
      expect(new Set(fys).size).toBe(fys.length);
    });
  });

  describe('DDI Engine', () => {
    test('detects major severity interaction between warfarin and aspirin', () => {
      const results = checkDrugInteractions(['Warfarin 5mg', 'Aspirin 75mg']);
      expect(results.length).toBe(1);
      expect(results[0].severity).toBe('major');
      expect(results[0].drugA).toBe('warfarin');
      expect(results[0].drugB).toBe('aspirin');
    });

    test('detects metformin and iodinated contrast conflict', () => {
      const results = checkDrugInteractions(['Metformin 500mg', 'Iodinated Contrast']);
      expect(results.length).toBe(1);
      expect(results[0].severity).toBe('major');
      expect(results[0].effect).toContain('lactic acidosis');
    });

    test('returns empty array when prescribed drugs have no interactions', () => {
      const results = checkDrugInteractions(['Paracetamol 650mg', 'Amoxicillin 500mg']);
      expect(results).toEqual([]);
    });

    // Wave 4 hardening: the knowledge base grew from 12 to 145 curated pairs and
    // matching is symmetric. These tests stop a silent shrink or a one-way key.
    test('knowledge base stays curated (>= 100 pairs) with a majority of major severity', () => {
      const db = JSON.parse(readFileSync(new URL('../../src/config/interactions.json', import.meta.url), 'utf8'));
      expect(db.length).toBeGreaterThanOrEqual(100);
      const major = db.filter((e) => e.severity === 'major').length;
      expect(major).toBeGreaterThanOrEqual(60);
      for (const e of db) {
        expect(['major', 'moderate', 'minor']).toContain(e.severity);
        expect(e.drugA && e.drugB && e.effect && e.recommendation).toBeTruthy();
      }
    });

    test('matching is symmetric regardless of prescribed order', () => {
      const forward = checkDrugInteractions(['clarithromycin', 'simvastatin']);
      const reverse = checkDrugInteractions(['simvastatin', 'clarithromycin']);
      expect(forward.length).toBe(1);
      expect(reverse.length).toBe(1);
      expect(reverse[0].severity).toBe('major');
      expect(reverse[0].drugA).toBe('simvastatin');
    });

    test('sorts multi-drug results by severity (major before moderate)', () => {
      const results = checkDrugInteractions([
        'warfarin', 'aspirin', 'sertraline', 'phenelzine', 'ibuprofen',
      ]);
      const order = results.map((r) => r.severity);
      expect(order[0]).toBe('major');
      expect(order[order.length - 1]).toBe('moderate');
      const idxMajor = order.indexOf('major');
      const idxModerate = order.indexOf('moderate');
      expect(idxMajor).toBeLessThan(idxModerate);
    });

    // T3 (file 31) hardening: strength tokens are stripped, unknown drugs are
    // surfaced as "not checked", and a 20-drug check stays well under 50ms.
    test('strips strength tokens so "Warfarin 5 mg" still matches entry "warfarin"', () => {
      const results = checkDrugInteractions(['Warfarin 5 mg', 'Aspirin 75 mg']);
      expect(results.length).toBe(1);
      expect(results[0].severity).toBe('major');
    });

    test('reports unknown drugs instead of silently claiming "safe"', () => {
      const { interactions, unknownDrugs } = checkDrugInteractionsDetailed([
        'Zzznotindb Drug 10mg', 'Anotherzzi Pill 5mg',
      ]);
      expect(interactions).toEqual([]);
      expect(unknownDrugs).toHaveLength(2);
    });

    test('mixed known pair still flags the interaction', () => {
      const { interactions } = checkDrugInteractionsDetailed([
        'Warfarin 5mg', 'Aspirin 75mg', 'Zzznotindb Drug 10mg',
      ]);
      expect(interactions).toHaveLength(1);
      expect(interactions[0].severity).toBe('major');
    });

    test('performs a 20-drug check in under 50ms (pre-normalized DB + cache)', () => {
      const drugs = Array.from({ length: 20 }, (_, i) => `Drugname${i} ${i + 1}mg`);
      drugs[0] = 'Warfarin 5mg';
      drugs[1] = 'Aspirin 75mg';
      const t0 = performance.now();
      checkDrugInteractions(drugs);
      const first = performance.now() - t0;
      const t1 = performance.now();
      checkDrugInteractions(drugs); // cached second call
      const second = performance.now() - t1;
      expect(first).toBeLessThan(50);
      expect(second).toBeLessThan(50);
    });

    test('empty / single-drug input returns no interactions', () => {
      expect(checkDrugInteractions([])).toEqual([]);
      expect(checkDrugInteractions(['Aspirin'])).toEqual([]);
      expect(checkDrugInteractions('not-an-array')).toEqual([]);
    });

    test('145-pair DDI data lint: no duplicate pairs, valid severity enum, non-empty effects and recommendations', () => {
      const interactions = JSON.parse(readFileSync(new URL('../../src/config/interactions.json', import.meta.url), 'utf8'));
      expect(interactions.length).toBeGreaterThanOrEqual(145);

      const seen = new Set();
      const validSeverities = ['major', 'moderate', 'minor'];

      for (const item of interactions) {
        expect(item.drugA).toBeDefined();
        expect(item.drugB).toBeDefined();
        expect(item.drugA.trim().length).toBeGreaterThan(0);
        expect(item.drugB.trim().length).toBeGreaterThan(0);

        expect(validSeverities).toContain(item.severity);
        expect(item.effect).toBeDefined();
        expect(item.effect.trim().length).toBeGreaterThan(0);
        expect(item.recommendation).toBeDefined();
        expect(item.recommendation.trim().length).toBeGreaterThan(0);

        const pairKey = [item.drugA.toLowerCase().trim(), item.drugB.toLowerCase().trim()].sort().join('::');
        expect(seen.has(pairKey)).toBe(false);
        seen.add(pairKey);
      }
    });
  });
});

import { describe, it, expect } from '@jest/globals';
import {
  CATEGORY_TYPES, CATEGORY_CODE_RE, SPECIALTIES,
  deriveCategoryCode, resolveSpecialtyCode, specialtyPattern, specialtyCondition,
} from '../../src/lib/taxonomy.js';
import { createCategorySchema, updateCategorySchema } from '../../src/utils/validate.js';
import Category from '../../src/models/Category.js';
import Doctor from '../../src/models/Doctor.js';

describe('R0 taxonomy foundation', () => {
  it('keeps the legacy category types and adds the PART B3 ones', () => {
    for (const legacy of ['test', 'medicine', 'department', 'service']) {
      expect(CATEGORY_TYPES).toContain(legacy);
    }
    for (const added of ['specialty', 'sub_specialty', 'facility_type', 'provider_type', 'emergency_type', 'medicine_class']) {
      expect(CATEGORY_TYPES).toContain(added);
    }
    expect(new Set(CATEGORY_TYPES).size).toBe(CATEGORY_TYPES.length);
  });

  it('derives a stable code per type', () => {
    expect(deriveCategoryCode('test', 'CBC Blood Test')).toBe('TEST.CBC_BLOOD_TEST');
    expect(deriveCategoryCode('sub_specialty', 'Cardiac - Paed')).toBe('SUBSPECIALTY.CARDIAC_PAED');
    expect(CATEGORY_CODE_RE.test(deriveCategoryCode('medicine', 'Paracetamol 500'))).toBe(true);
  });

  it('rejects malformed codes', () => {
    for (const bad of ['spec.cardio', 'SPEC', 'SPEC.', 'SPEC.A B', 'SPEC.a/b', 'SPEC;DROP']) {
      expect(CATEGORY_CODE_RE.test(bad)).toBe(false);
    }
  });

  it('gives every canonical specialty a unique, well-formed code', () => {
    const codes = SPECIALTIES.map((s) => s.code);
    expect(new Set(codes).size).toBe(codes.length);
    expect(codes.every((code) => CATEGORY_CODE_RE.test(code))).toBe(true);
    expect(SPECIALTIES.length).toBeGreaterThanOrEqual(40);
  });

  it("resolves every spelling of a specialty to one canonical code", () => {
    const pairs = [
      ['Orthopedics', 'SPEC.ORTHO'],
      ['Orthopaedics', 'SPEC.ORTHO'],
      ['Pediatrics', 'SPEC.PAED'],
      ['Paediatrics', 'SPEC.PAED'],
      ['Gynecologist', 'SPEC.OBGY'],
      ['Obstetrics & Gynaecology', 'SPEC.OBGY'],
      ['Dentist', 'SPEC.DENTAL'],
      ['Dentistry', 'SPEC.DENTAL'],
      ['General Physician', 'SPEC.GENMED'],
      ['Chest Physician', 'SPEC.PULMO'],
      ['Diabetologist', 'SPEC.ENDO'],
    ];
    for (const [input, code] of pairs) expect(resolveSpecialtyCode(input)).toBe(code);
    expect(resolveSpecialtyCode('definitely not a specialty')).toBeNull();
    expect(resolveSpecialtyCode('')).toBeNull();
  });

  it('matches alias spellings without matching mid-word', () => {
    expect(specialtyPattern('Orthopaedics').test('Dr Mehta - Orthopedics')).toBe(true);
    expect(specialtyPattern('Orthopaedics').test('Cardiology')).toBe(false);
    expect(specialtyPattern('ENT').test('Patient')).toBe(false);
    expect(specialtyPattern('Cardiology').test('Interventional Cardiology')).toBe(true);
    expect(specialtyPattern('unknown specialty')).toBeNull();
  });

  it('returns a code + alias condition for doctor filters', () => {
    const condition = specialtyCondition('Cardiology');
    expect(condition.$or[0]).toEqual({ specialtyCode: 'SPEC.CARDIO' });
    expect(condition.$or[1].specialization).toBeInstanceOf(RegExp);
    expect(specialtyCondition('   ')).toBeNull();
    expect(specialtyCondition('not a specialty')).toEqual({ specialization: expect.any(RegExp) });
  });

  it('validates category writes and keeps code server-owned on update', () => {
    expect(createCategorySchema.parse({ name: ' Cardiology ', type: 'specialty', aliases: ['Heart'] }))
      .toMatchObject({ name: 'Cardiology', type: 'specialty' });
    expect(() => createCategorySchema.parse({ name: 'x', type: 'nope' })).toThrow();
    expect(() => createCategorySchema.parse({ name: 'x', type: 'test', code: 'spec.cardio' })).toThrow();
    const updated = updateCategorySchema.parse({ name: 'Renamed', code: 'SPEC.X', path: 'X', level: 9 });
    expect(updated).toEqual({ name: 'Renamed' });
  });

  it('declares the PART B2 fields and indexes on the Category model', () => {
    expect(Category.schema.path('type').enumValues).toEqual(expect.arrayContaining([...CATEGORY_TYPES]));
    expect(Category.schema.path('code').options.immutable).toBe(true);
    for (const field of ['code', 'aliases', 'path', 'level', 'tier', 'regulatedBy', 'adClaimsRestricted', 'externalCodes.snomed', 'externalCodes.icd10', 'nameHi']) {
      expect(Category.schema.path(field)).toBeTruthy();
    }
    const indexes = Category.schema.indexes();
    expect(indexes.some(([keys, options]) => keys.type === 1 && keys.code === 1 && options.unique === true)).toBe(true);
    expect(indexes.some(([keys]) => keys.type === 1 && keys.parent === 1 && keys.name === 1)).toBe(true);
    expect(indexes.some(([keys]) => keys.name === 'text')).toBe(true);
  });

  it('adds the canonical specialtyCode field to the Doctor model', () => {
    const field = Doctor.schema.path('specialtyCode');
    expect(field).toBeTruthy();
    expect(field.instance).toBe('String');
    expect(field.options.default).toBe('');
  });
});

/**
 * subcatogary.md §79 — Test.sampleType free-text → enum.
 *
 * What it pins:
 *  - the write vocabulary coerces (trim + case-insensitive): 'blood' and
 *    '  Urine ' arrive at the model as 'Blood' / 'Urine', '' stays '';
 *  - anything outside the catalog vocabulary 400s at the zod boundary
 *    (garbage can no longer be typed into the catalogue or the
 *    collect-sample form);
 *  - createTestSchema persists sampleType end-to-end through validate() —
 *    before this slice the create path silently STRIPPED it (unknown key on
 *    a non-strict schema), so the enum only ever applied on PUT.
 */
import { describe, it, expect } from '@jest/globals';
import {
  TEST_SAMPLE_TYPES, canonicalSampleType, sampleTypeSchema, createTestSchema,
} from '../../src/utils/validate.js';

describe('TEST_SAMPLE_TYPES vocabulary', () => {
  it('keeps the unspecified tail so legacy catalog rows stay valid', () => {
    expect(TEST_SAMPLE_TYPES).toContain('');
    expect(TEST_SAMPLE_TYPES).toContain('Blood');
  });

  it('canonicalizes staff-typed input without rejecting it', () => {
    expect(sampleTypeSchema.parse('blood')).toBe('Blood');
    expect(sampleTypeSchema.parse('  Urine ')).toBe('Urine');
    expect(sampleTypeSchema.parse('Blood')).toBe('Blood');
    expect(sampleTypeSchema.parse('')).toBe('');
    expect(canonicalSampleType('  serum\t')).toBe('Serum');
  });

  it('rejects vocabulary outside the catalog at the boundary', () => {
    expect(() => sampleTypeSchema.parse('marrow soup')).toThrow();
    expect(() => sampleTypeSchema.parse('plasmaa')).toThrow();
  });

  it('persists sampleType through the catalog create schema', () => {
    const parsed = createTestSchema.parse({
      name: 'CBC', category: 'Blood', price: 100, sampleType: 'blood',
    });
    expect(parsed.sampleType).toBe('Blood');
  });

  it('leaves create untouched when sampleType is omitted', () => {
    const parsed = createTestSchema.parse({ name: 'CBC', category: 'Blood', price: 100 });
    expect(parsed).not.toHaveProperty('sampleType');
  });
});

import { jest } from '@jest/globals';

